def _now_str():
    try:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""


def _read_json_file(path, default):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return _json.load(f)
    except Exception:
        return default


def _write_json_file(path, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            _json.dump(data, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _all_pool_refs():
    refs = []
    for group_name, pools in (NICK_STOCK_POOLS or {}).items():
        for pool_name in (pools or {}).keys():
            refs.append((group_name, pool_name))
    return refs


def _stock_name_from_code(code):
    c = str(code or "").strip()
    return NICK_STOCK_NAMES.get(c, c)


@st.cache_data(ttl=1800, show_spinner=False)
def _fetch_dynamic_pool_tech(stock_id, period="4mo"):
    """資金流向用的輕量股價技術資料。只用在按鈕更新時。"""
    if not _YF_OK:
        return None
    sid = str(stock_id or "").strip()
    if not re.fullmatch(r"\d{4}", sid):
        return None
    for suffix in [".TW", ".TWO"]:
        symbol = f"{sid}{suffix}"
        try:
            df = yf.download(symbol, period=period, interval="1d", progress=False, auto_adjust=False)
            if df is None or df.empty or len(df) < 25:
                continue
            if isinstance(df.columns, pd.MultiIndex):
                df.columns = [c[0] if isinstance(c, tuple) else c for c in df.columns]
            df = df.reset_index()
            close = df["Close"].apply(to_float)
            volume = df["Volume"].apply(to_float) if "Volume" in df.columns else pd.Series([None] * len(df))
            ma20 = close.rolling(20).mean()
            ma60 = close.rolling(60).mean()
            vol_ma20 = volume.rolling(20).mean()
            last_close = to_float(close.iloc[-1])
            last_ma20 = to_float(ma20.iloc[-1])
            last_ma60 = to_float(ma60.iloc[-1])
            last_vol = to_float(volume.iloc[-1])
            last_vol_ma20 = to_float(vol_ma20.iloc[-1])
            close_5 = to_float(close.iloc[-6]) if len(close) >= 6 else None
            close_20 = to_float(close.iloc[-21]) if len(close) >= 21 else None
            return {
                "symbol": symbol,
                "close": last_close,
                "chg_5d": pct_change(last_close, close_5),
                "chg_20d": pct_change(last_close, close_20),
                "ma20": last_ma20,
                "ma60": last_ma60,
                "vol_ratio": safe_div(last_vol, last_vol_ma20),
                "above_ma20": last_close is not None and last_ma20 is not None and last_close >= last_ma20,
                "above_ma60": last_close is not None and last_ma60 is not None and last_close >= last_ma60,
            }
        except Exception:
            continue
    return None


def _score_dynamic_pool(pool_codes, max_stocks_each=3):
    """用族群內前幾檔股票的價量狀態估資金流向。"""
    stock_results = []
    for sid in _unique_stock_codes(pool_codes)[: max(1, int(max_stocks_each or 3))]:
        tech = _fetch_dynamic_pool_tech(sid)
        if not tech:
            continue
        stock_results.append({"股票": f"{_stock_name_from_code(sid)} {sid}", "代號": sid, **tech})

    if not stock_results:
        return {
            "分數": None,
            "狀態": "資料不足",
            "說明": "抓不到有效股價資料",
            "5日均漲跌": None,
            "20日均漲跌": None,
            "站上MA20比例": None,
            "量比": None,
            "個股": [],
        }

    df = pd.DataFrame(stock_results)
    avg_5d = df["chg_5d"].apply(to_float).dropna().mean() if "chg_5d" in df else None
    avg_20d = df["chg_20d"].apply(to_float).dropna().mean() if "chg_20d" in df else None
    above_ma20_ratio = df["above_ma20"].mean() if "above_ma20" in df else 0
    vol_ratio = df["vol_ratio"].apply(to_float).dropna().mean() if "vol_ratio" in df else None

    score = 0.0
    if pd.notna(avg_5d):
        score += max(0, min(30, ((float(avg_5d) + 3) / 8 * 30)))
    if pd.notna(avg_20d):
        score += max(0, min(35, ((float(avg_20d) + 5) / 20 * 35)))
    score += max(0, min(25, float(above_ma20_ratio) * 25))
    if pd.notna(vol_ratio):
        score += max(0, min(10, ((float(vol_ratio) - 0.8) / 1.0 * 10)))

    avg_5d_f = None if pd.isna(avg_5d) else float(avg_5d)
    avg_20d_f = None if pd.isna(avg_20d) else float(avg_20d)
    vol_ratio_f = None if pd.isna(vol_ratio) else float(vol_ratio)

    if score >= 72 and (avg_20d_f or 0) >= 4:
        label, note = "明面主流", "市場資金集中追捧，動能最強"
    elif 55 <= score < 72 and (avg_5d_f or 0) >= 0:
        label, note = "偷偷流入", "資金有回補，尚未引起市場注意"
    elif (avg_20d_f or 0) < 0 and (avg_5d_f or 0) > 0 and score >= 45:
        label, note = "低基期轉強", "從弱勢區翻揚，先列觀察"
    elif (avg_20d_f or 0) >= 6 and (avg_5d_f or 0) < 0:
        label, note = "主流鈍化", "漲多後轉弱，短線動能趨緩"
    elif score < 38:
        label, note = "退潮轉弱", "資金已撤退，避免追高"
    else:
        label, note = "觀察中", "方向未明，等下一次確認"

    return {
        "分數": round(float(score), 1),
        "狀態": label,
        "說明": note,
        "5日均漲跌": None if avg_5d_f is None else round(avg_5d_f, 2),
        "20日均漲跌": None if avg_20d_f is None else round(avg_20d_f, 2),
        "站上MA20比例": round(float(above_ma20_ratio) * 100, 1),
        "量比": None if vol_ratio_f is None else round(vol_ratio_f, 2),
        "個股": stock_results,
    }


