def _wmf_industry_to_sector(industry):
    s = str(industry or "")
    if not s:
        return ""
    if "航運" in s:
        return "航運"
    if "金融" in s or "保險" in s:
        return "金融/金控"
    if "營建" in s or "建材" in s:
        return "營建資產"
    if "觀光" in s:
        return "觀光餐飲"
    if "生技" in s or "醫療" in s:
        return "生技醫療"
    if "鋼鐵" in s:
        return "鋼鐵"
    if "塑膠" in s or "化學" in s:
        return "塑化"
    if "水泥" in s:
        return "水泥"
    if "造紙" in s:
        return "造紙"
    if "半導體" in s:
        return "半導體"
    if "電子零組件" in s:
        return "電子零組件"
    if "通信" in s or "網路" in s:
        return "網通設備"
    if "光電" in s:
        return "光電/面板"
    if "電機" in s or "機械" in s:
        return "電機機械"
    return s.replace("業", "")


def _wmf_guess_sectors(code, name, industry, seed_map):
    sectors = set()
    try:
        sectors.update(seed_map.get(str(code), set()))
    except Exception:
        pass
    text = f"{name} {industry}"
    for sector, kws in _WMF_RULES:
        if any(str(k) and str(k) in text for k in kws):
            sectors.add(sector)
    mapped = _wmf_industry_to_sector(industry)
    if mapped:
        sectors.add(mapped)
    # 避免同一檔被塞進太多相近大類，最多保留 3 個；但保留未分類防漏
    out = [x for x in sectors if x and x not in ["ETF", "指數股票型基金"]]
    return out[:3]


def _wmf_fetch_recent_tech(code):
    try:
        if "fetch_stock_price_tech" in globals():
            return fetch_stock_price_tech(str(code), period="4mo")
    except Exception:
        pass
    try:
        if "_fetch_dynamic_pool_tech" in globals():
            return _fetch_dynamic_pool_tech(str(code))
    except Exception:
        pass
    # 最後備援：直接 yfinance
    try:
        yf_obj = None
        if "import_yfinance" in globals():
            yf_obj, _ = import_yfinance()
        elif globals().get("_YF_OK"):
            yf_obj = globals().get("yf")
        if yf_obj is None:
            return None
        for suffix in [".TW", ".TWO"]:
            symbol = f"{code}{suffix}"
            df = yf_obj.download(symbol, period="4mo", interval="1d", progress=False, auto_adjust=False)
            if df is None or df.empty or len(df) < 25:
                continue
            try:
                if "flatten_yf_columns" in globals():
                    df = flatten_yf_columns(df)
                elif isinstance(df.columns, pd.MultiIndex):
                    df.columns = [c[0] if isinstance(c, tuple) else c for c in df.columns]
            except Exception:
                pass
            df = df.reset_index()
            close = df["Close"].apply(to_float)
            volume = df["Volume"].apply(to_float) if "Volume" in df.columns else pd.Series([None] * len(df))
            ma20 = close.rolling(20).mean()
            ma60 = close.rolling(60).mean()
            vol_ma20 = volume.rolling(20).mean()
            last_close = to_float(close.iloc[-1])
            return {
                "symbol": symbol,
                "close": last_close,
                "chg_5d": pct_change(last_close, to_float(close.iloc[-6]) if len(close) >= 6 else None),
                "chg_20d": pct_change(last_close, to_float(close.iloc[-21]) if len(close) >= 21 else None),
                "ma20": to_float(ma20.iloc[-1]),
                "ma60": to_float(ma60.iloc[-1]),
                "vol_ratio": safe_div(to_float(volume.iloc[-1]), to_float(vol_ma20.iloc[-1])),
                "above_ma20": last_close is not None and to_float(ma20.iloc[-1]) is not None and last_close >= to_float(ma20.iloc[-1]),
                "above_ma60": last_close is not None and to_float(ma60.iloc[-1]) is not None and last_close >= to_float(ma60.iloc[-1]),
            }
    except Exception:
        return None
    return None


def _wmf_score_group(sector, items, max_stocks_each, max_trade_value):
    if not items:
        return None
    # 今日資料：全市場即時/盤後報價，不只內建股池
    df0 = pd.DataFrame(items)
    for c in ["change_pct", "trade_value"]:
        if c in df0.columns:
            df0[c] = df0[c].apply(to_float)
    valid_chg = df0["change_pct"].dropna() if "change_pct" in df0.columns else pd.Series(dtype=float)
    day_avg = valid_chg.mean() if not valid_chg.empty else float("nan")
    day_median = valid_chg.median() if not valid_chg.empty else float("nan")
    up_ratio = float((valid_chg > 0).mean()) if not valid_chg.empty else 0.0
    strong_count = int((valid_chg >= 1.5).sum()) if not valid_chg.empty else 0
    weak_count = int((valid_chg <= -1.5).sum()) if not valid_chg.empty else 0
    trade_sum = df0["trade_value"].dropna().sum() if "trade_value" in df0.columns else 0

    # v184｜此處不只保留代表標的，也保留今日族群內的候選個股。
    # CAF 機器人選股會直接從這裡抓今日流入族群個股，不再回頭抓內建股池。
    candidate_source = sorted(
        items,
        key=lambda x: (
            to_float(x.get("trade_value")) or 0,
            to_float(x.get("change_pct")) or -999,
            abs(to_float(x.get("change_pct")) or 0),
        ),
        reverse=True,
    )
    candidate_rows = []
    for x in candidate_source[:40]:
        code = str(x.get("code") or "").strip()
        if not re.fullmatch(r"\d{4}", code):
            continue
        candidate_rows.append({
            "股票": f"{x.get('name')} {code}",
            "代號": code,
            "名稱": x.get("name", ""),
            "今日漲跌": x.get("change_pct"),
            "成交金額": x.get("trade_value"),
            "產業": x.get("industry", ""),
        })

    top = candidate_source[: max(1, int(max_stocks_each or 3))]
    tech_rows = []
    for x in top:
        tech = _wmf_fetch_recent_tech(x.get("code"))
        row = {
            "股票": f"{x.get('name')} {x.get('code')}",
            "代號": x.get("code"),
            "今日漲跌": x.get("change_pct"),
            "成交金額": x.get("trade_value"),
        }
        if tech:
            row.update(tech)
        tech_rows.append(row)

    df = pd.DataFrame(tech_rows)
    avg_5d = df["chg_5d"].apply(to_float).dropna().mean() if "chg_5d" in df else float("nan")
    avg_20d = df["chg_20d"].apply(to_float).dropna().mean() if "chg_20d" in df else float("nan")
    above_ma20_ratio = df["above_ma20"].mean() if "above_ma20" in df else float("nan")
    vol_ratio = df["vol_ratio"].apply(to_float).dropna().mean() if "vol_ratio" in df else float("nan")

    score = 0.0
    if pd.notna(day_avg):
        score += max(0, min(26, (float(day_avg) + 1.5) / 4.5 * 26))
    score += max(0, min(18, up_ratio * 18))
    score += max(0, min(14, strong_count / 5 * 14))
    if max_trade_value and max_trade_value > 0:
        score += max(0, min(16, (float(trade_sum) / max_trade_value) * 16))
    if pd.notna(avg_5d):
        score += max(0, min(12, (float(avg_5d) + 2) / 8 * 12))
    if pd.notna(avg_20d):
        score += max(0, min(10, (float(avg_20d) + 5) / 20 * 10))
    if pd.notna(above_ma20_ratio):
        score += max(0, min(8, float(above_ma20_ratio) * 8))
    if pd.notna(vol_ratio):
        score += max(0, min(6, (float(vol_ratio) - 0.8) / 1.2 * 6))

    day_avg_f = None if pd.isna(day_avg) else float(day_avg)
    avg_5d_f = None if pd.isna(avg_5d) else float(avg_5d)
    avg_20d_f = None if pd.isna(avg_20d) else float(avg_20d)
    above_f = None if pd.isna(above_ma20_ratio) else float(above_ma20_ratio)
    vol_f = None if pd.isna(vol_ratio) else float(vol_ratio)

    # 分類順序：先辨識退潮與鈍化，再看主流/偷流/低基期，避免漲多回落被誤判成偷流。
    if (day_avg_f is not None and day_avg_f <= -0.8 and up_ratio < 0.45 and weak_count >= max(1, strong_count)) or score < 32:
        label, note = "退潮轉弱", "今日資金偏流出，族群內弱勢股較多，先避開追價"
    elif avg_20d_f is not None and avg_20d_f >= 5 and ((avg_5d_f is not None and avg_5d_f < 0) or (day_avg_f is not None and day_avg_f < 0.5)):
        label, note = "主流鈍化", "前波已有漲幅，近日追價力道降溫，續抱不追高"
    elif avg_20d_f is not None and avg_20d_f < 0 and day_avg_f is not None and day_avg_f > 0.8 and strong_count >= 1:
        label, note = "低基期轉強", "原本偏弱，今日開始放量轉強，列入潛力觀察"
    elif (
        avg_20d_f is not None and avg_20d_f >= 3
        and (avg_5d_f is not None and avg_5d_f <= 1.5)
        and (day_avg_f is not None and day_avg_f >= 0.5)
        and up_ratio >= 0.50
        and strong_count >= 1
    ):
        label, note = "回檔轉強", "原本強勢，短線整理後今日重新轉強，適合進 CAF 檢查 Attack"
    elif score >= 66 and day_avg_f is not None and day_avg_f >= 0.8 and up_ratio >= 0.55 and strong_count >= 2:
        label, note = "明面主流", "成交金額與強勢股同步集中，市場已明顯追進"
    elif score >= 48 and day_avg_f is not None and day_avg_f >= 0 and up_ratio >= 0.48:
        label, note = "偷偷流入", "資金開始回補但尚未全面噴出，留意接棒機會"
    else:
        label, note = "觀察中", "有資金跡象但方向未完全確認"

    return {
        "大類": "全市場資金流向",
        "族群": sector,
        "分數": round(float(score), 1),
        "狀態": label,
        "說明": note,
        "今日均漲跌": None if day_avg_f is None else round(day_avg_f, 2),
        "今日中位數": None if pd.isna(day_median) else round(float(day_median), 2),
        "5日均漲跌": None if avg_5d_f is None else round(avg_5d_f, 2),
        "20日均漲跌": None if avg_20d_f is None else round(avg_20d_f, 2),
        "站上MA20比例": None if above_f is None else round(above_f * 100, 1),
        "量比": None if vol_f is None else round(vol_f, 2),
        "上漲比例": round(up_ratio * 100, 1),
        "強勢股數": strong_count,
        "弱勢股數": weak_count,
        "成交金額(億)": round(float(trade_sum or 0) / 100000000, 2),
        "候選檔數": len(candidate_rows),
        "候選個股": candidate_rows,
        "個股": tech_rows,
    }


def build_whole_market_flow(max_stocks_each=3, max_groups=45):
    twse_rows, twse_err = _wmf_fetch_twse_quotes()
    tpex_rows, tpex_err = _wmf_fetch_tpex_quotes()
    quotes = (twse_rows or []) + (tpex_rows or [])
    if not quotes:
        return {
            "updated_at": _wmf_now_str(),
            "engine": WHOLE_MARKET_FLOW_ENGINE_VERSION,
            "rows": [],
            "source": "TWSE OpenAPI / TPEx OpenAPI",
            "errors": [twse_err, tpex_err],
        }, _wmf_status("fail", False, "全市場行情抓取失敗，無法分析資金流向")

    info_map = _wmf_fetch_stock_info_map()
    seed_map = _wmf_seed_sector_map()
    grouped = {}
    unclassified = []

    for q in quotes:
        code = str(q.get("code") or "").strip()
        info = info_map.get(code, {})
        if info.get("name") and not q.get("name"):
            q["name"] = info.get("name")
        q["industry"] = info.get("industry", "")
        sectors = _wmf_guess_sectors(code, q.get("name", ""), q.get("industry", ""), seed_map)
        chg = to_float(q.get("change_pct"))
        val = to_float(q.get("trade_value")) or 0
        strongish = (chg is not None and abs(chg) >= 1.5) or val >= 300000000
        if not sectors:
            if strongish:
                sectors = ["未分類強勢資金池"]
                unclassified.append(q)
            else:
                continue
        for s in sectors:
            grouped.setdefault(s, []).append(q)

    max_trade_value = 0
    for items in grouped.values():
        val = sum((to_float(x.get("trade_value")) or 0) for x in items)
        max_trade_value = max(max_trade_value, val)

    rows = []
    # 先處理成交金額與異動較大的族群，避免 yfinance 抓太多無效族群。
    group_order = sorted(
        grouped.items(),
        key=lambda kv: (sum((to_float(x.get("trade_value")) or 0) for x in kv[1]), len(kv[1])),
        reverse=True,
    )[: max(10, int(max_groups or 45))]

    for sector, items in group_order:
        if len(items) < 2 and sector != "未分類強勢資金池":
            # 單檔族群除非成交金額很大，否則容易誤判。
            total_value = sum((to_float(x.get("trade_value")) or 0) for x in items)
            if total_value < 500000000:
                continue
        r = _wmf_score_group(sector, items, max_stocks_each=max_stocks_each, max_trade_value=max_trade_value)
        if r:
            rows.append(r)

    rows = sorted(rows, key=lambda r: (to_float(r.get("分數")) or -999, to_float(r.get("成交金額(億)")) or 0), reverse=True)
    snap = {
        "updated_at": _wmf_now_str(),
        "engine": WHOLE_MARKET_FLOW_ENGINE_VERSION,
        "max_stocks_each": max_stocks_each,
        "source": "TWSE OpenAPI + TPEx OpenAPI + 三竹股池/內建股池 + yfinance 近日價量（不使用 FinMind）",
        "quote_count": len(quotes),
        "group_count": len(rows),
        "unclassified_count": len(unclassified),
        "errors": [e for e in [twse_err, tpex_err] if e],
        "rows": rows,
    }
    level = "ok" if rows else "fail"
    included = bool(rows)
    note = f"全市場行情掃描 {len(quotes)} 檔，產出 {len(rows)} 個資金族群；防漏池 {len(unclassified)} 檔｜本步驟不使用 FinMind"
    return snap, _wmf_status(level, included, note)


@st.cache_data(ttl=1800, show_spinner=False)
def _fetch_google_news_titles(query, limit=12):
    """用 Google News RSS 抓近期新聞標題，用於聯網新增候選標的。"""
    try:
        r = requests.get(
            "https://news.google.com/rss/search",
            params={
                "q": query,
                "hl": "zh-TW",
                "gl": "TW",
                "ceid": "TW:zh-Hant",
            },
            headers={"User-Agent": "Mozilla/5.0"},
            timeout=8,
        )
        if r.status_code != 200:
            return [], f"HTTP {r.status_code}"
        root = ET.fromstring(r.content)
        channel = root.find("channel")
        if channel is None:
            return [], "新聞格式解析失敗"

        rows = []
        for item in channel.findall("item")[: max(1, int(limit or 12))]:
            title = (item.findtext("title") or "").strip()
            link = (item.findtext("link") or "").strip()
            pub = (item.findtext("pubDate") or "").strip()
            source = ""
            try:
                src_node = item.find("source")
                if src_node is not None and src_node.text:
                    source = src_node.text.strip()
            except Exception:
                source = ""
            if title:
                rows.append({
                    "title": title,
                    "link": link,
                    "pubDate": pub,
                    "source": source,
                })
        return rows, ""
    except Exception as e:
        return [], str(e)


def _sector_online_query(sector_name, strategy):
    """把資金流向族群轉成新聞搜尋語句。"""
    s = str(sector_name or "").strip()
    stg = str(strategy or "").strip()
    replace_map = {
        "財報打臉市場": "財報 優於預期",
        "營收轉強": "營收 成長",
        "毛利率回升": "毛利率 回升",
        "EPS轉強": "EPS 成長",
        "法人回補觀察": "法人 回補",
        "20日線回測觀察": "強勢股 回檔",
        "MA60支撐測試": "波段股 回測",
        "Nick核心熱門池": "台股 強勢股",
    }
    q = replace_map.get(s, s)
    return f"台股 {q} {stg} 概念股"


def _stock_info_candidates():
    """建立新聞標題比對用的股票清單；優先用 FinMind 全市場資料，失敗則用內建清單。"""
    df, err = fetch_stock_info()
    if df is not None and not df.empty and {"stock_id", "stock_name"}.issubset(set(df.columns)):
        work = df.copy()
        work["stock_id"] = work["stock_id"].astype(str).str.strip()
        work["stock_name"] = work["stock_name"].astype(str).str.strip()
        work = work[work["stock_id"].str.fullmatch(r"\d{4}", na=False)]
        work = work[work["stock_name"].str.len() >= 2]
        return work[["stock_id", "stock_name"]].drop_duplicates().to_dict("records")

    return [{"stock_id": k, "stock_name": v} for k, v in (NICK_STOCK_NAMES or {}).items()]


def _match_news_titles_to_stocks(news_rows, stock_candidates, max_matches=8):
    """從新聞標題裡找台股名稱/代號。"""
    hits = {}
    for row in news_rows or []:
        title = str(row.get("title", "") or "")
        if not title:
            continue

        for code in re.findall(r"(?<!\d)(\d{4})(?!\d)", title):
            if code not in hits:
                hits[code] = {
                    "code": code,
                    "name": NICK_STOCK_NAMES.get(code, ""),
                    "title": title,
                    "source": row.get("source", ""),
                    "link": row.get("link", ""),
                    "reason": "新聞標題出現股票代號",
                }

        for item in stock_candidates or []:
            code = str(item.get("stock_id", "")).strip()
            name = str(item.get("stock_name", "")).strip()
            if not re.fullmatch(r"\d{4}", code):
                continue
            if not name or len(name) < 2:
                continue
            if name and name in title and code not in hits:
                hits[code] = {
                    "code": code,
                    "name": name,
                    "title": title,
                    "source": row.get("source", ""),
                    "link": row.get("link", ""),
                    "reason": f"新聞標題提到「{name}」",
                }
                break

        if len(hits) >= int(max_matches or 8):
            break
    return list(hits.values())[: int(max_matches or 8)]


def fetch_online_candidates_from_flow(strategy, picked_rows, limit=8):
    """依資金流向結果聯網搜尋近期相關標的。

    這一段是「聯網新增」：先看資金流向挑出的族群，再用新聞標題找近期被提到的台股。
    新增標的不直接取代內建池，而是補充到機器人股池後段。
    """
    picked_rows = picked_rows or []
    if not picked_rows:
        return {"updated_at": _now_str(), "codes": [], "items": [], "queries": []}, ""

    stock_candidates = _stock_info_candidates()
    all_items = []
    queries = []

    for r in picked_rows[:5]:
        sector = str(r.get("族群", "") or "").strip()
        status = str(r.get("狀態", "") or "").strip()
        if not sector:
            continue

        query = _sector_online_query(sector, strategy)
        queries.append({"族群": sector, "狀態": status, "query": query})

        news_rows, err = _fetch_google_news_titles(query, limit=14)
        if not news_rows:
            continue

        matches = _match_news_titles_to_stocks(news_rows, stock_candidates, max_matches=6)
        for m in matches:
            m["族群"] = sector
            m["狀態"] = status
            m["query"] = query
            all_items.append(m)

    seen = set()
    clean_items = []
    for item in all_items:
        code = str(item.get("code", "")).strip()
        if not re.fullmatch(r"\d{4}", code) or code in seen:
            continue
        seen.add(code)
        clean_items.append(item)
        if len(clean_items) >= int(limit or 8):
            break

    snap = {
        "updated_at": _now_str(),
        "strategy": strategy,
        "codes": [x["code"] for x in clean_items],
        "items": clean_items,
        "queries": queries,
    }
    _write_json_file(NICK_ONLINE_CANDIDATE_PATH, snap)
    return snap, ""


def update_nick_dynamic_flow(max_stocks_each=3):
    """v250｜更新資金流向：不主動使用 FinMind；FinMind 留給個股雷達與聯網新增標的。"""
    snap, status = build_whole_market_flow(max_stocks_each=max_stocks_each, max_groups=45)
    snap["status"] = status
    _write_json_file(NICK_DYNAMIC_FLOW_PATH, snap)
    return snap


def load_nick_dynamic_flow():
    return _read_json_file(NICK_DYNAMIC_FLOW_PATH, {"updated_at": "", "rows": []})


def _flow_rows_by_status(flow_snap, wanted_statuses=None):
    rows = (flow_snap or {}).get("rows") or []
    if wanted_statuses:
        rows = [r for r in rows if r.get("狀態") in wanted_statuses]
    return sorted(rows, key=lambda r: (to_float(r.get("分數")) or -999), reverse=True)


def _preferred_statuses_for_strategy(strategy):
    """v184｜CAF 機器人選股來源固定為今日資金流入族群。

    策略只影響後續排序加權，不再決定股池來源。
    """
    return list(CAF_INFLOW_STATUSES)



def _caf_sector_key_variants(sector):
    """v258｜CAF 用族群別名橋接，讓今日熱族群可以展開完整三竹/內建股池。"""
    raw = str(sector or "").strip()
    if not raw:
        return []
    norm = raw.replace(" ", "").replace("／", "/")
    manual = {
        "AI": ["AI", "AI伺服器", "伺服器", "雲端運算"],
        "AI PC": ["AI PC", "AI PC/邊緣AI", "筆記電腦", "桌上電腦", "邊緣運算"],
        "伺服器": ["伺服器", "AI伺服器", "雲端運算"],
        "雲端運算": ["雲端運算", "伺服器", "AI伺服器"],
        "邊緣運算": ["邊緣運算", "工業電腦", "AI PC"],
        "AMD": ["AMD", "AI", "AI伺服器", "伺服器"],
        "智慧電網": ["智慧電網", "重電能源", "重電/電力設備", "電源供應"],
        "重電能源": ["重電能源", "重電/電力設備", "綠能/儲能"],
        "風電概念": ["風電概念", "綠能/儲能", "重電能源"],
        "水資源": ["水資源"],
        "太陽能": ["太陽能", "綠能/儲能"],
        "工具機": ["工具機", "機器人/自動化"],
        "行動支付": ["行動支付", "電子支付"],
        "特用化學": ["特用化學", "化學", "化工"],
        "銅": ["銅", "銅箔", "銅概念"],
        "車聯網": ["車聯網", "車用電子", "汽車零組件"],
        "穿戴式裝置": ["穿戴式裝置", "穿戴裝置", "AI PIN", "AI眼鏡"],
        "AI PIN": ["AI PIN", "穿戴式裝置", "AI眼鏡"],
        "AMOLED": ["AMOLED", "面板", "觸控面板"],
        "Micro LED": ["Micro LED", "LED", "面板"],
        "電子紙": ["電子紙", "面板", "STN-LCD"],
        "觸控面板": ["觸控面板", "面板"],
        "PCB": ["PCB", "印刷電路", "CCL", "ABF載板"],
        "車用電子": ["車用電子", "車聯網", "汽車零組件"],
        "低軌衛星": ["低軌衛星", "衛星通訊", "低軌"],
        "散熱": ["散熱", "散熱族群", "水冷散熱", "液冷散熱"],
        "光通訊/CPO": ["光通訊/CPO", "光通訊", "CPO"],
        "連接器": ["連接器", "連接元件", "高速線材"],
        "智慧電網": ["智慧電網", "重電能源", "重電/電力設備"],
    }
    variants = [raw, norm]
    for canon, arr in manual.items():
        arr_norm = [str(x).replace(" ", "").replace("／", "/") for x in arr]
        if norm == canon.replace(" ", "").replace("／", "/") or norm in arr_norm:
            variants.extend(arr)
            variants.append(canon)
    keyword_rules = [
        ("電源", ["電源管理", "電源供應"]), ("散熱", ["散熱", "水冷散熱", "液冷散熱"]),
        ("低軌", ["低軌衛星"]), ("衛星", ["低軌衛星"]), ("資安", ["資安/軟體", "資安軟體"]),
        ("PCB", ["PCB", "印刷電路"]), ("電路", ["PCB", "印刷電路"]), ("封裝", ["先進封裝"]),
        ("伺服器", ["伺服器", "AI伺服器"]), ("邊緣", ["邊緣運算"]), ("穿戴", ["穿戴式裝置"]),
        ("AMOLED", ["AMOLED"]), ("電子紙", ["電子紙"]), ("觸控", ["觸控面板"]),
        ("車", ["車用電子", "汽車零組件"]), ("銅", ["銅", "銅箔"]),
    ]
    for key, arr in keyword_rules:
        if key and key in raw:
            variants.extend(arr)
    out, seen = [], set()
    for v in variants:
        vv = str(v or "").strip()
        if vv and vv not in seen:
            out.append(vv); seen.add(vv)
    return out


def _caf_is_sector_allowed_for_scan(sector, status=None):
    """v268｜CAF雷達統一排除閘門；資金流動圖不使用此函式。"""
    s = str(sector or "").strip()
    if not s:
        return False
    if str(status or "").strip() in CAF_EXCLUDE_STATUSES:
        return False
    try:
        variants = _caf_sector_key_variants(s)
    except Exception:
        variants = [s]
    check_names = [s] + list(variants or [])
    disabled = {str(x).strip() for x in CAF_EXCLUDED_SECTORS if str(x).strip()}
    if disabled and any(str(x).strip() in disabled for x in check_names):
        return False
    bad_keywords = [str(x).strip() for x in CAF_EXCLUDED_KEYWORDS if str(x).strip()]
    if bad_keywords and any(k in str(name) for name in check_names for k in bad_keywords):
        return False
    return True


def _caf_add_pool_item(out, seen, code, name, source=""):
    c = str(code or "").strip()
    if not re.fullmatch(r"\d{4}", c) or c in seen:
        return False
    n = str(name or NICK_STOCK_NAMES.get(c, "") or c).strip()
    out.append({"code": c, "name": n, "source": source})
    seen.add(c)
    if n and n != c:
        NICK_STOCK_NAMES[c] = n
    return True


def _caf_items_from_flow_row(row):
    items = []
    for bucket in [row.get("候選個股") or [], row.get("個股") or []]:
        if not isinstance(bucket, list):
            continue
        for item in bucket:
            if not isinstance(item, dict):
                continue
            code = str(item.get("代號") or item.get("code") or item.get("stock_id") or "").strip()
            name = str(item.get("名稱") or item.get("name") or item.get("stock_name") or NICK_STOCK_NAMES.get(code, "") or "").strip()
            if re.fullmatch(r"\d{4}", code):
                items.append({"code": code, "name": name, "source": "flow_candidate", **item})
    return items


def _caf_build_full_sector_pool_from_flow_row(row):
    """v258｜今日資金流入族群 → 完整/擴展股池。

    順序：資金流向候選 → 三竹完整類股 → 內建 NICK_STOCK_POOLS。只建股池，不抓 FinMind。"""
    sector = str(row.get("族群") or "").strip()
    status = str(row.get("狀態") or "").strip()
    if not _caf_is_sector_allowed_for_scan(sector, status):
        return []
    aliases = _caf_sector_key_variants(sector)
    out, seen = [], set()

    for item in _caf_items_from_flow_row(row):
        _caf_add_pool_item(out, seen, item.get("code"), item.get("name"), "flow_candidate")

    try:
        if _CAF_MITAKE_AVAILABLE:
            _caf_seed_mitake_industry_db()
    except Exception:
        pass

    for key in aliases:
        try:
            members = _caf_get_mitake_industry_members(key) if callable(_caf_get_mitake_industry_members) else []
        except Exception:
            members = []
        for m in members or []:
            if isinstance(m, dict):
                code = m.get("stock_id") or m.get("code") or m.get("代號")
                name = m.get("stock_name") or m.get("name") or m.get("名稱")
            elif isinstance(m, (list, tuple)) and len(m) >= 2:
                code, name = m[0], m[1]
            else:
                code, name = m, ""
            _caf_add_pool_item(out, seen, code, name, "mitake_full_pool")

    # 內建池橋接：比對所有群組的 pool_name，不只用舊的小股池。 
    aliases_norm = {str(x).replace(" ", "").replace("／", "/") for x in aliases}
    for group_name, pools in (NICK_STOCK_POOLS or {}).items():
        if not isinstance(pools, dict):
            continue
        for pool_name, codes in pools.items():
            pn = str(pool_name or "").strip()
            pn_norm = pn.replace(" ", "").replace("／", "/")
            matched = pn_norm in aliases_norm or any(a and (a in pn_norm or pn_norm in a) for a in aliases_norm)
            if not matched:
                continue
            for code in codes or []:
                c = str(code or "").strip()
                _caf_add_pool_item(out, seen, c, NICK_STOCK_NAMES.get(c, ""), f"builtin:{pool_name}")
    return out


@st.cache_data(ttl=120, show_spinner=False)
def _caf_latest_market_quote_lookup():
    """CAF 免 FinMind 初篩行情表。"""
    meta = {}
    try:
        twse_rows, _ = _wmf_fetch_twse_quotes()
    except Exception:
        twse_rows = []
    try:
        tpex_rows, _ = _wmf_fetch_tpex_quotes()
    except Exception:
        tpex_rows = []
    for q in (twse_rows or []) + (tpex_rows or []):
        code = str(q.get("code") or "").strip()
        if not re.fullmatch(r"\d{4}", code):
            continue
        meta[code] = q
        name = str(q.get("name") or "").strip()
        if name:
            NICK_STOCK_NAMES[code] = name
    return meta


def _caf_rank_full_pool_without_finmind(pool_items, flow_row, per_sector_limit=80):
    flow_meta = {}
    for item in _caf_items_from_flow_row(flow_row):
        c = str(item.get("code") or "").strip()
        if c:
            flow_meta[c] = item
    try:
        quote_meta = _caf_latest_market_quote_lookup()
    except Exception:
        quote_meta = {}

    def score_pair(idx_item):
        idx, item = idx_item
        c = str(item.get("code") or "").strip()
        fm = flow_meta.get(c, {})
        qm = quote_meta.get(c, {})
        chg = to_float(fm.get("今日漲跌") or fm.get("change_pct") or qm.get("change_pct"))
        val = to_float(fm.get("成交金額") or fm.get("trade_value") or qm.get("trade_value"))
        has_flow = 1 if c in flow_meta else 0
        has_quote = 1 if c in quote_meta else 0
        if chg is None:
            heat = 0
        elif chg >= 9:
            heat = 0.8
        elif chg >= 6:
            heat = 2.0
        elif chg > 0:
            heat = 3 + min(5, chg)
        elif chg >= -3.5:
            heat = 1.5 + chg * 0.2
        else:
            heat = -1
        return (has_flow, has_quote, float(val or 0), heat, -idx)

    ranked = sorted(list(enumerate(pool_items or [])), key=score_pair, reverse=True)
    return [x[1] for x in ranked[:max(1, int(per_sector_limit or 80))]]


def _caf_round_robin_codes(ranked_by_sector, limit_n):
    out, seen, detail = [], set(), []
    sector_order = list(ranked_by_sector.keys())
    i = 0
    while len(out) < int(limit_n or 0):
        added = False
        for sector in sector_order:
            arr = ranked_by_sector.get(sector) or []
            if i >= len(arr):
                continue
            item = arr[i]
            c = str(item.get("code") or "").strip()
            if re.fullmatch(r"\d{4}", c) and c not in seen:
                seen.add(c); out.append(c)
                detail.append(item)
                added = True
                if len(out) >= int(limit_n or 0):
                    break
        if not added:
            break
        i += 1
    return out, detail


def build_dynamic_robot_pool(strategy, limit=300, include_online=False):
    """v258｜CAF 機器人選股：今日資金流入族群 → 同族群完整/擴展股池。

    修正重點：
    - 不再只拿資金流動圖前台代表 5 檔，也不只吃 flow row 的候選 25 檔。
    - 每個流入族群先展開三竹完整股池 / 內建股池，再用 TWSE/TPEx 行情做免 FinMind 排序。
    - 只有後面真正重新掃描選股雷達 單檔時，才進個股法醫資料抓取。
    """
    flow = load_nick_dynamic_flow()
    rows = flow.get("rows") or []
    if not rows:
        return None, "尚未更新資金流向，請先按「更新資金流向」。"

    picked_rows = _flow_rows_by_status(flow, wanted_statuses=CAF_INFLOW_STATUSES)
    # v268｜CAF 只吃合格資金流入族群；不掃 Nick 指定排除族群與退潮轉弱。
    picked_rows = [r for r in picked_rows if _caf_is_sector_allowed_for_scan(r.get("族群"), r.get("狀態"))]
    if not picked_rows:
        return None, "今日沒有合格資金流入族群，CAF 不硬掃內建股池；排除族群與退潮轉弱不進掃描。"

    limit_n = max(30, int(limit or 300))
    per_sector_limit = max(20, min(int(_CAF_MITAKE_MAX_PER_SECTOR or 80), limit_n))

    ranked_by_sector = {}
    picked_sectors = []
    full_pool_total = 0
    prefilter_total = 0

    for r in picked_rows:
        sector = str(r.get("族群") or "").strip()
        status = str(r.get("狀態") or "").strip()
        if not _caf_is_sector_allowed_for_scan(sector, status):
            continue

        full_pool = _caf_build_full_sector_pool_from_flow_row(r)
        ranked_pool = _caf_rank_full_pool_without_finmind(full_pool, r, per_sector_limit=per_sector_limit)
        ranked_by_sector[sector] = ranked_pool
        full_pool_total += len(full_pool or [])
        prefilter_total += len(ranked_pool or [])

        picked_sectors.append({
            "大類": "今日資金流入族群",
            "族群": sector,
            "狀態": status,
            "分數": r.get("分數"),
            "候選檔數": len(full_pool or []),
            "納入檔數": len(ranked_pool or []),
            "說明": r.get("說明"),
        })

    # v272｜先算出「可用候選總量」，再按 limit_n 取本次 CAF 候選池。
    # 這裡只建池、不深掃財報；若可用候選小於上限，代表股池已完整吃完，後面沒有隱藏下一批。
    _available_seen = set()
    for _sector, _arr in (ranked_by_sector or {}).items():
        for _item in _arr or []:
            _c = str((_item or {}).get("code") or "").strip()
            if re.fullmatch(r"\d{4}", _c):
                _available_seen.add(_c)
    available_unique_total = len(_available_seen)

    flow_codes, candidate_detail = _caf_round_robin_codes(ranked_by_sector, limit_n)
    if not flow_codes:
        return None, "今日資金流入族群暫時沒有可用候選標的，請重新更新資金流向。"

    # v272｜CAF 更新按鈕只做「股池建立」，預設不再同步跑新聞補漏，避免 Replit / 手機端卡在右上 Stop。
    # 聯網標的之後保留為獨立流程，不阻塞 CAF 候選池更新。
    online_limit = max(0, min(8, max(1, limit_n // 20))) if include_online else 0
    online_snap, online_err = fetch_online_candidates_from_flow(strategy, picked_rows, limit=online_limit) if online_limit else ({"items": [], "codes": []}, "")
    online_items = online_snap.get("items", []) if online_snap else []
    online_codes = [x.get("code") for x in online_items]

    try:
        for item in online_items:
            c = str(item.get("code", "")).strip()
            n = str(item.get("name", "")).strip()
            if re.fullmatch(r"\d{4}", c) and n:
                NICK_STOCK_NAMES[c] = n
        for item in candidate_detail:
            c = str(item.get("code", "")).strip()
            n = str(item.get("name", "")).strip()
            if re.fullmatch(r"\d{4}", c) and n:
                NICK_STOCK_NAMES[c] = n
    except Exception:
        pass

    codes = _unique_stock_codes(flow_codes + online_codes)[:limit_n]

    snap = _read_json_file(NICK_DYNAMIC_ROBOT_POOL_PATH, {})
    snap[str(strategy)] = {
        "updated_at": _now_str(),
        "flow_updated_at": flow.get("updated_at", ""),
        "strategy": strategy,
        "source_mode": "CAF資金流入完整股池掃描",
        "codes": codes,
        "base_codes": flow_codes,
        "flow_codes": flow_codes,
        "online_codes": _unique_stock_codes(online_codes),
        "online_candidates": online_items,
        "online_error": online_err,
        "candidate_detail": candidate_detail[:limit_n],
        "sectors": picked_sectors[:30],
        "full_pool_total": full_pool_total,
        "prefilter_total": prefilter_total,
        "available_unique_total": available_unique_total,
        "pool_limit": limit_n,
        "pool_remaining_after_limit": max(0, int(available_unique_total or 0) - len(codes)),
        "pool_is_complete": bool((available_unique_total or 0) <= len(codes)),
        "online_supplement_enabled": bool(include_online),
        "caf_rule": "v268/v272：資金流動圖全族群照跑；CAF只取合格資金流入族群，排除觀光/文創/農業/電商/塑膠橡膠/水泥營建/生技/TDR/金融/管理股票與退潮轉弱；更新CAF只建候選池，預設不跑新聞補漏。",
    }
    _write_json_file(NICK_DYNAMIC_ROBOT_POOL_PATH, snap)
    return snap[str(strategy)], ""


def load_dynamic_robot_pool(strategy):
    snap = _read_json_file(NICK_DYNAMIC_ROBOT_POOL_PATH, {})
    return snap.get(str(strategy), {}) if isinstance(snap, dict) else {}


def _current_robot_pool_version(strategy):
    data = load_dynamic_robot_pool(strategy)
    return str(data.get("updated_at", ""))


def _dynamic_robot_pool_codes(strategy):
    data = load_dynamic_robot_pool(strategy)
    codes = data.get("codes") or []
    return _unique_stock_codes(codes)


def _flow_status_summary(flow_snap):
    rows = (flow_snap or {}).get("rows") or []
    if not rows:
        return "尚未更新資金流向"
    cats = {"明面主流": [], "偷偷流入": [], "低基期轉強": [], "回檔轉強": [], "主流鈍化": [], "退潮轉弱": []}
    for r in sorted(rows, key=lambda x: (to_float(x.get("分數")) or -999), reverse=True):
        s = r.get("狀態")
        if s in cats and len(cats[s]) < 4:
            cats[s].append(str(r.get("族群")))
    parts = []
    for k, v in cats.items():
        if v:
            parts.append(f"{k}：" + "、".join(v))
    return "｜".join(parts) if parts else "目前沒有明確族群"


def _full_flow_cats(flow_snap):
    rows = (flow_snap or {}).get("rows") or []
    cats = {"明面主流": [], "偷偷流入": [], "低基期轉強": [], "回檔轉強": [], "主流鈍化": [], "退潮轉弱": [], "觀察中": []}
    for r in sorted(rows, key=lambda x: (to_float(x.get("分數")) or -999), reverse=True):
        s = r.get("狀態") or "觀察中"
        sector = str(r.get("族群") or "").strip()
        if sector:
            cats.setdefault(s, []).append(sector)
    return cats


def _flow_chip(text, color):
    palette = {
        "green": ("#86efac", "rgba(22,101,52,.18)", "#166534"),
        "blue": ("#93c5fd", "rgba(30,64,175,.18)", "#1d4ed8"),
        "orange": ("#fdba74", "rgba(154,52,18,.18)", "#9a3412"),
        "yellow": ("#fde047", "rgba(113,63,18,.18)", "#854d0e"),
        "red": ("#fca5a5", "rgba(127,29,29,.18)", "#7f1d1d"),
        "gray": ("#cbd5e1", "rgba(71,85,105,.18)", "#475569"),
    }
    fg, bg, bd = palette.get(color, palette["blue"])
    return f'<span style="display:inline-block;margin:6px 6px 0 0;padding:7px 11px;border-radius:10px;border:1px solid {bd};background:{bg};color:{fg};font-weight:800;">{_html.escape(str(text))}</span>'


def _render_full_flow_map(flow_snap):
    """CAF / 資金流向完整族群分類：預設收合，避免主畫面太吵。"""
    rows = (flow_snap or {}).get("rows") or []
    if not rows:
        st.caption("尚未更新資金流向。")
        return

    cats = _full_flow_cats(flow_snap)
    groups = [
        ("明面主流", "green", "市場資金集中追捧，動能最強"),
        ("偷偷流入", "blue", "資金低調回補，尚未引起市場注意"),
        ("低基期轉強", "orange", "從弱勢區開始翻揚，潛力觀察"),
        ("回檔轉強", "green", "原本強，短線整理後重新轉強"),
        ("主流鈍化", "yellow", "漲多後量縮，短線動能趨緩"),
        ("退潮轉弱", "red", "資金已撤退，避免追高"),
        ("觀察中", "gray", "有資金跡象但尚未定調"),
    ]

    with st.expander("完整族群分類｜預設收合", expanded=False):
        html = '<div style="border:1px solid #1f3b60;border-radius:16px;padding:18px;background:rgba(15,23,42,.68);margin:6px 0 14px 0;">'
        html += '<div style="font-size:1.1rem;font-weight:900;color:#93c5fd;margin-bottom:8px;">🧭 完整族群分類｜資金流向全貌</div>'
        html += f'<div style="color:#94a3b8;margin-bottom:12px;">更新：{_html.escape(str((flow_snap or {}).get("updated_at") or "—"))}｜掃描族群：{len(rows)} 組。這裡是完整分類，平常不用展開。</div>'
        for name, color, note in groups:
            vals = cats.get(name, [])
            color_map = {"green":"#86efac","blue":"#93c5fd","orange":"#fdba74","yellow":"#fde047","red":"#fca5a5","gray":"#cbd5e1"}
            chips = ''.join(_flow_chip(v, color) for v in vals) or '<span style="color:#94a3b8;">目前沒有明確族群</span>'
            html += f'<div style="margin:14px 0;"><span style="font-weight:900;color:{color_map[color]};font-size:1.05rem;">{name}（{len(vals)}）</span><span style="color:#94a3b8;margin-left:8px;">{note}</span><br>{chips}</div>'
        html += '<div style="border-top:1px solid #334155;margin-top:16px;padding-top:12px;color:#94a3b8;">資金流向只代表族群熱度，不代表每檔個股都能買；仍要回到買點、財報、籌碼與風報比判斷。</div>'
        html += '</div>'
        st.markdown(html, unsafe_allow_html=True)

        with st.expander("完整族群明細", expanded=False):
            df = pd.DataFrame(rows)
            if not df.empty:
                display_cols = [c for c in ["族群", "狀態", "分數", "今日均漲跌", "5日均漲跌", "20日均漲跌", "站上MA20比例", "量比", "成交金額(億)", "強勢股數", "弱勢股數", "說明"] if c in df.columns]
                st.dataframe(df[display_cols], use_container_width=True, hide_index=True)


def _unique_stock_codes(codes):
    out, seen = [], set()
    for code in codes or []:
        c = str(code).strip()
        if re.fullmatch(r"\d{4}", c) and c not in seen:
            out.append(c)
            seen.add(c)
    return out

def _stock_label(code):
    c = str(code).strip()
    name = NICK_STOCK_NAMES.get(c, "")
    try:
        _hist = load_hot_history()
        name = (_hist.get(c, {}) or {}).get("name") or name
    except Exception:
        pass
    if not name:
        try:
            _snap = _read_json_file(NICK_DYNAMIC_ROBOT_POOL_PATH, {})
            for _data in (_snap or {}).values():
                for _item in (_data.get("online_candidates", []) or []):
                    if str(_item.get("code", "")).strip() == c and _item.get("name"):
                        name = str(_item.get("name"))
                        break
                if name:
                    break
        except Exception:
            pass
    return f"{c} {name}".strip()

def _pool_codes(group_name, pool_names):
    group = NICK_STOCK_POOLS.get(group_name, {})
    codes = []
    for p in pool_names or []:
        codes.extend(group.get(p, []))
    return _unique_stock_codes(codes)


def _codes_from_refs(refs):
    codes = []
    for group_name, pool_name in refs or []:
        codes.extend(NICK_STOCK_POOLS.get(group_name, {}).get(pool_name, []))
    return _unique_stock_codes(codes)


def _recent_searched_codes(limit=30):
    """最近分析 / 搜尋過的股票，上限 limit。"""
    try:
        history = load_hot_history()
        items = sorted(
            history.items(),
            key=lambda x: (str(x[1].get("last_analyzed", "")), int(x[1].get("count", 0))),
            reverse=True,
        )
        return _unique_stock_codes([code for code, _data in items])[:limit]
    except Exception:
        return []


def _robot_picker_codes(strategy):
    """v184｜CAF 機器人選股：只讀取今日資金流入掃描池，不再回退內建股池。"""
    dynamic_codes = _dynamic_robot_pool_codes(strategy)
    return dynamic_codes if dynamic_codes else []


def _ai_pool_codes():
    return _codes_from_refs(NICK_AI_POOL_REFS)


def _pool_type_codes(pool_type, strategy):
    if pool_type == "機器人挑選股池":
        return _robot_picker_codes(strategy)
    if pool_type == "AI類股":
        return _ai_pool_codes()
    if pool_type == "我搜尋過的（上限30）":
        return _recent_searched_codes(limit=30)
    return []


def _combined_pool_codes(pool_types, strategy):
    codes = []
    for p in pool_types or []:
        codes.extend(_pool_type_codes(p, strategy))
    return _unique_stock_codes(codes)


def _pool_type_reason(pool_type, strategy):
    if pool_type == "機器人挑選股池":
        dyn = load_dynamic_robot_pool(strategy)
        if dyn.get("codes"):
            online_n = len(dyn.get("online_codes", []) or [])
            flow_n = len(dyn.get("flow_codes", []) or dyn.get("base_codes", []) or [])
            sector_n = len(dyn.get("sectors", []) or [])
            full_n = int(to_float(dyn.get("full_pool_total")) or 0)
            online_txt = f"｜新增候選 {online_n} 檔" if online_n else "｜新增候選 0 檔"
            return f"今日流入候選 {flow_n} 檔｜相關族群 {sector_n} 組｜可觀察標的 {full_n} 檔" + online_txt
        return "尚未建立資金流入候選清單；請先更新資金流向，再進行選股雷達掃描。"
    if pool_type == "AI類股":
        return "固定 AI 大池：伺服器、散熱、PCB、光通訊、電源、Edge AI"
    if pool_type == "我搜尋過的（上限30）":
        return "最近分析 / 搜尋過的股票，最多 30 檔"
    return ""

def _codes_to_text(codes):
    return "\n".join(_stock_label(c) for c in _unique_stock_codes(codes))

def _default_strategy_group(strategy):
    if strategy in ["回檔型強股", "回檔強股"]:
        return "回檔強股"
    if strategy in ["財報打臉市場", "低基期轉機"]:
        return "低基期轉機"
    if strategy in ["防守現金流"]:
        return "防守資金"
    if strategy in ["突破準備", "主攻成長股"]:
        return "主攻成長"
    if strategy in ["下一波主題", "偷偷流入"]:
        return "下一波主題"
    return "主攻成長"

def _default_pools_for_strategy(strategy, group_name):
    options = list(NICK_STOCK_POOLS.get(group_name, {}).keys())
    preferred = {
        "Focus優先觀察": ["Nick核心熱門池", "AI伺服器", "PCB / CCL"],
        "回檔型強股": ["20日線回測觀察", "MA60支撐測試"],
        "突破準備": ["光通訊 / CPO", "AI伺服器", "散熱 / 液冷"],
        "財報打臉市場": ["財報打臉市場", "營收轉強"],
        "低基期轉機": ["低基期轉機", "記憶體 / HBM周邊"],
        "防守現金流": ["電信現金流", "金融 / 金控"],
    }.get(strategy, [])
    defaults = [p for p in preferred if p in options]
    return defaults if defaults else options[:1]


