def get_valuation_submodel_key(stock, model_key=None, industry_category=None):
    stock = str(stock or "").strip()
    model_key = str(model_key or "").strip()
    industry_category = clean_text(industry_category)

    if stock in STOCK_VALUATION_SUBMODEL_MAP:
        return STOCK_VALUATION_SUBMODEL_MAP[stock]

    if model_key in MODEL_VALUATION_SUBMODEL_MAP:
        return MODEL_VALUATION_SUBMODEL_MAP[model_key]

    if industry_category:
        if industry_category in INDUSTRY_VALUATION_SUBMODEL_MAP:
            return INDUSTRY_VALUATION_SUBMODEL_MAP[industry_category]
        for key, sub_key in INDUSTRY_VALUATION_SUBMODEL_MAP.items():
            if key and key in industry_category:
                return sub_key

    return "default_pe_check"

def build_valuation_submodel_meta(stock, model_key=None, industry_category=None):
    key = get_valuation_submodel_key(stock, model_key, industry_category)
    rule = VALUATION_SUBMODEL_RULES.get(key) or VALUATION_SUBMODEL_RULES["default_pe_check"]
    formula_family = rule.get("formula_family", "PE")
    is_non_pe_primary = formula_family in ["PB+NormalizedEPS", "EVEBITDA+PB", "NAV+PB", "PB+ROE", "PB+EPS", "EventDiscount"]
    v1_warning = str(rule.get("v1_warning", "") or "")
    if not v1_warning and is_non_pe_primary:
        v1_warning = "估值模型已切到非純 PE；若資料不足，會先用可取得資料輔助估算並顯示限制。"
    elif not v1_warning and formula_family in ["PE+PB", "PE+DividendYield", "PE+WorkingCapital"]:
        v1_warning = "估值模型為混合估值；若資料不足，會先用可取得資料輔助估算並提醒。"

    return {
        "key": key,
        "name": rule.get("name", key),
        "formula_family": formula_family,
        "primary_method": rule.get("primary_method", ""),
        "secondary_method": rule.get("secondary_method", ""),
        "multiple_label": rule.get("multiple_label", "合理 PE"),
        "support_key": rule.get("support_key", ""),
        "note": rule.get("note", ""),
        "v1_warning": v1_warning,
    }

def valuation_submodel_summary_line(val):
    if not val or not isinstance(val, dict):
        return ""
    name = val.get("valuation_submodel_name") or ""
    method = val.get("valuation_primary_method") or ""
    if not name:
        return ""
    if method:
        return f"估值子模組：{name}\n主估值方式：{method}"
    return f"估值子模組：{name}"


