def to_float(x):
    try:
        if x is None:
            return None
        s = str(x).replace(",", "").replace("%", "").replace("x", "").strip()
        if s in ["", "-", "--", "nan", "None", "NaN"]:
            return None
        return float(s)
    except Exception:
        return None


@st.cache_data(ttl=86400, show_spinner=False)
def fetch_analyst_target(stock):
    if not _YF_OK:
        return {
            "ok": False,
            "source_symbol": "",
            "low": None,
            "mean": None,
            "median": None,
            "high": None,
            "raw": {},
            "note": "yfinance 未安裝",
        }, "未安裝"
    last_err = ""
    for symbol in [f"{stock}.TW", f"{stock}.TWO"]:
        try:
            t = yf.Ticker(symbol)
            data = None
            try:
                data = t.get_analyst_price_targets()
            except Exception:
                data = getattr(t, "analyst_price_targets", None)
            if not data:
                info = {}
                try:
                    info = t.info or {}
                except Exception:
                    info = {}
                data = {
                    "low": info.get("targetLowPrice"),
                    "mean": info.get("targetMeanPrice"),
                    "median": info.get("targetMedianPrice"),
                    "high": info.get("targetHighPrice"),
                }
            low = to_float(data.get("low"))
            mean = to_float(data.get("mean"))
            median = to_float(data.get("median"))
            high = to_float(data.get("high"))
            if any(v is not None and v > 0 for v in [low, mean, median, high]):
                return {
                    "ok": True,
                    "source_symbol": symbol,
                    "low": low,
                    "mean": mean,
                    "median": median,
                    "high": high,
                    "raw": data,
                    "note": "yfinance 法人共識目標價；僅供輔助參考，不影響 Core / Attack / Focus。",
                }, ""
        except Exception as e:
            last_err = str(e)
    return {
        "ok": False,
        "source_symbol": "",
        "low": None,
        "mean": None,
        "median": None,
        "high": None,
        "raw": {},
        "note": "無法人共識目標價資料",
    }, last_err or "無資料"


def safe_div(a, b):
    a, b = to_float(a), to_float(b)
    if a is None or b in [None, 0]:
        return None
    return a / b


def pct_change(a, b):
    a, b = to_float(a), to_float(b)
    if a is None or b in [None, 0]:
        return None
    return (a - b) / abs(b) * 100


def fmt(x, d=2):
    x = to_float(x)
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "無資料"
    return f"{x:,.{d}f}"


def fmt0(x):
    x = to_float(x)
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "無資料"
    return f"{int(round(x)):,.0f}"


def fmp(x):
    x = to_float(x)
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "無資料"
    return f"{x:.2f}%"


# v205｜全APP方向性數字顏色：台股習慣，上漲紅色、下跌綠色。
def tw_direction_cls(x):
    v = to_float(x)
    if v is None:
        return "tw-flat"
    if v > 0:
        return "tw-up-red"
    if v < 0:
        return "tw-down-green"
    return "tw-flat"


def tw_direction_html(x, display=None):
    txt = str(display if display is not None else x)
    return f'<span class="{tw_direction_cls(x)}">{txt}</span>'


def _news_date_short(pub_date):
    try:
        dt = pd.to_datetime(pub_date, errors="coerce")
        if pd.isna(dt):
            return ""
        return dt.strftime("%m/%d")
    except Exception:
        return ""


def _news_source_from_item(item):
    try:
        source = item.find("source")
        if source is not None and source.text:
            return source.text.strip()
    except Exception:
        pass
    return ""


@st.cache_data(ttl=600, show_spinner=False)
def fetch_news_snapshot(stock, name, limit=4):
    """抓 Google News RSS 最新新聞快照，不讀全文、不用 OpenAI API。

    fix9：新聞來源分級重寫。
    1. 優先官方 / A 級財報資料：月營收、累計營收、季報、EPS、法說、公司公告。
    2. 次優先 B 級：主流財經媒體、法人展望、產業供應鏈新聞。
    3. 降權 / 過濾 C/D 級：個股概覽、K棒教學、分點、同學會、社群、純技術訊號。
    4. 若沒有 A/B 級新聞，寧可不顯示，也不要把低品質文章放成主要新聞。
    """
    name_s = str(name or "").strip()
    code_s = str(stock or "").strip()

    base_terms = []
    if name_s:
        base_terms.append(name_s)
    if code_s:
        base_terms.append(code_s)
    base = " ".join(base_terms) if base_terms else "台股 股票"

    queries = []
    if name_s and code_s:
        queries.extend([
            f'"{name_s}" {code_s} 月營收 財報 EPS 法說 when:60d',
            f'"{name_s}" {code_s} 合併營收 季報 展望 when:60d',
            f'{name_s} {code_s} 營收 年增 EPS 毛利率 when:60d',
            f'{name_s} {code_s} 法人 目標價 產業 供應鏈 when:60d',
        ])
    elif name_s:
        queries.extend([
            f'"{name_s}" 月營收 財報 EPS 法說 when:60d',
            f'{name_s} 合併營收 季報 展望 when:60d',
        ])
    else:
        queries.append(f'{base} 月營收 財報 EPS when:60d')

    def _parse_pub_dt(pub_text):
        try:
            dt = pd.to_datetime(pub_text, errors="coerce", utc=True)
            if pd.isna(dt):
                return None
            return dt
        except Exception:
            return None

    def _normalize_title(title, source):
        t = str(title or "")
        s = str(source or "")
        # Google News title 常見格式：標題 - 來源
        if s and t.endswith(" - " + s):
            t = t[: -(len(s) + 3)]
        return re.sub(r"\s+", " ", t).strip()

    def _direct_subject_ok(title):
        """v28｜新聞相關性通用過濾：
        標題必須是本檔主體新聞；只拿本檔當比較對象、供應鏈背景或概念股引子，不放進主要新聞。
        """
        t = str(title or "")
        if not t:
            return False
        if code_s and code_s in t:
            return True
        if name_s:
            # 明顯是本檔主詞的格式。
            if t.startswith(name_s) or t.startswith(f"【{name_s}") or f"「{name_s}" in t or f"{name_s}法說" in t or f"{name_s}月營收" in t or f"{name_s}營收" in t:
                return True
            # 只把目標股拿來比較或當題材背景，容易抓到別檔新聞。
            comparative_bad = [f"超車{name_s}", f"超越{name_s}", f"勝過{name_s}", f"打敗{name_s}", f"追上{name_s}", f"比{name_s}"]
            vague_subject = ["這檔", "這家", "這電源", "這族群", "概念股", "供應鏈", "受惠股", "同族群"]
            if any(k in t for k in comparative_bad):
                return False
            if any(k in t for k in vague_subject) and not (t.startswith(name_s) or f"【{name_s}" in t):
                return False
            # 一般情況：名稱出現且不是明顯比較文，仍保留。
            if name_s in t:
                return True
        return False

    def _news_grade(title, source):
        """回傳 (grade, priority, reason)。priority 越小越優先。"""
        t = str(title or "")
        s = str(source or "")
        text = f"{t} {s}"

        # D 級：不能當主要新聞。直接排除或最後備援。
        hard_bad_kw = [
            "個股概覽", "股價相對高檔", "長黑K", "K棒", "技術分析", "技術訊號",
            "分點", "主力", "同學會", "爆料", "討論區", "社群", "PTT", "Dcard",
            "買賣超排行", "籌碼日報", "股市爆料", "喊盤", "飆股", "存股", "除權息試算",
        ]
        if any(k in text for k in hard_bad_kw):
            return "D", 99, "排除：個股概覽 / 技術 / 社群 / 分點類"

        # 低品質來源：若沒有 A 級財報字眼，不可排前面。
        low_sources = ["CMoney", "Yahoo股市", "奇摩股市", "玩股網", "股市爆料同學會", "鉅亨買基金"]
        is_low_source = any(ls in s for ls in low_sources)
        # fix20：CMoney 常混入個股概覽 / 技術文 / 轉載文，不再進入主要新聞欄。
        if "CMoney" in s:
            return "C", 80, "C級：CMoney 來源僅作備援，不作主要新聞"

        a_kw = [
            "月營收", "合併營收", "累計營收", "營收", "財報", "季報", "EPS", "每股盈餘",
            "法說", "法說會", "公司公告", "公開資訊", "毛利率", "營益率", "營業利益",
            "淨利", "展望", "指引", "Q1", "Q2", "Q3", "Q4", "第1季", "第2季", "第一季", "第二季",
        ]
        if any(k in t for k in a_kw):
            # A 級資料即使是轉載，也可保留；但低品質來源仍排在主流來源後面。
            return "A", 0 if not is_low_source else 2, "A級：營收 / 財報 / 法說 / 公告"

        mainstream_sources = [
            "Reuters", "路透", "中央社", "CNA", "經濟日報", "工商時報", "MoneyDJ",
            "鉅亨", "Anue", "DIGITIMES", "財訊", "今周刊", "天下", "商周", "TechNews", "科技新報",
        ]
        b_kw = ["法人", "目標價", "上修", "供應鏈", "AI", "伺服器", "交換器", "800G", "1.6T", "CPO", "ASIC", "訂單"]
        if any(ms in s for ms in mainstream_sources) and any(k in text for k in b_kw):
            return "B", 3, "B級：主流財經 / 產業供應鏈"

        if any(ms in s for ms in mainstream_sources):
            return "B", 4, "B級：主流財經媒體"

        if is_low_source:
            return "C", 80, "C級：低優先來源，僅備援"

        # 其他來源若有產業關鍵字，保留但排後面。
        if any(k in text for k in b_kw):
            return "C", 30, "C級：產業相關但來源普通"

        return "C", 50, "C級：一般新聞"

    try:
        collected = []
        seen_titles = set()
        last_err = ""
        for query in queries:
            r = requests.get(
                "https://news.google.com/rss/search",
                params={
                    "q": query,
                    "hl": "zh-TW",
                    "gl": "TW",
                    "ceid": "TW:zh-Hant",
                },
                headers={"User-Agent": "Mozilla/5.0"},
                timeout=8,
            )
            if r.status_code != 200:
                last_err = f"新聞抓取失敗 HTTP {r.status_code}"
                continue

            try:
                root = ET.fromstring(r.content)
            except Exception as e:
                last_err = f"新聞格式解析失敗：{e}"
                continue
            channel = root.find("channel")
            if channel is None:
                last_err = "新聞格式解析失敗"
                continue

            for item in channel.findall("item")[:35]:
                raw_title = (item.findtext("title") or "").strip()
                if not raw_title:
                    continue
                link = (item.findtext("link") or "").strip()
                pub = (item.findtext("pubDate") or "").strip()
                source = _news_source_from_item(item)
                title = _normalize_title(raw_title, source)

                # v28｜基本相關性：必須是本檔主體新聞；
                # 不接受只把本檔拿來比較、供應鏈背景或概念股引子的新聞。
                if not _direct_subject_ok(title):
                    continue

                grade, priority, reason = _news_grade(title, source)
                if priority >= 99:
                    continue

                norm_title = re.sub(r"\s+", " ", title).strip().lower()
                if norm_title in seen_titles:
                    continue
                seen_titles.add(norm_title)

                pub_dt = _parse_pub_dt(pub)
                collected.append({
                    "title": title,
                    "link": link,
                    "date": _news_date_short(pub),
                    "source": source,
                    "_pub_dt": pub_dt,
                    "_priority": int(priority),
                    "_grade": grade,
                    "_reason": reason,
                })

        if not collected:
            return [], last_err or "沒有抓到 A/B 級明確新聞"

        # 新聞優先順序：品質 > 日期。
        collected.sort(
            key=lambda x: (
                int(x.get("_priority", 50) or 50),
                -(x.get("_pub_dt").timestamp() if x.get("_pub_dt") is not None else 0),
            )
        )

        now_utc = pd.Timestamp.utcnow()
        recent_rows = []
        for r in collected:
            dt = r.get("_pub_dt")
            if dt is not None and (now_utc - dt).days <= 60:
                recent_rows.append(r)

        pool = recent_rows if recent_rows else collected
        # 主要新聞只允許 A/B 級或優先度 <= 4；避免 CMoney / 個股概覽等變主要新聞。
        preferred = [r for r in pool if int(r.get("_priority", 50) or 50) <= 4]
        if not preferred:
            # 若沒有 A/B 級，寧可不顯示低品質新聞，避免誤導為主要依據。
            return [], "沒有抓到 A/B 級新聞；已略過個股概覽 / 技術文 / 社群文"

        final_rows = preferred[:limit]
        for r in final_rows:
            r.pop("_pub_dt", None)
            r.pop("_priority", None)
            r.pop("_grade", None)
            r.pop("_reason", None)
        return final_rows, ""
    except Exception as e:
        return [], str(e)

def build_news_snapshot_html(news_rows, err=""):
    """回傳主畫面用新聞快照 HTML。"""
    if news_rows:
        items = []
        for r in news_rows[:4]:
            title = _html.escape(str(r.get("title", "")))
            link = _html.escape(str(r.get("link", "")))
            date = _html.escape(str(r.get("date", "")))
            source = _html.escape(str(r.get("source", "")))
            meta = "｜".join([x for x in [date, source] if x])
            title_html = (
                f'<a class="news-link" href="{link}" target="_blank">{title}</a>'
                if link
                else f'<span class="news-link">{title}</span>'
            )
            items.append(
                '<div class="news-item">'
                f'<div class="news-date">{meta}</div>'
                f'{title_html}'
                '</div>'
            )
        body = '<div class="news-list">' + "".join(items) + '</div>'
        sub = "最新公開新聞"
    else:
        body = f'<div class="news-empty">目前沒有抓到明確相關新聞。{_html.escape(str(err or ""))}</div>'
        sub = "暫無明確新聞"

    return (
        '<div class="news-box">'
        '<div class="news-head">'
        '<div class="news-title">📰 最新新聞快照</div>'
        f'<div class="news-sub">{sub}</div>'
        '</div>'
        + body
        + '</div>'
    )


def fmt_100m(x, d=2):
    x = to_float(x)
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return "無資料"
    return f"{x / 100_000_000:,.{d}f} 億"




# ============================================================
# v48｜SQLite 估值模組學習庫基礎版
# 目的：先讓 App 具備「AI Core / 估值判斷」的儲存與讀取能力。
# 注意：本版不連 AI、不改 Attack / Focus、不覆蓋底層估值公式；
#      只提供手動貼入 / 手動建立 AI Core 結果，並下次自動讀取提醒。
# ============================================================
VALUATION_LEARNING_DB = "valuation_learning.db"


def _nick_json_dumps(obj):
    try:
        return _json.dumps(obj, ensure_ascii=False, default=str)
    except Exception:
        return "{}"


def _nick_json_loads(txt, default=None):
    if default is None:
        default = {}
    try:
        if txt is None or txt == "":
            return default
        data = _json.loads(txt) if isinstance(txt, str) else txt
        return data if data is not None else default
    except Exception:
        return default


def valuation_learning_init_db(db_path=VALUATION_LEARNING_DB):
    """建立估值模組學習庫。只使用 SQLite，本版不連 AI。"""
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS ai_core_cases (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                stock_id TEXT NOT NULL,
                stock_name TEXT,
                industry_family TEXT,
                model_key TEXT,
                subfamily TEXT,
                source TEXT DEFAULT 'manual',
                core_verdict TEXT,
                core_type TEXT,
                rerating_verdict TEXT,
                eps_json TEXT,
                pe_json TEXT,
                valuation_zones_json TEXT,
                validation_rules_json TEXT,
                limitations_json TEXT,
                raw_json TEXT,
                created_at TEXT,
                updated_at TEXT,
                is_active INTEGER DEFAULT 1
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS valuation_modules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_key TEXT UNIQUE,
                module_name TEXT,
                industry_family TEXT,
                subfamily TEXT,
                model_key TEXT,
                maturity_level TEXT DEFAULT 'L1',
                eps_rule_json TEXT,
                pe_rule_json TEXT,
                validation_rules_json TEXT,
                invalidation_rules_json TEXT,
                source_cases_json TEXT,
                created_at TEXT,
                updated_at TEXT,
                is_active INTEGER DEFAULT 1
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS module_validation_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                case_id INTEGER,
                stock_id TEXT,
                rule_key TEXT,
                rule_label TEXT,
                expected_value TEXT,
                compare_type TEXT,
                created_at TEXT
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS ai_usage_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                stock_id TEXT,
                stock_name TEXT,
                model_name TEXT,
                input_tokens INTEGER,
                output_tokens INTEGER,
                estimated_cost_twd REAL,
                status TEXT,
                note TEXT,
                created_at TEXT
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def valuation_learning_save_case(case, db_path=VALUATION_LEARNING_DB):
    valuation_learning_init_db(db_path)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    case = case or {}
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO ai_core_cases (
                stock_id, stock_name, industry_family, model_key, subfamily, source,
                core_verdict, core_type, rerating_verdict,
                eps_json, pe_json, valuation_zones_json, validation_rules_json,
                limitations_json, raw_json, created_at, updated_at, is_active
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            """,
            (
                str(case.get("stock_id") or "").strip(),
                str(case.get("stock_name") or "").strip(),
                str(case.get("industry_family") or "").strip(),
                str(case.get("model_key") or "").strip(),
                str(case.get("subfamily") or "").strip(),
                str(case.get("source") or "manual").strip(),
                str(case.get("core_verdict") or "").strip(),
                str(case.get("core_type") or "").strip(),
                str(case.get("rerating_verdict") or "").strip(),
                _nick_json_dumps(case.get("eps_assumption") or {}),
                _nick_json_dumps(case.get("pe_assumption") or {}),
                _nick_json_dumps(case.get("valuation_zones") or {}),
                _nick_json_dumps(case.get("validation_rules") or {}),
                _nick_json_dumps(case.get("limitations") or []),
                _nick_json_dumps(case),
                now,
                now,
            ),
        )
        case_id = cur.lastrowid
        # 同步寫入可比對規則，方便之後擴充自動驗證。
        vr = case.get("validation_rules") or {}
        labels = {
            "monthly_revenue_min_100m": "月營收低標（億）",
            "monthly_revenue_base_100m": "月營收中性（億）",
            "monthly_revenue_high_100m": "月營收高標（億）",
            "gross_margin_min": "毛利率低標（%）",
            "gross_margin_base": "毛利率中性（%）",
            "gross_margin_high": "毛利率高標（%）",
            "operating_margin_min": "營益率低標（%）",
            "operating_margin_base": "營益率中性（%）",
            "operating_margin_high": "營益率高標（%）",
            "next_quarter_eps_min": "下一季 EPS 低標",
            "next_quarter_eps_base": "下一季 EPS 中性",
            "next_quarter_eps_high": "下一季 EPS 高標",
            "valid_days": "模組有效天數",
        }
        for k, label in labels.items():
            if vr.get(k) not in [None, "", 0, 0.0]:
                cur.execute(
                    """
                    INSERT INTO module_validation_rules
                    (case_id, stock_id, rule_key, rule_label, expected_value, compare_type, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?)
                    """,
                    (case_id, case.get("stock_id"), k, label, str(vr.get(k)), ">=", now),
                )
        conn.commit()
        return case_id
    finally:
        conn.close()


def valuation_learning_load_latest_case(stock_id, db_path=VALUATION_LEARNING_DB):
    sid = str(stock_id or "").strip()
    if not sid:
        return None
    valuation_learning_init_db(db_path)
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT * FROM ai_core_cases
            WHERE stock_id = ? AND is_active = 1
            ORDER BY datetime(updated_at) DESC, id DESC
            LIMIT 1
            """,
            (sid,),
        )
        row = cur.fetchone()
        if not row:
            return None
        d = dict(row)
        d["eps_assumption"] = _nick_json_loads(d.get("eps_json"), {})
        d["pe_assumption"] = _nick_json_loads(d.get("pe_json"), {})
        d["valuation_zones"] = _nick_json_loads(d.get("valuation_zones_json"), {})
        d["validation_rules"] = _nick_json_loads(d.get("validation_rules_json"), {})
        d["limitations"] = _nick_json_loads(d.get("limitations_json"), [])
        d["raw"] = _nick_json_loads(d.get("raw_json"), {})
        return d
    finally:
        conn.close()


