def valuation_learning_module_key(industry_family="", subfamily="", model_key=""):
    """v52：建立族群 / 子族群估值模組 key。

    注意：模組是估值腦袋，不是個股價位。跨標的套用時只當 PE / EPS 假設框架，
    不直接拿來源個股的基本面支撐價去套另一檔。
    """
    raw = "|".join([str(industry_family or "").strip(), str(model_key or "").strip(), str(subfamily or "").strip()])
    raw = raw or "unknown"
    key = re.sub(r"\s+", "_", raw)
    key = re.sub(r"[^0-9A-Za-z_\-\u4e00-\u9fff｜|/]+", "", key)
    return key[:120] or "unknown"


def valuation_learning_maturity_level(case_count):
    try:
        n = int(case_count or 0)
    except Exception:
        n = 0
    if n >= 10:
        return "L4"
    if n >= 5:
        return "L3"
    if n >= 3:
        return "L2"
    if n >= 1:
        return "L1"
    return "L0"


def valuation_learning_upsert_module_from_case(case, case_id=None, db_path=VALUATION_LEARNING_DB):
    """v52：把單檔 AI Core 案例沉澱成族群 / 子族群估值模組。

    這裡只儲存「估值邏輯框架」：EPS 假設、PE 區間、驗證條件、限制條件、來源案例。
    不代表以後同族群股票會直接沿用同一個價位區間。
    """
    case = case or {}
    industry_family = str(case.get("industry_family") or "").strip()
    subfamily = str(case.get("subfamily") or "").strip()
    model_key = str(case.get("model_key") or "").strip()
    module_key = valuation_learning_module_key(industry_family, subfamily, model_key)
    module_name = "｜".join([x for x in [industry_family, subfamily or model_key] if x]) or module_key
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    source_case = {
        "case_id": case_id,
        "stock_id": case.get("stock_id"),
        "stock_name": case.get("stock_name"),
        "core_verdict": case.get("core_verdict"),
        "core_type": case.get("core_type"),
        "rerating_verdict": case.get("rerating_verdict"),
        "created_at": now,
    }
    valuation_learning_init_db(db_path)
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        cur.execute("SELECT * FROM valuation_modules WHERE module_key = ? AND is_active = 1", (module_key,))
        row = cur.fetchone()
        if row:
            d = dict(row)
            sources = _nick_json_loads(d.get("source_cases_json"), [])
            if not isinstance(sources, list):
                sources = []
            # 同一股票只保留最新一筆來源摘要，避免案例數被重複灌水。
            sid = str(source_case.get("stock_id") or "")
            sources = [x for x in sources if str((x or {}).get("stock_id") or "") != sid]
            sources.append(source_case)
            sources = sources[-30:]
            maturity = valuation_learning_maturity_level(len({str((x or {}).get("stock_id") or "") for x in sources if (x or {}).get("stock_id")}))
            cur.execute(
                """
                UPDATE valuation_modules
                SET module_name=?, industry_family=?, subfamily=?, model_key=?, maturity_level=?,
                    eps_rule_json=?, pe_rule_json=?, validation_rules_json=?, invalidation_rules_json=?,
                    source_cases_json=?, updated_at=?
                WHERE module_key=?
                """,
                (
                    module_name, industry_family, subfamily, model_key, maturity,
                    _nick_json_dumps(case.get("eps_assumption") or {}),
                    _nick_json_dumps(case.get("pe_assumption") or {}),
                    _nick_json_dumps(case.get("validation_rules") or {}),
                    _nick_json_dumps({"limitations": case.get("limitations") or [], "valuation_zones_reference": case.get("valuation_zones") or {}}),
                    _nick_json_dumps(sources), now, module_key,
                ),
            )
        else:
            sources = [source_case]
            maturity = valuation_learning_maturity_level(1)
            cur.execute(
                """
                INSERT INTO valuation_modules (
                    module_key, module_name, industry_family, subfamily, model_key, maturity_level,
                    eps_rule_json, pe_rule_json, validation_rules_json, invalidation_rules_json,
                    source_cases_json, created_at, updated_at, is_active
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
                """,
                (
                    module_key, module_name, industry_family, subfamily, model_key, maturity,
                    _nick_json_dumps(case.get("eps_assumption") or {}),
                    _nick_json_dumps(case.get("pe_assumption") or {}),
                    _nick_json_dumps(case.get("validation_rules") or {}),
                    _nick_json_dumps({"limitations": case.get("limitations") or [], "valuation_zones_reference": case.get("valuation_zones") or {}}),
                    _nick_json_dumps(sources), now, now,
                ),
            )
        conn.commit()
        return module_key
    finally:
        conn.close()


def valuation_learning_load_matching_module(industry_family="", subfamily="", model_key="", db_path=VALUATION_LEARNING_DB):
    """v52：讀取目前族群 / 子族群的估值模組。只做提示，不直接跨標的硬套價位。"""
    valuation_learning_init_db(db_path)
    keys = [
        valuation_learning_module_key(industry_family, subfamily, model_key),
        valuation_learning_module_key(industry_family, "", model_key),
        valuation_learning_module_key(industry_family, subfamily, ""),
    ]
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        for k in keys:
            cur.execute("SELECT * FROM valuation_modules WHERE module_key=? AND is_active=1 LIMIT 1", (k,))
            row = cur.fetchone()
            if row:
                d = dict(row)
                d["eps_rule"] = _nick_json_loads(d.get("eps_rule_json"), {})
                d["pe_rule"] = _nick_json_loads(d.get("pe_rule_json"), {})
                d["validation_rules"] = _nick_json_loads(d.get("validation_rules_json"), {})
                d["invalidation_rules"] = _nick_json_loads(d.get("invalidation_rules_json"), {})
                d["source_cases"] = _nick_json_loads(d.get("source_cases_json"), [])
                return d
        # 最後用 industry_family 模糊找最近一筆，避免完全找不到。
        if str(industry_family or "").strip():
            cur.execute(
                """
                SELECT * FROM valuation_modules
                WHERE industry_family=? AND is_active=1
                ORDER BY datetime(updated_at) DESC, id DESC
                LIMIT 1
                """,
                (str(industry_family or "").strip(),),
            )
            row = cur.fetchone()
            if row:
                d = dict(row)
                d["eps_rule"] = _nick_json_loads(d.get("eps_rule_json"), {})
                d["pe_rule"] = _nick_json_loads(d.get("pe_rule_json"), {})
                d["validation_rules"] = _nick_json_loads(d.get("validation_rules_json"), {})
                d["invalidation_rules"] = _nick_json_loads(d.get("invalidation_rules_json"), {})
                d["source_cases"] = _nick_json_loads(d.get("source_cases_json"), [])
                d["match_note"] = "僅族群模糊符合，需人工確認子族群是否適用。"
                return d
        return None
    finally:
        conn.close()


