def _vl_first_num(obj, keys):
    """從 dict 內依序找第一個可轉數字的欄位。"""
    obj = obj or {}
    for k in keys:
        try:
            v = to_float(obj.get(k))
        except Exception:
            v = None
        if v is not None:
            return v
    return None


def valuation_learning_validate_case(case, rev=None, fin=None, price=None):
    """v50-1｜用 App 最新資料雙向比對 AI 原本驗證條件。本函式不呼叫 AI。

    設計目的：
    - App 自己抓最新月營收 / 毛利率 / 營益率 / EPS / 股價。
    - 跟 AI 當初儲存的低標 / 中性 / 高標比對。
    - 低於假設：提醒降級或重新校正。
    - 符合假設：繼續使用模組。
    - 明顯優於假設：提醒可能需要上修 EPS / PE / 重評合理區。
    - 只做提醒，不自動花 API 費用，也不自動改 Attack / Focus。
    """
    if not case:
        return {
            "status": "尚未校正",
            "level": "gray",
            "items": [],
            "message": "尚未有 AI Core / 估值案例。",
            "action": "可手動新增 AI Core 案例，或之後按鈕啟動 AI Core 判斷。",
            "bad_count": 0,
            "warn_count": 0,
            "upside_count": 0,
        }

    rules = case.get("validation_rules") or {}
    items = []
    warn = 0
    bad = 0
    upside = 0

    def _add(label, current, expected, state="通過", diff="", note=""):
        nonlocal warn, bad, upside
        if state in ["不符合", "低於假設"]:
            bad += 1
        elif state in ["小幅不符", "小幅低於", "資料不足", "注意"]:
            warn += 1
        elif state in ["追價提醒", "價格提醒"]:
            pass
        elif state in ["優於假設", "明顯優於"]:
            upside += 1
        items.append({
            "驗證項目": label,
            "目前資料": current,
            "AI 原假設": expected,
            "差異": diff or "—",
            "狀態": state,
            "說明": note or "—",
        })

    def _fmt_unit(v, unit=""):
        try:
            return f"{float(v):.2f}{unit}"
        except Exception:
            return f"{v}{unit}"

    def _check_band(label, cur, low=None, base=None, high=None, unit="", low_tolerance=0.90, note_low="", note_high=""):
        """低標 / 中性 / 高標三段比對。

        - 低於低標：原 Core / 估值可能失效。
        - 達低標但未達中性：保守符合。
        - 達中性：符合原假設。
        - 高於高標：資料明顯變好，提醒可考慮上修校正。
        """
        low = to_float(low)
        base = to_float(base)
        high = to_float(high)
        if (low is None or low <= 0) and (base is None or base <= 0) and (high is None or high <= 0):
            return
        parts = []
        if low is not None and low > 0:
            parts.append(f"低標 {low:.2f}{unit}")
        if base is not None and base > 0:
            parts.append(f"中性 {base:.2f}{unit}")
        if high is not None and high > 0:
            parts.append(f"高標 {high:.2f}{unit}")
        exp = " / ".join(parts) if parts else "—"
        if cur is None:
            _add(label, "無資料", exp, "資料不足", note="App 尚未抓到此欄位，先不自動否定模組。")
            return

        # 參考點優先序：低標 > 中性 > 高標
        ref = low if low and low > 0 else (base if base and base > 0 else high)
        diff_pct = (cur / ref - 1) * 100 if ref else 0
        diff_txt = _fmt_signed_pct(diff_pct) if '_fmt_signed_pct' in globals() else f"{diff_pct:+.1f}%"
        cur_txt = _fmt_unit(cur, unit)

        if low is not None and low > 0 and cur < low:
            if cur < low * low_tolerance:
                _add(label, cur_txt, exp, "低於假設", diff_txt, note_low or "明顯低於 AI 原本低標，原 Core / 估值模組需要重新檢查。")
            else:
                _add(label, cur_txt, exp, "小幅低於", diff_txt, note_low or "略低於 AI 原本低標，先列為提醒，不立即判定失效。")
            return

        if high is not None and high > 0 and cur >= high:
            ref_high = high
            gap_high = (cur / ref_high - 1) * 100 if ref_high else 0
            diff_high = _fmt_signed_pct(gap_high) if '_fmt_signed_pct' in globals() else f"{gap_high:+.1f}%"
            _add(label, cur_txt, exp, "優於假設", diff_high, note_high or "最新資料已高於 AI 原高標，原估值可能偏保守；可考慮重新 AI 校正以評估 EPS / PE 是否上修。")
            return

        if base is not None and base > 0 and cur >= base:
            ref_base = base
            gap_base = (cur / ref_base - 1) * 100 if ref_base else 0
            diff_base = _fmt_signed_pct(gap_base) if '_fmt_signed_pct' in globals() else f"{gap_base:+.1f}%"
            _add(label, cur_txt, exp, "通過", diff_base, "符合 AI 原本中性假設，模組可繼續使用。")
            return

        if low is not None and low > 0 and cur >= low:
            _add(label, cur_txt, exp, "通過", diff_txt, "達到 AI 原本低標，但尚未達中性假設；模組可用但不宜自動升級。")
            return

        # 沒有低標，只能以中性 / 高標判斷。
        if base is not None and base > 0 and cur < base:
            if cur < base * low_tolerance:
                _add(label, cur_txt, exp, "低於假設", diff_txt, note_low or "明顯低於 AI 原本中性假設，估值需要保守。")
            else:
                _add(label, cur_txt, exp, "小幅低於", diff_txt, note_low or "略低於 AI 原本中性假設，先列提醒。")
        else:
            _add(label, cur_txt, exp, "通過", diff_txt, "未設定低標 / 中性，但目前資料未觸發風險提醒。")

    # 月營收：App 的 revenue_100m 已是億；同時相容其他可能欄位。
    cur_mr = _vl_first_num(rev, ["revenue_100m", "latest_revenue_100m", "month_revenue_100m", "revenue"])
    _check_band(
        "月營收",
        cur_mr,
        rules.get("monthly_revenue_min_100m"),
        rules.get("monthly_revenue_base_100m") or rules.get("monthly_revenue_target_100m"),
        rules.get("monthly_revenue_high_100m"),
        " 億",
        note_low="月營收低於 AI 原假設，代表 EPS 接棒可信度下降。",
        note_high="月營收優於 AI 原高標，可能代表未來 EPS 假設需要上修。",
    )

    cur_gm = _vl_first_num(fin, ["gross_margin", "gross_margin_q", "gm", "gross_profit_margin"])
    _check_band(
        "毛利率",
        cur_gm,
        rules.get("gross_margin_min"),
        rules.get("gross_margin_base") or rules.get("gross_margin_target"),
        rules.get("gross_margin_high"),
        "%",
        low_tolerance=0.95,
        note_low="毛利率低於 AI 原假設，PE 上修需要保守。",
        note_high="毛利率優於 AI 原高標，代表產品組合 / 報價 / 成本結構可能比原模型更好。",
    )

    cur_op = _vl_first_num(fin, ["op_margin", "operating_margin", "operating_margin_q", "operating_profit_margin"])
    _check_band(
        "營益率",
        cur_op,
        rules.get("operating_margin_min"),
        rules.get("operating_margin_base") or rules.get("operating_margin_target"),
        rules.get("operating_margin_high"),
        "%",
        low_tolerance=0.95,
        note_low="營益率低於 AI 原假設，代表營收轉 EPS 的品質要重估。",
        note_high="營益率優於 AI 原高標，代表營收轉 EPS 品質優於原模型，可考慮上修估值。",
    )

    cur_eps = _vl_first_num(fin, ["eps", "latest_eps", "quarter_eps", "eps_q"])
    _check_band(
        "最新季 EPS",
        cur_eps,
        rules.get("next_quarter_eps_min"),
        rules.get("next_quarter_eps_base") or rules.get("next_quarter_eps_target"),
        rules.get("next_quarter_eps_high"),
        "",
        note_low="EPS 低於 AI 原假設，基本面支撐價與 Core 需要重新檢查。",
        note_high="EPS 優於 AI 原高標，原基本面支撐區可能偏保守，建議評估是否重新 AI 校正。",
    )

    valid_days = to_float(rules.get("valid_days")) or 90
    try:
        updated = str(case.get("updated_at") or case.get("created_at") or "")
        dt = datetime.strptime(updated[:19], "%Y-%m-%d %H:%M:%S")
        age = (datetime.now() - dt).days
        exp = f"<= {int(valid_days)} 天"
        if age <= valid_days:
            _add("模組時間", f"{age} 天", exp, "通過", note="模組仍在有效期內。")
        elif age <= valid_days * 1.5:
            _add("模組時間", f"{age} 天", exp, "小幅不符", note="模組已過期，建議人工覆核是否仍適用。")
        else:
            _add("模組時間", f"{age} 天", exp, "不符合", note="模組過期太久，建議重新 AI 校正。")
    except Exception:
        _add("模組時間", "無法判斷", f"<= {int(valid_days)} 天", "資料不足", note="缺少建立時間或格式異常。")

    # 估值區間完整性：缺核心區間時提醒，避免 UI 誤把不完整資料當結論。
    zones = case.get("valuation_zones") or {}
    support_txt = str(zones.get("fundamental_support") or zones.get("support") or "").strip()
    rerating_txt = str(zones.get("rerating_fair_zone") or zones.get("rerating") or "").strip()
    failure_txt = str(zones.get("failure_downside_zone") or zones.get("failure") or "").strip()
    missing_zone = []
    if not support_txt:
        missing_zone.append("基本面支撐區")
    if not rerating_txt:
        missing_zone.append("重評合理區")
    if not failure_txt:
        missing_zone.append("驗證失敗區")
    if missing_zone:
        _add("估值區間完整性", "缺少：" + "、".join(missing_zone), "三區間皆應有資料", "資料不足", note="AI Core 案例資料不完整，估值表僅能部分套用。")
    else:
        _add("估值區間完整性", "完整", "三區間皆應有資料", "通過", note="基本面支撐 / 重評 / 失敗區皆已儲存。")

    cur_price = None
    try:
        if isinstance(price, dict):
            cur_price = to_float(price.get("realtime_price") or price.get("close"))
        else:
            cur_price = to_float(price)
    except Exception:
        cur_price = None

    # 現價 vs 基本面支撐區：提醒綜合評分與追價風險，不一定代表模組失效。
    support_range = valuation_learning_parse_range(support_txt)
    if cur_price is not None and support_range:
        lo, hi = support_range
        if lo <= cur_price <= hi:
            _add("現價 vs 基本面支撐", fmt_price(cur_price), f"{fmt_price(lo)}～{fmt_price(hi)}", "通過", note="現價仍在 AI 基本面支撐區內。")
        elif cur_price > hi:
            gap = (cur_price / hi - 1) * 100 if hi else 0
            state = "追價提醒"
            _add("現價 vs 基本面支撐", fmt_price(cur_price), f"<= {fmt_price(hi)}", state, _fmt_signed_pct(gap), "現價高於基本面支撐區，代表追價風險提高；這不代表 AI 模組失效。")
        elif cur_price < lo:
            gap = (1 - cur_price / lo) * 100 if lo else 0
            _add("現價 vs 基本面支撐", fmt_price(cur_price), f">= {fmt_price(lo)}", "注意", f"-{fmt(gap,1)}%", "低於支撐區不等於可買，需確認基本面沒有失效。")

    # 現價高於重評合理區太多：這較接近需要重新檢查的風險。
    rerating_range = valuation_learning_parse_range(rerating_txt)
    if cur_price is not None and rerating_range:
        _, hi = rerating_range
        if cur_price <= hi:
            _add("現價 vs 重評上緣", fmt_price(cur_price), f"<= {fmt_price(hi)}", "通過", note="現價未高於 AI 重評合理區上緣。")
        elif cur_price <= hi * 1.10:
            gap = (cur_price / hi - 1) * 100
            _add("現價 vs 重評上緣", fmt_price(cur_price), f"<= {fmt_price(hi)}", "注意", _fmt_signed_pct(gap), "現價略高於重評合理區，追價要保守。")
        else:
            gap = (cur_price / hi - 1) * 100
            state = "不符合" if gap > 20 else "小幅不符"
            _add("現價 vs 重評上緣", fmt_price(cur_price), f"<= {fmt_price(hi)}", state, _fmt_signed_pct(gap), "現價高於重評合理區太多，原估值假設需重新檢查。")

    if bad >= 1:
        status, level = "建議重新 AI 校正", "red"
        action = "最新資料已明顯低於原本假設，或估值區間失衡；建議重新校正估值，或先將估值重評降級。"
    elif warn >= 2:
        status, level = "需注意 / 可人工覆核", "yellow"
        action = "目前有多項提醒，但不一定失效；可先保守套用，等下一筆資料或人工決定是否重跑 AI。"
    elif warn == 1:
        status, level = "輕微偏離 / 留意", "yellow"
        action = "只有一項提醒，模組可暫時使用，但綜合評分與追價判斷要保守。"
    elif upside >= 1:
        status, level = "優於原假設 / 可評估上修", "blue"
        action = "最新資料明顯優於 AI 原高標，原估值模組可能偏保守；建議人工確認，必要時重新 AI 校正 EPS / PE / 重評合理區。"
    else:
        status, level = "可用", "green"
        action = "最新資料符合 AI 原假設，可繼續套用儲存的 Core / 估值模組，不需要重新呼叫 AI。"

    return {
        "status": status,
        "level": level,
        "items": items,
        "message": f"{status}｜{bad} 項明顯低於假設，{warn} 項提醒 / 資料不足，{upside} 項優於原高標。",
        "action": action,
        "bad_count": bad,
        "warn_count": warn,
        "upside_count": upside,
    }

def valuation_learning_validation_brief(check):
    """把驗證結果整理成一句短提醒。"""
    if not check:
        return "尚未有 AI Core 驗證結果。"
    level = check.get("level") or "gray"
    icon = {"green": "🟢", "yellow": "🟡", "red": "🔴", "blue": "🔵", "gray": "⚪"}.get(level, "⚪")
    return f"{icon} {check.get('message', '')}｜{check.get('action', '')}"



