def get_openai_api_key():
    """讀取 OpenAI API Key。只從 Streamlit secrets / 環境變數讀，不在畫面顯示。"""
    try:
        key = str(st.secrets.get("OPENAI_API_KEY", "") or "").strip()
    except Exception:
        key = ""
    if not key:
        key = str(os.getenv("OPENAI_API_KEY", "") or "").strip()
    return key


def get_openai_model(default=AI_CORE_DEFAULT_MODEL):
    try:
        m = str(st.secrets.get("OPENAI_MODEL", "") or "").strip()
    except Exception:
        m = ""
    if not m:
        m = str(os.getenv("OPENAI_MODEL", "") or "").strip()
    return m or default


