def nick_v247_extract_trade_plan_from_text(raw_text):
    """v255｜從法醫報告 / AI Core 文字補抓交易計畫欄位。
    修正重點：若貼文前面含舊 30 秒摘要、後面才是完整法醫報告，交易計畫優先讀後段正式「交易策略」。
    """
    raw_text = str(raw_text or "")
    if not raw_text.strip():
        return {}
    source_text = _nick_v255_trade_plan_source_text(raw_text)
    def _val(labels):
        try:
            return _nick_clean_ai_core_range_text(_nick_extract_label_value_from_text_last(source_text, labels))
        except Exception:
            return ""
    def _txt(labels):
        try:
            return str(_nick_extract_label_value_from_text_last(source_text, labels) or "").strip()
        except Exception:
            return ""
    tp = {
        "new": _val(["新倉主區", "新倉主買區", "左側主買", "左側主買區", "左側觀察區", "左側"]),
        "shallow": _val(["淺回檔試單區", "淺回檔試單", "回檔小倉區", "淺回檔小倉區", "試單區"]),
        "right_start": _txt(["右側啟動"]),
        "right_confirm": _txt(["右側突破追擊條件", "右側突破條件", "右側確認", "右側突破", "突破條件"]),
        "right_hold": _txt(["隔日不跌回", "不跌回"]),
        "upper_pressure": _val(["上方壓力", "關鍵壓力", "前高壓力"]),
        "wrong": _val(["追錯失效點", "短線失效", "短線認錯", "短線防守"]),
        "stop": _val(["停損 / 波段失效點", "波段防守", "波段失效點", "停損"]),
        "short": _val(["短線目標", "短線壓力/目標"]),
        "wave": _val(["波段目標", "波段目標價"]),
        "chip_semantic": _txt(["籌碼語意", "吃貨判斷", "籌碼判斷"]),
    }
    return {k: v for k, v in tp.items() if v not in [None, "", "資料不足"]}


def nick_v247_case_trade_plan(case):
    """從 SQLite AI Core case 取出 trade_plan；支援新舊 raw_json。"""
    if not isinstance(case, dict):
        return {}
    for obj in [
        case,
        case.get("raw"),
        (case.get("raw") or {}).get("raw_import") if isinstance(case.get("raw"), dict) else {},
        (case.get("raw") or {}).get("raw_import", {}).get("json_if_any") if isinstance(case.get("raw"), dict) else {},
    ]:
        if isinstance(obj, dict):
            tp = obj.get("trade_plan") or obj.get("forensic_trade_plan") or obj.get("trade_semantic_plan")
            if isinstance(tp, dict) and any(str(v or "").strip() for v in tp.values()):
                return {k: v for k, v in tp.items() if v not in [None, ""]}
            pasted = ""
            try:
                pasted = str((obj.get("raw_import") or {}).get("pasted_text") or obj.get("pasted_text") or "")
            except Exception:
                pasted = ""
            tp2 = nick_v247_extract_trade_plan_from_text(pasted)
            if tp2:
                return tp2
    return {}




def nick_v255_trade_plan_should_fallback(tp=None, support_r=None, close=None, case=None, a=None):
    """v255｜交易計畫防呆：若法醫文字擷取到的買點明顯來自舊摘要或倒掛，就回到支撐區重新衍生。
    通用規則，不針對單一個股：
    - 現價位於基本面支撐區內，左側主買 / 淺回檔試單不應整段高於現價。
    - 現價已高於支撐區，買點不應再整段高於現價。
    - 候選 / Core 股都適用，避免把壓力區誤叫主買區。
    """
    try:
        if not tp or not support_r:
            return False
        cur = to_float(close)
        if cur is None or cur <= 0:
            return False
        lo, hi = float(support_r[0]), float(support_r[1])
        new_r = nick_v247_parse_zone(tp.get("new"))
        shallow_r = nick_v247_parse_zone(tp.get("shallow"))
        inside = lo <= cur <= hi
        above = cur > hi
        if inside:
            if new_r and new_r[0] > cur * 1.005:
                return True
            if shallow_r and shallow_r[0] > cur * 1.015:
                return True
            if new_r and new_r[0] > hi * 0.99 and cur < hi * 0.99:
                return True
        if above:
            if new_r and new_r[0] > cur * 1.005:
                return True
            if shallow_r and shallow_r[0] > cur * 1.015:
                return True
        # 若新倉區與淺回檔區順序倒掛，也回到模型重算。
        if new_r and shallow_r and new_r[0] > shallow_r[1] * 1.01:
            return True
    except Exception:
        return False
    return False

def nick_v247_range_text_from_tuple(lo, hi):
    try:
        if lo is None or hi is None:
            return ""
        lo, hi = min(float(lo), float(hi)), max(float(lo), float(hi))
        return f"{fmt_price(lo)}～{fmt_price(hi)}"
    except Exception:
        return ""


def nick_v247_parse_zone(z):
    try:
        if isinstance(z, (tuple, list)) and len(z) >= 2:
            a, b = to_float(z[0]), to_float(z[1])
            if a is not None and b is not None:
                return min(a, b), max(a, b)
        return valuation_learning_parse_range(z)
    except Exception:
        return None


def nick_v247_next_round_price(x):
    """高價股右側確認：抓短壓附近的整數/心理關卡，不直接抓上方大壓。"""
    p = to_float(x)
    if p is None or p <= 0:
        return None
    try:
        if p >= 500:
            return math.ceil(p / 10) * 10
        if p >= 250:
            return math.ceil(p / 10) * 10
        if p >= 100:
            return math.ceil(p / 5) * 5
        if p >= 50:
            return math.ceil(p / 2) * 2
        return round_price_to_tick(p, "ceil")
    except Exception:
        return p



def nick_v247_case_text_blob(case=None, a=None):
    """v247｜法醫報告文字匯總。用於公司型態/模板判斷，法醫優先，APP fallback。"""
    parts = []
    try:
        if isinstance(case, dict):
            for k in ["ai_core", "core_verdict", "core_type", "rerating_verdict", "subfamily", "source"]:
                v = case.get(k)
                if v:
                    parts.append(str(v))
            for k in ["limitations", "validation_conditions"]:
                v = case.get(k)
                if isinstance(v, (list, tuple)):
                    parts.extend([str(x) for x in v if x])
                elif v:
                    parts.append(str(v))
            raw = case.get("raw")
            if isinstance(raw, dict):
                for k in ["ai_core", "core_type", "rerating", "rerating_verdict", "pasted_text"]:
                    v = raw.get(k)
                    if v:
                        parts.append(str(v))
                ri = raw.get("raw_import")
                if isinstance(ri, dict):
                    for k in ["pasted_text", "ai_core", "core_type", "rerating"]:
                        v = ri.get(k)
                        if v:
                            parts.append(str(v))
    except Exception:
        pass
    try:
        if isinstance(a, dict):
            parts.extend([
                str(a.get("core_status", "")),
                str((a.get("val") or {}).get("model_key", "")),
                str((a.get("val") or {}).get("model_name", "")),
                str(a.get("attack_type", "")),
                str(a.get("action", "")),
            ])
    except Exception:
        pass
    return "｜".join([p for p in parts if p])




def nick_v253_forensic_core_level(case=None, text=""):
    """v253｜法醫 Core 語意分級。

    目的：避免「Core 候選 / 不是正式 Core Yes」被舊規則用字串包含 Core Yes 誤判成正式 Core。
    回傳：yes / candidate / no / unknown。
    """
    try:
        parts = []
        if isinstance(case, dict):
            for k in ["ai_core", "core_verdict", "core_type", "subfamily", "rerating_verdict"]:
                v = case.get(k)
                if v:
                    parts.append(str(v))
            raw = case.get("raw")
            if isinstance(raw, dict):
                for k in ["ai_core", "core_verdict", "core_type", "pasted_text"]:
                    v = raw.get(k)
                    if v:
                        parts.append(str(v))
                ri = raw.get("raw_import")
                if isinstance(ri, dict):
                    for k in ["pasted_text", "ai_core", "core_verdict", "core_type"]:
                        v = ri.get(k)
                        if v:
                            parts.append(str(v))
        if text:
            parts.append(str(text))
        blob = "｜".join([x for x in parts if x])
        if not blob.strip():
            return "unknown"
        compact = re.sub(r"\s+", "", blob.lower())

        # 先抓「否定 Core Yes」；這一類在 Nick 報告中通常代表 Core 候選，不是正式 Yes。
        neg_yes = any(k in compact for k in [
            "不是正式coreyes", "非正式coreyes", "不是coreyes", "不等於coreyes",
            "不能正式coreyes", "未達正式core", "不是正式core", "無法正式收編",
            "不能正式收編", "不得正式收編", "目前不能正式收編", "不是正式收編",
        ])
        core_candidate = any(k in compact for k in [
            "core候選", "aicore：core候選", "aicore:core候選", "core候選觀察",
            "core觀察", "觀察型core", "觀察型", "候選觀察", "收編候選",
        ]) or neg_yes
        core_no = any(k in compact for k in [
            "coreno", "core:no", "core：no", "core不通過", "不具收編", "不可收編", "不收編",
        ])
        core_yes = any(k in compact for k in [
            "aicore：coreyes", "aicore:coreyes", "core：yes", "core:yes", "正式coreyes", "coreyes",
        ]) and not neg_yes

        # Core 候選優先於模糊的 Core Yes 字樣；公司體質未通過 只有在沒有候選語意時才是 No。
        if core_candidate:
            return "candidate"
        if core_no:
            return "no"
        if core_yes:
            return "yes"
        return "unknown"
    except Exception:
        return "unknown"


def nick_v253_core_is_candidate(case=None, a=None):
    level = nick_v253_forensic_core_level(case, nick_v247_case_text_blob(case, a))
    return level == "candidate"

def nick_v247_core_treasury_note(a=None, case=None):
    """v247｜Core/金庫備註模板：有法醫報告時以法醫的 AI Core / Core 類型 / 限制條件為主。"""
    a = a or {}
    case = case or (a.get("_ai_core_saved_case") if isinstance(a.get("_ai_core_saved_case"), dict) else {})
    blob = nick_v247_case_text_blob(case, a)
    core_eff = str(a.get("_forensic_core_effective") or a.get("core") or "")
    core_raw = str((case or {}).get("core_verdict") or "")
    _core_level_v253 = nick_v253_forensic_core_level(case, blob)
    is_core_yes = (_core_level_v253 == "yes") or (core_eff == "Yes" and _core_level_v253 != "candidate") or (core_raw == "Yes")
    is_candidate = (_core_level_v253 == "candidate") or (core_eff == "候選") or ("Core 候選" in blob)
    low_margin_keys = ["低毛利", "大型製造平台", "製造平台", "代工", "ODM", "EMS", "組裝", "毛利率只有", "低淨利率"]
    growth_keys = ["成長財報金庫", "金庫級", "高毛利", "高營益率", "EPS 轉大人", "結構成長", "高階測試", "高階材料", "財報品質佳"]
    turnaround_keys = ["轉機", "資金點火", "題材轉機", "觀察級", "部分通過", "尚未完全", "需財報", "需營收接棒"]

    if any(k in blob for k in low_margin_keys):
        return "公司可收編 ≠ 現在可以買；低毛利平台可 Core，但金庫/Focus 要更嚴。"
    if is_core_yes and any(k in blob for k in growth_keys):
        return "公司可收編 ≠ 現在可買；金庫級仍要看買點、籌碼與風報比。"
    if (not is_core_yes) and (is_candidate or any(k in blob for k in turnaround_keys)):
        return "具備候選條件，但仍需財報、營收或籌碼接棒確認。"
    if is_core_yes:
        return "公司可收編 ≠ 現在可買；仍要看買點、籌碼與風報比。"
    if is_candidate:
        return "具備 Core 候選條件，但仍需下一步基本面或交易訊號確認。"
    return "先看公司是否可收編，再看買點、籌碼與風報比。"


def nick_v247_layered_right_text(start_price=None, first_confirm=None, hold_price=None, short_pressure="", second_confirm=None, upper_pressure="", extra_note=""):
    """v247｜右側分層語意，不用價位高低硬判斷對錯。"""
    parts = []
    if start_price is not None:
        parts.append(f"右側啟動：先站回 {fmt_price(start_price)}")
    if first_confirm is not None:
        txt = f"第一段確認：突破 {fmt_price(first_confirm)}"
        if hold_price is not None:
            txt += f"，隔日不跌回 {fmt_price(hold_price)}"
        parts.append(txt)
    if short_pressure:
        parts.append(f"短線壓力：{short_pressure}")
    if second_confirm is not None:
        parts.append(f"關鍵壓力/第二段確認：{fmt_price(second_confirm)}")
    if upper_pressure and upper_pressure != short_pressure:
        parts.append(f"上方壓力：{upper_pressure}")
    if extra_note:
        parts.append(str(extra_note))
    return "｜".join(parts) if parts else "右側分層：資料不足"


def nick_v247_range_mid_or_next(z, fallback=None):
    r = nick_v247_parse_zone(z)
    if r:
        return (float(r[0]) + float(r[1])) / 2
    return to_float(fallback)


def nick_v247_derive_targets_from_context(close=None, support_r=None, base_plan=None):
    """v247｜沒有法醫明確目標時，目標價以同一套分層來源產生，不讓情境卡各自用舊目標。"""
    base_plan = base_plan or {}
    ref = to_float(close)
    if ref is None and support_r:
        try:
            ref = float(support_r[1])
        except Exception:
            ref = None
    if ref is None:
        return {}
    # 若 APP 原目標已經合理且不是跳太遠，可保留；否則用分層估算。
    short_txt = str(base_plan.get("short") or "")
    wave_txt = str(base_plan.get("wave") or "")
    short_anchor = nick_v217_price_anchor(short_txt)
    wave_anchor = nick_v217_price_anchor(wave_txt)
    out = {}
    if short_anchor is not None and ref * 1.03 <= short_anchor <= ref * 1.20:
        out["short"] = short_txt
    else:
        out["short"] = rng_price((ref * 1.08, ref * 1.16))
    if wave_anchor is not None and ref * 1.10 <= wave_anchor <= ref * 1.40:
        out["wave"] = wave_txt
    else:
        out["wave"] = rng_price((ref * 1.20, ref * 1.30))
    return out


def nick_v247_build_trade_semantic_plan(a=None, case=None, price=None):
    """v247｜交易 single source of truth。

    優先順序：
    1) 法醫 / AI Core 明確 trade_plan
    2) 法醫估值支撐區衍生，不跟現價漂移
    3) APP 原 plan 作 fallback
    """
    a = a or {}
    base_plan = dict(a.get("plan") or {})
    nums = dict(base_plan.get("num") or {})
    tp = nick_v247_case_trade_plan(case)
    zones = (case or {}).get("valuation_zones") or {}
    support_zone = zones.get("fundamental_support") or zones.get("support") or zones.get("基本面支撐區")
    support_r = nick_v247_parse_zone(support_zone)
    close = None
    try:
        if isinstance(price, dict):
            close = to_float(price.get("realtime_price") or price.get("close"))
    except Exception:
        close = None

    result = dict(base_plan)
    result.setdefault("num", nums)
    result.setdefault("new_label", "新倉主區")

    # v255｜若貼上的法醫文字同時含舊 30 秒摘要，可能擷取到舊摘要的買點；
    # 只要買點相對現價 / 支撐區倒掛，就放棄文字買點，回到估值支撐區衍生。
    if nick_v255_trade_plan_should_fallback(tp, support_r, close, case, a):
        tp = {}
        result["trade_plan_source_note"] = "v255_suspect_text_trade_plan_fallback_to_support"

    if tp:
        # 明確法醫交易計畫優先。
        if tp.get("new"): result["new"] = tp.get("new")
        if tp.get("shallow"): result["shallow"] = tp.get("shallow")
        if tp.get("wrong"): result["wrong"] = tp.get("wrong")
        if tp.get("stop"): result["stop"] = tp.get("stop")
        if tp.get("short"): result["short"] = tp.get("short")
        if tp.get("wave"): result["wave"] = tp.get("wave")
        upper = tp.get("upper_pressure") or base_plan.get("key_pressure_zone") or base_plan.get("key_pressure") or ""
        start = tp.get("right_start") or ""
        confirm = tp.get("right_confirm") or ""
        hold = tp.get("right_hold") or ""
        # v247｜法醫有明確右側欄位時也分層呈現。
        right_parts = []
        if start: right_parts.append(f"右側啟動：{start}")
        if confirm:
            c = f"第一段確認：{confirm}"
            if hold and hold not in c:
                c += f"，隔日不跌回 {hold}"
            right_parts.append(c)
        if upper: right_parts.append(f"短線壓力/關鍵壓力：{upper}")
        if right_parts:
            result["right"] = "｜".join(right_parts)
        result["trade_plan_source"] = "forensic_trade_plan"
    elif valuation_learning_has_usable_case(case) and support_r:
        # v254｜沒有明確法醫交易計畫時，從估值支撐區衍生「可執行買點」。
        # 核心修正：基本面支撐區 ≠ 交易買點；買點必須相對「目前即時價」分層。
        # 1) 現價位於支撐區內：主買/淺回檔應落在現價下方，不可用支撐區上緣往上追。
        # 2) 現價高於支撐區：買點才可貼近支撐區上緣，代表等回檔。
        # 3) 現價低於支撐區：不急著攤平，先等重新站回或基本面確認。
        lo, hi = support_r
        span = max(hi - lo, 1e-9)
        _core_level = nick_v253_forensic_core_level(case, nick_v247_case_text_blob(case, a))
        _rerating_txt = str((case or {}).get("rerating_verdict") or "")
        _is_candidate_like = (_core_level == "candidate") or ("部分" in _rerating_txt)
        _is_core_yes_like = (_core_level == "yes")
        cur = to_float(close)
        if cur is None or cur <= 0:
            cur = hi

        # v254｜三種價格位置：區內 / 高於 / 低於。區內時以現價回檔帶推買點。
        _inside_support = (lo <= cur <= hi)
        _above_support = (cur > hi)
        _below_support = (cur < lo)

        if _inside_support:
            if _is_candidate_like:
                # 候選股在支撐區內：仍只允許回檔觀察，避免把現價上方叫買點。
                new_lo = max(lo, cur * 0.900)
                new_hi = min(hi, cur * 0.950)
                shallow_lo = max(lo, cur * 0.955)
                shallow_hi = min(hi, cur * 0.985)
                short_wrong_lo = max(lo, cur * 0.920)
                short_wrong_hi = min(cur * 0.955, shallow_lo)
            elif _is_core_yes_like:
                # Core Yes / 金庫級在支撐區內：主買落在回檔甜點，淺回檔落在現價下方。
                new_lo = max(lo, cur * 0.930)
                new_hi = min(hi, cur * 0.970)
                shallow_lo = max(lo, cur * 0.972)
                shallow_hi = min(hi, cur * 0.995)
                short_wrong_lo = max(lo, cur * 0.955)
                short_wrong_hi = min(hi, cur * 0.985)
            else:
                new_lo = max(lo, cur * 0.920)
                new_hi = min(hi, cur * 0.965)
                shallow_lo = max(lo, cur * 0.970)
                shallow_hi = min(hi, cur * 0.995)
                short_wrong_lo = max(lo, cur * 0.940)
                short_wrong_hi = min(hi, cur * 0.975)
        elif _above_support:
            # 現價已高於基本面支撐區：等回支撐上緣/回測，不追。
            if _is_candidate_like:
                new_lo = hi * 0.970
                new_hi = hi * 1.005
                shallow_lo = max(hi * 1.010, min(cur * 0.970, hi * 1.035))
                shallow_hi = min(cur * 0.995, hi * 1.055)
                short_wrong_lo = hi * 0.960
                short_wrong_hi = hi * 0.985
            elif _is_core_yes_like:
                new_lo = hi * 0.920
                new_hi = hi * 0.980
                shallow_lo = max(hi * 0.985, min(cur * 0.970, hi * 1.010))
                shallow_hi = min(cur * 0.995, hi * 1.025)
                short_wrong_lo = hi * 0.945
                short_wrong_hi = hi * 0.975
            else:
                new_lo = lo + span * 0.55
                new_hi = lo + span * 0.82
                shallow_lo = hi * 0.970
                shallow_hi = hi * 1.005
                short_wrong_lo = lo + span * 0.62
                short_wrong_hi = hi * 0.960
        else:
            # 現價低於支撐區：不可把支撐區上方寫成新倉主買，先看站回與基本面是否變差。
            new_lo = max(cur * 0.970, lo * 0.920)
            new_hi = min(lo * 0.995, cur * 1.030)
            shallow_lo = min(lo, cur * 1.010)
            shallow_hi = min(hi, cur * 1.050)
            short_wrong_lo = max(cur * 0.940, lo * 0.880)
            short_wrong_hi = max(cur * 0.970, short_wrong_lo)

        # 區間防呆：買點區間不應整段高於現價；若發生，回到現價下方重新校正。
        if cur and new_lo > cur * 1.005:
            new_lo = max(lo, cur * 0.930)
            new_hi = min(hi, cur * 0.970)
        if cur and shallow_lo > cur * 1.005:
            shallow_lo = max(lo, cur * 0.972)
            shallow_hi = min(hi, cur * 0.995)
        if new_hi < new_lo:
            new_lo, new_hi = min(new_lo, new_hi), max(new_lo, new_hi)
        if shallow_hi < shallow_lo:
            shallow_lo, shallow_hi = min(shallow_lo, shallow_hi), max(shallow_lo, shallow_hi)

        result["new"] = nick_v247_range_text_from_tuple(new_lo, new_hi)
        result["shallow"] = nick_v247_range_text_from_tuple(shallow_lo, shallow_hi)
        result["wrong"] = nick_v247_range_text_from_tuple(short_wrong_lo, short_wrong_hi) or result.get("wrong")
        wave_lo = lo
        wave_hi = lo * 1.05
        result["stop"] = nick_v247_range_text_from_tuple(wave_lo, wave_hi) or result.get("stop")

        # v254｜右側條件優先用真正的上方壓力；壓力若低於現價，視為已站上，不拿來當未來壓力。
        upper_pressure = base_plan.get("key_pressure_zone") or base_plan.get("key_pressure") or ""
        upper_r = nick_v247_parse_zone(upper_pressure)
        short_pressure = ""
        start_price = None
        if upper_r and upper_r[1] > cur * 1.005:
            short_pressure = upper_pressure
            start_price = upper_r[1]
        elif hi > cur * 1.005:
            start_price = hi
        else:
            # 若已在支撐區內且上緣高於現價不多，右側看前高/心理整數，避免寫「站回已經在下方的價位」。
            start_price = nick_v247_next_round_price(cur * 1.03)
        first_confirm = nick_v247_next_round_price((start_price or cur) * 1.01)
        try:
            if first_confirm is not None and start_price is not None and first_confirm <= start_price:
                first_confirm = nick_v247_next_round_price(start_price * 1.015)
        except Exception:
            pass
        # 隔日不跌回必須低於確認價，不能出現「突破 420，隔日不跌回 422」這種倒掛。
        hold_price = None
        try:
            if first_confirm is not None:
                hold_price = min(first_confirm * 0.985, (start_price or first_confirm) * 0.995)
        except Exception:
            hold_price = None

        second_confirm = None
        try:
            raw_right_anchor = nick_v217_price_anchor(base_plan.get("right"))
            old_short_anchor = nick_v217_price_anchor(base_plan.get("short"))
            wave_anchor = nick_v217_price_anchor(base_plan.get("wave"))
            candidates_2nd = [x for x in [raw_right_anchor, old_short_anchor, wave_anchor] if x is not None and x > (first_confirm or cur) * 1.10]
            if candidates_2nd:
                second_confirm = nick_v247_next_round_price(min(candidates_2nd))
        except Exception:
            second_confirm = None

        _tg = nick_v247_derive_targets_from_context(cur if cur is not None else hi, support_r=support_r, base_plan=base_plan)
        if _tg.get("short"):
            result["short"] = _tg["short"]
        if _tg.get("wave"):
            result["wave"] = _tg["wave"]
        result["right"] = nick_v247_layered_right_text(
            start_price=start_price,
            first_confirm=first_confirm,
            hold_price=hold_price,
            short_pressure=short_pressure,
            second_confirm=second_confirm,
            upper_pressure="",
        )
        result["trade_plan_source"] = "forensic_valuation_derived_v254"
    else:
        result["trade_plan_source"] = "app_plan"

    # 同步 num，讓小白表 / 情境卡 / 交易卡都吃同一組數字。
    def _fill_range_nums(txt, low_key, high_key):
        r = nick_v247_parse_zone(txt)
        if r:
            result["num"][low_key], result["num"][high_key] = r[0], r[1]
    _fill_range_nums(result.get("new"), "new_low", "new_high")
    _fill_range_nums(result.get("shallow"), "shallow_low", "shallow_high")
    _fill_range_nums(result.get("wrong"), "wrong_low", "wrong_high")
    _fill_range_nums(result.get("stop"), "stop_low", "stop_high")
    try:
        _short_r = nick_v247_parse_zone(result.get("short"))
        if _short_r:
            result["num"]["short"] = _short_r[1]
        else:
            _short_a = nick_v217_price_anchor(result.get("short"))
            if _short_a is not None:
                result["num"]["short"] = _short_a
        _wave_r = nick_v247_parse_zone(result.get("wave"))
        if _wave_r:
            result["num"]["wave"] = _wave_r[1]
        else:
            _wave_a = nick_v217_price_anchor(result.get("wave"))
            if _wave_a is not None:
                result["num"]["wave"] = _wave_a
        _stop_r = nick_v247_parse_zone(result.get("stop"))
        if _stop_r:
            result["num"]["stop"] = _stop_r[0]
    except Exception:
        pass
    try:
        # 情境分數的右側買點吃第一段確認，不吃短線壓力 / 第二段確認 / 波段目標。
        right_confirm = None
        s_right = str(result.get("right") or "")
        for pat in [r"第一段確認[：:][^\d]*(\d+(?:\.\d+)?)", r"右側確認[：:][^\d]*(\d+(?:\.\d+)?)"]:
            m = re.search(pat, s_right)
            if m:
                right_confirm = to_float(m.group(1))
                break
        if right_confirm is None:
            m = re.search(r"右側啟動[：:][^\d]*(\d+(?:\.\d+)?)", s_right)
            if m:
                right_confirm = to_float(m.group(1))
        if right_confirm is not None:
            result["num"]["right"] = right_confirm
    except Exception:
        pass
    # 新倉主區用同一標籤，避免 30秒/小白/交易表各講各的。
    result["new_label"] = result.get("new_label") or "新倉主區"
    return result


def nick_v247_apply_trade_semantic_plan(a=None, case=None, price=None):
    """把 canonical trade plan 寫回 a['plan']，供所有前台共用。"""
    if not isinstance(a, dict):
        return a
    try:
        plan = nick_v247_build_trade_semantic_plan(a, case, price)
        a["plan"] = plan
        a["_trade_semantic_plan"] = plan
        return a
    except Exception:
        return a


def _nick_parse_ai_core_text_to_case_fields(raw_text, default_subfamily="", default_source="manual_text"):
    """把 Nick 貼上的法醫估值結論文字，轉成 SQLite AI Core 案例欄位。

    v67.1：支援逐行貼：EPS 保守 / EPS 中性 / EPS 樂觀、PE 保守 / PE 中性 / PE 樂觀 / PE 重評上緣。
    """
    raw_text = str(raw_text or "").strip()
    raw_obj = {}
    if raw_text and raw_text[:1] in ["{", "["]:
        raw_obj = _nick_json_loads(raw_text, {})
        if isinstance(raw_obj, dict) and any(k in raw_obj for k in ["core_verdict", "eps_assumption", "pe_assumption", "valuation_zones"]):
            return {
                "core_verdict": str(raw_obj.get("core_verdict") or "").strip(),
                "rerating_verdict": str(raw_obj.get("rerating_verdict") or "").strip(),
                "core_type": str(raw_obj.get("core_type") or "").strip(),
                "subfamily": str(raw_obj.get("subfamily") or default_subfamily or "").strip(),
                "source": str(raw_obj.get("source") or default_source or "manual_text").strip(),
                "eps_assumption": raw_obj.get("eps_assumption") or {},
                "pe_assumption": raw_obj.get("pe_assumption") or {},
                "valuation_zones": raw_obj.get("valuation_zones") or {},
                "trade_plan": raw_obj.get("trade_plan") or raw_obj.get("forensic_trade_plan") or raw_obj.get("trade_semantic_plan") or {},
                "validation_rules": raw_obj.get("validation_rules") or {"valid_days": 90},
                "limitations": raw_obj.get("limitations") or [],
                "raw_import": raw_obj,
            }

    core_verdict = _nick_extract_label_value_from_text(raw_text, ["AI Core", "Core", "核心判斷", "AI Core 判斷"])
    rerating_verdict = _nick_extract_label_value_from_text(raw_text, ["估值重評", "重評", "Re-rating", "估值重評判斷"])
    core_type = _nick_extract_label_value_from_text(raw_text, ["Core 類型", "核心類型", "族群 / 模組方向", "子族群 / 模組方向", "子族群"])

    # EPS：優先讀取 Nick 新格式三段假設；若沒有，才回到舊版「EPS 假設」。
    eps_general = _nick_extract_label_value_from_text(raw_text, ["EPS 假設", "預估 EPS", "未來 EPS"])
    eps_bear = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["EPS 保守", "保守 EPS", "EPS 低標", "EPS Bear"]))
    eps_base = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["EPS 中性", "EPS 基準", "EPS Base", "EPS 假設", "預估 EPS", "未來 EPS"]))
    eps_bull = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["EPS 樂觀", "樂觀 EPS", "EPS 高標", "EPS Bull"]))
    eps_failure = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["EPS 失敗", "EPS 下修", "驗證失敗 EPS", "EPS Failure"]))
    if eps_general and not eps_base:
        eps_base = _nick_clean_ai_core_number_text(eps_general)
    # 舊格式只有一個 EPS 時，不要再把 bull 硬塞等於 base；有明確樂觀才填樂觀。
    if eps_general and not eps_bear and not eps_bull:
        eps_base = eps_base or _nick_clean_ai_core_number_text(eps_general)

    # PE：支援 PE 保守 / PE 中性 / PE 樂觀 / PE 重評上緣；若只有 PE 區間，沿用舊版 range parser。
    pe_text = _nick_extract_label_value_from_text(raw_text, ["PE 區間", "本益比區間", "合理 PE", "PE 假設"])
    pe_bear = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["PE 保守", "保守 PE", "PE 低標", "本益比保守", "PE Bear"]))
    pe_base = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["PE 中性", "PE 基準", "本益比中性", "合理 PE", "PE Base"]))
    pe_bull = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["PE 樂觀", "樂觀 PE", "本益比樂觀", "PE 高標", "PE Bull"]))
    pe_rerating = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["PE 重評上緣", "重評上緣", "PE 重評", "重評 PE", "重評倍數", "PE Rerating"]))
    pe_failure = _nick_clean_ai_core_number_text(_nick_extract_label_value_from_text(raw_text, ["PE 失敗", "PE 下修", "驗證失敗 PE", "PE Failure"]))
    if pe_text and not any([pe_bear, pe_base, pe_bull, pe_rerating]):
        pe_assumption = _nick_parse_pe_assumption_text(pe_text)
    else:
        pe_assumption = {
            "bear": pe_bear,
            "base": pe_base,
            "bull": pe_bull,
            "rerating": pe_rerating,
            "failure": pe_failure,
        }
        # 若同時貼 PE 區間 + 部分逐項欄位，用區間補空白中性/樂觀。
        if pe_text:
            _range_pe = _nick_parse_pe_assumption_text(pe_text)
            if not pe_assumption.get("base"):
                pe_assumption["base"] = _range_pe.get("base") or ""
            if not pe_assumption.get("bull"):
                pe_assumption["bull"] = _range_pe.get("bull") or ""
            if not pe_assumption.get("rerating"):
                pe_assumption["rerating"] = _range_pe.get("rerating") or ""

    support_zone = _nick_extract_label_value_from_text(raw_text, ["基本面支撐區", "基本面支撐價", "支撐區"])
    rerating_zone = _nick_extract_label_value_from_text(raw_text, ["重評合理區", "重評區間", "重評價", "樂觀區"])
    failure_zone = _nick_extract_label_value_from_text(raw_text, ["驗證失敗下修區", "驗證失敗區", "下修區", "失敗區"])

    validation_text = _nick_extract_label_value_from_text(raw_text, ["驗證條件", "後續驗證條件", "觀察條件", "驗證重點"])
    limit_text = _nick_extract_label_value_from_text(raw_text, ["限制條件", "失效提醒", "失效條件", "風險提醒"])
    limitations = _nick_split_condition_text(limit_text)
    validation_conditions = _nick_split_condition_text(validation_text)
    trade_plan = nick_v247_extract_trade_plan_from_text(raw_text)

    return {
        "core_verdict": core_verdict,
        "rerating_verdict": rerating_verdict,
        "core_type": core_type or default_subfamily or "",
        "subfamily": core_type or default_subfamily or "",
        "source": default_source or "manual_text",
        "eps_assumption": {
            "bear": eps_bear,
            "base": eps_base,
            "bull": eps_bull,
            "failure": eps_failure,
        },
        "pe_assumption": pe_assumption,
        "valuation_zones": {
            "fundamental_support": _nick_clean_ai_core_range_text(support_zone),
            "rerating_fair_zone": _nick_clean_ai_core_range_text(rerating_zone),
            "failure_downside_zone": _nick_clean_ai_core_range_text(failure_zone),
        },
        "trade_plan": trade_plan,
        "validation_rules": {
            "valid_days": 90,
            "conditions_text": validation_text,
            "conditions": validation_conditions,
        },
        "limitations": limitations,
        "raw_import": {
            "pasted_text": raw_text,
            "parsed_by": "nick_ai_core_text_parser_v67_1",
            "json_if_any": raw_obj if isinstance(raw_obj, (dict, list)) else {},
        },
    }



# =========================================================
# v271.4｜法醫 v6.7 當次參數優先權：估值結構參數 > SQLite 舊 AI Core > APP 自算
# 目的：若 Nick 在補充證據貼了 v6.7 APP 作戰參數，當次分析就先套用，避免前台仍顯示舊估值錨點。
# =========================================================
def nick_v2714_extract_label_value(txt, labels):
    txt = str(txt or "")
    labels = labels if isinstance(labels, (list, tuple, set)) else [labels]
    lines = [str(x).strip() for x in txt.splitlines()]
    found = ""
    for i, line in enumerate(lines):
        if not line:
            continue
        for label in labels:
            label = str(label or "").strip()
            if not label:
                continue
            patterns = [
                rf"^\s*{re.escape(label)}\s*[：:]\s*(.*?)\s*$",
                rf"^\s*{re.escape(label)}\s*（[^）]*）\s*[：:]\s*(.*?)\s*$",
                rf"^\s*{re.escape(label)}\s*\([^)]*\)\s*[：:]\s*(.*?)\s*$",
            ]
            for pat in patterns:
                m = re.match(pat, line)
                if m:
                    found = (m.group(1) or "").strip()
            if re.match(rf"^\s*{re.escape(label)}\s*[：:]?\s*$", line) and i + 1 < len(lines):
                nxt = lines[i + 1].strip()
                if nxt:
                    found = nxt
    return str(found or "").strip()


def nick_v2714_clean_range(x):
    try:
        return _nick_clean_ai_core_range_text(x)
    except Exception:
        s = str(x or "").strip()
        s = s.replace("－", "～").replace("-", "～").replace("~", "～").replace("—", "～")
        s = re.sub(r"\s+", " ", s)
        return s.replace("元", "").replace("倍", "").strip(" ：:,，;；")


def nick_v2714_clean_num(x):
    try:
        return _nick_clean_ai_core_number_text(x)
    except Exception:
        s = nick_v2714_clean_range(x)
        m = re.search(r"\d+(?:\.\d+)?", s)
        return m.group(0) if m else s


def nick_v2714_build_forensic_v67_case(raw_text, stock_id="", stock_name="", industry_category=""):
    """把當次貼入的 v6.7 APP 作戰參數複製框轉成暫時 AI Core case。
    不寫入 SQLite，只在本次分析中作為最高優先前台錨點。
    """
    raw_text = str(raw_text or "").strip()
    if not raw_text:
        return None
    has_v67 = any(k in raw_text for k in ["APP 作戰參數", "估值結構參數", "法醫交易快照", "forensic_snapshot_date", "Nick 法醫報告 v6.7"])
    if not has_v67:
        return None

    core_ai = nick_v2714_extract_label_value(raw_text, ["AI Core"])
    core_plain = nick_v2714_extract_label_value(raw_text, ["Core"])
    core_type = nick_v2714_extract_label_value(raw_text, ["Core 類型", "forensic_core_type"])
    rerating = nick_v2714_extract_label_value(raw_text, ["估值重評狀態", "forensic_rerating_status", "估值重評"])

    eps = {
        "bear": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["EPS 保守"])),
        "base": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["EPS 中性", "EPS 假設"])),
        "bull": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["EPS 樂觀"])),
        "failure": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["EPS 失敗", "EPS 下修"])),
    }
    pe = {
        "bear": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["PE 保守"])),
        "base": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["PE 中性"])),
        "bull": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["PE 樂觀"])),
        "rerating": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["PE 重評上緣", "PE 重評", "重評 PE"])),
        "failure": nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, ["PE 失敗", "PE 下修"])),
    }
    zones = {
        "fundamental_support": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["基本面支撐區", "forensic_value_floor"])),
        "rerating_fair_zone": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["重評合理區", "forensic_re_rating_zone"])),
        "failure_downside_zone": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["驗證失敗下修區", "forensic_fail_zone"])),
    }
    trade_plan = {
        "new": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照新倉主區", "snapshot_main_buy_zone"])),
        "shallow": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照小倉試單區", "snapshot_small_position_zone"])),
        "right_confirm": nick_v2714_extract_label_value(raw_text, ["快照右側確認條件", "snapshot_right_confirm"]),
        "upper_pressure": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照短線 / 關鍵壓力", "快照短線/關鍵壓力", "snapshot_pressure"])),
        "wrong": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照短線追錯失效", "snapshot_short_invalid"])),
        "stop": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照波段防守參考", "snapshot_swing_defense", "快照洗盤忍受底線"])),
        "short": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照短線目標", "snapshot_short_target"])),
        "wave": nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, ["快照波段目標", "snapshot_swing_target"])),
    }

    if not any(str(v or "").strip() for v in [core_ai, core_plain, core_type, rerating] + list(zones.values()) + list(eps.values()) + list(pe.values())):
        return None

    snapshot_date = nick_v2714_extract_label_value(raw_text, ["報告日期", "forensic_snapshot_date"])
    report_verdict = nick_v2714_extract_label_value(raw_text, ["財報裁決"])
    verdict_type = nick_v2714_extract_label_value(raw_text, ["財報部分通過類型"])
    treasury = nick_v2714_extract_label_value(raw_text, ["財報金庫"])
    fin_quality = nick_v2714_extract_label_value(raw_text, ["法醫財務品質"])
    attack = nick_v2714_extract_label_value(raw_text, ["Attack"])
    attack_type = nick_v2714_extract_label_value(raw_text, ["Attack 類型"])
    focus = nick_v2714_extract_label_value(raw_text, ["Focus"])
    final_action = nick_v2714_extract_label_value(raw_text, ["最終動作"])
    limitations = _nick_split_condition_text(nick_v2714_extract_label_value(raw_text, ["限制條件", "最大反方證據", "買錯條件"]))

    now_txt = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    structural = {
        "forensic_snapshot_date": snapshot_date,
        "report_verdict": report_verdict,
        "report_verdict_type": verdict_type,
        "treasury_level": treasury,
        "financial_quality": fin_quality,
        "attack": attack,
        "attack_type": attack_type,
        "focus": focus,
        "final_action": final_action,
    }
    return {
        "stock_id": str(stock_id or ""),
        "stock_name": str(stock_name or ""),
        "industry_family": str(industry_category or ""),
        "model_key": "forensic_v67_current_run",
        "subfamily": core_type or str(industry_category or ""),
        "source": "forensic_v67_current_run",
        "core_verdict": core_plain or core_ai,
        "ai_core": core_ai,
        "core_type": core_type,
        "rerating_verdict": rerating,
        "eps_assumption": {k: v for k, v in eps.items() if str(v or "").strip()},
        "pe_assumption": {k: v for k, v in pe.items() if str(v or "").strip()},
        "valuation_zones": {k: v for k, v in zones.items() if str(v or "").strip()},
        "trade_plan": {k: v for k, v in trade_plan.items() if str(v or "").strip()},
        "validation_rules": {"valid_days": 90, "conditions_text": nick_v2714_extract_label_value(raw_text, ["驗證條件", "買後續抱條件", "重新法醫條件"])},
        "limitations": limitations,
        "created_at": now_txt,
        "updated_at": now_txt,
        "raw": {
            "raw_import": {
                "pasted_text": raw_text,
                "parsed_by": "v2714_forensic_v67_current_run_parser",
                "forensic_v67_detected": True,
                "forensic_structural_params": {k: v for k, v in structural.items() if str(v or "").strip()},
                "forensic_trade_snapshot": {k: v for k, v in trade_plan.items() if str(v or "").strip()},
                "snapshot_lifecycle_note": "估值結構參數是地形；交易快照是天氣，APP 每日用 Nick 撐壓 / 均線 / 籌碼重新校正。",
            }
        },
    }


