def nick_v2715_get_v67_import(case):
    try:
        raw = (case or {}).get("raw") or {}
        imp = raw.get("raw_import") if isinstance(raw, dict) else {}
        return imp if isinstance(imp, dict) and imp.get("forensic_v67_detected") else {}
    except Exception:
        return {}


def nick_v2715_is_v67(case):
    return bool(nick_v2715_get_v67_import(case))


def nick_v2715_struct(case):
    imp = nick_v2715_get_v67_import(case)
    stt = imp.get("forensic_structural_params") if isinstance(imp, dict) else {}
