def nick_v2715_trade_snapshot(case):
    imp = nick_v2715_get_v67_import(case)
    snap = imp.get("forensic_trade_snapshot") if isinstance(imp, dict) else {}
    return snap if isinstance(snap, dict) else {}


def nick_v2715_case_verdict(case):
    """回傳 v6.7/v6.8 法醫結構裁決，不碰個股特例。
    v271.8：同時支援舊鍵名(forensic_core_type)與新版一體化鍵名(core_type/rerating_status)。
    """
    stt = nick_v2715_struct(case)
    case = case or {}
    return {
        "core": str(case.get("core_verdict") or case.get("ai_core") or stt.get("core") or stt.get("ai_core") or "").strip(),
        "core_type": str(case.get("core_type") or stt.get("core_type") or stt.get("forensic_core_type") or "").strip(),
        "rerating": str(case.get("rerating_verdict") or stt.get("rerating_status") or stt.get("forensic_rerating_status") or "").strip(),
        "report": str(stt.get("report_verdict") or stt.get("forensic_report_verdict") or "").strip(),
        "report_type": str(stt.get("report_verdict_type") or stt.get("forensic_report_verdict_type") or "").strip(),
        "treasury": str(stt.get("treasury_level") or stt.get("forensic_treasury_level") or "").strip(),
        "financial_quality": str(stt.get("financial_quality") or stt.get("forensic_financial_quality") or "").strip(),
        "attack_snapshot": str(stt.get("attack") or stt.get("forensic_attack") or "").strip(),
        "attack_type_snapshot": str(stt.get("attack_type") or stt.get("forensic_attack_type") or "").strip(),
        "focus_snapshot": str(stt.get("focus") or stt.get("forensic_focus") or "").strip(),
        "final_action_snapshot": str(stt.get("final_action") or stt.get("forensic_final_action") or "").strip(),
    }


def nick_v2715_norm_yes_no(x):
    s = str(x or "").strip().lower()
    if not s:
        return ""
    if s in {"yes", "y", "true", "1", "是"} or "yes" in s:
        return "Yes"
    if s in {"no", "n", "false", "0", "否"} or "no" in s:
        return "No"
    return str(x or "").strip()


def nick_v2715_apply_forensic_frontend_rules(a, case, price=None):
    """前台共用裁決來源：法醫給地形，APP 算天氣。
    - 只把穩定結構參數寫回前台語意（Core/財報/估值錨點）。
    - Attack/Focus/買點若來自法醫，標成快照，不覆蓋 APP 今日動態運算。
    """
    if not isinstance(a, dict) or not valuation_learning_has_usable_case(case) or not nick_v2715_is_v67(case):
        return a
    v = nick_v2715_case_verdict(case)
    a["_v2715_forensic_frontend_applied"] = True
    a["_v2715_forensic_verdict"] = v
    a["_v2715_forensic_trade_snapshot"] = nick_v2715_trade_snapshot(case)

    # Core 是公司收編結構參數，穩定度高，可統一前台，不等於現價可買。
    core_norm = nick_v2715_norm_yes_no(v.get("core"))
    if core_norm == "Yes":
        a["core"] = "Yes"
        a["_forensic_core_effective"] = "Yes"
        if v.get("core_type"):
            a["core_status"] = v.get("core_type")
    elif core_norm == "No":
        a["core"] = "No"
        a["_forensic_core_effective"] = "No"

    # 財報裁決與財務品質是結構參數，前台可引用，避免把高品質公司誤寫成財務惡化。
    fj = a.get("fin_j") or {}
    if not isinstance(fj, dict):
        fj = {}
    if v.get("report"):
        fj["report"] = v.get("report")
    if v.get("report_type"):
        fj["report_type"] = v.get("report_type")
        fj["forensic_report_type"] = v.get("report_type")
    if v.get("treasury"):
        fj["treasury"] = v.get("treasury")
    if v.get("financial_quality"):
        fj["forensic_financial_quality"] = v.get("financial_quality")
        # 高品質但交易限制型：不是財務惡化，只是估值/買點要防守。
        if v.get("financial_quality") == "高" and ("部分" in v.get("report", "") or "B" in v.get("report_type", "") or "交易限制" in v.get("report_type", "")):
            radar = fj.get("financial_radar") or {}
            if isinstance(radar, dict):
                radar["summary"] = "高品質｜交易限制"
                radar["quick"] = "公司體質高，但本次財報只算部分通過；現價需看營收/EPS接棒與買點。"
                fj["financial_radar"] = radar
    a["fin_j"] = fj

    # 如果現有 action 還是因 APP 舊 公司體質未通過 導致過度保守，改成通用口令，不用個股文字。
    if core_norm == "Yes" and str(a.get("action") or "") in ["不買", "暫不操作", "只觀察", "只觀察 / 等右側"]:
        a["action"] = "等回檔 / 建立追蹤"
        a["why"] = "公司已通過法醫收編；現價能否動手仍由 APP 今日防線、買點、籌碼與風報比決定。"
        if str(a.get("grade") or "") in ["D", "E", "", "?"]:
            a["grade"] = "C"
    return a


def nick_v2715_support_summary_from_case(case, price=None):
    """v6.7 專用基本面支撐卡：只顯示法醫結構參數，不把快照價位當永久防線。"""
    if not valuation_learning_has_usable_case(case) or not nick_v2715_is_v67(case):
        return None
    zones = (case or {}).get("valuation_zones") or {}
    support_txt = str(zones.get("fundamental_support") or "").strip()
    rerating_txt = str(zones.get("rerating_fair_zone") or "").strip()
    failure_txt = str(zones.get("failure_downside_zone") or "").strip()
    if not any([support_txt, rerating_txt, failure_txt]):
        return None
    ref_price = None
    try:
        if isinstance(price, dict):
            ref_price = to_float(price.get("realtime_price") or price.get("close"))
        else:
            ref_price = to_float(price)
    except Exception:
        ref_price = None
    relation = "需搭配今日價格判斷"
    sr = valuation_learning_parse_range(support_txt)
    rr = valuation_learning_parse_range(rerating_txt)
    if ref_price is not None:
        if sr:
            lo, hi = sr
            if lo <= ref_price <= hi:
                relation = "位於法醫基本面支撐區；仍要看買點與籌碼。"
            elif ref_price > hi:
                relation = "高於法醫基本面支撐區；需靠後續營收、毛利率與 EPS 接棒。"
            elif ref_price < lo:
                relation = "低於法醫支撐區；便宜不等於可買，需確認劇本未壞。"
        if rr:
            lo, hi = rr
            if lo <= ref_price <= hi:
                relation = "位於法醫重評合理區；不是便宜區，追價需更強驗證。"
            elif ref_price > hi:
                relation = "高於法醫重評合理區；屬高溢價，需嚴格控風險。"
    quick_parts = [
        f"基本面支撐區：{support_txt or '資料不足'}",
        f"重評合理區：{rerating_txt or '資料不足'}",
        f"驗證失敗下修區：{failure_txt or '資料不足'}",
        relation,
    ]
    return {
        "support_range": support_txt or "資料不足",
        "card_value": f"法醫支撐 {support_txt}" if support_txt else "法醫支撐 資料不足",
        "card_note": relation,
        "quick": "\n".join(quick_parts),
        "check": "法醫結構參數作估值錨點；APP 每日重算交易防線。",
        "source": "估值結構參數",
    }




# =========================================================
# v271.6｜AI Core 一體化輸入框：法醫估值地形 + 交易快照天氣 + 自我學習素材 + 同族群案例
# 目的：Nick 只貼一次，APP 同時完成：單檔估值錨點、族群案例累積、學習規則草稿沉澱。
# 原則：自我學習只存「待確認規則素材」，不讓 APP 自己亂改正式規則。
# =========================================================
def nick_v2716_is_integrated_input(raw_text):
    raw_text = str(raw_text or "")
    keys = [
        "Nick AI Core 一體化輸入框", "AI Core 一體化", "v6.8",
        "分析器自我學習", "同族群案例標籤", "法醫結構參數", "法醫交易快照",
        "APP 作戰參數複製框", "Nick 法醫報告 v6.7",
    ]
    return any(k in raw_text for k in keys)


def nick_v2716_extract_section(raw_text, section_title_keywords):
    """擷取【三、分析器自我學習】這類 section。"""
    raw_text = str(raw_text or "")
    keys = section_title_keywords if isinstance(section_title_keywords, (list, tuple, set)) else [section_title_keywords]
    lines = raw_text.splitlines()
    start = None
    for i, line in enumerate(lines):
        clean = str(line or "").strip()
        if any(str(k) in clean for k in keys):
            start = i + 1
            break
    if start is None:
        return ""
    out = []
    for line in lines[start:]:
        clean = str(line or "").strip()
        # 遇到下一個大 section 就停止
        if re.match(r"^【[^】]+】", clean) and not any(str(k) in clean for k in keys):
            break
        if clean.startswith("━━━━━━━━"):
            # 分隔線不是內容，但不中斷，因為有些格式 section 中間會用分隔線。
            continue
        out.append(line)
    return "\n".join(out).strip()


def nick_v2716_extract_block_value(raw_text, labels, stop_labels=None):
    """支援：標籤：下一行多行條列，直到下一個標籤/section。"""
    raw_text = str(raw_text or "")
    labels = labels if isinstance(labels, (list, tuple, set)) else [labels]
    stop_labels = set([str(x) for x in (stop_labels or []) if str(x or "").strip()])
    lines = raw_text.splitlines()
    label_patterns = [str(x).strip() for x in labels if str(x or "").strip()]
    start = None
    inline_val = ""
    for i, line in enumerate(lines):
        clean = str(line or "").strip()
        for label in label_patterns:
            m = re.match(rf"^\s*{re.escape(label)}\s*[：:]\s*(.*?)\s*$", clean)
            if m:
                start = i + 1
                inline_val = (m.group(1) or "").strip()
                break
        if start is not None:
            break
    if start is None:
        return ""
    if inline_val:
        return inline_val
    out = []
    # 常見欄位名，遇到就停
    common_stops = set([
        "這次 APP 可能判錯的地方", "正確應該怎麼判", "這次可萃取成通用規則嗎", "若可，適用範圍",
        "建議通用規則", "不可硬改提醒", "驗收標準", "族群", "子族群", "本檔在族群角色",
        "本檔可否作為族群估值案例", "可參考原因", "不可參考限制", "限制條件", "最大反方證據",
        "買錯條件", "基本面 / 劇本徹底翻案觸發點", "備註"
    ]) | stop_labels
    for line in lines[start:]:
        clean = str(line or "").strip()
        if not clean:
            if out:
                out.append("")
            continue
        if clean.startswith("━━━━━━━━"):
            break
        if re.match(r"^【[^】]+】", clean):
            break
        # 下一個欄位開始就停止
        for stp in common_stops:
            if stp and re.match(rf"^\s*{re.escape(stp)}\s*[：:]?\s*", clean):
                return "\n".join(out).strip()
        out.append(clean)
    return "\n".join(out).strip()


def nick_v2716_split_lines(txt):
    txt = str(txt or "").strip()
    if not txt:
        return []
    items = []
    for line in txt.splitlines():
        line = str(line or "").strip()
        line = re.sub(r"^[\-•*]\s*", "", line)
        line = re.sub(r"^\d+[\.、)]\s*", "", line)
        if line:
            items.append(line)
    return items


def nick_v2716_parse_self_learning(raw_text):
    section = nick_v2716_extract_section(raw_text, ["分析器自我學習"])
    if not section:
        return {}
    possible = nick_v2716_extract_block_value(section, ["這次 APP 可能判錯的地方", "APP 哪裡判錯", "這次 APP 判斷問題"])
    correct = nick_v2716_extract_block_value(section, ["正確應該怎麼判", "法醫正確裁決"])
    generalizable = nick_v2716_extract_block_value(section, ["這次可萃取成通用規則嗎", "能不能變成通用規則"])
    scope = nick_v2716_extract_block_value(section, ["若可，適用範圍", "適用範圍"])
    rules = nick_v2716_extract_block_value(section, ["建議通用規則", "要萃取成通用規則", "通用規則"])
    guardrails = nick_v2716_extract_block_value(section, ["不可硬改提醒", "硬改提醒"])
    acceptance = nick_v2716_extract_block_value(section, ["驗收標準"])
    return {
        "possible_app_errors": nick_v2716_split_lines(possible),
        "correct_judgement": nick_v2716_split_lines(correct),
        "generalizable": generalizable,
        "scope": scope,
        "suggested_rules": nick_v2716_split_lines(rules),
        "guardrails": nick_v2716_split_lines(guardrails),
        "acceptance_criteria": nick_v2716_split_lines(acceptance),
        "raw_section": section,
        "status": "pending_confirmation",
        "note": "這是學習素材/待確認規則草稿，不會自動改正式規則。",
    }


def nick_v2716_parse_peer_case_tags(raw_text):
    section = nick_v2716_extract_section(raw_text, ["同族群案例標籤"])
    if not section:
        return {}
    peer = {
        "sector": nick_v2716_extract_block_value(section, ["族群"]),
        "subsector": nick_v2716_extract_block_value(section, ["子族群"]),
        "role": nick_v2716_extract_block_value(section, ["本檔在族群角色"]),
        "use_as_peer_case": nick_v2716_extract_block_value(section, ["本檔可否作為族群估值案例"]),
        "reference_reasons": nick_v2716_split_lines(nick_v2716_extract_block_value(section, ["可參考原因"])),
        "reference_limits": nick_v2716_split_lines(nick_v2716_extract_block_value(section, ["不可參考限制"])),
        "raw_section": section,
    }
    return {k: v for k, v in peer.items() if v not in [None, "", [], {}]}


