_nick_v2716_base_valuation_learning_init_db = valuation_learning_init_db

def valuation_learning_init_db(db_path=VALUATION_LEARNING_DB):
    _nick_v2716_base_valuation_learning_init_db(db_path)
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS analyzer_learning_suggestions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                stock_id TEXT,
                stock_name TEXT,
                industry_family TEXT,
                case_id INTEGER,
                suggestion_type TEXT DEFAULT 'rule_draft',
                scope TEXT,
                title TEXT,
                content_json TEXT,
                status TEXT DEFAULT 'pending',
                created_at TEXT,
                updated_at TEXT,
                is_active INTEGER DEFAULT 1
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS analyzer_formal_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                suggestion_id INTEGER,
                stock_id TEXT,
                stock_name TEXT,
                industry_family TEXT,
                scope TEXT,
                title TEXT,
                rule_json TEXT,
                status TEXT DEFAULT 'active',
                created_at TEXT,
                updated_at TEXT,
                is_active INTEGER DEFAULT 1
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def valuation_learning_save_suggestion_from_case(case, case_id=None, db_path=VALUATION_LEARNING_DB):
    """把一體化輸入框中的自我學習素材存為待確認規則草稿。"""
    case = case or {}
    raw_import = case.get("raw_import") or (case.get("raw") or {}).get("raw_import") or {}
    if not isinstance(raw_import, dict):
        return None
    self_learning = raw_import.get("self_learning") or raw_import.get("analyzer_self_learning") or {}
    if not isinstance(self_learning, dict) or not any(self_learning.get(k) for k in ["possible_app_errors", "correct_judgement", "suggested_rules", "raw_section"]):
        return None
    valuation_learning_init_db(db_path)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    title = "；".join((self_learning.get("suggested_rules") or [])[:2]) or "AI Core 一體化自我學習草稿"
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO analyzer_learning_suggestions (
                stock_id, stock_name, industry_family, case_id, suggestion_type, scope, title,
                content_json, status, created_at, updated_at, is_active
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)
            """,
            (
                str(case.get("stock_id") or ""),
                str(case.get("stock_name") or ""),
                str(case.get("industry_family") or ""),
                case_id,
                "ai_core_integrated_rule_draft",
                str(self_learning.get("scope") or self_learning.get("generalizable") or "待確認"),
                title[:200],
                _nick_json_dumps(self_learning),
                "pending",
                now,
                now,
            ),
        )
        conn.commit()
        return cur.lastrowid
    finally:
        conn.close()


