def valuation_learning_confirm_suggestion_to_formal_rule(suggestion_id, db_path=VALUATION_LEARNING_DB):
    """v271.8：把『待確認規則草稿』經 Nick 手動確認後，寫入正式規則庫。
    注意：正式規則庫只保存已確認的通用規則，不自動改核心演算法；後續模組可明確讀取 active rules。
    """
    valuation_learning_init_db(db_path)
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        cur = conn.cursor()
        cur.execute("SELECT * FROM analyzer_learning_suggestions WHERE id=? AND is_active=1", (int(suggestion_id),))
        row = cur.fetchone()
        if not row:
            return False, "找不到這筆待確認規則草稿。"
        d = dict(row)
        content = _nick_json_loads(d.get("content_json"), {})
        title = d.get("title") or "AI Core 已確認通用規則"
        # 避免同一草稿重複寫入。
        cur.execute("SELECT id FROM analyzer_formal_rules WHERE suggestion_id=? AND is_active=1 LIMIT 1", (int(suggestion_id),))
        existed = cur.fetchone()
        if existed:
            cur.execute("UPDATE analyzer_learning_suggestions SET status=?, updated_at=? WHERE id=?", ("approved", now, int(suggestion_id)))
            conn.commit()
            return True, f"這筆草稿已在正式規則庫中（rule_id={existed['id']}）。"
        cur.execute(
            """
            INSERT INTO analyzer_formal_rules (
                suggestion_id, stock_id, stock_name, industry_family, scope, title,
                rule_json, status, created_at, updated_at, is_active
            ) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, 1)
            """,
            (
                int(suggestion_id),
                d.get("stock_id") or "",
                d.get("stock_name") or "",
                d.get("industry_family") or "",
                d.get("scope") or (content.get("scope") if isinstance(content, dict) else "") or "待確認",
                str(title)[:200],
                _nick_json_dumps(content),
                now,
                now,
            ),
        )
        rule_id = cur.lastrowid
        cur.execute("UPDATE analyzer_learning_suggestions SET status=?, updated_at=? WHERE id=?", ("approved", now, int(suggestion_id)))
        conn.commit()
        return True, f"已確認並寫入正式規則庫（rule_id={rule_id}）。"
    except Exception as e:
        return False, f"寫入正式規則庫失敗：{e}"
    finally:
        conn.close()


