_nick_v2716_base_ai_core_parser = _nick_parse_ai_core_text_to_case_fields

def _nick_parse_ai_core_text_to_case_fields(raw_text, default_subfamily="", default_source="manual_text"):
    """v271.6：支援 AI Core 一體化輸入框。
    同一段文字可同時解析：估值/Core、交易快照、分析器自我學習、同族群案例標籤。
    """
    raw_text = str(raw_text or "")
    parsed = _nick_v2716_base_ai_core_parser(raw_text, default_subfamily=default_subfamily, default_source=default_source)
    if not raw_text.strip() or not nick_v2716_is_integrated_input(raw_text):
        return parsed

    core_ai = nick_v2714_extract_label_value(raw_text, ["AI Core"])
    core_plain = nick_v2714_extract_label_value(raw_text, ["Core"])
    core_type = nick_v2714_extract_label_value(raw_text, ["Core 類型", "forensic_core_type"])
    rerating = nick_v2714_extract_label_value(raw_text, ["估值重評狀態", "forensic_rerating_status", "估值重評"])

    eps = parsed.get("eps_assumption") or {}
    for k, labels in {
        "bear": ["EPS 保守"],
        "base": ["EPS 中性", "EPS 假設"],
        "bull": ["EPS 樂觀"],
        "failure": ["EPS 失敗", "EPS 下修"],
    }.items():
        val = nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, labels))
        if str(val or "").strip():
            eps[k] = val

    pe = parsed.get("pe_assumption") or {}
    for k, labels in {
        "bear": ["PE 保守"],
        "base": ["PE 中性"],
        "bull": ["PE 樂觀"],
        "rerating": ["PE 重評上緣", "PE 重評", "重評 PE"],
        "failure": ["PE 失敗", "PE 下修"],
    }.items():
        val = nick_v2714_clean_num(nick_v2714_extract_label_value(raw_text, labels))
        if str(val or "").strip():
            pe[k] = val

    zones = parsed.get("valuation_zones") or {}
    zmap = {
        "fundamental_support": ["基本面支撐區", "forensic_value_floor"],
        "rerating_fair_zone": ["重評合理區", "forensic_re_rating_zone"],
        "failure_downside_zone": ["驗證失敗下修區", "forensic_fail_zone"],
    }
    for k, labels in zmap.items():
        val = nick_v2714_clean_range(nick_v2714_extract_label_value(raw_text, labels))
        if str(val or "").strip():
            zones[k] = val

    trade_plan = parsed.get("trade_plan") or {}
    trade_plan.update(nick_v247_extract_trade_plan_from_text(raw_text) or {})

    self_learning = nick_v2716_parse_self_learning(raw_text)
    peer_tags = nick_v2716_parse_peer_case_tags(raw_text)
    # 若有同族群標籤，優先用子族群輔助沉澱模組；價位仍不得跨標的硬套。
    subfamily = peer_tags.get("subsector") or core_type or parsed.get("subfamily") or default_subfamily or ""
    industry_family_hint = peer_tags.get("sector") or ""

    validation_text = nick_v2714_extract_label_value(raw_text, ["驗證條件", "買後續抱條件", "重新法醫條件"])
    limit_text = nick_v2714_extract_label_value(raw_text, ["限制條件", "最大反方證據", "買錯條件"])
    limitations = list(parsed.get("limitations") or [])
    limitations += _nick_split_condition_text(limit_text)
    limitations = list(dict.fromkeys([x for x in limitations if str(x or "").strip()]))

    structural = {
        "forensic_snapshot_date": nick_v2714_extract_label_value(raw_text, ["報告日期", "forensic_snapshot_date"]),
        "data_basis_date": nick_v2714_extract_label_value(raw_text, ["資料基準日"]),
        "ai_core": core_ai,
        "core": core_plain,
        "core_type": core_type,
        "rerating_status": rerating,
        "report_verdict": nick_v2714_extract_label_value(raw_text, ["財報裁決"]),
        "report_verdict_type": nick_v2714_extract_label_value(raw_text, ["財報部分通過類型"]),
        "treasury_level": nick_v2714_extract_label_value(raw_text, ["財報金庫"]),
        "financial_quality": nick_v2714_extract_label_value(raw_text, ["法醫財務品質"]),
        "attack": nick_v2714_extract_label_value(raw_text, ["Attack"]),
        "attack_type": nick_v2714_extract_label_value(raw_text, ["Attack 類型"]),
        "observe_small_lot": nick_v2714_extract_label_value(raw_text, ["是否觀察型小倉"]),
        "focus": nick_v2714_extract_label_value(raw_text, ["Focus"]),
        "final_action": nick_v2714_extract_label_value(raw_text, ["最終動作"]),
    }

    parsed.update({
        "core_verdict": core_plain or core_ai or parsed.get("core_verdict") or "",
        "rerating_verdict": rerating or parsed.get("rerating_verdict") or "",
        "core_type": core_type or parsed.get("core_type") or default_subfamily or "",
        "subfamily": subfamily,
        "source": "manual_integrated_v68" if "一體化" in raw_text or "v6.8" in raw_text else (parsed.get("source") or "manual_text"),
        "eps_assumption": {k: v for k, v in eps.items() if str(v or "").strip()},
        "pe_assumption": {k: v for k, v in pe.items() if str(v or "").strip()},
        "valuation_zones": {k: v for k, v in zones.items() if str(v or "").strip()},
        "trade_plan": trade_plan,
        "validation_rules": {
            **(parsed.get("validation_rules") or {"valid_days": 90}),
            "conditions_text": validation_text or (parsed.get("validation_rules") or {}).get("conditions_text", ""),
            "conditions": _nick_split_condition_text(validation_text) or (parsed.get("validation_rules") or {}).get("conditions", []),
        },
        "limitations": limitations,
    })
    raw_imp = parsed.get("raw_import") or {}
    if not isinstance(raw_imp, dict):
        raw_imp = {}
    raw_imp.update({
        "pasted_text": raw_text,
        "parsed_by": "nick_ai_core_integrated_parser_v2716",
        "forensic_v67_detected": True,
        "integrated_v68_detected": bool("一體化" in raw_text or "v6.8" in raw_text),
        "forensic_structural_params": {k: v for k, v in structural.items() if str(v or "").strip()},
        "forensic_trade_snapshot": {k: v for k, v in (trade_plan or {}).items() if str(v or "").strip()},
        "self_learning": self_learning,
        "peer_case_tags": peer_tags,
        "industry_family_hint": industry_family_hint,
        "snapshot_lifecycle_note": "EPS/PE/估值區是地形；交易快照是天氣，APP每日重算。自我學習素材只存待確認草稿，不自動改正式規則。",
    })
    parsed["raw_import"] = raw_imp
    return parsed


_nick_v2716_base_current_run_parser = nick_v2714_build_forensic_v67_case

def nick_v2714_build_forensic_v67_case(raw_text, stock_id="", stock_name="", industry_category=""):
    """v271.6：補充證據也可直接貼 AI Core 一體化輸入框。"""
    raw_text = str(raw_text or "").strip()
    if not raw_text:
        return None
    if not nick_v2716_is_integrated_input(raw_text):
        return _nick_v2716_base_current_run_parser(raw_text, stock_id=stock_id, stock_name=stock_name, industry_category=industry_category)
    parsed = _nick_parse_ai_core_text_to_case_fields(raw_text, default_subfamily=str(industry_category or ""), default_source="manual_integrated_v68_current_run")
    if not parsed:
        return None
    # 沒有任何估值/Core重點就不套用
    if not any(str(v or "").strip() for v in [parsed.get("core_verdict"), parsed.get("core_type"), parsed.get("rerating_verdict")] + list((parsed.get("valuation_zones") or {}).values())):
        return None
    now_txt = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    raw_imp = parsed.get("raw_import") or {}
    return {
        "stock_id": str(stock_id or ""),
        "stock_name": str(stock_name or ""),
        "industry_family": str((raw_imp.get("peer_case_tags") or {}).get("sector") or industry_category or ""),
        "model_key": "forensic_integrated_v68_current_run",
        "subfamily": parsed.get("subfamily") or parsed.get("core_type") or str(industry_category or ""),
        "source": "forensic_integrated_v68_current_run",
        "core_verdict": parsed.get("core_verdict") or "",
        "ai_core": (raw_imp.get("forensic_structural_params") or {}).get("ai_core", ""),
        "core_type": parsed.get("core_type") or "",
        "rerating_verdict": parsed.get("rerating_verdict") or "",
        "eps_assumption": parsed.get("eps_assumption") or {},
        "pe_assumption": parsed.get("pe_assumption") or {},
        "valuation_zones": parsed.get("valuation_zones") or {},
        "trade_plan": parsed.get("trade_plan") or {},
        "validation_rules": parsed.get("validation_rules") or {"valid_days": 90},
        "limitations": parsed.get("limitations") or [],
        "created_at": now_txt,
        "updated_at": now_txt,
        "raw": {"raw_import": raw_imp},
    }


def nick_v2738_learning_scope_badge(content, row=None):
    """v273.8｜把 v6.8 自我學習素材轉成清楚的適用範圍標籤。"""
    content = content if isinstance(content, dict) else {}
    row = row if isinstance(row, dict) else {}
    scope = str(row.get("scope") or content.get("scope") or content.get("generalizable") or "待確認").strip()
    if not scope:
        scope = "待確認"
    if "全市場" in scope:
        return "全市場｜需最高審查"
    if "同族群" in scope:
        return "同族群｜可萃取"
    if "同型態" in scope:
        return "同型態｜可萃取"
    if "只限本檔" in scope or "No" in scope:
        return "只限本檔｜不得泛化"
    return scope


def nick_v2738_learning_risk_flag(content):
    """v273.8｜防止單一個股硬改。只做顯示提醒，不自動改正式規則。"""
    content = content if isinstance(content, dict) else {}
    scope = str(content.get("scope") or content.get("generalizable") or "")
    rules = " ".join([str(x or "") for x in (content.get("suggested_rules") or [])])
    raw = str(content.get("raw_section") or "")
    txt = f"{scope} {rules} {raw}"
    if "只限本檔" in txt:
        return "高｜只限本檔，不得寫入通用規則"
    if "全市場" in txt:
        return "高｜全市場規則需人工二次審查"
    if "不針對單一個股硬改" in txt:
        return "低｜已附防硬改提醒"
    if "同族群" in txt or "同型態" in txt:
        return "中｜僅限相同族群 / 型態"
    return "中｜需補適用範圍"


def valuation_learning_suggestion_counts(rows):
    counts = {"pending": 0, "approved": 0, "ignored": 0}
    for r in rows or []:
        s = str((r or {}).get("status") or "pending")
        if s not in counts:
            counts[s] = 0
        counts[s] += 1
    return counts


def render_v2716_learning_suggestions_box(stock_id=None):
    """v273.8｜Rule Pending Zone。

    目的：
    1. v6.8 第三段「分析器自我學習」只進待確認區，不自動改模型。
    2. Nick 手動確認後才寫入正式規則庫。
    3. 前台清楚顯示：適用範圍、硬改風險、APP 可能判錯、建議通用規則、驗收標準。
    """
    try:
        rows_current = valuation_learning_list_suggestions(stock_id=stock_id, limit=20) if stock_id else []
        rows_all = valuation_learning_list_suggestions(stock_id=None, limit=60)
    except Exception as e:
        st.caption(f"自我學習草稿讀取略過：{e}")
        return

    # 若在個股頁，預設先看本檔；也提供全域待審查摘要。
    rows = rows_current if stock_id and rows_current else rows_all
    if not rows:
        st.caption("尚無自我學習草稿；若一體化輸入框含【三、分析器自我學習】，儲存後會出現在這裡。")
        return

    st.markdown("### 🧠 待確認規則｜估值學習")
    st.caption(
        "這裡只保存『APP 可能判錯 / 正確應該怎麼判 / 建議通用規則』。"
        "草稿不會自動改正式規則，必須手動確認才會寫入正式規則庫。"
    )

    counts_all = valuation_learning_suggestion_counts(rows_all)
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("待確認", counts_all.get("pending", 0))
    c2.metric("已確認", counts_all.get("approved", 0))
    c3.metric("已略過", counts_all.get("ignored", 0))
    c4.metric("本檔草稿", len(rows_current) if stock_id else 0)

    show_rows = []
    for r in rows:
        c = r.get("content") or {}
        status_raw = str(r.get("status") or "pending")
        status_label = "已寫入正式規則庫" if status_raw == "approved" else ("已忽略" if status_raw == "ignored" else "待確認")
        suggested = "；".join((c.get("suggested_rules") or [])[:2]) or r.get("title") or "—"
        app_err = "；".join((c.get("possible_app_errors") or [])[:2]) or "—"
        show_rows.append({
            "ID": r.get("id"),
            "狀態": status_label,
            "股票": f"{r.get('stock_name') or ''} {r.get('stock_id') or ''}".strip() or "—",
            "適用範圍": nick_v2738_learning_scope_badge(c, r),
            "硬改風險": nick_v2738_learning_risk_flag(c),
            "規則草稿": suggested,
            "APP可能判錯": app_err,
            "建立時間": r.get("created_at"),
        })

    st.dataframe(pd.DataFrame(show_rows), use_container_width=True, hide_index=True)

    pending_rows = [r for r in rows if str(r.get("status") or "pending") == "pending"]
    if pending_rows:
        st.markdown("#### ✅ 待確認規則審查")
        st.caption("確認前請先看『適用範圍』與『硬改風險』。全市場規則、只限本檔規則，請不要直接泛化。")
        for r in pending_rows[:8]:
            c = r.get("content") or {}
            sid = r.get("id")
            title = "；".join((c.get("suggested_rules") or [])[:2]) or r.get("title") or "待確認規則草稿"
            risk = nick_v2738_learning_risk_flag(c)
            scope_badge = nick_v2738_learning_scope_badge(c, r)
            with st.expander(f"待確認 #{sid}｜{scope_badge}｜{title[:34]}", expanded=False):
                st.markdown(f"**目前狀態：待確認**｜**硬改風險：{risk}**")
                st.caption("此規則尚未寫入正式規則庫，不會影響 APP 正式判斷。")
                if c.get("possible_app_errors"):
                    st.markdown("**APP 可能判錯：**\n" + "\n".join([f"- {x}" for x in c.get("possible_app_errors", [])[:8]]))
                if c.get("correct_judgement"):
                    st.markdown("**正確應該怎麼判：**\n" + "\n".join([f"- {x}" for x in c.get("correct_judgement", [])[:8]]))
                if c.get("suggested_rules"):
                    st.markdown("**建議通用規則：**\n" + "\n".join([f"- {x}" for x in c.get("suggested_rules", [])[:8]]))
                if c.get("guardrails"):
                    st.markdown("**不可硬改提醒 / 防呆：**\n" + "\n".join([f"- {x}" for x in c.get("guardrails", [])[:8]]))
                if c.get("acceptance_criteria"):
                    st.markdown("**驗收標準：**\n" + "\n".join([f"- {x}" for x in c.get("acceptance_criteria", [])[:8]]))
                if c.get("raw_section"):
                    with st.expander("查看原始第三段文字", expanded=False):
                        st.text_area("raw_section", value=str(c.get("raw_section") or ""), height=220, disabled=True, key=f"raw_learning_{sid}")

                c1, c2 = st.columns(2)
                if c1.button("✅ 確認寫入正式規則庫", key=f"approve_learning_rule_{sid}", use_container_width=True, type="primary"):
                    # v273.8｜硬防呆：只限本檔的草稿不要誤寫為通用規則。
                    if "只限本檔" in str(scope_badge) or "只限本檔" in str(risk):
                        st.error("此草稿標示為只限本檔，請先改寫成同族群/同型態規則後再確認。")
                    else:
                        ok, msg = valuation_learning_confirm_suggestion_to_formal_rule(sid)
                        if ok:
                            st.success(msg)
                            st.rerun()
                        else:
                            st.error(msg)
                if c2.button("略過 / 不寫入", key=f"ignore_learning_rule_{sid}", use_container_width=True):
                    try:
                        valuation_learning_update_suggestion_status(sid, status="ignored")
                        st.success("已標記略過，不會寫入正式規則庫。")
                        st.rerun()
                    except Exception as e:
                        st.error(f"標記略過失敗：{e}")

    try:
        formal_rules = valuation_learning_list_formal_rules(limit=20)
    except Exception:
        formal_rules = []
    if formal_rules:
        with st.expander("📚 已確認正式規則庫｜最近 20 筆", expanded=False):
            fr_rows = []
            for r in formal_rules:
                c = r.get("content") or {}
                fr_rows.append({
                    "ID": r.get("id"),
                    "來源草稿": r.get("suggestion_id"),
                    "股票": f"{r.get('stock_name') or ''} {r.get('stock_id') or ''}".strip() or "—",
                    "適用範圍": r.get("scope") or c.get("scope") or "—",
                    "正式規則": "；".join((c.get("suggested_rules") or [])[:2]) or r.get("title") or "—",
                    "寫入時間": r.get("created_at"),
                })
            st.dataframe(pd.DataFrame(fr_rows), use_container_width=True, hide_index=True)
            st.caption("正式規則庫目前只做『人工確認後的規則素材庫』，不會自動覆蓋 Core / Attack / Focus 主裁決。")



# =========================================================
# v271.8｜final_verdict_payload：前台裁決統一出口
# 原則：法醫結構參數＝估值地形；法醫交易快照＝報告當下參考；APP 今日防線每天動態重算。
# =========================================================
def nick_v2718_price_relation_to_zones(price, support_txt="", rerating_txt="", fail_txt=""):
    try:
        ref = None
        if isinstance(price, dict):
            ref = to_float(price.get("realtime_price") or price.get("close") or price.get("last"))
        else:
            ref = to_float(price)
        if ref is None:
            return "需搭配今日價格判斷"
        sr = valuation_learning_parse_range(support_txt)
        rr = valuation_learning_parse_range(rerating_txt)
        fr = valuation_learning_parse_range(fail_txt)
        if rr:
            lo, hi = rr
            if lo <= ref <= hi:
                return "重評合理區"
            if ref > hi:
                return "高於重評區"
        if sr:
            lo, hi = sr
            if lo <= ref <= hi:
                return "基本面支撐區"
            if ref > hi:
                return "高於基本面支撐區"
            if ref < lo:
                return "低於基本面支撐區"
        if fr:
            lo, hi = fr
            if ref <= hi:
                return "驗證失敗下修區附近"
        return "需動態校正"
    except Exception:
        return "需動態校正"


def nick_v2718_build_final_verdict_payload(a, case=None, price=None, current_zone="", buy_zone_summary=None, sr_levels=None):
    """建立所有前台共用的 final_verdict_payload。
    不做單一個股硬改；只把已套用法醫結構參數的標的統一成同一口徑。
    """
    a = a or {}
    case = case if isinstance(case, dict) else (a.get("_ai_core_saved_case") if isinstance(a.get("_ai_core_saved_case"), dict) else {})
    fin_j = a.get("fin_j") if isinstance(a.get("fin_j"), dict) else {}
    rr_j = a.get("rerating") if isinstance(a.get("rerating"), dict) else {}
    buy_zone_summary = buy_zone_summary if isinstance(buy_zone_summary, dict) else {}
    sr_levels = sr_levels if isinstance(sr_levels, dict) else {}
    has_forensic = valuation_learning_has_usable_case(case) and nick_v2715_is_v67(case)
    v = nick_v2715_case_verdict(case) if has_forensic else {}
    zones = (case or {}).get("valuation_zones") if isinstance(case, dict) else {}
    zones = zones if isinstance(zones, dict) else {}
    trade_snapshot = nick_v2715_trade_snapshot(case) if has_forensic else {}
    core = nick_v2715_norm_yes_no(v.get("core")) or str(a.get("core") or "").strip()
    attack_snapshot = nick_v2715_norm_yes_no(v.get("attack_snapshot")) or ""
    focus_snapshot = nick_v2715_norm_yes_no(v.get("focus_snapshot")) or ""
    report = v.get("report") or fin_j.get("report") or "資料不足"
    report_type = v.get("report_type") or fin_j.get("report_type") or ""
    rerating = v.get("rerating") or rr_j.get("verdict") or rr_j.get("rerating_verdict") or "資料不足"
    treasury = v.get("treasury") or fin_j.get("treasury") or "資料不足"
    fin_quality = v.get("financial_quality") or fin_j.get("forensic_financial_quality") or fin_j.get("financial_quality") or fin_j.get("quality") or "資料不足"
    support_zone = zones.get("fundamental_support") or ""
    rerating_zone = zones.get("rerating_fair_zone") or ""
    fail_zone = zones.get("failure_downside_zone") or ""
    relation = nick_v2718_price_relation_to_zones(price, support_zone, rerating_zone, fail_zone) if has_forensic else (current_zone or "資料不足")

    recommended_action = str(a.get("action") or "只觀察")
    recommended_reason = str(a.get("why") or "")
    grade = str(a.get("grade") or "")
    if has_forensic:
        # B交易限制型：公司可收編，但前台一致顯示交易受限，不顯示成 公司體質未通過。
        is_trade_limited = ("B" in report_type) or ("交易限制" in report_type) or ("部分" in report)
        if core == "Yes" and is_trade_limited:
            recommended_action = "等回檔 / 建立追蹤"
            recommended_reason = "Core 代表公司可追蹤收編，但財報仍需營收、EPS、毛利率與現金流接棒；現價能否動手看 APP 今日動態防線。"
            grade = "C" if grade not in ["A", "B+", "B", "C+"] else grade
        elif core == "Yes" and recommended_action in ["不買", "只觀察", "暫不操作"]:
            recommended_action = "等回檔 / 建立追蹤"
            recommended_reason = "公司已通過法醫收編；現價仍需買點、籌碼與風報比確認。"
            grade = "C" if not grade or grade in ["D", "E", "?"] else grade
        if ("C" in report_type and "核心疑慮" in report_type) or "不通過" in report:
            recommended_action = "只觀察"
            recommended_reason = "法醫財報/核心疑慮未解除，APP 不允許用題材硬追。"
            grade = "D"

        # v273.1｜Core 同步防呆：
        # 若法醫結構已明確 Core Yes，前面舊 action engine 仍留下「Core 未正式通過 / Core 未過」等語意，
        # 必須在 final_verdict_payload 內先洗乾淨，避免總裁決卡與 Core / 金庫卡互打。
        _reason_txt_for_sync = str(recommended_reason or "")
        _action_txt_for_sync = str(recommended_action or "")
        _core_mismatch_words = ["Core 未正式通過", "Core未正式通過", "Core 未過", "Core未過", "未正式通過"]
        if core == "Yes" and any(_w in _reason_txt_for_sync for _w in _core_mismatch_words):
            if any(_w in _action_txt_for_sync for _w in ["攻擊觀察", "小倉", "不追高"]):
                recommended_action = "回檔小倉 / 不追高"
            elif _action_txt_for_sync in ["", "不買", "只觀察", "暫不操作"]:
                recommended_action = "等回檔 / 建立追蹤"
            recommended_reason = (
                "公司已通過法醫收編；但今日能否動手仍由 APP 動態防線、"
                "買點、籌碼與風報比決定，不等於現價可重押。"
            )

    # v273.2｜前台語意清潔：財報通過時不要再顯示「通過｜不適用」這種半成品語意。
    _report_badge = ""
    try:
        _report_clean = str(report or "").strip()
        _report_type_clean = str(report_type or "").strip()
        if _report_clean:
            if _report_type_clean and _report_type_clean not in ["不適用", "None", "none", "-", "—"]:
                _report_badge = f"財報{_report_clean}｜{_report_type_clean}"
            else:
                _report_badge = f"財報{_report_clean}"
    except Exception:
        _report_badge = str(report or "").strip()

    payload = {
        "version": "v273.2",
        "source": "forensic_v67_v68_structural" if has_forensic else "app_dynamic",
        "structural_applied": bool(has_forensic),
        "forensic_structure_applied": bool(has_forensic),
        "forensic_trade_snapshot_reference_only": bool(has_forensic and trade_snapshot),
        "today_dynamic_defense": True,
        "core": core,
        "core_type": v.get("core_type") or a.get("core_status") or "",
        "attack": str(a.get("attack") or ""),
        "attack_snapshot": attack_snapshot,
        "focus": str(a.get("focus") or ""),
        "focus_snapshot": focus_snapshot,
        "report": report,
        "report_type": report_type,
        "treasury": treasury,
        "financial_quality": fin_quality,
        "rerating": rerating,
        "recommended_action": recommended_action,
        "recommended_reason": recommended_reason,
        "grade": grade or str(a.get("grade") or ""),
        "valuation": {
            "support_zone": support_zone,
            "rerating_zone": rerating_zone,
            "fail_zone": fail_zone,
            "price_relation": relation,
        },
        "trade_snapshot": trade_snapshot,
        "dynamic_defense": {
            "buy_main": buy_zone_summary.get("main") or "",
            "buy_condition": buy_zone_summary.get("condition") or "",
            "support_text": sr_levels.get("support_text") or "",
            "pressure_text": sr_levels.get("pressure_text") or "",
            "summary": sr_levels.get("summary") or "",
        },
        "badges": [x for x in [
            "已套用法醫結構參數" if has_forensic else "APP動態裁決",
            "法醫交易快照僅供參考" if has_forensic and trade_snapshot else "",
            "今日防線由APP動態重算",
            _report_badge,
        ] if x],
        "frontend_note": "法醫給估值地形；APP 今天看交易天氣，不把快照價位當永久聖旨。" if has_forensic else "APP 使用即時資料、Nick撐壓、均線、籌碼與財報動態判斷。",
    }
    return payload


def nick_v2718_apply_final_verdict_payload(a, payload):
    """把 final_verdict_payload 寫回 a，讓前台舊區塊也讀同一口徑。"""
    if not isinstance(a, dict) or not isinstance(payload, dict) or not payload:
        return a
    a["final_verdict_payload"] = payload
    a["_final_verdict_payload"] = payload
    if payload.get("structural_applied"):
        # v273.1｜final_verdict_payload 是前台共同出口：
        # 除了 Core / Focus，也要把推薦動作與原因同步回 a，避免總裁決卡仍讀舊 action / why。
        _sync_action = str(payload.get("recommended_action") or "").strip()
        _sync_reason = str(payload.get("recommended_reason") or "").strip()
        if _sync_action:
            a["action"] = _sync_action
            a["final_action"] = _sync_action
        if _sync_reason:
            a["why"] = _sync_reason
            a["final_reason"] = _sync_reason
        if payload.get("core"):
            a["core"] = payload.get("core")
            a["_forensic_core_effective"] = payload.get("core")
        if payload.get("core_type"):
            a["core_status"] = payload.get("core_type")
        # v271.8.2｜Focus 是最終集中火力裁決；若法醫結構/快照明確 No，前台不得翻成「觀察名單」。
        _focus_eff = str(payload.get("focus_snapshot") or payload.get("focus") or "").strip()
        if _focus_eff:
            if re.search(r"\bNo\b", _focus_eff, flags=re.I) or "No" in _focus_eff or "否" in _focus_eff:
                a["focus"] = "No"
                a["focus_display"] = "No"
            elif re.search(r"\bYes\b", _focus_eff, flags=re.I) or "Yes" in _focus_eff or "是" in _focus_eff:
                a["focus"] = "Yes"
                a["focus_display"] = "Yes"
        fj = a.get("fin_j") if isinstance(a.get("fin_j"), dict) else {}
        for src_key, dst_key in [
            ("report", "report"),
            ("report_type", "report_type"),
            ("treasury", "treasury"),
            ("financial_quality", "forensic_financial_quality"),
        ]:
            val = payload.get(src_key)
            if val not in [None, "", "資料不足"]:
                fj[dst_key] = val
        if payload.get("financial_quality") not in [None, "", "資料不足"]:
            fj["financial_quality"] = payload.get("financial_quality")
        # 高品質但交易限制，不再讓前台誤寫成財務品質惡化。
        if payload.get("financial_quality") == "高" and ("部分" in str(payload.get("report")) or "B" in str(payload.get("report_type")) or "交易限制" in str(payload.get("report_type"))):
            radar = fj.get("financial_radar") if isinstance(fj.get("financial_radar"), dict) else {}
            radar["summary"] = "高品質｜交易限制"
            radar["quick"] = "公司體質高，但本次財報只算部分通過；後續營收、EPS、毛利率與現金流要接棒。"
            fj["financial_radar"] = radar
        a["fin_j"] = fj
        rr = a.get("rerating") if isinstance(a.get("rerating"), dict) else {}
        if payload.get("rerating") not in [None, "", "資料不足"]:
            rr["verdict"] = payload.get("rerating")
            rr["forensic_text"] = payload.get("rerating")
        a["rerating"] = rr
        if payload.get("recommended_action"):
            a["action"] = payload.get("recommended_action")
        if payload.get("recommended_reason"):
            a["why"] = payload.get("recommended_reason")
        if payload.get("grade"):
            a["grade"] = payload.get("grade")
    return a


