    with st.expander("🧠 估值學習區 🔒", expanded=False):
        if not nick_private_gate("估值學習區", f"ai_valuation_zone_{stock}"):
            return latest
        st.markdown("### 🧠 估值學習區")
        st.caption("這裡是進階估值資料與手動回填區；一般使用者只看主畫面的結果即可。")

