def twse_tick_size(price):
    p = to_float(price)
    if p is None or p <= 0:
        return None
    if p < 10:
        return 0.01
    if p < 50:
        return 0.05
    if p < 100:
        return 0.1
    if p < 500:
        return 0.5
    if p < 1000:
        return 1
    return 5


def round_price_to_tick(price, mode="nearest"):
    p = to_float(price)
    if p is None or p <= 0:
        return None
    tick = twse_tick_size(p)
    if tick is None:
        return None
    d_p = Decimal(str(p))
    d_t = Decimal(str(tick))
    q = d_p / d_t
    if mode == "ceil":
        units = q.to_integral_value(rounding=ROUND_CEILING)
    elif mode == "floor":
        units = q.to_integral_value(rounding=ROUND_FLOOR)
    else:
        units = q.to_integral_value(rounding=ROUND_HALF_UP)
    return float(units * d_t)


def _price_decimals(price):
    tick = twse_tick_size(price)
    if tick is None:
        return 2
    if tick >= 1:
        return 0
    if tick >= 0.1:
        return 1
    return 2


def fmt_price(x, mode="nearest"):
    p = round_price_to_tick(x, mode)
    if p is None:
        return "無資料"
    d = _price_decimals(p)
    s = f"{p:,.{d}f}"
    if d == 1 and s.endswith(".0"):
        s = s[:-2]
    return s


def price_range_text(low, high, low_mode="ceil", high_mode="floor"):
    lo = round_price_to_tick(low, low_mode)
    hi = round_price_to_tick(high, high_mode)
    if lo is None or hi is None:
        return "無法推估"
    if lo > hi:
        lo = round_price_to_tick(low, "nearest")
        hi = round_price_to_tick(high, "nearest")
    return f"{fmt_price(lo)} ～ {fmt_price(hi)}"


def rng(r):
    if not r or r[0] is None or r[1] is None:
        return "無法推估"
    return f"{fmt(r[0])} ～ {fmt(r[1])}"


def rng_price(r, low_mode="ceil", high_mode="floor"):
    if not r or r[0] is None or r[1] is None:
        return "無法推估"
    return price_range_text(r[0], r[1], low_mode=low_mode, high_mode=high_mode)


def calc_range(eps, pe_range):
    eps = to_float(eps)
    if eps is None or eps <= 0 or not pe_range:
        return None
    return (eps * pe_range[0], eps * pe_range[1])


def clean_text(x):
    if x is None:
        return ""
    return str(x).strip()


