def get_model_key(stock, industry_category=None):
    stock = str(stock).strip()
    industry_category = clean_text(industry_category)
    if stock in STOCK_MODEL_MAP:
        return STOCK_MODEL_MAP[stock]
    if industry_category:
        if industry_category in INDUSTRY_MODEL_MAP:
            return INDUSTRY_MODEL_MAP[industry_category]
        for key, model_key in INDUSTRY_MODEL_MAP.items():
            if key and key in industry_category:
                return model_key
    if stock.startswith(("28", "58")):
        return "financial"
    if stock.startswith("25"):
        return "asset_construction"
    return "default"


def get_model_source(stock, industry_category=None):
    stock = str(stock).strip()
    industry_category = clean_text(industry_category)
    if stock in STOCK_MODEL_MAP:
        return "個股白名單"
    if industry_category:
        if industry_category in INDUSTRY_MODEL_MAP:
            return "產業類別"
        for key in INDUSTRY_MODEL_MAP:
            if key and key in industry_category:
                return "產業類別"
    if stock.startswith(("28", "58", "25")):
        return "代號 fallback"
    return "default"


def _fingerprint_model_key(initial_key, industry_category, fj):
    """若初始模型為 default，根據財務特徵 fingerprint 嘗試升級到高品質成長模型。
    回傳 (refined_key, source_label)。"""
    if initial_key != "default" or not fj:
        return initial_key, ("產業 / 白名單" if initial_key != "default" else "default")
    fq = fj.get("financial_quality", "")
    treasury = fj.get("treasury", "")
    ts = float(fj.get("treasury_score", 0) or 0)
    eps_s = fj.get("eps", "")
    cashflow = fj.get("cashflow", "")
    rte = fj.get("revenue_to_eps", "")
    margin = fj.get("margin", "")
    is_hq = (
        fq == "高"
        and treasury in ["金庫級", "候選級"]
        and ts >= 8
        and eps_s != "沒有"
        and cashflow in ["有", "普通"]
        and rte in ["有", "部分有"]
        and margin in ["有", "普通"]
    )
    if not is_hq:
        return "default", "default"
    ic = clean_text(industry_category)
    _optical = ["通信網路", "光通訊", "光電", "光纖", "光模組"]
    _precision = ["電子零組件", "電機機械"]
    _pcb = ["電路板", "線路板", "CCL"]
    _highspeed_material = ["高階材料", "高速材料", "銅箔基板", "HDI", "mSAP", "低損耗材料", "高頻材料"]
    _power = ["電力", "電源"]
    if any(k in ic for k in _optical):
        # 通信網路 / 網通 / 高速交換器類，優先用 AI 網通強成長模型；
        # 光通訊個股若已有白名單會在 get_model_key 階段先命中 optical_ai_datacenter。
        return "ai_network_switch_growth", "財務特徵 fingerprint"
    if any(k in ic for k in _precision):
        return "precision_component_growth", "財務特徵 fingerprint"
    if any(k in ic for k in _highspeed_material):
        return "ai_highspeed_materials", "財務特徵 fingerprint"
    if any(k in ic for k in _pcb):
        return "ai_pcb_ccl", "財務特徵 fingerprint"
    if any(k in ic for k in _power):
        return "ai_power_premium", "財務特徵 fingerprint"
    return "growth_premium", "財務特徵 fingerprint"


def _no_change_result(model_key, reason=""):
    """Helper: 回傳「不切換」結果。"""
    return {
        "selected_model_key": model_key,
        "original_model_key": model_key,
        "model_changed": False,
        "model_confidence": "高",
        "model_reason": reason,
        "anomalies": [],
        "beginner_message": "",
        "original_model_name": MODEL_CONFIG.get(model_key, {}).get("name", model_key),
        "selected_model_name": MODEL_CONFIG.get(model_key, {}).get("name", model_key),
    }


def auto_select_valuation_model(
    stock, industry_category, price, fj, fin, val, current_model_key
):
    """
    根據估值異常、產業類別、財務 fingerprint 自動評估是否需要切換估值模型。

    防呆規則：
    - 不可只因現價高就切換
    - 必須同時有產業或財務特徵證據（至少一種）
    - 結構性特殊模型（金融、通路、景氣循環等）不做升級
    - 個股白名單已指定者不做切換
    - 每次最多切換一次（only one re-run）

    回傳：
    {
        "selected_model_key":  str,
        "original_model_key":  str,
        "model_changed":       bool,
        "model_confidence":    "高" / "中" / "低",
        "model_reason":        str,
        "anomalies":           list[str],
        "beginner_message":    str,
        "original_model_name": str,
        "selected_model_name": str,
    }
    """
    original_key = current_model_key
    ic = clean_text(industry_category)

    # ── 防呆 1：個股白名單已手動指定，不做自動切換 ──────────────
    if stock in STOCK_MODEL_MAP:
        return _no_change_result(
            original_key, "個股白名單已明確指定模型，系統不做自動切換"
        )

    # ── 防呆 2：結構性特殊模型不可升級（避免誤給高 PE）──────────
    _LOCKED_MODELS = {
        "semi_leader",
        "financial",
        "dividend_utility",
        "asset_construction",
        "real_estate_delivery_recognition",
        "cyclical_material",
        "distributor",
        "low_margin_assembly",
        "turnaround",
    }
    _LOCKED_MODELS.update({
        "mature_foundry",
        "semicap_equipment_material",
        "abf_substrate",
        "abf_bt_substrate_cycle",
        "ai_server_pcb_core",
        "pcb_drill_consumables",
        "general_pcb_hdi_candidate",
        "thermal_liquid_cooling",
        "advanced_packaging_osat",
        "connector_highspeed",
        "memory_storage",
        "power_grid_equipment",
        "robotics_automation",
        "ip_asic_design",
        "cybersecurity_software",
        "biotech_healthcare",
        "shipping_logistics",
        "tourism_consumption",
        "green_energy_storage",
        "defensive_cashflow_treasury",
    })
    if original_key in _LOCKED_MODELS:
        return _no_change_result(
            original_key,
            f"產業模型（{original_key}）屬結構性特殊分類，不做自動升級以避免高估風險",
        )

    # ── 估值異常偵測 ─────────────────────────────────────────────
    anomalies = []
    if val.get("ok"):
        implied_future_pe = val.get("implied_future_pe")
        model_high_pe = val.get("model_high_pe")
        mp_range = val.get("market_premium")
        close = price.get("close") if price else None

        if (
            implied_future_pe
            and model_high_pe
            and implied_future_pe > model_high_pe * 1.5
        ):
            anomalies.append(
                f"現價隱含 PE（{implied_future_pe:.1f}x）超出模型最高 PE（{model_high_pe:.0f}x）的 1.5 倍"
            )
        if close and mp_range and mp_range[1] and close > mp_range[1] * 1.5:
            anomalies.append(f"現價（{fmt_price(close)}）高於模型最高估值區間 50% 以上")
        if original_key == "default" and fj:
            _fq = fj.get("financial_quality", "")
            _ts2 = float(fj.get("treasury_score", 0) or 0)
            if _fq == "高" and _ts2 >= 8:
                anomalies.append("原模型為 default，但財報品質高、成長動能強")
        if (
            val.get("pe_status")
            in [
                "市場給價超出模型，需人工校正產業 PE",
                "市場給高溢價，已高於一般重評區",
            ]
            and fj
            and fj.get("financial_quality") == "高"
            and fj.get("growth_quality") == "通過"
        ):
            anomalies.append("系統偵測到市場溢價，但財報品質與成長動能明顯強")

    # 無異常且非 default → 無需切換
    if not anomalies and original_key != "default":
        return _no_change_result(original_key, "目前模型無明顯估值異常，維持原模型")

    # ── 財務特徵 fingerprint ─────────────────────────────────────
    if not fj:
        return {
            "selected_model_key": original_key,
            "original_model_key": original_key,
            "model_changed": False,
            "model_confidence": "低",
            "model_reason": "財報資料不足，無法評估是否切換模型",
            "anomalies": anomalies,
            "beginner_message": "系統判斷：財報資料不足，估值請保守看待。",
            "original_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
            "selected_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
        }

    fq = fj.get("financial_quality", "")
    treasury = fj.get("treasury", "")
    ts_val = float(fj.get("treasury_score", 0) or 0)
    eps_s = fj.get("eps", "")
    cashflow = fj.get("cashflow", "")
    rte = fj.get("revenue_to_eps", "")
    margin_s = fj.get("margin", "")

    is_hq_fp = (
        fq == "高"
        and treasury in ["金庫級", "候選級"]
        and ts_val >= 8
        and eps_s != "沒有"
        and cashflow in ["有", "普通"]
        and rte in ["有", "部分有"]
        and margin_s in ["有", "普通"]
    )

    rev_yoy = to_float(fin.get("revenue_yoy") if fin else None)
    eps_yoy = to_float(fin.get("eps_yoy") if fin else None)
    gm = to_float(fin.get("gross_margin") if fin else None)
    op_m = to_float(fin.get("operating_margin") if fin else None)

    strong_growth = (rev_yoy is not None and rev_yoy > 20) or (
        eps_yoy is not None and eps_yoy > 20
    )
    good_margin = (gm is not None and gm >= 25) or (op_m is not None and op_m >= 10)

    # ── 產業關鍵字 → 目標模型 ────────────────────────────────────
    _optical_kws = [
        "通信網路",
        "光通訊",
        "光電",
        "光纖",
        "光模組",
        "網通",
        "資料中心",
        "高速傳輸",
    ]
    _precision_kws = ["電子零組件", "其他電子", "精密零組件", "機構件", "滑軌"]
    _highspeed_material_kws = ["高階材料", "高速材料", "CCL", "銅箔基板", "HDI", "mSAP", "低損耗材料", "高頻材料"]
    _pcb_kws = ["電路板", "線路板"]
    _power_kws = ["電力", "電源", "重電", "電力設備"]
    _ic_kws = ["半導體業", "IC設計", "IC 設計"]

    industry_target = None
    industry_evidence = False

    if any(k in ic for k in _optical_kws):
        # AI 網通 / 資料中心相關，先給高速交換器強成長模型；若資料不足會在後續防呆維持原模型。
        industry_target, industry_evidence = "ai_network_switch_growth", True
    elif any(k in ic for k in _precision_kws) and good_margin:
        industry_target, industry_evidence = "precision_component_growth", True
    elif any(k in ic for k in _highspeed_material_kws):
        industry_target, industry_evidence = "ai_highspeed_materials", True
    elif any(k in ic for k in _pcb_kws):
        industry_target, industry_evidence = "ai_pcb_ccl", True
    elif any(k in ic for k in _power_kws):
        industry_target, industry_evidence = "ai_power_premium", True
    elif any(k in ic for k in _ic_kws) and is_hq_fp:
        industry_target, industry_evidence = "ic_design_large", True
    elif is_hq_fp and strong_growth and good_margin:
        industry_target, industry_evidence = "growth_premium", False

    # ── 防呆 3：必須有至少一種明確證據 ──────────────────────────
    has_evidence = industry_evidence or (is_hq_fp and strong_growth)
    if not has_evidence:
        return {
            "selected_model_key": original_key,
            "original_model_key": original_key,
            "model_changed": False,
            "model_confidence": "低",
            "model_reason": "估值異常，但無足夠的產業或財務特徵證據支持切換，維持保守估值",
            "anomalies": anomalies,
            "beginner_message": "系統判斷：目前資料不足以改用其他模型，估值請保守看待。\n建議以法人共識目標價與技術位置輔助判斷。",
            "original_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
            "selected_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
        }

    if industry_target is None:
        industry_target = "growth_premium"

    # ── 防呆 4：目標模型 PE 上限需高於當前模型 ───────────────────
    curr_max = (MODEL_CONFIG.get(original_key) or {}).get("market_premium", (0, 0))[1]
    targ_max = (MODEL_CONFIG.get(industry_target) or {}).get("market_premium", (0, 0))[
        1
    ]
    if targ_max <= curr_max and original_key != "default":
        return _no_change_result(
            original_key,
            f"目標模型 PE 上限（{targ_max}x）不高於當前模型（{curr_max}x），不做切換",
        )

    # ── 信心評分 ─────────────────────────────────────────────────
    if industry_evidence and is_hq_fp and strong_growth:
        confidence = "高"
    elif industry_evidence and is_hq_fp:
        confidence = "中"
    elif is_hq_fp and strong_growth and good_margin:
        confidence = "中"
    else:
        confidence = "低"

    if confidence == "低":
        return {
            "selected_model_key": original_key,
            "original_model_key": original_key,
            "model_changed": False,
            "model_confidence": "低",
            "model_reason": "有部分證據但信心不足，維持原模型保守估值，不強行切換",
            "anomalies": anomalies,
            "beginner_message": "系統判斷：目前資料不足以改用其他模型，估值請保守看待。\n建議以法人共識目標價與技術位置輔助判斷。",
            "original_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
            "selected_model_name": MODEL_CONFIG.get(original_key, {}).get(
                "name", original_key
            ),
        }

    # ── 組建切換理由 ─────────────────────────────────────────────
    targ_name = MODEL_CONFIG.get(industry_target, {}).get("name", industry_target)
    orig_name = MODEL_CONFIG.get(original_key, {}).get("name", original_key)

    evidence_parts = []
    if industry_evidence:
        evidence_parts.append(f"產業類別（{ic}）符合「{targ_name}」模型適用範圍")
    if is_hq_fp:
        evidence_parts.append(
            f"財務特徵達高品質成長標準（金庫分 {ts_val:.0f}/12、現金流支撐、EPS 有轉換）"
        )
    if strong_growth:
        g_parts = []
        if rev_yoy is not None and rev_yoy > 20:
            g_parts.append(f"月營收年增 {rev_yoy:.1f}%")
        if eps_yoy is not None and eps_yoy > 20:
            g_parts.append(f"EPS 年增 {eps_yoy:.1f}%")
        if g_parts:
            evidence_parts.append(f"成長動能強：{'、'.join(g_parts)}")

    reason_lines = ["【切換依據】"] + [f"• {p}" for p in evidence_parts]
    if anomalies:
        reason_lines += ["【觸發原因】"] + [f"• {x}" for x in anomalies]

    return {
        "selected_model_key": industry_target,
        "original_model_key": original_key,
        "model_changed": True,
        "model_confidence": confidence,
        "model_reason": "\n".join(reason_lines),
        "anomalies": anomalies,
        "beginner_message": (
            f"系統判斷：原本模型（{orig_name}）可能太保守，"
            f"已自動改用較適合的估值模型（{targ_name}）。"
        ),
        "original_model_name": orig_name,
        "selected_model_name": targ_name,
    }


def get_model(stock, industry_category=None):
    return MODEL_CONFIG[get_model_key(stock, industry_category)]


def investor_display_name(x):
    return INVESTOR_NAME_MAP.get(str(x), str(x))


@st.cache_data(ttl=3600, show_spinner=False)
def fm(dataset, stock_id=None, start=None, end=None):
    try:
        params = {"dataset": dataset}
        if stock_id is not None:
            params["data_id"] = stock_id
        if start is not None:
            params["start_date"] = start
        if end is not None:
            params["end_date"] = end
        r = requests.get(API_URL, params=params, timeout=25, headers=_nick_finmind_headers())
        if r.status_code != 200:
            return pd.DataFrame(), f"HTTP {r.status_code}"
        js = r.json()
        df = pd.DataFrame(js.get("data", []))
        if df.empty:
            return pd.DataFrame(), "查無資料"
        return df, ""
    except Exception as e:
        return pd.DataFrame(), str(e)


@st.cache_data(ttl=86400, show_spinner=False)
def fetch_stock_info():
    try:
        r = requests.get(API_URL, params={"dataset": "TaiwanStockInfo"}, timeout=25, headers=_nick_finmind_headers())
        if r.status_code != 200:
            return pd.DataFrame(), f"HTTP {r.status_code}"
        js = r.json()
        df = pd.DataFrame(js.get("data", []))
        if df.empty:
            return pd.DataFrame(), "查無股票基本資料"
        for c in ["stock_id", "stock_name"]:
            if c not in df.columns:
                return pd.DataFrame(), f"股票基本資料缺欄位：{c}"
        if "industry_category" not in df.columns:
            df["industry_category"] = ""
        if "type" not in df.columns:
            df["type"] = ""
        df["stock_id"] = df["stock_id"].astype(str).str.strip()
        df["stock_name"] = df["stock_name"].astype(str).str.strip()
        df["industry_category"] = df["industry_category"].astype(str).str.strip()
        df["type"] = df["type"].astype(str).str.strip()
        return df, ""
    except Exception as e:
        return pd.DataFrame(), str(e)


def stock_row_to_meta(row):
    return {
        "stock_id": clean_text(row.get("stock_id")),
        "stock_name": clean_text(row.get("stock_name")),
        "industry_category": clean_text(row.get("industry_category")),
        "type": clean_text(row.get("type")),
    }


def search_stock_by_name(stock_info_df, name_query):
    if stock_info_df is None or stock_info_df.empty or not clean_text(name_query):
        return pd.DataFrame()
    q = clean_text(name_query)
    exact = stock_info_df[stock_info_df["stock_name"] == q]
    if not exact.empty:
        return exact
    return stock_info_df[
        stock_info_df["stock_name"].str.contains(q, na=False, regex=False)
    ].head(30)


def resolve_stock_inputs(
    stock_code_raw, stock_name_raw, stock_info_df, selected_meta=None
):
    if selected_meta:
        return selected_meta, "使用選單指定的股票。"
    code = clean_text(stock_code_raw)
    name = clean_text(stock_name_raw)
    if stock_info_df is not None and not stock_info_df.empty:
        if code:
            exact = stock_info_df[stock_info_df["stock_id"] == code]
            if not exact.empty:
                return stock_row_to_meta(
                    exact.iloc[0]
                ), "代號已自動帶入股票名稱與產業類別。"
            by_name = search_stock_by_name(stock_info_df, code)
            if len(by_name) == 1:
                return stock_row_to_meta(
                    by_name.iloc[0]
                ), "你在代號欄輸入了名稱，系統已自動轉成股票代號。"
        if name:
            matches = search_stock_by_name(stock_info_df, name)
            if len(matches) == 1:
                return stock_row_to_meta(
                    matches.iloc[0]
                ), "名稱已自動帶入股票代號與產業類別。"
            if len(matches) > 1:
                exact = matches[matches["stock_name"] == name]
                if not exact.empty:
                    return stock_row_to_meta(
                        exact.iloc[0]
                    ), "名稱完全符合，已自動帶入股票代號與產業類別。"
                return stock_row_to_meta(
                    matches.iloc[0]
                ), "找到多筆近似名稱，系統先採第一筆；建議用選單確認。"
    if code:
        return {
            "stock_id": code,
            "stock_name": name if name else code,
            "industry_category": "",
            "type": "",
        }, "股票基本資料未取得，先用輸入代號分析。"
    return None, "請輸入股票代號或股票名稱。"


DEFAULT_HOT_STOCKS = [
    ("2330", "台積電"),
    ("2383", "台光電"),
    ("2059", "川湖"),
    ("2317", "鴻海"),
    ("2454", "聯發科"),
]

HOT_HISTORY_PATH = "hot_stocks.json"


def load_hot_history():
    try:
        if _os.path.exists(HOT_HISTORY_PATH):
            with open(HOT_HISTORY_PATH, "r", encoding="utf-8") as f:
                return _json.load(f)
    except Exception:
        pass
    return {}


def save_hot_history(history):
    try:
        with open(HOT_HISTORY_PATH, "w", encoding="utf-8") as f:
            _json.dump(history, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def update_recent_search_history(stock_code, stock_name):
    """v271.3｜記錄近期搜尋標的。

    這裡只記「最近搜尋/帶入」時間，不增加熱門次數。
    用途：首頁右側按鈕改成「近期搜尋」，不再用固定熱門池。
    """
    if not stock_code:
        return
    history = load_hot_history()
    code = str(stock_code).strip()
    name = str(stock_name).strip() if stock_name else code
    now_txt = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if code not in history or not isinstance(history.get(code), dict):
        history[code] = {"name": name, "count": 0, "last_analyzed": "", "last_searched": ""}
    history[code]["name"] = name
    history[code]["last_searched"] = now_txt
    # 保留舊欄位相容，不讓既有 hot_stocks.json 壞掉。
    history[code].setdefault("count", 0)
    history[code].setdefault("last_analyzed", "")
    save_hot_history(history)


def update_hot_history(stock_code, stock_name):
    """分析成功後記錄分析次數；同時更新近期搜尋時間。"""
    if not stock_code:
        return
    history = load_hot_history()
    code = str(stock_code).strip()
    name = str(stock_name).strip() if stock_name else code
    now_txt = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if code not in history or not isinstance(history.get(code), dict):
        history[code] = {"name": name, "count": 0, "last_analyzed": "", "last_searched": ""}
    history[code]["name"] = name
    history[code]["count"] = int(history[code].get("count", 0)) + 1
    history[code]["last_analyzed"] = now_txt
    history[code]["last_searched"] = now_txt
    save_hot_history(history)


def get_dynamic_hot_stocks(limit=5):
    """v271.3｜改為回傳近期搜尋標的，不再用熱門次數排序。"""
    history = load_hot_history()
    if not history:
        return []
    normalized = []
    for code, data in (history or {}).items():
        if not isinstance(data, dict):
            continue
        ts = str(data.get("last_searched") or data.get("last_analyzed") or "")
        if not ts:
            continue
        normalized.append((str(code), data, ts))
    items = sorted(normalized, key=lambda x: x[2], reverse=True)
    return [(code, data.get("name", code)) for code, data, _ts in items[:limit]]


def select_hot_stock(code, name):
    st.session_state["stock_code_input"] = code
    st.session_state["stock_name_input"] = name
    st.session_state["auto_run_hot_stock"] = True


def select_scan_candidate(code, name):
    """選股雷達優先候選：一鍵帶入並直接跳單檔分析。"""
    code = str(code or "").strip()
    name = str(name or "").strip()
    if not code:
        return
    st.session_state["stock_code_input"] = code
    st.session_state["stock_name_input"] = name
    st.session_state["holding_cost_input"] = ""
    st.session_state["auto_run_hot_stock"] = True


def parse_stock_label_to_code_name(label):
    """把『南電 8046』或『8046 南電』轉成 code/name。"""
    s = str(label or "").strip()
    m = re.search(r"(?<!\d)(\d{4})(?!\d)", s)
    if not m:
        return "", s
    code = m.group(1)
    name = s.replace(code, "").strip(" ｜|")
    if not name:
        name = _hot_stock_name_from_code(code)
    return code, name


def save_last_radar_candidates(df_top, strategy="", pool_label=""):
    """保存上次雷達優先候選，方便分析完一檔後接著切下一檔。"""
    items = []
    try:
        for _, r in df_top.iterrows():
            label = str(r.get("股票", "") or "")
            code, name = parse_stock_label_to_code_name(label)
            if not code:
                continue
            items.append({
                "code": code,
                "name": name,
                "label": label,
                "category": str(r.get("分類", "—")),
                "attack": str(r.get("攻擊機會", "—")),
                "buy_score": str(r.get("買點分", "—")),
                "action": str(r.get("目前動作", "—")),
            })
    except Exception:
        items = []

    if items:
        st.session_state["last_radar_candidates"] = items
        st.session_state["last_radar_strategy"] = str(strategy or "")
        st.session_state["last_radar_pool"] = str(pool_label or "")
        st.session_state["last_radar_saved_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def clear_last_radar_candidates():
    st.session_state.pop("last_radar_candidates", None)
    st.session_state.pop("last_radar_strategy", None)
    st.session_state.pop("last_radar_pool", None)
    st.session_state.pop("last_radar_saved_at", None)


def render_last_radar_candidates(current_code=""):
    """在單檔分析頁保留上一批雷達候選，方便連續切換分析。"""
    items = st.session_state.get("last_radar_candidates") or []
    if not items:
        return

    current_code = str(current_code or "").strip()
    strategy = st.session_state.get("last_radar_strategy", "")
    pool = st.session_state.get("last_radar_pool", "")
    saved_at = st.session_state.get("last_radar_saved_at", "")

    with st.expander("🧭 上次雷達候選｜可直接切下一檔", expanded=False):
        meta_parts = []
        if strategy:
            meta_parts.append(f"策略：{strategy}")
        if pool:
            meta_parts.append(f"股池：{pool}")
        if saved_at:
            meta_parts.append(f"時間：{saved_at}")
        if meta_parts:
            st.caption("｜".join(meta_parts))

        for idx, item in enumerate(items):
            code = str(item.get("code", "")).strip()
            name = str(item.get("name", "")).strip()
            label = str(item.get("label", "")).strip() or f"{name} {code}".strip()
            line = (
                f"**{label}**｜{item.get('category', '—')}｜"
                f"{item.get('attack', '—')}｜買點分 {item.get('buy_score', '—')}"
            )
            if code == current_code:
                st.markdown(f"✅ 目前分析中：{line}")
            else:
                st.markdown(line)
                st.button(
                    f"🔍 分析 {label}",
                    key=f"last_radar_candidate_{code}_{idx}",
                    use_container_width=True,
                    on_click=select_scan_candidate,
                    args=(code, name),
                )

        st.button(
            "清除上次雷達候選",
            key="clear_last_radar_candidates",
            use_container_width=True,
            on_click=clear_last_radar_candidates,
        )


def _hot_stock_name_from_code(code):
    code = str(code or "").strip()
    if not code:
        return ""
    try:
        history = load_hot_history()
        if code in history and history[code].get("name"):
            return str(history[code].get("name"))
    except Exception:
        pass
    for _c, _n in DEFAULT_HOT_STOCKS:
        if str(_c) == code:
            return _n
    return code


def handle_hot_stock_query():
    """保留相容舊版 query param；新版熱門標的已改回原生按鈕，避免手機整頁跳轉閃爍。"""
    try:
        code = st.query_params.get("hot_stock", "")
        if isinstance(code, list):
            code = code[0] if code else ""
        code = str(code or "").strip()
        if not code:
            return
        st.session_state["stock_code_input"] = code
        st.session_state["stock_name_input"] = _hot_stock_name_from_code(code)
        st.session_state["auto_run_hot_stock"] = True
        try:
            st.query_params.clear()
        except Exception:
            pass
    except Exception:
        pass


def render_hot_stock_pills(limit=4):
    """v271.3｜近期搜尋原生按鈕版。

    放在輸入區右欄，最多4個；點選後直接帶入並自動分析。
    """
    recent = get_dynamic_hot_stocks(limit=limit)
    st.markdown('<div class="hot-mini-title">近期搜尋</div>', unsafe_allow_html=True)
    if not recent:
        st.caption("尚無近期搜尋；分析過的標的會出現在這裡。")
        return
    for code, name in recent[:limit]:
        label = str(name or code)
        st.button(
            label,
            key=f"recent_native_{code}",
            use_container_width=True,
            on_click=select_hot_stock,
            args=(str(code), label),
        )


