import json as _json
import os as _os
import concurrent.futures as _cf


def load_watchlist():
    try:
        if _os.path.exists(WATCHLIST_PATH):
            with open(WATCHLIST_PATH, "r", encoding="utf-8") as f:
                data = _json.load(f)
                if isinstance(data, list):
                    return data
    except Exception:
        pass
    return []


def save_watchlist(wl):
    try:
        with open(WATCHLIST_PATH, "w", encoding="utf-8") as f:
            _json.dump(wl, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def watchlist_add(code, name):
    wl = load_watchlist()
    for item in wl:
        if item.get("code") == code:
            item["name"] = name
            save_watchlist(wl)
            return
    wl.append({"code": code, "name": name})
    save_watchlist(wl)


def watchlist_remove(code):
    wl = load_watchlist()
    wl = [item for item in wl if item.get("code") != code]
    save_watchlist(wl)


def watchlist_load_callback(code, name):
    st.session_state["stock_code_input"] = code
    st.session_state["stock_name_input"] = name
    st.session_state["autofill_msg"] = f"已從觀察清單載入：{code}｜{name}"


