def save_analysis_snapshot(stock_id, stock_name, a, current_zone):
    history = load_analysis_history()
    plan = a.get("plan", {})
    fj = a.get("fin_j", {})
    rr = a.get("rerating", {})
    snapshot = {
        "stock_id": stock_id,
        "stock_name": stock_name,
        "analysis_time": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "action": a.get("action", ""),
        "grade": a.get("grade", ""),
        "core": a.get("core", ""),
        "core_status": a.get("core_status", ""),
        "attack": a.get("attack", ""),
        "focus": a.get("focus", ""),
        "trend_status": a.get("trend", {}).get("status", ""),
        "fin_report": fj.get("report", ""),
        "fin_quality": fj.get("financial_quality", ""),
        "growth_quality": fj.get("growth_quality", ""),
        "treasury": fj.get("treasury", ""),
        "rerating_verdict": rr.get("verdict", ""),
        "valuation_zone": current_zone,
        "price_status": a.get("price_status", ""),
        "short_target": plan.get("short", ""),
        "wave_target": plan.get("wave", ""),
        "wrong_point": plan.get("wrong", ""),
        "stop_point": plan.get("stop", ""),
    }
    history[stock_id] = snapshot
    try:
        with open(HISTORY_PATH, "w", encoding="utf-8") as f:
            _json.dump(history, f, ensure_ascii=False, indent=2)
    except Exception:
        pass
    return snapshot


def compare_snapshots(prev, curr):
    WATCH = [
        ("action", "最終動作"),
        ("grade", "交易分級"),
        ("core", "Core"),
        ("core_status", "Core 狀態"),
        ("attack", "Attack"),
        ("focus", "Focus"),
        ("trend_status", "趨勢變化"),
        ("fin_report", "財報裁決"),
        ("fin_quality", "財務品質"),
        ("growth_quality", "成長品質"),
        ("treasury", "金庫等級"),
        ("rerating_verdict", "估值重評"),
        ("valuation_zone", "估值區間"),
        ("price_status", "股價位置"),
        ("short_target", "短線目標"),
        ("wave_target", "波段目標"),
        ("wrong_point", "短線認錯"),
        ("stop_point", "波段認錯"),
    ]
    changes = []
    for field, label in WATCH:
        p = str(prev.get(field, "")).strip()
        c = str(curr.get(field, "")).strip()
        if p and c and p != c:
            changes.append((label, p, c))
    return changes



