TRACKING_PATH = "nick_tracking_list.json"
REJECT_REVIEW_PATH = "nick_reject_review.json"
VALUATION_VERSION_PATH = "nick_valuation_versions.json"


def _nick_json_load(path, default):
    try:
        if _os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = _json.load(f)
                return data if data is not None else default
    except Exception:
        pass
    return default


def _nick_json_save(path, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            _json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def nick_load_tracking_list():
    data = _nick_json_load(TRACKING_PATH, {})
    return data if isinstance(data, dict) else {}


def nick_save_tracking_list(data):
    if not isinstance(data, dict):
        data = {}
    _nick_json_save(TRACKING_PATH, data)


def nick_tracking_entry_from_analysis(stock, name, a, price, current_zone, status="觀察中", memo=""):
    plan = a.get("plan", {}) if isinstance(a, dict) else {}
    fj = a.get("fin_j", {}) if isinstance(a, dict) else {}
    rr = a.get("rerating", {}) if isinstance(a, dict) else {}
    px = None
    try:
        px = to_float((price or {}).get("close"))
    except Exception:
        px = None
    return {
        "stock_id": str(stock),
        "stock_name": str(name or stock),
        "status": status,
        "memo": memo,
        "added_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "last_price": px,
        "action": a.get("action", "") if isinstance(a, dict) else "",
        "grade": a.get("grade", "") if isinstance(a, dict) else "",
        "core": a.get("core", "") if isinstance(a, dict) else "",
        "core_status": a.get("core_status", "") if isinstance(a, dict) else "",
        "attack": a.get("attack", "") if isinstance(a, dict) else "",
        "focus": a.get("focus", "") if isinstance(a, dict) else "",
        "fin_report": fj.get("report", ""),
        "rerating": rr.get("verdict", ""),
        "valuation_zone": str(current_zone or ""),
        "buy_zone": plan.get("buy", ""),
        "watch_zone": plan.get("watch", ""),
        "wrong_point": plan.get("wrong", ""),
        "stop_point": plan.get("stop", ""),
        "short_target": plan.get("short", ""),
        "wave_target": plan.get("wave", ""),
    }


def nick_upsert_tracking_entry(entry):
    data = nick_load_tracking_list()
    code = str(entry.get("stock_id", "")).strip()
    if not code:
        return
    old = data.get(code, {}) if isinstance(data.get(code), dict) else {}
    merged = dict(old)
    merged.update(entry)
    # 保留第一次加入時間
    if old.get("added_at"):
        merged["added_at"] = old.get("added_at")
    data[code] = merged
    nick_save_tracking_list(data)


def nick_remove_tracking_entry(stock):
    data = nick_load_tracking_list()
    data.pop(str(stock), None)
    nick_save_tracking_list(data)


def nick_build_buy_after_tracking_alerts(entry, a, price):
    alerts = []
    ok = []
    if not isinstance(entry, dict):
        return alerts, ok
    px_now = None
    try:
        px_now = to_float((price or {}).get("close"))
    except Exception:
        pass
    stop = to_float(entry.get("stop_point"))
    wrong = to_float(entry.get("wrong_point"))
    if px_now is not None and stop is not None and px_now < stop:
        alerts.append(f"跌破波段失效點 {stop:g}，原始持有劇本需重新檢查。")
    elif px_now is not None and wrong is not None and px_now < wrong:
        alerts.append(f"跌破短線認錯點 {wrong:g}，觀察型小倉應先降級。")
    fj_now = (a.get("fin_j") or {}).get("report", "") if isinstance(a, dict) else ""
    fj_old = str(entry.get("fin_report", ""))
    if fj_old == "通過" and fj_now in ["部分通過", "不通過"]:
        alerts.append(f"財報裁決由 {fj_old} 轉為 {fj_now}，買進理由已弱化。")
    rr_now = (a.get("rerating") or {}).get("verdict", "") if isinstance(a, dict) else ""
    rr_old = str(entry.get("rerating", ""))
    if rr_old in ["成立", "部分成立"] and rr_now == "不成立":
        alerts.append("估值重評由成立/部分成立轉為不成立，需下修期待。")
    action = str(a.get("action", "") if isinstance(a, dict) else "")
    if any(x in action for x in ["減碼", "出清", "不買"]):
        alerts.append(f"目前最終動作為「{action}」，與持有/觀察狀態不一致。")
    if not alerts:
        ok.append("原始劇本尚未出現重大失效訊號。")
    if px_now is not None:
        tgt = to_float(entry.get("short_target"))
        if tgt is not None and px_now >= tgt:
            ok.append(f"目前價格已接近或達到短線目標 {tgt:g}，可評估分批獲利。")
    return alerts, ok


def nick_load_reject_review():
    data = _nick_json_load(REJECT_REVIEW_PATH, {})
    return data if isinstance(data, dict) else {}


def nick_save_reject_review(data):
    _nick_json_save(REJECT_REVIEW_PATH, data if isinstance(data, dict) else {})


def nick_update_and_render_reject_review(stock, name, a, price):
    data = nick_load_reject_review()
    code = str(stock)
    px = None
    try:
        px = to_float((price or {}).get("close"))
    except Exception:
        pass
    action = str(a.get("action", "") if isinstance(a, dict) else "")
    old = data.get(code) if isinstance(data.get(code), dict) else None
    # 先顯示復盤提醒，再更新本次資料。
    if old and px is not None and to_float(old.get("price")):
        old_px = to_float(old.get("price"))
        gain = (px / old_px - 1) * 100 if old_px else None
        if gain is not None and gain >= 15:
            st.warning(
                f"拒絕後強漲復盤：{name} {code} 上次「{old.get('action','只觀察')}」後，股價約 +{gain:.1f}%。請檢查是否漏判 Attack、估值重評或族群資金擴散。"
            )
    if any(x in action for x in ["只觀察", "不買", "暫不操作", "放棄"]):
        data[code] = {
            "stock_id": code,
            "stock_name": str(name or code),
            "price": px,
            "action": action,
            "grade": a.get("grade", "") if isinstance(a, dict) else "",
            "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
            "core": a.get("core", "") if isinstance(a, dict) else "",
            "attack": a.get("attack", "") if isinstance(a, dict) else "",
            "rerating": (a.get("rerating") or {}).get("verdict", "") if isinstance(a, dict) else "",
        }
        nick_save_reject_review(data)


def nick_classify_sector_stage(a, industry_category=""):
    trend = str((a.get("trend") or {}).get("status", ""))
    action = str(a.get("action", ""))
    rr = str((a.get("rerating") or {}).get("verdict", ""))
    attack = str(a.get("attack", ""))
    focus = str(a.get("focus", ""))
    core = str(a.get("core", ""))
    reasons = []
    if focus == "Yes":
        stage = "主升期"
        reasons.append("主攻成立，代表 Core + Attack + 風報比條件較完整。")
    elif attack == "Yes" and rr in ["成立", "部分成立"]:
        stage = "擴散期 / 攻擊期"
        reasons.append("短線攻擊條件成立，且有估值重評線索。")
    elif core == "Yes" and any(x in action for x in ["等回檔", "小倉", "觀察"]):
        stage = "擴散期 / 等買點"
        reasons.append("公司可收編，但交易位置尚未到主攻甜點。")
    elif "候選" in str(a.get("core_status", "")) or rr == "部分成立":
        stage = "啟動期 / 轉機觀察"
        reasons.append("已出現劇本轉強，但仍需財報或籌碼驗證。")
    elif any(x in trend for x in ["轉弱", "反轉", "空頭"]):
        stage = "退潮期"
        reasons.append("趨勢轉弱，先降低進場積極度。")
    else:
        stage = "觀察期"
        reasons.append("尚未看到足夠同向證據，先觀察族群與財報接棒。")
    if industry_category:
        reasons.append(f"產業類別：{industry_category}。")
    return stage, reasons[:3]


def nick_same_sector_peers(stock, industry_category, stock_info_df, limit=8):
    try:
        if stock_info_df is None or getattr(stock_info_df, "empty", True) or not industry_category:
            return []
        df = stock_info_df.copy()
        # FinMind / TWSE 基本資料欄名不一定固定，盡量用模糊欄位。
        cols = list(df.columns)
        id_col = next((c for c in cols if c.lower() in ["stock_id", "code", "證券代號"] or "stock_id" in c.lower()), None)
        name_col = next((c for c in cols if c.lower() in ["stock_name", "name", "證券名稱"] or "stock_name" in c.lower()), None)
        ind_col = next((c for c in cols if "industry" in c.lower() or "產業" in c or "類別" in c), None)
        if not id_col or not ind_col:
            return []
        work = df[df[ind_col].astype(str) == str(industry_category)].copy()
        out = []
        for _, row in work.iterrows():
            code = str(row.get(id_col, "")).strip()
            if not code or clean_stock_id(code) == clean_stock_id(stock):
                continue
            nm = str(row.get(name_col, code)).strip() if name_col else code
            out.append(f"{nm} {clean_stock_id(code)}")
            if len(out) >= limit:
                break
        return out
    except Exception:
        return []


def nick_extract_valuation_version_case(a):
    case = a.get("_ai_core_saved_case") if isinstance(a, dict) else None
    if not isinstance(case, dict) or not case:
        return None
    return {
        "saved_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "ai_core": case.get("ai_core") or case.get("core_verdict") or case.get("core"),
        "rerating": case.get("rerating") or case.get("rerating_verdict"),
        "core_type": case.get("core_type"),
        "eps_bear": case.get("eps_bear"),
        "eps_base": case.get("eps_base"),
        "eps_bull": case.get("eps_bull"),
        "pe_base_low": case.get("pe_base_low"),
        "pe_base_high": case.get("pe_base_high"),
        "pe_rerating_low": case.get("pe_rerating_low"),
        "pe_rerating_high": case.get("pe_rerating_high"),
        "support_low": case.get("support_low"),
        "support_high": case.get("support_high"),
        "rerating_low": case.get("rerating_low"),
        "rerating_high": case.get("rerating_high"),
        "failure_low": case.get("failure_low"),
        "failure_high": case.get("failure_high"),
    }


def nick_save_valuation_version(stock, name, a):
    case = nick_extract_valuation_version_case(a)
    if not case:
        return
    data = _nick_json_load(VALUATION_VERSION_PATH, {})
    if not isinstance(data, dict):
        data = {}
    code = str(stock)
    arr = data.get(code, [])
    if not isinstance(arr, list):
        arr = []
    # 若最後一筆核心區間相同，不重複塞。
    fingerprint = _json.dumps({k: case.get(k) for k in case if k != "saved_at"}, ensure_ascii=False, sort_keys=True)
    last_fp = _json.dumps({k: arr[-1].get(k) for k in arr[-1] if k != "saved_at"}, ensure_ascii=False, sort_keys=True) if arr else ""
    if fingerprint != last_fp:
        case["stock_id"] = code
        case["stock_name"] = str(name or code)
        arr.append(case)
        data[code] = arr[-10:]
        _nick_json_save(VALUATION_VERSION_PATH, data)


def nick_load_valuation_versions(stock):
    data = _nick_json_load(VALUATION_VERSION_PATH, {})
    if isinstance(data, dict):
        return data.get(str(stock), []) if isinstance(data.get(str(stock), []), list) else []
    return []


# =========================
# 快速判讀
# =========================
def _tw_today_date():
    """用台灣時間取得今天日期，避免 Replit / 伺服器時區不是台灣。"""
    try:
        return (datetime.utcnow() + timedelta(hours=8)).date()
    except Exception:
        return datetime.today().date()


def _date_label_md(d):
    try:
        ts = pd.to_datetime(d, errors="coerce")
        if pd.isna(ts):
            return ""
        return ts.strftime("%m/%d")
    except Exception:
        return ""


def _daily_close_rows(price):
    """從日 K 取得日期與收盤價，不依賴資料源何時更新。"""
    try:
        raw = price.get("raw") if isinstance(price, dict) else None
        if raw is None or getattr(raw, "empty", True):
            return pd.DataFrame()
        df = raw.copy()
        if "date" not in df.columns or "close" not in df.columns:
            return pd.DataFrame()
        df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.date
        df["close"] = pd.to_numeric(df["close"], errors="coerce")
        df = df.dropna(subset=["date", "close"]).sort_values("date").reset_index(drop=True)
        return df[["date", "close"]]
    except Exception:
        return pd.DataFrame()


def build_date_price_context(price, realtime_quote=None):
    """價格顯示與比較基準的唯一入口。

    核心原則：
    1. 不猜資料源幾點更新。
    2. 收盤價一律用 date 對齊抓。
    3. 即時價與日 K 分開處理。
    4. 比較基準 = 分析日期以前，最近一個交易日收盤價。
    """

    df = _daily_close_rows(price)
    rt_price = to_float((realtime_quote or {}).get("price"))
    rt_time = str((realtime_quote or {}).get("time", "") or "")
    qdate_raw = (realtime_quote or {}).get("date")
    qdate = pd.to_datetime(qdate_raw, errors="coerce")
    if not pd.isna(qdate):
        analysis_date = qdate.date()
    else:
        analysis_date = _tw_today_date()

    today_close = None
    today_close_date = analysis_date
    base_close = None
    base_date = None
    latest_close = to_float(price.get("close")) if isinstance(price, dict) else None
    latest_date = None
    prev_latest_close = None
    prev_latest_date = None

    if not df.empty:
        same_day = df[df["date"] == analysis_date]
        if not same_day.empty:
            today_close = to_float(same_day.iloc[-1]["close"])
            today_close_date = same_day.iloc[-1]["date"]

        before = df[df["date"] < analysis_date]
        if not before.empty:
            base_close = to_float(before.iloc[-1]["close"])
            base_date = before.iloc[-1]["date"]

        latest = df.iloc[-1]
        latest_close = to_float(latest["close"])
        latest_date = latest["date"]
        if len(df) >= 2:
            prev_latest = df.iloc[-2]
            prev_latest_close = to_float(prev_latest["close"])
            prev_latest_date = prev_latest["date"]

    # 即時資料通常會提供前一交易日收盤 y，作為備援；但顯示上仍以「比較基準」命名。
    rt_prev_close = to_float((realtime_quote or {}).get("prev_close"))
    if base_close is None and rt_prev_close is not None:
        base_close = rt_prev_close
        base_date = None

    # 顯示價格：有即時價就用即時 / 最新價；沒有即時價才用指定日期日 K 或最近日 K。
    if rt_price is not None and rt_price > 0:
        display_price = rt_price
        display_label = "即時價"
        _rt_source = str((realtime_quote or {}).get("source", "") or "")
        _rt_source_txt = f"即時來源：{_rt_source}" if _rt_source else "即時來源：即時報價"
        data_status = (
            f"{_rt_source_txt}｜日K：{_date_label_md(today_close_date)}收盤已更新 {fmt_price(today_close)}"
            if today_close is not None
            else f"{_rt_source_txt}｜日K：{_date_label_md(analysis_date)}收盤尚未更新"
        )
    elif today_close is not None:
        display_price = today_close
        display_label = f"{_date_label_md(today_close_date)}收盤"
        data_status = f"日K：{_date_label_md(today_close_date)}收盤已更新"
    else:
        display_price = latest_close
        display_label = f"{_date_label_md(latest_date)}最近收盤" if latest_date else "最近收盤"
        data_status = "日K：指定日期收盤尚未更新，使用最近一筆收盤"

        # 沒有即時價、也沒有分析日期日 K 時，比較基準改用最近收盤的前一筆。
        if base_close is None and prev_latest_close is not None:
            base_close = prev_latest_close
            base_date = prev_latest_date

    pct = pct_change(display_price, base_close) if display_price not in [None, 0] and base_close not in [None, 0] else None
    base_label = f"{_date_label_md(base_date)}收盤" if base_date else "昨日收盤"
    pct_text = _fmt_signed_pct(pct) if pct is not None else "—"

    parts = [f"{display_label} {fmt_price(display_price)}"]
    if base_close is not None:
        parts.append(f"昨日收盤：{base_label} {fmt_price(base_close)}")
        parts.append(f"較昨日 {pct_text}")
    else:
        parts.append("昨日收盤：資料不足")
    if rt_time:
        parts.append(rt_time)
    parts.append(data_status)

    return {
        "display_price": display_price,
        "display_label": display_label,
        "base_close": base_close,
        "base_date": base_date,
        "pct": pct,
        "analysis_date": analysis_date,
        "today_close": today_close,
        "today_close_date": today_close_date,
        "data_status": data_status,
        "quick_line": "｜".join([str(x) for x in parts if x]),
    }


def build_realtime_price_for_trend(price, realtime_quote=None):
    """v273.4｜趨勢變化雷達用即時價重算。

    原則：
    - 只更新「趨勢變化雷達 / 技術面即時判斷」。
    - 不覆蓋原始日 K，也不改財報、估值、Core / Focus 裁決。
    - 有即時價時，均線位置、價量關係、突破判斷改用即時價與即時量。
    """
    if not isinstance(price, dict):
        return price
    q = realtime_quote or {}
    rt_price = to_float(q.get("price"))
    if rt_price is None or rt_price <= 0:
        return price

    work = dict(price)
    work["close"] = rt_price
    work["trend_reference_label"] = "即時價"
    work["_trend_realtime_applied"] = True
    work["realtime_price"] = rt_price
    if q.get("time"):
        work["realtime_time"] = q.get("time")

    prev_close = to_float(q.get("prev_close"))
    if prev_close is not None and prev_close > 0:
        work["change_pct"] = pct_change(rt_price, prev_close)

    raw = price.get("raw")
    try:
        if raw is not None and not getattr(raw, "empty", True):
            df = raw.copy().sort_values("date").reset_index(drop=True)
            for c in ["close", "Trading_Volume", "VolMA20"]:
                if c in df.columns:
                    df[c] = pd.to_numeric(df[c], errors="coerce")
            last_idx = len(df) - 1
            if len(df) >= 5:
                work["ret5"] = pct_change(rt_price, df.iloc[max(0, len(df) - 5)]["close"])
            if len(df) >= 20:
                work["ret20"] = pct_change(rt_price, df.iloc[max(0, len(df) - 20)]["close"])
            if len(df) >= 60:
                work["ret60"] = pct_change(rt_price, df.iloc[max(0, len(df) - 60)]["close"])
            try:
                high20 = float(pd.to_numeric(df["close"], errors="coerce").tail(20).max())
                work["high20"] = high20
                work["drawdown20"] = pct_change(rt_price, high20) if high20 else work.get("drawdown20")
            except Exception:
                pass
            try:
                high60 = float(pd.to_numeric(df["close"], errors="coerce").tail(60).max())
                work["high60"] = high60
                work["drawdown60"] = pct_change(rt_price, high60) if high60 else work.get("drawdown60")
            except Exception:
                pass

            # 即時量：TWSE MIS 有時回傳張數，有時資料源日K是股數；用 VolMA20 大小自動校正。
            q_vol = to_float(q.get("volume"))
            vol_ma20 = None
            if "VolMA20" in df.columns and len(df) > 0:
                vol_ma20 = to_float(df.iloc[-1].get("VolMA20"))
            if q_vol is not None and q_vol > 0 and vol_ma20 is not None and vol_ma20 > 0:
                q_vol_eff = q_vol
                if q_vol_eff < vol_ma20 * 0.05:
                    q_vol_eff = q_vol_eff * 1000
                work["volume_ratio"] = safe_div(q_vol_eff, vol_ma20)
                work["volume_lot"] = q_vol_eff / 1000
                work["realtime_volume"] = q_vol_eff

            prev_high20 = work.get("prev_high20")
            if prev_high20 is None and len(df) >= 20:
                prev_high20 = pd.to_numeric(df["close"], errors="coerce").tail(20).max()
            vol_ratio = work.get("volume_ratio")
            work["breakout_now"] = (
                rt_price is not None
                and prev_high20 is not None
                and vol_ratio is not None
                and rt_price > float(prev_high20) * 1.005
                and float(vol_ratio) >= 1.3
            )
    except Exception:
        pass

    return work



