def get_family_valuation_support_style(model_key=None, industry_category=None, valuation_submodel_key=None, stock=None):
    try:
        fk, rule = get_effective_family_context(model_key, valuation_submodel_key, stock, industry_category)
    except Exception:
        fk, rule = "quality_growth_pe", MODEL_FAMILY_RULES.get("quality_growth_pe", {}) if "MODEL_FAMILY_RULES" in globals() else {}
    style = dict(FAMILY_VALUATION_SUPPORT_STYLES.get(fk) or FAMILY_VALUATION_SUPPORT_STYLES["quality_growth_pe"])
    style["family_key"] = fk
    style["family_name"] = (rule or {}).get("family_name") or fk
    style["valuation_role"] = (rule or {}).get("valuation_role") or "需用財報與估值交叉驗證"
    style["evidence_tags"] = (rule or {}).get("evidence_tags") or []
    style["risk_tags"] = (rule or {}).get("risk_tags") or []
    style["subfamily_key"] = (rule or {}).get("subfamily_key", "")
    style["subfamily_note"] = (rule or {}).get("subfamily_note", "")
    return style


def family_valuation_role_line(val):
    """估值區塊的母模型角色說明；只提示方法，不改裁決。"""
    val = val or {}
    model_key = val.get("model_key")
    style = get_family_valuation_support_style(model_key, valuation_submodel_key=val.get("valuation_submodel_key"), stock=val.get("stock"))
    family_name = style.get("family_name")
    valuation_role = style.get("valuation_role")
    if not family_name and not valuation_role:
        return ""
    return f"估值母模型：{family_name}｜{valuation_role}"


def build_family_support_quick(val, support_range, ref_label, relation, rel_label="", gap=None, eps_basis_text="EPS", ratio_label="合理 PE", ratio_text="倍數無資料"):
    """用母模型產生基本面支撐語氣，避免每個 model_key 寫死。"""
    style = get_family_valuation_support_style((val or {}).get("model_key"))
    msg = style.get(relation) or style.get("inside") or "仍需看財報與估值是否接棒。"
    if relation == "above" and gap is not None:
        pos = f"高於支撐區上緣約 {_fmt_signed_pct(gap)}"
    elif relation == "below" and gap is not None:
        pos = f"低於支撐區下緣約 {_fmt_signed_pct(gap)}"
    else:
        pos = f"位於{rel_label}" if rel_label else "位於支撐區"
    quick = f"EPS 基礎：{eps_basis_text}｜{ratio_label}：{ratio_text}\n基本面支撐區約 {support_range}；{ref_label}{pos}，{msg}"
    return quick, style.get("card") or msg

def build_fundamental_support_summary(price, val, current_zone="", realtime_quote=None):
    """把估值模型裡的「中性 / 基本面支撐區」翻成小白看得懂的文字。

    核心回答三件事：
    1. 基本面支撐價大約是多少？
    2. 現價是否已經高於基本面支撐區？
    3. 如果股價已先跑，未來要靠什麼接棒？
    """
    val = val or {}
    if not val.get("ok"):
        return {
            "support_range": "資料不足",
            "card_value": "資料不足",
            "card_note": "目前 EPS 或估值資料不足，不能硬算基本面支撐價。",
            "quick": "資料不足，暫時不能判斷基本面支撐價。",
            "check": "先確認 EPS、毛利率與營收資料是否完整。",
        }

    support = valuation_support_range(val)
    support_pe = valuation_support_pe(val)
    if not support or support[0] is None or support[1] is None:
        return {
            "support_range": "資料不足",
            "card_value": "資料不足",
            "card_note": "模型沒有產出基本面支撐區。",
            "quick": "模型沒有產出基本面支撐區，需人工確認估值。",
            "check": "先確認 EPS 與產業 PE 假設。",
        }

    low, high = min(support[0], support[1]), max(support[0], support[1])
    support_range = rng_price((low, high))
    eps_basis_text = val.get("base_eps_label", "EPS")
    _formula_used_for_basis = str(val.get("valuation_formula_used") or "")
    _formula_family_for_basis = str(val.get("valuation_formula_family") or "")
    if "PE + P/B" in _formula_used_for_basis or _formula_family_for_basis == "PE+PB":
        _bvps = to_float(val.get("bvps"))
        _pbr = to_float(val.get("market_pbr"))
        _eps_label = "未來 12 個月 EPS" if valuation_support_key(val) not in ["down", "cons"] else val.get("base_eps_label", "EPS")
        if _bvps is not None and _pbr is not None:
            eps_basis_text = f"{_eps_label} + BVPS {fmt(_bvps, 2)} / PBR {fmt(_pbr, 2)}"
        else:
            eps_basis_text = f"{_eps_label} + P/B 資料不足"
    elif val.get("valuation_formula_used") and ("P/B" in str(val.get("valuation_formula_used")) or "proxy" in str(val.get("valuation_formula_used"))):
        _bvps = to_float(val.get("bvps"))
        _pbr = to_float(val.get("market_pbr"))
        if _bvps is not None and _pbr is not None:
            eps_basis_text = f"推估 BVPS {fmt(_bvps, 2)}｜PBR {_pbr:.2f}"
        else:
            eps_basis_text = "P/B 資料不足"
    elif val.get("model_key") in ["advanced_packaging_osat", "memory_cyclical_distributor", "defensive_cashflow_treasury", "financial_holding_life_revaluation", "financial_bank_core", "financial_brokerage_cycle", "financial_general_core"]:
        eps_basis_text = "未來 12 個月 EPS"
    elif valuation_support_key(val) != "down":
        eps_basis_text = "未來 12 個月 EPS" if valuation_support_key(val) not in ["down", "cons"] else val.get("base_eps_label", "EPS")
    valuation_ratio_label = val.get("valuation_multiple_label") or "合理 PE"
    pe_text = valuation_support_multiple_text(val) or (f"{support_pe[0]}x～{support_pe[1]}x" if support_pe else "倍數無資料")
    if str(val.get("valuation_formula_family") or "") == "PE+PB" or "PE + P/B" in str(val.get("valuation_formula_used") or ""):
        valuation_ratio_label = "估值倍數"
    _submodel_line = valuation_submodel_summary_line(val)
    _submodel_note = val.get("valuation_submodel_note") or ""
    _submodel_warning = val.get("valuation_submodel_v1_warning") or ""
    _valuation_prefix_parts = []
    _family_role_line = family_valuation_role_line(val)
    if _family_role_line:
        _valuation_prefix_parts.append(_family_role_line)
    if _submodel_line:
        _valuation_prefix_parts.append(_submodel_line)
    if _submodel_note:
        _valuation_prefix_parts.append("提醒：" + _submodel_note)
    if _submodel_warning:
        _valuation_prefix_parts.append("資料防呆：" + _submodel_warning)
    if val.get("valuation_formula_used"):
        _formula_line = f"實際估值公式：{val.get('valuation_formula_used')}"
        if val.get("valuation_formula_detail"):
            _formula_line += "｜" + str(val.get("valuation_formula_detail"))
        _valuation_prefix_parts.append(_formula_line)
    if val.get("valuation_formula_warning"):
        _valuation_prefix_parts.append("公式限制：" + str(val.get("valuation_formula_warning")))
    valuation_prefix = "\n".join(_valuation_prefix_parts)
    if valuation_prefix:
        valuation_prefix = valuation_prefix + "\n"
    price_ctx = build_date_price_context(price, realtime_quote)
    ref_price = price_ctx.get("display_price")
    ref_label = price_ctx.get("display_label", "目前價格")

    zone = str(current_zone or "")
    check = "後續要看營收、毛利率、EPS 能不能接棒。"

    if ref_price is None or ref_price <= 0:
        return {
            "support_range": support_range,
            "card_value": f"支撐價 {support_range}",
            "card_note": "目前沒有現價可比較。",
            "quick": f"基本面支撐價約 {support_range}，但目前缺少現價比較。",
            "check": check,
        }

    if low <= ref_price <= high:
        rel_label, _rel_pos = valuation_relative_label({"close": ref_price}, val)
        if val.get("model_key") == "memory_cyclical_distributor":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有部分基本面支撐，但支撐來自記憶體報價與 EPS 延續，不代表可以重押。"
            card_note = "低毛利通路股仍需看 Q2 EPS、毛利率、現金流與庫存週轉。"
        elif val.get("model_key") == "defensive_cashflow_treasury":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有基本面支撐，但不是便宜價；重點是買點與股利防守性。"
            card_note = "這是防守型金庫，不是攻擊股；等回檔更漂亮。"
        elif val.get("model_key") == "financial_holding_life_revaluation":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有基本面支撐，但不是便宜甜蜜點；重點看 5～6 月獲利與投信賣壓是否縮小。"
            card_note = "金融資產型金庫可收編，但仍要等回檔或右側突破。"
        elif val.get("model_key") == "consumer_restaurant_stable":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有財報與股息支撐，但不是便宜甜蜜點，需靠 Q2 旺季與營益率接棒。"
            card_note = "穩健內需餐飲可 Core 觀察，但不是爆發攻擊股；重點看買點、股息與法人籌碼。"
        elif val.get("model_key") == "biotech_commercial_drug_growth":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有成長支撐但不低估，需靠後續營收、EPS 與藥證進度驗證。"
            card_note = "商業化新藥可 Core，但現價若已買未來預期，不適合重倉追價。"
        elif val.get("model_key") == "real_estate_delivery_recognition":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有交屋認列支撐，但不是低估甜蜜價，需靠後續營收與 EPS 接棒。"
            card_note = "建商交屋潮可重評，但營收認列會跳；只適合等買點，不適合無腦重押。"
        elif val.get("model_key") == "shipping_freight_rebound":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有部分基本面支撐，但 Q1 財報仍年減，需靠運價與 Q2 EPS 驗證。"
            card_note = "航運可短打，但不可戀愛；重點看 SCFI / 運價、營收與法人籌碼。"
        elif val.get("model_key") == "financial_brokerage_cycle":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有資本市場循環支撐，但不代表可以重押；重點看台股成交量與法人籌碼。"
            card_note = "證券循環型金融股要看市場熱度、自營 / 財管收益與股利能力。"
        elif val.get("model_key") in ["financial_bank_core", "financial_general_core"]:
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於{rel_label}，有金融基本面支撐，但不代表可以重押；重點看月獲利、配息與法人籌碼。"
            card_note = "金融股要看 EPS、ROE、資產品質 / 市場熱度與股利能力，不是看毛利率。"
        else:
            quick, card_note = build_family_support_quick(
                val, support_range, ref_label, "inside", rel_label=rel_label,
                eps_basis_text=eps_basis_text, ratio_label=valuation_ratio_label, ratio_text=pe_text
            )
        card_value = f"支撐價 {support_range}"
    elif ref_price > high:
        gap = (ref_price / high - 1) * 100 if high else None
        if gap is not None and gap >= 25:
            tone = "已明顯高於支撐區，市場在買未來預期"
        elif gap is not None and gap >= 10:
            tone = "已高於支撐區，市場已先買一部分未來"
        else:
            tone = "略高於支撐區，仍要看後續基本面能否接棒"
        if val.get("model_key") == "panel_turnaround_rerating":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n目前基本面支撐區約 {support_range}；{ref_label}高於支撐區上緣約 {_fmt_signed_pct(gap)}，市場已先買轉型與未來 EPS，需靠 5～7 月營收、Q2 EPS、毛利率 / 營益率接棒。"
            card_note = "面板轉機重評只能部分成立；若 EPS 沒上修，股價容易回測支撐區。"
        elif val.get("model_key") == "advanced_packaging_osat":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}高於保守支撐區上緣約 {_fmt_signed_pct(gap)}，已接近中性 / 重評區，需靠 Q2 EPS 與毛利率 / 營益率續升接棒。"
            card_note = "封測 Re-rating 有根，但現價已非低估區，需等回檔小倉 / 不追高。"
        elif val.get("model_key") == "memory_cyclical_distributor":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}高於保守支撐區上緣約 {_fmt_signed_pct(gap)}，仍需靠 Q2 EPS、記憶體報價與毛利率 / 營益率續強接棒。"
            card_note = "支撐來自記憶體循環與 EPS 延續，不是高毛利體質；不適合主倉重押。"
        elif val.get("model_key") == "defensive_cashflow_treasury":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}略高於合理支撐區，仍有基本面支撐，但風報比不漂亮，等回檔比較舒服。"
            card_note = "防守型 Core 有收編價值，但現價不適合攻擊追價。"
        elif val.get("model_key") == "financial_holding_life_revaluation":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}有基本面支撐，但不是便宜甜蜜點；需看 5～6 月獲利與籌碼能否接棒。"
            card_note = "金融資產型金庫可收編，但不適合把單月爆賺當成重押理由。"
        elif val.get("model_key") == "consumer_restaurant_stable":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}已接近支撐區上緣，仍有財報支撐但不適合追重倉。"
            card_note = "王品屬穩健內需股，估值重評只能部分成立；要等回檔小倉；若已突破，等回測確認。"
        elif val.get("model_key") == "biotech_commercial_drug_growth":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於合理偏上，基本面能解釋但不是便宜價，需靠 Q2 EPS 與藥證進度接棒。"
            card_note = "商業化新藥可給成長溢價，但不可只用藥證期待重押；要看月營收、營益率、EPS 與事件進度。"
        elif val.get("model_key") == "real_estate_delivery_recognition":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}位於合理偏上，仍需靠交屋認列、5～6 月營收與 Q2 EPS 接棒。"
            card_note = "營建股要搭配 P/B、完工案量、存貨 / 負債與股利殖利率，不可只用單月營收暴增追價。"
        elif val.get("model_key") == "shipping_freight_rebound":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}接近支撐區上緣，需靠 SCFI / 運價、月營收與 Q2 毛利率接棒。"
            card_note = "航運是運價反彈交易，不是穩定成長重評；只能小倉或等突破確認。"
        elif val.get("model_key") == "financial_brokerage_cycle":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}已高於基本支撐區，需靠台股成交量、自營 / 財管收益與法人籌碼接棒。"
            card_note = "證券循環型金融可觀察，但現價不是便宜甜蜜點，不適合主倉重押。"
        elif val.get("model_key") in ["financial_bank_core", "financial_general_core"]:
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}有金融基本面支撐，但仍要看月獲利、股利政策與法人籌碼是否接棒。"
            card_note = "金融股重點看 EPS、ROE、資產品質 / 市場熱度與配息能力，不套製造業毛利率邏輯。"
        elif val.get("model_key") == "hvlp_copper_foil_growth":
            if gap is not None and gap > 0:
                quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n成長型支撐區約 {support_range}；{ref_label}高於支撐區上緣約 {_fmt_signed_pct(gap)}，市場正在買未來 EPS 上修與 HVLP 高階銅箔 Re-rating。"
            else:
                quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n成長型支撐區約 {support_range}；{ref_label}位於成長支撐區內，有基本面支撐但不是低估價。"
            card_note = "HVLP / VLP 高階銅箔已不是一般銅箔循環估值；現價需靠 HVLP 占比、毛利率、EPS 與法人籌碼接棒，不適合重押追高。"
        elif val.get("model_key") in ["copper_foil_cyclical", "glass_fiber_cyclical", "ccl_general_highspeed"] and gap is not None and gap > 50:
            # fix56｜循環股支撐區百分比降噪
# fix56b｜循環股支撐區百分比保留＋白話說明
# fix57｜PCB / ABF 子模組拆分：
            # 金居 / 富喬 / 聯茂等材料循環股，保守支撐區常只代表「目前 EPS × 保守 PE」。
            # 若直接顯示 +300%、+500%，會被誤會成模型判斷股價必倒；
            # 正確語氣是：高於保守支撐區，市場在先買未來修復，需等待報價與 EPS 驗證。
            if gap > 80:
                # fix56b｜保留百分比，但加白話解釋，避免誤會成單純泡沫判定。
                quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n保守支撐區約 {support_range}；{ref_label}高於保守支撐區約 {_fmt_signed_pct(gap)}，市場正在先買報價、稼動率與未來 EPS 修復。"
                card_note = "高於保守支撐區，市場正在先買未來修復；若報價、毛利率、EPS 沒接上，只能小倉觀察，不能重押。"
            else:
                quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n保守支撐區約 {support_range}；{ref_label}高於保守支撐區約 {_fmt_signed_pct(gap)}，市場正在先買報價、稼動率與未來 EPS 修復。"
                card_note = "這不是高階 CCL Core 估值；若報價、毛利率、EPS 沒接上，只能小倉觀察，不能重押。"
        elif gap is not None and gap > 50:
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}高於支撐區上緣約 {_fmt_signed_pct(gap)}，需先檢查 EPS 基礎與族群 PE，不可寫成沒有脫離基本面。"
            card_note = "股價已先跑，需靠營收、毛利率、EPS 接棒。"
        else:
            quick, card_note = build_family_support_quick(
                val, support_range, ref_label, "above", gap=gap,
                eps_basis_text=eps_basis_text, ratio_label=valuation_ratio_label, ratio_text=pe_text
            )
        if val.get("model_key") in ["copper_foil_cyclical", "glass_fiber_cyclical", "ccl_general_highspeed"] and gap is not None and gap > 80:
            card_value = f"高於保守支撐區 {_fmt_signed_pct(gap)}"
        else:
            card_value = f"高於支撐區 {_fmt_signed_pct(gap)}"
    else:
        gap = (ref_price / low - 1) * 100 if low else None
        if val.get("model_key") == "thermal_liquid_cooling":
            quick = f"EPS 基礎：{eps_basis_text}｜{valuation_ratio_label}：{pe_text}\n基本面支撐區約 {support_range}；{ref_label}低於支撐區下緣約 {_fmt_signed_pct(gap)}，用未來 EPS 看可解釋，但仍需等技術與籌碼確認。"
            card_note = "估值可解釋不等於低風險買點，需確認法人止賣與站回攻擊位。"
        else:
            quick, card_note = build_family_support_quick(
                val, support_range, ref_label, "below", gap=gap,
                eps_basis_text=eps_basis_text, ratio_label=valuation_ratio_label, ratio_text=pe_text
            )
        card_value = f"低於支撐區 {_fmt_signed_pct(gap)}"

    if valuation_prefix and quick:
        quick = valuation_prefix + quick

    return {
        "support_range": support_range,
        "card_value": card_value,
        "card_note": card_note,
        "quick": quick,
        "check": check,
        "ref_price": ref_price,
        "zone": zone,
        "valuation_submodel": val.get("valuation_submodel_name", ""),
        "valuation_primary_method": val.get("valuation_primary_method", ""),
    }


def build_upside_valuation_target(price, val, realtime_quote=None):
    """找出目前股價所在區間上方的下一個估值區間目標。

    用在快速判讀：法人平均目標價旁邊，補一個「模型上方目標」。
    """
    if not val or not val.get("ok"):
        return "上方估值目標：資料不足"

    price_ctx = build_date_price_context(price, realtime_quote)
    ref_price = price_ctx.get("display_price")

    if ref_price is None or ref_price <= 0:
        return "上方估值目標：資料不足"

    zones = [
        ("下修區", val.get("down")),
        ("保守區", val.get("cons")),
        ("基本面支撐區", val.get("neutral")),
        ("樂觀區", val.get("opt")),
        ("估值重評合理區", val.get("rerating")),
        ("市場溢價區", val.get("market_premium")),
    ]

    parsed = []
    for name, r in zones:
        if r and r[0] is not None and r[1] is not None:
            lo, hi = min(r[0], r[1]), max(r[0], r[1])
            parsed.append((name, lo, hi))

    if not parsed:
        return "上方估值目標：資料不足"

    # 若現價在某區間內，目標看「下一個區間」；若落在兩區中間，目標看最近的上方區間。
    for idx, (name, lo, hi) in enumerate(parsed):
        if lo <= ref_price <= hi:
            if idx + 1 < len(parsed):
                n2, lo2, hi2 = parsed[idx + 1]
                return f"上方估值目標：{n2} {rng_price((lo2, hi2))}"
            return "上方估值目標：已在最高估值區，需保守看"
        if ref_price < lo:
            return f"上方估值目標：{name} {rng_price((lo, hi))}"

    return "上方估值目標：已高於模型最高區，需人工複核"


def build_future_win_quick_line(price, a, holding_cost=None):
    """快速判讀用：挑出買點情境分數中的最佳可參考情境。"""
    try:
        rows = build_future_win_rows(price, a, holding_cost)
    except Exception:
        rows = []

    candidates = []
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        label = str(r.get("情境", ""))
        if "持股" in label:
            continue
        win = _pct_from_win_text(r.get("20日區間") or r.get("20日勝率"))
        entry = to_float(r.get("進場區") or r.get("進場價"))
        if win is None or entry is None:
            continue
        # 現價買若動作是只觀察，不要讓它太容易成為最佳，避免誤導。
        penalty = -3 if ("現價" in label and "只觀察" in str(a.get("action", ""))) else 0
        candidates.append((win + penalty, win, entry, r))

    if not candidates:
        return "買點情境分數：資料不足"

    candidates.sort(key=lambda x: (x[0], -x[2]), reverse=True)
    _, win, entry, r = candidates[0]
    label = r.get("情境", "試算")
    target = r.get("短線目標", "—")
    stop = r.get("停損", "—")
    return f"買點情境分數：{label}｜進場 {r.get('進場區', r.get('進場價', '—'))}｜目標 {target}｜20日 {r.get('20日區間', r.get('20日勝率', '—'))}｜動作 {r.get('適合動作', '—')}"


def build_15s_read(
    stock,
    name,
    price,
    rev,
    fin,
    inst,
    a,
    current_zone="",
    buy_zone_summary=None,
    sr_levels=None,
    realtime_quote=None,
    news_rows=None,
    data_quality=None,
    pullback_quality=None,
    attack_display_text="",
    analyst_target=None,
):
    """產生給小白分享用的快速判讀。

    V9.0：分享文改成「判斷 → 位置 → 市場在看什麼 → 估值支撐 → 操作 → 觀察 → 新聞」。
    原則：
    1. 第一段固定露出：財報裁決 / Core / Attack / Focus / 最終動作。
    2. 買點拆成新倉主買區、淺回檔小倉區、右側突破條件。
    3. 估值必須顯示 EPS 基礎、PE、基本面支撐區與現價相對位置。
    """
    buy_zone_summary = buy_zone_summary or {}
    sr_levels = sr_levels or {}
    news_rows = news_rows or []
    data_quality = data_quality or {}
    pullback_quality = pullback_quality or {}

    action = str(a.get("action", "") or "")
    why = str(a.get("why", "") or "")
    fj = a.get("fin_j", {}) or {}

    def _plain_text(s):
        """把系統內部術語翻成分享文語氣。"""
        s = str(s or "").strip()
        replacements = {
            "公司可收編": "Core Yes",
            "公司不可收編": "公司體質未通過",
            "Attack Yes": "Attack Yes",
            "Attack No": "Attack No",
            "Focus Yes": "Focus Yes",
            "Focus No": "Focus No",
            "1–4 週攻擊條件未完整成立": "短線買點還沒完整轉強",
            "1-4 週攻擊條件未完整成立": "短線買點還沒完整轉強",
            "1–4週攻擊條件未完整成立": "短線買點還沒完整轉強",
            "1-4週攻擊條件未完整成立": "短線買點還沒完整轉強",
            "攻擊條件未完整成立": "短線買點還沒完整轉強",
            "金庫級": "財報品質佳",
            "候選級": "財報品質可追蹤",
            "觀察級": "財報仍需觀察",
            "估值重評": "市場重新給價",
        }
        for k, v in replacements.items():
            s = s.replace(k, v)
        # 保留 Core / Attack / Focus，因為 30 秒判讀需要明確露出五層裁決。
        return s.strip(" ｜，。") or "目前條件還要再確認"

    def _clean_label_text(s):
        s = str(s or "").strip()
        for prefix in ["最近支撐：", "最近支撐", "最近壓力：", "最近壓力", "支撐看", "壓力看"]:
            s = s.replace(prefix, "")
        return s.strip(" ：｜") or "資料不足"

    def _shorten(s, n=58):
        s = str(s or "").strip()
        return s if len(s) <= n else s[:n] + "…"

    def _v27182_clean_condition_text(txt: Any) -> str:
        """v271.8.2｜30秒判讀文案清潔：避免重複跌破/站上與空白符號。"""
        t = str(txt or "").strip()
        if not t:
            return t
        # 常見模板會自動補「跌破」，但法醫快照本身已經含跌破。
        t = re.sub(r"跌破\s*跌破\s*", "跌破 ", t)
        t = re.sub(r"站上\s*站上\s*", "站上 ", t)
        t = re.sub(r"突破\s*突破\s*", "突破 ", t)
        t = re.sub(r"守\s*守\s*", "守 ", t)
        t = re.sub(r"\s+", " ", t).strip()
        t = t.replace("跌破 跌破", "跌破").replace("站上 站上", "站上")
        return t

    def _v27182_prefix_condition(prefix: str, cond: Any) -> str:
        """prefix 不重複：cond 已含跌破/站上時不再補。"""
        c = _v27182_clean_condition_text(cond)
        if not c:
            return ""
        if c.startswith(prefix) or c.startswith("跌破") or c.startswith("站上") or c.startswith("突破") or c.startswith("收回"):
            return c
        return _v27182_clean_condition_text(f"{prefix} {c}")

    def _v27182_case_text_blob(case: Any) -> str:
        if not isinstance(case, dict):
            return ""
        parts = []
        for k in [
            "raw_text", "limitations_text", "risk_text", "buy_wrong_text", "learning_mistakes",
            "correct_judgement", "suggested_rules", "case_reason", "case_limitations",
            "core_type", "rerating_verdict", "report_type", "final_action", "forensic_note"
        ]:
            v = case.get(k)
            if v is not None:
                parts.append(str(v))
        for k in ["limitations", "validation_rules", "learning", "self_learning", "trade_snapshot", "same_sector_tags"]:
            v = case.get(k)
            if v is not None:
                parts.append(str(v))
        return " ｜ ".join(parts)

    def _v27182_focus_display(raw: Any, payload: Any = None) -> str:
        """Focus No 一律不能翻成「觀察名單」。"""
        fp = payload if isinstance(payload, dict) else {}
        val = str(fp.get("focus_snapshot") or fp.get("focus") or raw or "").strip()
        if not val:
            val = "No"
        if re.search(r"\bYes\b", val, flags=re.I) or val == "是":
            return "Yes"
        if re.search(r"\bNo\b", val, flags=re.I) or val == "否" or "No" in val or "不" in val:
            return "No｜暫不集中火力"
        if "觀察" in val and not ("Yes" in val):
            return "No｜暫不集中火力"
        return val

    def _v27182_chip_priority_line(case: Any) -> str:
        """法醫/AI Core 若明確寫籌碼不乾淨，30秒判讀優先顯示，不被近5日買超淡化。"""
        blob = _v27182_case_text_blob(case)
        if not blob:
            return ""
        has_invest_trust = "投信" in blob
        has_20d = ("20日" in blob) or ("近20" in blob) or ("20 日" in blob)
        has_dirty = any(k in blob for k in ["不乾淨", "大賣", "賣壓尚未", "連續賣", "賣超未止", "投信賣壓", "不得Focus", "不得 Focus", "限制 Focus"])
        if has_invest_trust and (has_20d or has_dirty):
            return "籌碼：短線法人有回補，但 20 日籌碼仍不乾淨，投信賣壓尚未完全解除，因此限制 Focus。"
        if any(k in blob for k in ["法人20日賣超", "法人 20 日賣超", "法人續賣", "籌碼不乾淨"]):
            return "籌碼：短線承接可觀察，但 20 日籌碼仍不乾淨，法人賣壓未完全解除，限制 Attack / Focus。"
        return ""

    def _v27182_replace_or_append_chip_line(market_text: Any, chip_line: str) -> str:
        txt = str(market_text or "").strip()
        if not chip_line:
            return txt
        if "籌碼：" in txt:
            txt = re.sub(r"籌碼：.*", chip_line, txt)
            return txt
        return (txt + "\n" + chip_line).strip()

    def _parse_price_range_text(s):
        """從「2,345 ～ 2,445」這類文字抓出區間，失敗則回傳 (None, None)。
        只用於分享文買點分層，不影響底層估值 / 法醫計算。
        """
        try:
            txt = str(s or "")
            nums = re.findall(r"\d[\d,]*(?:\.\d+)?", txt)
            vals = []
            for n in nums[:2]:
                v = to_float(str(n).replace(",", ""))
                if v is not None:
                    vals.append(v)
            if len(vals) >= 2:
                lo, hi = min(vals[0], vals[1]), max(vals[0], vals[1])
                return lo, hi
            if len(vals) == 1:
                return vals[0], vals[0]
        except Exception:
            pass
        return None, None

    def _zone_relation(price_value, low, high, buffer_pct=0.005):
        """回傳 below / in / near_above / above / unknown。"""
        try:
            px = to_float(price_value)
            if px is None or low is None or high is None:
                return "unknown"
            if px < low:
                return "below"
            if low <= px <= high:
                return "in"
            if high and px <= high * (1 + buffer_pct):
                return "near_above"
            return "above"
        except Exception:
            return "unknown"

    # 價格與比較基準：分享文只保留最直覺的目前價格與漲跌幅。
    price_ctx = build_date_price_context(price, realtime_quote)
