            title = r.get("title") if isinstance(r, dict) else ""
            source = r.get("source") if isinstance(r, dict) else ""
            _bad_title = any(k in str(title) for k in ["個股概覽", "長黑K", "分點", "同學會", "爆料"])
            _bad_source = any(k in str(source) for k in ["CMoney", "股市爆料同學會"])
            if _bad_title or _bad_source:
                continue
            date = r.get("date") if isinstance(r, dict) else ""
            if title:
                title = str(title)
                # v28｜快速判讀新聞也做一次本檔主體過濾，避免抓到只提到本檔的別檔新聞。
                _name_s = str(name or "").strip()
                _code_s = str(stock or "").strip()
                _title_for_rel = title
                if source and _title_for_rel.endswith(" - " + str(source)):
                    _title_for_rel = _title_for_rel[: -(len(str(source)) + 3)]
                _direct_ok = False
                if _code_s and _code_s in _title_for_rel:
                    _direct_ok = True
                elif _name_s:
                    _bad_cmp = any(k in _title_for_rel for k in [f"超車{_name_s}", f"超越{_name_s}", f"勝過{_name_s}", f"打敗{_name_s}", f"追上{_name_s}", f"比{_name_s}"])
