    def _nick_role_operation_label_sanitize(line: Any, buy_wrong_value: Any = "") -> str:
        """v259｜30秒操作三句固定角色：空手想進場 / 已持有 / 想加碼。"""
        txt = str(line or "").strip()
        if not txt:
            return txt
        # 先統一三個角色標籤，避免「想買」到底是空手還是加碼。
        if txt.startswith("空手："):
            txt = "空手想進場：" + txt[len("空手："):]
        if txt.startswith("持有："):
            txt = "已持有：" + txt[len("持有："):]
        if txt.startswith("想買："):
            txt = "想加碼：" + txt[len("想買："):]
        # 防呆：加碼永遠不能發生在跌破防守時。
        if txt.startswith("想加碼："):
            bw = str(buy_wrong_value or "").strip()
            has_no_add_guard = ("不加碼" in txt) or ("不追" in txt and "加碼" in txt) or ("跌破" in txt and ("停" in txt or "降" in txt))
            if not has_no_add_guard:
                if bw and bw != "—":
                    txt = txt.rstrip("。") + f"；跌破 {bw} 不加碼。"
                else:
                    txt = txt.rstrip("。") + "；跌破防守不加碼。"
        # 空手追價防呆：如果句子只有等回，補承接確認語意。
        if txt.startswith("空手想進場：") and ("等回" in txt) and ("承接" not in txt):
            txt = txt.replace("等回 ", "等回 ").rstrip("。") + "，有承接再小量。"
        return _v27182_clean_condition_text(txt)

