# 股價資料不快取：每次分析都重新抓，避免用到舊價
def fetch_price(stock):
    end = datetime.today().date()
    start = end - timedelta(days=420)
    df, err = fm("TaiwanStockPrice", stock, str(start), str(end))
    if df.empty:
        return None, err
    if "date" not in df.columns or "close" not in df.columns:
        return None, f"股價欄位不足：{list(df.columns)}"
    df = df.copy().sort_values("date")
    for c in ["open", "max", "min", "close", "Trading_Volume"]:
        if c in df.columns:
            df[c] = df[c].apply(to_float)
    df = df.dropna(subset=["close"])
    if df.empty:
        return None, "股價清洗後為空"
    df["MA5"] = df["close"].rolling(5).mean()
    df["MA10"] = df["close"].rolling(10).mean()
    df["MA20"] = df["close"].rolling(20).mean()
    df["MA60"] = df["close"].rolling(60).mean()
    df["MA120"] = df["close"].rolling(120).mean()
    if "Trading_Volume" in df.columns:
        df["VolMA20"] = df["Trading_Volume"].rolling(20).mean()
    last = df.iloc[-1]
    prev = df.iloc[-2] if len(df) >= 2 else last
    close = to_float(last["close"])
    prev_close = to_float(prev["close"])
    prev_high20 = df["close"].iloc[:-1].tail(20).max() if len(df) >= 21 else None
    high20 = df["close"].tail(20).max()
    low10 = df["close"].tail(10).min() if len(df) >= 10 else None
    low20 = df["close"].tail(20).min()
    high60 = df["close"].tail(60).max() if len(df) >= 60 else None
    low60 = df["close"].tail(60).min() if len(df) >= 60 else None
    volume_ratio = safe_div(last.get("Trading_Volume"), last.get("VolMA20"))
    breakout_now = (
        close is not None
        and prev_high20 is not None
        and volume_ratio is not None
        and close > prev_high20 * 1.005
        and volume_ratio >= 1.3
    )

    def ret(days):
        if len(df) <= days or close is None:
            return None
        return pct_change(close, df.iloc[-days - 1]["close"])

    ma20_slope_5 = (
        pct_change(last.get("MA20"), df.iloc[-6].get("MA20")) if len(df) >= 26 else None
    )
    ma60_slope_10 = (
        pct_change(last.get("MA60"), df.iloc[-11].get("MA60"))
        if len(df) >= 71
        else None
    )
    drawdown20 = pct_change(close, high20) if close is not None and high20 else None
    drawdown60 = pct_change(close, high60) if close is not None and high60 else None
    volume_lot = (
        to_float(last.get("Trading_Volume")) / 1000
        if to_float(last.get("Trading_Volume")) is not None
        else None
    )
    return {
        "date": last["date"],
        "close": close,
        "change_pct": pct_change(close, prev_close),
        "ma5": to_float(last.get("MA5")),
        "ma10": to_float(last.get("MA10")),
        "ma20": to_float(last.get("MA20")),
        "ma60": to_float(last.get("MA60")),
        "ma120": to_float(last.get("MA120")),
        "ma20_slope_5": ma20_slope_5,
        "ma60_slope_10": ma60_slope_10,
        "ret5": ret(5),
        "ret20": ret(20),
        "ret60": ret(60),
        "drawdown20": drawdown20,
        "drawdown60": drawdown60,
        "volume_lot": volume_lot,
        "volume_ratio": volume_ratio,
        "high20": high20,
        "prev_high20": prev_high20,
        "low10": low10,
        "low20": low20,
        "high60": high60,
        "low60": low60,
        "breakout_now": breakout_now,
        "raw": df,
    }, ""


def _quote_num(v):
    """解析 TWSE MIS 即時報價數字欄位。遇到多檔位字串時取第一個有效值。"""
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        if "_" in s:
            parts = [p for p in s.split("_") if p not in ["", "-", "--"]]
            s = parts[0] if parts else ""
        s = s.replace(",", "").strip()
        if s in ["", "-", "--", "nan", "None", "NaN"]:
            return None
        return to_float(s)
    return to_float(v)


def _quote_date_to_timestamp(date_str):
    try:
        s = str(date_str or "").strip()
        if len(s) == 8 and s.isdigit():
            return pd.to_datetime(s, format="%Y%m%d", errors="coerce")
        return pd.to_datetime(s, errors="coerce")
    except Exception:
        return pd.NaT



def _fetch_yahoo_realtime_quote_fallback(code):
    """TWSE MIS 失敗時的備援即時/近即時報價。

    為什麼需要：
    - Replit / 部分網路環境偶爾抓不到 TWSE MIS。
    - 主畫面第一張價格卡必須優先顯示「即時價」，不能在盤中退回最近收盤。
    - Yahoo Finance 台股通常有延遲，但仍比日K最近收盤更接近目前價。
    """
    code = clean_text(code)
    if not code:
        return None, "股票代號空白"

    headers = {"User-Agent": "Mozilla/5.0"}
    symbols = [f"{code}.TW", f"{code}.TWO"]
    last_err = ""

    for sym in symbols:
        try:
            url = f"https://query1.finance.yahoo.com/v8/finance/chart/{sym}"
            r = requests.get(
                url,
                params={"range": "1d", "interval": "1m", "includePrePost": "false"},
                headers=headers,
                timeout=8,
            )
            if r.status_code != 200:
                last_err = f"Yahoo {sym} HTTP {r.status_code}"
                continue
            js = r.json()
            result = (((js or {}).get("chart") or {}).get("result") or [])
            if not result:
                err = (((js or {}).get("chart") or {}).get("error") or {})
                last_err = f"Yahoo {sym} 無資料 {err}"
                continue

            obj = result[0]
            meta = obj.get("meta") or {}
            price = to_float(meta.get("regularMarketPrice"))
            prev_close = to_float(meta.get("chartPreviousClose")) or to_float(meta.get("previousClose"))

            # regularMarketPrice 偶爾空白，改用最後一根 1m close。
            if price is None:
                try:
                    closes = (((obj.get("indicators") or {}).get("quote") or [{}])[0] or {}).get("close") or []
                    closes = [to_float(x) for x in closes if to_float(x) is not None]
                    if closes:
                        price = closes[-1]
                except Exception:
                    pass
            if price is None:
                last_err = f"Yahoo {sym} 即時價空白"
                continue

            ts = meta.get("regularMarketTime")
            dt_tw = None
            if ts:
                try:
                    dt_tw = pd.to_datetime(int(ts), unit="s", utc=True).tz_convert("Asia/Taipei")
                except Exception:
                    dt_tw = None
            if dt_tw is not None:
                qdate_s = dt_tw.strftime("%Y-%m-%d")
                qtime_s = dt_tw.strftime("%H:%M:%S")
            else:
                now_tw = datetime.utcnow() + timedelta(hours=8)
                qdate_s = now_tw.strftime("%Y-%m-%d")
                qtime_s = now_tw.strftime("%H:%M:%S")

            return {
                "ok": True,
                "code": code,
                "name": meta.get("shortName") or meta.get("longName") or "",
                "exchange_channel": sym,
                "price": price,
                "open": to_float(meta.get("regularMarketOpen")) or price,
                "high": to_float(meta.get("regularMarketDayHigh")) or price,
                "low": to_float(meta.get("regularMarketDayLow")) or price,
                "prev_close": prev_close,
                "volume": to_float(meta.get("regularMarketVolume")),
                "date": qdate_s,
                "time": qtime_s,
                "change": (price - prev_close) if prev_close not in [None, 0] else None,
                "change_pct": pct_change(price, prev_close) if prev_close not in [None, 0] else None,
                "source": "Yahoo Finance 備援",
                "raw": meta,
            }, ""
        except Exception as e:
            last_err = f"Yahoo {sym} {e}"

    return None, last_err or "Yahoo 即時報價抓取失敗"


@st.cache_data(ttl=8, show_spinner=False)
def fetch_realtime_quote(stock):
    """抓台股盤中即時報價。

    用途：
    - 主頁顯示即時股價。
    - 支撐壓力圖最右側補一根「今日盤中未收K」。
    注意：這根盤中K只顯示，不參與支撐壓力線計算。
    """
    code = clean_text(stock)
    if not code:
        return None, "股票代號空白"

    # 先試上市 tse，再試上櫃 otc。
    channels = [f"tse_{code}.tw", f"otc_{code}.tw"]
    last_err = ""
    headers = {
        "User-Agent": "Mozilla/5.0",
        "Referer": f"https://mis.twse.com.tw/stock/fibest.jsp?stock={code}",
    }

    for ch in channels:
        try:
            ts = int(datetime.now().timestamp() * 1000)
            r = requests.get(
                "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
                params={"ex_ch": ch, "json": "1", "delay": "0", "_": ts},
                headers=headers,
                timeout=8,
            )
            if r.status_code != 200:
                last_err = f"{ch} HTTP {r.status_code}"
                continue

            try:
                js = r.json()
            except Exception:
                js = _json.loads(r.text)

            arr = js.get("msgArray", []) if isinstance(js, dict) else []
            if not arr:
                last_err = f"{ch} 無即時資料"
                continue

            item = arr[0]
            rt_price = _quote_num(item.get("z"))
            # 盤中還沒成交時，z 可能是 -，先嘗試用揭示買/賣價替代。
            if rt_price is None:
                rt_price = _quote_num(item.get("a")) or _quote_num(item.get("b"))

            open_p = _quote_num(item.get("o"))
            high_p = _quote_num(item.get("h"))
            low_p = _quote_num(item.get("l"))
            prev_close = _quote_num(item.get("y"))
            volume = _quote_num(item.get("v"))

            # fix76｜TWSE MIS 有時盤中 high/low/open 會回傳 0 或空值。
            # 0 不能拿來畫 K 棒，否則會出現從現價直插到 0 的錯誤長下影線。
            if open_p is not None and open_p <= 0:
                open_p = None
            if high_p is not None and high_p <= 0:
                high_p = None
            if low_p is not None and low_p <= 0:
                low_p = None
            if prev_close is not None and prev_close <= 0:
                prev_close = None

            if rt_price is None:
                last_err = f"{ch} 即時成交價空白"
                continue

            qdate = _quote_date_to_timestamp(item.get("d"))
            qtime = str(item.get("t") or "").strip()
            qdate_s = ""
            if not pd.isna(qdate):
                qdate_s = qdate.strftime("%Y-%m-%d")
            if qtime and len(qtime) == 6 and qtime.isdigit():
                qtime_s = f"{qtime[:2]}:{qtime[2:4]}:{qtime[4:]}"
            else:
                qtime_s = qtime or datetime.now().strftime("%H:%M:%S")

            if open_p is None:
                open_p = prev_close if prev_close is not None else rt_price
            if high_p is None:
                high_p = max(open_p, rt_price)
            if low_p is None:
                low_p = min(open_p, rt_price)

            return {
                "ok": True,
                "code": code,
                "name": item.get("n") or "",
                "exchange_channel": ch,
                "price": rt_price,
                "open": open_p,
                "high": max(high_p, open_p, rt_price),
                "low": min(low_p, open_p, rt_price),
                "prev_close": prev_close,
                "volume": volume,
                "date": qdate_s,
                "time": qtime_s,
                "change": (rt_price - prev_close) if prev_close not in [None, 0] else None,
                "change_pct": pct_change(rt_price, prev_close) if prev_close not in [None, 0] else None,
                "source": "TWSE MIS",
                "raw": item,
            }, ""

        except Exception as e:
            last_err = f"{ch} {e}"

    # TWSE MIS 若失敗，改用 Yahoo Finance 備援，避免盤中主畫面退回「最近收盤」。
    yahoo_quote, yahoo_err = _fetch_yahoo_realtime_quote_fallback(code)
    if yahoo_quote:
        return yahoo_quote, ""

    if yahoo_err:
        last_err = f"{last_err}；{yahoo_err}" if last_err else yahoo_err
    return None, last_err or "即時報價抓取失敗"


@st.cache_data(ttl=8, show_spinner=False)
def fetch_market_realtime_quote():
    """抓加權指數盤中即時報價，給首頁大盤支撐壓力圖補盤中K。"""
    headers = {
        "User-Agent": "Mozilla/5.0",
        "Referer": "https://mis.twse.com.tw/stock/fibest.jsp?stock=t00",
    }
    try:
        ts = int(datetime.now().timestamp() * 1000)
        r = requests.get(
            "https://mis.twse.com.tw/stock/api/getStockInfo.jsp",
            params={"ex_ch": "tse_t00.tw", "json": "1", "delay": "0", "_": ts},
            headers=headers,
            timeout=8,
        )
        if r.status_code != 200:
            return None, f"HTTP {r.status_code}"

        try:
            js = r.json()
        except Exception:
            js = _json.loads(r.text)

        arr = js.get("msgArray", []) if isinstance(js, dict) else []
        if not arr:
            return None, "加權指數即時資料空白"

        item = arr[0]
        rt_price = _quote_num(item.get("z"))
        open_p = _quote_num(item.get("o"))
        high_p = _quote_num(item.get("h"))
        low_p = _quote_num(item.get("l"))
        prev_close = _quote_num(item.get("y"))
        volume = _quote_num(item.get("v"))

        # fix76｜即時資料若出現 0，不能拿來畫盤中 K 棒。
        if open_p is not None and open_p <= 0:
            open_p = None
        if high_p is not None and high_p <= 0:
            high_p = None
        if low_p is not None and low_p <= 0:
            low_p = None
        if prev_close is not None and prev_close <= 0:
            prev_close = None

        if rt_price is None:
            return None, "加權指數即時價空白"
        if open_p is None:
            open_p = prev_close if prev_close is not None else rt_price
        if high_p is None:
            high_p = max(open_p, rt_price)
        if low_p is None:
            low_p = min(open_p, rt_price)

        qdate = _quote_date_to_timestamp(item.get("d"))
        qtime = str(item.get("t") or "").strip()
        qdate_s = qdate.strftime("%Y-%m-%d") if not pd.isna(qdate) else ""
        qtime_s = f"{qtime[:2]}:{qtime[2:4]}:{qtime[4:]}" if qtime and len(qtime) == 6 and qtime.isdigit() else (qtime or datetime.now().strftime("%H:%M:%S"))

        return {
            "ok": True,
            "code": "TAIEX",
            "name": "加權指數",
            "exchange_channel": "tse_t00.tw",
            "price": rt_price,
            "open": open_p,
            "high": max(high_p, open_p, rt_price),
            "low": min(low_p, open_p, rt_price),
            "prev_close": prev_close,
            "volume": volume,
            "date": qdate_s,
            "time": qtime_s,
            "change": (rt_price - prev_close) if prev_close not in [None, 0] else None,
            "change_pct": pct_change(rt_price, prev_close) if prev_close not in [None, 0] else None,
            "source": "TWSE MIS tse_t00.tw",
            "raw": item,
        }, ""

    except Exception as e:
        return None, str(e)


def _append_intraday_k_to_chart_df(df, realtime_quote):
    """在圖表最右側補今日盤中K。只供顯示，不改變支撐壓力線來源。"""
    if df is None or getattr(df, "empty", True) or not realtime_quote:
        return df, False

    q_price = to_float(realtime_quote.get("price"))
    q_date = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
    if q_price is None or pd.isna(q_date):
        return df, False

    work = df.copy().sort_values("date").reset_index(drop=True)
    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")
    if pd.isna(last_date):
        return work, False

    # 若資料源已經有今日日K，先不覆蓋，避免把已完成日K誤改成盤中K。
    if q_date.normalize() <= last_date.normalize():
        return work, False

    # fix76｜盤中 K 棒只能用有效 OHLC。
    # TWSE MIS / 備援來源若回傳 0，會把 K 棒畫成從現價直插到 0；這裡統一防呆。
    last_close = to_float(work["close"].iloc[-1])
    q_prev_close = to_float(realtime_quote.get("prev_close")) or last_close or q_price

    q_open = to_float(realtime_quote.get("open"))
    q_high = to_float(realtime_quote.get("high"))
    q_low = to_float(realtime_quote.get("low"))
    q_volume = to_float(realtime_quote.get("volume")) or 0

    if q_open is None or q_open <= 0:
        q_open = q_prev_close if q_prev_close and q_prev_close > 0 else q_price
    if q_high is None or q_high <= 0:
        q_high = max(q_open, q_price)
    if q_low is None or q_low <= 0:
        q_low = min(q_open, q_price)

    q_high = max(q_high, q_open, q_price)
    q_low = min(q_low, q_open, q_price)
    if q_low <= 0:
        q_low = min(q_open, q_price)

    new_row = {
        "date": q_date,
        "open": q_open,
        "max": q_high,
        "min": q_low,
        "close": q_price,
        "Trading_Volume": q_volume,
    }
    for c in work.columns:
        if c not in new_row:
            # 盤中 K 只供顯示，不參與均線 / 支撐壓力 / 法醫裁決計算。
            new_row[c] = None

    work = pd.concat([work, pd.DataFrame([new_row])], ignore_index=True)
    return work, True


def _build_price_payload_from_ohlcv_df(df):
    """把已整理好的 OHLCV DataFrame 轉成和 fetch_price 相同的 price dict。"""
    if df is None or getattr(df, "empty", True):
        return None, "股價資料為空"

    df = df.copy().sort_values("date").reset_index(drop=True)
    for c in ["open", "max", "min", "close", "Trading_Volume"]:
        if c in df.columns:
            df[c] = df[c].apply(to_float)
    df = df.dropna(subset=["date", "open", "max", "min", "close"]).reset_index(drop=True)
    if df.empty:
        return None, "OHLC 資料清洗後為空"

    if "Trading_Volume" not in df.columns:
        df["Trading_Volume"] = 0
    df["Trading_Volume"] = df["Trading_Volume"].apply(to_float).fillna(0)

    df["MA5"] = df["close"].rolling(5).mean()
    df["MA10"] = df["close"].rolling(10).mean()
    df["MA20"] = df["close"].rolling(20).mean()
    df["MA60"] = df["close"].rolling(60).mean()
    df["MA120"] = df["close"].rolling(120).mean()
    df["VolMA20"] = df["Trading_Volume"].rolling(20).mean()

    last = df.iloc[-1]
    prev = df.iloc[-2] if len(df) >= 2 else last
    close = to_float(last["close"])
    prev_close = to_float(prev["close"])
    prev_high20 = df["close"].iloc[:-1].tail(20).max() if len(df) >= 21 else None
    high20 = df["close"].tail(20).max()
    low10 = df["close"].tail(10).min() if len(df) >= 10 else None
    low20 = df["close"].tail(20).min()
    high60 = df["close"].tail(60).max() if len(df) >= 60 else None
    low60 = df["close"].tail(60).min() if len(df) >= 60 else None
    volume_ratio = safe_div(last.get("Trading_Volume"), last.get("VolMA20"))
    breakout_now = (
        close is not None
        and prev_high20 is not None
        and volume_ratio is not None
        and close > prev_high20 * 1.005
        and volume_ratio >= 1.3
    )

    def ret(days):
        if len(df) <= days or close is None:
            return None
        return pct_change(close, df.iloc[-days - 1]["close"])

    ma20_slope_5 = (
        pct_change(last.get("MA20"), df.iloc[-6].get("MA20")) if len(df) >= 26 else None
    )
    ma60_slope_10 = (
        pct_change(last.get("MA60"), df.iloc[-11].get("MA60")) if len(df) >= 71 else None
    )
    drawdown20 = pct_change(close, high20) if close is not None and high20 else None
    drawdown60 = pct_change(close, high60) if close is not None and high60 else None
    volume_lot = (
        to_float(last.get("Trading_Volume")) / 1000
        if to_float(last.get("Trading_Volume")) is not None
        else None
    )

    return {
        "date": last["date"],
        "close": close,
        "change_pct": pct_change(close, prev_close),
        "ma5": to_float(last.get("MA5")),
        "ma10": to_float(last.get("MA10")),
        "ma20": to_float(last.get("MA20")),
        "ma60": to_float(last.get("MA60")),
        "ma120": to_float(last.get("MA120")),
        "ma20_slope_5": ma20_slope_5,
        "ma60_slope_10": ma60_slope_10,
        "ret5": ret(5),
        "ret20": ret(20),
        "ret60": ret(60),
        "drawdown20": drawdown20,
        "drawdown60": drawdown60,
        "volume_lot": volume_lot,
        "volume_ratio": volume_ratio,
        "high20": high20,
        "prev_high20": prev_high20,
        "low10": low10,
        "low20": low20,
        "high60": high60,
        "low60": low60,
        "breakout_now": breakout_now,
        "raw": df,
    }, ""


@st.cache_data(ttl=900, show_spinner=False)
def fetch_market_index_price():
    """抓台股加權指數 OHLCV。優先用 FinMind，失敗再用 yfinance。"""
    end = datetime.today().date()
    start = end - timedelta(days=420)
    errors = []

    # FinMind 有些環境可用 TAIEX 抓加權指數；若資料源不支援，會自動往下 fallback。
    for data_id in ["TAIEX", "IX0001"]:
        df, err = fm("TaiwanStockPrice", data_id, str(start), str(end))
        if not df.empty and {"date", "open", "max", "min", "close"}.issubset(set(df.columns)):
            df = df.copy()
            df["date"] = pd.to_datetime(df["date"], errors="coerce")
            if "Trading_Volume" not in df.columns:
                df["Trading_Volume"] = 0
            payload, payload_err = _build_price_payload_from_ohlcv_df(df[["date", "open", "max", "min", "close", "Trading_Volume"]])
            if payload:
                payload["source"] = f"FinMind TaiwanStockPrice/{data_id}"
                return payload, ""
            errors.append(f"{data_id}: {payload_err}")
        else:
            errors.append(f"{data_id}: {err or '查無OHLC資料'}")

    # yfinance 備援：^TWII 是台灣加權指數。部分環境 Volume 可能為 0，若如此量K線可能不足。
    if _YF_OK:
        try:
            yf_df = yf.download("^TWII", period="18mo", interval="1d", progress=False, auto_adjust=False)
            if yf_df is not None and not yf_df.empty:
                if isinstance(yf_df.columns, pd.MultiIndex):
                    yf_df.columns = [c[0] if isinstance(c, tuple) else c for c in yf_df.columns]
                yf_df = yf_df.reset_index()
                date_col = "Date" if "Date" in yf_df.columns else yf_df.columns[0]
                vol_col = "Volume" if "Volume" in yf_df.columns else None
                out = pd.DataFrame({
                    "date": pd.to_datetime(yf_df[date_col], errors="coerce"),
                    "open": yf_df["Open"],
                    "max": yf_df["High"],
                    "min": yf_df["Low"],
                    "close": yf_df["Close"],
                    "Trading_Volume": yf_df[vol_col] if vol_col else 0,
                })
                payload, payload_err = _build_price_payload_from_ohlcv_df(out)
                if payload:
                    payload["source"] = "yfinance ^TWII"
                    return payload, ""
                errors.append(f"yfinance: {payload_err}")
            else:
                errors.append("yfinance: 查無資料")
        except Exception as e:
            errors.append(f"yfinance: {e}")
    else:
        errors.append("yfinance: 未安裝")

    return None, "；".join(errors[:4])


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_revenue(stock):
    end = datetime.today().date()
    start = end - timedelta(days=1200)
    df, err = fm("TaiwanStockMonthRevenue", stock, str(start), str(end))
    if df.empty:
        return None, err
    if "date" not in df.columns:
        return None, "月營收缺 date"
    rev_col = pick_col(df.columns, ["revenue", "當月營收", "營業收入"])
    yoy_col = pick_col(
        df.columns, ["revenue_year_rate", "year_over_year", "yoy", "年增", "去年同月"]
    )
    mom_col = pick_col(
        df.columns, ["revenue_month_rate", "month_over_month", "mom", "月增", "上月"]
    )
    if rev_col is None:
        return None, f"找不到營收欄位：{list(df.columns)}"
    df = df.copy()
    df[rev_col] = df[rev_col].apply(to_float)
    if yoy_col:
        df[yoy_col] = df[yoy_col].apply(to_float)
    if mom_col:
        df[mom_col] = df[mom_col].apply(to_float)
    df["dt"] = pd.to_datetime(df["date"], errors="coerce")
    df = df.dropna(subset=["dt"]).sort_values("dt")
    latest = df.iloc[-1]
    rev = to_float(latest[rev_col])
    yoy = to_float(latest.get(yoy_col)) if yoy_col else None
    if yoy is None:
        ly = df[
            (df["dt"].dt.year == latest["dt"].year - 1)
            & (df["dt"].dt.month == latest["dt"].month)
        ]
        if not ly.empty:
            yoy = pct_change(rev, ly.iloc[-1][rev_col])
    mom = to_float(latest.get(mom_col)) if mom_col else None
    if mom is None and len(df) >= 2:
        mom = pct_change(rev, df.iloc[-2][rev_col])
    y = latest["dt"].year
    m = latest["dt"].month
    ytd = df[(df["dt"].dt.year == y) & (df["dt"].dt.month <= m)][rev_col].sum()
    lytd = df[(df["dt"].dt.year == y - 1) & (df["dt"].dt.month <= m)][rev_col].sum()
    ytd_yoy = pct_change(ytd, lytd)
    yoy_list = []
    for _, row in df.tail(3).iterrows():
        val = to_float(row.get(yoy_col)) if yoy_col else None
        if val is None:
            ly = df[
                (df["dt"].dt.year == row["dt"].year - 1)
                & (df["dt"].dt.month == row["dt"].month)
            ]
            if not ly.empty:
                val = pct_change(row[rev_col], ly.iloc[-1][rev_col])
        if val is not None:
            yoy_list.append(val)
    return {
        "date": str(latest["date"]),
        "revenue": rev,
        "revenue_100m": rev / 100_000_000 if rev is not None else None,
        "yoy": yoy,
        "mom": mom,
        "ytd": ytd,
        "ytd_100m": ytd / 100_000_000 if ytd is not None else None,
        "ytd_yoy": ytd_yoy,
        "yoy_list": yoy_list,
        "raw": df.drop(columns=["dt"]),
    }, ""


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_inst(stock):
    end = datetime.today().date()
    start = end - timedelta(days=90)
    df, err = fm(
        "TaiwanStockInstitutionalInvestorsBuySell",
        stock,
        str(start),
        str(end),
    )
    if df.empty:
        return None, err
    buy_col = pick_col(df.columns, ["buy", "買"])
    sell_col = pick_col(df.columns, ["sell", "賣"])
    name_col = pick_col(df.columns, ["name", "investor", "法人"])
    if buy_col is None or sell_col is None:
        return None, f"找不到買賣欄位：{list(df.columns)}"
    df = df.copy()
    df[buy_col] = df[buy_col].apply(to_float)
    df[sell_col] = df[sell_col].apply(to_float)
    df["net"] = df[buy_col] - df[sell_col]
    if name_col:
        df["investor_zh"] = df[name_col].apply(investor_display_name)
    daily = df.groupby("date", as_index=False)["net"].sum().sort_values("date")
    last5 = daily.tail(5)
    last20 = daily.tail(20)
    consecutive_buy = 0
    for v in reversed(daily["net"].tolist()):
        if v > 0:
            consecutive_buy += 1
        else:
            break
    consecutive_sell = 0
    for v in reversed(daily["net"].tolist()):
        if v < 0:
            consecutive_sell += 1
        else:
            break
    latest_by_type = []
    foreign_net5_lot = None
    trust_net5_lot = None
    if name_col:
        tmp = df[df["date"] == daily.iloc[-1]["date"]].copy()
        tmp["net_lot"] = (tmp["net"] / 1000).round(0).astype("Int64")
        tmp["法人"] = tmp["investor_zh"]
        latest_by_type = tmp[["法人", "net_lot"]].to_dict("records")

        _last5_dates = set(last5["date"].tolist())
        _type5 = df[df["date"].isin(_last5_dates)].copy()
        foreign_net5_lot = int(round(_type5[_type5["investor_zh"] == "外資"]["net"].sum() / 1000))
        trust_net5_lot = int(round(_type5[_type5["investor_zh"] == "投信"]["net"].sum() / 1000))

        _last20_dates = set(last20["date"].tolist())
        _type20 = df[df["date"].isin(_last20_dates)].copy()
        foreign_net20_lot = int(round(_type20[_type20["investor_zh"] == "外資"]["net"].sum() / 1000))
        trust_net20_lot = int(round(_type20[_type20["investor_zh"] == "投信"]["net"].sum() / 1000))

    daily_out = daily.copy()
    daily_out["net_lot"] = (daily_out["net"] / 1000).round(0).astype("Int64")
    return {
        "latest_date": daily.iloc[-1]["date"],
        "net5_lot": int(round(last5["net"].sum() / 1000)),
        "foreign_net5_lot": foreign_net5_lot,
        "trust_net5_lot": trust_net5_lot,
        "foreign_net20_lot": locals().get("foreign_net20_lot"),
        "trust_net20_lot": locals().get("trust_net20_lot"),
        "net20_lot": int(round(last20["net"].sum() / 1000)),
        "positive_days_5": int((last5["net"] > 0).sum()),
        "negative_days_5": int((last5["net"] < 0).sum()),
        "positive_days_20": int((last20["net"] > 0).sum()),
        "negative_days_20": int((last20["net"] < 0).sum()),
        "consecutive_sell": consecutive_sell,
        "consecutive_buy": consecutive_buy,
        "latest_by_type": latest_by_type,
        "daily": daily_out,
        "raw": df,
    }, ""


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_financial(stock):
    end = datetime.today().date()
    start = end - timedelta(days=1900)
    df, err = fm("TaiwanStockFinancialStatements", stock, str(start), str(end))
    if df.empty:
        return None, err
    p = long_to_pivot(df)
    if p.empty:
        return None, "財報轉換後為空"
    cols = p.columns
    rev = pick_col(
        cols, ["Revenue", "OperatingRevenue", "營業收入合計", "營業收入", "收入合計"]
    )
    gp = pick_col(cols, ["GrossProfit", "GrossProfitLoss", "營業毛利", "毛利"])
    op = pick_col(cols, ["OperatingIncome", "OperatingProfit", "營業利益", "營業淨利"])
    net = pick_col(cols, ["NetIncome", "ProfitLoss", "本期淨利", "稅後淨利", "淨利"])
    eps = pick_col(
        cols,
        [
            "EPS",
            "EarningsPerShare",
            "BasicEarningsPerShare",
            "基本每股盈餘",
            "每股盈餘",
        ],
    )
    latest, prev, ly = latest_prev_yoy(p)
    eps_series, eps_ttm_note, eps_cumulative_suspect = normalize_eps_series_for_ttm(
        p, eps
    )
    ttm_eps = sum(eps_series) if len(eps_series) >= 4 else None
    lr = rowv(latest, rev)
    lg = rowv(latest, gp)
    lo = rowv(latest, op)
    ln = rowv(latest, net)
    le = rowv(latest, eps)
    pr = rowv(prev, rev)
    pg = rowv(prev, gp)
    po = rowv(prev, op)
    yr = rowv(ly, rev)
    yg = rowv(ly, gp)
    yo = rowv(ly, op)
    ye = rowv(ly, eps)
    return {
        "date": latest.get("date") if latest is not None else None,
        "revenue": lr,
        "revenue_yoy": pct_change(lr, yr),
        "gross_profit": lg,
        "op_income": lo,
        "net_income": ln,
        "eps": le,
        "eps_yoy": pct_change(le, ye),
        "ttm_eps": ttm_eps,
        "eps_series": eps_series,
        "eps_series_used": eps_series,
        "eps_ttm_note": eps_ttm_note,
        "eps_cumulative_suspect": eps_cumulative_suspect,
        "annualized_eps": le * 4 if le is not None else None,
        "gross_margin": safe_div(lg, lr) * 100
        if safe_div(lg, lr) is not None
        else None,
        "gross_margin_prev": safe_div(pg, pr) * 100
        if safe_div(pg, pr) is not None
        else None,
        "gross_margin_yoy": safe_div(yg, yr) * 100
        if safe_div(yg, yr) is not None
        else None,
        "op_margin": safe_div(lo, lr) * 100 if safe_div(lo, lr) is not None else None,
        "op_margin_prev": safe_div(po, pr) * 100
        if safe_div(po, pr) is not None
        else None,
        "op_margin_yoy": safe_div(yo, yr) * 100
        if safe_div(yo, yr) is not None
        else None,
        "net_margin": safe_div(ln, lr) * 100 if safe_div(ln, lr) is not None else None,
        "raw": df,
        "pivot": p,
        "cols": {
            "revenue": rev,
            "gross": gp,
            "op": op,
            "net": net,
            "eps": eps,
        },
    }, ""


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_balance(stock):
    end = datetime.today().date()
    start = end - timedelta(days=1900)
    df, err = fm("TaiwanStockBalanceSheet", stock, str(start), str(end))
    if df.empty:
        return None, err
    p = long_to_pivot(df)
    cols = p.columns
    inv = pick_col(cols, ["Inventory", "Inventories", "存貨"])
    ar = pick_col(cols, ["AccountsReceivable", "Receivable", "應收帳款", "應收款項"])
    liab = pick_col(cols, ["TotalLiabilities", "負債總計", "總負債", "負債合計"])
    asset = pick_col(cols, ["TotalAssets", "資產總計", "總資產", "資產合計"])
    current_assets = pick_col(cols, ["CurrentAssets", "流動資產", "流動資產合計", "流動資產總計"])
    current_liabilities = pick_col(cols, ["CurrentLiabilities", "流動負債", "流動負債合計", "流動負債總計"])
    cash_eq = pick_col(cols, [
        "CashAndCashEquivalents",
        "CashAndCashEquivalentsAtCarryingValue",
        "Cash",
        "現金及約當現金",
        "現金及約當現金合計",
    ])

    latest, prev, ly = latest_prev_yoy(p)
    invv = rowv(latest, inv)
    arv = rowv(latest, ar)
    liabv = rowv(latest, liab)
    assetv = rowv(latest, asset)
    cav = rowv(latest, current_assets)
    clv = rowv(latest, current_liabilities)
    cashv = rowv(latest, cash_eq)
    inv_prev = rowv(prev, inv)
    ar_prev = rowv(prev, ar)

    quick_assets = None
    if cav is not None:
        quick_assets = cav - (invv or 0)

    return {
        "date": latest.get("date") if latest is not None else None,
        "inventory": invv,
        "inventory_prev": inv_prev,
        "inventory_yoy": pct_change(invv, rowv(ly, inv)),
        "ar": arv,
        "ar_prev": ar_prev,
        "ar_yoy": pct_change(arv, rowv(ly, ar)),
        "liabilities": liabv,
        "liabilities_yoy": pct_change(liabv, rowv(ly, liab)),
        "assets": assetv,
        "current_assets": cav,
        "current_liabilities": clv,
        "cash": cashv,
        "debt_ratio": safe_div(liabv, assetv) * 100
        if safe_div(liabv, assetv) is not None
        else None,
        "current_ratio": safe_div(cav, clv) * 100 if safe_div(cav, clv) is not None else None,
        "quick_ratio": safe_div(quick_assets, clv) * 100 if safe_div(quick_assets, clv) is not None else None,
        "cash_to_current_liab": safe_div(cashv, clv) * 100 if safe_div(cashv, clv) is not None else None,
        "raw": df,
        "pivot": p,
        "cols": {
            "inventory": inv,
            "ar": ar,
            "liabilities": liab,
            "assets": asset,
            "current_assets": current_assets,
            "current_liabilities": current_liabilities,
            "cash": cash_eq,
        },
    }, ""


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_cashflow(stock):
    end = datetime.today().date()
    start = end - timedelta(days=1900)
    df, err = fm("TaiwanStockCashFlowsStatement", stock, str(start), str(end))
    if df.empty:
        return None, err
    p = long_to_pivot(df)
    cols = p.columns
    ocf = pick_col(
        cols,
        [
            "CashFlowsFromOperatingActivities",
            "OperatingCashFlow",
            "營業活動之淨現金流入",
            "營業活動現金流量",
            "營業活動",
        ],
    )
    capex = pick_col(
        cols,
        [
            "CapitalExpenditure",
            "AcquisitionOfPropertyPlantAndEquipment",
            "取得不動產廠房及設備",
            "資本支出",
        ],
    )
    latest, prev, ly = latest_prev_yoy(p)
    ocfv = rowv(latest, ocf)
    capexv = rowv(latest, capex)
    fcf = None
    if ocfv is not None and capexv is not None:
        fcf = ocfv + capexv if capexv < 0 else ocfv - capexv
    return {
        "date": latest.get("date") if latest is not None else None,
        "ocf": ocfv,
        "ocf_yoy": pct_change(ocfv, rowv(ly, ocf)),
        "capex": capexv,
        "fcf": fcf,
        "raw": df,
        "pivot": p,
        "cols": {
            "ocf": ocf,
            "capex": capex,
        },
    }, ""




@st.cache_data(ttl=3600, show_spinner=False)
def fetch_market_valuation(stock):
    """抓 FinMind TaiwanStockPER：PER / PBR / 殖利率。
    用途：
    - PBR → 反推 BVPS = 股價 / PBR，供 P/B 估值子模組使用。
    - PER / dividend_yield 僅作輔助顯示與防呆。
    """
    end = datetime.today().date()
    start = end - timedelta(days=500)
    try:
        df, err = fm("TaiwanStockPER", stock, str(start), str(end))
    except Exception as e:
        return None, f"TaiwanStockPER 抓取失敗：{e}"
    if df is None or df.empty:
        return None, err or "TaiwanStockPER 無資料"
    df = df.copy()
    if "date" in df.columns:
        df = df.sort_values("date")
    latest = df.iloc[-1]
    cols = list(df.columns)

    def _pick_any(row, names):
        for n in names:
            if n in row.index:
                return to_float(row.get(n))
        # 寬鬆比對
        for c in row.index:
            cs = str(c).lower()
            for n in names:
                if str(n).lower() == cs or str(n).lower() in cs:
                    return to_float(row.get(c))
        return None

    per = _pick_any(latest, ["PER", "pe", "PEratio", "本益比"])
    pbr = _pick_any(latest, ["PBR", "pb", "股價淨值比"])
    dy = _pick_any(latest, ["dividend_yield", "DividendYield", "殖利率", "殖利率(%)"])
    return {
        "date": latest.get("date") if "date" in latest.index else None,
        "per": per,
        "pbr": pbr,
        "dividend_yield": dy,
        "raw": df,
    }, ""


# =========================
# 防卡 Timeout 包裝
# =========================
_FETCH_TIMEOUT = 20  # 秒


def fetch_with_timeout(fn, stock, timeout=_FETCH_TIMEOUT):
    """執行 fetch_* 函式，若超過 timeout 秒就回傳 (None, 錯誤訊息)。"""
    with _cf.ThreadPoolExecutor(max_workers=1) as _ex:
        _fut = _ex.submit(fn, stock)
        try:
            return _fut.result(timeout=timeout)
        except _cf.TimeoutError:
            return None, f"抓取超時（>{timeout}秒），已跳過"
        except Exception as _e:
            return None, f"抓取失敗：{_e}"


# =========================
# 法醫判斷
# =========================
def judge_price(price):
    if not price:
        return {"score": 0, "bias": "中性", "text": "股價資料不足", "fatal": False}
    close, ma20, ma60 = price.get("close"), price.get("ma20"), price.get("ma60")
    if close is None or ma20 is None or ma60 is None:
        return {"score": 0, "bias": "中性", "text": "均線資料不足", "fatal": False}

    ma60_floor = ma60 * 0.96  # Nick 規則：MA60 可容忍跌破 4% 內，視為支撐測試

    if close > ma20 > ma60:
        if close / ma20 > 1.15:
            return {
                "score": 1,
                "bias": "偏多",
                "text": "多頭排列，但短線乖離偏大",
                "fatal": False,
            }
        return {
            "score": 2,
            "bias": "偏多",
            "text": "站上 20 日與 60 日均線，技術偏強",
            "fatal": False,
        }

    if close < ma20 and close >= ma60_floor:
        return {
            "score": 0 if close < ma60 else 1,
            "bias": "中性",
            "text": "短線回測支撐，MA60 跌破 4% 內仍視為正常回測 / 支撐測試",
            "fatal": False,
        }

    if close < ma20 and close < ma60_floor:
        return {
            "score": -2,
            "bias": "偏空",
            "text": "跌破 20 日均線且低於 MA60 容忍區，技術轉弱",
            "fatal": True,
        }

    return {
        "score": 0,
        "bias": "中性",
        "text": "技術面中性，等方向",
        "fatal": False,
    }


def judge_revenue(rev):
    if not rev:
        return {
            "score": 0,
            "bias": "中性",
            "level": "觀察",
            "text": "月營收資料不足",
        }
    y, yy = rev.get("yoy"), rev.get("ytd_yoy")
    score, txt = 0, []
    if y is not None:
        if y >= 30:
            score += 3
            txt.append("最新月營收年增超過 30%，動能強")
        elif y >= 10:
            score += 2
            txt.append("最新月營收年增超過 10%，正向")
        elif y >= 0:
            txt.append("最新月營收持平偏弱")
        else:
            score -= 2
            txt.append("最新月營收年減")
    if yy is not None:
        if yy >= 20:
            score += 2
            txt.append("累計營收年增強")
        elif yy >= 5:
            score += 1
            txt.append("累計營收小幅成長")
        elif yy < 0:
            score -= 1
            txt.append("累計營收年減")
    yl = rev.get("yoy_list", [])
    if len(yl) >= 3:
        if yl[-1] > yl[-2] > yl[-3]:
            score += 1
            txt.append("近三月年增率連續升溫")
        elif yl[-1] < yl[-2] < yl[-3]:
            score -= 1
            txt.append("近三月年增率連續降溫")
    level = (
        "強" if score >= 5 else "正向" if score >= 2 else "普通" if score >= 0 else "弱"
    )
    bias = "偏多" if score >= 2 else "中性" if score >= 0 else "偏空"
    return {
        "score": score,
        "bias": bias,
        "level": level,
        "text": "；".join(txt),
    }


def _ability_level(score):
    score = to_float(score)
    if score is None:
        return "資料不足"
    if score >= 75:
        return "強"
    if score >= 60:
        return "穩"
    if score >= 45:
        return "觀察"
    return "弱"


def build_financial_ability_radar(fin, bal, cf):
    """財務能力雷達：獲利、現金流、償債、經營效率。

    資料來源使用目前 app 已聯網抓取的 FinMind 財報 / 資產負債表 / 現金流量表。
    分數是法醫風險篩檢，不是單獨買進理由。
    """

    def _score_profitability():
        if not fin:
            return None, "資料不足"
        gm = to_float(fin.get("gross_margin"))
        om = to_float(fin.get("op_margin"))
        nm = to_float(fin.get("net_margin"))
        eps = to_float(fin.get("eps"))
        eps_yoy = to_float(fin.get("eps_yoy"))
        score = 35
        if gm is not None:
            score += 20 if gm >= 40 else 15 if gm >= 25 else 8 if gm >= 15 else -8
        if om is not None:
            score += 20 if om >= 20 else 14 if om >= 10 else 6 if om >= 5 else -10
        if nm is not None:
            score += 15 if nm >= 15 else 10 if nm >= 8 else 5 if nm > 0 else -12
        if eps is not None:
            score += 12 if eps > 0 else -20
        if eps_yoy is not None:
            score += 13 if eps_yoy >= 20 else 8 if eps_yoy >= 0 else -8
        score = clamp(score, 0, 100)
        if score >= 75:
            txt = "獲利能力強，毛利 / EPS 有支撐"
        elif score >= 60:
            txt = "獲利能力穩，仍要看 EPS 能否續航"
        elif score >= 45:
            txt = "獲利普通，需看毛利率與 EPS 能否改善"
        else:
            txt = "獲利偏弱，基本面支撐要打折"
        return score, txt

    def _score_cashflow():
        if not cf:
            return None, "資料不足"
        ocf = to_float(cf.get("ocf"))
        fcf = to_float(cf.get("fcf"))
        ocf_yoy = to_float(cf.get("ocf_yoy"))
        net_income = to_float(fin.get("net_income")) if fin else None
        ocf_to_net = safe_div(ocf, net_income) if ocf is not None and net_income not in [None, 0] else None
        score = 40
        if ocf is not None:
            score += 25 if ocf > 0 else -25
        if fcf is not None:
            score += 18 if fcf >= 0 else -8
        if ocf_to_net is not None:
            score += 12 if ocf_to_net >= 1 else 8 if ocf_to_net >= 0.6 else -8
        if ocf_yoy is not None:
            score += 5 if ocf_yoy >= 0 else -5
        score = clamp(score, 0, 100)
        if score >= 75:
            txt = "現金流有跟上，獲利比較不是紙上富貴"
        elif score >= 60:
            txt = "現金流大致正常，仍需持續追蹤"
        elif score >= 45:
            txt = "現金流普通，獲利品質需觀察"
        else:
            txt = "現金流偏弱，獲利可信度要打折"
        return score, txt

    def _score_solvency():
        if not bal:
            return None, "資料不足"
        debt_ratio = to_float(bal.get("debt_ratio"))
        current_ratio = to_float(bal.get("current_ratio"))
        quick_ratio = to_float(bal.get("quick_ratio"))
        cash_cover = to_float(bal.get("cash_to_current_liab"))
        score = 50
        if debt_ratio is not None:
            score += 25 if debt_ratio <= 40 else 15 if debt_ratio <= 60 else 5 if debt_ratio <= 70 else -18
        if current_ratio is not None:
            score += 18 if current_ratio >= 180 else 12 if current_ratio >= 120 else 5 if current_ratio >= 100 else -15
        if quick_ratio is not None:
            score += 12 if quick_ratio >= 120 else 6 if quick_ratio >= 80 else -8
        if cash_cover is not None:
            score += 8 if cash_cover >= 50 else 4 if cash_cover >= 20 else 0
        score = clamp(score, 0, 100)
        if score >= 75:
            txt = "償債壓力低，資金安全感較高"
        elif score >= 60:
            txt = "償債能力正常，短期壓力不明顯"
        elif score >= 45:
            txt = "償債能力普通，需留意負債與流動性"
        else:
            txt = "償債壓力偏高，需保守看待"
        return score, txt

    def _score_operation():
        if not bal:
            return None, "資料不足"
        rev_yoy = to_float(fin.get("revenue_yoy")) if fin else None
        revenue = to_float(fin.get("revenue")) if fin else None
        inv_yoy = to_float(bal.get("inventory_yoy"))
        ar_yoy = to_float(bal.get("ar_yoy"))
        inv = to_float(bal.get("inventory"))
        inv_prev = to_float(bal.get("inventory_prev"))
        ar = to_float(bal.get("ar"))
        ar_prev = to_float(bal.get("ar_prev"))
        avg_inv = ((inv or 0) + (inv_prev or 0)) / 2 if inv is not None and inv_prev is not None else None
        avg_ar = ((ar or 0) + (ar_prev or 0)) / 2 if ar is not None and ar_prev is not None else None
        inv_turnover = safe_div(revenue, avg_inv) if revenue is not None and avg_inv not in [None, 0] else None
        ar_turnover = safe_div(revenue, avg_ar) if revenue is not None and avg_ar not in [None, 0] else None
        score = 55
        if inv_yoy is not None and rev_yoy is not None:
            if inv_yoy <= rev_yoy + 15:
                score += 18
            elif inv_yoy > rev_yoy + 30 and inv_yoy > 30:
                score -= 20
            else:
                score += 2
        if ar_yoy is not None and rev_yoy is not None:
            if ar_yoy <= rev_yoy + 15:
                score += 18
            elif ar_yoy > rev_yoy + 30 and ar_yoy > 30:
                score -= 20
            else:
                score += 2
        if inv_turnover is not None:
            score += 5 if inv_turnover >= 1 else -5 if inv_turnover < 0.35 else 0
        if ar_turnover is not None:
            score += 4 if ar_turnover >= 1 else -4 if ar_turnover < 0.35 else 0
        score = clamp(score, 0, 100)
        if score >= 75:
            txt = "經營效率佳，存貨 / 應收沒有明顯拖累"
        elif score >= 60:
            txt = "經營效率正常，存貨 / 應收目前可接受"
        elif score >= 45:
            txt = "經營效率普通，存貨或應收需追蹤"
        else:
            txt = "存貨或應收壓力偏高，基本面要打折"
        return score, txt

    modules = {
        "獲利能力": _score_profitability(),
        "現金流能力": _score_cashflow(),
        "償債能力": _score_solvency(),
        "經營能力": _score_operation(),
    }
    rows = []
    valid_scores = []
    for name, (score, desc) in modules.items():
        if score is not None:
            valid_scores.append(score)
        rows.append({
            "項目": name,
            "等級": _ability_level(score) if score is not None else "資料不足",
            "分數": int(round(score)) if score is not None else None,
            "說明": desc,
        })

    overall = sum(valid_scores) / len(valid_scores) if valid_scores else None
    level = _ability_level(overall)
    if overall is None:
        summary = "資料不足"
        quick = "財務能力資料不足，無法完整判斷。"
    else:
        weak = [r["項目"] for r in rows if r["分數"] is not None and r["分數"] < 45]
        watch = [r["項目"] for r in rows if r["分數"] is not None and 45 <= r["分數"] < 60]
        strong = [r["項目"] for r in rows if r["分數"] is not None and r["分數"] >= 75]
        summary = f"{level}｜{int(round(overall))}分"
        if weak:
            quick = f"財務能力{level}；{'、'.join(weak[:2])}偏弱，基本面支撐要打折。"
        elif watch:
            quick = f"財務能力{level}；{'、'.join(watch[:2])}需觀察。"
        elif strong:
            quick = f"財務能力{level}；{'、'.join(strong[:2])}表現較好，基本面支撐度較高。"
        else:
            quick = f"財務能力{level}；四項大致正常，基本面支撐度尚可。"

    return {
        "overall_score": overall,
        "summary": summary,
        "quick": quick,
        "rows": rows,
        "profitability": modules["獲利能力"][0],
        "cashflow": modules["現金流能力"][0],
        "solvency": modules["償債能力"][0],
        "operation": modules["經營能力"][0],
    }



# ============================================================
# v271｜財報訊號分類器＋企業主預期差雷達
# 目的：財報不是判決書，是企業行為留下的腳印。
#       不再單一指標扣分，而是把存貨、應收、現金流、負債、投資現金流、毛利變化
#       分類成「風險 / 普通 / 未來成長代價」，再交給預期差雷達。
# ============================================================

def _v271_score_level(score):
    if score is None:
        return "資料不足"
    try:
        score = float(score)
    except Exception:
        return "資料不足"
    if score >= 75:
        return "強"
    if score >= 60:
        return "穩"
    if score >= 45:
        return "觀察"
    return "弱"


def _v271_pct(x, default=None):
    """把資料來源可能給的 20 / 20% / 0.20 統一成百分點數值 20。"""
    try:
        v = to_float(x)
        if v is None:
            return default
        if abs(v) <= 2:
            return v * 100
        return v
    except Exception:
        return default


def _v271_ratio(x, default=None):
    """把資料來源可能給的 20 / 20% / 0.20 統一成 0.20。"""
    try:
        v = to_float(x)
        if v is None:
            return default
        if abs(v) > 2:
            return v / 100.0
        return v
    except Exception:
        return default


def _v271_signal_box(label, classification, risk_level, owner_view, cfo_view, evidence=None, action_hint=None):
    return {
        "label": label,
        "classification": classification,
        "risk_level": risk_level,
        "owner_view": owner_view,
        "cfo_view": cfo_view,
        "evidence": evidence or [],
        "action_hint": action_hint or "",
    }


def classify_financial_signals_v271(
    fin=None,
    bal=None,
    cf=None,
    fj=None,
    sector_money_flow=None,
    trend_status=None,
    model_key="",
    industry_category=None,
    **kwargs,
):
    """
    v271｜財報訊號分類器。

    同一個財報變化不直接判好壞，而先分類：
    - 營運解讀：這可能是公司正在布局未來，還是營運開始卡住？
    - CFO 風險提醒：哪些地方不能被故事合理化？
    """
    fin = fin or {}
    bal = bal or {}
    cf = cf or {}
    fj = fj or {}
    industry_category = str(industry_category or "").strip()

    rev_yoy = _v271_pct(fin.get("revenue_yoy"), None)
    rev_mom = _v271_pct(fin.get("revenue_mom"), None)
    cum_rev_yoy = _v271_pct(fin.get("cumulative_revenue_yoy"), None)
    eps_yoy = _v271_pct(fin.get("eps_yoy"), None)
    gm_yoy = _v271_pct(fin.get("gross_margin_yoy"), None)
    opm_yoy = _v271_pct(fin.get("operating_margin_yoy"), None)
    gm = to_float(fin.get("gross_margin"))
    opm = to_float(fin.get("op_margin"))

    inv_yoy = _v271_pct(bal.get("inventory_yoy") or fin.get("inventory_yoy"), None)
    ar_yoy = _v271_pct(bal.get("ar_yoy") or fin.get("receivable_yoy") or fin.get("ar_yoy"), None)
    debt_ratio = to_float(bal.get("debt_ratio"))
    current_ratio = to_float(bal.get("current_ratio"))
    quick_ratio = to_float(bal.get("quick_ratio"))

    ocf = to_float(cf.get("ocf"))
    fcf = to_float(cf.get("fcf"))
    capex = to_float(cf.get("capex"))
    ocf_yoy = _v271_pct(cf.get("ocf_yoy"), None)

    inv_ar_status = str(fj.get("inv_ar") or "").strip()
    cashflow_status = str(fj.get("cashflow") or "").strip()
    margin_status = str(fj.get("margin") or "").strip()
    eps_status = str(fj.get("eps") or "").strip()
    revenue_to_eps = str(fj.get("revenue_to_eps") or "").strip()

    revenue_support = any(x is not None and x >= 10 for x in [rev_yoy, cum_rev_yoy, rev_mom])
    strong_revenue_support = any(x is not None and x >= 25 for x in [rev_yoy, cum_rev_yoy])
    margin_bad = (margin_status == "沒有") or (gm_yoy is not None and gm_yoy < -3) or (opm_yoy is not None and opm_yoy < -3)
    margin_ok = margin_status in ["有", "普通", "", "無法判斷"] and not margin_bad
    eps_bad = eps_status == "沒有" or (eps_yoy is not None and eps_yoy < -10)
    cash_bad = cashflow_status == "不配合" or (ocf is not None and ocf < 0 and fcf is not None and fcf < 0)
    sector_hot = str(sector_money_flow or "").lower() in ["strong", "hyper_active", "hot", "active", "資金強", "hyper"]
    trend_strong = str(trend_status or "").lower() in ["strong_up", "up", "bull", "right_up", "強勢"]

    signals = {}

    # 1) 存貨：備貨、觀察、堆貨
    inv_evidence = []
    if inv_yoy is not None: inv_evidence.append(f"存貨YoY約{inv_yoy:.1f}%")
    if rev_yoy is not None: inv_evidence.append(f"營收YoY約{rev_yoy:.1f}%")
    if cum_rev_yoy is not None: inv_evidence.append(f"累計營收YoY約{cum_rev_yoy:.1f}%")
    has_inv_alert = inv_ar_status in ["稍高", "偏高", "異常"] or (inv_yoy is not None and inv_yoy >= 20)
    if not has_inv_alert:
        inv_box = _v271_signal_box("存貨", "正常", "低", "存貨未見明顯異常。", "暫無需要因存貨調整估值。", inv_evidence, "維持原判斷")
    elif (strong_revenue_support or (revenue_support and (sector_hot or trend_strong))) and margin_ok and not eps_bad:
        inv_box = _v271_signal_box("存貨", "健康備貨", "中低", "存貨上升可能是為後續出貨、新訂單或旺季需求備貨。", "CFO 不折價，但要求 1～2 個月營收接棒驗證。", inv_evidence, "列入預期差觀察，不直接扣 PE")
    elif (rev_yoy is not None and rev_yoy < 3) and (cum_rev_yoy is None or cum_rev_yoy < 5) and (margin_bad or cash_bad or eps_bad):
        inv_box = _v271_signal_box("存貨", "危險堆貨", "高", "存貨增加沒有被營收與獲利解釋，較像東西賣不動或庫存壓力。", "CFO 啟動估值防守，限制 Re-rating。", inv_evidence, "PE 折價 / 禁追 / 需重新法醫")
    else:
        inv_box = _v271_signal_box("存貨", "中性觀察", "中", "存貨變化暫時無法判定是備貨或堆貨。", "CFO 不急著折價，但不允許因備貨想像直接升級。", inv_evidence, "等營收、毛利率、EPS 接棒")
    signals["inventory"] = inv_box

    # 2) 應收：大客戶放量、收款放寬、塞貨疑慮、呆帳風險
    ar_evidence = []
    if ar_yoy is not None: ar_evidence.append(f"應收YoY約{ar_yoy:.1f}%")
    if rev_yoy is not None: ar_evidence.append(f"營收YoY約{rev_yoy:.1f}%")
    if ocf is not None: ar_evidence.append(f"營業現金流{ocf:,.0f}")
    has_ar_alert = inv_ar_status in ["稍高", "偏高", "異常"] or (ar_yoy is not None and ar_yoy >= 20)
    if not has_ar_alert:
        ar_box = _v271_signal_box("應收帳款", "正常", "低", "應收未見明顯異常。", "暫不因應收調整估值。", ar_evidence, "維持原判斷")
    elif revenue_support and (ocf is None or ocf >= 0) and not eps_bad:
        ar_box = _v271_signal_box("應收帳款", "大客戶出貨放大", "中低", "應收增加可能來自大客戶出貨放大或收款週期拉長。", "CFO 要求現金流後續跟上，但不直接視為塞貨。", ar_evidence, "觀察現金轉換率 / 下季 OCF")
    elif revenue_support and (ocf is None or ocf >= 0):
        ar_box = _v271_signal_box("應收帳款", "收款條件放寬", "中", "營收有放大，但收款條件可能變寬。", "CFO 限制樂觀估值，等待現金流驗證。", ar_evidence, "限制重評，等 OCF")
    elif cash_bad or (rev_yoy is not None and rev_yoy < 3):
        ar_box = _v271_signal_box("應收帳款", "塞貨 / 呆帳風險", "高", "應收增加但營收與現金沒有接上，可能是塞貨或收款品質變差。", "CFO 啟動防守，不允許把營收成長全當真。", ar_evidence, "PE 折價 / 禁追")
    else:
        ar_box = _v271_signal_box("應收帳款", "中性觀察", "中", "應收增加需觀察客戶品質與現金回收。", "CFO 保留估值折價權。", ar_evidence, "看下一季 OCF")
    signals["receivable"] = ar_box

    # 3) 投資現金流 / CAPEX：成長型擴產、維持性支出、併購布局、現金消耗風險
    capex_evidence = []
    if capex is not None: capex_evidence.append(f"CAPEX/投資現金流約{capex:,.0f}")
    if ocf is not None: capex_evidence.append(f"OCF約{ocf:,.0f}")
    if fcf is not None: capex_evidence.append(f"FCF約{fcf:,.0f}")
    capex_outflow = capex is not None and capex < 0
    if not capex_outflow:
        invest_box = _v271_signal_box("投資現金流 / CAPEX", "未見明顯擴產訊號", "低", "投資支出沒有明顯放大。", "CFO 不因投資現金流調整估值。", capex_evidence, "維持原判斷")
    elif revenue_support and (ocf is None or ocf >= 0):
        invest_box = _v271_signal_box("投資現金流 / CAPEX", "成長型擴產", "中低", "投資流出可能是擴產、設備或產能布局，若後續營收接棒，可能是成長代價。", "CFO 不直接扣分，但要求資本支出轉成營收與 EPS。", capex_evidence, "列入未來 1～3 個月驗證點")
    elif (ocf is not None and ocf < 0) or (fcf is not None and fcf < 0 and not revenue_support):
        invest_box = _v271_signal_box("投資現金流 / CAPEX", "現金消耗風險", "高", "本業現金流沒跟上卻持續投資，可能是燒錢或被迫支出。", "CFO 降低估值容忍度。", capex_evidence, "限制 Re-rating / 觀察融資壓力")
    else:
        invest_box = _v271_signal_box("投資現金流 / CAPEX", "必要維持 / 待驗證", "中", "投資支出有放大，但暫時無法確認是成長型還是維持型。", "CFO 先列觀察，不給額外重評。", capex_evidence, "等營收與稼動率")
    signals["investment_cashflow"] = invest_box

    # 4) 負債 / 變現率：成長槓桿 vs 資金壓力
    debt_evidence = []
    if debt_ratio is not None: debt_evidence.append(f"負債比約{debt_ratio:.1f}%")
    if current_ratio is not None: debt_evidence.append(f"流動比率約{current_ratio:.1f}%")
    if quick_ratio is not None: debt_evidence.append(f"速動比率約{quick_ratio:.1f}%")
    debt_high = debt_ratio is not None and debt_ratio >= 70
    liquidity_weak = (current_ratio is not None and current_ratio < 100) or (quick_ratio is not None and quick_ratio < 80)
    if not debt_high and not liquidity_weak:
        debt_box = _v271_signal_box("負債 / 變現率", "安全", "低", "短期流動性與負債壓力不明顯。", "CFO 不因負債限制估值。", debt_evidence, "維持原判斷")
    elif debt_high and revenue_support and not cash_bad:
        debt_box = _v271_signal_box("負債 / 變現率", "成長槓桿", "中", "負債偏高可能與擴產或營運放大有關。", "CFO 允許觀察，但限制 Focus 與重押。", debt_evidence, "要求現金流與營收接棒")
    elif debt_high or liquidity_weak:
        debt_box = _v271_signal_box("負債 / 變現率", "短期資金壓力", "高", "負債或流動性壓力升高，若景氣轉弱會放大風險。", "CFO 啟動防守，估值需打安全邊際。", debt_evidence, "限制估值 / 降低部位")
    else:
        debt_box = _v271_signal_box("負債 / 變現率", "中性觀察", "中", "負債變化需搭配現金流與擴產目的判讀。", "CFO 暫不加分。", debt_evidence, "持續觀察")
    signals["debt_liquidity"] = debt_box

    # 5) 毛利 / 營益率變化：產品轉換期 vs 競爭惡化
    margin_evidence = []
    if gm is not None: margin_evidence.append(f"毛利率約{gm:.1f}%")
    if opm is not None: margin_evidence.append(f"營益率約{opm:.1f}%")
    if gm_yoy is not None: margin_evidence.append(f"毛利YoY約{gm_yoy:.1f}%")
    if opm_yoy is not None: margin_evidence.append(f"營益YoY約{opm_yoy:.1f}%")
    if margin_status == "有" or (gm is not None and gm >= 25 and opm is not None and opm >= 10 and not margin_bad):
        margin_box = _v271_signal_box("毛利 / 營益率", "結構支撐", "低", "雙率能支撐獲利品質。", "CFO 允許使用正常估值模型。", margin_evidence, "可進入估值重評檢查")
    elif margin_bad and revenue_support:
        margin_box = _v271_signal_box("毛利 / 營益率", "產品轉換或低毛利放量待驗證", "中", "營收有成長但雙率暫時承壓，可能是產品轉換期，也可能是低毛利放量。", "CFO 不允許直接樂觀估值，需看後續雙率修復。", margin_evidence, "限制樂觀 EPS / 等毛利驗證")
    elif margin_bad:
        margin_box = _v271_signal_box("毛利 / 營益率", "競爭惡化 / 成本壓力", "高", "雙率下滑且缺乏營收支撐，較像競爭或成本壓力。", "CFO 沒收樂觀與重評。", margin_evidence, "降低估值 / 禁追")
    else:
        margin_box = _v271_signal_box("毛利 / 營益率", "普通", "中低", "雙率尚可但未形成明顯重評證據。", "CFO 維持中性估值。", margin_evidence, "等產品組合證據")
    signals["margin"] = margin_box

    # 六維子分數：不用追求精準百分制，重點是讓 APP 分辨「風險」與「成長代價」。
    ability = build_financial_ability_radar(fin, bal, cf) if 'build_financial_ability_radar' in globals() else {}
    profit_score = ability.get("profitability")
    cashflow_score = ability.get("cashflow")
    safety_score = ability.get("solvency")
    turnover_score = ability.get("operation")

    # 成長轉換：營收 → EPS / 雙率
    growth_score = 50
    if revenue_support: growth_score += 15
    if revenue_to_eps in ["有", "部分有"]: growth_score += 15
    if eps_yoy is not None and eps_yoy >= 0: growth_score += 10
    if margin_status == "有": growth_score += 10
    if eps_bad or (revenue_support and revenue_to_eps == "沒有"): growth_score -= 25
    growth_score = clamp(growth_score, 0, 100)

    # 投資擴張品質：capex / ocf / revenue support
    expansion_score = 55
    if invest_box["classification"] == "成長型擴產": expansion_score += 20
    elif invest_box["classification"] == "現金消耗風險": expansion_score -= 25
    elif invest_box["classification"] == "必要維持 / 待驗證": expansion_score -= 5
    expansion_score = clamp(expansion_score, 0, 100)

    sub_scores = {
        "獲利品質": profit_score,
        "成長轉換": growth_score,
        "現金流品質": cashflow_score,
        "營運周轉": turnover_score,
        "財務安全": safety_score,
        "投資擴張品質": expansion_score,
    }
    valid_scores = [float(v) for v in sub_scores.values() if v is not None]
    overall = sum(valid_scores) / len(valid_scores) if valid_scores else None

    high_risk_count = sum(1 for x in signals.values() if x.get("risk_level") == "高")
    expectation_watch_count = sum(1 for x in signals.values() if x.get("classification") in ["健康備貨", "成長型擴產", "大客戶出貨放大"])
    weak_score_count = sum(1 for v in valid_scores if v < 45)

    if high_risk_count >= 2 or weak_score_count >= 3:
        verdict = "高度風險 / 財務品質惡化"
        action = "CFO 拉高防守，不得只靠題材給高估值。"
    elif high_risk_count >= 1:
        verdict = "營運卡住 / 需降速觀察"
        action = "限制 Focus 與樂觀估值，等財報訊號改善。"
    elif expectation_watch_count >= 2 and (overall is None or overall >= 45):
        verdict = "財報普通但有預期差"
        action = "觸發法醫解剖候選：確認是否為產品組合、訂單或擴產帶來的未來成長。"
    elif overall is not None and overall >= 70 and growth_score >= 60:
        verdict = "健康成長"
        action = "可進入 Core / Focus 候選，但仍需買點與風報比。"
    elif growth_score >= 60 or expectation_watch_count >= 1:
        verdict = "成長但需驗證"
        action = "列入 1～3 個月驗證清單，等營收、雙率、EPS 接棒。"
    else:
        verdict = "中性觀察"
        action = "財報沒有重大地雷，也尚未形成明確預期差。"

    rows = []
    for k, v in sub_scores.items():
        rows.append({"項目": k, "等級": _v271_score_level(v), "分數": int(round(v)) if v is not None else None})

    signal_rows = []
    for key, box in signals.items():
        signal_rows.append({
            "項目": box.get("label"),
            "分類": box.get("classification"),
            "風險": box.get("risk_level"),
            "企業主解讀": box.get("owner_view"),
            "CFO提醒": box.get("cfo_view"),
            "動作": box.get("action_hint"),
        })

    return {
        "version": "v271",
        "overall_score": overall,
        "summary": f"{verdict}" + (f"｜{int(round(overall))}分" if overall is not None else ""),
        "quick": f"{verdict}：{action}",
        "verdict": verdict,
        "action": action,
        "sub_scores": sub_scores,
        "rows": rows,
        "signals": signals,
        "signal_rows": signal_rows,
        "expectation_gap_watch": expectation_watch_count >= 1,
        "need_forensic_dissection": verdict in ["財報普通但有預期差", "營運卡住 / 需降速觀察", "高度風險 / 財務品質惡化"],
        "cfo_alerts": [box.get("cfo_view") for box in signals.values() if box.get("risk_level") == "高"],
        "owner_clues": [box.get("owner_view") for box in signals.values() if box.get("classification") in ["健康備貨", "成長型擴產", "大客戶出貨放大"]],
        "signal_principle": "財報不是答案，是企業行為的腳印；要先分類，再判斷是風險還是未來成長代價。",
    }


def _wc_status_from_score(score):
    if score is None:
        return "資料不足"
    if score >= 75:
        return "正常"
    if score >= 60:
        return "可接受"
    if score >= 45:
        return "需追蹤"
    if score >= 30:
        return "警訊"
    return "硬傷"


def working_capital_quality_engine(fin, bal, cf=None, stock=None, industry_category=None, model_key=None):
    """法醫級營運資金判讀器。

    存貨 / 應收是否正常，不用單一 YoY / QoQ 門檻硬判；
    必須搭配營收、毛利率、營益率、EPS、現金流與商業模式。
    輸出只提供 Core / Focus / 估值的風險閘門，不直接決定 Core Yes。
    """
    try:
        model_key = model_key or get_model_key(stock or "", industry_category)
    except Exception:
        model_key = model_key or ""
    try:
        family_key, family_rule = get_model_family_rule(model_key, industry_category)
    except Exception:
        family_key, family_rule = "quality_growth_pe", {}

    if not bal:
        return {
            "inventory_status": "資料不足",
            "receivable_status": "資料不足",
            "working_capital_verdict": "資料不足",
            "working_capital_score": None,
            "business_model_adjustment": family_rule.get("family_name", "一般模型") if isinstance(family_rule, dict) else "一般模型",
            "summary": "存貨 / 應收資料不足，不單獨否決財報，但 Focus 需保守確認。",
            "reason": "資料不足",
            "focus_allowed": True,
            "limit_focus": False,
            "limit_rerating": False,
            "core_limit": False,
        }

    rev_yoy = to_float((fin or {}).get("revenue_yoy"))
    eps = to_float((fin or {}).get("eps"))
    eps_yoy = to_float((fin or {}).get("eps_yoy"))
    gm = to_float((fin or {}).get("gross_margin"))
    gm_prev = to_float((fin or {}).get("gross_margin_prev"))
    om = to_float((fin or {}).get("op_margin"))
    om_prev = to_float((fin or {}).get("op_margin_prev"))
    ocf = to_float((cf or {}).get("ocf")) if cf else None
    fcf = to_float((cf or {}).get("fcf")) if cf else None
    inv_yoy = to_float(bal.get("inventory_yoy"))
    ar_yoy = to_float(bal.get("ar_yoy"))
    inventory = to_float(bal.get("inventory"))
    inventory_prev = to_float(bal.get("inventory_prev"))
    ar = to_float(bal.get("ar"))
    ar_prev = to_float(bal.get("ar_prev"))
    revenue = to_float((fin or {}).get("revenue"))

    inv_gap = inv_yoy - rev_yoy if inv_yoy is not None and rev_yoy is not None else None
    ar_gap = ar_yoy - rev_yoy if ar_yoy is not None and rev_yoy is not None else None
    inv_ratio = safe_div(inventory, revenue) if inventory is not None and revenue not in [None, 0] else None
    ar_ratio = safe_div(ar, revenue) if ar is not None and revenue not in [None, 0] else None
    inv_qoq = pct_change(inventory, inventory_prev) if inventory is not None and inventory_prev not in [None, 0] else None
    ar_qoq = pct_change(ar, ar_prev) if ar is not None and ar_prev not in [None, 0] else None
    gm_up = gm is not None and (gm_prev is None or gm >= gm_prev - 1.5)
    om_up = om is not None and (om_prev is None or om >= om_prev - 1.5)
    eps_ok = eps is not None and eps > 0 and (eps_yoy is None or eps_yoy >= -10)
    cash_ok = ocf is None or ocf > 0
    fcf_ok = fcf is None or fcf >= 0
    margin_ok = (gm is not None and gm >= 20) or gm_up or om_up
    revenue_ok = rev_yoy is None or rev_yoy >= 0

    family_name = family_rule.get("family_name", family_key) if isinstance(family_rule, dict) else family_key
    strict_wc = family_key in ["low_margin_distributor", "low_margin_odm"] or model_key in [
        "distributor", "memory_cyclical_distributor", "low_margin_assembly"
    ]
    cyclical_wc = family_key in ["cycle_pb_recovery", "cycle_eps_rerating", "turnaround_rerating_candidate"] or model_key in [
        "memory_manufacturing_cycle_rerating", "panel_turnaround_rerating"
    ]
    asset_or_financial = family_key in ["financial_pb_roe", "asset_nav_real_estate", "freight_cycle", "biotech_event_milestone"]

    inv_score = 65
    ar_score = 65
    reasons = []

    # 存貨：先看是否遠快於營收，再看毛利 / EPS / 現金流能否解釋。
    if inv_gap is not None:
        if inv_gap <= 15:
            inv_score += 10; reasons.append("存貨增速與營收大致匹配")
        elif inv_gap <= 30:
            inv_score -= 5; reasons.append("存貨增速略快於營收，需追蹤")
        else:
            inv_score -= 22; reasons.append("存貨增速明顯快於營收")
    if inv_qoq is not None and inv_qoq > 25 and not revenue_ok:
        inv_score -= 12; reasons.append("存貨季增偏快但營收未配合")
    if margin_ok and eps_ok and cash_ok:
        inv_score += 10; reasons.append("毛利 / EPS / 現金流可解釋存貨變化")
    if ocf is not None and ocf <= 0 and inv_gap is not None and inv_gap > 20:
        inv_score -= 18; reasons.append("存貨擴張但營業現金流不配合")

    # 應收：看營收成長是否能解釋，以及現金是否收得回來。
    if ar_gap is not None:
        if ar_gap <= 15:
            ar_score += 10; reasons.append("應收增速與營收大致匹配")
        elif ar_gap <= 30:
            ar_score -= 5; reasons.append("應收增速略快於營收，需追蹤")
        else:
            ar_score -= 22; reasons.append("應收增速明顯快於營收")
    if ar_qoq is not None and ar_qoq > 25 and not revenue_ok:
        ar_score -= 12; reasons.append("應收季增偏快但營收未配合")
    if eps_ok and cash_ok and fcf_ok:
        ar_score += 8; reasons.append("EPS 與現金流可支撐應收變化")
    if ocf is not None and ocf <= 0 and ar_gap is not None and ar_gap > 20:
        ar_score -= 18; reasons.append("應收擴張但營業現金流不配合")

    # 商業模式校正。
    if strict_wc:
        inv_score -= 8; ar_score -= 8
        reasons.append("低毛利 / 通路 / 組裝模型：存貨與應收採較嚴格標準")
    elif cyclical_wc:
        if margin_ok and eps_ok:
            inv_score += 6; ar_score += 4
            reasons.append("景氣循環 / 轉機模型：若毛利與 EPS 已接上，庫存與應收可給較高容忍")
        else:
            inv_score -= 4; ar_score -= 2
            reasons.append("景氣循環模型：報價 / 毛利未確認前，庫存需保守")
    elif asset_or_financial:
        # 金融 / 航運 / 營建 / 生技不硬套製造業存貨應收，但仍保留追蹤訊號。
        inv_score += 4; ar_score += 4
        reasons.append(f"{family_name}：不硬套一般製造業存貨 / 應收門檻")

    inv_score = clamp(inv_score, 0, 100)
    ar_score = clamp(ar_score, 0, 100)
    inventory_status = _wc_status_from_score(inv_score)
    receivable_status = _wc_status_from_score(ar_score)
    wc_score = min(inv_score, ar_score)
    working_capital_verdict = _wc_status_from_score(wc_score)

    # Focus：不是要求完美，但不能有警訊 / 硬傷；嚴格模型的「需追蹤」也不適合 Focus。
    focus_allowed = working_capital_verdict in ["正常", "可接受", "資料不足"]
    if strict_wc and working_capital_verdict == "需追蹤":
        focus_allowed = False
    limit_focus = not focus_allowed
    limit_rerating = working_capital_verdict in ["警訊", "硬傷"]
    core_limit = working_capital_verdict == "硬傷" and strict_wc

    if working_capital_verdict == "正常":
        summary = "存貨 / 應收與營收、獲利、現金流大致匹配。"
    elif working_capital_verdict == "可接受":
        summary = "存貨 / 應收有壓力但可被商業模式與基本面部分解釋。"
    elif working_capital_verdict == "需追蹤":
        summary = "存貨 / 應收需追蹤，暫不適合因此升級 Focus。"
    elif working_capital_verdict == "警訊":
        summary = "存貨 / 應收出現警訊，需限制 Focus 與估值重評。"
    else:
        summary = "存貨 / 應收構成法醫硬傷，低毛利 / 通路模型需限制 Core。"

    return {
        "inventory_status": inventory_status,
        "receivable_status": receivable_status,
        "working_capital_verdict": working_capital_verdict,
        "working_capital_score": round(wc_score, 1),
        "inventory_score": round(inv_score, 1),
        "receivable_score": round(ar_score, 1),
        "business_model_adjustment": family_name,
        "summary": summary,
        "reason": "；".join(dict.fromkeys([r for r in reasons if r]))[:260],
        "focus_allowed": focus_allowed,
        "limit_focus": limit_focus,
        "limit_rerating": limit_rerating,
        "core_limit": core_limit,
        "inv_gap_vs_revenue": inv_gap,
        "ar_gap_vs_revenue": ar_gap,
        "inventory_to_revenue": inv_ratio,
        "ar_to_revenue": ar_ratio,
    }

def judge_fin(fin, bal, cf, stock=None, industry_category=None):
    if not fin:
        return {
            "score": -2,
            "quality": "低",
            "treasury": "淘汰級",
            "report": "尚未公布",
            "financial_quality": "低",
            "growth_quality": "無法判斷",
            "revenue_to_eps": "無法判斷",
            "margin": "無法判斷",
            "eps": "無法判斷",
            "cashflow": "無法判斷",
            "inv_ar": "無法判斷",
            "debt": "無法判斷",
            "limit_core": True,
            "limit_focus": True,
            "limit_rerating": True,
            "low_margin": False,
            "cyclical": False,
            "text": "財報資料不足，不能給高估值",
            "treasury_score": 0,
            "treasury_reason": "財報資料不足",
            "financial_radar": build_financial_ability_radar(fin, bal, cf),
            "financial_signal_radar_v271": classify_financial_signals_v271(fin, bal, cf, fj={"inv_ar":"無法判斷", "cashflow":"無法判斷", "margin":"無法判斷", "eps":"無法判斷"}),
        }
    model_key = get_model_key(stock or "", industry_category)
    eps = fin.get("eps")
    eps_yoy = fin.get("eps_yoy")
    rev_yoy = fin.get("revenue_yoy")
    gm = fin.get("gross_margin")
    gmp = fin.get("gross_margin_prev")
    gmy = fin.get("gross_margin_yoy")
    om = fin.get("op_margin")
    omp = fin.get("op_margin_prev")
    omy = fin.get("op_margin_yoy")
    score, q_score, g_score, txt = 0, 0, 0, []
    limit_core = False
    limit_focus = False
    limit_rerating = False
    low_margin = False
    cyclical = False
    if eps is None:
        eps_support = "部分有"
        txt.append("EPS 無資料")
    elif eps > 0:
        q_score += 2
        score += 2
        eps_support = "有" if eps_yoy is None or eps_yoy >= 0 else "部分有"
        txt.append(
            "EPS 為正"
            + ("且年增未惡化" if eps_yoy is None or eps_yoy >= 0 else "但年增轉弱")
        )
    else:
        score -= 4
        q_score -= 3
        eps_support = "沒有"
        limit_core = True
        limit_focus = True
        txt.append("EPS 不支撐")
    if rev_yoy is not None and rev_yoy >= 10:
        g_score += 2
        score += 1
        txt.append("財報營收年增正向")
    elif rev_yoy is not None and rev_yoy >= 0:
        g_score += 1
        txt.append("財報營收年增持平偏正")
    elif rev_yoy is not None:
        g_score -= 2
        txt.append("財報營收年減，成長動能扣分")
    if eps_yoy is not None and eps_yoy >= 10:
        g_score += 2
        score += 1
        txt.append("EPS 年增明確")
    elif eps_yoy is not None and eps_yoy >= 0:
        g_score += 1
        txt.append("EPS 年增持平偏正")
    elif eps_yoy is not None:
        g_score -= 2
        txt.append("EPS 年減，成長動能未通過")
    if rev_yoy is not None and rev_yoy > 10 and eps_yoy is not None and eps_yoy > 0:
        score += 2
        rte = "有"
        txt.append("營收成長有轉成 EPS")
    elif rev_yoy is not None and rev_yoy > 10 and (eps_yoy is None or eps_yoy >= -10):
        rte = "部分有"
        txt.append("營收成長，但 EPS 轉換還要驗證")
    elif rev_yoy is not None and rev_yoy > 10:
        score -= 1
        rte = "沒有"
        limit_rerating = True
        txt.append("營收成長但 EPS 沒跟上")
    elif eps is not None and eps > 0 and gm is not None and gm >= 30:
        rte = "部分有"
        txt.append("營收成長不強，但獲利體質仍有支撐")
    else:
        rte = "無法判斷"
        txt.append("財報營收成長不明")
    gm_high = gm is not None and gm >= 40
    om_high = om is not None and om >= 25
    gm_ok = gm is not None and gm >= 25
    om_ok = om is not None and om >= 10
    gm_imp = gm is not None and (
        (gmp is not None and gm >= gmp - 1.5) or (gmy is not None and gm >= gmy - 1.5)
    )
    om_imp = om is not None and (
        (omp is not None and om >= omp - 1.5) or (omy is not None and om >= omy - 1.5)
    )
    if gm is not None and gm < 10:
        score -= 1
        q_score -= 1
        low_margin = True
        txt.append("毛利率偏低")
    if om is not None and om < 3:
        score -= 1
        q_score -= 1
        limit_focus = True
        txt.append("營益率偏薄")
    if (gm_high and om_high) or (
        model_key in HIGH_QUALITY_GROWTH_MODELS
        and gm_ok
        and om_ok
        and (gm_imp or om_imp)
    ):
        q_score += 3
        score += 2
        margin = "有"
        txt.append("毛利率 / 營益率高檔維持或改善")
    elif gm_ok and om_ok:
        q_score += 2
        score += 1
        margin = "普通"
        txt.append("毛利率 / 營益率尚可")
    elif gm_imp or om_imp:
        q_score += 1
        margin = "普通"
        txt.append("毛利率或營益率部分改善")
    else:
        margin = "沒有"
        limit_rerating = True
        txt.append("毛利率與營益率未明確支撐")
    if not cf or cf.get("ocf") is None:
        cash = "普通"
        txt.append("現金流資料不足，不直接重罰")
    elif cf["ocf"] > 0 and (cf.get("fcf") is None or cf["fcf"] >= 0):
        score += 2
        q_score += 2
        cash = "有"
        txt.append("營業現金流支撐")
    elif cf["ocf"] > 0:
        score += 1
        q_score += 1
        cash = "普通"
        txt.append("營業現金流為正但 FCF 需觀察")
    else:
        # 現金流不配合應限制 Focus / 估值倍率，不應直接把強成長財報打成不通過或 公司體質未通過。
        score -= 3
        q_score -= 2
        cash = "不配合"
        limit_focus = True
        txt.append("營業現金流不配合，限制 Focus / 重押")
    inv_ar, debt = "正常", "沒有"
    wcq = working_capital_quality_engine(fin, bal, cf, stock=stock, industry_category=industry_category, model_key=model_key)
    wc_verdict = wcq.get("working_capital_verdict", "資料不足")
    if wc_verdict in ["正常", "可接受", "資料不足"]:
        inv_ar = "正常"
    elif wc_verdict == "需追蹤":
        inv_ar = "偏高"
        limit_focus = True
        q_score -= 0.5
    else:
        inv_ar = "異常"
        limit_focus = True
        q_score -= 1
        score -= 1
    if wcq.get("limit_rerating"):
        limit_rerating = True
    if wcq.get("core_limit"):
        limit_core = True
    if wcq.get("summary"):
        txt.append(wcq.get("summary"))
    if wcq.get("reason"):
        txt.append("營運資金判讀：" + str(wcq.get("reason")))
    if bal and bal.get("debt_ratio") is not None and bal["debt_ratio"] > 70:
        score -= 2
        q_score -= 1
        debt = "明顯"
        limit_focus = True
        txt.append("負債比偏高")
    # 低毛利大型製造平台：若營益率改善且營收 / EPS 有跟上，不直接視為循環槓桿股。
    low_margin_platform_ok = (
        low_margin
        and om is not None and om >= 3
        and eps is not None and eps > 0
        and rev_yoy is not None and rev_yoy >= 15
        and rte in ["有", "部分有"]
    )
    if low_margin and margin != "有" and not low_margin_platform_ok:
        cyclical = True
        limit_rerating = True
    elif low_margin_platform_ok:
        limit_focus = True
        txt.append("低毛利大型平台有結構改善，可 Core 但限制 Focus")
    # v5.3 修正：財報裁決與財務品質限制拆開。
    # financial_quality 保留「含現金流 / 存貨 / 應收 / 負債」的法醫品質分數，
    # 但 report 不再直接吃 q_score，避免高成長財報被營運資金或股價位置誤殺成「不通過」。
    financial_quality = (
        "高"
        if q_score >= 5 and eps_support in ["有", "部分有"]
        else "中"
        if q_score >= 2 and eps_support != "沒有"
        else "低"
    )
    growth_quality = (
        "通過" if g_score >= 3 else "部分通過" if g_score >= 0 else "不通過"
    )

    # report_core_score 只看財報本體：營收 / EPS / 毛利率 / 營益率 / 營收轉 EPS。
    # 現金流、存貨、應收、負債只會寫入 financial_quality、limit_focus、limit_rerating，
    # 不得單獨讓財報裁決變成「不通過」。
    report_core_score = 0
    if eps_support == "有":
        report_core_score += 2
    elif eps_support == "部分有":
        report_core_score += 1
    if rte == "有":
        report_core_score += 2
    elif rte == "部分有":
        report_core_score += 1
    if margin == "有":
        report_core_score += 2
    elif margin == "普通":
        report_core_score += 1
    if growth_quality == "通過":
        report_core_score += 2
    elif growth_quality == "部分通過":
        report_core_score += 1

    report_hard_fail = (
        eps_support == "沒有"
        or (growth_quality == "不通過" and margin == "沒有")
        or (rte == "沒有" and margin == "沒有")
    )
    strong_report_core = (
        not report_hard_fail
        and eps_support in ["有", "部分有"]
        and rte in ["有", "部分有"]
        and margin in ["有", "普通"]
        and growth_quality == "通過"
        and report_core_score >= 6
    )
    if strong_report_core:
        report = "通過"
    elif not report_hard_fail and report_core_score >= 4 and eps_support in ["有", "部分有"]:
        report = "部分通過"
    else:
        report = "不通過"

    # fix60｜金居 HVLP 高階銅箔財報防呆：
    if model_key == "hvlp_copper_foil_growth" and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin == "有" and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        limit_focus = True
        txt.append("HVLP 高階銅箔：營收、毛利率、營益率、EPS 與現金流同向，財報通過；但現價與處置 / 追價風險限制新倉 Focus")

    # fix57｜PCB / ABF 財報防呆：
    if model_key in ["abf_bt_substrate_cycle", "ai_server_pcb_core", "pcb_drill_consumables"] and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin in ["有", "普通"] and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        txt.append("PCB / ABF：營收轉 EPS，毛利率 / 營益率支撐，財報通過；但需看稼動率、報價與產品組合接棒")
    if model_key == "general_pcb_hdi_candidate" and report == "通過":
        limit_focus = True
        txt.append("一般 PCB / HDI：財報可通過，但未證明高階占比前，限制 Focus 與主倉重押")

    # fix53｜CCL / 高階材料財報防呆：
    if model_key == "ccl_highend_highspeed" and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin in ["有", "普通"] and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        txt.append("高階 CCL / 高速材料：營收轉 EPS，毛利率 / 營益率支撐，財報通過；但現價與風報比仍限制重押")
    if model_key in ["copper_foil_cyclical", "glass_fiber_cyclical"] and report == "通過":
        limit_focus = True
        txt.append("材料循環：財報可通過，但銅箔 / 玻纖報價與稼動率循環性高，限制 Focus 與主倉重押")

    # fix52｜穩健內需餐飲財報防呆：
    if model_key == "consumer_restaurant_stable" and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin in ["有", "普通"] and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        limit_focus = True
        txt.append("穩健內需餐飲：營收已轉 EPS，財報通過；但營益率不高、展店 / 租金 / 人力成本限制 Focus")

    # fix50｜商業化新藥財報防呆：
    if model_key == "biotech_commercial_drug_growth" and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin == "有" and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        limit_focus = True
        txt.append("商業化新藥：營收、EPS、高毛利率 / 營益率與現金流同向，財報通過；但高估值與藥證事件限制 Focus")

    # fix48｜建商交屋認列財報防呆：
    # 營建股只要交屋認列已轉 EPS、毛利率/營益率支撐、現金流沒有不配合，財報應為通過；
    # 但因存貨/負債大與營收認列跳動，Focus 仍需嚴格。
    if model_key == "real_estate_delivery_recognition" and eps_support in ["有", "部分有"] and rte in ["有", "部分有"] and margin in ["有", "普通"] and cash in ["有", "普通"]:
        report = "通過"
        limit_core = False
        limit_focus = True
        txt.append("建商交屋認列：營收已轉 EPS 且毛利/營益率支撐，財報通過；但營收認列跳動、存貨與負債限制 Focus")

    # fix46｜貨櫃航運運價反彈財報防呆：
    # 航運 Q1 若仍是衰退財報，不可判完整通過；但 EPS 仍有、現金流/負債未崩時，不應判不通過。
    # 這代表可交易運價反彈，但不可 Core / Focus。
    if model_key == "shipping_freight_rebound" and eps_support in ["有", "部分有"]:
        report = "部分通過"
        limit_core = True
        limit_focus = True
        limit_rerating = True
        txt.append("貨櫃航運運價反彈：EPS 仍有支撐但財報年減，財報只給部分通過，限制 Core / Focus")

    # fix75｜面板轉機重評財報防呆：
    # 群創 / 友達這類財報剛轉盈、現金流改善、題材與籌碼強，但 EPS / 營益率仍低時，
    # 不可寫成完整財報通過；正確是「部分通過 + 估值重評部分成立」，Core / Focus 受限。
    if model_key == "panel_turnaround_rerating" and eps_support in ["有", "部分有"]:
        report = "部分通過"
        limit_core = True
        limit_focus = True
        limit_rerating = True
        cyclical = True
        if financial_quality == "高":
            financial_quality = "中"
        txt.append("面板轉機重評：Q1 轉盈與現金流改善是加分，但 EPS / 營益率尚未厚到支撐高位股價，財報只給部分通過，限制 Core / Focus")

    # fix42｜金融類股通用財報防呆：
    # 金融股不可用製造業毛利率、存貨、應收邏輯誤殺；EPS / 子公司獲利 / 資產品質才是主軸。
    if model_key in ["financial_bank_core", "financial_brokerage_cycle", "financial_general_core"] and eps_support in ["有", "部分有"]:
        report = "通過"
        limit_core = False if model_key == "financial_bank_core" else limit_core
        txt.append("金融股專用判斷：不套製造業毛利率 / 存貨邏輯，EPS 支撐則財報通過")

    # fix41｜金控壽險資產重評：
    # 金控 / 壽險股不套一般製造業毛利率、存貨、應收邏輯；
    # 若 EPS 為正、獲利支撐，財報應通過，但 Focus 仍受資產波動 / 籌碼分歧限制。
    if model_key == "financial_holding_life_revaluation" and eps_support in ["有", "部分有"]:
        report = "通過"
        limit_core = False
        limit_rerating = False
        txt.append("金融資產型金庫：EPS 與子公司獲利支撐，財報通過；壽險受股債匯波動影響，限制 Focus")

    # fix40｜防守型現金流金庫：
    # 電信 / 現金流金庫股不是爆發型，若 EPS 為正、毛利/營益率與現金流支撐，財報應可通過。
    if model_key == "defensive_cashflow_treasury" and report != "不通過":
        if eps_support in ["有", "部分有"] and margin in ["有", "普通"] and cash in ["有", "普通"]:
            report = "通過"
            limit_core = False
            txt.append("防守型現金流金庫：財報品質與現金流通過，但非攻擊型成長股")

    # fix35｜記憶體循環 / 低毛利電子通路：
    # EPS 爆發可以讓財報「部分通過偏強」，但低毛利、負現金流、存貨應收負債重時，
    # 不得直接完整通過，也不得正式 Core / Focus。
    if model_key == "memory_cyclical_distributor" and report == "通過":
        report = "部分通過"
        limit_core = True
        limit_focus = True
        limit_rerating = True
        txt.append("記憶體循環低毛利通路：EPS 強但財報品質只給部分通過偏強，限制 Core / Focus")

    # 現金流 / 存貨 / 應收 / 股價位置不直接改 report；只限制 Focus / 估值 / 交易倉位。
    working_capital_or_cash_risk = cash == "不配合" or inv_ar != "正常" or debt == "明顯"
    if working_capital_or_cash_risk:
        limit_focus = True
        if cash == "不配合" or inv_ar != "正常":
            limit_rerating = True
        txt.append("營運資金 / 現金流風險只限制 Focus / 估值倍率，不直接否決財報裁決")

    if growth_quality == "不通過":
        limit_rerating = True
    # Core 只被財報本體重大失敗限制；營運資金風險不單獨打成 公司體質未通過。
    if report_hard_fail:
        limit_core = True
        limit_focus = True
    treasury_score = 0.0
    treasury_notes = []
    scoring_pairs = [
        (
            eps_support,
            {"有": (2, "EPS 支撐"), "部分有": (1, "EPS 部分支撐")},
            "EPS 不支撐",
        ),
        (
            rte,
            {"有": (2, "營收有轉 EPS"), "部分有": (1, "營收部分轉 EPS")},
            "營收轉 EPS 未確認",
        ),
        (
            margin,
            {"有": (2, "毛利率 / 營益率支撐"), "普通": (1, "毛利率 / 營益率普通")},
            "毛利率 / 營益率不支撐",
        ),
        (cash, {"有": (2, "現金流支撐"), "普通": (1, "現金流普通")}, "現金流不配合"),
    ]
    for value, table, bad in scoring_pairs:
        if value in table:
            s, note = table[value]
            treasury_score += s
            treasury_notes.append(note)
        else:
            treasury_notes.append(bad)
    if inv_ar == "正常":
        treasury_score += 1
        treasury_notes.append("存貨 / 應收正常或可接受")
    elif inv_ar == "偏高":
        treasury_score += 0.3
        treasury_notes.append("存貨 / 應收需追蹤")
    else:
        treasury_notes.append("存貨 / 應收異常")
    if debt != "明顯":
        treasury_score += 1
        treasury_notes.append("負債未明顯惡化")
    else:
        treasury_notes.append("負債明顯偏高")
    if financial_quality == "高":
        treasury_score += 1
        treasury_notes.append("財報品質高")
    elif financial_quality == "中":
        treasury_score += 0.5
        treasury_notes.append("財報品質中")
    else:
        treasury_notes.append("財報品質低")
    if growth_quality == "通過":
        treasury_score += 1
        treasury_notes.append("成長動能通過")
    elif growth_quality == "部分通過":
        treasury_score += 0.5
        treasury_notes.append("成長動能部分通過")
    else:
        treasury_notes.append("成長動能不通過")
    strict_working_capital_models = [
        "distributor",
        "memory_cyclical_distributor",
        "low_margin_assembly",
        "cyclical_material",
        "turnaround",
    ]
    working_capital_hard_block = (
        inv_ar == "異常" and model_key in strict_working_capital_models
    )
    treasury_block = (
        financial_quality == "低" or eps_support == "沒有" or cash == "不配合"
    )
    if not treasury_block and treasury_score >= 9:
        treasury = "金庫級"
    elif treasury_score >= 8 and eps_support != "沒有":
        treasury = "候選級偏金庫"
    elif treasury_score >= 7 and eps_support != "沒有":
        treasury = "候選級"
    elif treasury_score >= 5 and eps_support != "沒有":
        treasury = "觀察級"
    else:
        treasury = "淘汰級"
    return {
        "score": score,
        "quality": financial_quality,
        "treasury": treasury,
        "report": report,
        "treasury_score": treasury_score,
        "treasury_reason": "；".join(treasury_notes),
        "report_type": (
            "銀行型金庫通過"
            if model_key == "financial_bank_core" and report == "通過"
            else (
                "證券循環金融通過"
                if model_key == "financial_brokerage_cycle" and report == "通過"
                else (
                    "一般金融通過"
                    if model_key == "financial_general_core" and report == "通過"
                    else (
                        "金融資產型金庫通過"
                        if model_key == "financial_holding_life_revaluation" and report == "通過"
                        else (
                "防守型金庫通過"
                if model_key == "defensive_cashflow_treasury" and report == "通過"
                else (
                    "部分通過偏強"
                    if model_key == "memory_cyclical_distributor" and report == "部分通過"
                    else ("低毛利結構改善型通過" if low_margin_platform_ok and report == "通過" else ("高成長財報通過" if report == "通過" else report))
                )
                        )
                    )
                )
            )
        ),
        "financial_quality": financial_quality,
        "growth_quality": growth_quality,
        "revenue_to_eps": rte,
        "margin": margin,
        "eps": eps_support,
        "cashflow": cash,
        "inv_ar": inv_ar,
        "working_capital_verdict": wcq.get("working_capital_verdict", "資料不足"),
        "inventory_status": wcq.get("inventory_status", "資料不足"),
        "receivable_status": wcq.get("receivable_status", "資料不足"),
        "working_capital_score": wcq.get("working_capital_score"),
        "working_capital_reason": wcq.get("reason", ""),
        "working_capital_summary": wcq.get("summary", ""),
        "working_capital_focus_allowed": wcq.get("focus_allowed", True),
        "debt": debt,
        "limit_core": limit_core,
        "limit_focus": limit_focus,
        "limit_rerating": limit_rerating,
        "low_margin": low_margin,
        "cyclical": cyclical,
        "text": "；".join(txt),
        "financial_radar": build_financial_ability_radar(fin, bal, cf),
        "financial_signal_radar_v271": classify_financial_signals_v271(
            fin, bal, cf,
            fj={
                "inv_ar": inv_ar,
                "cashflow": cash,
                "margin": margin,
                "eps": eps_support,
                "revenue_to_eps": rte,
            },
            model_key=model_key,
            industry_category=industry_category,
        ),
    }


def judge_chip(inst):
    if not inst:
        return {
            "score": 0,
            "bias": "中性",
            "text": "法人資料不足",
            "limit_attack": False,
            "limit_focus": False,
        }
    n5 = inst.get("net5_lot")
    n20 = inst.get("net20_lot")
    f5 = inst.get("foreign_net5_lot")
    f20 = inst.get("foreign_net20_lot")
    pos5 = inst.get("positive_days_5", 0)
    pos20 = inst.get("positive_days_20", 0)
    sell = inst.get("consecutive_sell", 0)
    if n5 is None:
        return {
            "score": 0,
            "bias": "中性",
            "text": "法人資料不足",
            "limit_attack": False,
            "limit_focus": False,
        }
    # fix20｜低毛利平台外資吃貨：若外資 20 日大買，對 Attack / 小倉觀察加分。
    # 這不是 Focus 放行，只代表籌碼有主導資金承接。
    if f20 is not None and f20 > 50000 and pos20 >= 12:
        _f5_txt = f"，近 5 日外資 {f5:+,} 張" if f5 is not None else ""
        return {
            "score": 3,
            "bias": "偏多",
            "text": f"外資近 20 日明顯買超 {f20:+,} 張{_f5_txt}；近 20 日買進 {pos20}/20 天",
            "limit_attack": False,
            "limit_focus": False,
        }
    if n5 > 3000 and pos5 >= 3:
        return {
            "score": 3,
            "bias": "偏多",
            "text": f"近 5 日法人明顯買超；近 20 日買進 {pos20}/20 天",
            "limit_attack": False,
            "limit_focus": False,
        }
    if n5 > 0 and pos5 >= 3:
        return {
            "score": 2,
            "bias": "偏多",
            "text": f"近 5 日法人偏買超；近 20 日買進 {pos20}/20 天",
            "limit_attack": False,
            "limit_focus": False,
        }
    if n5 > 0 or (n20 is not None and n20 > 0 and pos20 >= 8):
        return {
            "score": 1,
            "bias": "中性",
            "text": f"法人小買或近 20 日偏買；近 20 日買進 {pos20}/20 天",
            "limit_attack": False,
            "limit_focus": False,
        }
    if n5 > -1000:
        return {
            "score": 0,
            "bias": "中性",
            "text": f"法人小賣或中性；近 20 日買進 {pos20}/20 天",
            "limit_attack": False,
            "limit_focus": False,
        }
    if sell >= 3 or n5 < -3000:
        return {
            "score": -3,
            "bias": "偏空",
            "text": f"法人連續或明顯賣超，限制 Attack / Focus；近 20 日買進 {pos20}/20 天",
            "limit_attack": True,
            "limit_focus": True,
        }
    return {
        "score": -1,
        "bias": "偏空",
        "text": f"法人偏賣超，不得直接判健康回檔；近 20 日買進 {pos20}/20 天",
        "limit_attack": False,
        "limit_focus": True,
    }


# ============================================================
# v276.5｜法人逆勢承接模組：跌深錯殺核心驗證＋CAF跨策略加權
# ============================================================
def _v2765_num(x, default=None):
    try:
        v = to_float(x)
        return default if v is None else float(v)
    except Exception:
        return default


def _v2765_last_daily_net_lots(inst, n=5):
    """從 fetch_inst 回傳的 daily 表取近 n 日法人淨買賣超（張）。資料不足時安全回傳空 list。"""
    try:
        if not inst:
            return []
        daily = inst.get("daily")
        if daily is None or getattr(daily, "empty", True):
            return []
        df = daily.copy()
        if "date" in df.columns:
            df = df.sort_values("date")
        col = "net_lot" if "net_lot" in df.columns else ("net" if "net" in df.columns else None)
        if not col:
            return []
        vals = []
        for v in df[col].tail(int(n)).tolist():
            vv = _v2765_num(v)
            if vv is not None:
                # fetch_inst 的 net 是股；net_lot 是張。若誤拿到 net，轉成張。
                if col == "net" and abs(vv) > 100000:
                    vv = vv / 1000.0
                vals.append(float(vv))
        return vals
    except Exception:
        return []


def _v2765_price_support_context(price):
    price = price or {}
    close = _v2765_num(price.get("close"))
    ma20 = _v2765_num(price.get("ma20"))
    ma60 = _v2765_num(price.get("ma60"))
    low20 = _v2765_num(price.get("low20"))
    recent_support = _v2765_num(price.get("recent_support"))
    volume_ratio = _v2765_num(price.get("volume_ratio"))
    ret20 = _v2765_num(price.get("ret20"))
    drawdown20 = _v2765_num(price.get("drawdown20"))
    support_refs = [x for x in [recent_support, ma60, low20, ma20] if x not in [None, 0]]
    support_ref = max([x for x in support_refs if close is not None and x <= close * 1.08], default=(support_refs[0] if support_refs else None))
    support_ok = False
    broken_support = False
    if close is not None:
        if ma60 not in [None, 0] and close >= ma60 * 0.96:
            support_ok = True
        if low20 not in [None, 0] and close >= low20 * 0.985:
            support_ok = True
        if recent_support not in [None, 0] and close >= recent_support * 0.97:
            support_ok = True
        if ma60 not in [None, 0] and close < ma60 * 0.94:
            broken_support = True
        if low20 not in [None, 0] and close < low20 * 0.97:
            broken_support = True
    long_black = False
    try:
        raw = price.get("raw")
        if raw is not None and not getattr(raw, "empty", True):
            last = raw.copy().sort_values("date").iloc[-1]
            op = _v2765_num(last.get("open"))
            cl = _v2765_num(last.get("close"))
            hi = _v2765_num(last.get("max") if "max" in last.index else last.get("high"))
            lo = _v2765_num(last.get("min") if "min" in last.index else last.get("low"))
            if op not in [None, 0] and cl is not None:
                body_pct = (cl - op) / abs(op) * 100
                range_pct = ((hi or max(op, cl)) - (lo or min(op, cl))) / abs(op) * 100 if op else 0
                long_black = body_pct <= -3.5 and (volume_ratio is None or volume_ratio >= 1.15 or range_pct >= 5.5)
    except Exception:
        pass
    return {
        "close": close,
        "ma20": ma20,
        "ma60": ma60,
        "low20": low20,
        "support_ref": support_ref,
        "support_ok": support_ok,
        "broken_support": broken_support,
        "long_black": long_black,
        "volume_ratio": volume_ratio,
        "ret20": ret20,
        "drawdown20": drawdown20,
    }


def build_institutional_absorption_signal_v2765(price=None, inst=None, rev=None, fin=None, flow_status="", core_hint=""):
    """v276.5-full｜法人逆勢承接共用模組。

    定位：不是獨立功能頁，而是同一顆底層判斷器，同時餵給：
    1) 跌深錯殺：當核心驗證器，判斷是真錯殺、承接觀察或接刀風險。
    2) CAF Radar：當跨策略加分/警示標籤，不覆蓋 Core/Attack/Focus。

    v1 只使用穩定資料源：法人 1/3/5/20 日、投信/外資、價量支撐、融資警示文字。
    盤中大單/分點大戶先保留給 v2，不作硬條件。
    """
    price = price or {}
    inst = inst or {}
    rev = rev or {}
    fin = fin or {}
    px = _v2765_price_support_context(price)
    nets5 = _v2765_last_daily_net_lots(inst, 5)
    nets3 = nets5[-3:]
    today = nets5[-1] if nets5 else None
    prev = nets5[-2] if len(nets5) >= 2 else None
    net3 = sum(nets3) if nets3 else None
    net5 = _v2765_num(inst.get("net5_lot"))
    net20 = _v2765_num(inst.get("net20_lot"))
    foreign5 = _v2765_num(inst.get("foreign_net5_lot"))
    trust5 = _v2765_num(inst.get("trust_net5_lot"))
    pos5 = int(_v2765_num(inst.get("positive_days_5"), 0) or 0)
    sell_streak = int(_v2765_num(inst.get("consecutive_sell"), 0) or 0)
    buy_streak = int(_v2765_num(inst.get("consecutive_buy"), 0) or 0)

    evidence = []
    tags = []
    warnings = []
    score_adjust = 0
    flow_s = str(flow_status or "")

    if net5 is not None:
        evidence.append(f"法人5日{net5:+.0f}張")
    if net20 is not None:
        evidence.append(f"20日{net20:+.0f}張")
    if today is not None:
        evidence.append(f"最新日{today:+.0f}張")
    if px.get("ma60") is not None:
        evidence.append(f"MA60約{fmt_price(px.get('ma60'))}")

    sell_shrink = False
    if today is not None and prev is not None and today < 0 and prev < 0 and abs(today) <= abs(prev) * 0.5:
        sell_shrink = True
    if net5 is not None and net20 is not None and net5 < 0 and net20 < 0 and abs(net5) <= max(abs(net20) / 4.0, 1):
        sell_shrink = True
    if sell_shrink:
        tags.append("賣壓縮小")
        evidence.append("賣壓縮小")

    buyer_back = False
    if today is not None and today > 0:
        buyer_back = True
    if net3 is not None and net3 > 0:
        buyer_back = True
    if net5 is not None and net5 > 0 and pos5 >= 3:
        buyer_back = True
    if trust5 is not None and trust5 > 0:
        tags.append("投信回補")
    if foreign5 is not None and foreign5 > 0:
        tags.append("外資回補")
    if buyer_back:
        evidence.append("短線法人回補")
    if px.get("support_ok"):
        evidence.append("支撐未破")

    # 融資資料目前不是每個單檔穩定輸入，v1 兼容文字警示與可能存在的欄位。
    margin_keys = [
        "margin_change_5d", "margin_balance_change_5d", "margin_5d", "margin_delta_5d",
        "融資增減", "融資5日", "融資餘額變化"
    ]
    margin_delta = None
    for k in margin_keys:
        if isinstance(inst, dict) and k in inst:
            margin_delta = _v2765_num(inst.get(k))
            if margin_delta is not None:
                break
    text_blob = "｜".join([str(inst), str(price), str(rev), str(fin), str(core_hint), flow_s])
    margin_warning = any(k in text_blob for k in ["融資暴增", "融資逆勢暴增", "散戶攤平", "融資攤平"])
    if margin_delta is not None and margin_delta > 1000:
        margin_warning = True

    hard_risk = False
    risk_reasons = []
    if px.get("broken_support") and px.get("long_black"):
        hard_risk = True
        risk_reasons.append("帶量長黑跌破支撐")
    if net5 is not None and net20 is not None and net5 < 0 and net20 < 0 and sell_streak >= 3 and not sell_shrink:
        hard_risk = True
        risk_reasons.append("法人短波段同步續賣")
    if today is not None and prev is not None and today < 0 and prev < 0 and abs(today) > abs(prev) * 1.25:
        hard_risk = True
        risk_reasons.append("最新日賣超擴大")
    if margin_warning:
        hard_risk = True
        risk_reasons.append("融資攤平警示")

    if hard_risk:
        state = "接刀風險"
        label = "🔴 無承接 / 接刀風險"
        note = "法人續賣、融資攤平或跌破支撐，這種跌深不能直接當錯殺。"
        warnings.extend(risk_reasons)
        tags.append("接刀風險")
        score_adjust = -12
    elif buyer_back and px.get("support_ok") and not px.get("long_black"):
        state = "承接成立"
        label = "🟢 法人逆勢承接"
        note = "有人接、支撐未破，錯殺機率提高；但仍要進個股法醫確認基本面與買點。"
        tags.append("法人逆勢承接")
        score_adjust = 8
    elif (sell_shrink or (trust5 is not None and trust5 > 0) or (net5 is not None and net5 > -1000 and px.get("support_ok"))) and not px.get("broken_support"):
        state = "承接觀察"
        label = "🟡 承接觀察"
        note = "賣壓縮小或支撐未破，但還沒明確轉買；先觀察，不急追。"
        tags.append("承接觀察")
        score_adjust = 3
    else:
        state = "資料不足"
        label = "⚪ 承接資料不足"
        note = "法人或支撐證據不足，不能因跌深直接認定錯殺。"
        score_adjust = 0

    ret20 = px.get("ret20")
    drawdown20 = px.get("drawdown20")
    dip_like = False
    for v in [ret20, drawdown20]:
        if v is not None and v <= -10:
            dip_like = True

    if dip_like and state == "承接成立":
        dip_verdict = "真錯殺候選｜錯殺驗證成功"
    elif dip_like and state == "承接觀察":
        dip_verdict = "跌深反彈觀察｜承接觀察"
    elif dip_like and state == "接刀風險":
        dip_verdict = "非真錯殺｜接刀風險"
    elif state in ["承接成立", "承接觀察"]:
        dip_verdict = "非跌深主軸｜承接可加分"
    else:
        dip_verdict = "尚未通過錯殺驗證"

    strategy_tags = []
    if state == "承接成立":
        if "回檔" in flow_s or "整理" in flow_s:
            strategy_tags.append("主力回檔防守")
        if "偷偷" in flow_s:
            strategy_tags.append("法人低調回補")
        if "低基期" in flow_s or "轉機" in flow_s:
            strategy_tags.append("底部承接觀察")
        if any(k in flow_s for k in ["輪動", "新", "主題", "低基期", "偷偷", "回檔轉強"]):
            strategy_tags.append("新題材資金試單")
    elif state == "承接觀察":
        if sell_shrink:
            strategy_tags.append("賣壓縮小")
        if "低基期" in flow_s:
            strategy_tags.append("底部承接觀察")
    elif state == "接刀風險":
        strategy_tags.append("接刀風險")
        if margin_warning:
            strategy_tags.append("融資攤平警示")

    if "真錯殺" in dip_verdict:
        strategy_tags.append("錯殺驗證成功")
    elif "非真錯殺" in dip_verdict:
        strategy_tags.append("非真錯殺")

    all_tags = list(dict.fromkeys([x for x in (tags + strategy_tags) if x]))
    front_summary = "、".join(strategy_tags[:3]) if strategy_tags else ("法人逆勢承接" if state == "承接成立" else state)
    action_hint = ""
    if state == "接刀風險":
        action_hint = "先避開，不因跌深亂接。"
    elif state == "承接成立":
        action_hint = "可列優先待分析，等支撐/買點確認。"
    elif state == "承接觀察":
        action_hint = "先放觀察，等法人或支撐確認。"
    else:
        action_hint = "資料不足，先不認定錯殺。"

    return {
        "state": state,
        "label": label,
        "note": note,
        "score_adjust": score_adjust,
        "tags": all_tags,
        "strategy_tags": strategy_tags,
        "warnings": list(dict.fromkeys([x for x in warnings if x])),
        "evidence": list(dict.fromkeys([x for x in evidence if x]))[:6],
        "sell_shrink": bool(sell_shrink),
        "buyer_back": bool(buyer_back),
        "support_ok": bool(px.get("support_ok")),
        "broken_support": bool(px.get("broken_support")),
        "long_black": bool(px.get("long_black")),
        "margin_warning": bool(margin_warning),
        "dip_verdict": dip_verdict,
        "ret20": ret20,
        "drawdown20": drawdown20,
        "is_risk": state == "接刀風險",
        "is_positive": state == "承接成立",
        "front_summary": front_summary,
        "action_hint": action_hint,
    }




# =========================================================
# v277｜發動前鎖碼分：CAF / 掃股雷達共用點火前確認模組
# =========================================================
def build_pre_breakout_lock_signal_v277(price=None, inst=None, rev=None, fin=None, flow_status="", core_hint=""):
    """v277｜發動前鎖碼分。

    只做「股價正式發動前 1～3 天」的籌碼/量價臨界點確認；
    不覆蓋 Core / Attack / Focus / 財報裁決。
    沒有家數差、集中度或融資資料時會自動降為觀察，不假裝資料完整。
    """
    price = price or {}; inst = inst or {}; rev = rev or {}; fin = fin or {}

    def _n(*keys):
        for k in keys:
            for src in (price, inst, rev, fin):
                if isinstance(src, dict) and k in src:
                    v = _v2765_num(src.get(k))
                    if v is not None:
                        return v
        return None

    close = _n("close"); open_p = _n("open"); high = _n("max", "high"); prev_close = _n("prev_close")
    ma20 = _n("ma20"); ma60 = _n("ma60"); high20 = _n("high20", "prev_high20"); low20 = _n("low20")
    support_ref = _n("recent_support", "support_ref", "main_support")
    chg5 = _n("ret5", "chg_5d", "pct_change_5d"); chg20 = _n("ret20", "chg_20d")
    volume_ratio = _n("volume_ratio", "vol_ratio")
    ma20_slope = _n("ma20_slope_5")
    daily_chg = _n("change_pct")
    if daily_chg is None and close is not None and prev_close not in [None, 0]:
        daily_chg = pct_change(close, prev_close)
    bias20 = pct_change(close, ma20) if close is not None and ma20 not in [None, 0] else None

    net5 = _n("net5_lot", "inst_5d")
    net20 = _n("net20_lot", "inst_20d")
    foreign5 = _n("foreign_net5_lot", "foreign_5d")
    trust5 = _n("trust_net5_lot", "sitc_5d")
    pos5 = int(_n("positive_days_5", "inst_buy_days_5") or 0)
    nets5 = _v2765_last_daily_net_lots(inst, 5)
    today = nets5[-1] if nets5 else _n("inst_today")
    net3 = sum(nets5[-3:]) if len(nets5) >= 3 else _n("inst_3d")

    revenue_yoy = _n("revenue_yoy", "latest_yoy", "revenue_1m_yoy")
    ytd_yoy = _n("revenue_ytd_yoy")
    family_diff = _n("family_diff", "holder_diff", "家數差", "家數差變化", "買賣家數差", "分點家數差")
    family_diff_3d = _n("family_diff_3d", "holder_diff_3d", "家數差3日", "家數差連續")
    concentration = _n("chip_concentration", "concentration", "top_broker_ratio", "籌碼集中度", "集中度")
    concentration_delta = _n("chip_concentration_delta", "concentration_delta", "籌碼集中度變化", "集中度變化")
    margin_delta = _n("margin_change_5d", "margin_balance_change_5d", "margin_5d", "margin_delta_5d", "融資增減", "融資5日", "融資餘額變化")
    blob = "｜".join([str(price), str(inst), str(rev), str(fin), str(flow_status), str(core_hint)])
    margin_warning = any(k in blob for k in ["融資暴增", "融資逆勢暴增", "散戶攤平", "融資攤平"])

    parts = {"not_overheat": 0, "compression": 0, "volume": 0, "chip": 0, "margin": 0, "aux": 0}
    evidence, warnings, missing, caps = [], [], [], []

    # A. 未過熱｜20
    if chg5 is not None and chg20 is not None and chg5 <= 8 and chg20 <= 20:
        parts["not_overheat"] += 5; evidence.append("短線未過熱")
    if daily_chg is None or daily_chg < 9.2:
        parts["not_overheat"] += 4
    if bias20 is not None and -5 <= bias20 <= 6:
        parts["not_overheat"] += 5; evidence.append(f"20MA乖離{bias20:.1f}%")
    if chg5 is not None and chg5 <= 6:
        parts["not_overheat"] += 3
    upper_shadow_risk = False
    if close is not None and open_p is not None and high is not None:
        body = abs(close - open_p); upper = high - max(close, open_p)
        upper_shadow_risk = bool(body > 0 and upper > body * 1.6 and (volume_ratio is None or volume_ratio >= 1.5))
    if not upper_shadow_risk:
        parts["not_overheat"] += 3
    else:
        warnings.append("長上影警示")

    # B. 壓縮末端｜20
    if close is not None and ma20 not in [None, 0] and close >= ma20:
        parts["compression"] += 4; evidence.append("站回MA20")
    if close is not None and ma60 not in [None, 0] and close >= ma60 * 0.97:
        parts["compression"] += 4; evidence.append("靠近/站上MA60")
    if ma20_slope is not None and ma20_slope >= 0:
        parts["compression"] += 4; evidence.append("MA20走平轉上")
    if close is not None and ma20 not in [None, 0] and ma60 not in [None, 0] and abs(ma20 - ma60) / abs(close) * 100 <= 5:
        parts["compression"] += 4; evidence.append("均線收斂")
    if close is not None and high20 not in [None, 0] and close >= high20 * 0.965 and (daily_chg is None or daily_chg <= 6):
        parts["compression"] += 4; evidence.append("接近整理區上緣")

    # C. 量能剛啟動｜15
    if volume_ratio is not None and 0.55 <= volume_ratio <= 1.15 and (chg5 is None or abs(chg5) <= 4):
        parts["volume"] += 4; evidence.append("前段量縮不跌")
    if volume_ratio is not None and 1.15 <= volume_ratio <= 1.9:
        parts["volume"] += 5; evidence.append(f"量能溫和放大{volume_ratio:.2f}x")
    if close is not None and open_p is not None and close > open_p:
        parts["volume"] += 3; evidence.append("紅K承接")
    if volume_ratio is None or volume_ratio < 3:
        parts["volume"] += 3
    else:
        warnings.append("爆量失控警示")

    # D. 籌碼集中｜25
    has_direct_chip_data = False
    if family_diff is not None:
        has_direct_chip_data = True
        if family_diff < 0:
            parts["chip"] += 5; evidence.append(f"家數差下降{family_diff:.0f}")
        elif family_diff > 0:
            warnings.append("家數差擴大")
    if family_diff_3d is not None:
        has_direct_chip_data = True
        if family_diff_3d < 0:
            parts["chip"] += 5; evidence.append("家數差連續下降")
    if concentration_delta is not None:
        has_direct_chip_data = True
        if concentration_delta > 0:
            parts["chip"] += 5; evidence.append("籌碼集中度上升")
    elif concentration is not None:
        has_direct_chip_data = True
        if concentration >= 25:
            parts["chip"] += 5; evidence.append(f"集中度{concentration:.1f}%")
    buyer_signal = bool((today is not None and today > 0) or (net3 is not None and net3 > 0) or (net5 is not None and net5 > 0 and pos5 >= 2))
    if buyer_signal:
        parts["chip"] += 4; evidence.append("法人短線買盤")
    if (foreign5 is not None and foreign5 > 0) or (trust5 is not None and trust5 > 0):
        parts["chip"] += 4; evidence.append("外資/投信其中一方買")
    if (chg5 is None or chg5 < 5) and (buyer_signal or net5 is not None):
        parts["chip"] += 2
    if not has_direct_chip_data:
        missing.append("家數差/集中度"); caps.append(75)
        if buyer_signal or (foreign5 is not None and foreign5 > 0) or (trust5 is not None and trust5 > 0):
            evidence.append("無家數差資料，以法人現貨代理")

    # E. 融資乾淨｜15
    if margin_delta is not None:
        if margin_delta <= 0:
            parts["margin"] += 5; evidence.append("融資未追")
        if margin_delta < 0:
            parts["margin"] += 4; evidence.append("融資退場")
        support_candidates = [x for x in [support_ref, ma20, ma60, low20] if x not in [None, 0]]
        if support_candidates and close is not None:
            sref = max([x for x in support_candidates if x <= close] or support_candidates)
            if close >= sref * 0.97 and margin_delta < 0:
                parts["margin"] += 3; evidence.append("守支撐洗融資")
        if daily_chg is not None and daily_chg > 0 and margin_delta <= 0:
            parts["margin"] += 3
    else:
        missing.append("融資"); caps.append(75)

    # F. 族群/基本面｜5
    if str(flow_status or "") in ["偷偷流入", "低基期轉強", "回檔轉強", "明面主流"]:
        parts["aux"] += 2
    if (revenue_yoy is not None and revenue_yoy >= 15) or (ytd_yoy is not None and ytd_yoy >= 10):
        parts["aux"] += 2; evidence.append("營收/基本面有轉折")
    if "偷偷" in str(flow_status or "") or "回檔" in str(flow_status or ""):
        parts["aux"] += 1

    score = sum(parts.values())
    if daily_chg is not None and daily_chg >= 9.2:
        caps.append(60); warnings.append("已接近漲停/大紅棒")
    if chg5 is not None and chg5 >= 12:
        caps.append(65); warnings.append("近5日漲幅過大")
    if bias20 is not None and bias20 >= 8:
        caps.append(60); warnings.append("20MA乖離過大")
    if volume_ratio is not None and volume_ratio >= 3 and upper_shadow_risk:
        caps.append(45); warnings.append("爆量長上影")
    if margin_warning or (margin_delta is not None and margin_delta > 1000):
        caps.append(55); warnings.append("融資暴增/攤平")
    if close is not None and ma60 not in [None, 0] and close < ma60 * 0.94:
        caps.append(55); warnings.append("跌破波段支撐")
    if caps:
        score = min(score, min(caps))
    score = round(clamp(score, 0, 100), 1)

    warn_blob = "｜".join(warnings)
    hard_warning = any(k in warn_blob for k in ["漲停", "大紅棒", "乖離過大", "爆量", "融資暴增", "跌破"])

    # v282.13｜發動前鎖碼語意校正：
    # 分數只代表「鎖碼完整度」；狀態才代表最後能不能放行。
    # 0~39 不成立；40~64 觀察；65 以上若無硬防呆/關鍵缺資料才成立。
    if hard_warning:
        state, label, note, adjust = "追高/失敗風險", "🔴 鎖碼失敗/追高風險", "鎖碼完整度雖有分數，但已被追高、過熱、破線或融資防呆否決；不追。", -8
    elif score >= 65 and not warnings and not missing:
        state, label, note, adjust = "發動前鎖碼成立", "🟢 發動前鎖碼成立", "鎖碼完整度達標，且沒有追高或資料缺口防呆；列優先觀察，等回測不破或突破不跌回。", 10
    elif score >= 40:
        state, label, note, adjust = "鎖碼觀察", "🟡 發動前鎖碼觀察", "有部分鎖碼味道，但條件還沒完整共振；先觀察，等家數差、融資、量價或支撐再確認。", 5
    else:
        state, label, note, adjust = "不成立", "🔴 鎖碼未成立", "鎖碼完整度不足，尚未看到足夠的發動前結構；不當作正式鎖碼。", 0

    strategy_tags = []
    if state == "發動前鎖碼成立":
        strategy_tags.append("發動前鎖碼")
        if "偷偷" in str(flow_status): strategy_tags.append("偷偷流入臨門一腳")
        if "回檔" in str(flow_status): strategy_tags.append("回檔再攻前兆")
        if "低基期" in str(flow_status): strategy_tags.append("轉機點火確認")
    elif state == "鎖碼觀察":
        strategy_tags.append("鎖碼觀察")
    elif state == "追高/失敗風險":
        strategy_tags.append("發動後不追")

    if state == "發動前鎖碼成立": action_hint = "可列優先待分析，等回測不破或突破不跌回。"
    elif state == "鎖碼觀察": action_hint = "先放觀察，等家數差/融資/量價再確認。"
    elif state == "追高/失敗風險": action_hint = "不追大紅棒，等降溫或直接排除。"
    else: action_hint = "資料或條件不足，先觀察。"

    evidence = list(dict.fromkeys([x for x in evidence if x]))[:7]
    warnings = list(dict.fromkeys([x for x in warnings if x]))
    missing = list(dict.fromkeys([x for x in missing if x]))
    return {
        "score": score,
        "state": state,
        "label": label,
        "note": note,
        "score_adjust": adjust,
        "strategy_tags": strategy_tags,
        "front_summary": state,
        "action_hint": action_hint,
        "evidence": evidence,
        "evidence_text": "；".join(evidence) if evidence else "—",
        "warnings": warnings,
        "warnings_text": "、".join(warnings),
        "missing": missing,
        "missing_text": "、".join(missing),
        "parts": parts,
        "is_positive": state == "發動前鎖碼成立",
        "is_watch": state in ["鎖碼觀察", "有苗頭"],
        "is_risk": state == "追高/失敗風險",
        "has_direct_chip_data": has_direct_chip_data,
        "has_margin_data": margin_delta is not None,
    }

def judge_rerating(rj, fj, price):
    score, txt = 0, []
    if rj["score"] >= 3:
        score += 2
        txt.append("營收變大有支撐")
    elif rj["score"] >= 1:
        score += 1
        txt.append("營收有成長但強度待驗證")
    else:
        txt.append("營收成長力道不足")
    if fj["margin"] == "有":
        score += 2
        txt.append("毛利率 / 營益率支撐")
    elif fj["margin"] == "普通":
        score += 1
        txt.append("毛利結構部分支撐")
    else:
        txt.append("毛利率 / 營益率未支持")
    if fj["revenue_to_eps"] == "有":
        score += 2
        txt.append("營收有轉 EPS")
    elif fj["revenue_to_eps"] == "部分有":
        score += 1
        txt.append("EPS 部分跟上")
    else:
        txt.append("EPS 未跟上")
    if fj["growth_quality"] == "不通過":
        score -= 2
        txt.append("成長動能未通過，限制重評")
    elif fj["growth_quality"] == "通過":
        score += 1
        txt.append("成長動能通過")
    if fj["cashflow"] == "有":
        score += 1
        txt.append("現金流支撐")
    elif fj["cashflow"] == "不配合":
        score -= 2
        txt.append("現金流扣分")
    if fj["limit_rerating"]:
        score -= 2
        txt.append("法醫硬審限制 Re-rating")
    if (
        price
        and price.get("close")
        and price.get("ma20")
        and price["close"] / price["ma20"] > 1.18
    ):
        score -= 1
        txt.append("短線乖離過大")
    verdict = (
        "成立"
        if score >= 5 and not fj["limit_rerating"]
        else "部分成立"
        if score >= 2
        else "不成立"
    )
    return {
        "score": score,
        "verdict": verdict,
        "text": "；".join(txt),
    }



# ============================================================
# v269｜估值作戰引擎：EPS 三情境＋法醫斷路器
# 目的：不用每檔都靠 GPT / 法醫報告；APP 先自算，再由法醫 v6.7 參數做最高權限校正。
# ============================================================

def _nick_v269_ratio(x, default=None):
    """把 20 / 20% / 0.20 都轉成 0.20。"""
    try:
        if x is None:
            return default
        v = to_float(x)
        if v is None:
            return default
        if abs(v) > 2:
            return v / 100.0
        return v
    except Exception:
        return default


def _nick_v269_mul_range(rng, multiplier):
    if not rng or len(rng) < 2:
        return rng
    try:
        return (float(rng[0]) * multiplier, float(rng[1]) * multiplier)
    except Exception:
        return rng


def calculate_forensic_eps_scenarios_v269(
    ttm_eps=None,
    base_eps=None,
    annualized_eps=None,
    revenue_yoy=None,
    eps_yoy=None,
    fin=None,
    fj=None,
    model_key="",
):
    """
    v269｜APP 自算 EPS 三情境。
    公式不是為了取代法醫，而是讓 APP 在沒有法醫報告時先有一個可防呆的估值骨架。
    """
    fin = fin or {}
    fj = fj or {}
    base = to_float(base_eps) or to_float(ttm_eps) or to_float(annualized_eps)
    if base is None or base <= 0:
        return {
            "ok": False,
            "reason": "EPS 基礎不足，無法自算三情境",
            "eps_conservative": None,
            "eps_neutral": None,
            "eps_optimistic": None,
            "growth_coefficient": 0,
        }

    rev = _nick_v269_ratio(revenue_yoy, 0.0)
    eps_g = _nick_v269_ratio(eps_yoy, None)
    # 基期防呆：營收暴增常來自低基期或一次性大單，修正係數封頂。
    if rev is None:
        rev = 0.0
    growth_cap = 0.25 if rev > 0.50 else 0.35
    growth_coef = max(-0.20, min(rev, growth_cap))

    eps_conservative = round(base * 0.90, 2)
    eps_neutral = round(base * (1 + growth_coef), 2)

    margin_ok = str(fj.get("margin") or "") in ["有", "普通", ""]
    rev_to_eps_ok = str(fj.get("revenue_to_eps") or "") in ["有", "部分有", "無法判斷", ""]
    eps_bad = (eps_g is not None and eps_g < -0.05) or str(fj.get("eps") or "") == "沒有"
    if rev > 0 and margin_ok and rev_to_eps_ok and not eps_bad:
        eps_optimistic = round(base * (1 + min(rev * 1.20, 0.45)), 2)
    else:
        # 法醫精神：營收有成長但毛利 / EPS 沒跟上，不准硬推樂觀價。
        eps_optimistic = eps_neutral

    # 最近一季年化只做輔助，不直接無限制外推。
    ann = to_float(annualized_eps)
    if ann is not None and ann > 0:
        eps_neutral = round(max(eps_neutral, min(ann * 0.90, base * 1.25)), 2)
        eps_optimistic = round(max(eps_optimistic, min(ann * 1.00, base * 1.35)), 2)

    return {
        "ok": True,
        "eps_conservative": eps_conservative,
        "eps_neutral": eps_neutral,
        "eps_optimistic": eps_optimistic,
        "growth_coefficient": growth_coef,
        "revenue_yoy_ratio": rev,
        "eps_yoy_ratio": eps_g,
        "method": "TTM/Base EPS × 營收年增修正；毛利/EPS 未跟上則鎖樂觀情境",
        "note": "APP 自算估值骨架；若有 v6.7 法醫結構參數，仍以法醫 EPS / PE 為最高權限。",
    }



def classify_inventory_receivable_context_v270(fin=None, fj=None, sector_money_flow=None, trend_status=None):
    """
    v270｜存貨 / 應收不是一刀切打折，而是先判斷商業情境。

    核心規則：
    - 健康備貨：有營收/需求/毛利支撐，存貨上升可能是未來出貨準備，不折價，列入預期差觀察。
    - 中性觀察：資料尚未接上，不直接折價，但重評需要後續營收 / EPS 驗證。
    - 危險堆貨：營收弱、毛利/營益率惡化、現金流或應收同步轉差，才 PE 打折。
    """
    fin = fin or {}
    fj = fj or {}

    inv_ar_status = str(fj.get("inv_ar") or "").strip()
    cashflow_status = str(fj.get("cashflow") or "").strip()
    margin_status = str(fj.get("margin") or "").strip()
    eps_status = str(fj.get("eps") or "").strip()

    rev_yoy = _nick_v269_ratio(fin.get("revenue_yoy"), None)
    rev_mom = _nick_v269_ratio(fin.get("revenue_mom"), None)
    cumulative_rev_yoy = _nick_v269_ratio(fin.get("cumulative_revenue_yoy"), None)
    eps_yoy = _nick_v269_ratio(fin.get("eps_yoy"), None)
    gm_yoy = _nick_v269_ratio(fin.get("gross_margin_yoy"), None)
    opm_yoy = _nick_v269_ratio(fin.get("operating_margin_yoy"), None)
    inventory_yoy = _nick_v269_ratio(fin.get("inventory_yoy"), None)
    receivable_yoy = _nick_v269_ratio(fin.get("receivable_yoy"), None)

    has_wc_warning = inv_ar_status in ["稍高", "異常"] or (
        (inventory_yoy is not None and inventory_yoy > 0.20) or
        (receivable_yoy is not None and receivable_yoy > 0.20)
    )
    if not has_wc_warning:
        return {
            "classification": "正常",
            "action": "no_discount",
            "pe_multiplier": 1.0,
            "limit_rerating": False,
            "expectation_gap_watch": False,
            "message": "存貨 / 應收未觸發異常警示。",
            "evidence": [],
        }

    revenue_support = False
    for x in [rev_yoy, cumulative_rev_yoy, rev_mom]:
        if x is not None and x > 0.10:
            revenue_support = True
    strong_revenue_support = False
    for x in [rev_yoy, cumulative_rev_yoy]:
        if x is not None and x > 0.25:
            strong_revenue_support = True

    margin_bad = (margin_status == "沒有") or (gm_yoy is not None and gm_yoy < -0.03) or (opm_yoy is not None and opm_yoy < -0.03)
    margin_ok = (margin_status in ["有", "普通", "", "無法判斷"]) and not margin_bad
    cash_bad = cashflow_status == "不配合"
    eps_bad = eps_status == "沒有" or (eps_yoy is not None and eps_yoy < -0.10)
    ar_bad = inv_ar_status == "異常" or (receivable_yoy is not None and receivable_yoy > 0.30)

    sector_hot = str(sector_money_flow or "").lower() in ["strong", "hyper_active", "hot", "active", "資金強", "hyper"]
    trend_strong = str(trend_status or "").lower() in ["strong_up", "up", "bull", "right_up", "強勢"]

    evidence = []
    if inv_ar_status:
        evidence.append(f"存貨/應收狀態：{inv_ar_status}")
    if rev_yoy is not None:
        evidence.append(f"營收YoY約{rev_yoy*100:.1f}%")
    if cumulative_rev_yoy is not None:
        evidence.append(f"累計營收YoY約{cumulative_rev_yoy*100:.1f}%")
    if gm_yoy is not None:
        evidence.append(f"毛利YoY約{gm_yoy*100:.1f}%")
    if opm_yoy is not None:
        evidence.append(f"營益YoY約{opm_yoy*100:.1f}%")

    # 健康備貨：存貨/應收升高，但營收/需求或趨勢已轉強，毛利與 EPS 未明顯惡化。
    if (strong_revenue_support or (revenue_support and (sector_hot or trend_strong))) and margin_ok and not cash_bad and not eps_bad:
        return {
            "classification": "健康備貨",
            "action": "no_discount_expectation_gap_watch",
            "pe_multiplier": 1.0,
            "limit_rerating": False,
            "expectation_gap_watch": True,
            "message": "存貨 / 應收上升可能是因應後續出貨或訂單備貨；不做 PE 折價，列入預期差觀察，需看未來 1～2 個月營收是否接棒。",
            "evidence": evidence,
        }

    # 危險堆貨：營收弱/下滑 + 毛利或 EPS 或現金流惡化，才執行折價。
    weak_revenue = (rev_yoy is not None and rev_yoy < 0.03) and (cumulative_rev_yoy is None or cumulative_rev_yoy < 0.05)
    if (inv_ar_status == "異常" or ar_bad) and weak_revenue and (margin_bad or cash_bad or eps_bad):
        return {
            "classification": "危險堆貨",
            "action": "pe_discount",
            "pe_multiplier": 0.80,
            "limit_rerating": True,
            "expectation_gap_watch": False,
            "message": "存貨 / 應收上升且營收、毛利/EPS/現金流沒有接棒，較像危險堆貨或塞貨；PE 需折價並限制 Re-rating。",
            "evidence": evidence,
        }

    # 中性觀察：不直接打折，但不要因存貨備貨就自動升級重評。
    return {
        "classification": "中性觀察",
        "action": "watch_only",
        "pe_multiplier": 1.0,
        "limit_rerating": False,
        "expectation_gap_watch": False,
        "message": "存貨 / 應收上升但證據尚不足以判定健康備貨或危險堆貨；暫不 PE 折價，但重評需等營收、毛利率與 EPS 接棒。",
        "evidence": evidence,
    }


def calculate_expectation_gap_radar_v270(cfo_valuation=None, forensic_valuation=None, current_price=None, evidence_tags=None, financial_alert=False):
    """
    v270｜預期差雷達：不是用來直接下買賣結論，而是判斷 APP 歷史模型與法醫未來洞察是否產生重大裂口。
    """
    cfo = to_float(cfo_valuation)
    forensic = to_float(forensic_valuation)
    price = to_float(current_price)
    evidence_tags = evidence_tags or []
    ref = forensic if forensic not in [None, 0] else price
    gap_rate = None
    if cfo not in [None, 0] and ref not in [None, 0]:
        gap_rate = (float(ref) - float(cfo)) / abs(float(cfo))

    abs_gap = abs(gap_rate) if gap_rate is not None else 0
    has_structural_evidence = any(str(x).strip() for x in evidence_tags)
    if gap_rate is None:
        deviation_type = "資料不足"
        need_forensic = False
    elif abs_gap < 0.15:
        deviation_type = "正常偏離"
        need_forensic = False
    elif abs_gap >= 0.25 and has_structural_evidence and gap_rate > 0:
        deviation_type = "模型盲區（可能預期差黃金區）"
        need_forensic = True
    elif abs_gap >= 0.25 and gap_rate > 0 and not has_structural_evidence:
        deviation_type = "法醫過度樂觀風險 / 需證據交換"
        need_forensic = True
    elif abs_gap >= 0.25 and gap_rate < 0:
        deviation_type = "法醫較保守 / APP 可能高估"
        need_forensic = True
    else:
        deviation_type = "中度偏離"
        need_forensic = bool(financial_alert)

    return {
        "cfo_base_valuation": cfo,
        "forensic_future_valuation": forensic,
        "current_price": price,
        "valuation_gap_rate": gap_rate,
        "deviation_type": deviation_type,
        "need_forensic_dissection": need_forensic,
        "evidence_tags": evidence_tags,
        "note": "預期差只代表需要解剖，不代表可買；法醫若要推翻 CFO 估值，需提出營收、毛利率、訂單、產品組合或產業地位改變證據。",
    }


def check_forensic_trigger_conditions_v270(cfo_valuation=None, current_price=None, gap_rate=None, sector_money_flow=None, trend_status=None, financial_alert=False, forensic_valuation=None, evidence_tags=None):
    """v270｜法醫盲區觸發器：穩定告訴 Nick 哪些股票需要法醫，不是直接判買進。"""
    triggers = []
    cfo = to_float(cfo_valuation)
    price = to_float(current_price)
    gap = _nick_v269_ratio(gap_rate, None)
    sector_hot = str(sector_money_flow or "").lower() in ["strong", "hyper_active", "hot", "active", "資金強", "hyper"]
    trend_strong = str(trend_status or "").lower() in ["strong_up", "up", "bull", "right_up", "強勢"]

    if cfo not in [None, 0] and price is not None and price > cfo * 1.25 and trend_strong:
        triggers.append("【預期差裂口】CFO 歷史估值已追不上現行股價強勢，可能存在尚未入模的催化劑或結構性轉變。")
    if financial_alert and sector_hot:
        triggers.append("【拐點質變警報】落後財報欠佳，但族群資金出現結構性進駐，需法醫確認是利空出盡還是真轉強。")
    if gap is not None and abs(gap) > 0.25:
        triggers.append(f"【估值極端偏離】APP 歷史模型與法醫/市場未來洞察產生約 {gap*100:.1f}% 的預期差，需拆解原因。")
    if evidence_tags:
        # 有證據但 APP 仍保守，通常正是法醫值得介入的地方。
        if cfo not in [None, 0] and price is not None and price > cfo * 1.15:
            triggers.append("【證據交換】已有新產品/訂單/毛利改善等證據，但 APP 估值仍保守，需判斷是否更新族群規則卡或單檔 override。")

    return {
        "need_forensic_dissection": len(triggers) > 0,
        "trigger_reasons": triggers,
        "role_note": "APP 是保守 CFO，負責提出反方；法醫是預期差獵人，負責用證據推翻或確認 CFO 的保守估值。",
    }

def apply_forensic_valuation_circuit_breakers_v269(
    pe_scenarios,
    eps_scenarios,
    future_eps,
    fin=None,
    fj=None,
    model_key="",
    valuation_submodel_key="",
):
    """v269｜法醫斷路器：先找不能高估的理由，再允許估值重評。"""
    fin = fin or {}
    fj = fj or {}
    pe = {k: tuple(v) for k, v in (pe_scenarios or {}).items() if v}
    eps_box = dict(eps_scenarios or {})
    breakers = []
    locked_rerating = False

    rev = _nick_v269_ratio(fin.get("revenue_yoy"), None)
    eps_g = _nick_v269_ratio(fin.get("eps_yoy"), None)
    gm_yoy = _nick_v269_ratio(fin.get("gross_margin_yoy"), None)
    opm_yoy = _nick_v269_ratio(fin.get("operating_margin_yoy"), None)

    margin_failed = str(fj.get("margin") or "") == "沒有"
    margin_structural_down = False
    if gm_yoy is not None and opm_yoy is not None:
        margin_structural_down = gm_yoy < 0 and opm_yoy < 0
    elif opm_yoy is not None:
        margin_structural_down = opm_yoy < 0

    # 斷路器 A：毛利/營益率惡化，沒收樂觀與重評。
    if margin_failed or margin_structural_down:
        breakers.append("毛利率/營益率未支撐：沒收樂觀 EPS 與重評 PE")
        if eps_box.get("eps_conservative") is not None:
            eps_box["eps_optimistic"] = eps_box.get("eps_conservative")
            if future_eps is not None:
                future_eps = min(float(future_eps), float(eps_box.get("eps_neutral") or eps_box.get("eps_conservative") or future_eps))
        if "neutral" in pe:
            pe["opt"] = pe["neutral"]
            pe["rerating"] = pe["neutral"]
            pe["market_premium"] = pe["neutral"]
        locked_rerating = True

    # v271｜財報訊號分類器：先分類企業行為，再決定是否折價。
    financial_signal_radar_v271 = fj.get("financial_signal_radar_v271") if isinstance(fj, dict) else None
    if not financial_signal_radar_v271:
        financial_signal_radar_v271 = classify_financial_signals_v271(fin=fin, fj=fj, model_key=model_key)

    # v270｜存貨 / 應收不是原罪：先判斷健康備貨 / 中性觀察 / 危險堆貨。
    wc_context = classify_inventory_receivable_context_v270(fin=fin, fj=fj)
    wc_class = wc_context.get("classification")
    try:
        _v271_signals = financial_signal_radar_v271.get("signals", {}) or {}
        _inv_sig = (_v271_signals.get("inventory") or {}).get("classification")
        _ar_sig = (_v271_signals.get("receivable") or {}).get("classification")
        if _inv_sig == "危險堆貨" or _ar_sig in ["塞貨 / 呆帳風險"]:
            wc_class = "危險堆貨"
            wc_context["classification"] = wc_class
            wc_context["message"] = "v271 財報訊號分類器判定營運周轉有高風險。"
        elif _inv_sig == "健康備貨" or _ar_sig == "大客戶出貨放大":
            wc_class = "健康備貨"
            wc_context["classification"] = wc_class
            wc_context["expectation_gap_watch"] = True
            wc_context["message"] = "v271 財報訊號分類器判定可能是備貨 / 出貨放大，需營收與現金流驗證。"
    except Exception:
        pass
    if wc_class == "健康備貨":
        breakers.append("存貨/應收：健康備貨，不折價，列入預期差觀察")
    elif wc_class == "中性觀察":
        breakers.append("存貨/應收：中性觀察，不直接折價，重評需營收與 EPS 接棒")
    elif wc_class == "危險堆貨":
        breakers.append("存貨/應收：危險堆貨，PE 情境打 8 折並限制 Re-rating")
        for k in list(pe.keys()):
            pe[k] = _nick_v269_mul_range(pe[k], 0.80)
        locked_rerating = True
    elif wc_class and wc_class != "正常":
        breakers.append(f"存貨/應收：{wc_class}")

    # 斷路器 C：營收暴增但 EPS 沒跟上，鎖 Re-rating。
    if rev is not None and rev > 0.40 and (eps_g is None or eps_g < 0.10 or str(fj.get("eps") or "") == "沒有"):
        breakers.append("營收暴增但 EPS 沒跟上：不准估值重評")
        if "neutral" in pe:
            pe["rerating"] = pe.get("neutral")
            pe["market_premium"] = pe.get("neutral")
        locked_rerating = True

    # 法醫硬審限制 Re-rating。
    if bool(fj.get("limit_rerating")):
        breakers.append("法醫硬審限制 Re-rating：重評狀態鎖為不成立/部分成立")
        if "neutral" in pe:
            pe["rerating"] = pe.get("neutral")
            pe["market_premium"] = pe.get("neutral")
        locked_rerating = True

    return {
        "pe_scenarios": pe or pe_scenarios,
        "eps_scenarios": eps_box,
        "future_eps": future_eps,
        "breakers": breakers,
        "rerating_locked": locked_rerating,
        "working_capital_context": wc_context if 'wc_context' in locals() else {},
        "financial_signal_radar_v271": financial_signal_radar_v271 if 'financial_signal_radar_v271' in locals() else {},
    }


def build_valuation_recheck_alert_v269(close=None, future_eps=None, pe_scenarios=None, ranges=None, rr=None, inst=None):
    """當市場價格明顯超出 APP 估值，但資金仍強時，提醒啟動法醫校正，而非死板判太貴。"""
    close_f = to_float(close)
    eps_f = to_float(future_eps)
    if close_f is None or close_f <= 0 or eps_f is None or eps_f <= 0:
        return {"trigger": False, "message": ""}
    pe = pe_scenarios or {}
    max_model_pe = None
    try:
        max_model_pe = float((pe.get("market_premium") or pe.get("rerating") or (None, None))[1])
    except Exception:
        max_model_pe = None
    implied = close_f / eps_f if eps_f else None
    if max_model_pe and implied and implied > max_model_pe * 1.25:
        return {
            "trigger": True,
            "message": "現價隱含 PE 明顯高於 APP 模型上緣，可能存在 APP 未辨識的結構性轉變、法說新展望或新訂單能見度；建議啟動法醫報告校正。",
            "implied_future_pe": implied,
            "model_pe_cap": max_model_pe,
        }
    # 用區間檢查價格是否遠高於市場溢價區。
    try:
        mp = (ranges or {}).get("market_premium")
        if mp and mp[1] and close_f > float(mp[1]) * 1.25:
            return {
                "trigger": True,
                "message": "現價高於 APP 市場溢價區上緣 25% 以上；若法人仍買、股價續強，需重新法醫確認是否有新 Re-rating。",
                "implied_future_pe": implied,
                "model_price_cap": float(mp[1]),
            }
    except Exception:
        pass
    return {"trigger": False, "message": ""}

def estimate_value(
    fin, fj, rr, stock, price=None, industry_category=None, override_model_key=None, bal=None, valratio=None
):
    if not fin:
        return {
            "ok": False,
            "reason": "財報資料不足，無法估值",
        }
    ttm_eps = fin.get("ttm_eps")
    quarter_eps = fin.get("eps")
    annualized_eps = (
        quarter_eps * 4 if quarter_eps is not None and quarter_eps > 0 else None
    )
    if (ttm_eps is None or ttm_eps <= 0) and (
        annualized_eps is None or annualized_eps <= 0
    ):
        return {
            "ok": False,
            "reason": "近四季 EPS 與單季年化 EPS 不足或不為正，無法估值",
        }
    # ── EPS 基礎防呆：不可把單季 EPS 直接乘年度 PE ─────────────
    suspect_single_quarter_as_ttm = (
        ttm_eps is not None
        and quarter_eps is not None
        and ttm_eps > 0
        and quarter_eps > 0
        and ttm_eps <= quarter_eps * 1.6
    )
    if suspect_single_quarter_as_ttm and annualized_eps is not None:
        # 資料源有時把最新一季 EPS 塞進 TTM 欄位；此時改用單季年化作輔助。
        base_eps = annualized_eps
        base_eps_label = "最近一季 EPS 年化（TTM 疑似單季值，已防呆）"
        eps_basis_warning = "TTM EPS 疑似只抓到單季 EPS，已改用最近一季 EPS 年化輔助；仍需人工複核近四季 EPS。"
    else:
        base_eps = ttm_eps if ttm_eps is not None and ttm_eps > 0 else annualized_eps
        base_eps_label = "近四季 EPS" if ttm_eps is not None and ttm_eps > 0 else "最近一季 EPS 年化"
        eps_basis_warning = ""

    rev_yoy = to_float(fin.get("revenue_yoy"))
    eps_yoy = to_float(fin.get("eps_yoy"))
    _pre_model_key = override_model_key if override_model_key in MODEL_CONFIG else get_model_key(stock, industry_category)
    _is_highspeed_material = _pre_model_key == "ai_highspeed_materials"
    _is_abf_substrate = _pre_model_key == "abf_substrate"
    _is_advanced_packaging_osat = _pre_model_key == "advanced_packaging_osat"
    _is_memory_cyclical_distributor = _pre_model_key == "memory_cyclical_distributor"
    _is_defensive_cashflow_treasury = _pre_model_key == "defensive_cashflow_treasury"
    _is_financial_holding_life_revaluation = _pre_model_key == "financial_holding_life_revaluation"
    _is_financial_bank_core = _pre_model_key == "financial_bank_core"
    _is_financial_brokerage_cycle = _pre_model_key == "financial_brokerage_cycle"
    _is_financial_general_core = _pre_model_key == "financial_general_core"
    _is_real_estate_delivery = _pre_model_key == "real_estate_delivery_recognition"
    _is_biotech_commercial_drug = _pre_model_key == "biotech_commercial_drug_growth"
    _is_consumer_restaurant_stable = _pre_model_key == "consumer_restaurant_stable"
    _is_ccl_highend_highspeed = _pre_model_key == "ccl_highend_highspeed"
    _is_ccl_general_highspeed = _pre_model_key == "ccl_general_highspeed"
    _is_copper_foil_cyclical = _pre_model_key == "copper_foil_cyclical"
    _is_hvlp_copper_foil_growth = _pre_model_key == "hvlp_copper_foil_growth"
    _is_glass_fiber_cyclical = _pre_model_key == "glass_fiber_cyclical"
    _is_abf_bt_substrate_cycle = _pre_model_key == "abf_bt_substrate_cycle"
    _is_ai_server_pcb_core = _pre_model_key == "ai_server_pcb_core"
    _is_pcb_drill_consumables = _pre_model_key == "pcb_drill_consumables"
    _is_general_pcb_hdi_candidate = _pre_model_key == "general_pcb_hdi_candidate"
    _is_panel_turnaround_rerating = _pre_model_key == "panel_turnaround_rerating"
    _is_memory_manufacturing_cycle_rerating = _pre_model_key == "memory_manufacturing_cycle_rerating"
    # 成長假設改成「財報有根」：營收、EPS、毛利/營益率同步愈強，未來 12 個月 EPS 才能往上推。
    # fix25：AI 高階 CCL / 高速材料若 Q1 財報與營收明確加速，不能用一般成長股低成長假設。
    # fix26：AI 高階 ABF / BT 載板若景氣循環復甦且 Q1 EPS 已明顯轉強，
    # 不能只用 TTM EPS 小幅成長；要允許最近一季 EPS run-rate 成為未來 12 個月 EPS 輔助。
    if _is_memory_manufacturing_cycle_rerating:
        # fix76｜記憶體製造景氣反轉：子模組是分析框架，Core 仍看法醫硬門檻。
        # 記憶體製造若最近一季 EPS、毛利率、營益率已爆發，支撐價主估應用正常化 EPS；P/B 僅作風險檢查。
        growth = 0.00 if fj["report"] == "通過" else -0.20
    elif _is_panel_turnaround_rerating:
        # fix75｜面板轉機重評：未來 EPS 可以有轉機假設，但必須靠 Q2 EPS / 月營收 / 雙率驗證。
        # 不把近四季低 EPS 直接壓死，也不把單季轉盈直接當高成長股。
        growth = 0.18 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_advanced_packaging_osat:
        # fix33｜先進封裝 / 封測龍頭 EPS 基礎防呆：
        # 有些資料源的 rev_yoy / eps_yoy / margin 欄位會缺漏或被歸類成觀察，
        # 但模型已經被明確指定為 advanced_packaging_osat 時，
        # 只要財報本體不是不通過，就不能回到近四季 EPS 原地估值。
        # 先用 22% 作保守 2026 EPS 成長假設；若財報不通過才降為 8%。
        growth = 0.22 if fj["report"] in ["通過", "部分通過"] else 0.08
    elif _is_memory_cyclical_distributor:
        # fix37｜記憶體循環 / 低毛利通路：
        # EPS 可因報價循環上修，但低毛利、現金流與週轉壓力限制估值，不給高成長股倍數。
        # 用 EPS 上修 + 低 PE，而不是低 EPS + 高 PE。
        growth = 0.25 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_defensive_cashflow_treasury:
        # fix40｜防守型現金流金庫：
        # 中華電這類不是高爆發股，未來 EPS 只給溫和成長假設，估值靠防守溢價 / 現金流穩定性。
        growth = 0.03 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_financial_holding_life_revaluation:
        # fix42｜金控壽險資產重評：
        # 金控壽險股可因資產重評 / FVOCI / 配息能力上修 EPS，但不能把單月爆賺直接年化。
        growth = 0.15 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_financial_bank_core:
        growth = 0.04 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_financial_brokerage_cycle:
        growth = 0.08 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_financial_general_core:
        growth = 0.03 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_real_estate_delivery:
        # fix48｜建商交屋認列：
        # 交屋潮進入財報時，TTM EPS 可能落後最新一季 run-rate；但營收認列跳動，不能無限年化。
        growth = 0.20 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_biotech_commercial_drug:
        # fix50｜商業化新藥：
        # 高毛利新藥平台若月營收、EPS 與營益率同向，未來 12 個月 EPS 可高於 TTM。
        growth = 0.35 if fj["report"] == "通過" else 0.10
    elif _is_consumer_restaurant_stable:
        # fix52｜穩健內需餐飲：
        # EPS 可溫和上修，但不是爆發型成長股。
        growth = 0.10 if fj["report"] == "通過" else 0.03
    elif _is_ccl_highend_highspeed:
        growth = 0.28 if fj["report"] == "通過" else 0.10
    elif _is_ccl_general_highspeed:
        growth = 0.15 if fj["report"] in ["通過", "部分通過"] else 0.03
    elif _is_hvlp_copper_foil_growth:
        growth = 0.75 if fj["report"] == "通過" else 0.20
    elif _is_copper_foil_cyclical or _is_glass_fiber_cyclical:
        growth = 0.12 if fj["report"] in ["通過", "部分通過", "部分通過偏強"] else 0.00
    elif _is_abf_bt_substrate_cycle:
        growth = 0.25 if fj["report"] == "通過" else 0.08
    elif _is_ai_server_pcb_core:
        growth = 0.22 if fj["report"] == "通過" else 0.08
    elif _is_pcb_drill_consumables:
        growth = 0.18 if fj["report"] in ["通過", "部分通過"] else 0.03
    elif _is_general_pcb_hdi_candidate:
        growth = 0.08 if fj["report"] in ["通過", "部分通過"] else 0.00
    elif _is_abf_substrate and rev_yoy is not None and rev_yoy >= 25 and fj["revenue_to_eps"] in ["有", "部分有"] and fj["margin"] in ["有", "普通"]:
        growth = 0.85
    elif _is_abf_substrate and rev_yoy is not None and rev_yoy >= 15 and fj["revenue_to_eps"] in ["有", "部分有"]:
        growth = 0.65
    elif _is_highspeed_material and rev_yoy is not None and eps_yoy is not None and rev_yoy >= 45 and eps_yoy >= 35 and fj["revenue_to_eps"] in ["有", "部分有"] and fj["margin"] in ["有", "普通"]:
        growth = 0.55
    elif _is_highspeed_material and rev_yoy is not None and eps_yoy is not None and rev_yoy >= 30 and eps_yoy >= 25 and fj["revenue_to_eps"] in ["有", "部分有"]:
        growth = 0.45
    elif rev_yoy is not None and eps_yoy is not None and rev_yoy >= 30 and eps_yoy >= 50 and fj["margin"] in ["有", "普通"]:
        growth = 0.35
    elif rev_yoy is not None and eps_yoy is not None and rev_yoy >= 40 and eps_yoy >= 25 and fj["revenue_to_eps"] in ["有", "部分有"]:
        growth = 0.30
    elif eps_yoy is not None and eps_yoy > 30 and fj["margin"] in ["有", "普通"]:
        growth = 0.24
    elif rev_yoy is not None and rev_yoy > 20 and fj["revenue_to_eps"] in ["有", "部分有"]:
        growth = 0.18
    elif fj["financial_quality"] == "高" and fj["growth_quality"] in ["通過", "部分通過"]:
        growth = 0.12
    elif fj["financial_quality"] == "中":
        growth = 0.05
    else:
        growth = -0.05

    ttm_projected = base_eps * (1 + growth)
    if annualized_eps is not None and annualized_eps > 0 and not suspect_single_quarter_as_ttm:
        if _is_advanced_packaging_osat:
            # fix33｜先進封裝 / 封測龍頭：
            # 不靠單一欄位判斷是否套用 run-rate。只要是此模型，就用「TTM 成長假設 + 單季年化上限」雙軌保守取高。
            future_eps = max(ttm_projected, min(annualized_eps * 1.05, base_eps * 1.35))
            future_eps_note = "採近四季 EPS × 成長假設，並以最近一季年化作先進封裝 / 封測 run-rate 輔助"
        elif _is_abf_substrate and rev_yoy is not None and rev_yoy >= 20 and fj["revenue_to_eps"] in ["有", "部分有"] and fj["margin"] in ["有", "普通"]:
            # ABF / 高階載板復甦初期，TTM EPS 會落後最新一季 run-rate。
            # 但仍不能直接把單季 EPS 無限制年化，因此用 annualized_eps × 1.08 並加上 base_eps 上限防呆。
            future_eps = max(ttm_projected, min(annualized_eps * 1.08, base_eps * 2.20))
            future_eps_note = "採近四季 EPS × 成長假設，並以最近一季年化作 ABF 復甦 run-rate 輔助"
        else:
            # 年化 EPS 只能輔助：若與 TTM 推估差距太大，最多只取 15% 緩衝，避免單季暴衝扭曲估值。
            future_eps = max(ttm_projected, min(annualized_eps, base_eps * 1.15))
            future_eps_note = "採近四季 EPS × 成長假設，最近一季年化僅作 run-rate 輔助"
    else:
        future_eps = ttm_projected
        future_eps_note = "採 EPS 基礎 × 成長假設；未直接使用單季 EPS 乘年度 PE"
    if eps_basis_warning:
        future_eps_note += "；" + eps_basis_warning
    # fix41｜金控壽險資產重評 EPS 防呆：
    # 避免把 4 月爆賺直接年化；使用近四季 EPS / 系統 EPS 的有限上修做支撐。
    if _is_financial_holding_life_revaluation and base_eps is not None and base_eps > 0:
        _fin_life_eps = base_eps * (1.18 if fj["report"] in ["通過", "部分通過"] else 1.00)
        if future_eps is None or future_eps < _fin_life_eps:
            future_eps = _fin_life_eps
        future_eps_note = "採近四季 EPS × 金控壽險資產重評有限上修假設，不直接單月年化"

    # fix42｜一般金融 / 銀行 / 證券 EPS 防呆：
    # 金融股避免用製造業單季年化與毛利率邏輯，採有限上修 / 景氣循環假設。
    if (_is_financial_bank_core or _is_financial_general_core) and base_eps is not None and base_eps > 0:
        # fix43｜銀行型金控 EPS 支撐上修：
        # 銀行型金控若最新一季 EPS 明顯強，TTM 可能落後當年獲利節奏。
        # 但仍不可直接無限年化，因此取「近四季有限上修」與「最近一季年化保守折扣」的高者。
        if _is_financial_bank_core:
            _fin_core_eps_candidates = [base_eps * (1.12 if fj["report"] in ["通過", "部分通過"] else 1.00)]
            if annualized_eps is not None and annualized_eps > 0:
                _fin_core_eps_candidates.append(annualized_eps * 1.02)
            _fin_core_eps = max(_fin_core_eps_candidates)
            _fin_core_note = "採近四季 EPS 有限上修，並用最近一季年化作銀行型金控支撐輔助"
        else:
            _fin_core_eps = base_eps * (1.05 if fj["report"] in ["通過", "部分通過"] else 1.00)
            _fin_core_note = "採近四季 EPS × 金融股有限成長假設"
        if future_eps is None or future_eps < _fin_core_eps:
            future_eps = _fin_core_eps
            future_eps_note = _fin_core_note
    if _is_ccl_highend_highspeed and base_eps is not None and base_eps > 0:
        _ccl_eps_candidates = [base_eps * (1.28 if fj["report"] == "通過" else 1.10)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] == "通過":
            _ccl_eps_candidates.append(annualized_eps * 0.85)
        _ccl_eps = max(_ccl_eps_candidates)
        if future_eps is None or future_eps < _ccl_eps:
            future_eps = _ccl_eps
            future_eps_note = "採近四季 EPS + 最近一季高階材料 run-rate 保守折扣；需用營收、毛利率、EPS 與法人預期驗證"

    if (_is_copper_foil_cyclical or _is_glass_fiber_cyclical) and base_eps is not None and base_eps > 0:
        _mat_eps = base_eps * (1.12 if fj["report"] in ["通過", "部分通過", "部分通過偏強"] else 1.00)
        if future_eps is None or future_eps < _mat_eps:
            future_eps = _mat_eps
            future_eps_note = "採材料循環保守 EPS 修復，不使用高階 CCL 高 PE / 高成長假設"

    if _is_hvlp_copper_foil_growth and base_eps is not None and base_eps > 0:
        # fix60｜金居 HVLP 高階銅箔 EPS 假設，不能直接等於 Core Yes。
        _hvlp_eps_candidates = [base_eps * (2.0 if fj["report"] == "通過" else 1.2)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] == "通過":
            _hvlp_eps_candidates.append(annualized_eps * 1.15)
        _hvlp_eps = max(_hvlp_eps_candidates)
        if future_eps is None or future_eps < _hvlp_eps:
            future_eps = _hvlp_eps
            future_eps_note = "採近四季 EPS + 最近一季 run-rate 上修；需用 HVLP 占比、月營收、毛利率與 EPS 驗證"

    if (_is_abf_bt_substrate_cycle or _is_ai_server_pcb_core or _is_pcb_drill_consumables) and base_eps is not None and base_eps > 0:
        _pcb_mult = 1.25 if _is_abf_bt_substrate_cycle else (1.22 if _is_ai_server_pcb_core else 1.18)
        _pcb_eps_candidates = [base_eps * (_pcb_mult if fj["report"] == "通過" else 1.05)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] == "通過":
            _pcb_eps_candidates.append(annualized_eps * (0.85 if _is_abf_bt_substrate_cycle else 0.80))
        _pcb_eps = max(_pcb_eps_candidates)
        if future_eps is None or future_eps < _pcb_eps:
            future_eps = _pcb_eps
            future_eps_note = "採近四季 EPS + 最近一季 run-rate 保守折扣；需用營收、毛利率、EPS 與稼動率驗證"

    if _is_general_pcb_hdi_candidate and base_eps is not None and base_eps > 0:
        _gpcb_eps = base_eps * (1.08 if fj["report"] in ["通過", "部分通過"] else 1.00)
        if future_eps is None or future_eps < _gpcb_eps:
            future_eps = _gpcb_eps
            future_eps_note = "採一般 PCB / HDI 保守 EPS 修復，不使用 ABF / AI 伺服器 PCB 高估值假設"

    if _is_biotech_commercial_drug and base_eps is not None and base_eps > 0:
        # fix50｜商業化新藥 EPS 支撐上修：
        # 高毛利商業化新藥若 Q1 EPS 已放大，不可只用 TTM × 低 PE；但仍不直接用樂觀藥證情境。
        _bio_eps_candidates = [base_eps * (1.35 if fj["report"] == "通過" else 1.10)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] == "通過":
            _bio_eps_candidates.append(annualized_eps * 1.05)
        _bio_eps = max(_bio_eps_candidates)
        if future_eps is None or future_eps < _bio_eps:
            future_eps = _bio_eps
            future_eps_note = "採近四季 EPS + 最近一季年化 EPS 保守上修；需用月營收、Q2 EPS 與藥證進度驗證"

    if _is_real_estate_delivery and base_eps is not None and base_eps > 0:
        # fix48｜建商交屋認列 EPS 支撐上修：
        # Q1 / 單月交屋認列進帳時，近四季 EPS 常低估未來 12 個月，但又不能把單季直接年化到樂觀區。
        _real_estate_eps_candidates = [base_eps * (1.20 if fj["report"] in ["通過", "部分通過"] else 1.00)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] in ["通過", "部分通過"]:
            _real_estate_eps_candidates.append(annualized_eps * 0.90)
        _real_estate_eps = max(_real_estate_eps_candidates)
        if future_eps is None or future_eps < _real_estate_eps:
            future_eps = _real_estate_eps
            future_eps_note = "採近四季 EPS + 最近一季交屋認列 run-rate 保守折扣；營建股仍需搭配 P/B、完工案量與現金流"

    if _is_financial_brokerage_cycle and base_eps is not None and base_eps > 0:
        # fix44｜證券循環金融 EPS 支撐上修：
        # 證券 / 資本市場循環股的 EPS 會跟台股成交量、自營投資、ETF / 財富管理熱度連動。
        # 若資料源只抓舊 TTM，支撐價會被壓到明顯失真。
        # 使用三軌保守取高：近四季 EPS 上修、最近一季年化輔助、現價反推最低支撐。
        _fin_broker_eps_candidates = [
            base_eps * (1.35 if fj["report"] in ["通過", "部分通過"] else 1.00)
        ]
        if annualized_eps is not None and annualized_eps > 0:
            _fin_broker_eps_candidates.append(annualized_eps * 1.18)
        _broker_close = price.get("close") if price else None
        if _broker_close is not None and _broker_close > 0 and fj["report"] in ["通過", "部分通過"]:
            # 不把現價當合理價，只避免支撐區低到失真。支撐下緣約落在現價 55%～65%。
            _fin_broker_eps_candidates.append((_broker_close * 0.60) / 7.5)
        _fin_broker_eps = max(_fin_broker_eps_candidates)
        if future_eps is None or future_eps < _fin_broker_eps:
            future_eps = _fin_broker_eps
            future_eps_note = "採近四季 EPS / 最近一季年化 / 資本市場循環支撐三軌保守取高"

    if _is_panel_turnaround_rerating and base_eps is not None and base_eps > 0:
        # 轉機股估值測試：已公布 EPS 很低時，支撐價主要由 P/B 修復；未來 EPS 僅列驗證條件。
        # 取近四季 EPS 溫和上修與最近一季年化折扣的較高值，避免 Q1 剛轉盈就直接用過高 PE。
        _panel_eps_candidates = [base_eps * 1.20]
        if annualized_eps is not None and annualized_eps > 0:
            _panel_eps_candidates.append(annualized_eps * 0.85)
        _panel_eps = max(_panel_eps_candidates)
        if future_eps is None or future_eps < _panel_eps:
            future_eps = _panel_eps
            future_eps_note = "採 P/B 修復為主，未來 EPS 僅作 Q2 / 月營收驗證；轉型題材不得直接升高 PE"

    # fix40｜防守型現金流金庫 EPS 防呆：
    # 避免單季年化 run-rate 把穩定電信股 EPS 推得太高；以近四季 EPS 溫和上修為主。
    if _is_defensive_cashflow_treasury and base_eps is not None and base_eps > 0:
        _def_eps = base_eps * (1.03 if fj["report"] in ["通過", "部分通過"] else 1.00)
        future_eps = _def_eps
        future_eps_note = "採近四季 EPS × 防守型現金流溫和成長假設"

    # fix33｜先進封裝 / 封測龍頭最後 EPS 支撐防呆：
    # 避免因 annualized 分支未進入或欄位缺漏，最後仍只用近四季 EPS。
    if _is_advanced_packaging_osat and base_eps is not None and base_eps > 0:
        _adv_floor_eps = base_eps * (1.22 if fj["report"] in ["通過", "部分通過"] else 1.08)
        if future_eps is None or future_eps < _adv_floor_eps:
            future_eps = _adv_floor_eps
            future_eps_note = "採近四季 EPS × 先進封裝 / 封測重評成長假設"
    # fix37｜記憶體循環 / 低毛利通路 EPS 支撐防呆：
    # 至上這類公司 EPS 會受記憶體報價循環上修，但不能給高成長 PE。
    # 用「未來 EPS 較明確上修 × 較低 PE」處理：EPS 可往上修，PE 仍保守。
    if _is_memory_cyclical_distributor and base_eps is not None and base_eps > 0:
        _mem_floor_eps = base_eps * (1.35 if fj["report"] in ["通過", "部分通過"] else 1.00)
        if future_eps is None or future_eps < _mem_floor_eps:
            future_eps = _mem_floor_eps
            future_eps_note = "採近四季 EPS × 記憶體報價循環上修假設，PE 仍以低毛利通路保守估值"

    # v37｜記憶體製造主升重評 EPS 基礎：
    # 財報已驗證、毛利率 / EPS / 現金流都接上時，TTM 可能落後最新景氣 run-rate；
    # 用最近一季年化作保守支撐輔助，但仍需 Q2 / 月營收驗證。
    if _is_memory_manufacturing_cycle_rerating and base_eps is not None and base_eps > 0:
        _mem_mfg_eps_candidates = [base_eps * (1.00 if fj["report"] == "通過" else 0.90)]
        if annualized_eps is not None and annualized_eps > 0 and fj["report"] == "通過" and fj.get("margin") == "有":
            _mem_mfg_eps_candidates.append(annualized_eps * 1.00)
        _mem_mfg_eps = max(_mem_mfg_eps_candidates)
        if future_eps is None or future_eps < _mem_mfg_eps:
            future_eps = _mem_mfg_eps
            future_eps_note = "採最近一季年化 EPS 作記憶體景氣重評支撐；需用 5～6 月營收、報價、毛利率與 Q2 EPS 驗證"
    if override_model_key and override_model_key in MODEL_CONFIG:
        model_key = override_model_key
        model = MODEL_CONFIG[override_model_key]
    else:
        model_key = get_model_key(stock, industry_category)
        model = get_model(stock, industry_category)

    valuation_submodel = build_valuation_submodel_meta(stock, model_key, industry_category)

    pe_scenarios = {
        "down": model["down"],
        "cons": model["cons"],
        "neutral": model["neutral"],
        "opt": model["opt"],
        "rerating": model["rerating"],
        "market_premium": model["market_premium"],
    }
    # v269｜APP 自算 EPS 三情境：沒法醫 v6.7 參數時，先給估值骨架；有法醫時由前台/持股資料覆蓋。
    auto_eps_scenarios = calculate_forensic_eps_scenarios_v269(
        ttm_eps=ttm_eps,
        base_eps=base_eps,
        annualized_eps=annualized_eps,
        revenue_yoy=rev_yoy,
        eps_yoy=eps_yoy,
        fin=fin,
        fj=fj,
        model_key=model_key,
    )
    # Nick v5 fix4｜族群 PE 模型防呆
    # 舊邏輯會因 financial_quality == 低（常由現金流 / 存貨 / 應收造成）
    # 直接把 neutral PE 壓到 11x～14x，導致 AI 網通 / 高速交換器等強成長股
    # 即使營收、EPS、營益率已經通過，仍被錯估成低 PE 模型。
    # 現在改成：
    # 1) 低毛利製造平台、通路、循環、轉機股仍可降 PE。
    # 2) 高品質成長模型若財報本體通過 / 部分通過，現金流與營運資金風險只限制 Focus，
    #    不直接重壓 PE 到 11x～14x。
    report_core_score = float(fj.get("report_core_score", 0) or 0)
    is_growth_model = model_key in HIGH_QUALITY_GROWTH_MODELS
    has_report_support = (
        fj.get("report") in ["通過", "部分通過"]
        or fj.get("growth_quality") in ["通過", "部分通過"]
        or report_core_score >= 4
    )
    working_capital_only_risk = (
        fj.get("financial_quality") == "低"
        and has_report_support
        and (fj.get("cashflow") == "不配合" or fj.get("inv_ar") != "正常")
        and fj.get("eps") != "沒有"
        and fj.get("revenue_to_eps") in ["有", "部分有"]
        and fj.get("margin") in ["有", "普通"]
    )
    should_discount_pe = (
        fj["low_margin"]
        or fj["cyclical"]
        or (fj["financial_quality"] == "低" and not (is_growth_model and working_capital_only_risk))
    )
    # fix54｜高階 CCL / 高速材料估值防呆：
    # 台光電 / 台燿這類高階 CCL 若財報已通過，不可因低毛利或循環標籤被壓回 11x～14x。
    # 低毛利 / 循環只能限制 Focus 與追價，不能直接打掉高階材料 PE。
    if model_key == "ccl_highend_highspeed" and has_report_support:
        should_discount_pe = False
    if model_key == "hvlp_copper_foil_growth" and has_report_support:
        should_discount_pe = False
    if model_key in ["abf_bt_substrate_cycle", "ai_server_pcb_core", "pcb_drill_consumables"] and has_report_support:
        should_discount_pe = False
    if should_discount_pe:
        # 不同模型最低 PE 不同；高品質成長股原則上不會走到這裡。
        pe_scenarios["neutral"] = (
            min(pe_scenarios["neutral"][0], 11),
            min(pe_scenarios["neutral"][1], 14),
        )
        pe_scenarios["opt"] = (
            min(pe_scenarios["opt"][0], 15),
            min(pe_scenarios["opt"][1], 18),
        )
        pe_scenarios["rerating"] = (
            min(pe_scenarios["rerating"][0], 19),
            min(pe_scenarios["rerating"][1], 22),
        )


    # v37｜記憶體製造「估值重評 PE 上修」通用規則：
    # 當供給缺口 / 報價續強 / 財報三率 / EPS / 現金流與法人籌碼同向時，
    # 不再只用傳統景氣循環低 PE。這不是個股特例，而是記憶體主升重評狀態。
    _memory_rerating_pe_upshift = False
    if model_key == "memory_manufacturing_cycle_rerating":
        try:
            _cj_score_for_val = float((judge_chip({}) or {}).get('score') or 0)
        except Exception:
            _cj_score_for_val = 0
        _memory_rerating_pe_upshift = bool(
            fj.get("report") == "通過"
            and fj.get("margin") == "有"
            and fj.get("eps") in ["有", "部分有"]
            and fj.get("cashflow") in ["有", "普通"]
            and fj.get("revenue_to_eps") in ["有", "部分有", "無法判斷"]
            and rr.get("verdict") == "成立"
        )
        if _memory_rerating_pe_upshift:
            pe_scenarios["neutral"] = (12.0, 15.0)
            pe_scenarios["opt"] = (14.0, 17.0)
            pe_scenarios["rerating"] = (16.0, 18.0)
            pe_scenarios["market_premium"] = (18.0, 20.0)
    # v269｜法醫斷路器注入估值流水線：毛利/營益率、存貨應收、EPS 接棒失敗會直接限制 PE 與樂觀 EPS。
    _v269_gate = apply_forensic_valuation_circuit_breakers_v269(
        pe_scenarios=pe_scenarios,
        eps_scenarios=auto_eps_scenarios,
        future_eps=future_eps,
        fin=fin,
        fj=fj,
        model_key=model_key,
        valuation_submodel_key=valuation_submodel.get("key"),
    )
    pe_scenarios = _v269_gate.get("pe_scenarios") or pe_scenarios
    auto_eps_scenarios = _v269_gate.get("eps_scenarios") or auto_eps_scenarios
    future_eps = _v269_gate.get("future_eps", future_eps)
    forensic_circuit_breakers = _v269_gate.get("breakers") or []
    forensic_rerating_locked = bool(_v269_gate.get("rerating_locked"))
    working_capital_context_v270 = _v269_gate.get("working_capital_context") or {}
    financial_signal_radar_v271 = _v269_gate.get("financial_signal_radar_v271") or (fj.get("financial_signal_radar_v271") if isinstance(fj, dict) else {}) or {}

    if model_key == "financial_holding_life_revaluation":
        # fix41｜金控壽險資產重評估值：
        # 支撐區使用 EPS 區間，而不是把 4 月獲利年化。
        # 目標接近：基本面支撐 90～105，重評區 110～120。
        future_eps_low = future_eps * 0.96 if future_eps is not None else None
        future_eps_high = future_eps * 1.02 if future_eps is not None else None
        ranges = {
            "down": calc_range(base_eps, pe_scenarios["down"]),
            "cons": (
                future_eps_low * pe_scenarios["cons"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["cons"][1] if future_eps_high is not None else None,
            ),
            "neutral": (
                future_eps_low * pe_scenarios["neutral"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["neutral"][1] if future_eps_high is not None else None,
            ),
            "opt": (
                future_eps_low * pe_scenarios["opt"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["opt"][1] if future_eps_high is not None else None,
            ),
            "rerating": (
                future_eps_low * pe_scenarios["rerating"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["rerating"][1] if future_eps_high is not None else None,
            ),
            "market_premium": (
                future_eps_low * pe_scenarios["market_premium"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["market_premium"][1] if future_eps_high is not None else None,
            ),
        }
    elif model_key == "financial_brokerage_cycle":
        # fix44｜證券循環金融估值區間：
        # 支撐區用 EPS 區間，不把資本市場景氣高峰直接無限外推。
        future_eps_low = future_eps * 0.98 if future_eps is not None else None
        future_eps_high = future_eps * 1.08 if future_eps is not None else None
        ranges = {
            "down": calc_range(base_eps, pe_scenarios["down"]),
            "cons": (
                future_eps_low * pe_scenarios["cons"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["cons"][1] if future_eps_high is not None else None,
            ),
            "neutral": (
                future_eps_low * pe_scenarios["neutral"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["neutral"][1] if future_eps_high is not None else None,
            ),
            "opt": (
                future_eps_low * pe_scenarios["opt"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["opt"][1] if future_eps_high is not None else None,
            ),
            "rerating": (
                future_eps_low * pe_scenarios["rerating"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["rerating"][1] if future_eps_high is not None else None,
            ),
            "market_premium": (
                future_eps_low * pe_scenarios["market_premium"][0] if future_eps_low is not None else None,
                future_eps_high * pe_scenarios["market_premium"][1] if future_eps_high is not None else None,
            ),
        }
    elif model_key == "advanced_packaging_osat":
        # fix34｜先進封裝 / 封測龍頭估值支撐區：
        # support_key=cons 時也必須用 future_eps 計算，不能再用 base_eps。
        # 否則畫面會寫「未來 12 個月 EPS」，但數字仍是近四季 EPS × PE。
        ranges = {
            "down": calc_range(base_eps, pe_scenarios["down"]),
            "cons": calc_range(future_eps, pe_scenarios["cons"]),
            "neutral": calc_range(future_eps, pe_scenarios["neutral"]),
            "opt": calc_range(future_eps, pe_scenarios["opt"]),
            "rerating": calc_range(future_eps, pe_scenarios["rerating"]),
            "market_premium": calc_range(future_eps, pe_scenarios["market_premium"]),
        }
    elif model_key == "memory_cyclical_distributor":
        # fix38｜記憶體通路估值 EPS 區間上緣
# fix39｜修正 round_price 未定義錯誤
# fix40｜防守型現金流金庫模型
# fix41｜金控壽險資產重評模型
# fix42｜金融類股通用模型＋金融文案防呆
# fix43｜銀行型金控 EPS 支撐上修＋金融股觀察文案
# fix44｜證券循環金融 EPS 支撐上修＋Core 候選防呆
# fix45｜證券循環型買點語氣防呆
# fix46｜航運運價反彈交易模型
# fix47｜航運 公司體質未通過 顯示＋Attack 類型＋操作語氣防呆
# fix48｜營建建商交屋認列重評模型：
        # 至上這類循環通路股，估值支撐應呈現 EPS 區間，不是單一 EPS。
        # 低點 = future_eps × 保守 PE 下緣；高點 = future_eps_high × 保守 PE 上緣。
        # 這樣能貼近「未來 EPS 9.5～10.5 × PE 7～8」的法醫估值邏輯。
        future_eps_high = future_eps * 1.10 if future_eps is not None else None
        ranges = {
            "down": calc_range(base_eps, pe_scenarios["down"]),
            "cons": (
                future_eps * pe_scenarios["cons"][0] if future_eps is not None else None,
                future_eps_high * pe_scenarios["cons"][1] if future_eps_high is not None else None,
            ),
            "neutral": (
                future_eps * pe_scenarios["neutral"][0] if future_eps is not None else None,
                future_eps_high * pe_scenarios["neutral"][1] if future_eps_high is not None else None,
            ),
            "opt": (
                future_eps * pe_scenarios["opt"][0] if future_eps is not None else None,
                future_eps_high * pe_scenarios["opt"][1] if future_eps_high is not None else None,
            ),
            "rerating": (
                future_eps * pe_scenarios["rerating"][0] if future_eps is not None else None,
                future_eps_high * pe_scenarios["rerating"][1] if future_eps_high is not None else None,
            ),
            "market_premium": (
                future_eps * pe_scenarios["market_premium"][0] if future_eps is not None else None,
                future_eps_high * pe_scenarios["market_premium"][1] if future_eps_high is not None else None,
            ),
        }
    else:
        ranges = {
            "down": calc_range(base_eps, pe_scenarios["down"]),
            "cons": calc_range(base_eps, pe_scenarios["cons"]),
            "neutral": calc_range(future_eps, pe_scenarios["neutral"]),
            "opt": calc_range(future_eps, pe_scenarios["opt"]),
            "rerating": calc_range(future_eps, pe_scenarios["rerating"]),
            "market_premium": calc_range(future_eps, pe_scenarios["market_premium"]),
        }
    # fix71｜估值公式正式切換：
    # - P/B 主估值：用 PBR 反推 BVPS，再用 BVPS × P/B 情境。
    # - PE+P/B：PE 區間與 P/B 區間加權融合。
    # - EV/EBITDA / NAV 若資料不足：暫用 P/B proxy，並明確警示。
    close = price.get("close") if price else None
    market_pbr = to_float((valratio or {}).get("pbr")) if isinstance(valratio, dict) else None
    market_per = to_float((valratio or {}).get("per")) if isinstance(valratio, dict) else None
    dividend_yield = to_float((valratio or {}).get("dividend_yield")) if isinstance(valratio, dict) else None
    bvps = safe_div(close, market_pbr) if close is not None and market_pbr not in [None, 0] else None

    original_pe_ranges = dict(ranges)
    pb_scenarios = valuation_pb_scenarios_for_submodel(valuation_submodel.get("key"))
    pb_ranges = calc_pb_ranges(bvps, pb_scenarios)
    valuation_formula_family = valuation_submodel.get("formula_family", "PE")
    valuation_formula_used = "EPS × PE"
    valuation_formula_warning = ""
    valuation_formula_detail = ""

    if valuation_formula_family in ["PB+NormalizedEPS", "PB+ROE", "PB+EPS"]:
        if pb_ranges:
            ranges = pb_ranges
            valuation_formula_used = "BVPS × P/B"
            valuation_formula_detail = f"以 PBR {market_pbr:.2f} 反推 BVPS 約 {bvps:.2f}，再套用 P/B 情境。"
        else:
            valuation_formula_used = "EPS × PE fallback"
            valuation_formula_warning = "P/B 主估值需要 PBR / BVPS，但目前抓不到 PBR；本次暫用 EPS × PE 輔助，支撐價需保守解讀。"
    elif valuation_formula_family in ["PE+PB", "PB+EPS"]:
        if pb_ranges:
            _w = valuation_pb_weight_for_submodel(valuation_submodel.get("key"))
            ranges = blend_price_ranges(original_pe_ranges, pb_ranges, pb_weight=_w)
            valuation_formula_used = f"PE + P/B 加權融合（P/B權重{int(_w*100)}%）"
            valuation_formula_detail = f"以 PBR {market_pbr:.2f} 反推 BVPS 約 {bvps:.2f}，再與 EPS × PE 區間融合。"
        else:
            valuation_formula_used = "EPS × PE fallback"
            valuation_formula_warning = "混合估值需要 PBR 輔助，但目前抓不到 PBR；本次暫用 EPS × PE，需保守解讀。"
    elif valuation_formula_family in ["EVEBITDA+PB", "NAV+PB"]:
        if pb_ranges:
            ranges = pb_ranges
            valuation_formula_used = "P/B proxy"
            valuation_formula_warning = "此估值模型理想上需更多資料；目前資料不足，暫用 P/B 輔助。"
            valuation_formula_detail = f"以 PBR {market_pbr:.2f} 反推 BVPS 約 {bvps:.2f}，用 P/B 作 proxy。"
        else:
            valuation_formula_used = "EPS × PE fallback"
            valuation_formula_warning = "此估值模型需要更多資料；本次資料不足，暫用 EPS × PE 輔助，需人工複核。"
    elif valuation_formula_family == "PE+DividendYield":
        # 若能抓到殖利率，使用目前股價反推 DPS，再用防守股合理殖利率估值，與 PE 區間融合。
        if dividend_yield is not None and dividend_yield > 0 and close is not None:
            dps = close * dividend_yield / 100.0
            yield_scenarios = {
                "down": (0.060, 0.050),
                "cons": (0.052, 0.045),
                "neutral": (0.045, 0.038),
                "opt": (0.038, 0.033),
                "rerating": (0.033, 0.030),
                "market_premium": (0.030, 0.027),
            }
            yield_ranges = {}
            for k, yr in yield_scenarios.items():
                # 高殖利率 = 低價格；低殖利率 = 高價格
                yield_ranges[k] = (dps / yr[0], dps / yr[1])
            ranges = blend_price_ranges(original_pe_ranges, yield_ranges, pb_weight=0.35)
            valuation_formula_used = "PE + 殖利率反推融合"
            valuation_formula_detail = f"用目前殖利率 {dividend_yield:.2f}% 反推 DPS 約 {dps:.2f}，再與 PE 區間融合。"
        else:
            valuation_formula_used = "EPS × PE fallback"
            valuation_formula_warning = "殖利率模型需 dividend_yield；目前抓不到，暫用 EPS × PE。"
    elif valuation_formula_family == "PE+WorkingCapital":
        valuation_formula_used = "EPS × 保守 PE + 營運資金防呆"
        valuation_formula_warning = "此類多屬低毛利 / 組裝 / 通路 / 物流 / 模組股；支撐價雖用 PE，但需硬看現金流、存貨、應收與毛利率，不可只看營收。"
    elif valuation_formula_family == "EventDiscount":
        valuation_formula_used = "事件折現 fallback"
        valuation_formula_warning = "未獲利 / 事件型標的理想上不應用 PE；目前缺事件折現資料，支撐價只作保守參考。"

    implied_ttm_pe = safe_div(close, ttm_eps) if close is not None and ttm_eps else None
    implied_future_pe = (
        safe_div(close, future_eps) if close is not None and future_eps else None
    )
    model_high_pe = pe_scenarios["market_premium"][1]
    support_key = valuation_submodel.get("support_key") or (model or {}).get("support_key", "neutral")
    premium_ratio = (
        safe_div(implied_future_pe, model_high_pe)
        if implied_future_pe is not None
        else None
    )
    if implied_future_pe is None:
        pe_status = "資料不足"
    elif implied_future_pe > model_high_pe * 1.15:
        pe_status = "市場給價超出模型，需人工校正產業 PE"
    elif implied_future_pe > pe_scenarios["rerating"][1]:
        pe_status = "市場給高溢價，已高於一般重評區"
    elif implied_future_pe > pe_scenarios["neutral"][1]:
        pe_status = "市場已提前反映部分未來"
    else:
        pe_status = "仍在模型合理區內"

    # v269｜估值偏離提醒：APP 模型與市場價格差太大時，不硬判錯，提示重新法醫。
    try:
        _v269_recheck_alert = build_valuation_recheck_alert_v269(
            close=close,
            future_eps=future_eps,
            pe_scenarios=pe_scenarios,
            ranges=ranges,
            rr=rr,
        )
    except Exception:
        _v269_recheck_alert = {"trigger": False, "message": ""}

    # v270｜預期差雷達：APP 自算估值是 CFO 保守基準，不是買賣裁判；差距過大時觸發法醫解剖。
    try:
        _v270_evidence_tags = []
        _wc_ctx = working_capital_context_v270 if 'working_capital_context_v270' in locals() else {}
        if _wc_ctx.get("expectation_gap_watch"):
            _v270_evidence_tags.append("健康備貨 / 訂單備貨可能")
        try:
            _fsr = financial_signal_radar_v271 if 'financial_signal_radar_v271' in locals() else {}
            if _fsr.get("expectation_gap_watch"):
                _v270_evidence_tags.append("v271 財報訊號：" + str(_fsr.get("verdict") or "可能預期差"))
            for _clue in (_fsr.get("owner_clues") or [])[:2]:
                if _clue:
                    _v270_evidence_tags.append(str(_clue)[:40])
        except Exception:
            pass
        if rr and isinstance(rr, dict) and str(rr.get("status") or rr.get("rerating") or "").find("成立") >= 0:
            _v270_evidence_tags.append("估值重評線索")
        _cfo_val = None
        try:
            _cfo_val = (ranges.get("neutral") or ranges.get("cons") or (None, None))[1]
        except Exception:
            _cfo_val = None
        _v270_gap_radar = calculate_expectation_gap_radar_v270(
            cfo_valuation=_cfo_val,
            forensic_valuation=None,
            current_price=close,
            evidence_tags=_v270_evidence_tags,
            financial_alert=bool(forensic_circuit_breakers),
        )
        _v270_forensic_trigger = check_forensic_trigger_conditions_v270(
            cfo_valuation=_cfo_val,
            current_price=close,
            gap_rate=_v270_gap_radar.get("valuation_gap_rate"),
            sector_money_flow=None,
            trend_status="Strong_Up" if pe_status in ["市場給高溢價，已高於一般重評區", "市場給價超出模型，需人工校正產業 PE"] else "",
            financial_alert=bool(forensic_circuit_breakers),
            evidence_tags=_v270_evidence_tags,
        )
    except Exception:
        _v270_gap_radar = {"need_forensic_dissection": False, "deviation_type": "資料不足"}
        _v270_forensic_trigger = {"need_forensic_dissection": False, "trigger_reasons": []}

    # v3｜估值母模型 metadata：只提供估值角色 / 證據方向，不直接決定 Core。
    try:
        valuation_family_key, valuation_family_rule = get_effective_family_context(model_key, valuation_submodel_key=valuation_submodel.get("key"), stock=stock, industry_category=industry_category)
    except Exception:
        valuation_family_key, valuation_family_rule = "quality_growth_pe", MODEL_FAMILY_RULES.get("quality_growth_pe", {}) if "MODEL_FAMILY_RULES" in globals() else {}

    return {
        "ok": True,
        "model_key": model_key,
        "model_name": model["name"],
        "model_primary": model.get("primary", "PE"),
        "model_note": model.get("note", ""),
        "stock": stock,
        "valuation_submodel_key": valuation_submodel.get("key"),
        "valuation_submodel_name": valuation_submodel.get("name"),
        "valuation_family_key": valuation_family_key,
        "valuation_family_name": (valuation_family_rule or {}).get("family_name"),
        "valuation_family_role": (valuation_family_rule or {}).get("valuation_role"),
        "valuation_family_evidence_tags": (valuation_family_rule or {}).get("evidence_tags", []),
        "valuation_family_risk_tags": (valuation_family_rule or {}).get("risk_tags", []),
        "valuation_subfamily_key": (valuation_family_rule or {}).get("subfamily_key", ""),
        "valuation_subfamily_note": (valuation_family_rule or {}).get("subfamily_note", ""),
        "valuation_formula_family": valuation_submodel.get("formula_family"),
        "valuation_primary_method": valuation_submodel.get("primary_method"),
        "valuation_secondary_method": valuation_submodel.get("secondary_method"),
        "valuation_multiple_label": valuation_submodel.get("multiple_label"),
        "valuation_submodel_note": valuation_submodel.get("note"),
        "valuation_submodel_v1_warning": valuation_submodel.get("v1_warning"),
        "valuation_formula_used": valuation_formula_used,
        "valuation_formula_warning": valuation_formula_warning,
        "valuation_formula_detail": valuation_formula_detail,
        "market_pbr": market_pbr,
        "market_per": market_per,
        "dividend_yield": dividend_yield,
        "bvps": bvps,
        "pb_scenarios": pb_scenarios,
        "pb_ranges": pb_ranges,
        "original_pe_ranges": original_pe_ranges,
        "ttm_eps": ttm_eps,
        "quarter_eps": quarter_eps,
        "annualized_eps": annualized_eps,
        "base_eps": base_eps,
        "base_eps_label": base_eps_label,
        "future_eps": future_eps,
        "growth": growth * 100,
        "future_eps_note": future_eps_note,
        "pe_scenarios": pe_scenarios,
        "auto_eps_scenarios": auto_eps_scenarios,
        "forensic_circuit_breakers": forensic_circuit_breakers if 'forensic_circuit_breakers' in locals() else [],
        "forensic_rerating_locked": bool(forensic_rerating_locked) if 'forensic_rerating_locked' in locals() else False,
        "working_capital_context_v270": working_capital_context_v270 if 'working_capital_context_v270' in locals() else {},
        "financial_signal_radar_v271": financial_signal_radar_v271 if 'financial_signal_radar_v271' in locals() else {},
        "valuation_recheck_alert": _v269_recheck_alert,
        "expectation_gap_radar_v270": _v270_gap_radar if '_v270_gap_radar' in locals() else {},
        "forensic_trigger_v270": _v270_forensic_trigger if '_v270_forensic_trigger' in locals() else {},
        **ranges,
        "implied_ttm_pe": implied_ttm_pe,
        "implied_future_pe": implied_future_pe,
        "model_high_pe": model_high_pe,
        "support_key": support_key,
        "support_range": ranges.get(support_key) or ranges.get("neutral"),
        "pe_discount_applied": bool(should_discount_pe),
        "pe_discount_reason": ("低財務品質 / 低毛利 / 循環風險，已保守壓低 PE" if should_discount_pe else ("高成長模型：營運資金風險不直接壓低 PE，只限制 Focus" if working_capital_only_risk else "未觸發 PE 壓低")),
        "eps_basis_warning": eps_basis_warning if 'eps_basis_warning' in locals() else "",
        "premium_ratio": premium_ratio,
        "pe_status": pe_status,
        "reason": f"{future_eps_note}；產業估值模型：{model['name']}；估值子模組：{valuation_submodel.get('name')}；實際公式：{valuation_formula_used}；{valuation_formula_detail or valuation_formula_warning or 'EPS、倍數、目標價三者同步計算'}" + (("；CFO警報/法醫提醒：" + "、".join(forensic_circuit_breakers)) if ('forensic_circuit_breakers' in locals() and forensic_circuit_breakers) else ""),
    }


def valuation_interval_warnings(val):
    warnings = []
    if not val or not val.get("ok"):
        return warnings
    zone_specs = [
        ("下修區", val.get("down")),
        ("保守區", val.get("cons")),
        ("中性 / 基本面支撐區", val.get("neutral")),
        ("樂觀區", val.get("opt")),
        ("估值重評合理區", val.get("rerating")),
        ("市場溢價區", val.get("market_premium")),
    ]
    valid = []
    for name, r in zone_specs:
        if r and r[0] is not None and r[1] is not None:
            valid.append((name, (min(r[0], r[1]), max(r[0], r[1]))))
    valid = sorted(valid, key=lambda x: x[1][0])
    has_overlap = False
    has_gap = False
    for i in range(len(valid) - 1):
        _left_name, left = valid[i]
        _right_name, right = valid[i + 1]
        if left[1] > right[0]:
            has_overlap = True
        elif left[1] < right[0]:
            gap_pct = pct_change(right[0], left[1])
            if gap_pct is not None and gap_pct > 5:
                has_gap = True
    if has_overlap or has_gap:
        if has_overlap and has_gap:
            warnings.append("估值區間提醒：部分區間重疊或存在夾層，代表市場可能正在重評或模型區間接近；請搭配營收、EPS、籌碼與買點確認，不可單靠估值決定買賣。")
        elif has_overlap:
            warnings.append("估值區間提醒：部分區間有重疊，代表市場可能正在重評或模型區間接近；請搭配營收、EPS、籌碼與買點確認，不可單靠估值決定買賣。")
        else:
            warnings.append("估值區間提醒：部分區間中間存在夾層，若現價落在夾層，請搭配營收、EPS、籌碼與買點確認，不可單靠估值決定買賣。")
    try:
        _span = valuation_span_risk_payload(val)
        if _span.get("active") and _span.get("message"):
            warnings.append(_span.get("message"))
    except Exception:
        pass
    return warnings


def valuation_span_risk_payload(val):
    """v273.6｜估值跨度風險防呆。
    只提醒「重評上緣不是必達目標」，不否定估值重評，也不改買點公式。
    """
    try:
        if not isinstance(val, dict) or not val.get("ok"):
            return {"active": False, "level": "none", "span_pct": None, "message": ""}
        support = val.get("support_range") or val.get("neutral") or val.get("cons")
        rer = val.get("rerating") or val.get("opt")
        premium = val.get("market_premium") or rer
        if not support or not rer:
            return {"active": False, "level": "none", "span_pct": None, "message": ""}
        s_lo, s_hi = min(support[0], support[1]), max(support[0], support[1])
        r_lo, r_hi = min(rer[0], rer[1]), max(rer[0], rer[1])
        p_hi = max(premium[0], premium[1]) if premium and premium[0] is not None and premium[1] is not None else r_hi
        if s_hi in [None, 0] or s_hi <= 0 or r_hi is None:
            return {"active": False, "level": "none", "span_pct": None, "message": ""}
        span_pct = (r_hi / s_hi - 1) * 100
        premium_span_pct = (p_hi / s_hi - 1) * 100 if p_hi not in [None, 0] else span_pct
        family = str(val.get("valuation_family_key") or val.get("model_key") or "")
        # 不同族群用不同提醒門檻，避免一刀切。
        conservative_family = any(k in family for k in ["financial", "defensive", "cashflow", "distributor", "low_margin", "freight", "shipping"])
        cycle_family = any(k in family for k in ["cycle", "turnaround", "memory", "panel", "recovery"])
        high_growth_family = any(k in family for k in ["ai", "growth", "premium", "semi", "ccl", "highspeed", "optical"])
        if conservative_family:
            warn_th, high_th = 45, 70
        elif cycle_family:
            warn_th, high_th = 60, 95
        elif high_growth_family:
            warn_th, high_th = 85, 130
        else:
            warn_th, high_th = 70, 110
        level = "none"
        if span_pct >= high_th or premium_span_pct >= high_th + 20:
            level = "high"
        elif span_pct >= warn_th or premium_span_pct >= warn_th + 20:
            level = "watch"
        if level == "none":
            return {"active": False, "level": "none", "span_pct": span_pct, "premium_span_pct": premium_span_pct, "message": ""}
        if level == "high":
            msg = f"估值跨度偏大：基本面支撐區到重評區上緣約 +{fmt(span_pct, 1)}%。上方有想像空間，但必須靠營收、毛利率與 EPS 接棒；不可把重評上緣當成必達目標，進場務必分批並守今日防線。"
        else:
            msg = f"估值跨度需留意：支撐區到重評區約 +{fmt(span_pct, 1)}%。這代表上方空間來自未來驗證，不是現在就保證會到；操作仍要看買點、籌碼與風報比。"
        return {
            "active": True,
            "level": level,
            "span_pct": span_pct,
            "premium_span_pct": premium_span_pct,
            "message": msg,
            "support_range": support,
            "rerating_range": rer,
            "market_premium_range": premium,
        }
    except Exception:
        return {"active": False, "level": "none", "span_pct": None, "message": ""}


def valuation_zone_name(close, val):
    close = to_float(close)
    if close is None or not val or not val.get("ok"):
        return "資料不足"
    zones = [
        ("下修區", val.get("down")),
        ("保守區", val.get("cons")),
        ("中性 / 基本面支撐區", val.get("neutral")),
        ("樂觀區", val.get("opt")),
        ("估值重評合理區", val.get("rerating")),
        ("市場溢價區", val.get("market_premium")),
    ]
    valid = []
    for name, r in zones:
        if r and r[0] is not None and r[1] is not None:
            valid.append((name, (min(r[0], r[1]), max(r[0], r[1]))))
    if not valid:
        return "資料不足"
    valid = sorted(valid, key=lambda x: x[1][0])
    hits = [name for name, r in valid if r[0] <= close <= r[1]]
    if len(hits) >= 2:
        return "重疊區：" + " / ".join(hits)
    if len(hits) == 1:
        return hits[0]
    if close < valid[0][1][0]:
        return "低於下修區"
    if close > valid[-1][1][1]:
        return "高於市場溢價區"
    for i in range(len(valid) - 1):
        left_name, left = valid[i]
        right_name, right = valid[i + 1]
        if left[1] < close < right[0]:
            return f"{left_name}～{right_name}之間"
    return "區間外"



def _valuation_table_range_display(r):
    """v141｜通用估值表區間顯示整理：單點 147～147 改成 約147。"""
    if r is None:
        return "—"
    if isinstance(r, (list, tuple)) and len(r) >= 2:
        lo, hi = to_float(r[0]), to_float(r[1])
        if lo is None or hi is None:
            return "—"
        lo, hi = min(lo, hi), max(lo, hi)
        if abs(lo - hi) < 1e-9:
            return f"約{_valuation_learning_num_text(lo, 2)}"
        return _valuation_learning_range_text(lo, hi, 2)
    txt = str(r or "")
    return _valuation_learning_zone_display(txt)


def _valuation_table_is_direct_eps_pe_formula(formula_used, formula_family, multiple_text):
    """v141｜判斷此列是否宣稱為 EPS × PE 直接估值。

    若是 P/B、EV/EBITDA、殖利率、混合估值，就不做 EPS×PE 一致性硬檢查。
    """
    f = str(formula_used or "")
    fam = str(formula_family or "")
    mt = str(multiple_text or "")
    if any(k in f for k in ["P/B", "PB", "EV", "EBITDA", "殖利率", "proxy", "NAV"]):
        return False
    if any(k in fam for k in ["PB", "EV", "EBITDA", "NAV", "Dividend", "Yield"]):
        return False
    return ("PE" in f or fam in ["PE", "PER", "ForwardPE"] or "PE" in mt) and ("PE" in mt or "x" in mt)


def _valuation_table_formula_consistency(zone_text, eps_value, multiple_text, formula_used, formula_family):
    """v141｜通用估值公式一致性檢查。

    回傳 (狀態, 理論公式區)：
    - True：區間與 EPS×PE 大致一致
    - False：區間與 EPS×PE 明顯不一致
    - None：不適用或資料不足
    """
    if not _valuation_table_is_direct_eps_pe_formula(formula_used, formula_family, multiple_text):
        return None, ""
    eps_txt = str(eps_value if eps_value is not None else "")
    pe_txt = str(multiple_text or "")
    try:
        return _valuation_learning_zone_formula_consistent(zone_text, eps_txt, pe_txt, tolerance_pct=0.08)
    except Exception:
        return None, ""


def make_valuation_interval_df(price, val):
    """fix73｜估值區間表改版

    v141｜估值表通用一致性防呆：
    1. 只要畫面顯示 EPS × PE，就必須能算出旁邊估值區間。
    2. 若區間與 EPS×PE 明顯兜不起來，改標示「模型區間優先｜公式需校正」，避免誤導。
    3. 單點區間如 147～147，統一顯示為「約147」。
    4. 這是估值模組通用規則，不針對任何個股。
    """
    close = to_float(price.get("close")) if price else None
    current_zone = valuation_zone_name(close, val)
    if not val or not val.get("ok"):
        return pd.DataFrame(), current_zone

    rows = []
    formula_used = str(val.get("valuation_formula_used") or "EPS × PE")
    formula_family = str(val.get("valuation_formula_family") or "PE")
    submodel_name = str(val.get("valuation_submodel_name") or val.get("model_name", ""))
    multiple_label = str(val.get("valuation_multiple_label") or "合理 PE")

    # 新版表格語言
    zone_specs = [
        {
            "layer": "悲觀價",
            "old_zone": "下修區",
            "meaning": "驗證失敗",
            "range_key": "down",
            "eps_key": "base_eps",
            "multiple_key": "down",
            "market_read": "市場不信",
        },
        {
            "layer": "保守價",
            "old_zone": "保守區",
            "meaning": "保守底線",
            "range_key": "cons",
            "eps_key": "base_eps",
            "multiple_key": "cons",
            "market_read": "低估修復",
        },
        {
            "layer": "基本面支撐價",
            "old_zone": "中性 / 基本面支撐區",
            "meaning": "基本面可撐",
            "range_key": "neutral",
            "eps_key": "future_eps",
            "multiple_key": "neutral",
            "market_read": "買基本面",
        },
        {
            "layer": "合理價",
            "old_zone": "樂觀區",
            "meaning": "合理偏樂觀",
            "range_key": "opt",
            "eps_key": "future_eps",
            "multiple_key": "opt",
            "market_read": "買成長接棒",
        },
        {
            "layer": "樂觀價",
            "old_zone": "估值重評合理區",
            "meaning": "重評初段",
            "range_key": "rerating",
            "eps_key": "future_eps",
            "multiple_key": "rerating",
            "market_read": "買重評",
        },
        {
            "layer": "重評價",
            "old_zone": "市場溢價區",
            "meaning": "高溢價",
            "range_key": "market_premium",
            "eps_key": "future_eps",
            "multiple_key": "market_premium",
            "market_read": "買高預期",
        },
    ]

    matched = False

    def _range_mid(r):
        if not r or r[0] is None or r[1] is None:
            return 10**18
        lo, hi = min(r[0], r[1]), max(r[0], r[1])
        return (lo + hi) / 2

    def _vs_range_text(px, r):
        if px is None or not r or r[0] is None or r[1] is None:
            return "無資料"
        lo, hi = min(r[0], r[1]), max(r[0], r[1])
        if lo <= px <= hi:
            return "區間內"
        if px > hi and hi not in [None, 0]:
            return f"高於上緣 +{fmt((px / hi - 1) * 100, 1)}%"
        if px < lo and lo not in [None, 0]:
            return f"低於下緣 -{fmt((1 - px / lo) * 100, 1)}%"
        return "區間外"

    def _multiple_text(key):
        # P/B 主估值或 P/B proxy：顯示 P/B 倍數
        if "P/B" in formula_used or "proxy" in formula_used or formula_family in ["PB+NormalizedEPS", "PB+ROE", "PB+EPS", "NAV+PB", "EVEBITDA+PB"]:
            pb = (val.get("pb_scenarios") or {}).get(key)
            pe = (val.get("pe_scenarios") or {}).get(key)
            if "PE + P/B" in formula_used and pe and pb:
                return f"PE {pe[0]}x～{pe[1]}x / P/B {pb[0]}x～{pb[1]}x"
            if pb:
                return f"P/B {pb[0]}x～{pb[1]}x"
            if pe:
                return f"PE {pe[0]}x～{pe[1]}x"
            return "無資料"

        # 殖利率融合：仍列 PE 作參考
        pe = (val.get("pe_scenarios") or {}).get(key)
        if pe:
            if "殖利率" in formula_used:
                return f"PE {pe[0]}x～{pe[1]}x + 殖利率"
            return f"PE {pe[0]}x～{pe[1]}x"
        return "無資料"

    def _basis_text(eps_key):
        if "PE + P/B" in formula_used or formula_family == "PE+PB":
            bvps = to_float(val.get("bvps"))
            pbr = to_float(val.get("market_pbr"))
            eps_part = val.get("base_eps_label", "EPS") if eps_key == "base_eps" else "未來 12 個月 EPS"
            if bvps is not None and pbr is not None:
                return f"{eps_part} + BVPS {fmt(bvps, 2)} / PBR {fmt(pbr, 2)}"
            return f"{eps_part} + P/B 資料不足"
        if "P/B" in formula_used or "proxy" in formula_used:
            bvps = to_float(val.get("bvps"))
            pbr = to_float(val.get("market_pbr"))
            if bvps is not None and pbr is not None:
                return f"BVPS {fmt(bvps, 2)} / PBR {fmt(pbr, 2)}"
            return "P/B 資料不足"
        if eps_key == "base_eps":
            return val.get("base_eps_label", "EPS")
        return "未來 12 個月 EPS"

    def _market_expectation(layer, px, r):
        if px is None or not r or r[0] is None or r[1] is None:
            return "需補資料"
        lo, hi = min(r[0], r[1]), max(r[0], r[1])
        if px > hi:
            if layer in ["悲觀價", "保守價"]:
                return "已脫離低估"
            if layer == "基本面支撐價":
                return "買未來接棒"
            if layer == "合理價":
                return "買樂觀成長"
            if layer == "樂觀價":
                return "買重評延伸"
            return "買高溢價"
        if px < lo:
            if layer in ["樂觀價", "重評價"]:
                return "尚未反映"
            return "市場偏保守"
        return {
            "悲觀價": "風險區",
            "保守價": "保守修復",
            "基本面支撐價": "基本面支撐",
            "合理價": "合理偏樂觀",
            "樂觀價": "估值重評",
            "重評價": "高溢價",
        }.get(layer, "區間內")

    for spec in zone_specs:
        layer = spec["layer"]
        old_zone = spec["old_zone"]
        r = val.get(spec["range_key"])
        eps_value = val.get(spec["eps_key"])

        zone_display = _valuation_table_range_display(r)
        multiple_txt = _multiple_text(spec["multiple_key"])
        basis_txt = _basis_text(spec["eps_key"])
        row_formula = formula_used
        row_market = _market_expectation(layer, close, r)
        row_eps = fmt(eps_value)
        row_pe = multiple_txt

        consistent, theoretical_zone = _valuation_table_formula_consistency(
            zone_display,
            eps_value,
            multiple_txt,
            formula_used,
            formula_family,
        )

        # 通用防呆：EPS×PE 與區間明顯兜不起來時，顯示層停止假裝公式正確。
        if consistent is False:
            row_formula = "模型區間優先｜公式需校正"
            basis_txt = "EPS/倍數與區間不一致"
            multiple_txt = "需人工校正"
            row_pe = "需校正"
            row_market = f"{row_market}｜公式警示"

        is_current = old_zone == current_zone or layer in str(current_zone)
        if isinstance(current_zone, str) and current_zone.startswith("重疊區"):
            is_current = is_current or old_zone in current_zone
        if is_current:
            matched = True

        rows.append(
            {
                "_sort_price": _range_mid(r),
                "目前": "✅" if is_current else "",
                "價格層": layer,
                "判斷": spec["meaning"],
                "估值模組": submodel_name,
                "公式": row_formula,
                "倍數": multiple_txt,
                "基礎": basis_txt,
                "估值區間": zone_display,
                # 舊版畫面相容：若 UI 仍讀 EPS / PE / 股價區間，也不能顯示成 - / -。
                "EPS": row_eps,
                "PE": row_pe,
                "股價區間": zone_display,
                "理論公式區": theoretical_zone if theoretical_zone else "",
                "現價位置": _vs_range_text(close, r),
                "市場含意": row_market,
            }
        )

    # 目前股價不在任何區間時，插入目前股價列，方便手機版定位
    if close is not None and not matched and (
        current_zone in ["低於下修區", "高於市場溢價區", "區間外"]
        or (isinstance(current_zone, str) and "之間" in current_zone)
    ):
        rows.append(
            {
                "_sort_price": close,
                "目前": "✅",
                "價格層": "現價",
                "判斷": "模型外",
                "估值模組": submodel_name,
                "公式": "現價定位",
                "倍數": "-",
                "基礎": "-",
                "估值區間": fmt_price(close),
                "EPS": "-",
                "PE": "-",
                "股價區間": fmt_price(close),
                "理論公式區": "",
                "現價位置": current_zone,
                "市場含意": "需看下次驗證",
            }
        )

    df = pd.DataFrame(rows)
    if not df.empty and "_sort_price" in df.columns:
        df = df.sort_values("_sort_price", kind="mergesort").drop(columns=["_sort_price"]).reset_index(drop=True)

    return df, current_zone



def style_current_zone(df):
    def _style(row):
        if row.get("目前所在區間") == "✅ 目前股價" or row.get("目前") == "✅":
            return [
                "background-color:#facc15;color:#111827;font-weight:800" for _ in row
            ]
        return ["" for _ in row]

    return df.style.apply(_style, axis=1)


def price_status(price, val):
    if not price or not val.get("ok"):
        return "資料不足", "資料不足，不能用估值推買點"
    close = price.get("close")
    if close is None:
        return "資料不足", "股價資料不足"
    current_zone = valuation_zone_name(close, val)
    mapping = {
        "低於下修區": (
            "低估",
            "股價低於悲觀價，便宜不等於能買，需確認基本面沒有惡化",
        ),
        "下修區": (
            "悲觀價 / 驗證失敗區",
            "股價在悲觀價附近，需確認是基本面轉弱還是市場錯殺",
        ),
        "保守區": ("保守價", "股價落在保守價，風報比相對較好，但仍需確認催化"),
        "中性 / 基本面支撐區": ("基本面支撐價", "股價落在基本面支撐價，代表基本面大致撐得住"),
        "樂觀區": (
            "合理價 / 偏樂觀",
            "股價已進入合理偏樂觀區，需要營收、毛利率與 EPS 接棒",
        ),
        "估值重評合理區": (
            "樂觀價 / 重評初段",
            "股價已吃到估值重評預期，風報比下降",
        ),
        "市場溢價區": ("重評價 / 高溢價", "股價已進入高溢價區，只適合強基本面與強趨勢支撐"),
        "高於市場溢價區": (
            "高於重評價",
            "股價高於市場溢價模型上緣，風報比下降，需人工校正估值",
        ),
    }
    if current_zone in mapping:
        return mapping[current_zone]
    if current_zone.startswith("重疊區"):
        return "區間重疊", f"股價位於 {current_zone}，代表模型區間有重疊，需人工複核"
    if "之間" in current_zone:
        return "區間夾層", f"股價位於 {current_zone}，要看下一份資料能否接棒"
    return "資料不足", "估值資料不足"





def valuation_forensic_check(val, price=None, fj=None, rr=None, industry_category=None, analyst_target=None, current_zone=None):
    """估值信心精準版：先判斷估值能不能信，再保留目標價作參考。

    設計原則：
    1) 估值目標價保留，但永遠標成「參考」。
    2) 先看 EPS 可信度，再看 PE / 產業方法是否適用。
    3) 估值信心低時，不否決 Core，但會限制 Focus。
    """
    close = price.get("close") if price else None

    def _fmt_pe_range(r):
        if not r or not isinstance(r, (list, tuple)) or len(r) < 2:
            return "無資料"
        return f"{r[0]}x～{r[1]}x"

    def _range_text(name, r):
        if not r or r[0] is None or r[1] is None:
            return None
        return f"{name} {fmt_price(min(r[0], r[1]))}～{fmt_price(max(r[0], r[1]))}"

    if not val or not val.get("ok"):
        return {
            "confidence": "不適用",
            "status": "資料不足，暫不給內部目標價",
            "plain": "估值資料不足，本次估值不能當買賣依據。",
            "eps_confidence": "不適用",
            "eps_confidence_reason": "沒有有效 EPS，無法推估合理價。",
            "eps_basis": "無有效 EPS",
            "valuation_method": "無有效估值法",
            "method_suitability": "不適用",
            "pe_basis": "無有效 PE 模型",
            "implied_pe_text": "無資料",
            "implied_pe_verdict": "無法判斷",
            "pe_suitable": "需人工判斷",
            "focus_ok": False,
            "focus_effect": "Focus 降級：估值資料不足",
            "target_model_ref": "內部模型暫不給目標價",
            "target_market_ref": "法人共識：無資料",
            "target_ref": "內部模型暫不給目標價；若有法人共識，只能當參考。",
            "warnings": [val.get("reason", "估值資料不足") if isinstance(val, dict) else "估值資料不足"],
        }

    model_key = val.get("model_key", "")
    model_name = val.get("model_name", "")
    primary = val.get("model_primary", "") or "PE"
    pe_scenarios = val.get("pe_scenarios", {}) or {}
    implied_ttm_pe = val.get("implied_ttm_pe")
    implied_future_pe = val.get("implied_future_pe")
    model_high_pe = val.get("model_high_pe")
    future_eps = val.get("future_eps")
    base_eps = val.get("base_eps")
    ttm_eps = val.get("ttm_eps")
    quarter_eps = val.get("quarter_eps")
    annualized_eps = val.get("annualized_eps")
    growth = val.get("growth")
    base_eps_label = val.get("base_eps_label", "EPS")
    future_eps_note = val.get("future_eps_note", "")
    pe_status = val.get("pe_status", "")
    current_zone = current_zone or valuation_zone_name(close, val)

    warnings = []
    severe = False
    medium = False

    # ── 1) EPS 可信度分級 ─────────────────────────────────
    eps_confidence = "中"
    eps_reasons = []
    if future_eps is None or future_eps <= 0 or base_eps is None or base_eps <= 0:
        eps_confidence = "不適用"
        severe = True
        eps_reasons.append("EPS 不足或不為正，不能做 PE 估值")
    else:
        # TTM EPS 是最穩的基礎；單季年化只能當 run-rate 參考。
        if ttm_eps is not None and ttm_eps > 0:
            eps_confidence = "高"
            eps_reasons.append("使用近四季 EPS 作基礎，穩定度較高")
        elif annualized_eps is not None and annualized_eps > 0:
            eps_confidence = "中"
            medium = True
            eps_reasons.append("主要來自最近一季 EPS 年化，需確認不是單季暴衝")
        else:
            eps_confidence = "低"
            severe = True
            eps_reasons.append("EPS 基礎不完整")

        # 單季年化若遠高於 TTM，代表有 run-rate 上修，但也可能過度樂觀。
        if ttm_eps and annualized_eps and annualized_eps > ttm_eps * 1.6:
            eps_confidence = "中" if eps_confidence == "高" else eps_confidence
            medium = True
            eps_reasons.append("最近一季年化 EPS 明顯高於 TTM，可能是轉強，也可能是單季高峰")
        if ttm_eps and annualized_eps and annualized_eps < ttm_eps * 0.65:
            medium = True
            eps_reasons.append("最近一季年化 EPS 明顯低於 TTM，獲利動能可能降溫")
        if future_eps and base_eps and growth is not None and growth > 25:
            medium = True
            eps_reasons.append("Future EPS 成長假設偏高，目標價需打折看")
        if future_eps is not None and future_eps < 1:
            eps_confidence = "低"
            severe = True
            eps_reasons.append("EPS 基礎太小，PE 容易被放大失真")

    if eps_confidence in ["低", "不適用"]:
        warnings.append("EPS 可信度偏低，內部目標價只能當風險參考")
    elif eps_confidence == "中":
        warnings.append("EPS 可參考但需保守，不能單獨當買點依據")

    # ── 2) 產業估值方法自動說明 ───────────────────────────
    method_map = {
        "financial": ("P/B + ROE + 股利能力", "PE 只能輔助，金融股應優先看淨值、ROE、股利與利率環境"),
        "asset_construction": ("NAV / P/B + 入帳週期", "PE 只能輔助，營建資產股需看淨值、案量、入帳與資產價值"),
        "dividend_utility": ("殖利率 + 現金流 + 防守性", "PE 只能輔助，高股息 / 電信需看配息能力、現金流與殖利率區間"),
        "cyclical_material": ("P/B + 景氣循環位置 + 毛利率", "PE 只能輔助，循環股高峰 EPS 會讓 PE 看起來便宜"),
        "turnaround": ("營收 / 毛利 / EPS 改善幅度", "PE 只能輔助，轉機股要先看轉機是否被財報驗證"),
        "distributor": ("PE + 毛利率 + 現金流 + 應收存貨", "通路股營收大不代表獲利強，需嚴查毛利、現金流與營運資金"),
        "low_margin_assembly": ("PE + 營益率 + EPS 轉換率", "低毛利組裝股不能只看營收，需看獲利率是否真的改善"),
        "semi_leader": ("Forward PE + 現金流 + 產業地位", "可用 PE，但需檢查市場是否已給過高溢價"),
        "ic_design_large": ("Forward PE + 產品週期 + 毛利率", "可用 PE，但需確認產品循環與下一季展望"),
        "ai_pcb_ccl": ("Forward PE + 毛利率 / 產品結構", "可用 PE，但重點是高階產品占比與 EPS 能否接上"),
        "ai_power_premium": ("Forward PE + 訂單能見度 + 毛利率", "可用 PE，但若現價遠高於重評區需限制追價"),
        "growth_premium": ("Forward PE + EPS 上修", "可用 PE，但若 EPS 未跟上題材，估值要降權"),
        "optical_ai_datacenter": ("Forward PE + EPS 上修 + 訂單能見度", "可用 PE，但波動大，法人目標價只能輔助"),
        "precision_component_growth": ("Forward PE + 高毛利續航", "可用 PE，但需確認毛利率與 EPS 持續性"),
        "default": ("PE 粗估", "目前仍是 default 模型，產業估值可能錯配，需保守"),
    }
    method_map.update({
        "mature_foundry": ("Forward PE + 產能利用率 + ASP / 毛利率循環位置", "成熟製程需區分 TTM PE 偏貴與 Future EPS 可否解釋；未驗證毛利率 / ASP 前不追高"),
        "semicap_equipment_material": ("Forward PE + 訂單能見度 + 資本支出循環", "設備材料股要看訂單、認列與資本支出，不可只看題材"),
        "abf_substrate": ("Forward PE + 稼動率 + 報價 / 產品結構 + EPS 上修", "AI 高階 ABF / BT 載板若營收轉 EPS 且毛利率 / 營益率改善，可給重評 PE；但需搭配循環位置與買點紀律"),
        "abf_bt_substrate_cycle": ("Forward PE + 稼動率 + 報價 / 產品結構 + EPS 上修", "欣興 / 景碩 / 南電類 ABF / BT 載板，不可跟一般 PCB 或耗材混用"),
        "ai_server_pcb_core": ("Forward PE + AI 伺服器板占比 + 毛利率 / EPS", "金像電類 AI 高階 PCB，不可直接套 ABF 載板 PE，也不能用一般 PCB 低 PE"),
        "pcb_drill_consumables": ("Forward PE + 耗材出貨 + 高階 PCB 稼動率", "尖點類 PCB 鑽針 / 耗材，不是 ABF 本體也不是一般 PCB"),
        "general_pcb_hdi_candidate": ("Forward PE + 產品組合 + 毛利率改善", "一般 PCB / HDI 候選，未證明高階占比前不給高估值"),
        "thermal_liquid_cooling": ("Forward PE + 液冷滲透率 + 毛利率", "散熱液冷可用 PE，但需確認客戶放量與毛利率是否兌現"),
        "connector_highspeed": ("Forward PE + 高速規格升級 + 滲透率", "連接器需確認高速規格與客戶滲透，不可把一般產品給高估值"),
        "memory_storage": ("報價循環 + 庫存 + 毛利率轉正", "記憶體 PE 容易失真，需優先看報價與循環位置"),
        "power_grid_equipment": ("Forward PE + 在手訂單 + 認列節奏", "重電需看訂單認列與毛利率，漲多後需限制追價"),
        "robotics_automation": ("Forward PE + 本業自動化 + 訂單驗證", "機器人題材需確認是否能轉成營收與 EPS"),
        "ip_asic_design": ("Forward PE + NRE / 授權 / ASIC 放量", "矽智財可有高估值，但需驗證案量與量產時程"),
        "cybersecurity_software": ("Forward PE + 經常性收入 + 毛利率", "資安軟體需看續約、經常性收入與 EPS 續航"),
        "biotech_healthcare": ("產品階段 + 授權 / 藥證 / 營收化", "生技未獲利或里程碑型不能只用 PE"),
        "shipping_logistics": ("運價 / 客運需求 + P/B + 循環位置", "航運航空 PE 只能輔助，景氣高峰 EPS 會扭曲估值"),
        "tourism_consumption": ("Forward PE + 客流 / 展店 / 同店銷售", "觀光餐飲需看旺季與成本，不能只看題材"),
        "green_energy_storage": ("Forward PE + 專案認列 + 現金流", "綠能儲能需看專案認列、負債與現金流"),
    })
    valuation_method, method_suitability = method_map.get(
        model_key,
        (primary or "PE", "目前用模型法估值，但仍需確認產業特性是否適配")
    )
    non_pe_models = {"financial", "asset_construction", "dividend_utility", "cyclical_material", "turnaround", "memory_storage", "biotech_healthcare", "shipping_logistics"}
    pe_suitable = "適合以 PE 為主" if model_key not in non_pe_models else "PE 只能輔助，需看 P/B、ROE、殖利率、NAV 或循環位置"
    if model_key in non_pe_models:
        medium = True
        warnings.append("此產業不適合只用 PE 估值")
    if model_key == "default":
        medium = True
        warnings.append("目前仍是 default 模型，產業 PE 可能需校正")
    _strict_pe_models = {
        "mature_foundry",
        "memory_storage",
        "power_grid_equipment",
        "robotics_automation",
        "biotech_healthcare",
        "shipping_logistics",
        "real_estate_delivery_recognition",
        "green_energy_storage",
    }
    if model_key in _strict_pe_models:
        if implied_ttm_pe is not None and implied_ttm_pe >= 35:
            medium = True
            warnings.append("TTM PE 偏高，代表現價已先反映一段修復或題材期待")
        opt_pe_tmp = pe_scenarios.get("opt") if pe_scenarios else None
        rer_pe_tmp = pe_scenarios.get("rerating") if pe_scenarios else None
        if implied_future_pe is not None and opt_pe_tmp and implied_future_pe > opt_pe_tmp[1]:
            medium = True
            warnings.append("Future PE 已高於樂觀區，需等待營收 / 毛利率 / EPS 驗證")
        if implied_future_pe is not None and rer_pe_tmp and implied_future_pe > rer_pe_tmp[1]:
            severe = True
            warnings.append("Future PE 已超出重評區，Focus 必須降級")

    # ── 3) 現價隱含 PE vs 模型 PE ─────────────────────────
    implied_pe_verdict = "無法判斷"
    if implied_future_pe is None or model_high_pe is None:
        medium = True
        implied_pe_verdict = "資料不足，不能判斷現價 PE 是否合理"
    else:
        neutral_pe = pe_scenarios.get("neutral")
        opt_pe = pe_scenarios.get("opt")
        rer_pe = pe_scenarios.get("rerating")
        mkt_pe = pe_scenarios.get("market_premium")
        if mkt_pe and implied_future_pe > mkt_pe[1] * 1.5:
            severe = True
            implied_pe_verdict = "現價隱含 PE 遠高於模型上緣，估值可能失真或股價已嚴重提前反映"
            warnings.append("現價隱含 PE 遠高於模型上緣")
        elif mkt_pe and implied_future_pe > mkt_pe[1] * 1.15:
            medium = True
            implied_pe_verdict = "現價隱含 PE 高於模型上緣，需保守看待"
            warnings.append("現價隱含 PE 高於模型上緣")
        elif rer_pe and implied_future_pe > rer_pe[1]:
            medium = True
            implied_pe_verdict = "現價已高於一般重評 PE，市場給高溢價"
        elif opt_pe and implied_future_pe > opt_pe[1]:
            implied_pe_verdict = "現價高於樂觀 PE，仍可追蹤但不適合亂追"
        elif neutral_pe and implied_future_pe <= neutral_pe[1]:
            implied_pe_verdict = "現價 PE 仍在中性模型可解釋範圍"
        else:
            implied_pe_verdict = "現價 PE 位於樂觀區附近，可參考但要看買點"

    if current_zone in ["高於市場溢價區", "區間外"] or (isinstance(current_zone, str) and "之間" in current_zone):
        medium = True
        warnings.append(f"現價位於 {current_zone}，估值需保守解讀")

    # ── 4) 法人共識與內部模型分開顯示 ─────────────────────
    analyst_text = "法人共識：無資料"
    at_mean = None
    if analyst_target and analyst_target.get("ok"):
        at_mean = analyst_target.get("mean")
        if at_mean is not None and close:
            gap = (at_mean - close) / close * 100
            analyst_text = f"法人平均 {fmt_price(at_mean)}（相對現價 {'+' if gap >= 0 else ''}{gap:.1f}%），僅供參考"
            hi_model = None
            mp = val.get("market_premium")
            if mp and mp[1] is not None:
                hi_model = max(mp[0], mp[1])
            if hi_model and at_mean > hi_model * 1.5:
                medium = True
                warnings.append("法人目標價明顯高於內部模型上緣，需確認模型或 EPS 假設")
        else:
            analyst_text = "法人共識：有資料但缺少平均目標價"

    neutral_ref = _range_text("中性", val.get("neutral"))
    opt_ref = _range_text("樂觀", val.get("opt"))
    rerating_ref = _range_text("重評", val.get("rerating"))
    model_target_ref = "；".join([x for x in [neutral_ref, opt_ref, rerating_ref] if x]) or "內部模型暫無有效區間"

    # ── 5) 綜合估值信心與 Focus 影響 ───────────────────────
    if severe:
        confidence = "低" if eps_confidence != "不適用" else "不適用"
        status = "估值可信度低"
        plain = "本次 EPS、PE 或產業模型有明顯風險，估值目標價只能當參考，不能當買點依據。"
        focus_ok = False
        focus_effect = "Focus 降級：估值信心低，不給 Focus Yes"
    elif medium:
        confidence = "中"
        status = "估值可參考，但要保守"
        plain = "本次估值可以輔助判斷，但需搭配支撐、回檔品質、財報續航與籌碼，不可單獨決定買賣。"
        focus_ok = True
        focus_effect = "Focus 可保留，但動作偏分批 / 不追高"
    else:
        confidence = "高"
        status = "估值模型相對可信"
        plain = "EPS、PE 與產業模型大致一致，可搭配技術位置作為目標價參考。"
        focus_ok = True
        focus_effect = "估值不限制 Focus"

    # EPS 信心若低，估值信心至少不能高。
    if eps_confidence == "低" and confidence == "高":
        confidence = "中"
        status = "估值可參考，但 EPS 需保守"
        focus_effect = "Focus 可保留，但需等買點，不可追高"
    if eps_confidence == "不適用":
        confidence = "不適用"
        status = "EPS 不適用，暫不給內部目標價"
        focus_ok = False
        focus_effect = "Focus 降級：EPS 不足，估值不能支撐 Focus"

    if confidence in ["低", "不適用"]:
        target_ref = f"低信心參考：{model_target_ref}；{analyst_text}"
    elif confidence == "中":
        target_ref = f"保守參考：{model_target_ref}；{analyst_text}"
    else:
        target_ref = f"可參考：{model_target_ref}；{analyst_text}"

    eps_basis = f"{base_eps_label}：{fmt(base_eps)}；Future EPS：{fmt(future_eps)}。{future_eps_note}"
    eps_confidence_reason = "；".join(eps_reasons) if eps_reasons else "EPS 基礎正常"
    pe_basis = (
        f"採用模型：{model_name}；估值方法：{valuation_method}；"
        f"中性 PE：{_fmt_pe_range(pe_scenarios.get('neutral'))}；"
        f"樂觀 PE：{_fmt_pe_range(pe_scenarios.get('opt'))}；"
        f"重評 PE：{_fmt_pe_range(pe_scenarios.get('rerating'))}；"
        f"市場溢價 PE：{_fmt_pe_range(pe_scenarios.get('market_premium'))}"
    )
    implied_pe_text = (
        f"TTM PE：{fmt(implied_ttm_pe)}x；"
        f"Future PE：{fmt(implied_future_pe)}x；"
        f"模型最高 PE：{fmt(model_high_pe)}x；{implied_pe_verdict}"
    )

    return {
        "confidence": confidence,
        "status": status,
        "plain": plain,
        "eps_confidence": eps_confidence,
        "eps_confidence_reason": eps_confidence_reason,
        "eps_basis": eps_basis,
        "valuation_method": valuation_method,
        "method_suitability": method_suitability,
        "pe_basis": pe_basis,
        "implied_pe_text": implied_pe_text,
        "implied_pe_verdict": implied_pe_verdict,
        "pe_suitable": pe_suitable,
        "focus_ok": focus_ok,
        "focus_effect": focus_effect,
        "target_model_ref": model_target_ref,
        "target_market_ref": analyst_text,
        "target_ref": target_ref,
        "warnings": list(dict.fromkeys(warnings))[:6],
    }

def judge_trend_change(price, rev, inst, fin):
    if not price:
        return {
            "status": "資料不足",
            "score": 0,
            "bias": "中性",
            "text": "股價資料不足，無法判斷趨勢變化。",
            "items": [],
        }
    close = price.get("close")
    ref_label = str(price.get("trend_reference_label") or "收盤")
    ma20 = price.get("ma20")
    ma60 = price.get("ma60")
    ma20_slope = price.get("ma20_slope_5")
    ma60_slope = price.get("ma60_slope_10")
    ret20 = price.get("ret20")
    ret5 = price.get("ret5")
    drawdown20 = price.get("drawdown20")
    volume_ratio = price.get("volume_ratio")
    breakout_now = price.get("breakout_now")
    score = 0
    items = []

    def add(item, verdict, impact, reason):
        nonlocal score
        score += impact
        items.append(
            {
                "項目": item,
                "判斷": verdict,
                "分數": impact,
                "原因": reason,
            }
        )

    if close is not None and ma20 is not None and ma60 is not None:
        if close > ma20 > ma60:
            add(
                "均線位置",
                "多頭排列",
                2,
                f"{ref_label} {fmt_price(close)} > MA20 {fmt_price(ma20)} > MA60 {fmt_price(ma60)}",
            )
        elif close < ma20 and close >= ma60 * 0.96:
            add(
                "均線位置",
                "支撐測試",
                0,
                f"{ref_label} {fmt_price(close)} 回測 MA20 / MA60，仍在 MA60 4% 容忍區內",
            )
        elif close < ma20 and close < ma60 * 0.96:
            add(
                "均線位置",
                "空頭排列",
                -3,
                f"{ref_label} {fmt_price(close)} 已低於 MA60 4% 容忍區，波段轉弱警訊",
            )
    if ma20_slope is not None and ma60_slope is not None:
        if ma20_slope > 2 and ma60_slope > 0:
            add(
                "均線斜率",
                "趨勢加速",
                2,
                f"20 日與 60 日斜率同步向上：{fmp(ma20_slope)} / {fmp(ma60_slope)}",
            )
        elif ma20_slope < -1.5 and ma60_slope < 0:
            add(
                "均線斜率",
                "趨勢鈍化",
                -2,
                f"20 日與 60 日斜率同步轉弱：{fmp(ma20_slope)} / {fmp(ma60_slope)}",
            )
        else:
            add(
                "均線斜率",
                "中性",
                0,
                f"20 日斜率 {fmp(ma20_slope)}，60 日斜率 {fmp(ma60_slope)}",
            )
    if breakout_now:
        add(
            "價量突破", "轉強訊號", 2, f"{ref_label}突破近 20 日壓力，且量能放大或近 5 日量能升溫"
        )
    elif volume_ratio is not None:
        if volume_ratio >= 1.8 and ((ret5 is not None and ret5 <= -3) or (ret20 is not None and ret20 <= -7)):
            add(
                "價量關係",
                "放量下殺",
                -2,
                f"量能比 {fmt(volume_ratio)}，近 5 日 {fmp(ret5)} / 近 20 日 {fmp(ret20)}",
            )
        elif volume_ratio < 0.8 and drawdown20 is not None and -12 <= drawdown20 <= -3:
            add(
                "價量關係",
                "量縮回測",
                1,
                f"量能比 {fmt(volume_ratio)}，距 20 日高點 {fmp(drawdown20)}，偏健康回測",
            )
        else:
            add("價量關係", "中性", 0, f"量能比 {fmt(volume_ratio)}")
    if inst:
        n5 = inst.get("net5_lot")
        n20 = inst.get("net20_lot")
        if n5 is not None and n20 is not None:
            if n5 > 0 and n20 > 0:
                add(
                    "法人方向",
                    "籌碼支撐",
                    1,
                    f"近 5 日 {fmt0(n5)} 張，近 20 日 {fmt0(n20)} 張",
                )
            elif n5 <= -3000 and n20 <= -5000:
                add(
                    "法人方向",
                    "出貨型賣壓",
                    -2,
                    f"近 5 日 {fmt0(n5)} 張，近 20 日 {fmt0(n20)} 張，需確認是否為出貨",
                )
            elif n5 < 0 and n20 < 0:
                add(
                    "法人方向",
                    "健康調節 / 中性賣壓",
                    -1,
                    f"近 5 日 {fmt0(n5)} 張，近 20 日 {fmt0(n20)} 張，若支撐未破可視為調節",
                )
            else:
                add(
                    "法人方向",
                    "中性",
                    0,
                    f"近 5 日 {fmt0(n5)} 張，近 20 日 {fmt0(n20)} 張",
                )
    if rev:
        y = rev.get("yoy")
        yl = rev.get("yoy_list", [])
        if y is not None:
            if y >= 20:
                add("營收趨勢", "基本面升溫", 1, f"最新月營收年增 {fmp(y)}")
            elif y < 0:
                add("營收趨勢", "基本面降溫", -1, f"最新月營收年增 {fmp(y)}")
            else:
                add("營收趨勢", "中性", 0, f"最新月營收年增 {fmp(y)}")
        if len(yl) >= 3:
            if yl[-1] > yl[-2] > yl[-3]:
                add("營收斜率", "連續升溫", 1, "近三月營收年增率連續升溫")
            elif yl[-1] < yl[-2] < yl[-3]:
                add("營收斜率", "連續降溫", -1, "近三月營收年增率連續降溫")
    if fin:
        eps_yoy = fin.get("eps_yoy")
        gm = fin.get("gross_margin")
        gmp = fin.get("gross_margin_prev")
        if eps_yoy is not None:
            if eps_yoy >= 10:
                add("EPS 方向", "獲利升溫", 1, f"EPS 年增 {fmp(eps_yoy)}")
            elif eps_yoy < 0:
                add("EPS 方向", "獲利降溫", -1, f"EPS 年增 {fmp(eps_yoy)}")
        if gm is not None and gmp is not None:
            if gm >= gmp - 1:
                add("毛利率", "結構未壞", 1, f"毛利率 {fmp(gm)}，前期 {fmp(gmp)}")
            else:
                add("毛利率", "結構轉弱", -1, f"毛利率 {fmp(gm)}，前期 {fmp(gmp)}")
    severe_break = (
        close is not None and ma60 is not None and close < ma60 * 0.96 and score <= -3
    )
    healthy_pullback = (
        close is not None
        and ma20 is not None
        and ma60 is not None
        and close < ma20
        and close >= ma60 * 0.96
        and score >= 0
    )
    if severe_break:
        status = "趨勢反轉"
        bias = "偏空"
        text = "跌破波段均線且籌碼 / 基本面訊號未能支撐，不能再當正常回測。"
    elif score >= 5:
        status = "趨勢轉強"
        bias = "偏多"
        text = "價量、均線、籌碼或基本面多數同步轉強，屬於趨勢升溫。"
    elif healthy_pullback:
        status = "正常回測"
        bias = "中性偏多"
        text = "短線回測但波段防線未破，且籌碼 / 基本面沒有明顯惡化。"
    elif score <= -4:
        status = "趨勢轉弱"
        bias = "偏空"
        text = "多項訊號同步轉弱，需降低追價與加碼意願。"
    elif score <= -2:
        status = "趨勢鈍化"
        bias = "中性偏空"
        text = "趨勢沒有完全反轉，但上攻力道變弱，等重新轉強。"
    else:
        status = "盤整觀察"
        bias = "中性"
        text = "目前訊號分歧，尚未構成明確轉強或反轉。"
    return {
        "status": status,
        "score": score,
        "bias": bias,
        "text": text,
        "items": items,
    }



