def analyze_position(holding_cost, price, a):
    cost = to_float(holding_cost)
    close = price.get("close") if price else None
    if cost is None or cost <= 0 or close is None:
        return None
    pnl = pct_change(close, cost)
    stop_num = to_float(a.get("plan", {}).get("stop"))
    wrong_num = to_float(a.get("plan", {}).get("wrong"))
    short_num = to_float(a.get("plan", {}).get("short"))
    wave_num = to_float(a.get("plan", {}).get("wave"))
    if pnl is None:
        position_action = "資料不足"
    elif pnl >= 50:
        position_action = "獲利很大，優先用移動停利守住，不宜再無腦加碼"
    elif pnl >= 30:
        position_action = "已達可分批獲利區，留一部分看波段續航"
    elif pnl >= 15:
        position_action = "有獲利墊，可續抱但要守波段失效點"
    elif pnl >= 0:
        position_action = "小幅獲利，重點看是否守住新倉主區與均線"
    elif stop_num is not None and close < stop_num:
        position_action = "跌破波段失效點，優先降風險"
    else:
        position_action = "目前虧損未必錯，但要確認買進理由沒有消失"
    return {
        "holding_cost": cost,
        "close": close,
        "pnl_pct": pnl,
        "pnl_text": fmp(pnl),
        "position_action": position_action,
        "wrong": wrong_num,
        "stop": stop_num,
        "short": short_num,
        "wave": wave_num,
    }


