def clamp(x, low, high):
    return max(low, min(high, x))


def calc_rr(entry, stop, target):
    if entry is None or stop is None or target is None:
        return None
    denom = entry - stop
    if denom <= 0:
        return None
    return (target - entry) / denom


def _win_label(pct):
    if pct >= 80:
        return "條件高"
    if pct >= 70:
        return "條件中高"
    if pct >= 60:
        return "條件中"
    if pct >= 50:
        return "條件偏低"
    return "條件低"


def _win_conclusion(pct):
    if pct >= 80:
        return "條件完整，但仍需照停損執行。"
    if pct >= 70:
        return "可分批布局，但不要追高。"
    if pct >= 60:
        return "可觀察，等更好位置。"
    if pct >= 50:
        return "位置或條件不夠好，先不要急。"
    return "不建議進場。"


def _evidence_grade_from_context(price_dict, a, rr_val=None):
    """v247：證據完整度只做後台判斷，前台顯示高/中高/中/低。"""
    checks = 0
    total = 8
    if price_dict:
        checks += 1
    try:
        if (a.get("fin_j") or {}).get("report"):
            checks += 1
    except Exception:
        pass
    try:
        if (a.get("rerating") or {}).get("verdict"):
            checks += 1
    except Exception:
        pass
    try:
        if (a.get("trend") or {}).get("status"):
            checks += 1
    except Exception:
        pass
    try:
        if (a.get("chip_j") or {}).get("score") is not None:
            checks += 1
    except Exception:
        pass
    try:
        if a.get("valuation_zone"):
            checks += 1
    except Exception:
        pass
    try:
        nums = (a.get("plan") or {}).get("num") or {}
        if nums.get("stop") is not None and nums.get("wave") is not None:
            checks += 1
    except Exception:
        pass
    if rr_val is not None:
        checks += 1
    try:
        _tech_ev = _technical_evidence_adjustment(price_dict, a, "evidence", None, None, None)
        if (_tech_ev.get("evidence_count") or 0) >= 3:
            checks += 1
            total += 1
    except Exception:
        pass
    try:
        _tech_q = _technical_data_quality(price_dict)
        total += 1
        if _tech_q.get("grade") in ["高", "中高"]:
            checks += 1
        elif _tech_q.get("grade") == "中":
            checks += 0.5
    except Exception:
        pass
    try:
        _mkt_ctx = _market_sector_context_adjustment(a)
        total += 1
        if _mkt_ctx.get("evidence_count"):
            checks += 1
    except Exception:
        pass

    ratio = checks / max(total, 1)
    if ratio >= 0.85:
        return "高"
    if ratio >= 0.70:
        return "中高"
    if ratio >= 0.50:
        return "中"
    return "低"


def _win_range_text(pct, evidence_grade="中", cap=90):
    """單一規則分數轉為區間，避免讓使用者誤會成精準勝率。"""
    pct = int(clamp(round(pct), 25, cap))
    spread = 5
    if evidence_grade == "低":
        spread = 8
    elif evidence_grade == "中":
        spread = 6
    lo = int(clamp(pct - spread, 20, 90))
    hi = int(clamp(pct + spread, 25, cap))
    if hi < lo:
        hi = lo
    return f"{lo}%～{hi}%"


def _scenario_action_text(pct, scenario_type, action="", rr_val=None):
    """只給客戶看最後適合動作，不顯示背後公式。"""
    action_s = str(action or "")
    if "不買" in action_s:
        return "先不買"
    if scenario_type == "current" and ("等回檔" in action_s or "不追" in action_s or "只觀察" in action_s):
        return "不追高"
    if pct < 45:
        return "先觀察"
    if scenario_type == "breakout":
        return "右側小倉" if pct >= 50 else "等站穩"
    if scenario_type == "new_zone":
        return "分批布局" if pct >= 60 else "小倉觀察"
    if scenario_type == "pullback":
        return "小倉試單" if pct >= 50 else "等止跌"
    if scenario_type == "holding":
        return "續抱檢查"
    if pct >= 70:
        return "可分批"
    if pct >= 55:
        return "小倉觀察"
    return "只觀察"


def _latest_kd_from_price(price_dict):
    """v247：從 price.raw 背後計算 KD，只供買點條件分數用，不顯示給客戶。"""
    try:
        raw = price_dict.get("raw") if isinstance(price_dict, dict) else None
        if raw is None or getattr(raw, "empty", True) or len(raw) < 12:
            return None
        df = raw.copy().sort_values("date").reset_index(drop=True)
        high_col = "max" if "max" in df.columns else "high"
        low_col = "min" if "min" in df.columns else "low"
        close_col = "close"
        for c in [high_col, low_col, close_col]:
            df[c] = df[c].apply(to_float)
        low9 = df[low_col].rolling(9, min_periods=9).min()
        high9 = df[high_col].rolling(9, min_periods=9).max()
        rsv = (df[close_col] - low9) / (high9 - low9) * 100
        rsv = rsv.replace([float("inf"), float("-inf")], None).fillna(50)
        k_vals = []
        d_vals = []
        k = 50.0
        d = 50.0
        for v in rsv.tolist():
            try:
                vv = float(v)
            except Exception:
                vv = 50.0
            k = (2 / 3) * k + (1 / 3) * vv
            d = (2 / 3) * d + (1 / 3) * k
            k_vals.append(k)
            d_vals.append(d)
        if len(k_vals) < 2:
            return None
        return {"k": k_vals[-1], "d": d_vals[-1], "prev_k": k_vals[-2], "prev_d": d_vals[-2]}
    except Exception:
        return None


def _latest_kbar_profile(price_dict):
    """v247：背後判讀最後一根 K 棒品質。"""
    out = {"long_red": False, "long_black": False, "upper_shadow": False, "lower_shadow": False, "doji": False, "body_pct": None}
    try:
        raw = price_dict.get("raw") if isinstance(price_dict, dict) else None
        if raw is None or getattr(raw, "empty", True):
            return out
        row = raw.copy().sort_values("date").iloc[-1]
        o = to_float(row.get("open"))
        h = to_float(row.get("max"))
        l = to_float(row.get("min"))
        c = to_float(row.get("close"))
        if None in [o, h, l, c] or c <= 0:
            return out
        body_pct = abs(c - o) / c * 100
        upper_pct = (h - max(o, c)) / c * 100
        lower_pct = (min(o, c) - l) / c * 100
        out["body_pct"] = body_pct
        out["long_red"] = c > o and body_pct >= 2.5
        out["long_black"] = c < o and body_pct >= 2.5
        out["upper_shadow"] = upper_pct >= max(2.0, body_pct * 0.65)
        out["lower_shadow"] = lower_pct >= max(2.0, body_pct * 0.65)
        out["doji"] = body_pct <= 0.6
        return out
    except Exception:
        return out


def _technical_evidence_adjustment(price_dict, a, scenario_type, entry, stop_p, wave_p):
    """v247：技術證據後台化。
    只影響條件分數與上限，不把 KD / 扣抵 / K棒細項攤給客戶。
    """
    adj = 0
    cap_adj = None
    evidence_count = 0
    try:
        if not isinstance(price_dict, dict):
            return {"score": 0, "cap": None, "evidence_count": 0}
        close = to_float(price_dict.get("close"))
        ma5 = to_float(price_dict.get("ma5"))
        ma10 = to_float(price_dict.get("ma10"))
        ma20 = to_float(price_dict.get("ma20"))
        ma60 = to_float(price_dict.get("ma60"))
        ma20_slope = to_float(price_dict.get("ma20_slope_5"))
        ma60_slope = to_float(price_dict.get("ma60_slope_10"))
        volume_ratio = to_float(price_dict.get("volume_ratio"))
        ret5 = to_float(price_dict.get("ret5"))
        ret20 = to_float(price_dict.get("ret20"))
        drawdown20 = to_float(price_dict.get("drawdown20"))
        high20 = to_float(price_dict.get("high20")) or to_float(price_dict.get("prev_high20"))
        low20 = to_float(price_dict.get("low20"))
        low10 = to_float(price_dict.get("low10"))
        breakout_now = bool(price_dict.get("breakout_now"))

        # 1) 均線結構 / 扣抵近似：用斜率與相對位置背後加減分。
        if close is not None and ma20 is not None and ma60 is not None:
            evidence_count += 1
            if close > ma20 > ma60:
                adj += 3
            elif close < ma20 and close >= ma60 * 0.96:
                adj -= 2
            elif close < ma60 * 0.96:
                adj -= 6
                cap_adj = min(cap_adj or 99, 58)
        if ma20_slope is not None or ma60_slope is not None:
            evidence_count += 1
            if (ma20_slope or 0) > 1.5 and (ma60_slope is None or ma60_slope >= 0):
                adj += 2
            elif (ma20_slope or 0) < -1.5 and (ma60_slope is not None and ma60_slope < 0):
                adj -= 3
                cap_adj = min(cap_adj or 99, 62)

        # 2) K棒品質與量價。
        kbar = _latest_kbar_profile(price_dict)
        if kbar.get("body_pct") is not None:
            evidence_count += 1
        if volume_ratio is not None:
            evidence_count += 1
            if kbar.get("long_black") and volume_ratio >= 1.5:
                adj -= 9
                cap_adj = min(cap_adj or 99, 45 if scenario_type == "current" else 55)
            elif kbar.get("upper_shadow") and volume_ratio >= 1.3:
                adj -= 5
                cap_adj = min(cap_adj or 99, 58)
            elif kbar.get("long_red") and volume_ratio >= 1.2 and scenario_type in ("current", "breakout"):
                adj += 4
            elif volume_ratio < 0.8 and drawdown20 is not None and -12 <= drawdown20 <= -2 and scenario_type in ("pullback", "new_zone"):
                adj += 3
            if ret5 is not None and ret5 >= 10 and scenario_type in ("current", "breakout"):
                adj -= 4
                cap_adj = min(cap_adj or 99, 64)
            if ret5 is not None and ret5 <= -5 and volume_ratio >= 1.4:
                adj -= 3

        # 3) KD 動能：輔助 timing，不決定 Core。
        kd = _latest_kd_from_price(price_dict)
        if kd:
            evidence_count += 1
            k, d, pk, pdv = kd.get("k"), kd.get("d"), kd.get("prev_k"), kd.get("prev_d")
            if None not in [k, d, pk, pdv]:
                if pk < pdv and k > d and k <= 35:
                    adj += 3
                elif pk > pdv and k < d and k >= 75:
                    adj -= 4
                    cap_adj = min(cap_adj or 99, 60)
                elif k >= 80 and d >= 80:
                    if close is not None and ma20 is not None and close >= ma20:
                        adj += 1  # 強勢鈍化可續強，但只小加分。
                    else:
                        adj -= 2

        # 4) 支撐壓力距離：靠近支撐加分，壓力太近扣分。
        if close is not None and entry is not None:
            support_candidates = [x for x in [ma20, ma60, low10, low20] if x is not None and x > 0]
            pressure_candidates = [x for x in [high20] if x is not None and x > 0]
            if support_candidates:
                evidence_count += 1
                nearest_support = max([x for x in support_candidates if x <= entry * 1.03] or support_candidates)
                support_gap = abs(entry - nearest_support) / max(entry, 1e-9)
                if support_gap <= 0.03 and scenario_type in ("pullback", "new_zone"):
                    adj += 3
                elif entry < nearest_support * 0.96:
                    adj -= 2
            if pressure_candidates:
                evidence_count += 1
                nearest_pressure = min([x for x in pressure_candidates if x >= entry] or pressure_candidates)
                if nearest_pressure >= entry:
                    pressure_gap = (nearest_pressure - entry) / max(entry, 1e-9)
                    if pressure_gap <= 0.035 and scenario_type in ("current", "breakout"):
                        adj -= 4
                        cap_adj = min(cap_adj or 99, 60)
                    elif pressure_gap >= 0.10 and scenario_type in ("pullback", "new_zone"):
                        adj += 2

        # 5) 突破品質：只突破不夠，還要避免假突破。
        if scenario_type == "breakout":
            if breakout_now and volume_ratio is not None and volume_ratio >= 1.25 and not kbar.get("upper_shadow"):
                adj += 4
            elif kbar.get("upper_shadow") or (volume_ratio is not None and volume_ratio < 1.0):
                adj -= 4
                cap_adj = min(cap_adj or 99, 58)

        return {"score": int(adj), "cap": cap_adj, "evidence_count": evidence_count}
    except Exception:
        return {"score": 0, "cap": None, "evidence_count": evidence_count}


def _estimate_atr20_pct(price_dict):
    """v247：估算近 20 日平均真實波幅，只用於停損合理性與波動風險，不顯示給客戶。"""
    try:
        raw = price_dict.get("raw") if isinstance(price_dict, dict) else None
        if raw is None or getattr(raw, "empty", True) or len(raw) < 22:
            return None
        df = raw.copy().sort_values("date").reset_index(drop=True)
        high_col = "max" if "max" in df.columns else "high"
        low_col = "min" if "min" in df.columns else "low"
        for c in [high_col, low_col, "close"]:
            df[c] = df[c].apply(to_float)
        prev_close = df["close"].shift(1)
        tr = pd.concat([
            (df[high_col] - df[low_col]).abs(),
            (df[high_col] - prev_close).abs(),
            (df[low_col] - prev_close).abs(),
        ], axis=1).max(axis=1)
        atr = to_float(tr.tail(20).mean())
        close = to_float(df["close"].iloc[-1])
        if atr is None or close is None or close <= 0:
            return None
        return atr / close * 100
    except Exception:
        return None



def _nick_brief_text_from_obj(obj, max_chars=900, _depth=0):
    """v247：把可能來自大盤/族群/雷達的 dict/list/文字壓成短文字，避免把大量資料塞進分數器。"""
    try:
        if obj is None:
            return ""
        if isinstance(obj, str):
            return obj[:max_chars]
        if isinstance(obj, (int, float, bool)):
            return str(obj)
        if _depth >= 2:
            return str(obj)[:max_chars]
        if isinstance(obj, dict):
            parts = []
            preferred = [
                "verdict", "status", "state", "trend", "summary", "conclusion", "stage",
                "flow", "risk", "breadth", "leader", "main", "note", "label", "score",
                "族群", "大盤", "主題", "資金", "外部風險", "市場寬度",
            ]
            for k in preferred:
                if k in obj and obj.get(k) not in [None, ""]:
                    parts.append(f"{k}:{_nick_brief_text_from_obj(obj.get(k), max_chars=160, _depth=_depth+1)}")
            if not parts:
                for k, v in list(obj.items())[:12]:
                    if v not in [None, ""]:
                        parts.append(f"{k}:{_nick_brief_text_from_obj(v, max_chars=120, _depth=_depth+1)}")
            return " ".join(parts)[:max_chars]
        if isinstance(obj, (list, tuple, set)):
            return " ".join([_nick_brief_text_from_obj(x, max_chars=120, _depth=_depth+1) for x in list(obj)[:10]])[:max_chars]
        return str(obj)[:max_chars]
    except Exception:
        return ""


def _collect_market_sector_context_text(a):
    """v247：主動收集大盤/族群背景，讓分數不只看個股。
    有資料才納入；沒有資料不亂猜。
    """
    texts = []
    try:
        for k in [
            "market_state", "market_signal", "market_trend", "market_verdict",
            "market_context", "market_snapshot", "market_breadth", "external_risk",
            "sector_stage", "industry_stage", "theme_stage", "sector_flow", "theme_flow",
            "sector_context", "industry_context", "theme_context", "sector_leader_state",
            "sector_money_flow", "group_strength", "group_context", "market_risk",
        ]:
            v = (a or {}).get(k) if isinstance(a, dict) else None
            if v not in [None, ""]:
                texts.append(_nick_brief_text_from_obj(v, max_chars=500))
    except Exception:
        pass

    # 從 Streamlit session_state 裡補抓大盤/族群更新結果；只取常見鍵，不掃全部，避免誤吃雜訊。
    try:
        ss = getattr(st, "session_state", {})
        keys = [
            "market_snapshot", "market_status", "market_context", "market_trend",
            "market_breadth", "external_risk_snapshot", "external_risk",
            "whole_market_flow", "whole_market_flow_snapshot", "market_flow_snapshot",
            "sector_flow_snapshot", "sector_flow", "sector_context",
            "theme_radar", "theme_context", "industry_flow", "group_flow",
            "latest_market_snapshot", "latest_sector_flow", "news_risk_snapshot",
        ]
        for k in keys:
            if k in ss and ss.get(k) not in [None, ""]:
                texts.append(f"{k}:{_nick_brief_text_from_obj(ss.get(k), max_chars=700)}")
    except Exception:
        pass

    out = " ".join([t for t in texts if t]).strip()
    return out[:5000]


def _market_sector_context_adjustment(a):
    """v247：把大盤/族群背景轉成後台小分數與上限。
    重點：順風加小分，逆風降上限；沒有資料就中性。
    """
    text = _collect_market_sector_context_text(a)
    if not text:
        return {"score": 0, "cap": None, "evidence_count": 0, "text": ""}

    pos_words = [
        "主流", "擴散", "資金流入", "偏多", "順風", "轉強", "升溫", "強勢",
        "站上", "多頭", "領先", "輪動到", "健康", "續強", "風險降低",
    ]
    neg_words = [
        "退潮", "轉弱", "跌破", "空頭", "外部壓力", "風險升高", "資金流出",
        "鈍化", "降溫", "破線", "賣壓", "弱勢", "避險", "不利", "失守",
    ]
    strong_neg = ["跌破 MA60", "跌破60", "系統性風險", "全面退潮", "資金明顯流出", "族群退潮"]
    strong_pos = ["主流擴散", "資金明顯流入", "族群轉強", "大盤偏多", "市場寬度改善"]

    pos = sum(1 for w in pos_words if w in text)
    neg = sum(1 for w in neg_words if w in text)
    score = 0
    cap = None
    if any(w in text for w in strong_neg):
        score -= 5
        cap = 58
    elif any(w in text for w in strong_pos):
        score += 3

    if neg > pos:
        score -= min(5, 2 + (neg - pos))
        cap = min(cap or 99, 62)
    elif pos > neg:
        score += min(4, 1 + (pos - neg))

    return {"score": int(score), "cap": cap, "evidence_count": 1, "text": text}


def _technical_data_quality(price_dict):
    """v247：檢查技術資料可用性。資料不足時不亂加分，且降低證據完整度。"""
    try:
        if not isinstance(price_dict, dict):
            return {"score": 0, "grade": "低", "evidence_count": 0, "has_raw20": False, "has_raw60": False}
        score = 0
        evidence = 0
        raw = price_dict.get("raw")
        if raw is not None and not getattr(raw, "empty", True):
            try:
                n = len(raw)
            except Exception:
                n = 0
            if n >= 20:
                score += 2
                evidence += 1
            if n >= 60:
                score += 2
                evidence += 1
            cols = set(getattr(raw, "columns", []))
            if (("max" in cols or "high" in cols) and ("min" in cols or "low" in cols) and "close" in cols):
                score += 2
                evidence += 1
            if any(c in cols for c in ["volume", "Trading_Volume", "成交量"]):
                score += 1
                evidence += 1
        for k in ["ma20", "ma60", "volume_ratio", "high20", "low20"]:
            if price_dict.get(k) is not None:
                score += 1
                evidence += 1
        if _latest_kd_from_price(price_dict):
            score += 1
            evidence += 1
        if _estimate_atr20_pct(price_dict) is not None:
            score += 1
            evidence += 1
        if score >= 8:
            grade = "高"
        elif score >= 5:
            grade = "中高"
        elif score >= 3:
            grade = "中"
        else:
            grade = "低"
        return {
            "score": int(score),
            "grade": grade,
            "evidence_count": int(evidence),
            "has_raw20": bool(raw is not None and not getattr(raw, "empty", True) and len(raw) >= 20),
            "has_raw60": bool(raw is not None and not getattr(raw, "empty", True) and len(raw) >= 60),
        }
    except Exception:
        return {"score": 0, "grade": "低", "evidence_count": 0, "has_raw20": False, "has_raw60": False}



def _advanced_trade_evidence_adjustment(price_dict, a, scenario_type, entry, stop_p, wave_p):
    """v247：籌碼、族群/大盤、波動率、目標可信度、失效清楚度後台化。
    前台不顯示公式，只影響條件分數、分數上限與最後適合動作。
    """
    adj = 0
    cap_adj = None
    evidence_count = 0
    try:
        if not isinstance(a, dict):
            return {"score": 0, "cap": None, "evidence_count": 0}

        close = to_float(price_dict.get("close")) if isinstance(price_dict, dict) else None
        high20 = to_float(price_dict.get("high20")) or to_float(price_dict.get("prev_high20")) if isinstance(price_dict, dict) else None
        ret20 = to_float(price_dict.get("ret20")) if isinstance(price_dict, dict) else None
        volume_ratio = to_float(price_dict.get("volume_ratio")) if isinstance(price_dict, dict) else None
        drawdown20 = to_float(price_dict.get("drawdown20")) if isinstance(price_dict, dict) else None
        core = str(a.get("core", ""))
        attack = str(a.get("attack", ""))
        focus = str(a.get("focus", ""))
        trend_status = str((a.get("trend") or {}).get("status", ""))
        chip_j = a.get("chip_j") or {}
        diag = a.get("_diag") or {}

        # 1) 籌碼結構：不只看三大法人加總，還要看是否偏出貨/分歧/乾淨吃貨。
        chip_score = to_float(chip_j.get("score"))
        chip_text = " ".join([
            str(chip_j.get("status", "")),
            str(chip_j.get("text", "")),
            str(chip_j.get("summary", "")),
            str(diag.get("chip_pressure_type", "")),
            str(diag.get("atk_chip_health_status", "")),
            str(diag.get("chip_accumulation_type", "")),
        ])
        if chip_score is not None or chip_text.strip():
            evidence_count += 1
            if chip_score is not None:
                if chip_score >= 3:
                    adj += 3
                elif chip_score <= -3:
                    adj -= 5
                    cap_adj = min(cap_adj or 99, 62)
            if any(k in chip_text for k in ["出貨", "倒貨", "籌碼轉弱", "法人續賣"]):
                adj -= 7
                cap_adj = min(cap_adj or 99, 45 if scenario_type == "current" else 55)
            elif "籌碼分歧" in chip_text or "非全面同向" in chip_text:
                adj -= 3
            elif any(k in chip_text for k in ["乾淨吃貨", "財報型 Core 吃貨", "明顯吃貨"]):
                adj += 3
            elif "外資主導" in chip_text or "短中線吃貨" in chip_text:
                adj += 1

        # 2) 族群 / 大盤狀態：v247 會主動從 a 與 session_state 補抓背景資料。
        _mkt_adj = _market_sector_context_adjustment(a)
        if _mkt_adj.get("evidence_count"):
            evidence_count += int(_mkt_adj.get("evidence_count") or 0)
            adj += int(_mkt_adj.get("score") or 0)
            if _mkt_adj.get("cap") is not None:
                cap_adj = min(cap_adj or 99, int(_mkt_adj.get("cap")))

        # 3) 波動率 / 停損合理性：避免停損太近被正常震盪洗掉，或停損太遠不值得。
        atr20_pct = _estimate_atr20_pct(price_dict) if isinstance(price_dict, dict) else None
        if entry is not None and stop_p is not None and entry > 0 and stop_p > 0 and stop_p < entry:
            evidence_count += 1
            stop_gap_pct = (entry - stop_p) / entry * 100
            if atr20_pct is not None:
                evidence_count += 1
                if stop_gap_pct < atr20_pct * 0.75:
                    adj -= 4
                    cap_adj = min(cap_adj or 99, 58)
                elif atr20_pct * 1.0 <= stop_gap_pct <= max(atr20_pct * 2.8, 8):
                    adj += 2
            if stop_gap_pct < 2:
                adj -= 3
            elif stop_gap_pct > 15:
                adj -= 4
                cap_adj = min(cap_adj or 99, 62)
            elif 3 <= stop_gap_pct <= 12:
                adj += 1
        elif entry is not None and stop_p is not None:
            adj -= 5
            cap_adj = min(cap_adj or 99, 50)

        # 4) 目標價可信度：風報比有利不代表目標一定可信。
        if entry is not None and wave_p is not None and entry > 0 and wave_p > 0:
            evidence_count += 1
            upside_pct = (wave_p - entry) / entry * 100
            rerating_v = str((a.get("rerating") or {}).get("verdict", ""))
            val_zone = str(a.get("valuation_zone", ""))
            if upside_pct <= 0:
                adj -= 8
                cap_adj = min(cap_adj or 99, 50)
            elif upside_pct >= 35 and rerating_v != "成立":
                adj -= 5
                cap_adj = min(cap_adj or 99, 60)
            elif upside_pct >= 45:
                adj -= 6
                cap_adj = min(cap_adj or 99, 62)
            elif high20 is not None and wave_p <= high20 * 1.08:
                adj += 2
            elif "重評" in val_zone or rerating_v == "成立":
                adj += 1

        # 5) Core 股遇到交易面轉弱：公司可收編，但現價不能因此變高分。
        if core == "Yes" and attack != "Yes" and scenario_type == "current":
            if any(k in chip_text for k in ["出貨", "倒貨", "法人續賣", "籌碼轉弱"]) or trend_status in ("趨勢轉弱", "趨勢反轉"):
                adj -= 6
                cap_adj = min(cap_adj or 99, 38 if focus != "Yes" else 50)

        # 6) 題材過熱 / 追價風險：短線漲太快、量能放太大，不因情緒拉高分數。
        if scenario_type in ("current", "breakout"):
            if ret20 is not None and ret20 >= 25:
                adj -= 4
                cap_adj = min(cap_adj or 99, 64)
            if volume_ratio is not None and volume_ratio >= 2.2 and drawdown20 is not None and drawdown20 > -3:
                adj -= 3

        # 7) 技術資料完整度：資料完整才讓技術分數有信心；資料不足不亂給高分。
        _tech_quality = _technical_data_quality(price_dict)
        evidence_count += min(3, int(_tech_quality.get("evidence_count") or 0))
        if scenario_type in ("current", "breakout", "pullback") and _tech_quality.get("grade") == "低":
            adj -= 2
            cap_adj = min(cap_adj or 99, 62)
        elif _tech_quality.get("grade") in ("高", "中高"):
            adj += 1

        return {"score": int(adj), "cap": cap_adj, "evidence_count": evidence_count}
    except Exception:
        return {"score": 0, "cap": None, "evidence_count": evidence_count}


def calc_future_win_one(label, entry, price_dict, a, scenario_type="current"):
    """
    情境式條件勝率計算。
    scenario_type: "current" | "pullback" | "new_zone" | "breakout" | "holding"
    勝率分級：>=80 高 / 70-79 中高 / 60-69 普通 / 50-59 偏低 / <50 低
    """
    close = price_dict.get("close") if price_dict else None
    nums = a["plan"].get("num", {}) if a.get("plan") else {}
    stop_p = nums.get("stop")
    short_p = nums.get("short")
    wave_p = nums.get("wave")

    if entry is None or close is None or stop_p is None or wave_p is None:
        return {
            "情境": label,
            "進場區": "資料不足",
            "停損": "—",
            "目標": "—",
            "條件分數": "—",
            "證據完整度": "低",
            "20日區間": "—",
            "40日區間": "—",
            "適合動作": "先觀察",
            "一句話": "資料不足，暫不給高分",
        }

    fj = a["fin_j"]
    rr_d = a["rerating"]
    trend = a["trend"]
    cj = a["chip_j"]
    core = a["core"]
    attack = a["attack"]
    attack_type = a.get("attack_type", "無")
    focus = a["focus"]
    action = a.get("action", "")
    zone = a.get("valuation_zone", "")

    rr_val = calc_rr(entry, stop_p, wave_p)
    rr_str = f"{rr_val:.1f}" if rr_val is not None else "資料不足"
    rr_num = rr_val if rr_val is not None else 0
    invalid_stop_structure = False
    invalid_target_structure = False
    try:
        invalid_stop_structure = entry is not None and stop_p is not None and stop_p >= entry
        invalid_target_structure = entry is not None and wave_p is not None and wave_p <= entry
    except Exception:
        invalid_stop_structure = False
        invalid_target_structure = False

    # ── 基礎分與 Core / Attack / Focus 天花板 ─────────────
    if core == "Yes" and focus == "Yes":
        base, cap = 76, 85
    elif core == "Yes" and attack == "Yes" and attack_type.startswith("回檔型"):
        base, cap = 70, 82
    elif core == "Yes" and attack == "Yes":
        base, cap = 66, 78
    elif core == "Yes":
        base, cap = 57, 65
    elif attack == "Yes":
        base, cap = 51, 60
    else:
        base, cap = 44, 55

    score = base

    # ── 財報品質 ─────────────────────────────────────────
    fin_report = fj.get("report", "")
    if fin_report == "通過":
        score += 4
    elif fin_report == "部分通過":
        score += 1
    elif fin_report == "不通過":
        score -= 8
        cap = min(cap, 52)

    if fj.get("financial_quality") == "高":
        score += 2
    elif fj.get("financial_quality") == "低":
        score -= 5

    if fj.get("growth_quality") == "通過":
        score += 2
    elif fj.get("growth_quality") == "不通過":
        score -= 4

    # ── 估值重評 ─────────────────────────────────────────
    if rr_d.get("verdict") == "成立":
        score += 2
    elif rr_d.get("verdict") == "不成立":
        score -= 3

    # ── 趨勢 ─────────────────────────────────────────────
    t_status = trend.get("status", "")
    if t_status == "趨勢轉強":
        score += 4
    elif t_status == "正常回測":
        score += 3
    elif t_status == "盤整觀察":
        pass
    elif t_status == "趨勢鈍化":
        score -= 3
    elif t_status == "趨勢轉弱":
        score -= 7
        cap = min(cap, 62)
    elif t_status == "趨勢反轉":
        score -= 12
        cap = min(cap, 50)

    # ── 籌碼 ─────────────────────────────────────────────
    chip_sc = cj.get("score", 0) if cj.get("score") is not None else 0
    score += clamp(int(chip_sc * 1.5), -5, 5)

    # ── 估值區間 ─────────────────────────────────────────
    _zone_good = ["低估", "偏低估", "合理", "中性 / 基本面支撐區", "保守區"]
    _zone_bad = ["偏貴 / 已提前反映未來", "高溢價區", "明顯跑太前面", "高於市場溢價區"]
    if any(z in zone for z in _zone_good):
        score += 3
    elif any(z in zone for z in _zone_bad):
        score -= 8
        cap = min(cap, 65)
    elif zone in ("資料不足", "區間外"):
        cap = min(cap, 55)

    # ── 風報比 ───────────────────────────────────────────
    if rr_num >= 2.5:
        score += 5
    elif rr_num >= 2.0:
        score += 3
    elif rr_num >= 1.5:
        pass
    elif rr_num >= 1.2:
        score -= 5
        cap = min(cap, 65)
    elif rr_num > 0:
        score -= 10
        cap = min(cap, 55)
    else:
        cap = min(cap, 50)

    # ── 進場價 vs 現價（情境調整）────────────────────────
    try:
        r = entry / close
        if scenario_type == "current":
            if r > 1.03:
                score -= 5
        elif scenario_type == "pullback":
            if r <= 0.97:
                score += 5
            elif r <= 0.99:
                score += 3
        elif scenario_type == "new_zone":
            if r <= 0.93:
                score += 7
            elif r <= 0.97:
                score += 4
        elif scenario_type == "breakout":
            if r > 1.04:
                score -= 6
    except (ZeroDivisionError, TypeError):
        pass

    # ── 回檔型 / 突破型 Attack 情境加分 ──────────────────
    if attack_type.startswith("回檔型") and scenario_type in ("pullback", "new_zone"):
        score += 4
    elif attack_type.startswith("突破型") and scenario_type == "breakout":
        score += 4
    elif attack_type.startswith("突破型") and scenario_type == "current":
        score += 2

    # ── v247 技術證據後台化：均線扣抵 / KD / K棒 / 量價 / 支撐壓力 ─────────
    _tech_adj = _technical_evidence_adjustment(price_dict, a, scenario_type, entry, stop_p, wave_p)
    score += int(_tech_adj.get("score") or 0)
    if _tech_adj.get("cap") is not None:
        cap = min(cap, int(_tech_adj.get("cap")))

    # ── v247 交易環境證據後台化：籌碼 / 族群大盤 / 波動 / 目標可信度 / 失效點 ──
    _adv_adj = _advanced_trade_evidence_adjustment(price_dict, a, scenario_type, entry, stop_p, wave_p)
    score += int(_adv_adj.get("score") or 0)
    if _adv_adj.get("cap") is not None:
        cap = min(cap, int(_adv_adj.get("cap")))

    # ── 停損 / 目標結構防呆：試算本身不合理，就不能硬給高分 ─────────
    if invalid_stop_structure:
        score -= 22
        cap = min(cap, 35)
    if invalid_target_structure:
        score -= 18
        cap = min(cap, 40)

    # ── Action 一致性上限 ────────────────────────────────
    if "不買" in action:
        cap = min(cap, 45)
    elif "只觀察" in action:
        cap = min(cap, 55)
    elif ("等回檔" in action or "不追高" in action) and scenario_type == "current":
        cap = min(cap, 65)
    elif "右側小倉" in action and scenario_type not in ("breakout",):
        cap = min(cap, 62)
    elif "小倉試單" in action and scenario_type == "current":
        cap = min(cap, 60)

    # ── 模型校正狀態影響 ─────────────────────────────────
    val_auto = a.get("val_auto", {})
    if val_auto.get("model_confidence") == "低" and val_auto.get("anomalies"):
        cap = min(cap, 65)
        score -= 3

    # ── 最終條件分數：20 日偏交易面；40 日偏波段基本面續航 ─────────
    cap20 = cap
    cap40 = cap

    # 40 日不只是複製 20 日：財報 / 估值 / Core 會提高波段續航；短線長黑只限制 20 日較多。
    score40 = score
    if core == "Yes" and fin_report == "通過":
        score40 += 5
        cap40 = max(cap40, 68)
    elif fin_report == "部分通過":
        score40 -= 2
    elif fin_report == "不通過":
        score40 -= 8
        cap40 = min(cap40, 50)

    if fj.get("growth_quality") == "通過":
        score40 += 2
    elif fj.get("growth_quality") == "不通過":
        score40 -= 3

    if rr_d.get("verdict") == "成立":
        score40 += 3
        cap40 = max(cap40, 66)
    elif rr_d.get("verdict") == "不成立":
        score40 -= 4
        cap40 = min(cap40, 58)

    if attack == "Yes" and core == "No":
        score40 -= 5
        cap40 = min(cap40, 55)

    if t_status in ("趨勢轉弱", "趨勢反轉"):
        # 20 日要重扣；40 日若 Core/財報通過，不直接歸零，但仍扣分。
        score40 += 2 if (core == "Yes" and fin_report == "通過") else -2
        if not (core == "Yes" and fin_report == "通過"):
            cap40 = min(cap40, 58)

    if scenario_type in ("pullback", "new_zone") and core == "Yes" and fin_report == "通過":
        score40 += 3
    if scenario_type == "breakout" and rr_d.get("verdict") != "成立":
        score40 -= 3

    # Action 仍要尊重：不買就是不買；但「只觀察」若是 Core 財報股，40 日可保留觀察價值。
    if "不買" in action:
        cap40 = min(cap40, 45)
    elif "只觀察" in action and not (core == "Yes" and fin_report == "通過"):
        cap40 = min(cap40, 55)
    elif ("等回檔" in action or "不追高" in action) and scenario_type == "current":
        cap40 = min(cap40, 60 if core == "Yes" and fin_report == "通過" else 55)

    if invalid_stop_structure:
        score40 -= 18
        cap40 = min(cap40, 35)
    if invalid_target_structure:
        score40 -= 16
        cap40 = min(cap40, 40)

    win20 = clamp(round(score), 25, cap20)
    win40 = clamp(round(score40), 25, cap40)

    evidence_grade = _evidence_grade_from_context(price_dict, a, rr_val)
    _extra_evidence = int((_tech_adj.get("evidence_count") or 0) + (_adv_adj.get("evidence_count") or 0))
    if evidence_grade == "低" and _extra_evidence >= 4:
        evidence_grade = "中"
    elif evidence_grade == "中" and _extra_evidence >= 6:
        evidence_grade = "中高"
    elif evidence_grade == "中高" and _extra_evidence >= 9:
        evidence_grade = "高"
    win20_range = _win_range_text(win20, evidence_grade, cap20)
    win40_range = _win_range_text(win40, evidence_grade, cap40)

    action_text = _scenario_action_text(win20, scenario_type, action, rr_val)
    if invalid_stop_structure or invalid_target_structure:
        action_text = "先不買"
        conclusion = "結構異常｜停損或目標需人工確認"
    else:
        conclusion = f"{_win_label(win20)}｜{_win_conclusion(win20)}"

    target_text = f"短 {fmt_price(short_p)}｜波 {fmt_price(wave_p)}"

    return {
        "情境": label,
        "進場區": fmt_price(entry),
        "停損": fmt_price(stop_p),
        "短線失效": (a.get("plan", {}) or {}).get("wrong") or fmt_price(stop_p),
        "波段防守": (a.get("plan", {}) or {}).get("stop") or fmt_price(stop_p),
        "目標": target_text,
        "條件分數": f"{win20}/100",
        "證據完整度": evidence_grade,
        "20日區間": win20_range,
        "40日區間": win40_range,
        "適合動作": action_text,
        "一句話": conclusion,
    }


def build_future_win_rows(price, a, holding_cost=None):
    nums = a["plan"].get("num", {}) if a.get("plan") else {}
    new_label = a["plan"].get("new_label", "新倉主區") if a.get("plan") else "新倉主區"
    close, _ref_label = _reference_buy_price(price)
    price_for_win = dict(price) if isinstance(price, dict) else price
    if isinstance(price_for_win, dict) and close is not None:
        price_for_win["close"] = close
    attack_type = a.get("attack_type", "無")
    action = a.get("action", "")
    rows = []

    rows.append(calc_future_win_one("現價買", close, price_for_win, a, scenario_type="current"))
    rows.append(
        calc_future_win_one(
            "淺回檔買", nums.get("shallow_high"), price_for_win, a, scenario_type="pullback"
        )
    )
    rows.append(
        calc_future_win_one(
            f"{new_label}買", nums.get("new_high"), price_for_win, a, scenario_type="new_zone"
        )
    )

    if attack_type.startswith("突破型") or "右側" in action:
        rows.append(
            calc_future_win_one(
                "右側突破追價", nums.get("right"), price_for_win, a, scenario_type="breakout"
            )
        )

    if holding_cost is not None and holding_cost > 0:
        rows.append(
            calc_future_win_one(
                "持股續抱", holding_cost, price_for_win, a, scenario_type="holding"
            )
        )

    return rows


