def _fmt_signed_pct(x):
    """格式化正負百分比，給買點距離用。"""
    x = to_float(x)
    if x is None:
        return "—"
    sign = "+" if x > 0 else ""
    return f"{sign}{x:.1f}%"


def _reference_buy_price(price):
    """買點距離與買點區間判斷用價格。

    V8.5.3：
    - 盤中優先使用即時股價，比較貼近當下位置。
    - 沒有即時股價時，才退回收盤價。
    """
    if isinstance(price, dict):
        for k in ["realtime_price", "live_price", "current_price", "intraday_price"]:
            v = to_float(price.get(k))
            if v is not None and v > 0:
                return v, "即時價"
        v = to_float(price.get("close"))
        if v is not None and v > 0:
            return v, "收盤價"
    return None, "資料不足"


def _buy_zone_distance_text(price, a):
    """計算目前參考價距離波段買點區間的百分比。

    規則：
    - 參考價高於買點上緣：正數，代表買點上方。
    - 參考價低於買點下緣：負數，代表尚未站進買點區。
    - 參考價在買點區間內：顯示「已在買點區內」，不再顯示 0.0%。
    """
    close, ref_label = _reference_buy_price(price)
    plan = a.get("plan", {}) if isinstance(a, dict) else {}
    nums = plan.get("num", {}) if isinstance(plan, dict) else {}

    low = to_float(nums.get("new_low"))
    high = to_float(nums.get("new_high"))

    if close is None or low is None or high is None or low <= 0 or high <= 0:
        return ""

    low, high = min(low, high), max(low, high)

    if close > high:
        dist = (close / high - 1) * 100
        return f"距離買點約 {_fmt_signed_pct(dist)}"
    elif close < low:
        dist = (close / low - 1) * 100
        return f"距離買點約 {_fmt_signed_pct(dist)}"
    else:
        return "已在買點區內"


def display_attack_type(attack_type, price=None, a=None):
    s = str(attack_type or "無")
    # v24｜短線機會客戶版：先處理籌碼分歧 / 健康調節 / 出貨型賣壓，避免外資調節被誤寫成出貨。
    try:
        _a = a if isinstance(a, dict) else {}
        _mk = str(((_a.get("val") or {}).get("model_key")) or "")
        _atk = str(_a.get("attack", "") or "")
        _act = str(_a.get("action", "") or "")
        _d = _a.get("_diag", {}) or {}
        _chip_type = str(_d.get("chip_pressure_type") or _d.get("atk_chip_health_status") or "")
        _pullback_candidate = bool(_d.get("atk_pullback_window_candidate"))
        _breakout_candidate = "突破候選" in s or bool(_d.get("atk_near_breakout"))
        _main_up = (_a.get("main_up_attack") or {}) if isinstance(_a.get("main_up_attack"), dict) else {}
        if _main_up.get("active"):
            return "主升攻擊｜不追高"
        if _atk != "Yes":
            if "出貨型" in _chip_type:
                return "No｜出貨型賣壓"
            if "籌碼分歧" in _chip_type:
                return "支撐觀察｜籌碼分歧"
            if "籌碼轉弱" in _chip_type:
                return "籌碼轉弱｜等站回"
            if _pullback_candidate:
                return "回檔候選｜等站回"
            if _breakout_candidate:
                return "突破候選｜等確認"
        if _mk == "panel_turnaround_rerating" and _atk == "Yes":
            return "已發動，不追高"
        if _atk == "Yes" and ("攻擊觀察" in _act or "不追高" in _act):
            return "攻擊觀察，不追高"
        if _atk != "Yes" and ("觀察型小倉" in _act or "試單" in _act):
            return "觀察型小倉，等確認"
    except Exception:
        pass
    if "主升攻擊" in s:
        return "主升攻擊｜不追高"
    if "ABF" in s or "BT 載板" in s:
        return "ABF / BT 載板｜回檔 / 右側"
    if "AI 高階 PCB" in s:
        return "AI 高階 PCB｜回檔 / 右側"
    if "PCB 耗材" in s or "鑽針" in s:
        return "PCB 耗材｜等確認"
    if "一般 PCB" in s:
        return "一般 PCB｜等確認"
    if "材料循環" in s:
        return "材料循環候選｜若已突破，等回測"
    if "記憶體" in s:
        return "記憶體循環｜等確認"
    if "運價反彈" in s:
        return "航運反彈候選｜等回檔"
    if "金融資產型" in s:
        return "金融資產型｜等回檔"
    if "證券循環" in s:
        return "證券循環｜等確認"
    if "防守型" in s:
        return "防守型｜非攻擊倉"
    if "觀察型小倉" in s:
        return "觀察型小倉｜等確認"
    if "高階 CCL" in s:
        return "高階 CCL｜回檔 / 右側"
    if "突破候選" in s:
        return "壓力前候選｜等回檔"
    if "候選" in s:
        return "回檔候選｜等觸發"
    if s.startswith("回檔型"):
        dist_text = _buy_zone_distance_text(price, a) if price is not None and isinstance(a, dict) else ""
        # v191｜無法計算距離時，不要顯示「距離買點約 —」，避免使用者誤會資料壞掉。
        return f"回檔型｜{dist_text}" if dist_text else "回檔型｜等買點確認"
    if s.startswith("突破型｜已觸發"):
        return "已過壓力｜等回檔"
    if s.startswith("突破型"):
        return "壓力前候選｜等回檔"
    if "出貨型" in s:
        return "No｜出貨型賣壓"
    return "無"


def display_focus_state(a):
    focus = a.get("focus", "No")
    holding_focus = a.get("holding_focus", focus)
    new_focus = a.get("new_focus", focus)
    core = a.get("core", "No")
    attack = a.get("attack", "No")
    reasons = a.get("focus_block_reasons", []) or []
    if holding_focus == "Yes" and new_focus != "Yes":
        return "持股 Focus｜新倉等回檔", "低成本持有可續抱；空手新倉不追主倉"
    if focus == "Yes":
        return "優先觀察", "未來一週值得優先盯買點"
    try:
        _mu = (a.get("main_up_attack") or {}) if isinstance(a.get("main_up_attack"), dict) else {}
        if core == "Yes" and _mu.get("active"):
            return "主攻候選｜等買點", "主升已發動，但新倉不追高，等回測 / 回檔"
    except Exception:
        pass
    if core == "Yes" and attack == "Yes":
        return "候選｜等買點", "公司與攻擊條件接近，但仍有卡關項目"
    if core == "Yes":
        return "公司可收編｜等攻擊", "公司不差，但短線機會還沒進入觀察區"
    if attack == "Yes":
        return "短線觀察", "有短線攻擊味，但公司尚未正式收編"
    if reasons:
        return "先觀察", "、".join(reasons[:2])
    return "先觀察", "條件尚未完整"


