def evaluate_data_quality(status_df, price, rev, inst, fin, bal, cf, stock_info_err=""):
    issues = []
    ok_count = 0
    total = 7
    if stock_info_err:
        issues.append("股票基本資料不足，產業模型可能需保守看待")
    else:
        ok_count += 1
    for label, obj in [
        ("股價", price),
        ("月營收", rev),
        ("法人近 20 日", inst),
        ("財報", fin),
        ("資產負債表", bal),
        ("現金流量表", cf),
    ]:
        if obj:
            ok_count += 1
        else:
            issues.append(f"{label}資料不足")
    if inst and inst.get("positive_days_20") is None:
        issues.append("法人近 20 日資料可能不完整")
    if fin and fin.get("eps_cumulative_suspect"):
        issues.append("EPS 可能為累計值型態，估值需保守")
    ratio = ok_count / total
    if ratio >= 0.85 and not issues:
        grade = "高"
        msg = "資料完整度高，可參考主要裁決。"
    elif ratio >= 0.60:
        grade = "中"
        msg = "資料大致可用，但部分欄位需保守解讀。"
    else:
        grade = "低"
        msg = "資料缺漏較多，避免只靠本次結果做決策。"
    return {"grade": grade, "message": msg, "issues": issues[:5], "ok_count": ok_count, "total": total}


def judge_pullback_quality(price, a, inst=None):
    if not price:
        return {"status": "資料不足", "reasons": ["股價資料不足"], "tip": "先不要硬判斷。"}
    close = price.get("close")
    ma20 = price.get("ma20")
    ma60 = price.get("ma60")
    drawdown20 = price.get("drawdown20")
    volume_ratio = price.get("volume_ratio")
    ret5 = price.get("ret5")
    ret20 = price.get("ret20")
    trend = a.get("trend", {}).get("status", "")
    diag = a.get("_diag", {})
    chip_status = diag.get("atk_chip_health_status", "")
    ma60_ok = close is not None and ma60 is not None and close >= ma60 * 0.96
    near_ma20 = close is not None and ma20 is not None and close <= ma20 * 1.08
    pullback_range = drawdown20 is not None and -18 <= drawdown20 <= -2
    panic_volume = (
        volume_ratio is not None
        and volume_ratio >= 1.8
        and ((ret5 is not None and ret5 <= -3) or (ret20 is not None and ret20 <= -7))
    )
    reasons = []
    if ma60_ok:
        reasons.append("仍在 MA60 容忍區內")
    else:
        reasons.append("跌破 MA60 容忍區")
    if pullback_range:
        reasons.append("回檔幅度在合理區")
    if near_ma20:
        reasons.append("接近 MA20 / 支撐觀察區")
    if panic_volume:
        reasons.append("量能有放大下跌風險")
    else:
        reasons.append("量能未見失控下殺")
    if "出貨" in str(chip_status):
        reasons.append("籌碼偏出貨型賣壓")
    else:
        reasons.append("籌碼偏健康調節")
    if trend in ["趨勢轉弱", "趨勢反轉"]:
        status = "轉弱回檔"
        tip = "不要急著接，等重新站回關鍵均線。"
    elif ma60_ok and pullback_range and not panic_volume and "出貨" not in str(chip_status):
        status = "健康回檔"
        tip = "可觀察支撐附近的分批機會，但仍要守失效點。"
    elif ma60_ok and not panic_volume:
        status = "普通回檔"
        tip = "可觀察，等更接近支撐或買點品質提高。"
    else:
        status = "非回檔買點"
        tip = "目前不是漂亮回檔買點，避免誤判。"
    return {"status": status, "reasons": reasons[:4], "tip": tip}


def _pct_from_win_text(x):
    if x is None:
        return None
    s = str(x).replace("%", "").replace("～", "-").replace("—", "-").strip()
    nums = re.findall(r"\d+(?:\.\d+)?", s)
    if not nums:
        return None
    try:
        vals = [float(n) for n in nums[:2]]
        return int(round(sum(vals) / len(vals)))
    except Exception:
        return None


def _buy_zone_score_label(score):
    if score >= 80:
        return "高"
    if score >= 70:
        return "中高"
    if score >= 60:
        return "中"
    if score >= 50:
        return "普通"
    return "低"


def _buy_zone_context(label, entry, close, price, a):
    """把買點分成：低接、站回確認、突破確認，避免把高於現價的確認價誤叫低接買點。"""
    label_s = str(label or "")
    ma20 = price.get("ma20") if price else None
    ma60 = price.get("ma60") if price else None
    low10 = price.get("low10") if price else None
    attack_type = str(a.get("attack_type", "")) if isinstance(a, dict) else ""

    if close is None or entry is None:
        return {
            "context": "資料不足",
            "price_sweet": "—",
            "confirm": "—",
            "judge": "資料不足",
            "note": "買點資料不足，先不要硬判斷。",
        }

    # 價格甜度：越靠近支撐 / 越低於確認區，甜度較高，但不代表安全。
    try:
        ratio = entry / close
    except Exception:
        ratio = 1

    near_ma60 = ma60 is not None and close >= ma60 * 0.96 and close <= ma60 * 1.06
    near_ma20 = ma20 is not None and close <= ma20 * 1.05
    near_low10 = low10 is not None and close <= low10 * 1.05

    if "現價" in label_s:
        if near_ma60 or near_low10:
            context = "支撐低接觀察"
            price_sweet = "高"
            confirm = "低"
            judge = "便宜但未修復"
            note = "靠近支撐可觀察，但只適合小倉，不能當已轉強。"
        elif near_ma20:
            context = "短線回測觀察"
            price_sweet = "中"
            confirm = "中低"
            judge = "普通，等確認"
            note = "現價不算差，但仍要看能否站回關鍵均線。"
        else:
            context = "現價觀察"
            price_sweet = "普通"
            confirm = "低"
            judge = "可追蹤，不急買"
            note = "現價缺少明確支撐或轉強確認，不急著出手。"
    elif "淺回檔" in label_s or "支撐" in label_s:
        if entry > close * 1.02:
            context = "站回短線確認"
            price_sweet = "普通"
            confirm = "中高"
            judge = "不是低接，是修復點"
            note = "價格比現價高，代表要先站回才算短線修復。"
        else:
            context = "支撐低接區"
            price_sweet = "中高" if ratio <= 1.00 else "中"
            confirm = "中"
            judge = "可小倉觀察"
            note = "接近支撐才分批，跌破失效點要先降風險。"
    elif "反彈" in label_s or "站回" in label_s or "確認" in label_s or "新倉" in label_s:
        if entry > close * 1.02:
            context = "站回確認區"
            price_sweet = "普通"
            confirm = "高"
            judge = "比較安全，不是比較便宜"
            note = "這是短線修復價；站回後勝率提高，但不能解讀成低接漂亮價。"
        else:
            context = "新倉主區"
            price_sweet = "中高"
            confirm = "中"
            judge = "可分批觀察"
            note = "位置接近主區，可搭配量能與停損分批。"
    elif "突破" in label_s or "右側" in label_s:
        context = "突破確認區"
        price_sweet = "低" if entry > close * 1.05 else "普通"
        confirm = "高"
        judge = "等突破確認"
        note = "突破價不是便宜買點，必須搭配量能升溫與隔日不跌回。"
    elif "持股" in label_s:
        context = "持股檢查"
        price_sweet = "—"
        confirm = "—"
        judge = "看移動停利"
        note = "持股以波段是否破壞與移動停利為主。"
    else:
        context = "觀察買點"
        price_sweet = "普通"
        confirm = "普通"
        judge = "等條件完整"
        note = "先追蹤位置、量能與籌碼是否同步。"

    # 回檔型可提高低接區的可看性，但不能把確認價誤判成低接。
    if attack_type.startswith("回檔型") and context == "支撐低接區":
        note = "回檔型機會接近支撐，可小倉分批，但仍要守認錯點。"

    return {
        "context": context,
        "price_sweet": price_sweet,
        "confirm": confirm,
        "judge": judge,
        "note": note,
    }


def build_buy_point_quality(price, a, holding_cost=None):
    rows = []
    fw_rows = build_future_win_rows(price, a, holding_cost)
    action = str(a.get("action", ""))
    close = price.get("close") if price else None

    for r in fw_rows:
        win = _pct_from_win_text(r.get("20日區間") or r.get("20日勝率"))
        rr = None
        entry = to_float(r.get("進場區") or r.get("進場價"))
        score = win if win is not None else 50

        if rr is not None:
            if rr >= 2.5:
                score += 5
            elif rr < 1.2:
                score -= 10
            elif rr < 1.5:
                score -= 5

        label = r.get("情境", "")
        ctx = _buy_zone_context(label, entry, close, price, a)

        # 現價若被策略判為等回檔/不追，分數上限不能太高。
        if "現價" in label and ("等回檔" in action or "不追" in action):
            score = min(score, 65)

        # 如果價格比現價高，且屬於站回/突破確認，不再用「漂亮買點」語氣。
        if entry is not None and close is not None and entry > close * 1.02:
            if ctx["context"] in ["站回短線確認", "站回確認區", "突破確認區"]:
                score = min(score + 2, 88)

        # 支撐低接區可看，但只適合分批，不直接視為主倉漂亮價。
        if ctx["context"] == "支撐低接區" and a.get("attack_type", "").startswith("回檔型"):
            score += 3

        score = int(clamp(round(score), 0, 100))
        rows.append({
            "買點情境": ctx["context"],
            "價格": r.get("進場區", r.get("進場價", "—")),
            "甜度": ctx["price_sweet"],
            "買點把握": f"{ctx['confirm']}｜{score}分" if ctx["confirm"] != "—" else f"{score}分",
            "品質分數": score,
            "一句話": ctx["note"],
        })
    return rows


def _buy_point_grip_class(grip_text):
    """買點把握顏色：高/80分以上偏紅，中偏黃，低偏綠，符合台股上紅下綠視覺。"""
    s = str(grip_text or "")
    score = None
    m = re.search(r"(\d+)分", s)
    if m:
        try:
            score = int(m.group(1))
        except Exception:
            score = None
    if "高" in s or (score is not None and score >= 80):
        return "good"
    if "中" in s or (score is not None and score >= 65):
        return "mid"
    return "bad"


def render_buy_point_table(rows):
    """手機版精簡表：欄位依內容大小呈現，避免 dataframe 欄位撐太寬。"""
    if not rows:
        st.info("買點資料不足，暫不評分。")
        return
    cols = ["買點情境", "價格", "甜度", "買點把握", "一句話"]
    html_rows = []
    for r in rows:
        cells = []
        for c in cols:
            val = _html.escape(str(r.get(c, "—")))
            cls = ""
            if c == "價格":
                cls = ' class="num"'
            elif c == "買點把握":
                cls = f' class="{_buy_point_grip_class(r.get(c))}"'
            cells.append(f"<td{cls}>{val}</td>")
        html_rows.append("<tr>" + "".join(cells) + "</tr>")
    header = "".join([f"<th>{_html.escape(c)}</th>" for c in cols])
    st.markdown(
        '<div class="compact-table-wrap"><table class="compact-table">'
        f"<thead><tr>{header}</tr></thead><tbody>"
        + "".join(html_rows)
        + "</tbody></table></div>",
        unsafe_allow_html=True,
    )

def render_future_win_cards(rows):
    """v247：買點情境改成手機卡片，不再用橫向 dataframe。"""
    if not rows:
        st.info("買點情境資料不足，暫不評分。")
        return

    def _field(_r, *keys, default="—"):
        for _k in keys:
            _v = _r.get(_k)
            if _v not in [None, ""]:
                return str(_v)
        return default

    for r in rows:
        title = _html.escape(_field(r, "情境", default="買點情境"))
        action_txt = _html.escape(_field(r, "適合動作", default="觀察"))
        score_txt = _html.escape(_field(r, "條件分數", default="—"))
        ev_txt = _html.escape(_field(r, "證據完整度", default="—"))
        w20 = _html.escape(_field(r, "20日區間", "20日勝率", default="—"))
        w40 = _html.escape(_field(r, "40日區間", "40日勝率", default="—"))
        entry = _html.escape(_field(r, "進場區", "進場價", default="—"))
        stop = _html.escape(_field(r, "停損", default="—"))
        short_fail = _html.escape(_field(r, "短線失效", "追錯失效", "短線防守", default=stop))
        wave_defense = _html.escape(_field(r, "波段防守", "波段失效", default=stop))
        target = _html.escape(_field(r, "目標", default="—"))
        if target == "—":
            target = _html.escape(f"短 {_field(r, '短線目標')}｜波 {_field(r, '波段目標')}")
        note = _html.escape(_field(r, "一句話", "結論", default="—"))

        st.markdown(
            f"""
<div style="border:1px solid rgba(120,150,220,.35);background:rgba(10,15,28,.72);border-radius:16px;padding:14px 16px;margin:10px 0;">
  <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;">
    <div style="font-size:1.08rem;font-weight:800;color:#f8fafc;">{title}</div>
    <div style="font-size:.95rem;font-weight:800;color:#ffd166;white-space:nowrap;">{action_txt}</div>
  </div>
  <div style="margin-top:8px;font-size:.95rem;color:#dbeafe;">
    條件分數：<b>{score_txt}</b>　｜　證據：<b>{ev_txt}</b>
  </div>
  <div style="margin-top:6px;font-size:.95rem;color:#f8fafc;">
    20日：<b>{w20}</b>　｜　40日：<b>{w40}</b>
  </div>
  <div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(148,163,184,.18);font-size:.92rem;color:#cbd5e1;line-height:1.65;">
    進場：<b style="color:#f8fafc;">{entry}</b><br>
    短線失效：<b style="color:#f8fafc;">{short_fail}</b><br>
    波段防守：<b style="color:#f8fafc;">{wave_defense}</b><br>
    目標：<b style="color:#f8fafc;">{target}</b>
  </div>
  <div style="margin-top:10px;font-size:.92rem;color:#aab4c8;line-height:1.55;">{note}</div>
</div>
""",
            unsafe_allow_html=True,
        )


