def get_model_family_key(model_key=None, industry_category=None):
    """把既有 model_key / 估值子模組歸類到母模型；找不到時用名稱關鍵字 fallback。"""
    mk = str(model_key or "").strip()
    if mk in MODEL_TO_FAMILY_MAP:
        return MODEL_TO_FAMILY_MAP[mk]
    cfg = (MODEL_CONFIG or {}).get(mk, {}) if "MODEL_CONFIG" in globals() else {}
    hay = " ".join([
        mk,
        str(industry_category or ""),
        str(cfg.get("name", "")),
        str(cfg.get("primary", "")),
        str(cfg.get("note", "")),
    ]).lower()
    if any(k in hay for k in ["金融", "bank", "broker", "pb + roe", "p/b + roe", "壽險", "金控"]):
        return "financial_pb_roe"
    if any(k in hay for k in ["航運", "運價", "shipping", "freight", "bdi", "scfi", "airline", "航空"]):
        return "freight_cycle"
    if any(k in hay for k in ["營建", "建設", "nav", "土地", "入帳", "real estate", "construction"]):
        return "asset_nav_real_estate"
    if any(k in hay for k in ["生技", "藥", "臨床", "drug", "biotech", "cdmo", "里程碑"]):
        return "biotech_event_milestone"
    if any(k in hay for k in ["記憶體模組", "ssd", "模組循環", "庫存價差", "memory module"]):
        return "memory_module_inventory_cycle"
    if any(k in hay for k in ["通路", "代理", "distributor", "低毛利經銷"]):
        return "low_margin_distributor"
    if any(k in hay for k in ["組裝", "odm", "代工", "assembly", "低毛利代工"]):
        return "low_margin_odm"
    if any(k in hay for k in ["記憶體製造景氣反轉", "正常化 eps", "dram", "nand", "nor"]):
        return "cycle_eps_rerating"
    if any(k in hay for k in ["面板", "轉型", "foplp", "turnaround"]):
        return "turnaround_rerating_candidate"
    if any(k in hay for k in ["p/b", "pb", "景氣循環", "鋼鐵", "塑化", "水泥", "太陽能"]):
        return "cycle_pb_recovery"
    if any(k in hay for k in ["ccl", "pcb", "散熱", "液冷", "connector", "電源", "高階材料", "產品升級", "advanced", "材料重評"]):
        return "premium_product_rerating"
    return "quality_growth_pe"


def get_model_family_rule(model_key=None, industry_category=None):
    fk = get_model_family_key(model_key, industry_category)
    return fk, (MODEL_FAMILY_RULES.get(fk) or MODEL_FAMILY_RULES["quality_growth_pe"])


