def _nick_unique_keep_order(items):
    out = []
    for x in items or []:
        sx = str(x or "").strip()
        if sx and sx not in out:
            out.append(sx)
    return out


def _is_memory_ai_structural_context(family_key=None, model_key=None, valuation_submodel_key=None, industry_category=None):
    fk = str(family_key or "").strip()
    if fk in MEMORY_AI_STRUCTURAL_LAYER_RULES:
        return True
    hay = " ".join([
        str(family_key or ""),
        str(model_key or ""),
        str(valuation_submodel_key or ""),
        str(industry_category or ""),
    ]).lower()
    return any(k in hay for k in ["memory", "記憶體", "dram", "nand", "hbm", "ssd", "ddr"])


def get_memory_ai_structural_layer(family_key=None, model_key=None, valuation_submodel_key=None, industry_category=None):
    """回傳記憶體 AI 結構性需求加權層。只供分析語境，不直接放行裁決。"""
    fk = str(family_key or "").strip()
    if fk in MEMORY_AI_STRUCTURAL_LAYER_RULES:
        return dict(MEMORY_AI_STRUCTURAL_LAYER_RULES[fk])
    # 若是舊記憶體 PB 修復或記憶體 storage fallback，保守套製造端景氣層。
    if _is_memory_ai_structural_context(fk, model_key, valuation_submodel_key, industry_category):
        if "module" in str(valuation_submodel_key or "").lower() or "模組" in str(industry_category or ""):
            return dict(MEMORY_AI_STRUCTURAL_LAYER_RULES["memory_module_inventory_cycle"])
        return dict(MEMORY_AI_STRUCTURAL_LAYER_RULES["cycle_eps_rerating"])
    return {}


def apply_memory_ai_structural_layer(rule=None, family_key=None, model_key=None, valuation_submodel_key=None, industry_category=None):
    """把 AI 結構性需求層併入母模型規則；只加證據與文字，不改裁決。"""
    base = dict(rule or {})
    layer = get_memory_ai_structural_layer(family_key, model_key, valuation_submodel_key, industry_category)
    if not layer:
        return base
    base["ai_structural_layer"] = layer
    base["ai_structural_layer_name"] = layer.get("layer_name", "")
    base["ai_structural_layer_note"] = layer.get("layer_note", "")
    base["ai_structural_upgrade_gate"] = layer.get("upgrade_gate", "")
    base["ai_structural_stage_prompt"] = layer.get("stage_prompt", "")
    base["evidence_tags"] = _nick_unique_keep_order((base.get("evidence_tags") or []) + (layer.get("structural_evidence_tags") or []))
    base["risk_tags"] = _nick_unique_keep_order((base.get("risk_tags") or []) + (layer.get("structural_risk_tags") or []))
    return base


