def get_freight_subfamily_key(model_key=None, valuation_submodel_key=None, stock=None, industry_category=None):
    """判斷運價循環底下的子族群；只做路由，不做投資裁決。"""
    hay = " ".join([
        str(model_key or ""),
        str(valuation_submodel_key or ""),
        str(stock or ""),
        str(industry_category or ""),
    ]).lower()
    code = str(stock or "").strip()
    if code in {"2603", "2609", "2615"} or any(k in hay for k in ["container", "貨櫃", "scfi", "ccfi"]):
        return "container_shipping"
    if code in {"2605", "2606", "2612", "2617", "2637", "2641", "5608"} or any(k in hay for k in ["dry_bulk", "散裝", "bdi", "bci", "bpi"]):
        return "dry_bulk_shipping"
    if code in {"2610", "2618", "2645", "2646"} or any(k in hay for k in ["airline", "航空", "載客", "票價"]):
        return "airline"
    return "container_shipping" if "shipping" in hay or "航運" in hay else ""


def get_freight_subfamily_rule(model_key=None, valuation_submodel_key=None, stock=None, industry_category=None):
    key = get_freight_subfamily_key(model_key, valuation_submodel_key, stock, industry_category)
    return key, dict(FREIGHT_SUBFAMILY_RULES.get(key) or {})


def get_effective_family_context(model_key=None, valuation_submodel_key=None, stock=None, industry_category=None):
    """回傳母模型規則；若是運價循環，再套入貨櫃 / 散裝 / 航空子族群證據方向。

    v31：優先用估值子模組路由母模型，避免同一個 STOCK_MODEL_MAP 的大族群把子族群吃掉。
    例如記憶體製造、記憶體模組、低毛利通路、貨櫃 / 散裝 / 航空，先看 valuation_submodel_key，找不到再回到 model_key / 產業。
    """
    sub_mk = str(valuation_submodel_key or "").strip()
    if sub_mk and sub_mk in MODEL_TO_FAMILY_MAP:
        family_key = MODEL_TO_FAMILY_MAP.get(sub_mk) or "quality_growth_pe"
        family_rule = MODEL_FAMILY_RULES.get(family_key) or MODEL_FAMILY_RULES.get("quality_growth_pe", {})
    else:
        family_key, family_rule = get_model_family_rule(model_key, industry_category)
    rule = dict(family_rule or {})
    sub_key, sub_rule = "", {}
    if family_key == "freight_cycle":
        sub_key, sub_rule = get_freight_subfamily_rule(model_key, valuation_submodel_key, stock, industry_category)
        if sub_rule:
            rule["family_name"] = f"運價循環｜{sub_rule.get('name')}"
            rule["valuation_role"] = sub_rule.get("valuation_role") or rule.get("valuation_role")
            rule["evidence_tags"] = sub_rule.get("evidence_tags") or rule.get("evidence_tags", [])
            rule["risk_tags"] = sub_rule.get("risk_tags") or rule.get("risk_tags", [])
            rule["subfamily_note"] = sub_rule.get("note", "")
    rule = apply_memory_ai_structural_layer(rule, family_key=family_key, model_key=model_key, valuation_submodel_key=valuation_submodel_key, industry_category=industry_category)
    rule["family_key"] = family_key
    rule["subfamily_key"] = sub_key
    return family_key, rule


