def get_family_decision_guardrail(model_key=None, industry_category=None):
    fk, fr = get_model_family_rule(model_key, industry_category)
    return fk, fr, (FAMILY_DECISION_GUARDRAILS.get(fk) or FAMILY_DECISION_GUARDRAILS["quality_growth_pe"])


def _dedupe_short_items(items, limit=5):
    out, seen = [], set()
    for x in items or []:
        s = str(x or "").strip()
        if not s or s in seen:
            continue
        out.append(s)
        seen.add(s)
        if len(out) >= limit:
            break
    return out


def build_family_decision_context(model_key, core, attack, focus, action, fj=None, rr=None, cj=None, ps=None, plan=None, focus_block_reasons=None, industry_category=None):
    """母模型裁決語境：補充 Core 類型 / Attack gate / Focus gate，不直接改裁決結果。"""
    fk, fr, gr = get_family_decision_guardrail(model_key, industry_category)
    core = str(core or "")
    attack = str(attack or "")
    focus = str(focus or "")
    action = str(action or "")
    notes = []

    # Core 語境：只說明「這種 Core 的型態」，不替 decide_all() 決定 Core。
    if core == "Yes":
        notes.append(gr.get("core_yes_note"))
    elif "候選" in str((fj or {}).get("treasury", "")) or "候選" in action:
        notes.append(f"目前偏 {fr.get('family_name', '族群')} 候選；是否 Core 仍以法醫硬門檻為準。")
    else:
        notes.append(gr.get("core_no_note"))

    # Attack 語境：觀察型小倉不可等同 Attack 成立。
    if attack != "Yes" and ("小倉" in action or "試單" in action or "觀察" in action):
        notes.append("觀察型小倉不等於 Attack 成立；要等右側站回、突破或籌碼轉強。")
    elif attack == "Yes":
        notes.append(gr.get("attack_gate"))

    # Focus 語境：Focus No 的主要限制。
    if focus != "Yes":
        if focus_block_reasons:
            notes.append("Focus No：" + "、".join([str(x) for x in focus_block_reasons[:2]]))
        else:
            notes.append(gr.get("focus_gate"))
    else:
        notes.append("Focus Yes 仍需分批與失效點控管，不代表無風險重押。")

    # 籌碼限制：不改結論，只標記警示。
    cj = cj or {}
    if cj.get("limit_attack") or cj.get("limit_focus"):
        notes.append("籌碼限制：法人分歧或短線調節會限制 Attack / Focus 升級。")

    # 估值位置：高估值區不得把 Core 當追價理由。
    if ps in ["高溢價區", "明顯跑太前面", "偏貴 / 已提前反映未來", "區間夾層", "區間重疊"]:
        notes.append("估值限制：現價已偏樂觀，Core 若成立也不等於現價可追高。")

    notes = _dedupe_short_items(notes, limit=5)
    return {
        "family_key": fk,
        "family_name": fr.get("family_name", fk),
        "core_scope": gr.get("core_scope", fr.get("core_label", "Core")),
        "core_label": fr.get("core_label", gr.get("core_scope", "Core")),
        "notes": notes,
        "summary": "；".join(notes[:2]),
        "rule_source": "MODEL_FAMILY_RULES + FAMILY_DECISION_GUARDRAILS",
    }



