def get_family_routing_profile_v31(family_key=None, subfamily_key=None):
    """取得 v31 母模型路由說明；只供 UI / 自檢使用，不參與裁決。"""
    fk = str(family_key or "").strip()
    profile = dict(FAMILY_ROUTING_PROFILE_V31.get(fk) or {})
    if fk == "freight_cycle" and subfamily_key:
        # 運價循環底下的子族群已由 FREIGHT_SUBFAMILY_RULES 決定證據方向；這裡加一句避免混用。
        sub_rule = dict(FREIGHT_SUBFAMILY_RULES.get(str(subfamily_key or "")) or {})
        if sub_rule:
            profile["fit_for"] = f"運價循環｜{sub_rule.get('name')}。" + str(profile.get("fit_for") or "")
            profile["evidence_priority"] = _nick_join_tags(sub_rule.get("evidence_tags"), limit=8)
            profile["forensic_risk"] = _nick_join_tags(sub_rule.get("risk_tags"), limit=6)
            profile["do_not_apply"] = str(sub_rule.get("note") or profile.get("do_not_apply") or "")
    layer = get_memory_ai_structural_layer(fk)
    if layer:
        profile["ai_structural_layer"] = layer.get("layer_name", "")
        profile["ai_structural_gate"] = layer.get("upgrade_gate", "")
        profile["evidence_priority"] = str(profile.get("evidence_priority") or "").rstrip("。") + "；" + _nick_join_tags(layer.get("structural_evidence_tags"), limit=6)
        profile["forensic_risk"] = str(profile.get("forensic_risk") or "").rstrip("。") + "；" + _nick_join_tags(layer.get("structural_risk_tags"), limit=5)
    return profile

# =========================
# 族群母模型自檢 v1｜只做稽核顯示，不改裁決
# =========================
def _nick_join_tags(tags, limit=6):
    vals = []
    for x in (tags or []):
        sx = str(x or "").strip()
        if sx and sx not in vals:
            vals.append(sx)
        if len(vals) >= limit:
            break
    return "、".join(vals) if vals else "未設定"


def _nick_audit_attack_display(a):
    """自檢用 Attack 細分顯示；只改顯示，不改 decide_all() 裁決。"""
    a = a or {}
    attack = str(a.get("attack", "") or "")
    attack_type = str(a.get("attack_type", "") or "")
    action = str(a.get("action", "") or "")
    model_key = str(((a.get("val") or {}).get("model_key")) or "")

    if model_key == "panel_turnaround_rerating" and attack == "Yes":
        return "Yes｜已發動，不追高"
    if model_key == "memory_manufacturing_cycle_rerating":
        if attack == "Yes":
            return "回檔型｜小倉觀察"
        return "No｜觀察型小倉"
    if attack == "Yes":
        if "回檔" in attack_type:
            return "Yes｜回檔型，等承接"
        if "突破" in attack_type:
            return "Yes｜突破型，等量能確認"
        if "已發動" in action or "不追" in action or "追高" in action:
            return "Yes｜已發動，不追高"
        return "Yes｜攻擊成立"
    if "觀察型小倉" in attack_type or "小倉" in action or "試單" in action:
        return "No｜觀察型小倉"
    if "候選" in attack or "候選" in attack_type:
        return "候選｜等驗證"
    return f"{attack or 'No'}｜等訊號"


def _nick_audit_escape(x):
    try:
        return _html.escape(str(x if x is not None else ""))
    except Exception:
        return str(x if x is not None else "")


def build_family_audit_snapshot(stock=None, name=None, a=None, industry_category=None):
    """產生族群 / 子模組 / 母模型自檢資訊。

    重要：這個函式只用於檢查路由與顯示，不參與 Core / Attack / Focus 裁決。
    """
    a = a or {}
    val = a.get("val", {}) or {}
    plan = a.get("plan", {}) or {}
    model_key = val.get("model_key") or a.get("model_key") or "default"
    valuation_submodel_key = val.get("valuation_submodel_key") or val.get("submodel_key") or ""
    family_key, family_rule = get_effective_family_context(model_key, valuation_submodel_key=valuation_submodel_key, stock=stock, industry_category=industry_category)
    _, _, guardrail = get_family_decision_guardrail(model_key, industry_category)

    decision_ctx = a.get("family_decision_context") or {}
    evidence_box = a.get("evidence_box", {}) or {}
    evidence_rule = evidence_box.get("rule") or evidence_box.get("evidence_rule") or {}

    valuation_submodel_name = val.get("valuation_submodel_name") or nick_get_valuation_submodel_name(model_key)
    valuation_formula = val.get("valuation_formula_used") or val.get("valuation_formula_family") or val.get("formula_family") or "未標示"

    rows = [
        {"檢查項目": "標的", "目前內容": f"{name or ''} {stock or ''}".strip(), "用途": "確認本次分析對象"},
        {"檢查項目": "model_key", "目前內容": str(model_key), "用途": "既有個股模型路由，不等於 Core 裁決"},
        {"檢查項目": "母模型", "目前內容": f"{family_rule.get('family_name', family_key)}｜{family_key}", "用途": "決定分析框架、搜尋方向、估值語氣與風險檢查"},
        {"檢查項目": "母模型適用", "目前內容": str(get_family_routing_profile_v31(family_key, family_rule.get('subfamily_key')).get("fit_for", "未設定")), "用途": "確認這條路由適用什麼商業模式"},
        {"檢查項目": "不可硬套", "目前內容": str(get_family_routing_profile_v31(family_key, family_rule.get('subfamily_key')).get("do_not_apply", "未設定")), "用途": "避免把龍頭模型或其他族群公式套到分支族群"},
        {"檢查項目": "法醫風險", "目前內容": str(get_family_routing_profile_v31(family_key, family_rule.get('subfamily_key')).get("forensic_risk", "未設定")), "用途": "每次分析要優先找的反方證據"},
        {"檢查項目": "Focus 限制", "目前內容": str(get_family_routing_profile_v31(family_key, family_rule.get('subfamily_key')).get("focus_limit", "未設定")), "用途": "確認集中火力沒有被母模型風險限制"},
        {"檢查項目": "AI 結構層", "目前內容": str((family_rule.get("ai_structural_layer") or {}).get("layer_name") or "不適用"), "用途": "只對記憶體族群加權需求續航；不直接決定 Core / Focus"},
        {"檢查項目": "AI 加權門檻", "目前內容": str(family_rule.get("ai_structural_upgrade_gate") or "不適用"), "用途": "確認 AI 題材是否真的轉成報價、毛利率、EPS 與現金流"},
        {"檢查項目": "估值子模組", "目前內容": f"{valuation_submodel_name}｜{valuation_submodel_key}".strip("｜"), "用途": "決定估值方法與防呆提醒"},
        {"檢查項目": "估值角色", "目前內容": str(family_rule.get("valuation_role", "未設定")), "用途": "說明用 PE / P/B / EV/EBITDA / NAV / 事件模型的邏輯"},
        {"檢查項目": "實際估值公式", "目前內容": str(valuation_formula), "用途": "檢查畫面是否誤用估值公式"},
        {"檢查項目": "證據方向", "目前內容": _nick_join_tags(family_rule.get("evidence_tags")), "用途": "新聞 / 公告 / 財報搜尋應優先找這些證據"},
        {"檢查項目": "風險檢查", "目前內容": _nick_join_tags(family_rule.get("risk_tags")), "用途": "避免只看利多，找反方證據"},
        {"檢查項目": "Core 裁決", "目前內容": f"{a.get('core', '資料不足')}｜{guardrail.get('core_scope', '')}", "用途": "Core Yes 只能由法醫硬門檻決定，母模型只提供語境"},
        {"檢查項目": "Attack 裁決", "目前內容": _nick_audit_attack_display(a), "用途": "檢查攻擊是否已發動、是否只是觀察型小倉，避免把可看誤判成可追"},
        {"檢查項目": "Focus 裁決", "目前內容": str(a.get("focus", "資料不足")), "用途": "檢查是否因題材或子模組而誤放行重押"},
        {"檢查項目": "新倉 / 小倉", "目前內容": f"{plan.get('new', '資料不足')} / {plan.get('shallow', '資料不足')}", "用途": "檢查買點是否讀到正確交易區間"},
        {"檢查項目": "壓力 / 防守", "目前內容": f"右側：{plan.get('right', '資料不足')}｜防守：{plan.get('wrong', plan.get('stop', '資料不足'))}", "用途": "檢查右側條件與認錯點"},
        {"檢查項目": "提醒來源", "目前內容": str(decision_ctx.get("rule_source") or "MODEL_FAMILY_RULES / 通用提醒"), "用途": "確認提醒不是單一個股寫死"},
    ]
    return {
        "family_key": family_key,
        "family_name": family_rule.get("family_name", family_key),
        "model_key": model_key,
        "valuation_submodel_key": valuation_submodel_key,
        "valuation_submodel_name": valuation_submodel_name,
        "rows": rows,
    }


def render_family_audit_box(stock=None, name=None, a=None, industry_category=None):
    """在 UI 顯示族群母模型自檢卡。只顯示，不修改分析結果。"""
    try:
        snap = build_family_audit_snapshot(stock, name, a, industry_category)
        st.caption(
            "這裡只用來檢查路由：子模組 / 母模型 = 分析框架與搜尋方向；Core / Attack / Focus 仍由法醫硬門檻裁決。"
        )
        st.markdown(
            """
<style>
.nick-audit-card{
  border:1px solid rgba(120,145,190,.35);
  background:rgba(10,18,34,.74);
  border-radius:14px;
  padding:12px 13px;
  margin:9px 0;
  box-shadow:0 0 0 1px rgba(255,255,255,.02) inset;
}
.nick-audit-title{
  color:#93c5fd;
  font-weight:800;
  font-size:.92rem;
  margin-bottom:6px;
  letter-spacing:.02em;
}
.nick-audit-content{
  color:#f8fafc;
  font-weight:750;
  font-size:1.02rem;
  line-height:1.55;
  word-break:break-word;
}
.nick-audit-use{
  color:#aab4c5;
  font-size:.86rem;
  line-height:1.45;
  margin-top:7px;
}
</style>
""",
            unsafe_allow_html=True,
        )
        for row in snap.get("rows", []):
            title = _nick_audit_escape(row.get("檢查項目", ""))
            content = _nick_audit_escape(row.get("目前內容", ""))
            use = _nick_audit_escape(row.get("用途", ""))
            st.markdown(
                f"""
<div class="nick-audit-card">
  <div class="nick-audit-title">{title}</div>
  <div class="nick-audit-content">{content}</div>
  <div class="nick-audit-use">{use}</div>
</div>
""",
                unsafe_allow_html=True,
            )
    except Exception as e:
        st.caption(f"族群母模型自檢暫時無法顯示：{e}")

