def get_family_trade_rule(model_key=None, industry_category=None, valuation_submodel_key=None, stock=None):
    fk, family_rule = get_effective_family_context(model_key, valuation_submodel_key=valuation_submodel_key, stock=stock, industry_category=industry_category)
    trade_rule = dict(FAMILY_TRADE_POSITION_RULES.get(fk) or FAMILY_TRADE_POSITION_RULES["quality_growth_pe"])
    trade_rule["family_key"] = fk
    trade_rule["family_name"] = family_rule.get("family_name", "此族群")
    trade_rule["core_label"] = family_rule.get("core_label", "Core")
    if fk == "freight_cycle" and family_rule.get("subfamily_key"):
        trade_rule["check"] = _nick_join_tags(family_rule.get("evidence_tags"), limit=5)
        trade_rule["role"] = family_rule.get("subfamily_note") or trade_rule.get("role")
        trade_rule["subfamily_key"] = family_rule.get("subfamily_key")
    return trade_rule


def get_family_zone_labels(a):
    """回傳母模型對應的買點區塊名稱；只影響 30 秒判讀顯示，不改底層買點公式。"""
    model_key = ((a or {}).get("val") or {}).get("model_key")
    rule = get_family_trade_rule(model_key)
    return rule.get("new_label") or "新倉主買區", rule.get("shallow_label") or "淺回檔小倉區"


def build_family_trade_context(a, relation_new, relation_shallow, new_zone_line, shallow_zone_line, key_pressure_line, buy_wrong, buy_stop):
    """用母模型產生交易位置語氣。

    這裡只管文字：現價在主區 / 小倉區 / 高於小倉區 / 低於主區時該怎麼講。
    不直接決定 Core、Attack、Focus，也不改買點公式。
    """
    a = a or {}
    model_key = ((a.get("val") or {}).get("model_key") or "")
    rule = get_family_trade_rule(model_key)
    new_label = rule.get("new_label") or "新倉主買區"
    shallow_label = rule.get("shallow_label") or "淺回檔小倉區"
    check = rule.get("check") or "營收、毛利率、EPS 與法人籌碼"
    verify_phrase = _nick_compact_verification_phrase(check)
    role = rule.get("role") or "買點仍要看估值、籌碼與失效點"
    core = str(a.get("core", "") or "")
    attack = str(a.get("attack", "") or "")
    focus = str(a.get("focus", "") or "")
    action = str(a.get("action", "") or "")

    in_new = relation_new == "in"
    in_shallow = relation_shallow == "in"
    above_shallow = relation_shallow in ["near_above", "above"] and relation_new in ["near_above", "above"]
    below_new = relation_new == "below"

    if in_new:
        comment = f"現價位於{new_label}，可分批但仍要守失效點；{role}。"
        op_empty = f"空手想進場：位於{new_label} {new_zone_line}，可分批但不要一次押滿；跌破 {buy_wrong} 先停手。"
        op_hold = f"已持有：{buy_wrong} 是短線防守；沒跌破先看關鍵壓力，跌破先減碼或停止加碼。"
        op_want = f"想加碼：只在主買區守住、或重新站回防守後加；跌破 {buy_wrong} 不加碼，先等收回。"
    elif in_shallow:
        comment = f"現價位於{shallow_label}，只能小量觀察，不是主倉甜點；{role}。"
        op_empty = f"空手想進場：只允許觀察型小倉；主倉等 {new_zone_line}，跌破防守不接刀。"
        op_hold = f"已持有：{buy_wrong} 是短線防守區；跌破後先減碼或停止加碼，若收不回要降級。"
        op_want = f"想加碼：只在小倉區守住、或突破後回測不破再小量；跌破 {buy_wrong} 不加碼。"
    elif above_shallow:
        comment = f"現價已高於{new_label}與{shallow_label}，等回檔；若已突破，等回測確認，不追高。"
        op_empty = f"空手想進場：等回 {shallow_zone_line} 有承接再小量；若跌破 {buy_wrong} 先不接刀，等重新站回。"
        op_hold = f"已持有：{buy_wrong} 是短線防守區；跌破後先減碼或停止加碼，若收不回要降級。"
        op_want = f"想加碼：只在 {shallow_zone_line} 守住、或重新站回防守後加；跌破防守時不加碼。"
    elif below_new:
        comment = f"現價低於{new_label}，先確認趨勢與基本面是否轉弱，不急著攤平。"
        op_empty = "空手想進場：先觀察，不急著接；確認基本面與趨勢沒有破壞。"
        op_hold = f"已持有：守 {buy_stop}，跌破不要硬撐；先降風險再觀察是否收回。"
        op_want = f"想加碼：先等 {verify_phrase} 與支撐重新站回；跌破防守不加碼。"
    else:
        comment = f"目前位置仍需等買點確認；{role}。"
        op_empty = "空手想進場：先觀察，不急著追。"
        op_hold = f"已持有：守 {buy_wrong or buy_stop}，跌破先降風險。"
        op_want = f"想加碼：等 {verify_phrase} 與支撐承接確認；跌破防守不加碼。"

    # Core / Attack / Focus 不在此決定，只在文字上做風控提醒。
    if core == "Yes" and focus != "Yes" and "重押" not in comment:
        comment = comment.rstrip("。") + "；Core Yes 不等於可重押。"
    _main_up_active_for_trade = False
    try:
        _main_up_active_for_trade = bool((a.get("main_up_attack") or {}).get("active")) or ("主升" in str(a.get("attack_type", "")))
    except Exception:
        _main_up_active_for_trade = False
    if attack != "Yes" and "Attack" not in comment and not _main_up_active_for_trade:
        comment = comment.rstrip("。") + "；Attack 尚未正式成立。"
    elif _main_up_active_for_trade and "主升" not in comment:
        comment = comment.rstrip("。") + "；主升攻擊狀態成立，但新倉不追高，等回測 / 回檔。"

    return {
        "family_key": rule.get("family_key"),
        "family_name": rule.get("family_name"),
        "new_label": new_label,
        "shallow_label": shallow_label,
        "check": check,
        "role": role,
        "comment": comment,
        "op_empty": op_empty,
        "op_hold": op_hold,
        "op_want": op_want,
    }


# =========================
# v260｜30秒判讀決策合成器
# =========================
def nick_v260_30s_decision_synthesizer(
    a=None,
    report="",
    report_display="",
    core_display="",
    attack_display="",
    focus_v="",
    base_judge="",
    position_comment="",
    op_empty="",
    op_hold="",
    op_want="",
    relation_new="unknown",
    relation_shallow="unknown",
    new_zone_line="",
    shallow_zone_line="",
    key_pressure_line="",
    buy_wrong="",
    buy_stop="",
    family_trade_ctx=None,
    rerating_quick_line="",
    fundamental_quick="",
    valuation_guard_line="",
    ref_price=None,
):
    """把 30 秒判讀從「資料排版」升級為「多條件排列組合後的白話結論」。

    這個函式只改 30 秒分享文的語意層，不改底層 Core / Attack / Focus / 估值 / 買點公式。
    核心目的：同時看財報、Core、Attack、Focus、估值位置、買點位置、籌碼限制與族群母模型，
    再輸出小白能懂的「現在怎麼做」。
    """
    a = a or {}
    family_trade_ctx = family_trade_ctx or {}

    def _txt(x):
        return str(x or "").strip()

    def _has_yes(x):
        return bool(re.search(r"(^|[^A-Za-z])Yes([^A-Za-z]|$)|可收編|成立", _txt(x), flags=re.I))

    def _has_no(x):
        return bool(re.search(r"(^|[^A-Za-z])No([^A-Za-z]|$)|不可收編|不成立", _txt(x), flags=re.I))

    def _short(x, n=88):
        x = _txt(x).strip("；，。 ")
        return x if len(x) <= n else x[:n] + "…"

    def _clean_zone(x):
        x = _txt(x)
        return x if x and x != "資料不足" else "買點區"

    def _clean_defense(x, fallback="防守區"):
        x = _txt(x)
        return x if x and x != "資料不足" else fallback

    core_raw = _txt(a.get("core"))
    attack_raw = _txt(a.get("attack"))
    focus_raw = _txt(a.get("focus"))
    action_raw = _txt(a.get("action"))
    model_key = _txt((a.get("val") or {}).get("model_key"))
    family_key = _txt(family_trade_ctx.get("family_key"))
    family_role = _txt(family_trade_ctx.get("role"))
    check = _txt(family_trade_ctx.get("check"))

    report_pass = _txt(report) == "通過" or _txt(report_display) == "通過"
    report_partial = "部分" in _txt(report) or "部分" in _txt(report_display)
    report_fail = "不通過" in _txt(report) or "不通過" in _txt(report_display)

    core_yes = (core_raw == "Yes") or _has_yes(core_display)
    core_no = (core_raw == "No") and not core_yes
    core_candidate = ("候選" in _txt(core_display)) or ("觀察" in _txt(core_display))

    attack_yes = (attack_raw == "Yes") or _has_yes(attack_display)
    attack_observe = any(k in (_txt(attack_display) + action_raw) for k in ["小倉", "觀察", "回檔", "回測", "候選"])
    focus_yes = (focus_raw == "Yes") or _has_yes(focus_v)

    rer_blob = "｜".join([_txt(rerating_quick_line), _txt(fundamental_quick), _txt(valuation_guard_line)])
    rerating_yes = ("估值重評：成立" in rer_blob) or ("重評：成立" in rer_blob)
    rerating_partial = "部分成立" in rer_blob or "部分具備" in rer_blob
    rerating_fail = "不成立" in rer_blob

    pos = "unknown"
    if relation_new == "below":
        pos = "below_new"
    elif relation_new == "in":
        pos = "in_new"
    elif relation_shallow == "in":
        pos = "in_shallow"
    elif relation_shallow in ["near_above", "above"] and relation_new in ["near_above", "above"]:
        pos = "above_shallow"

    chip_j = a.get("chip_j") or {}
    chip_text = _txt(chip_j.get("text") or chip_j.get("summary") or chip_j.get("verdict"))
    chip_limit = bool(chip_j.get("limit_focus") or chip_j.get("limit_attack"))
    chip_risk = chip_limit or any(k in chip_text for k in ["賣", "分歧", "調節", "換手", "倒貨", "融資", "不乾淨"])

    cyclical_family = family_key in [
        "cycle_pb_recovery", "cycle_eps_rerating", "memory_module_inventory_cycle",
        "asset_heavy_ev_ebitda", "freight_cycle",
    ] or any(k in model_key for k in ["memory", "cycle", "shipping", "panel", "copper", "glass"])

    high_position = pos == "above_shallow" or any(k in (_txt(position_comment) + action_raw) for k in ["高於", "不追", "偏高", "壓力", "高檔"])
    low_position = pos == "below_new"
    executable_position = pos in ["in_new", "in_shallow"]

    # 先決定大方向，再用位置 / 風控微調。
    if report_fail and not core_yes:
        judge = "只觀察 / 不急著買"
        tail = "財報未通過，先不把題材當買進理由"
    elif core_yes and report_pass and focus_yes and executable_position and not chip_risk:
        judge = "可分批小倉 / 嚴守防守"
        tail = "三線條件較齊，但仍要分批與守失效點"
    elif core_yes and report_pass and focus_yes and high_position:
        judge = "主攻候選 / 但不追高"
        tail = "條件強，但位置不舒服，空手等回檔或回測"
    elif core_yes and report_pass and attack_yes:
        if high_position:
            judge = "持有續抱 / 空手等回檔"
            tail = "公司可收編且攻擊條件有味道，但現價風報比不適合追"
        elif low_position:
            judge = "低於買點 / 先確認沒轉弱"
            tail = "跌到買點下方時先查基本面與趨勢，不是越跌越買"
        elif executable_position:
            judge = "小倉試單 / 不重押"
            tail = "可測承接，但 Core Yes 不等於一次押滿"
        else:
            judge = "等回檔 / 等確認"
            tail = "公司條件可以，但買點仍要確認"
    elif core_yes and report_pass:
        if high_position:
            judge = "公司可收編 / 空手等回檔"
            tail = "財報與 Core 可收編，但 Attack / Focus 沒齊，不追高"
        elif executable_position:
            judge = "觀察型小倉 / 等攻擊訊號"
            tail = "公司可追蹤，先小倉看承接與籌碼"
        else:
            judge = "公司可收編 / 等買點"
            tail = "先看買點、籌碼與風報比，不急著重押"
    elif core_candidate or report_partial or rerating_partial or attack_observe:
        judge = "觀察型小倉 / 等驗證"
        tail = "有題材或部分財報證據，但還要營收、毛利率、EPS 或籌碼接棒"
    elif core_no or rerating_fail:
        judge = "只觀察 / 等訊號"
        tail = "Core 或估值重評沒過，先不要把它當主攻"
    else:
        judge = _txt(base_judge) or "等買點確認"
        tail = "目前條件還要再確認"

    if cyclical_family and core_yes and report_pass:
        tail = tail.rstrip("。") + "；週期型 Core 要看報價 / 月營收 / EPS 是否延續"
    if chip_risk and focus_yes:
        tail = tail.rstrip("。") + "；籌碼不夠乾淨，Focus 需降一級看"
        judge = "條件強但籌碼需驗證 / 不重押"
    elif chip_risk and "Focus" not in judge and not focus_yes:
        tail = tail.rstrip("。") + "；籌碼只當輔助，賣壓未收斂前不升級"

    # 位置說明：讓小白明確知道「空手買」和「加碼」不是永遠同一件事。
    new_zone = _clean_zone(new_zone_line)
    shallow_zone = _clean_zone(shallow_zone_line)
    wrong = _clean_defense(buy_wrong, "短線防守")
    stop = _clean_defense(buy_stop, wrong)
    pressure = _clean_zone(key_pressure_line)

    if report_fail and not core_yes:
        pos_comment = "財報或 Core 條件不足，先不急著進場；有持股也要看防守是否失守。"
        e = "空手想進場：先不買，等財報與買點重新轉強。"
        h = f"已持有：守 {wrong}；跌破後先降風險，不要用題材硬撐。"
        w = "想加碼：不加碼，等 Core / 財報 / 右側重新成立。"
    elif pos == "above_shallow":
        pos_comment = "現價已高於舒適買點，持有看防守與壓力；空手不要追，想加碼等回檔或回測。"
        e = f"空手想進場：等回 {shallow_zone} 有承接再小量；若跌破 {wrong} 先不接刀。"
        h = f"已持有：守 {wrong}；沒跌破可續看 {pressure}，跌破先減碼或降級。"
        w = f"想加碼：只在 {shallow_zone} 守住、或突破後回測不破再小量；跌破防守不加碼。"
    elif pos == "in_shallow":
        pos_comment = "現價在小倉區，只能測承接，不是主倉甜點。"
        e = f"空手想進場：可小量試單，但先看 {shallow_zone} 是否守住；跌破 {wrong} 停手。"
        h = f"已持有：守 {wrong}；守住可續看，跌破先降風險。"
        w = f"想加碼：只在 {shallow_zone} 守住後小量；跌破 {wrong} 不加碼。"
    elif pos == "in_new":
        pos_comment = "現價在主買區，條件若沒壞可分批，但仍不能一次押滿。"
        e = f"空手想進場：位於 {new_zone}，可分批小量；跌破 {wrong} 先停手。"
        h = f"已持有：守 {wrong}；沒跌破先看下一段壓力。"
        w = f"想加碼：只在主買區守住或重新站回防守後加；跌破 {wrong} 不加碼。"
    elif pos == "below_new":
        pos_comment = "現價低於主買區，先確認是不是基本面或趨勢轉弱，不要把破線誤會成便宜。"
        e = f"空手想進場：先觀察，不接刀；等重新站回 {wrong} 或買點區有承接再看。"
        h = f"已持有：先守 {stop}；若收不回 {wrong}，要降級處理。"
        w = f"想加碼：不加碼；等重新站回 {wrong} 且基本面沒壞再說。"
    else:
        pos_comment = _txt(position_comment) or "目前位置還要等買點確認。"
        e, h, w = op_empty, op_hold, op_want

    # 若原本母模型已產生更強的風控句，保留「跌破不加碼」精神。
    for_var = [e, h, w]
    if for_var[2] and "不加碼" not in for_var[2]:
        for_var[2] = for_var[2].rstrip("。") + f"；跌破 {wrong} 不加碼。"
    e, h, w = for_var

    one = f"財報{report_display or report}，Core {core_display}；Attack {attack_display}，Focus {focus_v}；合成判斷：{tail}。"
    return {
        "judge_text": _short(judge, 32),
        "one_sentence": _short(one, 108),
        "position_comment": _short(pos_comment, 96),
        "op_empty": _short(e, 88),
        "op_hold": _short(h, 88),
        "op_want": _short(w, 88),
        "decision_tail": _short(tail, 80),
        "position_state": pos,
    }

def _nick_join_tags(tags, limit=5):
    """把母模型證據標籤整理成一句短句，避免每個 model_key 寫死。"""
    try:
        tags = [str(x).strip() for x in (tags or []) if str(x).strip()]
    except Exception:
        tags = []
    if not tags:
        return "營收、毛利率、EPS、現金流"
    return "、".join(tags[:limit])


def _nick_compact_verification_phrase(check):
    """把操作句的驗證項目整理乾淨，避免出現「是否止賣 是否續強」這類模板黏連。

    只處理顯示文字，不改任何交易 / Core / Attack / Focus 判斷。
    """
    s = str(check or "").strip(" ，。；｜")
    if not s:
        return "營收、毛利率、EPS 與法人是否續強 / 轉弱"
    replacements = {
        "法人是否止賣": "法人是否續買或轉賣",
        "法人止賣": "法人是否續買或轉賣",
        "法人賣壓是否縮小": "法人賣壓是否縮小或轉買",
        "量能 / 法人確認": "量能與法人確認",
        "量能 / 法人": "量能與法人",
    }
    for old, new in replacements.items():
        s = s.replace(old, new)
    # 若 check 已經帶有「是否」，不要再在句尾硬補第二個是否。
    if "是否" in s:
        return s
    return f"{s} 是否續強 / 轉弱"


def _nick_compact_valuation_support_text(text):
    """30 秒判讀用的估值支撐減脂版。

    分工原則：
    - 市場在看什麼：講市場主軸。
    - 估值支撐：只講 EPS/倍數、支撐區、現價相對位置。
    - 子模組驗證：才放母模型、子模組、完整分數拆解。
    """
    raw_lines = [str(x).strip() for x in str(text or "").splitlines() if str(x).strip()]
    if not raw_lines:
        return "資料不足，暫時不能判斷基本面支撐價。"
    drop_prefixes = (
        "估值母模型：",
        "估值子模組：",
        "主估值方式：",
        "提醒：",
        "資料防呆：",
        "公式限制：",
        "實際估值公式：",
    )
    kept = []
    for line in raw_lines:
        if line.startswith(drop_prefixes):
            continue
        if line not in kept:
            kept.append(line)
    if not kept:
        return raw_lines[-1]
    # AI Core 估值文字需要保留 Core / EPS / PE / 基本面支撐 / 重評 / 失敗區，避免 30 秒判讀缺層。
    if any(("AI Core" in line or "基本面支撐區" in line or "重評合理區" in line or "驗證失敗下修區" in line) for line in kept):
        return "\n".join(kept[:6])
    # 一般 App 估值支撐區最多保留 2~3 行，避免與子模組驗證重複。
    return "\n".join(kept[:3])


def _nick_rerating_impact_line(val):
    """30 秒判讀用：估值重評只講分數如何影響估值，不展開完整依據。"""
    val = val or {}
    try:
        score = val.get("rerating_score")
        label = val.get("rerating_score_label") or ""
        allowed = bool(val.get("rerating_pe_uplift_allowed"))
        if score in [None, ""]:
            return "估值重評：資料不足。"
        score_text = str(int(float(score)))
        multiple_text = valuation_support_multiple_text(val) if "valuation_support_multiple_text" in globals() else ""
        multiple_label = val.get("valuation_multiple_label") or "合理 PE"
        if allowed:
            impact = "估值影響：允許評估重評倍數 / 上修估值區間"
            if multiple_text:
                impact += f"；目前採用{multiple_label} {multiple_text}"
            impact += "，但仍要看買點與風報比。"
        else:
            impact = "估值影響：重評證據不足，仍以保守估值與基本面支撐區為主。"
        return f"估值重評：{score_text}分｜{label}。{impact}"
    except Exception:
        return "估值重評：資料不足。"


def build_family_market_watch(a, financial_ability_text="", chip_text=""):
    """用母模型產生「市場在看什麼」。

    v42｜估值重評去重：
    這裡只講市場主軸與重評門檻，不再重複估值公式、子模組提醒、Core/Focus 裁決。
    完整分數拆解改放「子模組驗證」，估值倍數影響改放「估值支撐」。
    """
    a = a or {}
    val = a.get("val") or {}
    model_key = (val.get("model_key") or "")
    valuation_submodel_key = val.get("valuation_submodel_key") or val.get("submodel_key") or ""
    family_key, rule = get_effective_family_context(model_key, valuation_submodel_key=valuation_submodel_key, stock=val.get("stock"))
    evidence = _nick_join_tags(rule.get("evidence_tags"), limit=6)
    risks = _nick_join_tags(rule.get("risk_tags"), limit=3)

    parts = []
    parts.append(f"主線：市場主要看 {evidence} 是否延續，並轉成財報與現金流。")

    # 族群重評門檻只保留一段；不要同時把 valuation_role / AI gate / 子模組提醒全部塞進來。
    if family_key in ("cycle_eps_rerating", "memory_module_inventory_cycle"):
        parts.append("重評門檻：報價 / ASP、毛利率、EPS 與現金流同步接上，才提高估值上修可信度；若只是題材或供給排擠，只能當續航加分。")
    elif family_key in ("premium_product_rerating", "ai_infrastructure_growth") or rule.get("ai_structural_upgrade_gate"):
        parts.append("重評門檻：產品規格升級必須反映在 ASP、毛利率、EPS 或訂單能見度，不能只靠題材熱度。")
    elif family_key in ("cycle_pb_recovery", "turnaround_rerating_candidate"):
        parts.append("重評門檻：景氣修復要看報價、稼動率、虧損收斂與 EPS 是否真的轉強。")
    elif family_key in ("shipping_cycle", "shipping_freight_cycle"):
        parts.append("重評門檻：運價、裝載率、現金流與股利能力要同步改善，不能只看單週運價。")
    elif family_key in ("real_estate_nav", "asset_nav_delivery"):
        parts.append("重評門檻：交屋入帳、NAV / BVPS、負債與現金流要能互相驗證。")

    if risks:
        parts.append(f"反方：{risks}。")

    # 市場區塊只保留籌碼一句，且短句化；財務能力已在估值 / 子模組區呈現，這裡不重複。
    if chip_text:
        parts.append(str(chip_text).strip())

    out, seen = [], set()
    for x in parts:
        x = str(x or "").strip()
        if not x or x in seen:
            continue
        out.append(x)
        seen.add(x)
    return "\n".join(out[:4])


def build_family_watch_items(a, key_pressure_line="關鍵壓力"):
    """用母模型產生 30 秒判讀的 3 個觀察點。"""
    a = a or {}
    val = a.get("val") or {}
    model_key = (val.get("model_key") or "")
    valuation_submodel_key = val.get("valuation_submodel_key") or val.get("submodel_key") or ""
    family_key, rule = get_effective_family_context(model_key, valuation_submodel_key=valuation_submodel_key, stock=val.get("stock"))
    evidence_tags = [str(x).strip() for x in (rule.get("evidence_tags") or []) if str(x).strip()]
    risk_tags = [str(x).strip() for x in (rule.get("risk_tags") or []) if str(x).strip()]
    e1 = "、".join(evidence_tags[:3]) if evidence_tags else "營收、毛利率、EPS"
    e2 = "、".join(evidence_tags[3:6]) if len(evidence_tags) > 3 else "現金流與法人籌碼"
    r1 = "、".join(risk_tags[:3]) if risk_tags else "股價先跑與估值過熱"
    return [
        f"{e1} 是否延續，不能只有題材或單月數字。",
        f"{e2} 是否接棒，確認基本面能不能撐住股價。",
        f"反方注意 {r1}；法人籌碼與股價是否突破 {key_pressure_line}。",
    ]


def _nick_v2733_effective_core_yes(a):
    """v273.3｜Core 同步用：前台語意以 final_verdict_payload / 法醫結構參數為最高優先。
    避免 a["core"] 舊值仍是 No/候選時，重點提醒吐出「尚未收編」舊語意。
    """
    try:
        if not isinstance(a, dict):
            return False
        fp = a.get("final_verdict_payload") if isinstance(a.get("final_verdict_payload"), dict) else {}
        vals = [
            fp.get("core"),
            a.get("_forensic_core_effective"),
            a.get("_ai_core"),
            a.get("core"),
        ]
        case = a.get("_ai_core_saved_case") if isinstance(a.get("_ai_core_saved_case"), dict) else {}
        if case:
            vals.extend([
                case.get("core"),
                case.get("Core"),
                case.get("ai_core"),
                case.get("AI Core"),
            ])
        for v in vals:
            s = str(v or "").strip()
            if s == "Yes" or s.lower() in ["core yes", "yes"]:
                return True
            if "Core Yes" in s or "Core：Yes" in s or "Core: Yes" in s:
                return True
        return False
    except Exception:
        return False


def _family_core_alert(a, family_rule):
    core = str(a.get("core", "") or "")
    core_status = str(a.get("core_status", "") or "")
    if core == "Yes" or _nick_v2733_effective_core_yes(a):
        return family_rule.get("core_yes_msg") or "公司可收編，但仍要看財報、估值與買點，不等於現價可重押。"
    if "候選" in core_status:
        return f"目前最多是 {family_rule.get('family_name', '此族群')} 候選，還沒通過完整 Core 硬門檻。"
    return family_rule.get("core_no_msg") or "子模組只代表分析框架；Core 是否成立仍看法醫硬門檻。"


def _family_attack_alert(a):
    attack = str(a.get("attack", "") or "")
    attack_type = str(a.get("attack_type", "") or "")
    action = str(a.get("action", "") or "")
    if attack == "Yes":
        if "回檔" in attack_type:
            return "Attack 條件偏回檔型，仍要看支撐承接與失效點，不適合無腦追高。"
        if "突破" in attack_type:
            return "Attack 偏突破型，必須確認量能、隔日不跌回與法人賣壓不擴大。"
        return "Attack 成立，但仍要照失效點與資金配置執行。"
    if "小倉" in action or "試單" in action or a.get("attack_candidate"):
        return "觀察型小倉不是攻擊倉；要等站回壓力、突破確認或籌碼轉強後才升級。"
    return "Attack 尚未成立，先等回檔承接或突破後回測確認。"


def _nick_v2736_focus_tactical_sentence(a, reason=""):
    """v273.6｜Core Yes + Focus No 的語意一律改成戰術配置，不是否定公司價值。"""
    r = str(reason or "").strip()
    # 先把舊式否定詞轉成前台能理解的戰術語意。
    if any(k in r for k in ["流動性", "成交量", "量能", "換手"]):
        return "公司已可收編，但目前流動性 / 量能還沒到集中火力條件；適合小倉觀察或等量能換手，不適合重押。"
    if any(k in r for k in ["籌碼", "賣壓", "法人", "分歧"]):
        return "公司已可收編，但籌碼還沒完全配合；先看法人賣壓是否縮小與支撐是否守住，不急著集中火力。"
    if any(k in r for k in ["風報比", "估值", "重評", "追價", "位置", "買點"]):
        return "公司已可收編，但目前買點 / 風報比還不夠漂亮；先等回檔或右側確認，不把好公司等同於現在可重押。"
    if any(k in r for k in ["財報", "金庫", "現金流", "營運資金", "EPS", "毛利", "下月", "下季"]):
        return "公司已可收編，但集中火力還需要後續營收、毛利率、EPS 或現金流接棒；目前先用戰術部位觀察。"
    if any(k in r for k in ["波段", "趨勢", "支撐", "回檔", "回測", "突破"]):
        return "公司已可收編，但主攻條件還要看波段結構、支撐回測與突破確認；先照今日防線控風險。"
    return "公司已可收編，但目前還沒到集中火力條件；先看買點、籌碼、流動性與風報比。"


def _nick_v2736_core_focus_tactical_filter(a, alerts):
    """v273.6｜Core Yes 後，前台提醒不能再用否定公司價值的句子。
    Focus No 只能被翻成：不適合集中火力 / 等買點 / 看流動性 / 看籌碼。
    """
    if not _nick_v2733_effective_core_yes(a):
        return alerts
    out = []
    blocked = [
        "Core 尚未收編", "Core尚未收編", "Core 未正式收編", "Core未正式收編",
        "未通過收編門檻", "尚未通過收編門檻", "公司尚未通過收編門檻",
        "未正式通過", "Core 未過", "Core未過", "不能直接讓 Core 成立", "不能直接讓Core成立",
        "不能讓 Core 成立", "不具備收編", "公司不成立",
    ]
    added_focus_tactical = False
    for x in alerts or []:
        s = str(x or "").strip()
        if not s:
            continue
        # Core Yes 情境下，這些否定句直接移除或改寫。
        if any(w in s for w in blocked):
            if "題材" in s or "產品升級" in s:
                msg = "題材可作為追蹤方向；公司已可收編，後續重點看營收、毛利率與 EPS 能否接棒。"
                if msg not in out:
                    out.append(msg)
            continue
        # Focus No 類語意改成戰術配置，不讓使用者誤以為公司不好。
        if "Focus" in s or "集中火力" in s or "主攻" in s:
            msg = _nick_v2736_focus_tactical_sentence(a, s)
            if msg not in out:
                out.append(msg)
                added_focus_tactical = True
            continue
        out.append(x)
    if str((a or {}).get("focus") or "") != "Yes" and not added_focus_tactical:
        out.append(_nick_v2736_focus_tactical_sentence(a, ""))
    return out


def _family_focus_alert(a):
    if str(a.get("focus", "") or "") == "Yes":
        return "主攻成立也要分批執行，不能忽略失效點與估值風險。"
    reasons = a.get("focus_block_reasons") or []
    if _nick_v2733_effective_core_yes(a):
        # v273.6｜Core Yes + Focus No 是戰術配置問題，不是公司價值否定。
        for r in reasons:
            rs = str(r or "")
            if any(w in rs for w in ["Core 未正式收編", "Core未正式收編", "Core 尚未收編", "Core尚未收編", "未通過收編門檻", "未正式通過"]):
                continue
            if rs.strip():
                return _nick_v2736_focus_tactical_sentence(a, rs)
        return _nick_v2736_focus_tactical_sentence(a, "")
    if reasons:
        return simplify_alert_text(reasons[0])
    return "Focus 未成立，不適合集中火力或重押。"


def _family_position_alert(a):
    plan = a.get("plan") or {}
    action = str(a.get("action", "") or "")
    nums = plan.get("num", {}) if isinstance(plan, dict) else {}
    close = None
    try:
        close = to_float((a.get("val") or {}).get("current_price"))
    except Exception:
        close = None
    new_low = nums.get("new_low")
    new_high = nums.get("new_high")
    sh_low = nums.get("shallow_low")
    sh_high = nums.get("shallow_high")
    if close is not None:
        if new_low is not None and new_high is not None and new_low <= close <= new_high:
            return "現價落在主買區內，但仍要看 Core / Attack / Focus 是否同步成立。"
        if sh_low is not None and sh_high is not None and sh_low <= close <= sh_high:
            return "現價在小倉試單區，不是主倉甜點。"
        if new_high is not None and close > new_high:
            return "現價高於主買區，先等回檔小倉 / 不追高，不要把追價當低接。"
        if new_low is not None and close < new_low:
            return "現價低於主買區，先確認是不是基本面轉弱，不要只因便宜就接。"
    if "不追" in action or "等回檔" in action:
        return "目前操作重點是等回檔小倉 / 不追高，不是現價主倉追進。"
    if "小倉" in action or "試單" in action:
        return "目前只適合小倉測承接，還不是主倉甜點。"
    return "買點仍要搭配支撐、壓力與失效點，不要只看公司好不好。"


def _family_chip_alert(a):
    cj = a.get("chip_j") or {}
    txt = str(cj.get("text", "") or "")
    if cj.get("limit_focus") or cj.get("limit_attack"):
        return "籌碼有分歧或調節跡象，短線不宜直接升級 Attack / Focus。"
    if "調節" in txt or "賣" in txt or "分歧" in txt or "換手" in txt:
        return txt[:80]
    return "籌碼只能當輔助驗證，不能取代財報與估值支撐。"


def _dedupe_plain_alerts(items, limit=6):
    seen = set()
    out = []
    for x in items:
        s = simplify_alert_text(x)
        s = str(s or "").strip()
        if not s or s in seen:
            continue
        out.append(s)
        seen.add(s)
        if len(out) >= limit:
            break
    return out


def simplify_alert_text(msg):
    """把防呆/卡關訊息翻成小白看得懂的白話提醒。"""
    s = str(msg or "").strip()
    if not s:
        return ""
    if "市場給高溢價" in s or "現價隱含 PE 高於模型上緣" in s or "現價隱含 PE 遠高於模型上緣" in s:
        return "現在價格不便宜，追價要保守。"
    if "下修區 與 保守區 中間有" in s or "保守區 與 中性 / 基本面支撐區 中間有" in s:
        return "現在價位落在尷尬區，不算便宜，先別急著重壓。"
    if "估值位置未到可觀察區" in s:
        return "現在價格位置還不夠舒服，先觀察比較好。"
    if "Core 未正式收編" in s or "Core未正式收編" in s or "Core 尚未收編" in s:
        return "公司收編條件尚未完全同步，先不要提高到主攻名單。"
    if "財務風險限制 Focus" in s:
        return "成長本體與財報可支撐收編，但現金流 / 存貨 / 應收仍需追蹤，暫時不適合 Focus 重押。"
    if s.startswith("Focus No 原因："):
        return "主攻條件還沒到位，先觀察，不急著重壓。"
    if s.startswith("資料品質："):
        return "有些資料品質普通，先保守看，不要只靠單一數字下決定。"
    if "EPS 可信度偏低" in s or "EPS 可參考但需保守" in s:
        return "獲利數字參考就好，先不要把它當成唯一買進理由。"
    if "法人目標價明顯高於內部模型上緣" in s:
        return "外部目標價比模型樂觀很多，先保守看待。"
    if "交易計畫錯誤" in s or "一致性錯誤" in s:
        return "這筆交易的設定還不夠漂亮，先保守處理。"
    if s.startswith("估值提醒："):
        return s.replace("估值提醒：", "估值提醒：").strip()
    return s


def build_plain_alerts(a, data_quality):
    """整合防呆提醒＋卡關提醒，去重後輸出白話版。

    v1 母模型版：
    - 子模組 / 母模型只提供分析框架與風險提醒。
    - Core / Attack / Focus 仍吃法醫硬門檻的結果。
    - 不再針對單一個股或單一 model_key 寫死提醒。
    """
    raw_alerts = []
    try:
        model_key = ((a.get("val") or {}).get("model_key") or "")
        _family_key, _family_rule = get_model_family_rule(model_key)
        raw_alerts.append(_family_core_alert(a, _family_rule))
        raw_alerts.append(_family_attack_alert(a))
        raw_alerts.append(_family_focus_alert(a))
        raw_alerts.append(_family_position_alert(a))
        raw_alerts.append(_family_chip_alert(a))
    except Exception:
        pass

    # 母模型裁決護欄：只補充 Core 型態 / Attack Gate / Focus Gate，不直接改結論。
    _fd_ctx = a.get("family_decision_context") or {}
    for _fd_note in (_fd_ctx.get("notes") or [])[:3]:
        raw_alerts.append(_fd_note)

    # 保留原本法醫 / 估值 / Focus 防呆，但放在母模型提醒之後，避免長篇系統訊息吃掉主畫面。
    for w in (a.get("warnings") or [])[:4]:
        raw_alerts.append(w)
    # v273.2｜Core 同步防呆：若 final_verdict_payload / 法醫結構已經是 Core Yes，
    # 重點提醒不得再吐出「Core 未正式收編」這種舊卡關語意。
    _fp_for_alert = a.get("final_verdict_payload") if isinstance(a.get("final_verdict_payload"), dict) else {}
    _effective_core_yes = (str(_fp_for_alert.get("core") or a.get("_forensic_core_effective") or a.get("core") or "") == "Yes")
    if a.get("focus") != "Yes":
        for r in (a.get("focus_block_reasons") or [])[:3]:
            _r = str(r or "")
            if _effective_core_yes and any(_w in _r for _w in ["Core 未正式收編", "Core未正式收編", "Core 尚未收編", "Core尚未收編"]):
                continue
            raw_alerts.append(r)

    # v273.6｜估值跨度風險防呆：重評上緣很遠時，要提醒「不是必達目標」。
    try:
        _span_risk = valuation_span_risk_payload(a.get("val") or {})
        if _span_risk.get("active") and _span_risk.get("message"):
            raw_alerts.append(_span_risk.get("message"))
    except Exception:
        pass

    # v273.3｜再次全域清洗：只要 Core 已有效同步為 Yes，
    # 任何舊區塊產出的「未收編 / 不能讓 Core 成立」都不應進入重點提醒。
    if _effective_core_yes:
        _blocked_core_words = [
            "Core 未正式收編", "Core未正式收編", "Core 尚未收編", "Core尚未收編",
            "尚未正式收編", "未正式通過", "未通過收編門檻", "尚未通過收編門檻",
            "公司尚未通過收編門檻", "尚未正式通過 Core", "Core 未過", "Core未過",
        ]
        _rewritten_alerts = []
        for _x in raw_alerts:
            _s = str(_x or "").strip()
            if not _s:
                continue
            if any(_w in _s for _w in _blocked_core_words):
                # 已 Core Yes，不能再保留舊的「未收編」語意。
                continue
            if ("產品升級題材" in _s and ("不能直接讓 Core 成立" in _s or "不能直接讓Core成立" in _s or "不能讓 Core 成立" in _s)):
                _rewritten_alerts.append("產品升級題材可作為追蹤方向；公司已可收編，後續重點看營收、毛利率與 EPS 能否接棒。")
                continue
            if ("題材" in _s and ("不能直接讓 Core 成立" in _s or "不能直接讓Core成立" in _s or "不能讓 Core 成立" in _s)):
                _rewritten_alerts.append("題材只能輔助確認；公司已可收編，操作仍要回到買點、籌碼與風報比。")
                continue
            _rewritten_alerts.append(_x)
        raw_alerts = _rewritten_alerts

    # v273.6｜最後再做一次 Core/Focus 戰術語意濾鏡：
    # Core Yes 後，Focus No 不是否定公司，而是不適合集中火力 / 重押。
    if _effective_core_yes:
        raw_alerts = _nick_v2736_core_focus_tactical_filter(a, raw_alerts)

    data_quality = data_quality or {}
    dq_issues = data_quality.get("issues", []) or []
    if data_quality.get("grade") in ["中", "低"] or dq_issues:
        raw_alerts.append(f"資料品質：{data_quality.get('grade', '中')}｜{data_quality.get('message', '')}")
        raw_alerts.extend(dq_issues[:2])

    return _dedupe_plain_alerts(raw_alerts, limit=6)


def render_sr_table(rows, gap_label="離現價"):
    """目前壓力支撐表：支撐綠、壓力紅，並改成小白看得懂的說明。"""
    if not rows:
        st.info("壓力支撐資料不足。")
        return
    cols = ["類型", "價格", gap_label, "說明"]
    html_rows = []
    for r in rows:
        kind = str(r.get("類型", ""))
        type_cls = "sr-type-support" if kind == "支撐" else "sr-type-pressure"
        gap_cls = "sr-gap-support" if kind == "支撐" else "sr-gap-pressure"
        html_rows.append(
            "<tr>"
            f'<td><span class="{type_cls}">{_html.escape(kind)}</span></td>'
            f'<td class="sr-price">{_html.escape(str(r.get("價格", "—")))}</td>'
            f'<td class="{gap_cls}">{_html.escape(str(r.get("離現價", "—")))}</td>'
            f'<td>{_html.escape(str(r.get("說明", "—")))}</td>'
            "</tr>"
        )
    header = "".join([f"<th>{_html.escape(c)}</th>" for c in cols])
    st.markdown(
        '<div class="sr-table-wrap"><table class="sr-table">'
        f"<thead><tr>{header}</tr></thead><tbody>"
        + "".join(html_rows)
        + "</tbody></table></div>",
        unsafe_allow_html=True,
    )



def detect_volume_k_sr_lines(df, lookback=120, max_each=4, max_lines=None, min_gap_pct=0.003):
    """依 Nick 的「量K支撐壓力」規則找水平線。

    主規則：
    1) 資料必須先由舊到新排序。
    2) 從最新日往回看 lookback 天。
    3) 成交量 > 5日均量，且成交量 > 前一日成交量。
    4) 紅K（close > open）取低點畫支撐。
    5) 綠K（close < open）取高點畫壓力。
    6) 十字K（open == close）先略過。
    7) 支撐 + 壓力合併後，只取「離最新收盤價最近」的 max_lines 條。

    注意：max_each 只保留為舊程式相容參數；現在不再代表支撐4條 + 壓力4條。
    """
    if df is None or len(df) < 6:
        return []
    required = {"date", "open", "max", "min", "close", "Trading_Volume"}
    if not required.issubset(set(df.columns)):
        return []

    work = df.copy()
    work["date"] = pd.to_datetime(work["date"], errors="coerce")
    work = work.dropna(subset=["date"]).sort_values("date").reset_index(drop=True)
    if len(work) < 6:
        return []

    for c in ["open", "max", "min", "close", "Trading_Volume"]:
        work[c] = work[c].apply(to_float)
    work = work.dropna(subset=["open", "max", "min", "close", "Trading_Volume"]).reset_index(drop=True)
    if len(work) < 6:
        return []

    work["vol_ma5"] = work["Trading_Volume"].rolling(5, min_periods=5).mean()
    current_price = to_float(work["close"].iloc[-1])
    if current_price is None or current_price <= 0:
        return []

    # 舊版 max_each=4 原本代表支撐4 + 壓力4；新版改為總線數4。
    try:
        limit = int(max_lines if max_lines is not None else max_each)
    except Exception:
        limit = 4
    limit = max(1, limit)

    candidates = []
    start = max(1, len(work) - int(lookback))

    for i in range(start, len(work)):
        row = work.iloc[i]
        prev = work.iloc[i - 1]
        vol = to_float(row.get("Trading_Volume"))
        vol_ma5 = to_float(row.get("vol_ma5"))
        prev_vol = to_float(prev.get("Trading_Volume"))
        if vol is None or vol_ma5 is None or prev_vol is None:
            continue
        if not (vol > vol_ma5 and vol > prev_vol):
            continue

        o = to_float(row.get("open"))
        c = to_float(row.get("close"))
        h = to_float(row.get("max"))
        l = to_float(row.get("min"))
        if None in [o, c, h, l]:
            continue

        if c > o:
            level_price = l
            source_type = "紅K低點"
            candle_type = "red_low"
        elif c < o:
            level_price = h
            source_type = "綠K高點"
            candle_type = "green_high"
        else:
            continue

        if level_price is None or level_price <= 0:
            continue

        level_kind = "支撐" if level_price <= current_price else "壓力"
        distance = abs(level_price - current_price)
        distance_pct = distance / max(abs(current_price), 1e-9)
        source_date = row.get("date")
        candidates.append({
            "price": float(level_price),
            "source_date": source_date,
            "source_index": int(i),
            "type": source_type,
            "kind": level_kind,
            "candle_type": candle_type,
            "distance": float(distance),
            "distance_pct": float(distance_pct),
            "volume_ratio_ma5": safe_div(vol, vol_ma5),
            "volume_ratio_prev": safe_div(vol, prev_vol),
        })

    # 先用離最新收盤價最近排序；同價位附近只留一條，避免畫面重疊。
    candidates = sorted(candidates, key=lambda x: (x.get("distance", 10**9), -x.get("source_index", 0)))
    selected = []
    for item in candidates:
        p0 = item.get("price")
        if p0 is None:
            continue
        too_close = False
        for kept in selected:
            base = max(abs(kept.get("price", 0)), 1e-9)
            if abs(p0 - kept.get("price", 0)) / base <= min_gap_pct:
                too_close = True
                break
        if too_close:
            continue
        selected.append(item)
        if len(selected) >= limit:
            break

    # 回傳保持「離現價最近」排序，主頁標籤就會依重要性排列。
    return selected

def build_support_resistance_levels(price, plan=None, volume_k_lines=None, reference_price=None):
    """整理目前最重要的支撐 / 壓力，並把 MA/高低點/交易計畫/量K 位階放在一起比較。

    畫線來源仍用已完成日K；表格距離可用盤中即時價作為 reference_price。
    """
    plan = plan or {}
    volume_k_lines = volume_k_lines or []
    nums = plan.get("num", {}) if isinstance(plan, dict) else {}
    if not price or price.get("close") is None:
        return {
            "support_text": "資料不足",
            "pressure_text": "資料不足",
            "summary": "壓力 / 支撐資料不足",
            "rows": [],
        }

    close = price.get("close")
    ref_price = to_float(reference_price)
    if ref_price is None or ref_price <= 0:
        ref_price = to_float(close)
    compare_price = ref_price if ref_price is not None and ref_price > 0 else to_float(close)
    ma20 = price.get("ma20")
    ma60 = price.get("ma60")
    low10 = price.get("low10")  # v21 起不再把 10 日低點列入主支撐；保留欄位避免舊資料相容
    high20 = price.get("high20")
    prev_high20 = price.get("prev_high20")
    wrong = nums.get("wrong")
    stop = nums.get("stop")
    right = nums.get("right")

    supports = []
    if ma20 is not None and compare_price is not None and ma20 <= compare_price * 1.02:
        supports.append(("MA20", ma20, "短線支撐 / 回測觀察"))
    if ma60 is not None:
        supports.append(("MA60", ma60, "波段支撐"))
        supports.append(("MA60容忍線", ma60 * 0.96, "跌破 4% 內仍可觀察，跌破過多轉弱"))
    if wrong is not None:
        supports.append(("短線認錯", wrong, "跌破要降低幻想"))
    if stop is not None:
        supports.append(("波段停損", stop, "波段失效防線"))

    pressures = []
    if ma20 is not None and compare_price is not None and ma20 >= compare_price * 0.98:
        pressures.append(("MA20", ma20, "站回代表短線修復"))
    if prev_high20 is not None:
        pressures.append(("前20日壓力", prev_high20, "右側突破觀察"))
    if high20 is not None:
        pressures.append(("20日壓力", high20, "近期上檔壓力"))
    if right is not None:
        pressures.append(("突破確認", right, "收盤突破且量能升溫"))

    base_refs = []
    for _k, _v, _note in supports + pressures:
        if _v is not None:
            base_refs.append((_k, _v))

    def _near_ref_text(level):
        try:
            lf = float(level)
        except Exception:
            return ""
        nearest = None
        for label, ref in base_refs:
            if ref is None:
                continue
            diff = abs(lf - ref) / max(abs(ref), 1e-9)
            if nearest is None or diff < nearest[0]:
                nearest = (diff, label, ref)
        if nearest is None:
            return ""
        diff, label, ref = nearest
        if diff <= 0.012:
            return f"｜與 {label} {fmt_price(ref)} 接近"
        if diff <= 0.025:
            return f"｜接近 {label}（差約 {diff*100:.1f}%）"
        return "｜獨立量K位階"

    # 量K支撐 / 壓力也放入同一組清單，讓主畫面直接和 MA / 20日高低點 / 交易計畫價位比較。
    _s_no, _r_no = 0, 0
    for _line in volume_k_lines:
        _p = to_float(_line.get("price"))
        if _p is None or _p <= 0:
            continue
        _kind = "支撐" if (compare_price is not None and _p <= compare_price) else "壓力"
        if _kind == "支撐":
            _s_no += 1
            _label = f"量K S{_s_no}"
        else:
            _r_no += 1
            _label = f"量K R{_r_no}"
        _dt = _line.get("source_date")
        try:
            _dt_s = pd.to_datetime(_dt).strftime("%m/%d") if _dt is not None else "—"
        except Exception:
            _dt_s = "—"
        _ratio = _line.get("volume_ratio_ma5")
        _ratio_s = f"量/5均 {_ratio:.2f}x" if _ratio is not None else "量能放大"
        _note = f"{_line.get('type', '量K來源')}｜來源 {_dt_s}｜{_ratio_s}{_near_ref_text(_p)}"
        if _kind == "支撐":
            supports.append((_label, _p, _note))
        else:
            pressures.append((_label, _p, _note))

    # 取離現價最近、且有意義的支撐 / 壓力。
    # 規則：摘要卡優先抓圖上那組量K水平線，避免 MA20 / 認錯線 跟壓力撞在一起讓小白困惑。
    below = [(k, v, note) for k, v, note in supports if v is not None and compare_price is not None and v <= compare_price]
    above = [(k, v, note) for k, v, note in pressures if v is not None and compare_price is not None and v >= compare_price]
    below_sorted = sorted(below, key=lambda x: abs(compare_price - x[1]))
    above_sorted = sorted(above, key=lambda x: abs(compare_price - x[1]))

    volume_below_sorted = [x for x in below_sorted if str(x[0]).startswith("量K S")]
    volume_above_sorted = [x for x in above_sorted if str(x[0]).startswith("量K R")]

    main_support = (
        volume_below_sorted[0]
        if volume_below_sorted
        else (below_sorted[0] if below_sorted else ("現價附近", close, "暫以現價觀察"))
    )
    main_pressure = (
        volume_above_sorted[0]
        if volume_above_sorted
        else (above_sorted[0] if above_sorted else ("短線反壓", compare_price * 1.03 if compare_price else close * 1.03, "暫估短線反壓"))
    )

    def _simple_sr_note(kind, label, note):
        label = str(label or "")
        note = str(note or "")
        if kind == "支撐":
            if label == "MA20":
                return "靠近短線均線，先看這裡能不能守住。"
            if label == "MA60":
                return "這是波段支撐，守住代表大方向還沒壞。"
            if label == "MA60容忍線":
                return "再跌下去就偏弱了，這裡是最後容忍區。"
            if label == "短線認錯":
                return "跌破這裡，短線想法就要先保守。"
            if label == "波段停損":
                return "跌破這裡，代表這一段波段大致失效。"
            if label.startswith("量K S"):
                return "前面有量的支撐區，守住有機會止跌。"
            return "這裡是下方支撐，先看股價能不能守住。"
        else:
            if label == "MA20":
                return "先站回短線均線，短線才比較像轉強。"
            if label in ["前20日壓力", "20日壓力"]:
                return "這裡是近期上方壓力，突破才算更強。"
            if label == "突破確認":
                return "站上這裡，才比較像真的轉強。"
            if label.startswith("量K R"):
                return "前面有量的壓力區，來到這裡容易先卡住。"
            return "這裡是上方壓力，要突破才有機會續攻。"

    def _row(kind, item):
        k, v, note = item
        gap = pct_change(v, ref_price) if ref_price else None
        return {
            "類型": kind,
            "價格": fmt_price(v),
            "離現價": fmp(gap),
            "說明": _simple_sr_note(kind, k, note),
        }

    rows = []
    for item in below_sorted[:6]:
        rows.append(_row("支撐", item))
    for item in above_sorted[:6]:
        rows.append(_row("壓力", item))

    # App 內不顯示像「量K S1 / R1」這種技術代號，只保留小白看得懂的白話結果。
    support_text = f"最近支撐 {fmt_price(main_support[1])}"
    pressure_text = f"最近壓力 {fmt_price(main_pressure[1])}"
    summary = f"{support_text}｜{pressure_text}"

    return {
        "support_text": support_text,
        "pressure_text": pressure_text,
        "summary": summary,
        "rows": rows,
        "volume_k_count": len(volume_k_lines),
        "main_support": main_support[1],
        "main_pressure": main_pressure[1],
    }


def _prepare_price_chart_df(price):
    """整理股價明細資料，供主頁快照圖與技術分頁共用。"""
    _raw = price.get("raw") if price else None
    if _raw is None or getattr(_raw, "empty", True):
        return None, "無股價明細資料。"

    _df = _raw.copy().reset_index(drop=True)
    _df["date"] = pd.to_datetime(_df["date"], errors="coerce")
    _df = _df.dropna(subset=["date"]).sort_values("date").reset_index(drop=True)
    if _df.empty:
        return None, "股價日期資料不足。"

    for _c in ["open", "max", "min", "close", "Trading_Volume"]:
        if _c in _df.columns:
            _df[_c] = _df[_c].apply(to_float)
    _df = _df.dropna(subset=["open", "max", "min", "close"]).reset_index(drop=True)
    if len(_df) < 10:
        return None, "K線資料不足。"
    return _df, ""


def _sanitize_ohlc_for_chart(df, realtime_quote=None):
    """fix77｜K線畫圖專用 OHLC 防呆。

    盤中資料源偶爾會把 open/high/low 回傳 0、空字串或異常值；
    若直接丟給 Plotly Candlestick，手機圖會出現一根從 0 拉到現價的長針。

    原則：
    - 只修「畫圖用」DataFrame，不改支撐壓力、均線、法醫裁決來源。
    - 若 OHLC 某欄 <= 0，用 close / open / 前收 / 即時價補合理值。
    - high 一定 >= open/close/low，low 一定 <= open/close/high，且 low 不能 <= 0。
    """
    if df is None or getattr(df, "empty", True):
        return df
    work = df.copy().reset_index(drop=True)
    for _c in ["open", "max", "min", "close", "Trading_Volume"]:
        if _c in work.columns:
            work[_c] = work[_c].apply(to_float)

    rt_price = to_float((realtime_quote or {}).get("price"))
    rt_prev = to_float((realtime_quote or {}).get("prev_close"))

    prev_close = None
    for i in range(len(work)):
        c = to_float(work.at[i, "close"]) if "close" in work.columns else None
        o = to_float(work.at[i, "open"]) if "open" in work.columns else None
        h = to_float(work.at[i, "max"]) if "max" in work.columns else None
        l = to_float(work.at[i, "min"]) if "min" in work.columns else None

        # 最後一根若是盤中K，優先讓 close 貼近即時價。
        if i == len(work) - 1 and rt_price is not None and rt_price > 0:
            c = rt_price if c is None or c <= 0 else c

        base = None
        for v in [c, o, prev_close, rt_prev, rt_price]:
            if v is not None and v > 0:
                base = v
                break
        if base is None:
            continue

        if c is None or c <= 0:
            c = base
        if o is None or o <= 0:
            o = rt_prev if (i == len(work) - 1 and rt_prev is not None and rt_prev > 0) else base
        if h is None or h <= 0:
            h = max(o, c, base)
        if l is None or l <= 0:
            l = min(o, c, base)

        h = max(h, o, c, l)
        l = min(l, o, c, h)
        if l is None or l <= 0:
            l = min([v for v in [o, c, h, base] if v is not None and v > 0])

        work.at[i, "open"] = o
        work.at[i, "max"] = h
        work.at[i, "min"] = l
        work.at[i, "close"] = c
        prev_close = c if c is not None and c > 0 else prev_close

    # 最後再把無效列移除，避免任何 0 值被畫進K棒。
    for _c in ["open", "max", "min", "close"]:
        if _c in work.columns:
            work = work[work[_c].apply(lambda x: to_float(x) is not None and to_float(x) > 0)]
    return work.reset_index(drop=True)



def _build_20d_inst_cost_estimate_lines(price_df, inst):
    """建立 20 日法人估算成本線。

    重要說明：
    - 外資 / 投信：使用法人買賣超資料中的淨買超股數，搭配每日收盤價估算。
    - 法人：使用三大法人合計淨買均價估算；不是券商分點主力成本。
    - 不是券商真實成交成本，只作籌碼承接位置參考。
    """
    try:
        if price_df is None or getattr(price_df, "empty", True) or not inst:
            return {}, []
        raw = inst.get("raw") if isinstance(inst, dict) else None
        if raw is None or getattr(raw, "empty", True):
            return {}, []

        px = price_df.copy()
        if "date" not in px.columns or "close" not in px.columns:
            return {}, []
        px["_dt"] = pd.to_datetime(px["date"], errors="coerce").dt.normalize()
        px["_close"] = px["close"].apply(to_float)
        px = px.dropna(subset=["_dt", "_close"]).sort_values("_dt")
        if px.empty:
            return {}, []

        idf = raw.copy()
        if "date" not in idf.columns:
            return {}, []
        idf["_dt"] = pd.to_datetime(idf["date"], errors="coerce").dt.normalize()

        # fetch_inst 目前會保留 net / investor_zh；若未來資料結構變動，這裡做防呆。
        if "net" not in idf.columns:
            buy_col = pick_col(idf.columns, ["buy", "買"])
            sell_col = pick_col(idf.columns, ["sell", "賣"])
            if buy_col is None or sell_col is None:
                return {}, []
            idf[buy_col] = idf[buy_col].apply(to_float)
            idf[sell_col] = idf[sell_col].apply(to_float)
            idf["net"] = idf[buy_col] - idf[sell_col]
        else:
            idf["net"] = idf["net"].apply(to_float)

        if "investor_zh" not in idf.columns:
            name_col = pick_col(idf.columns, ["name", "investor", "法人"])
            if name_col:
                idf["investor_zh"] = idf[name_col].apply(investor_display_name)
            else:
                idf["investor_zh"] = "法人合計"

        idf = idf.dropna(subset=["_dt"])
        if idf.empty:
            return {}, []

        close_map = dict(zip(px["_dt"], px["_close"]))
        trade_dates = list(px["_dt"].tolist())

        def _daily_for(kind):
            tmp = idf.copy()
            if kind == "foreign":
                tmp = tmp[tmp["investor_zh"] == "外資"]
                label = "外資20日估成本"
                color = "#22d3ee"
            elif kind == "trust":
                tmp = tmp[tmp["investor_zh"] == "投信"]
                label = "投信20日估成本"
                color = "#f97316"
            else:
                # 法人線：用三大法人合計的淨買均價估算。不是券商分點主力成本。
                label = "法人20日估成本"
                color = "#e879f9"
            if tmp.empty:
                return None, label, color
            d = tmp.groupby("_dt", as_index=False)["net"].sum().sort_values("_dt")
            return d, label, color

        lines = {}
        notes = []
        for kind in ["smart_proxy", "foreign", "trust"]:
            daily, label, color = _daily_for(kind)
            if daily is None or daily.empty:
                continue
            net_map = dict(zip(daily["_dt"], daily["net"]))
            vals = []
            latest_total_lot = None
            latest_buy_days = None
            latest_value = None
            for i, dt in enumerate(trade_dates):
                win_dates = trade_dates[max(0, i - 19): i + 1]
                total = 0.0
                weighted = 0.0
                buy_days = 0
                for d0 in win_dates:
                    net = to_float(net_map.get(d0))
                    close = to_float(close_map.get(d0))
                    # 成本估算只看淨買超日；淨賣日不是買進成本。
                    if net is not None and net > 0 and close is not None and close > 0:
                        total += net
                        weighted += net * close
                        buy_days += 1
                val = (weighted / total) if total > 0 else None
                vals.append(val)
                if i == len(trade_dates) - 1:
                    latest_total_lot = int(round(total / 1000)) if total > 0 else 0
                    latest_buy_days = buy_days
                    latest_value = val
            if any(v is not None for v in vals):
                lines[kind] = {
                    "label": label,
                    "color": color,
                    "values_by_date": dict(zip(trade_dates, vals)),
                    "latest": latest_value,
                    "latest_total_lot": latest_total_lot,
                    "latest_buy_days": latest_buy_days,
                }
                _note_name = "法人" if kind == "smart_proxy" else ("外資" if kind == "foreign" else "投信")
                if latest_value is not None:
                    notes.append(f"{_note_name} {fmt_price(latest_value)}（買進{latest_buy_days}/20天，約{latest_total_lot:+,}張）")
                else:
                    notes.append(f"{_note_name} 近20日無有效淨買成本")
        return lines, notes
    except Exception:
        return {}, []

def render_volume_k_sr_chart(price, stock, name, volume_k_lines=None, expanded=True, expander_title="📈 支撐壓力快照（主頁）", enable_hover=True, realtime_quote=None, inst=None):
    """主頁用：K線 + 最近股價附近 4 條量K支撐壓力水平延伸線。

    手機版優化重點：
    - 不放成交量、KD、副圖。
    - X軸改用K棒序號，避免假日/未來日期把K棒壓扁。
    - 自動從最早來源K棒再往前多保留幾根K棒。
    - 標籤固定在圖內右側，不撐開時間軸。
    """
    _df_full, _err = _prepare_price_chart_df(price)
    if _df_full is None:
        st.warning(f"無法顯示支撐壓力快照：{_err}")
        return

    # 支撐壓力線仍以原始已完成日K計算；盤中K只補到圖上顯示。
    _volume_k_lines = volume_k_lines if volume_k_lines is not None else detect_volume_k_sr_lines(_df_full, lookback=120, max_lines=4)
    _volume_k_lines = (_volume_k_lines or [])[:4]

    _df_full, _intraday_added = _append_intraday_k_to_chart_df(_df_full, realtime_quote)
    # fix77｜不管盤中K是從即時資料補進來，還是資料源本身已帶今日K，
    # 畫圖前都再清一次 0 / 異常 OHLC，避免K棒直插到 0。
    _df_full = _sanitize_ohlc_for_chart(_df_full, realtime_quote)
    _close = to_float(realtime_quote.get("price")) if realtime_quote else None
    if _close is None:
        _close = to_float(_df_full["close"].iloc[-1])

    # 主頁快照自動裁切：先找最近4條線裡「最早來源K棒」，再往前多留4根K棒，避免畫面太貼邊。
    # 若暫時沒有量K線，才退回近45日。
    _pad_bars_left = 4
    _valid_source_indices = []
    for _line in _volume_k_lines:
        _idx = _line.get("source_index")
        try:
            _idx = int(_idx)
        except Exception:
            _idx = None
        if _idx is not None and 0 <= _idx < len(_df_full):
            _valid_source_indices.append(_idx)

    if _valid_source_indices:
        _start_idx = max(0, min(_valid_source_indices) - _pad_bars_left)
        _df = _df_full.iloc[_start_idx:].copy().reset_index(drop=True)
        _chart_start_date = _df["date"].iloc[0]
        _window_label = f"自動截圖：{pd.to_datetime(_chart_start_date).strftime('%m/%d')} 到最新"
    else:
        _chart_start = _df_full["date"].iloc[-1] - pd.Timedelta(days=45)
        _df = _df_full[_df_full["date"] >= _chart_start].copy().reset_index(drop=True)
        _window_label = "近45日快照"

    if len(_df) < 6:
        _df = _df_full.tail(12).copy().reset_index(drop=True)
        if len(_df) < 3:
            st.warning("K線資料不足，無法顯示支撐壓力快照。")
            return

    # 手機版關鍵：主頁快照用序號當X軸，K棒會變寬，不會被週末/未來日期空白擠壓。
    _df["_x"] = list(range(len(_df)))
    _last_x_num = int(_df["_x"].iloc[-1])

    # 日期 -> 圖上序號，用於把水平線起點精準對到來源K棒。
    _date_to_x = {}
    for _i, _dt in enumerate(_df["date"]):
        try:
            _date_to_x[pd.to_datetime(_dt).normalize()] = _i
        except Exception:
            pass

    def _source_x_num(_source_date):
        _dt = pd.to_datetime(_source_date, errors="coerce")
        if pd.isna(_dt):
            return 0
        _dt_n = _dt.normalize()
        if _dt_n in _date_to_x:
            return _date_to_x[_dt_n]
        # 若遇到日期格式落差，就找最接近但不晚於來源日的K棒。
        _dates = pd.to_datetime(_df["date"], errors="coerce")
        _mask = _dates <= _dt
        if _mask.any():
            return int(_mask[_mask].index[-1])
        return 0

    _fig = go.Figure()
    _fig.add_trace(
        go.Candlestick(
            x=_df["_x"],
            open=_df["open"],
            high=_df["max"],
            low=_df["min"],
            close=_df["close"],
            increasing_line_color="#f85149",
            increasing_fillcolor="#f85149",
            decreasing_line_color="#3fb950",
            decreasing_fillcolor="#3fb950",
            name="K線",
            showlegend=False,
            line=dict(width=1.25),
            whiskerwidth=0.25,
            hoverinfo=("skip" if not enable_hover else None),
        )
    )

    # 主頁快照補上 5 / 10 / 20 / 60 日均線，不顯示均線數值標籤。
    # v60｜Nick：支撐壓力快照也加入 MA60，方便判斷波段支撐。
    _ma_specs = [
        ("MA5", "#f59e0b", 1.1),
        ("MA10", "#60a5fa", 1.15),
        ("MA20", "#a78bfa", 1.2),
        ("MA60", "#a855f7", 1.25),
    ]
    for _ma_col, _ma_color, _ma_width in _ma_specs:
        if _ma_col in _df.columns:
            _ma_series = _df[_ma_col].apply(to_float)
            if _ma_series.notna().sum() >= 2:
                _fig.add_trace(
                    go.Scatter(
                        x=_df["_x"],
                        y=_ma_series,
                        mode="lines",
                        line=dict(color=_ma_color, width=_ma_width),
                        name=_ma_col,
                        showlegend=False,
                        hoverinfo="skip",
                        opacity=0.92,
                    )
                )

    # v62｜20日法人估算成本線：法人合計 / 外資 / 投信。
    # 注意：這不是券商真實成交成本，而是用淨買超股數 × 每日收盤價估算，作為籌碼承接參考。
    _inst_cost_lines, _inst_cost_notes = _build_20d_inst_cost_estimate_lines(_df_full, inst)
    for _kind, _info in (_inst_cost_lines or {}).items():
        _series = []
        for _dt in _df["date"]:
            _key = pd.to_datetime(_dt, errors="coerce")
            _key = _key.normalize() if not pd.isna(_key) else None
            _series.append((_info.get("values_by_date") or {}).get(_key))
        _series = pd.Series(_series).apply(to_float)
        if _series.notna().sum() >= 2:
            _fig.add_trace(
                go.Scatter(
                    x=_df["_x"],
                    y=_series,
                    mode="lines",
                    line=dict(color=_info.get("color", "#e879f9"), width=1.55, dash="dot"),
                    name=_info.get("label", "20日估成本"),
                    showlegend=False,
                    hoverinfo="skip",
                    opacity=0.92,
                )
            )

    if _intraday_added:
        try:
            _intraday_y = to_float(_df["close"].iloc[-1]) or to_float(_df["max"].iloc[-1])
            _fig.add_annotation(
                x=_last_x_num + 0.62,
                y=_intraday_y,
                text="盤中",
                showarrow=False,
                xanchor="left",
                yanchor="middle",
                font=dict(size=10, color="#facc15"),
                bgcolor="rgba(13,17,23,0.70)",
                bordercolor="#facc15",
                borderwidth=1,
                borderpad=2,
            )
        except Exception:
            pass

    # Y軸依照目前截圖K棒 + 4條線共同計算，留上下空間，避免壓縮在一起。
    _y_values = []
    for _c in ["max", "min", "close", "MA5", "MA10", "MA20", "MA60"]:
        if _c in _df.columns:
            _y_values.extend([v for v in _df[_c].apply(to_float).tolist() if v is not None])
    for _info in (_inst_cost_lines or {}).values():
        _vals = _info.get("values_by_date") or {}
        for _dt in _df["date"]:
            _key = pd.to_datetime(_dt, errors="coerce")
            _key = _key.normalize() if not pd.isna(_key) else None
            _v = to_float(_vals.get(_key))
            if _v is not None:
                _y_values.append(_v)
    _y_values.extend([to_float(_line.get("price")) for _line in _volume_k_lines if to_float(_line.get("price")) is not None])
    _y_min = min(_y_values) if _y_values else None
    _y_max = max(_y_values) if _y_values else None
    _y_range = None
    _y_span = None
    if _y_min is not None and _y_max is not None and _y_max > _y_min:
        _y_span = _y_max - _y_min
        _pad = max(_y_span * 0.12, abs(_close or _y_max) * 0.006)
        _y_range = [_y_min - _pad, _y_max + _pad]

    # 價位很近時，右側標籤改用「實際價位不動、標籤位置錯開」避免重疊。
    _label_ypos = {}
    _entries = []
    for _idx, _line in enumerate(_volume_k_lines):
        _p = to_float(_line.get("price"))
        if _p is not None:
            _entries.append((_idx, _p))
    if _entries and _y_span:
        _entries_sorted = sorted(_entries, key=lambda x: x[1])
        _min_sep = max(_y_span * 0.065, max(abs(_close or _y_max or 0), 1e-9) * 0.012)
        _clusters = []
        _cluster = []
        for _item in _entries_sorted:
            if not _cluster:
                _cluster = [_item]
                continue
            if abs(_item[1] - _cluster[-1][1]) <= _min_sep:
                _cluster.append(_item)
            else:
                _clusters.append(_cluster)
                _cluster = [_item]
        if _cluster:
            _clusters.append(_cluster)

        _lower = (_y_range[0] if _y_range else _y_min - _y_span * 0.08)
        _upper = (_y_range[1] if _y_range else _y_max + _y_span * 0.08)
        for _cluster in _clusters:
            _n = len(_cluster)
            if _n == 1:
                _label_ypos[_cluster[0][0]] = _cluster[0][1]
                continue
            _center = sum(_p for _, _p in _cluster) / max(_n, 1)
            _start = _center - ((_n - 1) / 2.0) * _min_sep
            _proposed = [_start + _j * _min_sep for _j in range(_n)]
            if _proposed[0] < _lower:
                _shift = _lower - _proposed[0]
                _proposed = [_v + _shift for _v in _proposed]
            if _proposed[-1] > _upper:
                _shift = _proposed[-1] - _upper
                _proposed = [_v - _shift for _v in _proposed]
            for (_i0, _orig_y), _adj_y in zip(_cluster, _proposed):
                _label_ypos[_i0] = _adj_y

    _support_no = 0
    _pressure_no = 0
    for _idx, _line in enumerate(_volume_k_lines):
        _kind = _line.get("kind", "")
        if _kind == "支撐":
            _support_no += 1
            _tag = f"S{_support_no}"
            _col_l = "#3fb950"
        else:
            _pressure_no += 1
            _tag = f"R{_pressure_no}"
            _col_l = "#f85149"
        _source_date = _line.get("source_date")
        _level_y = to_float(_line.get("price"))
        if _source_date is None or _level_y is None:
            continue
        _x0 = _source_x_num(_source_date)

        # 水平線從來源K棒延伸到最新K棒，不從最左邊開始。
        _fig.add_shape(
            type="line",
            x0=_x0,
            x1=_last_x_num,
            y0=_level_y,
            y1=_level_y,
            xref="x",
            yref="y",
            line=dict(color=_col_l, width=2.3, dash="solid"),
            opacity=0.9,
        )
        _fig.add_trace(
            go.Scatter(
                x=[_x0],
                y=[_level_y],
                mode="markers",
                marker=dict(color=_col_l, size=8, symbol="circle"),
                showlegend=False,
                hoverinfo=("skip" if not enable_hover else None),
                hovertemplate=(
                    None if not enable_hover else (
                        f"{_tag}｜{_line.get('kind', '')}<br>"
                        "價位：%{y:,.2f}<br>"
                        f"來源：{_line.get('type', '')}<br>"
                        f"來源日：{pd.to_datetime(_source_date).strftime('%Y-%m-%d') if _source_date is not None else '—'}<extra></extra>"
                    )
                ),
            )
        )
        _gap = pct_change(_level_y, _close) if _close else None
        _gap_s = f" ({fmp(_gap)})" if _gap is not None else ""
        _label_y = to_float(_label_ypos.get(_idx)) or _level_y
        if abs(_label_y - _level_y) > 1e-9:
            _fig.add_shape(
                type="line",
                x0=_last_x_num,
                x1=_last_x_num + 0.18,
                y0=_level_y,
                y1=_label_y,
                xref="x",
                yref="y",
                line=dict(color=_col_l, width=1.0, dash="dot"),
                opacity=0.75,
            )
        _fig.add_annotation(
            x=0.985,
            y=_label_y,
            xref="paper",
            yref="y",
            text=f"{fmt_price(_level_y)}{_gap_s}",
            showarrow=False,
            xanchor="right",
            yanchor="middle",
            font=dict(size=11, color=_col_l),
            bgcolor="rgba(13,17,23,0.82)",
            bordercolor=_col_l,
            borderwidth=1,
            borderpad=3,
        )

    # X軸只顯示少量日期刻度，避免手機底部太擠。
    _n = len(_df)
    if _n <= 6:
        _tick_vals = list(range(_n))
    else:
        _tick_vals = sorted(set([0, max(0, _n // 3), max(0, _n * 2 // 3), _n - 1]))
    _tick_text = [pd.to_datetime(_df["date"].iloc[_i]).strftime("%m/%d") for _i in _tick_vals]

    _bg = "#0d1117"
    _grid = "#21262d"
    _txt = "#c9d1d9"
    _fig.update_layout(
        height=505,
        paper_bgcolor=_bg,
        plot_bgcolor=_bg,
        font=dict(color=_txt, size=11),
        margin=dict(l=36, r=18, t=16, b=34),
        hovermode=("x unified" if enable_hover else False),
        hoverlabel=dict(bgcolor="rgba(15,23,42,0.40)", font_color="#ffffff", bordercolor="rgba(148,163,184,0.35)"),
        showlegend=False,
        dragmode="pan",
    )
    _axis_style = dict(gridcolor=_grid, linecolor=_grid, showgrid=True, zeroline=False, tickfont=dict(color=_txt, size=10))
    _fig.update_xaxes(
        **_axis_style,
        range=[-0.7, _last_x_num + (1.48 if _intraday_added else 0.45)],
        tickmode="array",
        tickvals=_tick_vals,
        ticktext=_tick_text,
        rangeslider=dict(visible=False),
        fixedrange=False,
    )
    # v60｜主頁支撐壓力快照：X 軸保留左右滑動；Y 軸鎖定，避免手機拖曳時上下跑掉。
    if _y_range:
        _fig.update_yaxes(**_axis_style, title_text=None, range=_y_range, fixedrange=True, automargin=True)
    else:
        _fig.update_yaxes(**_axis_style, title_text=None, fixedrange=True, automargin=True)

    with st.expander(expander_title, expanded=expanded):
        st.markdown(
            '<div style="color:#6e7681;font-size:12px;margin-bottom:4px;line-height:1.8">'
            '<span style="color:#f59e0b">■</span> MA5 &nbsp;'
            '<span style="color:#60a5fa">■</span> MA10 &nbsp;'
            '<span style="color:#a78bfa">■</span> MA20 &nbsp;'
            '<span style="color:#a855f7">■</span> MA60 &nbsp;│&nbsp;'
            '<span style="color:#e879f9">···</span> 法人 &nbsp;'
            '<span style="color:#22d3ee">···</span> 外資 &nbsp;'
            '<span style="color:#f97316">···</span> 投信 &nbsp;│&nbsp;'
            '<span style="color:#f85149">──</span> 壓力 &nbsp;'
            '<span style="color:#3fb950">──</span> 支撐 &nbsp;│&nbsp;'
            '左右可滑，Y軸已鎖定'
            '</div>',
            unsafe_allow_html=True,
        )
        st.plotly_chart(
            _fig,
            use_container_width=True,
            config={
                "scrollZoom": True,
                "displayModeBar": False,
                "displaylogo": False,
            },
        )
        if _inst_cost_notes:
            st.caption("20日成本線＝估算值：" + "｜".join(_inst_cost_notes) + "。法人＝三大法人合計估算，非券商分點主力真成本。")
        else:
            st.caption("20日成本線：法人資料不足或近20日無有效淨買成本，暫不畫線。")
        if _volume_k_lines:
            with st.expander("🔒 量K來源明細", expanded=False):
                if nick_private_gate("量K來源明細", f"volume_k_sources_{abs(hash(str(expander_title))) % 100000}"):
                    st.caption("規則：近120日內，成交量 > 5日均量且 > 前一日量；紅K取低點，綠K取高點；十字K先略過。")
                    _sr_rows = []
                    for _idx, _line in enumerate(_volume_k_lines, start=1):
                        _sr_rows.append({
                            "重要性": _idx,
                            "類型": _line.get("kind"),
                            "價位": fmt_price(_line.get("price")),
                            "離現價": fmp(pct_change(_line.get("price"), _close)) if _close else "—",
                            "來源K棒": pd.to_datetime(_line.get("source_date")).strftime("%Y-%m-%d") if _line.get("source_date") is not None else "—",
                            "來源判斷": _line.get("type"),
                            "量/5日均量": f"{_line.get('volume_ratio_ma5'):.2f}x" if _line.get("volume_ratio_ma5") is not None else "—",
                            "量/前日量": f"{_line.get('volume_ratio_prev'):.2f}x" if _line.get("volume_ratio_prev") is not None else "—",
                        })
                    st.dataframe(pd.DataFrame(_sr_rows), use_container_width=True, hide_index=True)
        else:
            st.caption("📌 量K壓力支撐線：近120日暫無符合條件的紅K/綠K來源。")

def render_technical_k_chart(price, stock, name, volume_k_lines=None, expanded=True):
    """技術分頁用：完整技術K線圖，保留均線、成交量、KD。

    資料與指標用完整股價資料計算；但初始視窗只顯示最近約1.5個月（45日）。
    """
    _df_full, _err = _prepare_price_chart_df(price)
    if _df_full is None:
        st.warning(f"無法顯示技術K線圖：{_err}")
        return

    _df = _df_full.copy().reset_index(drop=True)
    _x_end = _df["date"].max()
    _x_init_start = _x_end - pd.Timedelta(days=45)
    _volume_k_lines = volume_k_lines if volume_k_lines is not None else detect_volume_k_sr_lines(_df, lookback=120, max_lines=4)

    _low9_f = _df["min"].rolling(9, min_periods=1).min()
    _high9_f = _df["max"].rolling(9, min_periods=1).max()
    _rsv_f = (_df["close"] - _low9_f) / (_high9_f - _low9_f + 1e-9) * 100
    _ks_f, _ds_f = [], []
    _k, _d = 50.0, 50.0
    for _r in _rsv_f:
        _k = _k * 2 / 3 + _r * 1 / 3
        _d = _d * 2 / 3 + _k * 1 / 3
        _ks_f.append(round(_k, 2))
        _ds_f.append(round(_d, 2))
    _df["_K"] = _ks_f
    _df["_D"] = _ds_f

    _vol_colors = []
    for _, _row in _df.iterrows():
        _o = _row.get("open")
        _c = _row.get("close")
        if _o is None or _c is None or _c == _o:
            _vol_colors.append("#6e7681")
        elif _c > _o:
            _vol_colors.append("#f85149")
        else:
            _vol_colors.append("#3fb950")

    _vol_lots = (
        _df["Trading_Volume"].apply(lambda x: (x / 1000) if (x is not None and not pd.isna(x)) else 0)
        if "Trading_Volume" in _df.columns
        else pd.Series([0] * len(_df))
    )

    _fig = make_subplots(rows=3, cols=1, shared_xaxes=True, vertical_spacing=0.025, row_heights=[0.55, 0.25, 0.20])
    _fig.add_trace(
        go.Candlestick(
            x=_df["date"],
            open=_df["open"],
            high=_df["max"],
            low=_df["min"],
            close=_df["close"],
            increasing_line_color="#f85149",
            increasing_fillcolor="#f85149",
            decreasing_line_color="#3fb950",
            decreasing_fillcolor="#3fb950",
            name="K線",
            showlegend=False,
            line=dict(width=1),
            whiskerwidth=0,
        ),
        row=1,
        col=1,
    )

    for _ma, _col in [("MA5", "#f59e0b"), ("MA10", "#0B6E4F"), ("MA20", "#3b82f6"), ("MA60", "#a855f7")]:
        if _ma in _df.columns:
            _fig.add_trace(
                go.Scatter(x=_df["date"], y=_df[_ma], name=_ma, mode="lines", line=dict(color=_col, width=1.4), showlegend=False),
                row=1,
                col=1,
            )

    _fig.add_trace(go.Bar(x=_df["date"], y=_vol_lots, marker_color=_vol_colors, name="成交量（張）", showlegend=False), row=2, col=1)
    if "VolMA20" in _df.columns:
        _fig.add_trace(
            go.Scatter(x=_df["date"], y=(_df["VolMA20"] / 1000).round(0), name="VolMA20", mode="lines", line=dict(color="#f59e0b", width=1.5), showlegend=False),
            row=2,
            col=1,
        )
    _fig.add_trace(go.Scatter(x=_df["date"], y=_df["_K"], name="K", mode="lines", line=dict(color="#f59e0b", width=1.5), showlegend=False), row=3, col=1)
    _fig.add_trace(go.Scatter(x=_df["date"], y=_df["_D"], name="D", mode="lines", line=dict(color="#3b82f6", width=1.5), showlegend=False), row=3, col=1)
    _fig.add_hline(y=80, line=dict(color="#6e7681", width=1, dash="dash"), row=3, col=1)
    _fig.add_hline(y=20, line=dict(color="#6e7681", width=1, dash="dash"), row=3, col=1)

    _last_x = _df["date"].iloc[-1]
    _support_no = 0
    _pressure_no = 0
    for _line in (_volume_k_lines or [])[:4]:
        _kind = _line.get("kind", "")
        if _kind == "支撐":
            _support_no += 1
            _tag = f"S{_support_no}"
            _col_l = "#3fb950"
        else:
            _pressure_no += 1
            _tag = f"R{_pressure_no}"
            _col_l = "#f85149"
        _source_x = _line.get("source_date")
        _level_y = _line.get("price")
        if _source_x is None or _level_y is None:
            continue
        _source_x = pd.to_datetime(_source_x, errors="coerce")
        if pd.isna(_source_x):
            continue
        _fig.add_shape(
            type="line",
            x0=_source_x,
            x1=_last_x,
            y0=_level_y,
            y1=_level_y,
            xref="x",
            yref="y",
            line=dict(color=_col_l, width=1.8, dash="solid"),
            opacity=0.78,
            row=1,
            col=1,
        )
        _fig.add_trace(
            go.Scatter(
                x=[_source_x],
                y=[_level_y],
                mode="markers",
                marker=dict(color=_col_l, size=7, symbol="circle"),
                name=f"{_tag}｜{_line.get('type', '')}",
                hovertemplate=(f"{_tag}｜{_line.get('kind', '')}<br>價位：%{{y:,.2f}}<br>來源：{_line.get('type', '')}<br>來源日：%{{x|%Y-%m-%d}}<extra></extra>"),
                showlegend=False,
            ),
            row=1,
            col=1,
        )
        _fig.add_annotation(
            x=_last_x,
            y=_level_y,
            text=f"{_tag} {fmt_price(_level_y)}",
            showarrow=False,
            xanchor="left",
            font=dict(size=10, color=_col_l),
            bgcolor="rgba(13,17,23,0.65)",
            bordercolor=_col_l,
            borderwidth=1,
            borderpad=2,
            row=1,
            col=1,
        )

    _bg = "#0d1117"
    _grid = "#21262d"
    _txt = "#c9d1d9"
    _fig.update_layout(
        height=660,
        paper_bgcolor=_bg,
        plot_bgcolor=_bg,
        font=dict(color=_txt, size=11),
        margin=dict(l=8, r=76, t=28, b=8),
        hovermode="x unified",
        hoverlabel=dict(bgcolor="rgba(15,23,42,0.40)", font_color="#ffffff", bordercolor="rgba(148,163,184,0.35)"),
        showlegend=False,
        dragmode="pan",
    )
    _axis_style = dict(gridcolor=_grid, linecolor=_grid, showgrid=True, zeroline=False, tickfont=dict(color=_txt, size=10))
    _fig.update_xaxes(**_axis_style)
    _fig.update_yaxes(**_axis_style)
    _fig.update_yaxes(title_text="股價", row=1, col=1)
    _fig.update_yaxes(title_text="量（張）", row=2, col=1)
    _fig.update_yaxes(title_text="KD", row=3, col=1, range=[0, 100])
    _range_args = dict(range=[_x_init_start, _x_end], autorange=False, rangeslider=dict(visible=False), fixedrange=False)
    _fig.update_layout(xaxis=_range_args, xaxis2=_range_args, xaxis3=_range_args)

    if expanded:
        st.markdown("### 📈 技術K線圖")
    st.caption("初始畫面顯示最近約1.5個月；資料與均線仍用完整資料計算，可拖曳/縮放看更久以前。")
    st.markdown(
        f'<div style="color:#6e7681;font-size:12px;margin-bottom:4px;line-height:2">'
        f"📊 {name}（{stock}）｜初始1.5個月｜可縮放 / 拖曳查看更多&nbsp;&nbsp;"
        f'<span style="color:#f59e0b">■</span> MA5 &nbsp;'
        f'<span style="color:#0B6E4F">■</span> MA10 &nbsp;'
        f'<span style="color:#3b82f6">■</span> MA20 &nbsp;'
        f'<span style="color:#a855f7">■</span> MA60 &nbsp;│&nbsp;'
        f'<span style="color:#f85149">──</span> 壓力 &nbsp;'
        f'<span style="color:#3fb950">──</span> 支撐</div>',
        unsafe_allow_html=True,
    )
    st.plotly_chart(
        _fig,
        use_container_width=True,
        config={
            "scrollZoom": True,
            "displayModeBar": True,
            "modeBarButtonsToRemove": ["select2d", "lasso2d", "autoScale2d", "zoom2d"],
            "displaylogo": False,
        },
    )


def build_buy_zone_summary(price, a, buy_point_rows=None):
    """把買點區間整理成前台可讀的白話版本，並區分低接、站回確認、突破確認。"""
    plan = a.get("plan", {}) if isinstance(a, dict) else {}
    nums = plan.get("num", {}) if isinstance(plan, dict) else {}
    attack_type = str(a.get("attack_type", "")) if isinstance(a, dict) else ""
    action = str(a.get("action", "")) if isinstance(a, dict) else ""
    try:
        model_key = str(((a.get("val") or {}).get("model_key")) or "") if isinstance(a, dict) else ""
        family_key = str(((a.get("family_rule") or {}).get("family_key")) or _model_family_key(model_key, None) or "") if isinstance(a, dict) else ""
    except Exception:
        model_key, family_key = "", ""
    # V8.5.3.1：買點摘要優先用即時股價；若沒有即時價才退回收盤價。
    close, _buy_ref_label = _reference_buy_price(price)
    ma20 = price.get("ma20") if price else None
    ma60 = price.get("ma60") if price else None
    low10 = price.get("low10") if price else None
    new_label = plan.get("new_label", "新倉主區")
    new_zone = plan.get("new", "資料不足")
    shallow_zone = plan.get("shallow", "資料不足")
    right_num = nums.get("right")
    wrong = plan.get("wrong", "資料不足")
    stop = plan.get("stop", "資料不足")

    new_low = nums.get("new_low")
    new_high = nums.get("new_high")
    shallow_high = nums.get("shallow_high")

    support_candidates = []
    if ma60 is not None:
        support_candidates.append((ma60 * 0.96, ma60 * 1.02, "MA60 支撐低接觀察"))
    if close is not None:
        support_candidates.append((close * 0.98, close * 1.02, "現價附近小倉觀察"))

    support_zone = "資料不足"
    if support_candidates:
        # 優先取最接近現價的支撐帶
        chosen = sorted(support_candidates, key=lambda z: abs((z[0] + z[1]) / 2 - (close or z[0])))[0]
        support_zone = f"{chosen[2]} {fmt_price(chosen[0])}～{fmt_price(chosen[1])}"

    # 站回確認：通常是 MA20 / 新倉確認區，不代表便宜，而是修復訊號。
    standback_zone = new_zone
    if new_label == "反彈確認區":
        standback_zone = f"站回確認 {new_zone}"
    elif ma20 is not None and close is not None and close < ma20:
        standback_zone = f"站回 MA20 附近 {fmt_price(ma20)}"

    breakout_zone = fmt_price(right_num) if right_num is not None else "資料不足"

    # 先找最有意義的提示，不把高於現價的確認價稱為漂亮買點。
    if "不買" in action:
        main = "不設買點"
        condition = "條件不足，先不要硬做。"
    elif new_label == "反彈確認區" and close is not None and new_low is not None and close < new_low:
        main = f"現價低於確認區｜等站回 {new_zone}"
        condition = (
            "現價雖然較低，但短線尚未修復；低接只適合小倉觀察，"
            f"站回確認區才代表買點品質提高；跌破 {wrong} 先降風險。"
        )
    elif "突破候選" in attack_type:
        main = f"突破提醒｜已突破不追，等回測 {breakout_zone}"
        condition = f"漲停 / 突破後不追板；隔日不跌回、量能維持、法人賣壓不擴大，才升級為 Attack。跌破 {wrong} 先認錯。"
    elif "觀察型小倉" in attack_type:
        main = f"觀察型小倉｜等回檔 {shallow_zone} 或突破後回測確認"
        if "防守型" in attack_type:
            condition = f"這不是攻擊倉；守 {wrong}，回檔更漂亮，右側突破需站穩確認。"
        elif "金融資產型" in attack_type:
            condition = f"這不是攻擊倉；守 {wrong}，等回檔或右側突破確認，投信賣壓縮小才加分。"
        else:
            condition = f"這不是攻擊倉；守 {wrong}，突破確認區且量能 / 法人確認才升級。"
    elif "候選" in attack_type:
        main = f"Attack 候選｜等回檔 {shallow_zone} 或突破後回測確認"
        condition = f"未來一週觀察承接與站回；法人賣超若縮小、守住 {wrong} 且站回確認區，才升級為 Attack。"
    elif attack_type.startswith("回檔型"):
        # V8.5.2：回檔型買點改用「現價相對買點區」判斷，避免股價已高於買點區還顯示等站回確認。
        if close is not None and new_low is not None and new_high is not None:
            _bz_low, _bz_high = min(new_low, new_high), max(new_low, new_high)
            if close < _bz_low:
                _dist = (close / _bz_low - 1) * 100 if _bz_low else None
                main = f"等站回確認｜{new_zone}"
                condition = f"{_buy_ref_label}低於買點區約 {_fmt_signed_pct(_dist)}，先等站回；跌破 {wrong} 先降風險。"
            elif close <= _bz_high:
                main = f"進入買點區｜{new_zone}"
                condition = f"{_buy_ref_label}已在買點區內，仍需搭配量能與停損；跌破 {wrong} 先認錯。"
            else:
                _dist = (close / _bz_high - 1) * 100 if _bz_high else None
                if _dist is not None and _dist <= 3:
                    main = f"已高於主買區｜等回測 {new_zone}"
                    condition = f"{_buy_ref_label}高於主買區上緣約 {_fmt_signed_pct(_dist)}，目前只能小倉觀察或等回測。"
                elif _dist is not None and _dist <= 6:
                    main = f"買點已過｜等回測 {new_zone}"
                    condition = f"{_buy_ref_label}高於買點上緣約 {_fmt_signed_pct(_dist)}，位置已不漂亮，等回測買點區再評估。"
                else:
                    main = f"已離買點｜等下一次回檔"
                    condition = f"{_buy_ref_label}高於買點上緣約 {_fmt_signed_pct(_dist)}，不追高，等下一次回到 {new_zone} 附近。"
        elif ma60 is not None and close is not None and close >= ma60 * 0.96 and close <= ma60 * 1.06:
            main = f"支撐低接觀察｜{support_zone}"
            condition = f"接近支撐可小倉分批，但不是主倉；量能不能失控，跌破 {wrong} 先認錯。"
        else:
            main = f"觀察買點｜{standback_zone}"
            condition = f"目前以修復確認為主，站回關鍵區再提高分批意願；跌破 {wrong} 先降風險。"
    elif attack_type.startswith("突破型"):
        main = f"突破確認｜{breakout_zone}"
        condition = "收盤突破壓力且量能升溫；突破價是確認點，不是便宜買點，隔日不跌回才算有效。"
    elif "等回檔" in action:
        main = f"等回檔或站回確認｜支撐看 {support_zone}"
        condition = f"不追現價，等靠近支撐或站回確認；跌破 {wrong} 先降風險。"
    elif "小倉" in action:
        main = f"小倉觀察｜{support_zone}"
        condition = f"只能試單，不可主倉；若站回 {standback_zone}，買點確認度才提高。"
    else:
        main = f"觀察買點｜支撐 {support_zone} / 確認 {standback_zone}"
        condition = f"先分清楚低接與站回確認；跌破 {wrong} 先保守。"

    # v10｜波段機會卡統一格式：避免「支撐 / 確認 / 現價附近」混在一句，手機一眼看懂。
    def _clean_zone_label(_z):
        _z = str(_z or "資料不足").strip()
        for _prefix in [
            "現價附近小倉觀察", "MA60 支撐低接觀察",
            "站回確認", "站回 MA20 附近", "支撐看", "支撐", "確認"
        ]:
            _z = _z.replace(_prefix, "").strip()
        return _z or "資料不足"

    _small_zone = shallow_zone
    if isinstance(support_zone, str) and ("現價附近小倉觀察" in support_zone):
        _small_zone = _clean_zone_label(support_zone)
    else:
        _small_zone = _clean_zone_label(shallow_zone)

    _best_zone = _clean_zone_label(new_zone)
    if "不設買點" in str(main) or "不買" in action:
        main = "可小倉：不建議\n最佳買點：等條件重新成立"
        condition = f"防守：{wrong}"
    else:
        main = f"可小倉：{_small_zone}\n最佳買點：{_best_zone}"
        _right_txt = fmt_price(right_num) if right_num is not None else "資料不足"
        condition = f"防守：{wrong}｜右側：{_right_txt}"

    # 找出可參考的最高分，但避免用「最佳」誤導成一定要買。
    best_text = ""
    if buy_point_rows:
        try:
            best = max(buy_point_rows, key=lambda r: to_float(r.get("品質分數")) or 0)
            best_text = f"參考最高分：{best.get('買點情境')} {best.get('買點把握')}"
        except Exception:
            best_text = ""

    return {
        "main": main,
        "condition": condition,
        "support_zone": support_zone,
        "standback_zone": standback_zone,
        "breakout_zone": breakout_zone,
        "new_zone": new_zone,
        "shallow_zone": shallow_zone,
        "right": fmt_price(right_num) if right_num is not None else "資料不足",
        "wrong": wrong,
        "stop": stop,
        "best": best_text,
    }


def build_decision_cards(a, price, current_zone, data_quality, buy_zone=None, sr_levels=None):
    focus_state, focus_note = display_focus_state(a)
    block_reasons = a.get("focus_block_reasons", []) or []
    block_text = "、".join(block_reasons[:3]) if block_reasons else "無明顯卡關"
    win_text = str(a.get("win_rate", "資料不足"))
    action_text = action_as_trader_sentence(a)
    attack_text = display_attack_type(a.get("attack_type", "無"))
    buy_zone = buy_zone or {}
    sr_levels = sr_levels or {}
    treasury = a.get("fin_j", {}).get("treasury", "資料不足")
    treasury_score = a.get("fin_j", {}).get("treasury_score", "")
    treasury_display = {"淘汰級": "偏弱｜需驗證", "風險級": "偏弱｜需驗證"}.get(str(treasury), str(treasury))
    try:
        treasury_text = f"{treasury_display}｜{float(treasury_score):.1f}/12"
    except Exception:
        treasury_text = str(treasury_display)
    fundamental_support = valuation_learning_support_summary(a.get("_ai_core_saved_case"), price) or build_fundamental_support_summary(price, a.get("val", {}), current_zone=current_zone)
    financial_radar = (a.get("fin_j", {}) or {}).get("financial_radar", {}) or {}
    cards = [
        {"卡片": "目前動作", "重點": a.get("action", "資料不足"), "說明": action_text},
        {"卡片": "財報金庫", "重點": treasury_text, "說明": "公司體質核心分數，取代原本五行表重複資訊"},
        {"卡片": "財務能力", "重點": financial_radar.get("summary", "資料不足"), "說明": financial_radar.get("quick", "")},
        {"卡片": "基本面支撐", "重點": fundamental_support.get("card_value", "資料不足"), "說明": fundamental_support.get("card_note", "")},
        {"卡片": "優先觀察", "重點": focus_state, "說明": focus_note},
        {"卡片": "攻擊機會", "重點": attack_text, "說明": "看未來一週是否靠近買點 / 突破觸發"},
        {"卡片": "波段機會", "重點": buy_zone.get("main", "資料不足"), "說明": buy_zone.get("condition", "顯示可小倉區與最佳買點")},
        {"卡片": "支撐壓力", "重點": sr_levels.get("summary", "資料不足"), "說明": "先看下方能不能守住，再看上方能不能突破"},
        {"卡片": "卡關原因", "重點": block_text, "說明": "Focus No 時用來判斷是模型太嚴還是真的不適合"},
        {"卡片": "買進勝率", "重點": win_text, "說明": "需搭配買點品質與停損，不是保證獲利"},
        {"卡片": "資料品質", "重點": data_quality.get("grade", "中"), "說明": data_quality.get("message", "")},
    ]
    return cards



