def nick_v216_clean_text(v, fallback="資料不足"):
    s = str(v or "").strip()
    if not s or s in ["None", "nan", "NaN", "—", "-"]:
        return fallback
    return s


def nick_v216_score_bucket(score, fallback_text):
    """把既有分數翻成小白用的機率區間；不產生精準預測。"""
    try:
        if score is None or score == "":
            return fallback_text
        score = float(score)
    except Exception:
        return fallback_text
    if score >= 75:
        return "約 70%～80%｜高"
    if score >= 65:
        return "約 60%～70%｜中高"
    if score >= 55:
        return "約 50%～60%｜中"
    return "50% 以下｜偏低"


def nick_v216_parse_range_text(text):
    """從 1740～2380 / 約1740-2380 等文字抓區間。抓不到回 None。"""
    s = str(text or "")
    try:
        if "valuation_learning_parse_range" in globals():
            r = valuation_learning_parse_range(s)
            if r:
                lo, hi = r
                lo, hi = to_float(lo), to_float(hi)
                if lo is not None and hi is not None:
                    return (min(lo, hi), max(lo, hi))
    except Exception:
        pass
    nums = re.findall(r"\d+(?:\.\d+)?", s.replace(",", ""))
    if len(nums) >= 2:
        try:
            lo, hi = float(nums[0]), float(nums[1])
            return (min(lo, hi), max(lo, hi))
        except Exception:
            return None
    return None


def nick_v216_format_range_from_tuple(pair):
    if not pair:
        return "資料不足"
    try:
        return rng_price((pair[0], pair[1]))
    except Exception:
        return f"{fmt_price(pair[0])}～{fmt_price(pair[1])}"


def nick_v216_reference_price(price=None, realtime_quote=None):
    try:
        rt = to_float((realtime_quote or {}).get("price")) if isinstance(realtime_quote, dict) else None
        if rt is not None and rt > 0:
            return rt, "即時價"
    except Exception:
        pass
    try:
        return _reference_buy_price(price)
    except Exception:
        pass
    if isinstance(price, dict):
        close = to_float(price.get("close"))
        if close is not None and close > 0:
            return close, "收盤價"
    return None, "資料不足"


def nick_v217_text_blob(a=None, extra=None):
    """只取既有分析結果中的族群/模組文字，不用單一股票代號寫死。"""
    a = a or {}
    extra = extra or {}
    parts = []
    for obj in [a, a.get("val", {}) or {}, a.get("fin_j", {}) or {}, a.get("rerating", {}) or {}, a.get("_diag", {}) or {}, a.get("_ai_core_saved_case", {}) or {}, extra]:
        if isinstance(obj, dict):
            for k in [
                "model_key", "valuation_submodel_key", "valuation_submodel_name", "model_name", "industry_family", "subfamily",
                "core_type", "type", "primary", "note", "family", "sector", "industry_category", "name", "summary", "text",
            ]:
                v = obj.get(k)
                if isinstance(v, (str, int, float)):
                    parts.append(str(v))
    return " ".join(parts)


def nick_v217_is_project_power_context(a=None):
    """通用規則：重電/電力設備/工程認列型，不可只因訂單與營收強就放正式 Core / 高勝率。"""
    txt = nick_v217_text_blob(a).lower()
    keys = [
        "重電", "電力", "電網", "強韌電網", "變壓器", "配電", "電氣", "機電", "工程",
        "訂單", "在手訂單", "認列", "軌道", "idc", "資料中心", "電源", "power", "grid", "project",
    ]
    return any(k.lower() in txt for k in keys)


def nick_v218_is_low_margin_ai_manufacturing_platform(a=None, fin=None):
    """v218 通用規則：低毛利 AI 製造平台。

    不是用股票代號判斷，而是看模型/族群文字與財務特徵。
    這類公司可以因 AI server / cloud / rack 讓營收、營益率、EPS 接棒而 Core Yes；
    但低毛利、存貨/應收與營運資金壓力會限制「純金庫級」與 Focus。
    """
    fin = fin or {}
    txt = nick_v217_text_blob(a, extra=fin).lower()
    ai_keys = [
        "ai server", "ai伺服", "ai 伺服", "伺服器", "server", "rack", "機櫃",
        "cloud", "雲端", "networking", "網通", "asic", "gpu", "cpo", "高速交換器",
    ]
    platform_keys = [
        "製造", "平台", "代工", "odm", "ems", "組裝", "manufacturing", "低毛利", "大型製造",
    ]
    gm = to_float(fin.get("gross_margin") or fin.get("gm") or fin.get("gross_margin_pct"))
    opm = to_float(fin.get("op_margin") or fin.get("operating_margin") or fin.get("operating_margin_pct"))
    low_margin = (gm is not None and gm <= 12) or (opm is not None and opm <= 6) or ("低毛利" in txt)
    has_ai = any(k.lower() in txt for k in ai_keys)
    has_platform = any(k.lower() in txt for k in platform_keys)
    return bool(low_margin and has_ai and has_platform)


def nick_v217_margin_state(fin=None, a=None):
    """毛利率/營益率接棒檢查：營收變大但獲利率沒變好，要壓低 Core、下季機率與勝率。"""
    fin = fin or {}
    a = a or {}
    fj = a.get("fin_j", {}) or {}
    gm = to_float(fin.get("gross_margin"))
    gm_prev = to_float(fin.get("gross_margin_prev"))
    opm = to_float(fin.get("op_margin") or fin.get("operating_margin"))
    opm_prev = to_float(fin.get("op_margin_prev") or fin.get("operating_margin_prev"))
    margin_txt = str(fj.get("margin") or fj.get("margin_quality") or "")
    weak_words = ["不通過", "弱", "偏弱", "待確認"]
    ordinary_words = ["普通", "部分", "尚未", "未明顯"]
    deteriorated = False
    if gm is not None and gm_prev is not None and gm < gm_prev - 0.8:
        deteriorated = True
    if opm is not None and opm_prev is not None and opm < opm_prev - 0.8:
        deteriorated = True
    weak = deteriorated or any(w in margin_txt for w in weak_words)
    ordinary = any(w in margin_txt for w in ordinary_words)
    if weak:
        return "弱化"
    if ordinary:
        return "普通"
    if margin_txt in ["有", "改善", "通過", "高", "強"]:
        return "有"
    return "資料不足"


def nick_v217_financial_report_state(a=None):
    fj = (a or {}).get("fin_j", {}) or {}
    return str(fj.get("report") or fj.get("financial_report") or "")


def nick_v217_inst_pressure_score(inst=None):
    """法人賣壓扣分：用 5日/20日與外資投信方向，不針對單檔。"""
    inst = inst or {}
    score = 0
    net5 = to_float(inst.get("net5_lot") or inst.get("total_5d"))
    net20 = to_float(inst.get("net20_lot") or inst.get("total_20d"))
    foreign5 = to_float(inst.get("foreign_net5_lot") or inst.get("foreign5_lot") or inst.get("foreign_5d"))
    trust5 = to_float(inst.get("trust_net5_lot") or inst.get("investment_trust_net5_lot") or inst.get("trust_5d"))
    neg5 = to_float(inst.get("negative_days_5"))
    neg20 = to_float(inst.get("negative_days_20"))
    if net5 is not None and net5 < 0:
        score -= 6
    if net20 is not None and net20 < 0:
        score -= 7
    if foreign5 is not None and foreign5 < 0:
        score -= 4
    if trust5 is not None and trust5 < 0:
        score -= 4
    if neg5 is not None and neg5 >= 4:
        score -= 3
    if neg20 is not None and neg20 >= 12:
        score -= 4
    return score


def nick_v217_next_month_base_pressure_score(rev=None):
    """下個月基期壓力：用去年『下一個月』相對去年『本月』的營收判斷，不硬猜。"""
    try:
        if not isinstance(rev, dict) or not isinstance(rev.get("raw"), pd.DataFrame):
            return 0
        raw = rev.get("raw").copy()
        if raw.empty or "date" not in raw.columns:
            return 0
        rev_col = pick_col(raw.columns, ["revenue", "當月營收", "營業收入"])
        if not rev_col:
            return 0
        raw["dt"] = pd.to_datetime(raw["date"], errors="coerce")
        raw[rev_col] = raw[rev_col].apply(to_float)
        raw = raw.dropna(subset=["dt"]).sort_values("dt")
        if raw.empty:
            return 0
        latest_dt = raw.iloc[-1]["dt"]
        # 目標是下一個公告月份的去年基期
        next_month = latest_dt.month + 1
        next_year = latest_dt.year
        if next_month > 12:
            next_month = 1
            next_year += 1
        ly_curr = raw[(raw["dt"].dt.year == latest_dt.year - 1) & (raw["dt"].dt.month == latest_dt.month)]
        ly_next = raw[(raw["dt"].dt.year == next_year - 1) & (raw["dt"].dt.month == next_month)]
        if ly_curr.empty or ly_next.empty:
            return 0
        curr_base = to_float(ly_curr.iloc[-1][rev_col])
        next_base = to_float(ly_next.iloc[-1][rev_col])
        if curr_base is None or curr_base <= 0 or next_base is None:
            return 0
        ratio = next_base / curr_base - 1
        if ratio >= 0.18:
            return -10
        if ratio >= 0.10:
            return -7
        if ratio >= 0.05:
            return -4
    except Exception:
        return 0
    return 0


def nick_v219_is_turnaround_attack_context(a=None, fin=None):
    """v219 通用規則：轉機攻擊股 / 資金點火股。

    這類標的常見特徵是：題材、營收與籌碼先動，但 EPS、營益率或淨利率尚未完整接棒。
    它可以 Attack，但不能太快升級 Core / 金庫 / Focus。
    """
    a = a or {}
    fin = fin or {}
    txt = nick_v217_text_blob(a, extra=fin).lower()
    keys = [
        "轉機", "資金點火", "題材", "補漲", "攻擊", "候選", "rerating", "re-rating", "重評",
        "電源", "power", "hvdc", "高功率", "資料中心", "ai", "idc",
    ]
    fj = a.get("fin_j", {}) or {}
    report = nick_v217_financial_report_state(a)
    core_raw = str(a.get("core") or "")
    core_status = str(a.get("core_status") or "")
    margin_state = nick_v217_margin_state(fin, a)
    eps = to_float(fin.get("eps") or fin.get("EPS") or fin.get("latest_eps"))
    opm = to_float(fin.get("op_margin") or fin.get("operating_margin") or fin.get("operating_margin_pct"))
    netm = to_float(fin.get("net_margin") or fin.get("net_margin_pct"))
    theme_like = any(k.lower() in txt for k in keys)
    thin_profit = False
    if eps is not None and eps < 0.5:
        thin_profit = True
    if opm is not None and opm < 4:
        thin_profit = True
    if netm is not None and netm < 4:
        thin_profit = True
    partial_core = (core_raw != "Yes") or ("候選" in core_status) or bool((a.get("_diag") or {}).get("core_candidate"))
    partial_report = report in ["部分通過", "部分通過偏弱", "不通過"] or margin_state in ["普通", "弱化"]
    return bool(theme_like and partial_core and (partial_report or thin_profit))


def nick_v219_is_hot_chase_risk(price=None, a=None, support_range_text="", realtime_quote=None, core_text=""):
    """v219 通用防呆：漲停/爆量/高於支撐區且財報未完整接棒時，現價追高要大扣分。"""
    a = a or {}
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    support_pair = nick_v216_parse_range_text(support_range_text)
    change_pct = None
    try:
        change_pct = to_float(price.get("change_pct")) if isinstance(price, dict) else None
    except Exception:
        change_pct = None
    gap = None
    if support_pair and ref_price is not None and support_pair[1]:
        gap = ref_price / support_pair[1] - 1
    report = nick_v217_financial_report_state(a)
    margin_state = nick_v217_margin_state(None, a)
    core_candidate = "Core 候選" in str(core_text) or str(a.get("core") or "") != "Yes"
    hot_price = (change_pct is not None and change_pct >= 8) or (gap is not None and gap >= 0.15)
    not_full_financial_core = core_candidate or report in ["部分通過", "部分通過偏弱", "不通過"] or margin_state in ["普通", "弱化"]
    return bool(hot_price and not_full_financial_core)


def nick_v219_format_target_range(text, ref_price=None, kind="short"):
    """把單點目標轉成區間，避免小白表看起來像精準預測。"""
    raw = nick_v216_clean_text(text, "資料不足")
    pair = nick_v216_parse_range_text(raw)
    if pair:
        return nick_v216_format_range_from_tuple(pair)
    anchor = nick_v217_price_anchor(raw)
    if anchor is None:
        return raw
    try:
        anchor = float(anchor)
        if kind == "wave":
            lo = anchor * 0.98
            hi = anchor * 1.08
        else:
            lo = anchor * 0.96
            hi = anchor * 1.02
        if ref_price is not None and anchor > ref_price:
            lo = max(lo, float(ref_price) * 1.03)
        return rng_price((lo, hi))
    except Exception:
        return raw


def nick_v219_adjust_defense_text(wrong, stop, price=None, support_range_text="", a=None, realtime_quote=None, core_text=""):
    """轉機攻擊股防守點校正：短線防守不可直接抓淺回檔區上緣，波段防守要靠近基本面/平台失效區。"""
    wrong_text = nick_v216_clean_text(wrong, "資料不足")
    stop_text = nick_v216_clean_text(stop, "資料不足")
    if not nick_v219_is_hot_chase_risk(price, a, support_range_text, realtime_quote, core_text):
        return wrong_text, stop_text
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    support_pair = nick_v216_parse_range_text(support_range_text)
    wrong_anchor = nick_v217_price_anchor(wrong_text)
    stop_anchor = nick_v217_price_anchor(stop_text)
    try:
        if ref_price is not None and wrong_anchor is not None and wrong_anchor > ref_price * 0.90:
            # 漲停/過熱股：短線失效多半落在現價約 -8%~-10% 或前平台，不宜抓淺回檔上緣。
            wrong_text = fmt_price(min(wrong_anchor, ref_price * 0.91))
        if support_pair and stop_anchor is not None and stop_anchor > support_pair[1] * 1.03:
            lo = support_pair[1] * 0.98
            hi = support_pair[1] * 1.02
            stop_text = rng_price((lo, hi))
    except Exception:
        pass
    return wrong_text, stop_text



def nick_v221_latest_inst_net_lot(inst=None):
    """抓最近一日三大法人淨買賣超張數；抓不到回 None。"""
    inst = inst or {}
    try:
        daily = inst.get("daily")
        if isinstance(daily, pd.DataFrame) and not daily.empty:
            row = daily.sort_values("date").iloc[-1]
            if "net_lot" in daily.columns:
                return to_float(row.get("net_lot"))
            if "net" in daily.columns:
                v = to_float(row.get("net"))
                return v / 1000 if v is not None else None
    except Exception:
        pass
    try:
        latest_by_type = inst.get("latest_by_type") or []
        vals = []
        for r in latest_by_type:
            if isinstance(r, dict):
                vals.append(to_float(r.get("net_lot") or r.get("net")))
        vals = [v for v in vals if v is not None]
        if vals:
            return sum(vals)
    except Exception:
        pass
    for k in ["latest_net_lot", "today_net_lot", "net1_lot", "net_lot"]:
        v = to_float(inst.get(k))
        if v is not None:
            return v
    return None


def nick_v221_is_core_or_treasury_like(a=None, core_text=""):
    a = a or {}
    fj = a.get("fin_j", {}) or {}
    core_raw = str(a.get("core") or "")
    treasury = str(fj.get("treasury") or "")
    report = nick_v217_financial_report_state(a)
    if "Core Yes" in str(core_text) or core_raw == "Yes":
        return True
    if "金庫" in treasury and report == "通過":
        return True
    return False


def nick_v221_high_level_distribution_risk(price=None, inst=None, a=None):
    """v221 通用防呆：Core/金庫股遇到高檔大量長黑＋法人倒貨，交易面必須降級。

    不用單一個股代號判斷；只看價量、法人、Attack/Focus 與基本面狀態。
    """
    price = price or {}
    inst = inst or {}
    a = a or {}

    latest_net = nick_v221_latest_inst_net_lot(inst)
    net5 = to_float(inst.get("net5_lot") or inst.get("total_5d"))
    net20 = to_float(inst.get("net20_lot") or inst.get("total_20d"))
    foreign5 = to_float(inst.get("foreign_net5_lot") or inst.get("foreign5_lot") or inst.get("foreign_5d"))
    consec_sell = to_float(inst.get("consecutive_sell"))
    latest_sell = latest_net is not None and latest_net < 0
    short_sell = (net5 is not None and net5 < 0) or (foreign5 is not None and foreign5 < 0)
    mid_sell = net20 is not None and net20 < 0
    inst_sell_pressure = latest_sell or short_sell or mid_sell or (consec_sell is not None and consec_sell >= 2)

    volume_ratio = to_float(price.get("volume_ratio"))
    day_chg = to_float(price.get("change_pct"))
    close = to_float(price.get("close"))
    ma5 = to_float(price.get("ma5"))
    ma20 = to_float(price.get("ma20"))
    high20 = to_float(price.get("high20"))
    raw_black = False
    try:
        raw = price.get("raw")
        if isinstance(raw, pd.DataFrame) and not raw.empty:
            last = raw.sort_values("date").iloc[-1]
            o = to_float(last.get("open"))
            h = to_float(last.get("max") or last.get("high"))
            c = to_float(last.get("close"))
            if o is not None and c is not None:
                raw_black = c < o * 0.97
            if h is not None and c is not None and h > 0:
                raw_black = raw_black or ((c / h - 1) <= -0.06)
    except Exception:
        raw_black = False

    heavy_volume = volume_ratio is not None and volume_ratio >= 1.25
    high_level = False
    try:
        if close is not None and high20 is not None and high20 > 0:
            high_level = close >= high20 * 0.85
        if close is not None and ma20 is not None:
            high_level = high_level or close >= ma20 * 0.95
    except Exception:
        pass
    black_or_break = bool(raw_black or (day_chg is not None and day_chg <= -3.5) or (close is not None and ma5 is not None and close < ma5 and heavy_volume) or (close is not None and ma20 is not None and close < ma20 and heavy_volume))

    attack_raw = str(a.get("attack") or a.get("attack_type") or "")
    focus_raw = str(a.get("focus") or "")
    attack_not_ok = (a.get("attack") == "No") or ("Attack No" in attack_raw) or ("無" in attack_raw and "攻擊" in attack_raw)
    focus_not_ok = (a.get("focus") == "No") or ("Focus No" in focus_raw)
    chip_type = str((a.get("_diag") or {}).get("chip_pressure_type") or (a.get("_diag") or {}).get("atk_chip_health_status") or "")
    chip_distribution = any(w in chip_type for w in ["出貨", "倒貨", "籌碼退潮", "高檔換手"])

    return bool(high_level and inst_sell_pressure and (black_or_break or chip_distribution or attack_not_ok or focus_not_ok))


def nick_v221_safe_range_from_support(support_range_text, part="main", ref_price=None):
    """Core 股交易面轉弱時，買點要回到基本面支撐/平台，不跟現價亂漂。"""
    pair = nick_v216_parse_range_text(support_range_text)
    if not pair:
        return "資料不足"
    lo, hi = pair
    try:
        lo, hi = float(lo), float(hi)
        width = max(hi - lo, hi * 0.08)
        if part == "main":
            # 基本面甜點偏下半段：例如 190~220 => 約 195~208。
            return rng_price((lo + width * 0.15, lo + width * 0.60))
        if part == "trial":
            # v247｜淺回檔試單區：用「區間＋條件」，不要只抓接近失效點的窄區間。
            # 若現價仍在支撐區上半部，試單上緣可貼近現價 / 支撐上緣；下緣靠近短線防守。
            lower = hi * 0.966
            upper = hi * 0.995
            if ref_price is not None:
                rp = float(ref_price)
                if lo <= rp <= hi * 1.03:
                    upper = max(upper, min(rp * 1.005, hi * 0.998))
            return rng_price((lower, upper))
        if part == "wave_stop":
            return rng_price((lo * 1.00, lo * 1.05))
        if part == "short_stop":
            return fmt_price(hi * 0.98)
    except Exception:
        return nick_v216_format_range_from_tuple(pair)
    return nick_v216_format_range_from_tuple(pair)

def nick_v216_core_and_treasury(a, fin=None):
    a = a or {}
    fj = a.get("fin_j", {}) or {}
    diag = a.get("_diag", {}) or {}
    core_raw = str(a.get("core", "No") or "No")
    core_status = str(a.get("core_status", "") or "")
    case = a.get("_ai_core_saved_case") or {}
    case_core = str(case.get("core_verdict") or case.get("ai_core") or "") if isinstance(case, dict) else ""
    case_level = nick_v253_forensic_core_level(case, nick_v247_case_text_blob(case, a)) if isinstance(case, dict) else "unknown"
    is_candidate = bool(diag.get("core_candidate")) or ("候選" in core_status) or (case_level == "candidate") or ("Core 候選" in case_core)
    if case_level == "yes" or (core_raw == "Yes" and case_level != "candidate"):
        core_text = "Core Yes"
    elif is_candidate:
        core_text = "Core 候選"
    else:
        core_text = "公司體質未通過"

    treasury_raw = nick_v216_clean_text(fj.get("treasury"), "資料不足")
    treasury_score = to_float(fj.get("treasury_score"))
    if "金庫級" in treasury_raw:
        treasury_text = "金庫級"
    elif "偏金庫" in treasury_raw or (treasury_score is not None and treasury_score >= 10):
        treasury_text = "候選級偏金庫"
    elif "候選" in treasury_raw or (treasury_score is not None and treasury_score >= 8):
        treasury_text = "候選級"
    elif treasury_raw == "資料不足":
        treasury_text = "資料不足"
    else:
        treasury_text = "非金庫"

    report = nick_v217_financial_report_state(a)
    margin_state = nick_v217_margin_state(fin, a)
    project_power = nick_v217_is_project_power_context(a)
    low_margin_ai_platform = nick_v218_is_low_margin_ai_manufacturing_platform(a, fin)
    turnaround_attack = nick_v219_is_turnaround_attack_context(a, fin)
    weak_report = report in ["不通過", "部分通過", "部分通過偏弱"]

    # v253｜法醫 Core 候選 + 財報尚未完整通過：金庫不可顯示過度樂觀。
    if core_text.startswith("Core 候選") and weak_report and treasury_text in ["金庫級", "候選級偏金庫", "候選級"]:
        treasury_text = "觀察級偏候選"

    # v218｜低毛利 AI 製造平台：低毛利不直接否決 Core；若營收、營益率、EPS 已接棒，允許 Core Yes。
    # 但毛利率低、存貨/應收/現金流壓力會限制「純金庫級」與 Focus，因此小白表最高先壓到候選級偏金庫。
    if low_margin_ai_platform:
        if treasury_text == "金庫級":
            treasury_text = "候選級偏金庫"
        if weak_report and core_text == "Core Yes":
            core_text = "Core 候選（法醫校正）"
            if treasury_text == "候選級偏金庫":
                treasury_text = "候選級"
        return core_text, treasury_text

    # v217 通用法醫校正：工程/重電/專案認列型，若財報只部分通過或毛利/營益率未接棒，正式 Core 與金庫級不得太鬆。
    margin_not_strong = margin_state in ["弱化", "普通", "資料不足"]
    if project_power and core_text == "Core Yes" and (weak_report or margin_not_strong):
        core_text = "Core 候選（法醫校正）"
    if project_power and treasury_text in ["金庫級", "候選級偏金庫"] and (weak_report or margin_state in ["弱化", "普通"]):
        treasury_text = "候選級"

    # v219｜轉機攻擊股：Core 候選 + 財報部分通過 + EPS/營益率尚未接棒，
    # 金庫最高只能到「觀察級偏候選」，避免題材/外資吃貨把財報品質誤升級。
    if turnaround_attack and core_text != "Core Yes" and (weak_report or margin_state in ["弱化", "普通", "資料不足"]):
        if treasury_text in ["金庫級", "候選級偏金庫", "候選級"]:
            treasury_text = "觀察級偏候選"
    return core_text, treasury_text


def nick_v216_month_progress_probability(rev=None, inst=None, a=None):
    rev = rev or {}
    inst = inst or {}
    a = a or {}
    ev = a.get("evidence_box", {}) or {}
    score = None
    try:
        score = (ev.get("revenue_signal") or {}).get("score")
    except Exception:
        score = None
    if score is None:
        yoy = to_float(rev.get("yoy"))
        mom = to_float(rev.get("mom") or rev.get("mom_pct") or rev.get("monthly_growth"))
        ytd_yoy = to_float(rev.get("ytd_yoy"))
        points = 0
        if yoy is not None:
            points += 1
        if mom is not None:
            points += 1
        if ytd_yoy is not None:
            points += 1
        if inst:
            points += 1
        if points >= 2:
            s = 50
            if yoy is not None:
                s += 14 if yoy >= 30 else 10 if yoy >= 15 else 5 if yoy > 0 else -8
            if mom is not None:
                s += 6 if mom >= 5 else 2 if mom >= 0 else -6
            if ytd_yoy is not None:
                s += 6 if ytd_yoy >= 20 else 3 if ytd_yoy > 0 else -5
            score = s
    if score is None:
        return "待下月營收確認"
    try:
        score = float(score)
    except Exception:
        return "待下月營收確認"
    score += nick_v217_inst_pressure_score(inst)
    score += nick_v217_next_month_base_pressure_score(rev)
    # 工程/訂單認列型：營收強但獲利率未接棒時，下月續強不可直接高分。
    if nick_v217_is_project_power_context(a) and nick_v217_margin_state(None, a) in ["普通", "弱化"]:
        score -= 4
    score = max(25, min(82, round(score)))
    return nick_v216_score_bucket(score, "待下月營收確認")


def nick_v216_quarter_progress_probability(fin=None, a=None):
    fin = fin or {}
    a = a or {}
    fj = a.get("fin_j", {}) or {}
    ev = a.get("evidence_box", {}) or {}
    rr_score = None
    try:
        rr_score = (ev.get("rerating_score") or {}).get("score")
    except Exception:
        rr_score = None

    data_points = 0
    score = 50
    report = str(fj.get("report", "") or "")
    if report:
        data_points += 1
        if report == "通過":
            score += 15
        elif report == "部分通過":
            score += 4
        elif report == "不通過":
            score -= 14
    growth = str(fj.get("growth_quality", "") or "")
    if growth:
        data_points += 1
        if growth in ["通過", "高", "有"]:
            score += 8
        elif growth == "不通過":
            score -= 8
    margin_state = nick_v217_margin_state(fin, a)
    if margin_state != "資料不足":
        data_points += 1
        if margin_state == "有":
            score += 6
        elif margin_state == "普通":
            score -= 2
        elif margin_state == "弱化":
            score -= 10
    eps_yoy = to_float(fin.get("eps_yoy") or fin.get("eps_growth") or fin.get("eps_yoy_pct"))
    if eps_yoy is not None:
        data_points += 1
        score += 8 if eps_yoy > 0 else -6
    if rr_score is not None:
        data_points += 1
        try:
            score += max(-5, min(8, (float(rr_score) - 55) / 3.0))
        except Exception:
            pass
    if data_points < 2:
        return "待下一季財報確認"
    if nick_v217_is_project_power_context(a):
        if report == "部分通過" or margin_state in ["普通", "弱化", "資料不足"]:
            score = min(score, 64)
    elif report == "部分通過" and margin_state in ["普通", "弱化"]:
        score = min(score, 68)
    score = max(25, min(85, round(score)))
    return nick_v216_score_bucket(score, "待下一季財報確認")


def nick_v218_bucket_only(score, fallback="待確認"):
    try:
        return nick_v216_score_bucket(float(score), fallback).replace("｜高", "").replace("｜中高", "").replace("｜中", "").replace("｜偏低", "")
    except Exception:
        return fallback


def nick_v218_month_progress_text(rev=None, inst=None, a=None):
    """v218：下月進步拆成「月增」與「年增維持強勢」，避免大型股 MoM 與 YoY 被混成一個數字。"""
    rev = rev or {}
    inst = inst or {}
    yoy = to_float(rev.get("yoy"))
    mom = to_float(rev.get("mom") or rev.get("mom_pct") or rev.get("monthly_growth"))
    ytd_yoy = to_float(rev.get("ytd_yoy"))
    pressure = nick_v217_inst_pressure_score(inst) + nick_v217_next_month_base_pressure_score(rev)
    if yoy is None and mom is None and ytd_yoy is None:
        return nick_v216_month_progress_probability(rev, inst, a)

    mom_score = None
    if mom is not None:
        mom_score = 50
        mom_score += 12 if mom >= 8 else 8 if mom >= 3 else 3 if mom >= 0 else -8
        mom_score += max(-10, min(4, pressure * 0.55))
        if nick_v217_is_project_power_context(a) and nick_v217_margin_state(None, a) in ["普通", "弱化"]:
            mom_score -= 4
        mom_score = max(30, min(80, round(mom_score)))

    yoy_score = None
    base = yoy if yoy is not None else ytd_yoy
    if base is not None:
        yoy_score = 50
        yoy_score += 28 if base >= 30 else 22 if base >= 20 else 15 if base >= 10 else 7 if base > 0 else -10
        if ytd_yoy is not None:
            yoy_score += 5 if ytd_yoy >= 20 else 2 if ytd_yoy > 0 else -5
        # 法人賣壓會壓短線情緒，但不該把大型股 YoY 趨勢直接打死。
        yoy_score += max(-7, min(3, pressure * 0.35))
        yoy_score = max(35, min(82, round(yoy_score)))

    # v219：轉機股重點不只 MoM 再創高，更要看營收能否維持高檔。
    maintain_score = None
    if mom is not None or base is not None:
        maintain_score = 50
        if mom is not None:
            maintain_score += 16 if mom >= 3 else 12 if mom >= 0 else 5 if mom >= -5 else -10
        if base is not None:
            maintain_score += 14 if base >= 20 else 9 if base >= 10 else 4 if base > 0 else -8
        maintain_score += max(-5, min(2, pressure * 0.25))
        maintain_score = max(35, min(82, round(maintain_score)))

    if mom_score is not None and yoy_score is not None:
        return f"月增再創高：{nick_v218_bucket_only(mom_score)}；營收維持高檔：{nick_v218_bucket_only(maintain_score)}；年增維持強勢：{nick_v218_bucket_only(yoy_score)}"
    if mom_score is not None:
        return f"月增再創高：{nick_v218_bucket_only(mom_score)}；營收維持高檔：{nick_v218_bucket_only(maintain_score)}；年增待確認"
    return f"年增維持強勢：{nick_v218_bucket_only(yoy_score)}；營收維持高檔：{nick_v218_bucket_only(maintain_score)}；月增待確認"


def nick_v218_quarter_progress_text(fin=None, a=None):
    """v218：下季進步拆成「營收」與「EPS/毛利/營益率接棒」。"""
    fin = fin or {}
    a = a or {}
    fj = a.get("fin_j", {}) or {}
    report = nick_v217_financial_report_state(a)
    margin_state = nick_v217_margin_state(fin, a)
    rr = a.get("rerating", {}) or {}
    revenue_score = 55
    eps_score = 50
    data_points = 0

    # 營收/訂單/重評主線給營收進步分，但不直接等於 EPS 進步。
    growth = str(fj.get("growth_quality") or fj.get("growth") or "")
    if growth:
        data_points += 1
        if growth in ["通過", "高", "有", "強"]:
            revenue_score += 15
        elif "部分" in growth:
            revenue_score += 7
        elif "不通過" in growth:
            revenue_score -= 10
    rr_v = str(rr.get("verdict") or "")
    if rr_v:
        data_points += 1
        if rr_v == "成立":
            revenue_score += 8
        elif rr_v == "部分成立":
            revenue_score += 4
        elif rr_v == "不成立":
            revenue_score -= 6
    if nick_v218_is_low_margin_ai_manufacturing_platform(a, fin):
        revenue_score += 5

    # EPS/毛利/營益率接棒看財報裁決與 margin_state。
    if report:
        data_points += 1
        if report == "通過":
            eps_score += 12
        elif report == "部分通過":
            eps_score += 4
        elif report == "不通過":
            eps_score -= 14
    if margin_state != "資料不足":
        data_points += 1
        if margin_state == "有":
            eps_score += 8
        elif margin_state == "普通":
            eps_score -= 2
        elif margin_state == "弱化":
            eps_score -= 10
    eps_yoy = to_float(fin.get("eps_yoy") or fin.get("eps_growth") or fin.get("eps_yoy_pct"))
    if eps_yoy is not None:
        data_points += 1
        eps_score += 8 if eps_yoy > 0 else -6

    if data_points < 2:
        return nick_v216_quarter_progress_probability(fin, a)
    if nick_v217_is_project_power_context(a) and margin_state in ["普通", "弱化", "資料不足"]:
        eps_score = min(eps_score, 64)
    revenue_score = max(35, min(82, round(revenue_score)))
    eps_score = max(30, min(78, round(eps_score)))
    return f"營收更進步：{nick_v218_bucket_only(revenue_score)}；EPS/毛利接棒：{nick_v218_bucket_only(eps_score)}"


def nick_v216_support_text(price=None, a=None, current_zone="", fund_support=None, realtime_quote=None):
    a = a or {}
    val = a.get("val", {}) or {}
    fund_support = fund_support if isinstance(fund_support, dict) else None
    if fund_support is None:
        try:
            fund_support = valuation_learning_support_summary(a.get("_ai_core_saved_case"), price) or build_fundamental_support_summary(price, val, current_zone=current_zone, realtime_quote=realtime_quote)
        except Exception:
            fund_support = {}
    support_range_text = nick_v216_clean_text((fund_support or {}).get("support_range"), "資料不足")
    if support_range_text == "資料不足":
        try:
            if val.get("ok"):
                pair = valuation_support_range(val)
                support_range_text = nick_v216_format_range_from_tuple(pair)
        except Exception:
            support_range_text = "資料不足"
    pair = nick_v216_parse_range_text(support_range_text)
    ref_price, ref_label = nick_v216_reference_price(price, realtime_quote)
    if not pair or ref_price is None:
        judgement = "估值資料不足，暫不給支撐區"
    else:
        lo, hi = pair
        if lo <= ref_price <= hi:
            judgement = "現價位於支撐區內"
        elif ref_price > hi:
            gap = (ref_price / hi - 1) * 100 if hi else None
            if gap is not None and gap >= 20:
                judgement = f"現價已明顯高於基本面支撐區約 {_fmt_signed_pct(gap)}；不是便宜區，需靠 EPS / 毛利率接棒"
            else:
                judgement = f"現價已高於基本面支撐區約 {_fmt_signed_pct(gap)}；偏重評區，不是便宜區"
        else:
            gap = (ref_price / lo - 1) * 100 if lo else None
            judgement = f"現價低於支撐區下緣約 {_fmt_signed_pct(gap)}；便宜也要確認基本面沒壞"
    return support_range_text, judgement


def nick_v217_range_pair_from_any(v):
    if v is None:
        return None
    if isinstance(v, (list, tuple)) and len(v) >= 2:
        lo, hi = to_float(v[0]), to_float(v[1])
        if lo is not None and hi is not None:
            return (min(lo, hi), max(lo, hi))
    return nick_v216_parse_range_text(v)


def nick_v217_price_anchor(v):
    nums = re.findall(r"\d+(?:\.\d+)?", str(v or "").replace(",", ""))
    vals = []
    for n in nums:
        try:
            vals.append(float(n))
        except Exception:
            pass
    return max(vals) if vals else None


def nick_v216_target_text(a=None, price=None, support_range_text="", realtime_quote=None, inst=None):
    a = a or {}
    plan = a.get("plan", {}) or {}
    val = a.get("val", {}) or {}
    rr = a.get("rerating", {}) or {}
    ref_price_tmp, _ = nick_v216_reference_price(price, realtime_quote)
    short_t = nick_v219_format_target_range(plan.get("short"), ref_price=ref_price_tmp, kind="short")
    wave_t = nick_v219_format_target_range(plan.get("wave"), ref_price=ref_price_tmp, kind="wave")
    support_pair = nick_v216_parse_range_text(support_range_text) or nick_v217_range_pair_from_any(valuation_support_range(val) if isinstance(val, dict) else None)
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)

    # v247｜金庫/Core 高檔籌碼壓力防呆：大量長黑＋法人明顯出貨時，交易目標改回「先看壓力與止跌」，
    # 不可把樂觀估值區直接塞進短線/波段目標。
    distribution_risk = nick_v221_high_level_distribution_risk(price, inst, a)
    if distribution_risk and ref_price is not None:
        try:
            short_t = rng_price((float(ref_price) * 1.08, float(ref_price) * 1.16))
            wave_t = rng_price((float(ref_price) * 1.20, float(ref_price) * 1.30))
            strong_t = f"重評上緣：{rng_price((float(ref_price) * 1.34, float(ref_price) * 1.38))}｜需 Q2/Q3 驗證"
            return f"短線壓力/目標：{short_t}｜波段目標：{wave_t}｜強勢重評驗證區：{strong_t}"
        except Exception:
            pass

    short_anchor = nick_v217_price_anchor(short_t)
    wave_anchor = nick_v217_price_anchor(wave_t)
    floor_need = 0
    for x in [support_pair[1] if support_pair else None, short_anchor, wave_anchor, ref_price]:
        if x is not None:
            floor_need = max(floor_need, float(x) * 0.88)
    candidates = []
    try:
        if val.get("ok") and rr.get("verdict") in ["成立", "部分成立"]:
            candidates.append(("估值重評區", nick_v217_range_pair_from_any(val.get("rerating"))))
        if val.get("ok") and rr.get("verdict") == "成立":
            candidates.append(("市場溢價區", nick_v217_range_pair_from_any(val.get("market_premium"))))
        if val.get("ok"):
            candidates.append(("樂觀區", nick_v217_range_pair_from_any(val.get("opt"))))
    except Exception:
        pass
    strong_t = "需 Q2/Q3 驗證"
    for label, pair in candidates:
        if not pair:
            continue
        if floor_need <= 0 or pair[1] >= floor_need:
            strong_t = f"{label}：{rng_price(pair)}｜需財報接棒"
            break
    # v218：分清楚技術波段目標與估值重評驗證區，避免把高估值區直接當一般短線目標。
    return f"短線壓力/目標：{short_t}｜波段目標：{wave_t}｜強勢重評驗證區：{strong_t}"


def nick_v247_nice_confirm_price(x):
    """v247｜右側確認價不要直接用高壓前高；若短壓為 404 這類，顯示成 400 比較接近交易語意。"""
    p = to_float(x)
    if p is None:
        return None
    try:
        if p >= 1000:
            return round_price_to_tick(math.floor(p / 10) * 10)
        if p >= 250:
            return round_price_to_tick(math.floor(p / 5) * 5)
        return round_price_to_tick(p)
    except Exception:
        return p


def nick_v247_stage_right_plan_text(plan=None, price=None, ref_price=None, shallow_text="", wrong_text="", right_text=""):
    """v247｜右側買點語意分層：
    右側啟動 ≠ 右側確認 ≠ 上方壓力 ≠ 波段目標。
    若原本 right 明顯高於短線壓力，視為上方壓力，不當第一個右側買點。
    """
    plan = plan or {}
    price = price or {}
    right_text = nick_v216_clean_text(right_text or plan.get("right"), "資料不足")
    short_text = nick_v216_clean_text(plan.get("short"), "")
    wrong_text = nick_v216_clean_text(wrong_text or plan.get("wrong"), "")
    shallow_text = nick_v216_clean_text(shallow_text or plan.get("shallow"), "")

    right_anchor = nick_v217_price_anchor(right_text)
    short_anchor = nick_v217_price_anchor(short_text)
    ref_price = to_float(ref_price)
    if ref_price is None:
        try:
            ref_price = to_float(price.get("realtime_price") or price.get("close"))
        except Exception:
            ref_price = None

    # 右側啟動：先站回最近關鍵均線 / 短壓，不是直接等前高。
    start_candidates = []
    try:
        for k in ["ma5", "ma10", "ma20"]:
            v = to_float(price.get(k))
            if v is not None and v > 0:
                if ref_price is None or v >= ref_price * 0.995:
                    start_candidates.append(v)
    except Exception:
        pass
    start_anchor = None
    if start_candidates:
        # 取最接近現價的上方均線；避免直接抓到太遠的 MA。
        if ref_price is not None:
            start_anchor = min(start_candidates, key=lambda x: abs(x - ref_price))
        else:
            start_anchor = min(start_candidates)
    if start_anchor is None and short_anchor is not None:
        start_anchor = short_anchor * 0.955
    if start_anchor is not None and short_anchor is not None and start_anchor > short_anchor * 1.02:
        start_anchor = short_anchor

    # 右側確認：若原 right 是上方大壓，改用短線壓力/整數關卡當第一個確認。
    high_pressure_mode = bool(short_anchor is not None and right_anchor is not None and right_anchor > short_anchor * 1.04)
    if high_pressure_mode:
        confirm_anchor = nick_v247_nice_confirm_price(short_anchor)
        upper_pressure = right_text
    else:
        confirm_anchor = right_anchor or short_anchor
        upper_pressure = ""

    # 隔日不跌回：優先取淺回檔上緣附近，再退回短線防守。
    hold_anchor = None
    shallow_pair = nick_v216_parse_range_text(shallow_text)
    if shallow_pair:
        try:
            hold_anchor = float(shallow_pair[1]) * 0.995
        except Exception:
            hold_anchor = None
    if hold_anchor is None:
        wrong_anchor = nick_v217_price_anchor(wrong_text)
        if wrong_anchor is not None:
            hold_anchor = wrong_anchor
    if hold_anchor is None and ref_price is not None:
        hold_anchor = ref_price * 0.99

    parts = []
    if start_anchor is not None and confirm_anchor is not None and high_pressure_mode:
        parts.append(f"右側啟動：站回 {fmt_price(start_anchor)}")
        parts.append(f"第一段確認：突破 {fmt_price(confirm_anchor)}，隔日不跌回 {fmt_price(hold_anchor)}")
        parts.append(f"上方壓力：{upper_pressure}")
    elif right_text and right_text != "資料不足":
        parts.append(f"右側確認：{right_text}")
    else:
        parts.append("右側分層：資料不足")
    return "｜".join(parts)



def nick_v216_buy_point_text(a=None, price=None, support_range_text="", realtime_quote=None, inst=None):
    a = a or {}
    plan = a.get("plan", {}) or {}
    new_zone = nick_v216_clean_text(plan.get("new"), "資料不足")
    shallow = nick_v216_clean_text(plan.get("shallow"), "資料不足")
    right = nick_v216_clean_text(plan.get("right"), "資料不足")
    wrong = nick_v216_clean_text(plan.get("wrong"), "資料不足")
    stop = nick_v216_clean_text(plan.get("stop"), "資料不足")
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    support_pair = nick_v216_parse_range_text(support_range_text)

    # v247｜Core/金庫遇高檔籌碼壓力：買點回到基本面甜點與淺回檔試單，不跟現價漂移。
    if nick_v221_high_level_distribution_risk(price, inst, a):
        base_zone = nick_v221_safe_range_from_support(support_range_text, "main", ref_price)
        trial_zone = nick_v221_safe_range_from_support(support_range_text, "trial", ref_price)
        short_stop = nick_v221_safe_range_from_support(support_range_text, "short_stop", ref_price)
        wave_stop = nick_v221_safe_range_from_support(support_range_text, "wave_stop", ref_price)
        ma5 = to_float((price or {}).get("ma5"))
        ma20 = to_float((price or {}).get("ma20"))
        reclaim = None
        for x in [ma5, ma20]:
            if x is not None:
                reclaim = max(reclaim or 0, x)
        right_anchor = nick_v217_price_anchor(right)
        if reclaim is not None and right_anchor is not None and (ref_price is None or reclaim > ref_price * 1.01):
            right_text = f"先站回 {fmt_price(reclaim)}，再突破 {right}"
        else:
            right_text = right
        right_stage_text = nick_v247_stage_right_plan_text(
            plan, price=price, ref_price=ref_price, shallow_text=trial_zone, wrong_text=short_stop, right_text=right_text
        )
        return (
            f"新倉主區：{base_zone}｜淺回檔試單：{trial_zone}｜"
            f"條件：守住 {short_stop}，法人賣壓不擴大｜"
            f"{right_stage_text}｜短線失效：跌破 {short_stop}｜波段防守：{wave_stop}"
        )

    # v219：轉機攻擊股若已漲停/過熱，短線防守不可直接抓淺回檔上緣；波段防守靠近基本面/平台失效區。
    wrong, stop = nick_v219_adjust_defense_text(wrong, stop, price=price, support_range_text=support_range_text, a=a, realtime_quote=realtime_quote)
    new_pair = nick_v216_parse_range_text(new_zone)
    shallow_pair = nick_v216_parse_range_text(shallow)

    # v247｜右側條件分層：右側啟動 / 右側確認 / 上方壓力分開，避免把前高壓力誤叫右側買點。
    right_stage_text = nick_v247_stage_right_plan_text(
        plan, price=price, ref_price=ref_price, shallow_text=shallow, wrong_text=wrong, right_text=right
    )

    # v218｜買點不漂移：股價已離開基本面支撐區後，程式可以新增「突破後回測區」，
    # 但不可把突破後回測區誤叫成左側主買，避免越漲越叫主買。
    post_breakout = False
    if support_pair and ref_price is not None:
        hi = support_pair[1]
        if ref_price > hi * 1.08:
            if new_pair and new_pair[0] > hi * 0.98:
                post_breakout = True
            elif shallow_pair and shallow_pair[0] > hi * 1.02:
                post_breakout = True
    if post_breakout:
        base_zone = nick_v216_format_range_from_tuple(support_pair) if support_pair else "資料不足"
        return (
            f"原始基本面甜點：{base_zone}｜突破後回測區：{new_zone}｜"
            f"淺回檔觀察：{shallow}｜{right_stage_text}｜短線防守：{wrong}｜波段防守：{stop}"
        )
    return f"左側主買：{new_zone}｜淺回檔試單：{shallow}｜{right_stage_text}｜短線防守：{wrong}｜波段防守：{stop}"

def nick_v217_percent_value(text):
    nums = re.findall(r"\d+(?:\.\d+)?", str(text or ""))
    if not nums:
        return None
    try:
        return float(nums[0])
    except Exception:
        return None


def nick_v217_percent_text(v):
    if v is None:
        return "資料不足"
    try:
        return f"{int(round(float(v)))}%"
    except Exception:
        return "資料不足"


def nick_v216_buy_probability_text(price=None, a=None, realtime_quote=None, support_range_text="", core_text="", inst=None):
    a = a or {}
    plan = a.get("plan", {}) or {}
    nums = plan.get("num", {}) or {}
    price_for_win = dict(price) if isinstance(price, dict) else {}
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    if ref_price is not None:
        price_for_win["close"] = ref_price

    def _one(label, entry, scenario):
        try:
            row = calc_future_win_one(label, entry, price_for_win, a, scenario_type=scenario)
            return str(row.get("20日區間") or row.get("20日勝率") or "資料不足")
        except Exception:
            return "資料不足"

    p_current = nick_v217_percent_value(_one("現價買", ref_price, "current"))
    p_shallow = nick_v217_percent_value(_one("淺回檔買", nums.get("shallow_high"), "pullback"))
    p_new = nick_v217_percent_value(_one("新倉主區買", nums.get("new_high"), "new_zone"))
    p_right = nick_v217_percent_value(_one("右側突破追價", nums.get("right"), "breakout"))

    support_pair = nick_v216_parse_range_text(support_range_text)
    report = nick_v217_financial_report_state(a)
    margin_state = nick_v217_margin_state(None, a)
    core_like = ("Core Yes" in str(core_text)) or ("Core 候選" in str(core_text))
    new_pair = nick_v216_parse_range_text(plan.get("new"))
    shallow_pair = nick_v216_parse_range_text(plan.get("shallow"))
    post_breakout = False
    above_support = False
    if support_pair and ref_price is not None:
        lo, hi = support_pair
        gap = ref_price / hi - 1 if hi else 0
        above_support = ref_price > hi
        if above_support:
            # 現價已離開基本面支撐區，不能因 Core Yes 就給高現價勝率。
            cap = 55
            if gap >= 0.08:
                cap = 50
            if gap >= 0.20:
                cap = 45
            if p_current is not None:
                p_current = min(p_current, cap)
        if ref_price > hi * 1.08 and ((new_pair and new_pair[0] > hi * 0.98) or (shallow_pair and shallow_pair[0] > hi * 1.02)):
            post_breakout = True

    if "Core 候選" in str(core_text) and p_current is not None:
        p_current = min(p_current, 42)

    if core_like and report != "不通過":
        if post_breakout:
            # 突破後回測區不是原始主買甜點，勝率可提高但不得等同低位主買。
            if p_shallow is not None:
                p_shallow = min(max(p_shallow, 55), 62)
            if p_new is not None:
                p_new = min(max(p_new, 60), 66)
            if p_right is not None:
                p_right = min(max(p_right, 52), 60)
        else:
            if p_shallow is not None:
                p_shallow = min(max(p_shallow, 54), 64)
            if p_new is not None:
                floor_new = 64
                if margin_state == "弱化":
                    floor_new = 58
                p_new = min(max(p_new, floor_new), 72)
            if p_right is not None:
                p_right = min(max(p_right, 48), 60)
    if p_current is not None and p_new is not None and p_new <= p_current and core_like:
        p_new = min(max(p_current + 8, p_new), 72 if not post_breakout else 66)
    if p_current is not None and p_shallow is not None and p_shallow < p_current and above_support:
        p_shallow = min(max(p_current + 4, p_shallow), 64)

    # v219｜過熱追價扣分：漲停/爆量/明顯高於支撐區且財報未完整接棒時，現價勝率必須大幅降低。
    if nick_v219_is_hot_chase_risk(price, a, support_range_text, realtime_quote, core_text):
        if p_current is not None:
            p_current = min(p_current, 30)
        if p_shallow is not None:
            p_shallow = min(max(p_shallow, 45), 52)
        if p_new is not None:
            p_new = min(max(p_new, 58), 65)
        if p_right is not None:
            p_right = min(max(p_right, 40), 50)

    # v221｜金庫 Core 股遇高檔倒貨：公司再好，交易面未止跌前現價勝率要硬降級。
    if nick_v221_high_level_distribution_risk(price, inst, a):
        if p_current is not None:
            p_current = min(p_current, 30)
        if p_shallow is not None:
            p_shallow = min(max(p_shallow, 40), 50)
        if p_new is not None:
            p_new = min(max(p_new, 65), 70)
        if p_right is not None:
            p_right = min(max(p_right, 55), 60)

    return f"現價：{nick_v217_percent_text(p_current)}｜回淺回檔區守住：{nick_v217_percent_text(p_shallow)}｜回新倉/回測區且基本面沒壞：{nick_v217_percent_text(p_new)}｜右側突破站穩：{nick_v217_percent_text(p_right)}"


def nick_v216_accumulation_text(price=None, inst=None, a=None, support_range_text="", realtime_quote=None):
    inst = inst or {}
    a = a or {}
    diag = a.get("_diag", {}) or {}
    foreign5 = to_float(inst.get("foreign_net5_lot") or inst.get("foreign5_lot") or inst.get("foreign_5d"))
    trust5 = to_float(inst.get("trust_net5_lot") or inst.get("investment_trust_net5_lot") or inst.get("trust_5d"))
    dealer5 = to_float(inst.get("dealer_net5_lot") or inst.get("dealer_5d"))
    net5 = to_float(inst.get("net5_lot") or inst.get("total_5d"))
    foreign20 = to_float(inst.get("foreign_net20_lot") or inst.get("foreign20_lot") or inst.get("foreign_20d"))
    trust20 = to_float(inst.get("trust_net20_lot") or inst.get("investment_trust_net20_lot") or inst.get("trust_20d"))
    dealer20 = to_float(inst.get("dealer_net20_lot") or inst.get("dealer_20d"))
    net20 = to_float(inst.get("net20_lot") or inst.get("total_20d"))
    margin_chg = to_float(inst.get("margin_balance_change_5d") or inst.get("margin_chg_5d") or inst.get("margin_change_5d"))
    chip_type = str(diag.get("chip_pressure_type") or diag.get("atk_chip_health_status") or "")
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    support_pair = nick_v216_parse_range_text(support_range_text)
    price_high_vs_support = bool(support_pair and ref_price is not None and ref_price > support_pair[1])
    core_or_treasury_like = nick_v221_is_core_or_treasury_like(a)
    high_distribution = nick_v221_high_level_distribution_risk(price, inst, a)

    if any(v is not None for v in [foreign5, trust5, dealer5, net5, foreign20, trust20, dealer20, net20]):
        foreign_buy = (foreign5 is not None and foreign5 > 0) or (foreign20 is not None and foreign20 > 0)
        foreign_sell = (foreign5 is not None and foreign5 < 0) or (foreign20 is not None and foreign20 < 0)
        trust_buy = (trust5 is not None and trust5 > 0) or (trust20 is not None and trust20 > 0)
        dealer_buy = (dealer5 is not None and dealer5 > 0) or (dealer20 is not None and dealer20 > 0)
        trust_sell = (trust5 is not None and trust5 < 0) or (trust20 is not None and trust20 < 0)
        dealer_sell = (dealer5 is not None and dealer5 < 0) or (dealer20 is not None and dealer20 < 0)
        total_buy = (net5 is not None and net5 > 0) or (net20 is not None and net20 > 0)
        total_sell = (net5 is not None and net5 < 0) or (net20 is not None and net20 < 0)
        turnaround_attack = nick_v219_is_turnaround_attack_context(a, None)

        if high_distribution and core_or_treasury_like:
            if trust_buy and foreign_sell:
                judgement = "財報型 Core 股，但短線不是乾淨吃貨｜投信承接 / 外資調節"
                meaning = "公司可收編不等於現在可重押；目前較像法人分歧與高檔換手，先等止跌、站回關鍵價與賣壓縮小。"
            elif total_sell and not trust_buy:
                judgement = "財報型 Core 股，但短線不是吃貨｜高檔換手 / 出貨疑慮"
                meaning = "公司可收編不等於現在在吃貨；若法人續賣或大量長黑，先等止跌與賣壓縮小。"
            else:
                judgement = "財報型 Core 股，但短線不是乾淨吃貨｜高檔換手 / 籌碼調節"
                meaning = "公司可收編，但短線籌碼不夠乾淨；先等支撐、站回與法人賣壓縮小。"
        elif high_distribution:
            if trust_buy and foreign_sell:
                judgement = "法人分歧｜投信承接 / 外資調節"
                meaning = "有承接但不全面同向，不等於乾淨吃貨；先看支撐與賣壓是否縮小。"
            else:
                judgement = "高檔換手 / 出貨疑慮"
                meaning = "短線籌碼偏退潮，不能解讀成吃貨；先等支撐與賣壓確認。"
        elif "出貨" in chip_type:
            judgement = "高檔換手 / 出貨疑慮"
            meaning = "先不要把法人買賣當吃貨，等支撐與賣壓確認。"
        elif price_high_vs_support and (total_sell or (foreign5 is not None and foreign5 < 0)):
            judgement = "高檔換手偏調節，尚未乾淨吃貨"
            meaning = "股價在支撐區上方但法人偏賣，不能解讀成乾淨吃貨；等止賣或回檔承接。"
        elif foreign_buy and total_buy and turnaround_attack:
            judgement = "外資主導短中線吃貨，非財報型 Core 吃貨"
            meaning = "法人買盤有攻擊味，但財報尚未完整接棒；可做小倉觀察，不等於 Core 重押吃貨。"
        elif foreign_buy and trust_buy and (dealer_buy or dealer5 is None and dealer20 is None) and total_buy:
            judgement = "明顯乾淨吃貨"
            meaning = "外資與投信同向偏買，籌碼品質較乾淨；仍要看買點與風報比。"
        elif foreign_buy and total_buy and (trust_sell or dealer_sell):
            judgement = "外資主導吃貨，非全面同向"
            meaning = "有吃貨，但不是所有法人一起買；可觀察，不等於可重押。"
        elif foreign_buy and total_buy:
            judgement = "外資主導吃貨"
            meaning = "外資明顯回補，但仍要確認投信、自營商是否跟上。"
        elif foreign5 is not None and foreign5 > 0 and trust5 is not None and trust5 < 0:
            judgement = "有回補跡象，但不乾淨"
            meaning = "外資買、投信賣，不是乾淨吃貨；可觀察，不重押。"
        elif trust_buy and (foreign5 is None or foreign5 >= 0 or (foreign20 is not None and foreign20 >= 0)):
            judgement = "投信主導回補"
            meaning = "投信連買、外資止賣，吃貨品質提高；仍要看買點。"
        elif total_buy:
            judgement = "有回補跡象"
            meaning = "法人開始回補，但需確認不是高檔追價。"
        elif total_sell or (foreign5 is not None and foreign5 < 0):
            judgement = "短線調節 / 尚未乾淨吃貨"
            meaning = "法人偏賣不等於出貨；若守支撐可觀察，跌破支撐就降風險。"
        else:
            judgement = "尚未乾淨吃貨"
            meaning = "籌碼還不夠集中，先看法人是否轉連買。"
        if margin_chg is not None and margin_chg > 0 and judgement in ["明顯乾淨吃貨", "外資主導吃貨", "外資主導吃貨，非全面同向", "有回補跡象", "投信主導回補"]:
            judgement = judgement + "｜融資升溫"
            meaning = meaning + " 融資增加，追價風險同步升高。"
        return judgement, meaning
    return "資料不足", "待法人 5 日 / 20 日與融資資料確認。"




def nick_v255_compact_core_text(core_text="", treasury_text="", a=None):
    core_s = str(core_text or "")
    tre_s = str(treasury_text or "")
    if "Core Yes" in core_s:
        return f"公司可收編｜{tre_s or '金庫待確認'}"
    if "候選" in core_s:
        return f"可觀察｜{tre_s or '候選待驗證'}"
    if "公司體質未通過" in core_s or "No" in core_s:
        return "暫不收編｜先等證據"
    return f"{core_s or '資料不足'}｜{tre_s or '金庫待確認'}"


def nick_v255_compact_support_text(support_range="", support_judgement=""):
    sj = str(support_judgement or "")
    if "高於" in sj:
        pos = "現價高於支撐，等接棒或回檔"
    elif "低於" in sj:
        pos = "現價低於支撐，先確認基本面"
    elif "位於" in sj or "支撐區內" in sj:
        pos = "現價在支撐區內，仍看買點"
    else:
        pos = sj or "位置待確認"
    return f"支撐區：{support_range or '資料不足'}｜{pos}"


def nick_v255_compact_target_text(a=None, price=None, support_range_text="", realtime_quote=None, inst=None):
    raw = nick_v216_target_text(a, price=price, support_range_text=support_range_text, realtime_quote=realtime_quote, inst=inst)
    s = str(raw or "")
    short = "資料不足"
    wave = "資料不足"
    strong = "需財報接棒"
    m = re.search(r"短線(?:壓力/)?目標[：:]\s*([^｜;；]+)", s)
    if m:
        short = m.group(1).strip()
    m = re.search(r"波段目標[：:]\s*([^｜;；]+)", s)
    if m:
        wave = m.group(1).strip()
    if "需" in s and "驗證" in s:
        strong = "強勢區需驗證"
    elif "重評" in s:
        strong = "重評區需接棒"
    return f"短線：{short}｜波段：{wave}｜{strong}"


def nick_v255_first_right_level(text=""):
    s = str(text or "")
    pats = [
        r"第一段確認[：:][^\d]*(\d[\d,]*(?:\.\d+)?)",
        r"右側確認[：:][^\d]*(\d[\d,]*(?:\.\d+)?)",
        r"突破[^\d]*(\d[\d,]*(?:\.\d+)?)",
        r"站回[^\d]*(\d[\d,]*(?:\.\d+)?)",
        r"站上[^\d]*(\d[\d,]*(?:\.\d+)?)",
    ]
    for pat in pats:
        m = re.search(pat, s)
        if m:
            v = to_float(str(m.group(1)).replace(',', ''))
            if v is not None:
                return fmt_price(v)
    v = nick_v217_price_anchor(s)
    return fmt_price(v) if v is not None else "等右側確認"


def nick_v255_compact_buy_point_text(a=None, price=None, support_range_text="", realtime_quote=None, inst=None):
    a = a or {}
    plan = a.get("plan", {}) or {}
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    support_pair = nick_v216_parse_range_text(support_range_text)
    new_zone = nick_v216_clean_text(plan.get("new"), "資料不足")
    shallow = nick_v216_clean_text(plan.get("shallow"), "資料不足")
    wrong = nick_v216_clean_text(plan.get("wrong"), "資料不足")
    stop = nick_v216_clean_text(plan.get("stop"), "資料不足")
    right = nick_v255_first_right_level(plan.get("right"))
    action = "等買點"
    try:
        if support_pair and ref_price is not None:
            lo, hi = support_pair
            if ref_price < lo:
                action = "低於支撐｜先確認基本面"
            elif lo <= ref_price <= hi:
                action = "支撐區內｜小倉或等回檔"
            elif ref_price > hi:
                action = "高於支撐｜等回檔不追"
        elif str(a.get("action", "")):
            action = str(a.get("action"))
    except Exception:
        pass
    # 小白只要知道：現在要不要動、左側/回檔/右側/認錯，不展開第二段確認與壓力階層。
    defense = wrong if wrong and wrong != "資料不足" else stop
    return f"{action}｜左側：{new_zone}｜回檔：{shallow}｜右側：{right}｜失效：{defense}"


def nick_v255_compact_buy_probability_text(price=None, a=None, realtime_quote=None, support_range_text="", core_text="", inst=None):
    raw = nick_v216_buy_probability_text(price, a, realtime_quote=realtime_quote, support_range_text=support_range_text, core_text=core_text, inst=inst)
    s = str(raw or "")
    # 保留四個情境，但用白話標籤，避免被誤會成勝率保證。
    s = s.replace("回新倉/回測區且基本面沒壞", "回買點且基本面沒壞")
    s = s.replace("右側突破站穩", "突破站穩")
    return s


def nick_v255_compact_accumulation_text(eat_text="", eat_meaning=""):
    blob = f"{eat_text}｜{eat_meaning}"
    if any(k in blob for k in ["出貨", "高檔換手"]):
        verdict = "籌碼偏亂｜先觀察"
        note = "有高檔換手或賣壓疑慮，不解讀成乾淨吃貨；等止跌與賣壓縮小。"
    elif "融資" in blob and any(k in blob for k in ["吃貨", "回補", "承接"]):
        verdict = "有承接但不乾淨｜不重押"
        note = "法人有買盤，但融資同步升溫；可觀察，不適合重押追。"
    elif any(k in blob for k in ["分歧", "投信承接", "外資調節"]):
        verdict = "有承接但分歧｜看支撐"
        note = "法人不是全面同向，先看支撐能不能守住。"
    elif "明顯乾淨吃貨" in blob:
        verdict = "籌碼健康｜可觀察"
        note = "法人同向偏買，籌碼較乾淨；仍要看買點與風報比。"
    elif any(k in blob for k in ["外資主導", "有回補", "投信主導"]):
        verdict = "有回補跡象｜不追高"
        note = "有買盤，但仍要確認不是高檔追價。"
    elif any(k in blob for k in ["短線調節", "偏賣"]):
        verdict = "短線調節｜守支撐再看"
        note = "法人偏賣不等於出貨；守支撐可觀察，跌破就降風險。"
    elif "資料不足" in blob:
        verdict = "籌碼資料不足｜先不判定"
        note = "等法人 5 日 / 20 日與融資資料確認。"
    else:
        verdict = str(eat_text or "尚未乾淨吃貨")
        note = str(eat_meaning or "籌碼還要再確認。")
    return verdict, note



# =========================================================
# v248｜主力行為推論 + 散戶人性防呆層
# 定位：只做買後導航的「原因解釋與人性提醒」，不覆蓋 v247/進場條件裁決。
# =========================================================
def nick_v248_take_upper_from_range_text(text, fallback=None):
    """區間字串取上緣，作為嚴格防守/確認線。"""
    try:
        r = nick_v247_parse_zone(text)
        if r:
            return to_float(r[1])
    except Exception:
        pass
    try:
        v = nick_v217_price_anchor(text)
        if v is not None:
            return to_float(v)
    except Exception:
        pass
    return fallback


def nick_v248_pick_realtime_volume(realtime_quote=None, volume_ma20=None):
    """v281.8｜v248 即時成交量欄位對齊。

    TWSE MIS / 其他即時來源的成交量欄位不一定叫 volume。
    v248 原本只讀 q.get("volume")，會吃不到 app 傳入的 volume_raw，
    進而把缺量誤算成 0.00x。

    回傳：
    - volume：已校正到與日 K Trading_Volume 接近的量級
    - source：實際吃到的欄位名稱，方便後續診斷
    """
    q = realtime_quote or {}
    if not isinstance(q, dict):
        return None, "quote 非 dict"

    # 只把「累積成交量」類欄位拿來算量比；last_trade_volume/tv 只是單筆成交量，不拿來當今日量。
    candidate_keys = [
        "volume_raw",
        "volume",
        "total_volume",
        "acc_volume",
        "accumulated_volume",
        "cumulative_volume",
        "trade_volume",
        "Trading_Volume",
        "v",
    ]
    raw_vol = None
    raw_key = None
    for key in candidate_keys:
        v = to_float(q.get(key))
        if v is not None and v > 0:
            raw_vol = float(v)
            raw_key = key
            break

    if raw_vol is None or raw_vol <= 0:
        return None, "即時累積成交量未取得"

    vol = raw_vol
    avg = to_float(volume_ma20)

    # 單位校正：FinMind 日 K 多半是股數；TWSE MIS 的 v 常見為張。
    # 用 20 日均量作量級對齊，不猜特定來源。
    try:
        if avg is not None and avg > 0:
            if avg >= 10000 and vol < avg / 100:
                vol = vol * 1000.0
                raw_key = f"{raw_key}×1000(張→股)"
            elif avg < 100000 and vol > avg * 100:
                vol = vol / 1000.0
                raw_key = f"{raw_key}/1000(股→張)"
    except Exception:
        pass

    if vol is None or vol <= 0:
        return None, "即時成交量校正後無效"
    return float(vol), raw_key or "即時成交量"


def nick_v248_get_latest_ohlcv(price=None, realtime_quote=None):
    """從日K與盤中報價取得 v248 需要的 OHLCV。

    v281.8 修正重點：
    - 優先讀取即時報價的 volume_raw / total_volume / acc_volume 等累積量欄位。
    - 不再只讀 q.get("volume")。
    - 缺量不補 0，避免前台誤顯示量比 0.00x。
    """
    price = price or {}
    q = realtime_quote or {}
    raw = price.get("raw")
    open_p = high_p = low_p = close_p = volume = volume_ma20 = volume_ma5 = None
    volume_source = ""
    try:
        if raw is not None and not getattr(raw, "empty", True):
            df = raw.copy().sort_values("date")
            last = df.iloc[-1]
            open_p = to_float(last.get("open"))
            high_p = to_float(last.get("max") if "max" in df.columns else last.get("high"))
            low_p = to_float(last.get("min") if "min" in df.columns else last.get("low"))
            close_p = to_float(last.get("close"))
            if "Trading_Volume" in df.columns:
                v0 = to_float(last.get("Trading_Volume"))
                if v0 is not None and v0 > 0:
                    volume = v0
                    volume_source = "日K Trading_Volume"
                volume_ma20 = to_float(df["Trading_Volume"].tail(20).mean())
                volume_ma5 = to_float(df["Trading_Volume"].tail(5).mean())
    except Exception:
        pass

    # 若 price dict 已有均量欄位，補進來讓即時量可以做單位校正。
    if volume_ma20 in [None, 0]:
        volume_ma20 = to_float(price.get("avg_volume20") or price.get("volume_ma20") or price.get("VolMA20"))
    if volume_ma5 in [None, 0]:
        volume_ma5 = to_float(price.get("avg_volume5") or price.get("volume_ma5") or price.get("VolMA5"))

    try:
        q_price = to_float(q.get("price") or q.get("realtime_price"))
        if q_price is not None and q_price > 0:
            close_p = q_price
            open_p = to_float(q.get("open")) or open_p or q_price
            high_candidates = [to_float(q.get("high")), open_p, q_price, high_p]
            low_candidates = [to_float(q.get("low")), open_p, q_price, low_p]
            high_p = max([x for x in high_candidates if x is not None])
            low_p = min([x for x in low_candidates if x is not None])
            q_vol, q_vol_src = nick_v248_pick_realtime_volume(q, volume_ma20)
            if q_vol is not None and q_vol > 0:
                volume = q_vol
                volume_source = f"即時報價 {q_vol_src}"
    except Exception:
        pass

    close_p = close_p if close_p is not None else to_float(price.get("close"))
    open_p = open_p if open_p is not None else close_p
    high_p = high_p if high_p is not None else close_p
    low_p = low_p if low_p is not None else close_p

    # 缺量不補 0；量比缺資料就不顯示、不參與 v248 行為判斷。
    if volume is not None and volume <= 0:
        volume = None
    if volume_ma20 is not None and volume_ma20 <= 0:
        volume_ma20 = None
    if volume_ma5 is not None and volume_ma5 <= 0:
        volume_ma5 = None
    return open_p, high_p, low_p, close_p, volume, volume_ma5, volume_ma20, volume_source


def nick_v248_post_buy_status_from_context(a=None, price=None, realtime_quote=None):
    """用既有裁決轉成買後導航狀態；不創造新買賣裁決。"""
    a = a or {}
    action = str(a.get("action", "") or "")
    plan = a.get("plan", {}) or {}
    ref_price, _ = nick_v216_reference_price(price, realtime_quote)
    stop_p = nick_v248_take_upper_from_range_text(plan.get("stop"), None)
    wrong_p = nick_v248_take_upper_from_range_text(plan.get("wrong"), None)
    wave_p = nick_v248_take_upper_from_range_text(plan.get("wave"), None)
    if ref_price is not None and stop_p is not None and ref_price < stop_p:
        return "出清"
    if ref_price is not None and wrong_p is not None and ref_price < wrong_p:
        return "減碼警戒"
    if ref_price is not None and wave_p is not None and ref_price >= wave_p:
        return "獲利落袋"
    if any(k in action for k in ["出清", "轉弱", "停損"]):
        return "出清"
    if any(k in action for k in ["減碼", "降風險", "降低部位"]):
        return "減碼警戒"
    if any(k in action for k in ["獲利", "分批", "停利"]):
        return "獲利落袋"
    if any(k in action for k in ["續抱", "抱", "持有"]):
        return "續抱"
    if any(k in action for k in ["等回檔", "觀察", "小倉", "不追"]):
        return "觀察中"
    return "觀察中"


def nick_v248_infer_smart_money_psychology(stock=None, name=None, price=None, inst=None, rev=None, fin=None, a=None, realtime_quote=None, current_zone=""):
    """v248｜主力行為推論 + 散戶人性防呆。只做機率推論，不推翻 v247/v241 的買賣裁決。"""
    price = price or {}
    inst = inst or {}
    rev = rev or {}
    fin = fin or {}
    a = a or {}
    plan = a.get("plan", {}) or {}
    open_p, high_p, low_p, close_p, volume, volume_ma5, volume_ma20, volume_source = nick_v248_get_latest_ohlcv(price, realtime_quote)
    current_price = close_p or to_float(price.get("close"))
    ma5 = to_float(price.get("ma5"))
    ma10 = to_float(price.get("ma10"))
    ma20 = to_float(price.get("ma20"))
    ma60 = to_float(price.get("ma60"))
    ret5 = to_float(price.get("ret5"))
    short_invalid = nick_v248_take_upper_from_range_text(plan.get("wrong"), ma20 or ma10 or ma5 or current_price)
    swing_defense = nick_v248_take_upper_from_range_text(plan.get("stop"), ma60 or ma20 or current_price)
    valuation_ceiling = nick_v248_take_upper_from_range_text(plan.get("wave"), None)
    if valuation_ceiling is None:
        try:
            _case = a.get("_ai_core_saved_case") if isinstance(a.get("_ai_core_saved_case"), dict) else {}
            valuation_ceiling = nick_v248_take_upper_from_range_text((_case or {}).get("rerating_zone") or (_case or {}).get("重評合理區"), None)
        except Exception:
            pass
    if valuation_ceiling is None:
        valuation_ceiling = 999999999
    high_p = high_p if high_p is not None else current_price
    low_p = low_p if low_p is not None else current_price
    open_p = open_p if open_p is not None else current_price
    k_range = (high_p - low_p) if high_p is not None and low_p is not None else 0
    is_black_k = bool(current_price is not None and open_p is not None and current_price < open_p)
    upper_shadow_ratio = 0
    if k_range and k_range > 0:
        upper_shadow_ratio = max(0, (high_p - max(current_price or high_p, open_p or high_p)) / k_range)
    is_long_upper_shadow = upper_shadow_ratio >= 0.40
    ma60_bias = (current_price - ma60) / ma60 if current_price is not None and ma60 not in [None, 0] else 0
    ma5_bias = (current_price - ma5) / ma5 if current_price is not None and ma5 not in [None, 0] else 0
    vol_ratio = (volume / volume_ma20) if (volume is not None and volume > 0 and volume_ma20 not in [None, 0]) else None
    net5 = to_float(inst.get("net5_lot") or inst.get("total_5d")) or 0
    vol5_lot = None
    try:
        raw = price.get("raw")
        if raw is not None and not getattr(raw, "empty", True) and "Trading_Volume" in raw.columns:
            vol5_lot = to_float(raw.sort_values("date")["Trading_Volume"].tail(5).sum()) / 1000
    except Exception:
        vol5_lot = None
    if not vol5_lot or vol5_lot <= 0:
        vol5_lot = max(1, (to_float(price.get("volume_lot")) or 0) * 5)
    inst_buy_ratio_5d = net5 / vol5_lot if vol5_lot else 0
    margin_change_ratio = to_float(inst.get("margin_change_5d_ratio") or inst.get("margin_balance_change_5d_ratio") or inst.get("margin_change_ratio")) or 0
    post_buy_status = nick_v248_post_buy_status_from_context(a, price, realtime_quote)
    action_txt = str(a.get("action", "") or "")
    zone_txt = str(current_zone or "")
    state = "NEUTRAL"
    state_label = "無明顯主力行為"
    severity = "neutral"
    behavior_reason = "目前價量與籌碼沒有出現明顯洗盤、出貨或吃貨特徵，先依原本買點與防守點觀察。"
    retail_risk = "不要因為盤中一兩根K棒就自行改劇本；先看防守點、量能與法人是否同步轉壞。"
    mindset = "照系統原定交易計畫執行，等待更清楚的價量或基本面證據。"
    tags = []
    if post_buy_status == "出清":
        state, state_label, severity = "RISK_CONFIRMED", "風控已觸發｜不要再猜洗盤", "danger"
        behavior_reason = "價格已跌破核心防守或原本買進理由失效，主力行為推論不再優先於風控紀律。"
        retail_risk = "最容易犯的錯，是把該認錯的位置硬解讀成洗盤，讓小虧變大虧。"
        mindset = "依 v247 防線出清或大幅降風險，先保護本金。"
        tags = ["v247風控優先", "停止凹單"]
    elif post_buy_status == "減碼警戒":
        state, state_label, severity = "RISK_ALERT", "防線鬆動｜先降風險", "warn"
        behavior_reason = "短線防線已鬆動，若再疊加法人調節、量價轉弱或族群退潮，容易由洗盤變成轉弱。"
        retail_risk = "不要一邊喊觀察，一邊偷加碼攤平；警戒狀態重點是降低曝險。"
        mindset = "停止加碼，必要時先減碼一部分，等站回關鍵線再評估。"
        tags = ["減碼警戒", "禁止攤平"]
    elif post_buy_status == "獲利落袋":
        state, state_label, severity = "PROFIT_REALIZATION", "利多實現｜分批落袋", "good"
        behavior_reason = "股價已接近或超過波段目標 / 重評上緣，上檔空間變小，風報比開始惡化。"
        retail_risk = "不要把帳上獲利當成永遠存在；目標到位時，貪心常常會吃掉前面的紀律。"
        mindset = "可分批獲利，保留部分部位看延伸，但先把一部分成果收進口袋。"
        tags = ["分批獲利", "保護成果"]
    else:
        if (ma60_bias > 0.20 or (valuation_ceiling and valuation_ceiling < 999999999 and current_price and current_price > valuation_ceiling * 0.90)) and vol_ratio is not None and vol_ratio > 1.5:
            if is_long_upper_shadow or is_black_k or inst_buy_ratio_5d < -0.08:
                state, state_label, severity = "DISTRIBUTION", "高檔出貨嫌疑升高", "danger"
                behavior_reason = "股價位階偏高，且出現爆量、長上影 / 黑K，或法人五日賣超占比偏高，像是高檔換手偏出貨。"
                retail_risk = "不要把爆量長上影誤判成健康換手；利多見報後不漲反跌，要先看籌碼。"
                mindset = "停止加碼，若跌破短線失效點，先減碼保護本金。"
                tags = ["高位階", "爆量/長上影", "停看聽"]
        if state == "NEUTRAL" and vol_ratio is not None and vol_ratio > 1.2 and margin_change_ratio > 0.25 and inst_buy_ratio_5d < -0.05:
            state, state_label, severity = "RETAIL_TRAP", "散戶接盤風險升高", "danger"
            behavior_reason = "股價熱度仍在，但融資明顯增加、法人五日偏賣，籌碼可能由大戶流向散戶。"
            retail_risk = "人多的地方不一定安全；越熱的題材，越要回頭看誰在買、誰在賣。"
            mindset = "不要追熱度，不要攤平，先等籌碼重新乾淨。"
            tags = ["融資升溫", "法人偏賣", "避免接刀"]
        if state == "NEUTRAL" and current_price is not None and short_invalid is not None and swing_defense is not None:
            if current_price < short_invalid and current_price >= swing_defense and (vol_ratio is None or vol_ratio < 0.85) and inst_buy_ratio_5d >= -0.06:
                state, state_label, severity = "SHAKEOUT", "偏洗盤震倉", "good"
                behavior_reason = "跌破短線失效，但仍守波段防守；量能縮小且法人沒有大幅倒貨，比較像清洗浮額。"
                retail_risk = "容易因為短線黑K恐慌賣在低點；真正該看的是波段防守有沒有破。"
                mindset = "續抱觀察波段防守，不急著砍，也不急著加碼。"
                tags = ["量縮", "守波段防守", "免驚但要盯線"]
        if state == "NEUTRAL" and ma20 not in [None, 0] and current_price is not None:
            if abs(current_price - ma20) / ma20 < 0.05 and (vol_ratio is None or vol_ratio < 0.75) and ("等" in action_txt or "觀察" in action_txt or "盤整" in zone_txt):
                state, state_label, severity = "ROTATION_REST", "資金輪動休息", "neutral"
                behavior_reason = "股價靠近均線縮量整理，基本面未明顯壞掉，比較像資金暫時去別的族群。"
                retail_risk = "容易看別檔噴出就焦躁換股，結果剛賣掉就輪回來。"
                mindset = "先看支撐與基本面是否守住，等資金重新回流。"
                tags = ["縮量整理", "等輪動", "不亂換股"]
        if state == "NEUTRAL" and abs(ma60_bias) < 0.08 and (vol_ratio is None or vol_ratio >= 0.75) and inst_buy_ratio_5d > 0.03 and (ret5 is None or abs(ret5) < 3):
            state, state_label, severity = "ACCUMULATION", "偏吃貨吸籌", "good"
            behavior_reason = "股價低位階或接近中期均線，漲幅不大，但法人五日買超占成交量比例轉強，像是低調卡位。"
            retail_risk = "容易因為短線無聊就放棄；真正的吃貨期常常不會立刻噴。"
            mindset = "列入觀察，等營收、量價或右側突破點火。"
            tags = ["低調卡位", "法人買超比例", "耐心等點火"]
        if state == "NEUTRAL" and ma5 not in [None, 0] and current_price is not None and ma5_bias > 0.06 and current_price > ma5:
            if vol_ratio is None or vol_ratio < 2.5:
                state, state_label, severity = "SHORT_SQUEEZE", "軋空推進", "warn"
                behavior_reason = "股價沿短均線向上推進，乖離偏高但量能尚未失控，屬於主升段高位階推進。"
                retail_risk = "空手者最容易 FOMO 追高；持有者則容易太早賣掉主升段。"
                mindset = "持有者用移動防守點抱住；空手者不要情緒化追價。"
                tags = ["主升推進", "持有守線", "空手禁追"]
    if not tags:
        tags = ["先觀察"]
    return {
        "smart_money_state": state,
        "state_label": state_label,
        "severity": severity,
        "behavior_reason": behavior_reason,
        "retail_psychology_risk": retail_risk,
        "suggested_mindset": mindset,
        "system_action": mindset,
        "post_buy_status": post_buy_status,
        "tags": tags,
        "metrics": {
            "ma60_bias": ma60_bias,
            "ma5_bias": ma5_bias,
            "vol_ratio": vol_ratio,
            "volume_source": volume_source,
            "inst_buy_ratio_5d": inst_buy_ratio_5d,
            "short_invalid": short_invalid,
            "swing_defense": swing_defense,
        }
    }


def render_nick_v248_smart_money_card(stock=None, name=None, price=None, inst=None, rev=None, fin=None, a=None, realtime_quote=None, current_zone=""):
    """前台卡：主力行為推論 + 人性防呆。"""
    try:
        r = nick_v248_infer_smart_money_psychology(stock, name, price, inst, rev, fin, a, realtime_quote, current_zone)
        sev = r.get("severity", "neutral")
        card_cls = {"danger": "smart-card smart-card-danger", "warn": "smart-card smart-card-warn", "good": "smart-card smart-card-good", "neutral": "smart-card"}.get(sev, "smart-card")
        state_cls = {"danger": "smart-state smart-state-danger", "warn": "smart-state smart-state-warn", "good": "smart-state smart-state-good", "neutral": "smart-state"}.get(sev, "smart-state")
        tag_cls = {"danger": "smart-tag smart-tag-danger", "warn": "smart-tag smart-tag-warn", "good": "smart-tag smart-tag-good", "neutral": "smart-tag smart-tag-info"}.get(sev, "smart-tag")
        tags_html = "".join([f'<span class="{tag_cls}">{_html.escape(str(t))}</span>' for t in (r.get("tags") or [])[:5]])
        metrics = r.get("metrics", {}) or {}
        metric_tags = []
        if metrics.get("vol_ratio") is not None and float(metrics.get("vol_ratio") or 0) > 0:
            metric_tags.append(f"量比 {float(metrics.get('vol_ratio')):.2f}x")
        elif metrics.get("volume_source"):
            metric_tags.append("量比 資料不足")
        if metrics.get("inst_buy_ratio_5d") is not None:
            metric_tags.append(f"法人買賣占比 {float(metrics.get('inst_buy_ratio_5d'))*100:+.1f}%")
        if metrics.get("short_invalid") is not None:
            metric_tags.append(f"短線防守 {fmt_price(metrics.get('short_invalid'))}")
        metric_html = "".join([f'<span class="smart-tag">{_html.escape(str(t))}</span>' for t in metric_tags[:4]])
        html = f"""
<div class="{card_cls}">
  <div class="smart-head">
    <div>
      <div class="smart-kicker">主力行為觀察</div>
      <div class="{state_cls}">{_html.escape(str(r.get('state_label', '—')))}</div>
    </div>
  </div>
  <div class="smart-body">
    <div class="smart-row"><b>行為推論：</b>{_html.escape(str(r.get('behavior_reason', '—')))}</div>
    <div class="smart-row"><b>人性防呆：</b>{_html.escape(str(r.get('retail_psychology_risk', '—')))}</div>
    <div class="smart-row"><b>操作建議：</b>{_html.escape(str(r.get('suggested_mindset', '—')))}</div>
  </div>
  <div class="smart-tags">{tags_html}{metric_html}</div>
  <div class="smart-muted">這張卡只用來觀察主力行為與情緒風險，不會覆蓋上方最終動作。</div>
</div>
"""
        st.markdown(html, unsafe_allow_html=True)
    except Exception as _e:
        st.caption(f"主力行為觀察暫時無法顯示：{_e}")

def build_beginner_decision_rows_v216(stock, name, price, rev, fin, inst, a, current_zone="", buy_zone_summary=None, fund_support=None, realtime_quote=None):
    """v219：只讀既有結果並做通用法醫校正；新增轉機攻擊股過熱扣分、目標區間、防守點與財報型 Core 吃貨分級。"""
    core_text, treasury_text = nick_v216_core_and_treasury(a, fin=fin)
    support_range, support_judgement = nick_v216_support_text(price, a, current_zone=current_zone, fund_support=fund_support, realtime_quote=realtime_quote)
    eat_text, eat_meaning = nick_v216_accumulation_text(price, inst, a, support_range_text=support_range, realtime_quote=realtime_quote)
    eat_simple, eat_note = nick_v255_compact_accumulation_text(eat_text, eat_meaning)
    rows = [
        {
            "問題": "公司體質 / 財報等級",
            "判斷": nick_v255_compact_core_text(core_text, treasury_text, a),
            "操作意思": nick_v247_core_treasury_note(a, a.get("_ai_core_saved_case") if isinstance(a.get("_ai_core_saved_case"), dict) else None),
        },
        {
            "問題": "下個月是否更進步",
            "判斷": f"{nick_v218_month_progress_text(rev, inst, a)}",
            "操作意思": "看營收能不能續強；YoY 比 MoM 更重要。",
        },
        {
            "問題": "下季是否更進步",
            "判斷": f"{nick_v218_quarter_progress_text(fin, a)}",
            "操作意思": "看營收能不能轉成 EPS、毛利率與現金流。",
        },
        {
            "問題": "基本面支撐",
            "判斷": nick_v255_compact_support_text(support_range, support_judgement),
            "操作意思": "支撐區是公司價值參考，不等於現價一定能買。",
        },
        {
            "問題": "波段目標價",
            "判斷": nick_v255_compact_target_text(a, price=price, support_range_text=support_range, realtime_quote=realtime_quote, inst=inst),
            "操作意思": "先看短線壓力，再看波段；強勢區要靠財報接棒。",
        },
        {
            "問題": "左側 / 右側買點",
            "判斷": nick_v255_compact_buy_point_text(a, price=price, support_range_text=support_range, realtime_quote=realtime_quote, inst=inst),
            "操作意思": "左側看承接，右側看站穩；買錯就照失效點處理。",
        },
        {
            "問題": "AI判斷買進意願",
            "判斷": nick_v255_compact_buy_probability_text(price, a, realtime_quote=realtime_quote, support_range_text=support_range, core_text=core_text, inst=inst),
            "操作意思": "這是條件成熟度，不是保證勝率；用來比較現價、回檔與突破情境。",
        },
        {
            "問題": "是否有吃貨",
            "判斷": eat_simple,
            "操作意思": eat_note,
        },
    ]
    # v271.8｜小白決策表統一讀 final_verdict_payload，不再自己用舊 Core 判斷。
    try:
        payload = a.get("final_verdict_payload") if isinstance(a, dict) else {}
        if isinstance(payload, dict) and payload.get("structural_applied"):
            valp = payload.get("valuation") or {}
            core_line = "｜".join([x for x in [
                f"Core {payload.get('core') or '—'}",
                payload.get("treasury"),
                payload.get("report_type") or payload.get("report"),
            ] if str(x or "").strip()])
            core_note = "公司可收編，不代表現價一定可買；仍以買點、風報比與防守點決定動作。" if payload.get("core") == "Yes" else "先觀察，等財報、營收或籌碼證據更完整。"
            rows[0]["判斷"] = core_line or rows[0]["判斷"]
            rows[0]["操作意思"] = core_note
            if valp.get("support_zone"):
                rows[3]["判斷"] = f"支撐區：{valp.get('support_zone')}\n{valp.get('price_relation') or ''}".strip()
                rows[3]["操作意思"] = "法醫結構支撐區是估值地形，不等於現價一定能買。"
            if valp.get("rerating_zone"):
                rows[4]["判斷"] = f"重評合理區：{valp.get('rerating_zone')}"
                rows[4]["操作意思"] = "波段目標需靠營收、毛利率、EPS 與法人籌碼接棒。"
            dyn = payload.get("dynamic_defense") or {}
            if dyn.get("buy_main") or dyn.get("support_text"):
                rows[5]["判斷"] = "\n".join([x for x in [
                    f"今日買點：{dyn.get('buy_main')}" if dyn.get("buy_main") else "",
                    f"APP防線：{dyn.get('support_text')}" if dyn.get("support_text") else "",
                    "法醫快照僅供參考",
                ] if x])
                rows[5]["操作意思"] = "今日防線由 APP 動態重算；交易快照不可當永久防線。"
            rows[6]["判斷"] = payload.get("recommended_action") or rows[6]["判斷"]
            rows[6]["操作意思"] = payload.get("recommended_reason") or rows[6]["操作意思"]
    except Exception:
        pass
    return rows


def nick_v220_beginner_mobile_title(question):
    """手機版小白表短標題：縮短標題，但不刪減判斷內容。"""
    q = str(question or "")
    mapping = {
        "公司體質 / 財報等級": "Core / 金庫",
        "下個月是否更進步": "下月",
        "下季是否更進步": "下季",
        "基本面支撐股價": "基本面支撐",
        "基本面支撐": "基本面支撐",
        "波段目標價": "支撐 / 目標",
        "左側 / 右側買點": "買點",
        "AI判斷買進意願": "AI買進意願",
        "是否有吃貨": "籌碼 / 吃貨",
    }
    return mapping.get(q, q)


def nick_v220_html_lines(text):
    """手機卡片：保留區間與完整數字，只把分隔符改成換行。"""
    s = _html.escape(str(text or "—"))
    # 支撐 / 目標若有區間，完整保留；只做可讀換行，不把區間改成單點。
    for sep in ["｜", "；", ";"]:
        s = s.replace(sep, '<span class="line"></span>')
    return s


def render_beginner_decision_table_v216(rows):
    if not rows:
        st.info("小白決策表資料不足，暫不顯示。")
        return
    cols = ["問題", "判斷", "操作意思"]
    html_rows = []
    for r in rows:
        cells = []
        for c in cols:
            val = _html.escape(str(r.get(c, "—"))).replace("｜", "<br>")
            cls = ' class="num"' if c == "判斷" else ""
            cells.append(f"<td{cls}>{val}</td>")
        html_rows.append("<tr>" + "".join(cells) + "</tr>")
    header = "".join([f"<th>{_html.escape(c)}</th>" for c in cols])

    mobile_cards = []
    for r in rows:
        title = nick_v220_beginner_mobile_title(r.get("問題", ""))
        value = nick_v220_html_lines(r.get("判斷", "—"))
        note = nick_v220_html_lines(r.get("操作意思", ""))
        mobile_cards.append(
            '<div class="beginner-card">'
            f'<div class="beginner-card-title">{_html.escape(title)}</div>'
            f'<div class="beginner-card-value">{value}</div>'
            f'<div class="beginner-card-note">{note}</div>'
            '</div>'
        )

    st.markdown("### Nick 小白決策表｜買前 8 問")
    st.caption("這裡只顯示裁決、原因、動作與改判條件。")
    try:
        _core_row_text = " ".join([str(rows[0].get("判斷", "")), str(rows[0].get("操作意思", ""))]) if rows else ""
        if any(_k in _core_row_text for _k in ["暫不收編", "不收編", "先等證據", "公司體質未通過"]):
            _brain_title = "目前不符合進場條件"
            _brain_note = "下方買點只作回檔後參考；未看到財報、營收或籌碼接棒前，不把小倉觀察解讀成正式買進。"
        elif any(_k in _core_row_text for _k in ["公司可收編", "Core Yes", "金庫級"]):
            _brain_title = "公司可收編，但仍要看買點"
            _brain_note = "Core 代表公司可追蹤，不代表現價一定可買；仍以買點、風報比與防守點決定動作。"
        else:
            _brain_title = "先看能不能動手"
            _brain_note = "小白表先顯示最後裁決，再把支撐、買點與風險拆開看。"
        st.markdown(f'<div class="brain-verdict-card"><div class="brain-verdict-title">{_html.escape(_brain_title)}</div><div class="brain-verdict-note">{_html.escape(_brain_note)}</div></div>', unsafe_allow_html=True)
    except Exception:
        pass
    st.markdown(
        '<div class="compact-table-wrap"><table class="compact-table">'
        f"<thead><tr>{header}</tr></thead><tbody>"
        + "".join(html_rows)
        + "</tbody></table></div>"
        + '<div class="beginner-mobile-cards">'
        + "".join(mobile_cards)
        + "</div>",
        unsafe_allow_html=True,
    )


