# =========================
# 批量優先觀察雷達
# =========================
def parse_batch_stock_codes(text):
    codes = re.findall(r"(?<!\d)\d{4}(?!\d)", str(text or ""))
    seen = set()
    out = []
    for c in codes:
        if c not in seen:
            seen.add(c)
            out.append(c)
    return out


def _best_buy_score(buy_rows):
    scores = []
    for r in buy_rows or []:
        v = r.get("品質分數")
        try:
            scores.append(float(v))
        except Exception:
            pass
    return int(max(scores)) if scores else None


def _scan_rank_score(a, buy_score, pullback_status, data_quality, strategy="Focus優先觀察"):
    score = 0
    if a.get("focus") == "Yes":
        score += 80
    elif a.get("core") == "Yes" and a.get("attack") == "Yes":
        score += 65
    elif a.get("attack") == "Yes":
        score += 52
    elif a.get("core") == "Yes":
        score += 45
    else:
        score += 25

    if buy_score is not None:
        score += min(max(buy_score - 50, 0), 35) * 0.45

    if pullback_status == "健康回檔":
        score += 6
    elif pullback_status == "轉弱回檔":
        score -= 8

    _d = a.get("_diag", {}) or {}
    _atype = str(a.get("attack_type", ""))

    # Nick CAF 策略加權：同一批標的會依不同用途重新排序。
    if strategy == "主攻成長股":
        if a.get("core") == "Yes":
            score += 8
        if a.get("focus") == "Yes":
            score += 6
        if _d.get("financial_quality") == "高":
            score += 5
        if _d.get("growth_quality") in ["通過", "部分通過"]:
            score += 5
    elif strategy in ["回檔型強股", "回檔強股"]:
        if "回檔型" in _atype:
            score += 10
        if pullback_status == "健康回檔":
            score += 8
        if _d.get("atk_near_support"):
            score += 5
        if pullback_status == "轉弱回檔":
            score -= 12
    elif strategy in ["突破準備", "下一波主題"]:
        if "突破型" in _atype:
            score += 10
        if _d.get("atk_near_breakout"):
            score += 7
        if _d.get("atk_breakout_attack"):
            score += 5
    elif strategy == "財報打臉市場":
        if _d.get("financial_quality") in ["高", "中"]:
            score += 6
        if _d.get("growth_quality") in ["通過", "部分通過"]:
            score += 6
        try:
            if float(_d.get("rev_score", 0)) >= 2:
                score += 5
        except Exception:
            pass
        if a.get("core") == "Yes" and a.get("focus") != "Yes":
            score += 3
    elif strategy == "低基期轉機":
        try:
            if float(_d.get("rev_score", 0)) >= 2:
                score += 7
        except Exception:
            pass
        if _d.get("growth_quality") in ["通過", "部分通過"]:
            score += 5
        if a.get("attack") == "Yes":
            score += 4
    elif strategy == "防守現金流":
        if _d.get("financial_quality") == "高":
            score += 8
        if _d.get("cashflow") in ["有", "普通"]:
            score += 8
        if _d.get("debt") == "明顯":
            score -= 8
        if a.get("attack") == "Yes" and a.get("core") != "Yes":
            score -= 4

    elif strategy == "偷偷流入":
        # 偷偷流入不是追已噴，而是找量能 / 營收 / 攻擊條件剛升溫但還沒完全明牌。
        if a.get("attack") == "Yes":
            score += 8
        if _d.get("atk_near_support"):
            score += 5
        if _d.get("atk_near_breakout"):
            score += 5
        try:
            if float(_d.get("rev_score", 0)) >= 1:
                score += 4
        except Exception:
            pass
        if pullback_status == "轉弱回檔":
            score -= 8

    if data_quality.get("grade") == "低":
        score -= 5
    return round(clamp(score, 0, 100), 1)


def _caf_leg_scores(a, buy_score, pullback_status, data_quality=None, pool_label=""):
    """v184｜CAF = Core + Attack + 主攻成立度。

    這裡不是買進保證，而是批量初篩：三者接近 80 代表優先丟進單檔法醫。
    """
    data_quality = data_quality or {}
    _d = a.get("_diag", {}) or {}
    core_v = str(a.get("core", "No") or "No")
    attack_v = str(a.get("attack", "No") or "No")
    focus_v = str(a.get("focus", "No") or "No")
    core_status = str(a.get("core_status", "") or "")
    attack_type = str(a.get("attack_type", "") or "")
    try:
        focus_state, _ = display_focus_state(a)
    except Exception:
        focus_state = str(a.get("focus_display", focus_v) or focus_v)

    # Core：基本面 / 財報 / 成長 / 估值重評支撐
    if core_v == "Yes":
        core_score = 88
    elif "候選" in core_status:
        core_score = 80
    else:
        core_score = 55
        if _d.get("financial_quality") == "高":
            core_score += 10
        elif _d.get("financial_quality") == "中":
            core_score += 5
        if _d.get("growth_quality") == "通過":
            core_score += 10
        elif _d.get("growth_quality") == "部分通過":
            core_score += 6
        if str((a.get("rerating") or {}).get("verdict", "")) in ["成立", "部分成立"]:
            core_score += 6

    # Attack：未來 3～7 天攻擊條件 / 買點 / 回檔品質
    if attack_v == "Yes":
        attack_score = 88
    else:
        attack_score = 55
        if "回檔型" in attack_type or "突破型" in attack_type:
            attack_score += 10
        if pullback_status == "健康回檔":
            attack_score += 12
        elif pullback_status == "普通回檔":
            attack_score += 7
        try:
            if buy_score is not None and float(buy_score) >= 75:
                attack_score += 12
            elif buy_score is not None and float(buy_score) >= 65:
                attack_score += 8
        except Exception:
            pass
        if _d.get("atk_near_support") or _d.get("atk_near_breakout"):
            attack_score += 7

    # Focus：市場資金是否在看。CAF 資金流入掃描來源本身給 Focus 觀察底分。
    if focus_v == "Yes":
        focus_score = 88
    else:
        focus_score = 58
        if any(k in focus_state for k in ["觀察", "候選", "接近", "升溫"]):
            focus_score += 12
        if "CAF" in str(pool_label) or "資金流入" in str(pool_label):
            focus_score = max(focus_score, 80)
        if a.get("attack") == "Yes":
            focus_score += 4
        try:
            if float(_d.get("rev_score", 0)) >= 2:
                focus_score += 4
        except Exception:
            pass

    if data_quality.get("grade") == "低":
        core_score -= 5
        attack_score -= 3
        focus_score -= 3

    core_score = int(clamp(round(core_score), 0, 100))
    attack_score = int(clamp(round(attack_score), 0, 100))
    focus_score = int(clamp(round(focus_score), 0, 100))
    caf_score = int(round((core_score + attack_score + focus_score) / 3))

    if core_score >= 80 and attack_score >= 80 and focus_score >= 80:
        verdict = "CAF三項高成立"
    elif core_score >= 80 and focus_score >= 80:
        verdict = "Core+Focus成立，等Attack"
    elif attack_score >= 80 and focus_score >= 80:
        verdict = "Attack+Focus成立，Core待確認"
    elif core_score >= 80 and attack_score >= 80:
        verdict = "Core+Attack成立，Focus待確認"
    else:
        verdict = "CAF條件未齊"

    return {
        "Core成立度": core_score,
        "Attack成立度": attack_score,
        "Focus成立度": focus_score,
        "CAF成立度": caf_score,
        "CAF判讀": verdict,
    }


def _scan_category(a, buy_score, pullback_status, caf_scores=None):
    caf_scores = caf_scores or {}
    c = to_float(caf_scores.get("Core成立度")) or 0
    atk = to_float(caf_scores.get("Attack成立度")) or 0
    f = to_float(caf_scores.get("Focus成立度")) or 0
    if c >= 80 and atk >= 80 and f >= 80:
        return "CAF三項高成立｜優先分析"
    if c >= 80 and f >= 80 and atk >= 70:
        return "Core+Focus成立｜等Attack"
    if atk >= 80 and f >= 80 and c < 80:
        return "Attack+Focus｜短線觀察"
    if c >= 80 and atk >= 80 and f < 80:
        return "Core+Attack｜等市場確認"
    if a.get("focus") == "Yes":
        return "Focus｜優先觀察"
    if a.get("core") == "Yes" and a.get("attack") == "Yes":
        return "Focus候選｜等買點"
    if a.get("core") == "Yes":
        return "Core｜等回檔"
    if a.get("attack") == "Yes":
        return "Attack｜短線觀察"
    if pullback_status in ["健康回檔", "普通回檔"] and buy_score not in [None, "—"] and to_float(buy_score) and to_float(buy_score) >= 65:
        return "觀察｜買點接近"
    return "排除 / 等條件"


def scan_one_focus_candidate(stock_code, stock_info_df, strategy="Focus優先觀察", pool_label="自訂"):
    meta, resolve_msg = resolve_stock_inputs(stock_code, "", stock_info_df)
    if not meta:
        return {"排序分": 0, "股票": stock_code, "目前動作": "無法辨識", "優先觀察": "—", "攻擊機會": "—", "買點分": "—", "回檔品質": "—", "買進勝率": "—", "卡關原因": resolve_msg}

    stock = meta["stock_id"]
    name = meta.get("stock_name") or stock
    industry_category = meta.get("industry_category", "")
    tasks = [
        ("股價", fetch_price),
        ("月營收", fetch_revenue),
        ("法人", fetch_inst),
        ("財報", fetch_financial),
        ("資產負債表", fetch_balance),
        ("現金流量表", fetch_cashflow),
    ]
    results, errors = {}, {}
    for label, fn in tasks:
        val, err = fetch_with_timeout(fn, stock)
        results[label] = val
        errors[label] = err

    price = results["股價"]
    rev = results["月營收"]
    inst = results["法人"]
    fin = results["財報"]
    bal = results["資產負債表"]
    cf = results["現金流量表"]

    try:
        if isinstance(price, dict):
            _pre_volume_k_lines = detect_volume_k_sr_lines(price.get("raw") if price else None, lookback=120, max_lines=4)
            _pre_sr = build_support_resistance_levels(price, {}, volume_k_lines=_pre_volume_k_lines, reference_price=price.get("close"))
            if _pre_sr.get("main_support") is not None:
                price["recent_support"] = to_float(_pre_sr.get("main_support"))
            if _pre_sr.get("main_pressure") is not None:
                price["recent_resistance"] = to_float(_pre_sr.get("main_pressure"))
    except Exception:
        pass
    a = decide_all(stock, price, rev, inst, fin, bal, cf, industry_category=industry_category)
    current_zone = valuation_zone_name(price.get("close") if price else None, a.get("val", {}))
    dq = evaluate_data_quality(None, price, rev, inst, fin, bal, cf)
    buy_rows = build_buy_point_quality(price, a)
    buy_score = _best_buy_score(buy_rows)
    pullback = judge_pullback_quality(price, a, inst)
    # v276.5｜法人逆勢承接：同時餵給跌深錯殺與 CAF 跨策略標籤。
    absorption = build_institutional_absorption_signal_v2765(
        price=price,
        inst=inst,
        rev=rev,
        fin=fin,
        flow_status=str(pool_label or ""),
        core_hint=str(a.get("core_status") or a.get("core") or ""),
    )
    # v277｜發動前鎖碼分：CAF 排序輔助，不覆蓋 Core / Attack / Focus。
    pre_lock = build_pre_breakout_lock_signal_v277(
        price=price,
        inst=inst,
        rev=rev,
        fin=fin,
        flow_status=str(pool_label or ""),
        core_hint=str(a.get("core_status") or a.get("core") or ""),
    )
    focus_state, _ = display_focus_state(a)
    # v191｜批量 CAF 掃描也傳入 price / a，讓回檔型可以計算距離買點，不再出現「距離買點約 —」。
    attack_text = display_attack_type(a.get("attack_type"), price=price, a=a)
    block = "、".join((a.get("focus_block_reasons") or [])[:3]) or "無明顯卡關"
    rank = _scan_rank_score(a, buy_score, pullback.get("status"), dq, strategy=strategy)
    caf_scores = _caf_leg_scores(a, buy_score, pullback.get("status"), dq, pool_label=pool_label)
    # CAF 三項越接近 80，排序越前；仍保留原本法醫排序邏輯。
    try:
        rank = round(clamp(rank + max(0, (to_float(caf_scores.get("CAF成立度")) or 0) - 75) * 0.35, 0, 100), 1)
    except Exception:
        pass
    # v276.5｜法人承接只加權/警示，不覆蓋 CAF 主裁決。
    try:
        rank = round(clamp(rank + float(absorption.get("score_adjust") or 0), 0, 100), 1)
    except Exception:
        pass
    # v277｜發動前鎖碼分只加權排序，不代表勝率。
    try:
        rank = round(clamp(rank + float(pre_lock.get("score_adjust") or 0), 0, 100), 1)
    except Exception:
        pass
    if pre_lock.get("is_risk"):
        try:
            block = (block + "、" if block else "") + "發動前鎖碼失敗/追高風險"
        except Exception:
            pass
    if absorption.get("is_risk"):
        try:
            block = (block + "、" if block else "") + "法人接刀風險"
        except Exception:
            pass

    category = _scan_category(a, buy_score, pullback.get("status"), caf_scores=caf_scores)
    try:
        if any(k in str(absorption.get("dip_verdict") or "") for k in ["真錯殺", "跌深反彈觀察", "非真錯殺"]):
            category = absorption.get("dip_verdict")
        elif absorption.get("state") == "承接成立" and category in ["觀察｜買點接近", "Core｜等回檔", "Attack｜短線觀察"]:
            category = "承接加分｜" + category
    except Exception:
        pass
    return {
        "排序分": rank,
        "分類": category,
        "CAF成立度": caf_scores.get("CAF成立度", "—"),
        "Core成立度": caf_scores.get("Core成立度", "—"),
        "Attack成立度": caf_scores.get("Attack成立度", "—"),
        "Focus成立度": caf_scores.get("Focus成立度", "—"),
        "CAF判讀": caf_scores.get("CAF判讀", "—"),
        "法人承接狀態": absorption.get("label", "—"),
        "法人承接說明": absorption.get("note", "—"),
        "法人承接證據": "；".join(absorption.get("evidence") or []),
        "承接加分標籤": "｜".join(absorption.get("strategy_tags") or []),
        "承接前台摘要": absorption.get("front_summary", "—"),
        "承接操作口令": absorption.get("action_hint", "—"),
        "錯殺驗證": absorption.get("dip_verdict", "—"),
        "發動前鎖碼": pre_lock.get("label", "—"),
        "鎖碼分": pre_lock.get("score", "—"),
        "鎖碼狀態": pre_lock.get("state", "—"),
        "鎖碼說明": pre_lock.get("note", "—"),
        "鎖碼證據": pre_lock.get("evidence_text", "—"),
        "鎖碼警示": pre_lock.get("warnings_text", ""),
        "鎖碼缺資料": pre_lock.get("missing_text", ""),
        "鎖碼口令": pre_lock.get("action_hint", "—"),
        "鎖碼加分標籤": "｜".join(pre_lock.get("strategy_tags") or []),
        "20日漲跌": absorption.get("ret20", price.get("ret20") if isinstance(price, dict) else None),
        "20日回撤": absorption.get("drawdown20", price.get("drawdown20") if isinstance(price, dict) else None),
        "股票": f"{name} {stock}",
        "策略": strategy,
        "股票池": pool_label,
        "目前動作": action_as_trader_sentence(a),
        "優先觀察": "Yes" if a.get("focus") == "Yes" else focus_state,
        "攻擊機會": attack_text,
        "買點分": buy_score if buy_score is not None else "—",
        "回檔品質": pullback.get("status", "—"),
        "買進勝率": a.get("win_rate", "—"),
        "估值位置": current_zone,
        "卡關原因": block,
    }



def _caf_color_by_category(category: str) -> str:
    txt = str(category or "")
    if "CAF三項高成立" in txt:
        return "#22c55e"
    if "Core+Focus" in txt or "Core+Attack" in txt:
        return "#60a5fa"
    if "Attack+Focus" in txt:
        return "#f59e0b"
    if "排除" in txt or "失敗" in txt:
        return "#ef4444"
    return "#94a3b8"





def _caf_cache_key(strategy: str) -> str:
    return str(strategy or "default").strip() or "default"


def _json_safe_value(v):
    """把 DataFrame / numpy / NaN 轉成 json 可寫入格式。"""
    try:
        if pd.isna(v):
            return ""
    except Exception:
        pass
    try:
        if hasattr(v, "item"):
            v = v.item()
    except Exception:
        pass
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    try:
        return str(v)
    except Exception:
        return ""


def _df_to_cache_records(df: pd.DataFrame):
    if df is None or df.empty:
        return []
    out = []
    for r in df.to_dict("records"):
        out.append({str(k): _json_safe_value(v) for k, v in (r or {}).items()})
    return out


def load_caf_scan_cache(strategy: str = None):
    data = _read_json_file(NICK_CAF_SCAN_CACHE_PATH, {})
    if not isinstance(data, dict):
        data = {}
    if strategy is None:
        return data
    return data.get(_caf_cache_key(strategy), {}) or {}


def save_caf_scan_cache(
    strategy: str,
    pool_label: str,
    df_all: pd.DataFrame,
    df_filtered: pd.DataFrame,
    df_watch: pd.DataFrame = None,
    meta: dict = None,
):
    data = load_caf_scan_cache()
    key = _caf_cache_key(strategy)
    meta = meta or {}
    data[key] = {
        "strategy": str(strategy or ""),
        "pool_label": str(pool_label or ""),
        "updated_at": _now_str(),
        "flow_updated_at": str(meta.get("flow_updated_at", "")),
        "robot_pool_updated_at": str(meta.get("robot_pool_updated_at", "")),
        "source_codes": [str(x) for x in (meta.get("source_codes") or [])],
        "all_source_codes": [str(x) for x in (meta.get("all_source_codes") or meta.get("source_codes") or [])],
        "candidate_total": int(meta.get("candidate_total") or len(meta.get("all_source_codes") or meta.get("source_codes") or [])),
        "scan_batch_size": int(meta.get("scan_batch_size") or 0),
        "scan_batch_offset": int(meta.get("scan_batch_offset") or 0),
        "scan_batch_start": int(meta.get("scan_batch_start") or 0),
        "scan_batch_end": int(meta.get("scan_batch_end") or 0),
        "scan_batch_remaining": int(meta.get("scan_batch_remaining") or 0),
        "scan_next_batch_offset": int(meta.get("scan_next_batch_offset") or meta.get("scan_batch_end") or 0),
        "raw_count": int(len(df_all) if df_all is not None else 0),
        "filtered_count": int(len(df_filtered) if df_filtered is not None else 0),
        "watch_count": int(len(df_watch) if df_watch is not None else 0),
        "filter_rule": "嚴選區：排序分≥70＋買點分≥70＋Core/Attack/Focus三項成立度≥80＋CAF判讀=CAF三項高成立；觀察區：排序分≥65＋買點分≥60＋CAF≥75＋三項至少兩項≥80",
        "all_records": _df_to_cache_records(df_all),
        "filtered_records": _df_to_cache_records(df_filtered),
        "watch_records": _df_to_cache_records(df_watch),
    }
    _write_json_file(NICK_CAF_SCAN_CACHE_PATH, data)
    return data[key]


def clear_caf_scan_cache(strategy: str):
    data = load_caf_scan_cache()
    key = _caf_cache_key(strategy)
    if key in data:
        data.pop(key, None)
        _write_json_file(NICK_CAF_SCAN_CACHE_PATH, data)
    return True


def _caf_cache_status_text(cache: dict) -> str:
    if not cache:
        return "尚無快取"
    updated = str(cache.get("updated_at") or "未知時間")
    raw_n = cache.get("raw_count", 0)
    filtered_n = cache.get("filtered_count", 0)
    watch_n = cache.get("watch_count", 0)
    candidate_total = int(to_float(cache.get("candidate_total")) or 0)
    batch_end = int(to_float(cache.get("scan_batch_end")) or raw_n or 0)
    remaining = int(to_float(cache.get("scan_batch_remaining")) or 0)
    try:
        date_txt = updated[:10]
        today_txt = datetime.now().strftime("%Y-%m-%d")
        freshness = "今日快取" if date_txt == today_txt else "非今日快取，建議重新掃描"
    except Exception:
        freshness = "快取"
    if candidate_total:
        return f"{freshness}｜{updated}｜候選 {candidate_total} 檔｜已掃 {batch_end} 檔｜尚未 {remaining} 檔｜原始 {raw_n} 檔｜嚴選 {filtered_n} 檔｜觀察 {watch_n} 檔"
    return f"{freshness}｜{updated}｜原始 {raw_n} 檔｜嚴選 {filtered_n} 檔｜觀察 {watch_n} 檔"


def render_cached_caf_scan(strategy: str, cache: dict):
    """顯示某策略最近一次 CAF 掃描快取。"""
    if not cache:
        st.warning("目前沒有上次選股雷達結果，請先重新掃描一次。")
        return
    st.markdown("### 🧭 上次選股雷達結果")
    st.caption(f"{_caf_cache_status_text(cache)}")
    _candidate_total = int(to_float(cache.get("candidate_total")) or 0)
    _batch_start = int(to_float(cache.get("scan_batch_start")) or 0)
    _batch_end = int(to_float(cache.get("scan_batch_end")) or 0)
    _remaining = int(to_float(cache.get("scan_batch_remaining")) or 0)
    if _candidate_total:
        st.info(f"候選標的 {_candidate_total} 檔｜目前已檢查到第 {_batch_end} 檔｜尚未檢查 {_remaining} 檔。若還有剩餘，可回雷達區按『掃描下一批』。")
    st.caption("嚴選區負責找可進法醫的標的；觀察區負責追蹤還沒成熟但值得盯的早期機會。")

    df_filtered = pd.DataFrame(cache.get("filtered_records") or [])
    df_watch = pd.DataFrame(cache.get("watch_records") or [])
    df_all = pd.DataFrame(cache.get("all_records") or [])

    if not df_filtered.empty and "策略型態" not in df_filtered.columns:
        df_filtered = apply_caf_strategy_tags(df_filtered, strategy=cache.get("strategy") or strategy)
    if not df_watch.empty and "策略型態" not in df_watch.columns:
        df_watch = apply_caf_strategy_tags(df_watch, strategy=cache.get("strategy") or strategy)
    if not df_all.empty and "策略型態" not in df_all.columns:
        df_all = apply_caf_strategy_tags(df_all, strategy=cache.get("strategy") or strategy)

    if df_filtered.empty and df_watch.empty:
        st.warning("上次掃描沒有符合嚴選區或觀察區條件的標的。")
        with st.expander("查看上次原始掃描結果（未過濾）", expanded=False):
            render_caf_scan_result_cards(df_all, max_cards=12, section_title="完整掃描結果", section_caption="這是完整候選結果，只供檢查，不代表可買。")
        return

    if not df_filtered.empty:
        render_caf_scan_result_cards(
            df_filtered,
            max_cards=12,
            section_title="嚴選區｜可進法醫",
            section_caption="條件最完整：整體分數、買點、核心條件與動能都較接近。這區才是優先進一步分析名單。",
        )
        _top = df_filtered.head(3)
        if not _top.empty:
            save_last_radar_candidates(_top, strategy=cache.get("strategy") or strategy, pool_label=cache.get("pool_label", "CAF快取"))
    else:
        st.info("本次嚴選區沒有標的；可先看下方觀察候選。")

    if not df_watch.empty:
        render_caf_scan_result_cards(
            df_watch,
            max_cards=12,
            section_title="觀察區｜還沒成熟但值得追蹤",
            section_caption="條件還沒完全成熟。這區不是買進名單，而是追蹤名單。",
        )
        if df_filtered.empty:
            _top_watch = df_watch.head(3)
            if not _top_watch.empty:
                save_last_radar_candidates(_top_watch, strategy=cache.get("strategy") or strategy, pool_label=(cache.get("pool_label", "CAF快取") + "｜觀察區"))




def _caf_source_lookup(strategy: str = None) -> dict:
    """讀取 CAF 掃描池內每檔股票對應的今日資金流向族群/狀態。"""
    dyn = load_dynamic_robot_pool(strategy or NICK_CAF_AUTO_STRATEGY)
    lookup = {}
    for item in (dyn.get("candidate_detail") or []):
        code = str(item.get("code") or item.get("代號") or "").strip()
        if not code:
            continue
        lookup[code] = {
            "族群": str(item.get("族群") or ""),
            "資金狀態": str(item.get("狀態") or ""),
            "今日漲跌": item.get("今日漲跌", ""),
            "成交金額": item.get("成交金額", ""),
        }
    return lookup


def _num_or_zero(v):
    try:
        return float(v)
    except Exception:
        return 0.0


def infer_caf_strategy_tags(row: dict, source_info: dict = None):
    """v190｜掃描後自動標註策略型態。

    不是先選策略，而是用結果反推這檔比較像哪一種操作劇本。
    一檔可同時有多個標籤。
    """
    source_info = source_info or {}
    status = str(source_info.get("資金狀態") or row.get("資金狀態") or "")
    sector = str(source_info.get("族群") or row.get("族群") or "")
    category = str(row.get("分類") or "")
    verdict = str(row.get("CAF判讀") or "")
    pullback = str(row.get("回檔品質") or "")
    action = str(row.get("目前動作") or "")
    block = str(row.get("卡關原因") or "")

    core_s = _num_or_zero(row.get("Core成立度"))
    atk_s = _num_or_zero(row.get("Attack成立度"))
    focus_s = _num_or_zero(row.get("Focus成立度"))
    buy_s = _num_or_zero(row.get("買點分"))
    caf_s = _num_or_zero(row.get("CAF成立度"))
    absorption_state = str(row.get("法人承接狀態") or "")
    absorption_note = str(row.get("法人承接說明") or "")
    absorption_badges = str(row.get("承接加分標籤") or row.get("承接前台摘要") or "")
    dip_verdict = str(row.get("錯殺驗證") or "")
    lock_label = str(row.get("發動前鎖碼") or "")
    lock_state = str(row.get("鎖碼狀態") or "")
    lock_badges = str(row.get("鎖碼加分標籤") or "")
    lock_score = _num_or_zero(row.get("鎖碼分"))
    ret20_v = _num_or_zero(row.get("20日漲跌"))

    tags = []
    reasons = []

    # 1. 主攻成長股：Core 必須強
    if core_s >= 80 and ("CAF三項高成立" in verdict or caf_s >= 80):
        tags.append("主攻成長股")
        reasons.append("Core強，基本面可優先法醫確認")

    # 2. 回檔強股：回檔品質必須成立
    if pullback in ["健康回檔", "普通回檔"] and atk_s >= 80 and buy_s >= 70:
        tags.append("回檔強股")
        reasons.append(f"{pullback}，Attack與買點接近")
        if "承接成立" in absorption_state or "法人逆勢承接" in absorption_state:
            reasons.append("主力回檔防守，回檔品質加分")
        if "主力回檔防守" in absorption_badges:
            reasons.append("主力回檔防守")

    # 3. 低基期轉機：低基期 / 營收改善必須成立
    if status == "低基期轉強" or "低基期" in category or "營收" in block or "轉強" in action:
        if core_s >= 75 and focus_s >= 75:
            tags.append("低基期轉機")
            reasons.append("低基期或營收改善訊號，需驗證EPS/毛利接棒")
            if "底部承接觀察" in absorption_badges:
                reasons.append("底部承接觀察")
            if "接刀風險" in absorption_state:
                reasons.append("法人出逃或破支撐，低基期不得左側硬接")

    # 4. 下一波主題：Focus升溫、族群剛冒出
    if focus_s >= 80 and status in ["偷偷流入", "低基期轉強", "回檔轉強"]:
        tags.append("下一波主題")
        if "新題材資金試單" in absorption_badges:
            reasons.append("新題材資金試單，Focus成立")
        else:
            reasons.append(f"{status or '資金升溫'}，Focus成立")

    # 5. 偷偷流入：不能明面主流，必須資金低調轉強
    if status == "偷偷流入" and focus_s >= 80 and buy_s >= 70:
        tags.append("偷偷流入")
        if "法人低調回補" in absorption_badges:
            reasons.append("法人低調回補，資金開始卡位")
        else:
            reasons.append("非明面主流，資金低調回補")

    # 6. 發動前鎖碼：只作現有策略的臨門一腳，不取代主策略。
    if "發動前鎖碼成立" in lock_label or "發動前鎖碼" in lock_badges or lock_score >= 80:
        if "偷偷" in status or "偷偷" in lock_badges:
            tags.append("偷偷流入")
            reasons.append("發動前鎖碼分高，偷偷流入有臨門一腳味道")
        elif "回檔" in status or "回檔" in lock_badges or pullback in ["健康回檔", "普通回檔"]:
            tags.append("回檔強股")
            reasons.append("回檔後有發動前鎖碼跡象")
        elif "低基期" in status or "轉機" in lock_badges:
            tags.append("低基期轉機")
            reasons.append("轉機股出現點火前鎖碼確認")
        else:
            tags.append("下一波主題")
            reasons.append("個股出現發動前鎖碼，可能是族群精篩候選")
    elif "鎖碼觀察" in lock_label or "鎖碼觀察" in lock_state:
        reasons.append("有發動前鎖碼味道，但仍需家數差/融資/量價確認")
    elif "追高" in lock_label or "失敗" in lock_label:
        reasons.append("發動前鎖碼失敗或已偏追高，不當成潛伏訊號")

    # 7. 跌深錯殺：跌深不是答案，必須通過法人承接與 Core/基本面資格。
    if ("真錯殺" in dip_verdict or (ret20_v <= -10 and core_s >= 80)) and "接刀風險" not in absorption_state and "非真錯殺" not in dip_verdict:
        tags.append("跌深錯殺")
        if "承接成立" in absorption_state or "法人逆勢承接" in absorption_state:
            reasons.append("跌深後有法人承接，錯殺驗證加分")
        elif "承接觀察" in absorption_state:
            reasons.append("跌深後賣壓縮小，列錯殺觀察")
    if "接刀風險" in absorption_state or "非真錯殺" in dip_verdict:
        reasons.append("法人續賣或破支撐，跌深不等於錯殺")

    # 若真的沒有被打到，但CAF條件很高，給一個備註避免空白。
    if not tags and core_s >= 80 and atk_s >= 80 and focus_s >= 80:
        tags.append("CAF三項高成立")
        reasons.append("CAF三項成立，但策略型態尚需單檔確認")

    # 去重保序
    seen = set()
    tags = [x for x in tags if not (x in seen or seen.add(x))]
    seen_r = set()
    reasons = [x for x in reasons if not (x in seen_r or seen_r.add(x))]

    return {
        "策略型態": "｜".join(tags) if tags else "未歸類",
        "策略標籤原因": "；".join(reasons) if reasons else "未觸發特定策略標籤",
        "族群": sector,
        "資金狀態": status,
    }


def apply_caf_strategy_tags(df_scan: pd.DataFrame, strategy: str = None):
    """替 CAF 掃描結果補上策略型態欄位。"""
    if df_scan is None or df_scan.empty:
        return df_scan
    lookup = _caf_source_lookup(strategy or NICK_CAF_AUTO_STRATEGY)
    rows = []
    for _, r in df_scan.iterrows():
        rd = dict(r)
        label = str(rd.get("股票", "") or "")
        code, _name = parse_stock_label_to_code_name(label)
        src = lookup.get(str(code), {})
        info = infer_caf_strategy_tags(rd, src)
        rd.update(info)
        rows.append(rd)
    return pd.DataFrame(rows)



def _prepare_caf_numeric_df(df_scan: pd.DataFrame) -> pd.DataFrame:
    if df_scan is None or df_scan.empty:
        return df_scan
    _df = df_scan.copy()
    for _col in ["排序分", "Core成立度", "Attack成立度", "Focus成立度", "CAF成立度", "買點分", "鎖碼分"]:
        if _col in _df.columns:
            _df[_col] = pd.to_numeric(_df[_col], errors="coerce")
    return _df


def filter_caf_scan_candidates(df_scan: pd.DataFrame, min_rank: float = 70, min_buy_score: float = 70):
    """嚴選區｜真正接近可進法醫的 CAF 標的。"""
    if df_scan is None or df_scan.empty:
        return df_scan
    _df = _prepare_caf_numeric_df(df_scan)
    _mask = (
        (_df.get("排序分", 0) >= min_rank)
        & (_df.get("Core成立度", 0) >= 80)
        & (_df.get("Attack成立度", 0) >= 80)
        & (_df.get("Focus成立度", 0) >= 80)
        & (_df.get("買點分", 0) >= min_buy_score)
    )
    if "CAF判讀" in _df.columns:
        _mask = _mask & _df["CAF判讀"].astype(str).str.contains("CAF三項高成立", na=False)
    return _df.loc[_mask].sort_values(["排序分", "CAF成立度", "買點分"], ascending=False)


def filter_caf_watch_candidates(
    df_scan: pd.DataFrame,
    strict_df: pd.DataFrame = None,
    min_rank: float = 65,
    min_caf: float = 75,
    min_buy_score: float = 60,
):
    """觀察區｜還沒成熟但值得追蹤的早期候選。

    條件：
    1. 排序分 >= 65
    2. CAF 成立度 >= 75
    3. Core / Attack / Focus 至少兩項 >= 80
    4. 買點分 >= 60
    5. 排除明顯過熱、追高、技術破壞、法人倒貨與掃描失敗
    6. 不重複嚴選區標的
    """
    if df_scan is None or df_scan.empty:
        return df_scan
    _df = _prepare_caf_numeric_df(df_scan)

    c = _df.get("Core成立度", 0)
    a = _df.get("Attack成立度", 0)
    f = _df.get("Focus成立度", 0)
    two_of_three = ((c >= 80).astype(int) + (a >= 80).astype(int) + (f >= 80).astype(int)) >= 2

    text_cols = []
    for col in ["分類", "目前動作", "卡關原因", "攻擊機會", "CAF判讀", "法人承接狀態", "錯殺驗證", "發動前鎖碼", "鎖碼狀態", "鎖碼警示"]:
        if col in _df.columns:
            text_cols.append(_df[col].astype(str))
    if text_cols:
        text_blob = text_cols[0]
        for s in text_cols[1:]:
            text_blob = text_blob + "｜" + s
    else:
        text_blob = pd.Series([""] * len(_df), index=_df.index)

    bad_pattern = "掃描失敗|排除|過熱|不追高|追高|鎖碼失敗|發動後不追|技術破壞|法人倒貨|法人接刀風險|接刀風險|非真錯殺|出清|轉空|轉弱"
    not_bad = ~text_blob.str.contains(bad_pattern, na=False)

    _mask = (
        (_df.get("排序分", 0) >= min_rank)
        & (_df.get("CAF成立度", 0) >= min_caf)
        & two_of_three
        & (_df.get("買點分", 0) >= min_buy_score)
        & not_bad
    )

    # 觀察區不要重複嚴選區
    if strict_df is not None and not strict_df.empty and "股票" in strict_df.columns and "股票" in _df.columns:
        strict_set = set(strict_df["股票"].astype(str).tolist())
        _mask = _mask & (~_df["股票"].astype(str).isin(strict_set))

    return _df.loc[_mask].sort_values(["排序分", "CAF成立度", "買點分"], ascending=False)



def _caf_absorption_line_html_v2765_2(
    absorption_label: str = "",
    absorption_note: str = "",
    absorption_evidence: str = "",
    dip_verdict: str = "",
    category: str = "",
    action: str = "",
    block: str = "",
) -> str:
    """v276.5-3｜法人承接前台減肥＋CAF 卡片語意清潔。

    原則：
    - 排除 / 等條件股不展開長篇承接說明。
    - 資料不足用灰色，不用黃色，避免小白誤認為機會。
    - 只有承接成立 / 承接觀察 / 接刀風險，才顯示較完整資訊。
    """
    def _clean(x):
        x = str(x or "").strip()
        return "" if x in ["—", "-", "None", "nan", "NaN"] else x

    label = _clean(absorption_label)
    note = _clean(absorption_note)
    evidence = _clean(absorption_evidence)
    verdict = _clean(dip_verdict)
    cat = str(category or "")
    act = str(action or "")
    blk = str(block or "")

    if not label:
        return ""

    is_excluded = any(k in cat for k in ["排除", "等條件"]) or any(k in act for k in ["先避開", "避開", "不追"])
    is_data_lack = any(k in label + verdict for k in ["資料不足", "尚未通過", "未通過"])
    is_risk = any(k in label + verdict for k in ["接刀風險", "非真錯殺"])
    is_positive = any(k in label + verdict for k in ["承接成立", "法人逆勢承接", "真錯殺候選", "驗證成功"])
    is_watch = ("承接觀察" in label + verdict) or ("錯殺觀察" in label + verdict)

    if is_risk:
        label_color = "#f87171"
        main = "🔴 接刀風險"
        verdict_short = "禁止接刀"
        note_short = note or "法人續賣 / 破支撐 / 籌碼失控，不要因為跌深就亂接。"
    elif is_positive:
        label_color = "#4ade80"
        main = "🟢 有人接"
        verdict_short = "錯殺機率提高" if "真錯殺" in verdict else "承接加分"
        note_short = note or "法人有回補或賣壓縮小，且支撐未破；可列優先待分析，但仍要看財報與買點。"
    elif is_watch:
        label_color = "#facc15"
        main = "🟡 承接觀察"
        verdict_short = "等確認"
        note_short = note or "賣壓有縮小，但還沒完全確認回補；先放觀察，不急追。"
    else:
        label_color = "#94a3b8"
        main = "⚪ 承接資料不足"
        verdict_short = "未通過"
        note_short = "法人 / 支撐證據不足，暫不認定錯殺。"

    # 資料不足不是機會訊號；非排除股不特別顯示，避免每張卡都塞「未通過」。
    if is_data_lack and not is_excluded and not is_risk:
        return ""

    # 排除股＋資料不足：只留兩行，不展開承接證據。
    if is_excluded and is_data_lack and not is_risk:
        return (
            '<b style="color:#e5e7eb;">錯殺驗證：</b>'
            '<span style="color:#94a3b8;font-weight:800;">未通過</span><br>'
            '<b style="color:#e5e7eb;">原因：</b>'
            '<span style="color:#cbd5e1;">法人 / 支撐證據不足，暫不認定錯殺。</span><br>'
        )

    html = (
        '<b style="color:#e5e7eb;">法人承接：</b>'
        f'<span style="color:{label_color};font-weight:900;">{_html.escape(main)}</span>'
        f'｜{_html.escape(verdict_short)}<br>'
        '<b style="color:#e5e7eb;">說明：</b>'
        f'{_html.escape(note_short)}<br>'
    )
    if evidence and not is_data_lack:
        html += '<b style="color:#e5e7eb;">證據：</b>' + _html.escape(evidence) + '<br>'
    return html



def _caf_pre_lock_line_html_v277(lock_label: str = "", lock_score: str = "", lock_note: str = "", lock_evidence: str = "", lock_warning: str = "", lock_missing: str = "") -> str:
    """v277｜CAF 卡片顯示發動前鎖碼分；資料不足不硬講成立。"""
    def _clean(x):
        x = str(x or "").strip()
        return "" if x in ["—", "-", "None", "nan", "NaN"] else x
    label = _clean(lock_label); score = _clean(lock_score); note = _clean(lock_note); evidence = _clean(lock_evidence); warning = _clean(lock_warning); missing = _clean(lock_missing)
    if not label:
        return ""
    combo = label + note + warning
    if any(k in combo for k in ["失敗", "追高", "發動後", "不追", "爆量", "融資暴增", "跌破"]):
        color, main, verdict = "#f87171", "🔴 鎖碼失敗/追高風險", "不追"
        note = note or "已偏發動後或籌碼不乾淨，不符合發動前潛伏。"
    elif any(k in combo for k in ["成立", "🟢"]):
        color, main, verdict = "#4ade80", "🟢 發動前鎖碼", "等確認"
        note = note or "股價還沒正式噴，籌碼與量價接近臨界點。"
    elif any(k in combo for k in ["觀察", "苗頭", "🟡", "⚪"]):
        color, main, verdict = "#facc15", "🟡 鎖碼觀察", "不急追"
        note = note or "有收貨味道，但資料或條件還沒完全共振。"
    else:
        return ""
    html = (
        '<b style="color:#e5e7eb;">發動前鎖碼：</b>'
        f'<span style="color:{color};font-weight:900;">{_html.escape(main)}</span>'
        f'｜{_html.escape(str(score) if score else "—")}｜{_html.escape(verdict)}<br>'
        '<b style="color:#e5e7eb;">鎖碼說明：</b>' + _html.escape(note) + '<br>'
    )
    if evidence:
        html += '<b style="color:#e5e7eb;">鎖碼證據：</b>' + _html.escape(evidence) + '<br>'
    if missing and not any(k in combo for k in ["失敗", "追高"]):
        html += '<b style="color:#e5e7eb;">缺資料：</b>' + _html.escape(missing) + '<br>'
    return html


def _caf_card_action_hint_v2765_3(category: str = "", action: str = "", block: str = "", absorption_label: str = "", dip_verdict: str = "") -> str:
    """v276.5-3｜CAF 卡片第一眼操作口令。"""
    cat = str(category or "").strip()
    act = str(action or "").strip()
    blk = str(block or "").strip()
    combo = f"{cat}｜{act}｜{blk}｜{absorption_label}｜{dip_verdict}"
    if any(k in combo for k in ["接刀風險", "非真錯殺", "排除", "先避開", "法人接刀風險"]):
        return "先避開，不因跌深亂接"
    if any(k in combo for k in ["法人逆勢承接", "真錯殺候選", "驗證成功", "承接成立"]):
        return "可列優先待分析，等支撐/買點確認"
    if any(k in combo for k in ["承接觀察", "錯殺觀察"]):
        return "先放觀察，等法人或支撐確認"
    if act and act not in ["—", "-", "None", "nan"]:
        return act
    if "回檔" in cat:
        return "等支撐確認，不追高"
    if "等條件" in cat:
        return "先等條件補齊"
    return "先觀察，等條件更完整"

def render_caf_scan_result_cards(df_scan: pd.DataFrame, max_cards: int = 12, section_title: str = "選股雷達結果", section_caption: str = None):
    """v185｜CAF 掃描結果手機版卡片。

    取代直接把全部欄位丟進 st.dataframe，避免手機上欄位太多、文字直排。
    """
    if df_scan is None or df_scan.empty:
        st.info("目前沒有選股雷達結果。")
        return

    st.markdown(f"### {section_title}")
    if section_caption:
        st.caption(section_caption)
    else:
        st.caption("每張卡片下方可按「🔍 分析標的」進一步查看單檔分析。完整表格放在下方收合區。")

    show_df = df_scan.head(max_cards).reset_index(drop=True)
    for i, r in show_df.iterrows():
        label = str(r.get("股票", "") or "")
        code, name = parse_stock_label_to_code_name(label)
        # v276.5-2｜避免「2492 2492」這種代號重複；有名稱就顯示「名稱 代號」，沒有名稱就只顯示代號。
        if code and name and str(name).strip() != str(code).strip():
            title = f"{name} {code}"
        elif code:
            title = code
        else:
            title = label or "未辨識股票"

        category = str(r.get("分類", "—") or "—")
        color = _caf_color_by_category(category)

        rank = r.get("排序分", "—")
        caf = r.get("CAF成立度", "—")
        core_s = r.get("Core成立度", "—")
        atk_s = r.get("Attack成立度", "—")
        focus_s = r.get("Focus成立度", "—")
        buy_s = r.get("買點分", "—")
        attack = str(r.get("攻擊機會", "—") or "—").replace("距離買點約 —", "等買點確認")
        action = str(r.get("目前動作", "—") or "—")
        block = str(r.get("卡關原因", "—") or "—")
        verdict = str(r.get("CAF判讀", "—") or "—")
        strategy_tags = str(r.get("策略型態", "—") or "—")
        tag_reason = str(r.get("策略標籤原因", "—") or "—")
        flow_sector = str(r.get("族群", "—") or "—")
        flow_status = str(r.get("資金狀態", "—") or "—")
        pullback = str(r.get("回檔品質", "—") or "—")
        zone = str(r.get("估值位置", "—") or "—")
        win = str(r.get("買進勝率", "—") or "—")
        absorption_label = str(r.get("法人承接狀態", "—") or "—")
        absorption_note = str(r.get("法人承接說明", "—") or "—")
        absorption_evidence = str(r.get("法人承接證據", "—") or "—")
        absorption_badge = str(r.get("承接加分標籤", "") or "")
        dip_verdict = str(r.get("錯殺驗證", "—") or "—")
        pre_lock_label = str(r.get("發動前鎖碼", "") or "")
        pre_lock_score = str(r.get("鎖碼分", "") or "")
        pre_lock_note = str(r.get("鎖碼說明", "") or "")
        pre_lock_evidence = str(r.get("鎖碼證據", "") or "")
        pre_lock_warning = str(r.get("鎖碼警示", "") or "")
        pre_lock_missing = str(r.get("鎖碼缺資料", "") or "")
        pre_lock_action_hint = str(r.get("鎖碼口令", "") or "")
        pre_lock_badge = str(r.get("鎖碼加分標籤", "") or "")
        absorption_html = _caf_absorption_line_html_v2765_2(
            absorption_label=absorption_label,
            absorption_note=absorption_note,
            absorption_evidence=absorption_evidence,
            dip_verdict=dip_verdict,
            category=category,
            action=action,
            block=block,
        )
        action_hint = _caf_card_action_hint_v2765_3(
            category=category,
            action=action,
            block=block,
            absorption_label=absorption_label,
            dip_verdict=dip_verdict,
        )
        pre_lock_html = _caf_pre_lock_line_html_v277(
            pre_lock_label, pre_lock_score, pre_lock_note, pre_lock_evidence, pre_lock_warning, pre_lock_missing
        )
        if pre_lock_action_hint and pre_lock_action_hint not in ["—", "-", "None", "nan"] and "接刀風險" not in absorption_label and "非真錯殺" not in dip_verdict:
            action_hint = pre_lock_action_hint

        st.markdown(
            f"""
<div style="
    border:1px solid rgba(148,163,184,.22);
    border-left:5px solid {color};
    border-radius:16px;
    padding:13px 13px 11px 13px;
    margin:10px 0 12px 0;
    background:rgba(15,23,42,.48);
    box-shadow:0 8px 24px rgba(0,0,0,.16);
">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;">
    <div>
      <div style="font-size:1.08rem;font-weight:900;color:#f8fafc;line-height:1.25;">#{i+1}　{_html.escape(title)}</div>
      <div style="font-size:.86rem;color:{color};font-weight:800;margin-top:4px;">{_html.escape(category)}</div>
    </div>
    <div style="text-align:right;min-width:58px;">
      <div style="font-size:.72rem;color:#94a3b8;font-weight:700;">排序</div>
      <div style="font-size:1.12rem;color:#f8fafc;font-weight:900;">{_html.escape(str(rank))}</div>
    </div>
  </div>

  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px;">
    <div style="border:1px solid rgba(148,163,184,.18);border-radius:12px;padding:8px 4px;text-align:center;background:rgba(2,6,23,.28);">
      <div style="font-size:.68rem;color:#94a3b8;font-weight:800;">整體</div>
      <div style="font-size:1rem;color:#f8fafc;font-weight:900;">{_html.escape(str(caf))}</div>
    </div>
    <div style="border:1px solid rgba(148,163,184,.18);border-radius:12px;padding:8px 4px;text-align:center;background:rgba(2,6,23,.28);">
      <div style="font-size:.68rem;color:#94a3b8;font-weight:800;">核心</div>
      <div style="font-size:1rem;color:#f8fafc;font-weight:900;">{_html.escape(str(core_s))}</div>
    </div>
    <div style="border:1px solid rgba(148,163,184,.18);border-radius:12px;padding:8px 4px;text-align:center;background:rgba(2,6,23,.28);">
      <div style="font-size:.68rem;color:#94a3b8;font-weight:800;">買點</div>
      <div style="font-size:1rem;color:#f8fafc;font-weight:900;">{_html.escape(str(atk_s))}</div>
    </div>
    <div style="border:1px solid rgba(148,163,184,.18);border-radius:12px;padding:8px 4px;text-align:center;background:rgba(2,6,23,.28);">
      <div style="font-size:.68rem;color:#94a3b8;font-weight:800;">動能</div>
      <div style="font-size:1rem;color:#f8fafc;font-weight:900;">{_html.escape(str(focus_s))}</div>
    </div>
  </div>

  <div style="margin-top:10px;font-size:.9rem;color:#cbd5e1;line-height:1.55;">
    <b style="color:#e5e7eb;">目前動作：</b><span style="color:#f8fafc;font-weight:900;">{_html.escape(action_hint)}</span><br>
    <b style="color:#e5e7eb;">卡關：</b>{_html.escape(block)}<br>
    {absorption_html}
    {pre_lock_html}
    {('<b style="color:#e5e7eb;">承接標籤：</b><span style="color:#93c5fd;font-weight:900;">' + _html.escape(absorption_badge) + '</span><br>') if absorption_badge and absorption_badge not in ['—','-','None','nan'] else ''}
    {('<b style="color:#e5e7eb;">鎖碼標籤：</b><span style="color:#93c5fd;font-weight:900;">' + _html.escape(pre_lock_badge) + '</span><br>') if pre_lock_badge and pre_lock_badge not in ['—','-','None','nan'] else ''}
    <b style="color:#e5e7eb;">策略型態：</b><span style="color:#facc15;font-weight:900;">{_html.escape(strategy_tags)}</span><br>
    <b style="color:#e5e7eb;">族群資金：</b>{_html.escape(flow_status)}｜{_html.escape(flow_sector)}<br>
    <b style="color:#e5e7eb;">整體判讀：</b>{_html.escape(verdict)}<br>
    <b style="color:#e5e7eb;">買進機會：</b>{_html.escape(attack)}｜<b style="color:#e5e7eb;">買點分：</b>{_html.escape(str(buy_s))}<br>
    <b style="color:#e5e7eb;">回檔/估值：</b>{_html.escape(pullback)}｜{_html.escape(zone)}｜勝率 { _html.escape(str(win)) }<br>
    <b style="color:#e5e7eb;">觀察原因：</b>{_html.escape(tag_reason)}
  </div>
</div>
""",
            unsafe_allow_html=True,
        )

        if code:
            st.button(
                f"🔍 分析標的｜{title}",
                key=f"caf_card_analyze_{code}_{i}",
                use_container_width=True,
                on_click=select_scan_candidate,
                args=(code, name),
            )

    if len(df_scan) > max_cards:
        st.caption(f"已先顯示前 {max_cards} 檔；其餘請打開下方完整表格查看。")

    compact_cols = [
        "排序分", "股票", "策略型態", "資金狀態", "族群", "分類", "CAF成立度", "Core成立度", "Attack成立度", "Focus成立度",
        "買點分", "攻擊機會", "目前動作", "卡關原因", "法人承接狀態", "承接加分標籤", "錯殺驗證", "發動前鎖碼", "鎖碼分", "鎖碼說明", "鎖碼證據", "鎖碼缺資料"
    ]
    compact_cols = [c for c in compact_cols if c in df_scan.columns]
    with st.expander("完整雷達表格｜需要複製資料時再開", expanded=False):
        compact_display = df_scan[compact_cols].rename(columns={
            "CAF成立度": "整體分數",
            "Core成立度": "核心分數",
            "Attack成立度": "買點分數",
            "Focus成立度": "動能分數",
            "CAF判讀": "整體判讀",
        })
        st.dataframe(compact_display, use_container_width=True, hide_index=True)

    with st.expander("全部欄位｜進階查看", expanded=False):
        st.dataframe(df_scan, use_container_width=True, hide_index=True)



