def nick_unique_list(items):
    out = []
    for x in items or []:
        x = str(x or "").strip()
        if x and x not in out:
            out.append(x)
    return out


def nick_get_valuation_submodel_name(model_key: str) -> str:
    try:
        rule = (VALUATION_SUBMODEL_RULES or {}).get(str(model_key or ""), {})
        name = rule.get("name") or ""
        if name:
            return str(name)
    except Exception:
        pass
    return str(model_key or "通用估值模組")


def nick_get_evidence_rule_for_model(model_key: str) -> dict:
    """所有估值 / 產業子模組都要能搜尋與計分。

    1) 先找專用證據規則。
    2) 再用 valuation submodel alias 對到既有規則。
    3) 都沒有時建立通用 fallback 規則，避免畫面出現「不屬於六大子模組」。
    """
    mk = str(model_key or "default_pe_check")
    if mk in NICK_EVIDENCE_MODULE_RULES:
        rule = dict(NICK_EVIDENCE_MODULE_RULES[mk])
        rule["rule_type"] = "專用規則"
        return rule

    alias = NICK_EVIDENCE_MODEL_ALIAS.get(mk)
    if alias and alias in NICK_EVIDENCE_MODULE_RULES:
        rule = dict(NICK_EVIDENCE_MODULE_RULES[alias])
        rule["display"] = f"{nick_get_valuation_submodel_name(mk)}｜{rule.get('display', alias)}"
        rule["keywords"] = nick_unique_list((rule.get("keywords") or []) + nick_model_auto_search_keywords(mk))
        rule["needs"] = nick_unique_list((rule.get("needs") or []) + ["月營收", "毛利率", "EPS", "法人籌碼"])
        rule["rule_type"] = "估值子模組對應規則"
        return rule

    # 母模型規則：所有族群都至少有「搜尋證據方向」。
    # 注意：母模型只決定要查什麼，不決定 Core / Focus。
    try:
        family_key, family_rule = get_effective_family_context(mk, valuation_submodel_key=mk)
        evidence_tags = list(family_rule.get("evidence_tags") or [])
        risk_tags = list(family_rule.get("risk_tags") or [])
        family_name = str(family_rule.get("family_name") or "族群母模型")
        valuation_role = str(family_rule.get("valuation_role") or "")
        base_keywords = nick_unique_list(
            nick_model_auto_search_keywords(mk)
            + evidence_tags
            + risk_tags
            + [
                "月營收", "財報", "法說", "法人說明會", "公告", "重大訊息",
                "毛利率", "營益率", "EPS", "現金流", "法人", "籌碼", "目標價",
            ]
        )
        return {
            "display": f"{family_name}｜{nick_get_valuation_submodel_name(mk)}",
            "keywords": base_keywords,
            "needs": nick_unique_list(evidence_tags + ["月營收", "毛利率 / 營益率", "EPS", "現金流", "法人籌碼"]),
            "gap": f"此模組採母模型搜尋：需確認 { _nick_join_tags(evidence_tags, limit=5) } 是否真的轉成財報與估值支撐；反方需檢查 { _nick_join_tags(risk_tags, limit=4) }。子模組只代表分析框架，不直接決定 Core / Focus。",
            "valuation_role": valuation_role,
            "family_key": family_key,
            "rule_type": "母模型規則",
        }
    except Exception:
        pass

    kws = nick_unique_list(
        nick_model_auto_search_keywords(mk)
        + [
            "法說", "法人說明會", "月營收", "財報", "公告", "重大訊息",
            "毛利率", "營益率", "EPS", "現金流", "訂單", "出貨", "稼動率",
            "產品組合", "報價", "庫存", "應收", "法人",
        ]
    )
    return {
        "display": nick_get_valuation_submodel_name(mk),
        "keywords": kws,
        "needs": ["月營收", "毛利率 / 營益率", "EPS", "現金流", "產業關鍵指標", "法人籌碼"],
        "gap": "此模組採通用證據搜尋：需確認產業關鍵指標是否真的轉成營收、毛利率、EPS 與現金流；不能只靠題材或新聞升 Core / Focus。",
        "rule_type": "通用補完規則",
    }


