def _nick_evidence_decode_bytes(data: bytes) -> str:
    """盡量把上傳文字檔解碼。"""
    if not data:
        return ""
    for enc in ["utf-8", "utf-8-sig", "cp950", "big5", "latin-1"]:
        try:
            return data.decode(enc, errors="ignore")
        except Exception:
            continue
    return ""


def nick_extract_uploaded_evidence_text(uploaded_files):
    """讀取手動上傳的 TXT / CSV / PDF。PDF 只做文字層抽取，不做 OCR。"""
    if not uploaded_files:
        return "", []
    texts = []
    notes = []
    for f in uploaded_files:
        try:
            name = getattr(f, "name", "uploaded_file")
            raw = f.getvalue()
            lower = str(name).lower()
            if lower.endswith(".pdf"):
                pdf_text = ""
                try:
                    import pypdf
                    reader = pypdf.PdfReader(__import__("io").BytesIO(raw))
                    pages = []
                    for page in reader.pages[:20]:
                        try:
                            pages.append(page.extract_text() or "")
                        except Exception:
                            pages.append("")
                    pdf_text = "\n".join(pages).strip()
                except Exception:
                    try:
                        import PyPDF2
                        reader = PyPDF2.PdfReader(__import__("io").BytesIO(raw))
                        pages = []
                        for page in reader.pages[:20]:
                            try:
                                pages.append(page.extract_text() or "")
                            except Exception:
                                pages.append("")
                        pdf_text = "\n".join(pages).strip()
                    except Exception as e:
                        notes.append(f"{name}：PDF 文字抽取失敗，若是掃描圖檔需先轉文字。")
                        pdf_text = ""
                if pdf_text:
                    texts.append(f"\n--- 上傳 PDF：{name} ---\n{pdf_text[:12000]}")
                    notes.append(f"{name}：已抽取 PDF 文字")
                else:
                    notes.append(f"{name}：未抽到可用文字")
            else:
                decoded = _nick_evidence_decode_bytes(raw)
                if decoded:
                    texts.append(f"\n--- 上傳檔案：{name} ---\n{decoded[:12000]}")
                    notes.append(f"{name}：已讀取文字")
                else:
                    notes.append(f"{name}：無法讀取文字")
        except Exception as e:
            notes.append(f"{getattr(f, 'name', 'uploaded_file')}：讀取失敗 {e}")
    return "\n".join(texts).strip(), notes



# ============================================================
# fix64｜URL 抓取修正 + 官方資料捷徑
# 說明：
# - 修正 fix63 呼叫 nick_extract_url_evidence_text 但函式缺漏的問題。
# - URL 只作為「證據文字」來源，不直接改 Core / Attack / Focus。
# - 官方捷徑只提供查找入口，避免把搜尋結果誤當硬證據。
# ============================================================

def nick_extract_urls_from_text(text: str, max_urls: int = 5):
    if not text:
        return []
    raw = str(text).strip()
    urls = re.findall(r"https?://[^\s<>\"]+", raw)
    cleaned = []
    for u in urls:
        u = u.strip().rstrip("。），,)")
        if u and u not in cleaned:
            cleaned.append(u)
        if len(cleaned) >= max_urls:
            break
    return cleaned


def nick_strip_html_to_text(html: str) -> str:
    if not html:
        return ""
    s = str(html)
    s = re.sub(r"(?is)<script.*?>.*?</script>", " ", s)
    s = re.sub(r"(?is)<style.*?>.*?</style>", " ", s)
    s = re.sub(r"(?is)<noscript.*?>.*?</noscript>", " ", s)
    s = re.sub(r"(?is)<br\s*/?>", "\n", s)
    s = re.sub(r"(?is)</p\s*>", "\n", s)
    s = re.sub(r"(?is)</div\s*>", "\n", s)
    s = re.sub(r"(?is)<.*?>", " ", s)
    s = _html.unescape(s)
    s = re.sub(r"[ \t\r\f\v]+", " ", s)
    s = re.sub(r"\n\s*\n+", "\n", s)
    return s.strip()


def nick_fetch_single_url_evidence(url: str, max_chars: int = 12000):
    """抓單一 URL 文字。PDF 只抽文字層，不做 OCR。"""
    if not url:
        return "", "空 URL"
    try:
        headers = {
            "User-Agent": "Mozilla/5.0 NickEvidenceBot/1.0",
            "Accept": "text/html,application/pdf,text/plain,*/*",
        }
        r = requests.get(url, timeout=12, headers=headers)
        r.raise_for_status()
        content_type = (r.headers.get("content-type") or "").lower()
        raw = r.content or b""
        lower_url = str(url).lower()

        if "pdf" in content_type or lower_url.endswith(".pdf"):
            pdf_text = ""
            try:
                import pypdf
                reader = pypdf.PdfReader(__import__("io").BytesIO(raw))
                pages = []
                for page in reader.pages[:20]:
                    try:
                        pages.append(page.extract_text() or "")
                    except Exception:
                        pages.append("")
                pdf_text = "\n".join(pages).strip()
            except Exception:
                try:
                    import PyPDF2
                    reader = PyPDF2.PdfReader(__import__("io").BytesIO(raw))
                    pages = []
                    for page in reader.pages[:20]:
                        try:
                            pages.append(page.extract_text() or "")
                        except Exception:
                            pages.append("")
                    pdf_text = "\n".join(pages).strip()
                except Exception:
                    pdf_text = ""
            if pdf_text:
                return pdf_text[:max_chars], "已抽取 PDF 文字"
            return "", "PDF 未抽到文字，可能是掃描檔或網站限制"

        # HTML / text
        try:
            enc = r.encoding or "utf-8"
            page_text = raw.decode(enc, errors="ignore")
        except Exception:
            page_text = _nick_evidence_decode_bytes(raw)
        clean = nick_strip_html_to_text(page_text)
        if clean:
            return clean[:max_chars], "已抓取網頁文字"
        return "", "未抓到可用文字"
    except Exception as e:
        return "", f"抓取失敗：{e}"


def nick_extract_url_evidence_text(url_text: str):
    """讀取 URL 欄位，一行一個網址。回傳合併文字與抓取狀態。"""
    urls = nick_extract_urls_from_text(url_text, max_urls=5)
    if not urls:
        return "", []
    texts = []
    notes = []
    for idx, url in enumerate(urls, start=1):
        body, note = nick_fetch_single_url_evidence(url)
        short_url = url if len(url) <= 72 else url[:69] + "..."
        notes.append(f"URL{idx}：{note}｜{short_url}")
        if body:
            texts.append(f"\n--- URL{idx}：{url} ---\n{body}")
    return "\n".join(texts).strip(), notes


def nick_official_source_shortcuts(stock: str, name: str = ""):
    """產生官方 / 半官方資料查找捷徑。這只是找資料，不代表證據已驗證。"""
