def _nick_kw_weighted_hits(text: str, rule: dict):
    t = str(text or "")
    buckets = [("strong", 3.0), ("product", 2.0), ("future", 1.5), ("generic", 0.5)]
    hits = []
    score = 0.0
    seen = set()
    for bucket, weight in buckets:
        for kw in rule.get(bucket, []) or []:
            if not kw:
                continue
            if str(kw).lower() in t.lower():
                k = str(kw).lower()
                if k not in seen:
                    seen.add(k)
                    hits.append({"keyword": str(kw), "bucket": bucket, "weight": weight})
                    score += weight
    return score, hits

