def _nick_rule_family_tokens(rule: dict):
    fam = str((rule or {}).get("family") or "")
    tokens = []
    for fam_key, vals in NICK_MODULE_FAMILY_ALLOWED_MODEL_TOKENS.items():
        if fam_key and fam_key in fam:
            tokens.extend(vals)
    # 若 family 沒命中，退一步用 key / suggested_model_key 判斷。
    key_blob = (str((rule or {}).get("key") or "") + " " + str((rule or {}).get("suggested_model_key") or "")).lower()
    for fam_key, vals in NICK_MODULE_FAMILY_ALLOWED_MODEL_TOKENS.items():
        if any(v in key_blob for v in vals):
            tokens.extend(vals)
    out = []
    for t in tokens:
        if t and t not in out:
            out.append(t)
    return out

def _nick_module_rule_allowed_by_current_model(rule: dict, current_model_key: str) -> bool:
    """先鎖母族群：非同大方向的規則不掃，避免電子股跳金融、面板股跳航運。"""
    mk = str(current_model_key or "").strip().lower()
    if not mk:
        return True
    # default / growth_premium 是粗模型，允許用關鍵字提示，但後續仍需財報 + 核心詞防呆。
    if mk in ["default", "default_pe_check", "growth_premium"]:
        return True
    accepted = _nick_lower_set((rule or {}).get("accepted_models"))
    suggested_key = str((rule or {}).get("suggested_model_key") or "").lower()
    if mk in accepted or (suggested_key and mk == suggested_key):
        return True
    tokens = _nick_rule_family_tokens(rule or {})
    if not tokens:
        return True
    return any(str(t).lower() in mk for t in tokens)

def _nick_news_rows_to_text_bound(news_rows, stock=None, name=None):
    """模組適配用：新聞必須跟股票名稱或代號強綁定，避免抓到頁面雜訊。"""
    parts = []
    code = str(stock or "").strip()
    nm = str(name or "").strip()
    for r in news_rows or []:
        try:
            title = str(r.get("title") or r.get("標題") or "")
            source = str(r.get("source") or r.get("來源") or "")
            date = str(r.get("date") or r.get("日期") or "")
            blob = title + " " + source
            if not title:
                continue
            # 若有名稱 / 代號，新聞標題或來源文字至少要命中其中之一；否則不納入模組適配。
            if (code or nm) and (code not in blob and (not nm or nm not in blob)):
                continue
            parts.append(f"{date} {source} {title}")
        except Exception:
            continue
    return "\n".join(parts)

def _nick_short_module_direction(box: dict) -> str:
    label = str((box or {}).get("suggested_label") or "").strip()
    family = str((box or {}).get("family") or "").strip()
    direction = label or family or "可能需覆核子模組"
    # 手機小字只放短方向，避免一長串擠版。
    if len(direction) > 24:
        direction = direction[:24] + "…"
    return direction

def _nick_fin_feature_hits_for_rule(rule: dict, fin: dict, fj: dict):
    checks = rule.get("finance_checks") or {}
    hits = []
    gm = to_float((fin or {}).get("gross_margin"))
    opm = to_float((fin or {}).get("operating_margin"))
    rev_yoy = to_float((fin or {}).get("revenue_yoy"))
    eps_yoy = to_float((fin or {}).get("eps_yoy"))
    try:
        if checks.get("gross_margin_min") is not None and gm is not None and gm >= float(checks.get("gross_margin_min")):
            hits.append(f"毛利率 {gm:.1f}% ≥ {float(checks.get('gross_margin_min')):.0f}%")
        if checks.get("gross_margin_max") is not None and gm is not None and gm <= float(checks.get("gross_margin_max")):
            hits.append(f"毛利率 {gm:.1f}% ≤ {float(checks.get('gross_margin_max')):.0f}%")
        if checks.get("operating_margin_min") is not None and opm is not None and opm >= float(checks.get("operating_margin_min")):
            hits.append(f"營益率 {opm:.1f}% ≥ {float(checks.get('operating_margin_min')):.0f}%")
        if checks.get("revenue_yoy_min") is not None and rev_yoy is not None and rev_yoy >= float(checks.get("revenue_yoy_min")):
            hits.append(f"營收年增 {rev_yoy:.1f}% ≥ {float(checks.get('revenue_yoy_min')):.0f}%")
        if checks.get("eps_yoy_min") is not None and eps_yoy is not None and eps_yoy >= float(checks.get("eps_yoy_min")):
            hits.append(f"EPS 年增 {eps_yoy:.1f}% ≥ {float(checks.get('eps_yoy_min')):.0f}%")
    except Exception:
        pass
    # 法醫財報特徵作為通用補充，不取代上方硬條件。
    try:
        if (fj or {}).get("report") == "通過":
            hits.append("財報通過")
        if (fj or {}).get("revenue_to_eps") in ["有", "部分有"]:
            hits.append("營收有轉 EPS")
        if (fj or {}).get("margin") in ["有", "普通"]:
            hits.append("毛利率 / 營益率具支撐")
    except Exception:
        pass
    # 去重
    out = []
    seen = set()
    for h in hits:
        if h not in seen:
            seen.add(h)
            out.append(h)
    return out

def nick_module_adaptation_check(stock, name, a, rev=None, fin=None, news_rows=None, manual_text="", uploaded_text=""):
    """族群級模組適配檢查：只做提示，不自動切換模型，不改 Core / Attack / Focus。"""
    val = (a or {}).get("val") or {}
    current_model_key = str(val.get("model_key") or val.get("model") or "default").strip()
    current_model_name = (MODEL_CONFIG.get(current_model_key) or {}).get("name", current_model_key)
    fj = (a or {}).get("fin_j") or {}
    # v47-7：模組適配只採用與股票名稱 / 代號強綁定的新聞，避免抓到頁面雜訊或不相關新聞。
    news_text = _nick_news_rows_to_text_bound(news_rows, stock=stock, name=name)
    combined = "\n".join([str(news_text or ""), str(manual_text or ""), str(uploaded_text or "")]).strip()
    if not combined:
        return {"show": False, "reason": "沒有新聞 / 手動文字可供關鍵字檢查"}

    best = None
    for rule in NICK_MODULE_ADAPTATION_RULES:
        # v47-7：先鎖母族群；非同大方向的規則不掃，避免面板股跳金融、電子股跳航運。
        if not _nick_module_rule_allowed_by_current_model(rule, current_model_key):
            continue
        kw_score, kw_hits = _nick_kw_weighted_hits(combined, rule)
        if kw_score < float(rule.get("min_keyword_score", 6.0)):
            continue
        # v47-5｜第二版詞庫防呆：避免只有「AI / 營收 / EPS」等泛用詞就觸發。
        # 至少要命中 strong / product / future 其中一類核心詞，才進入財報特徵檢查。
        core_kw_hits = [h for h in (kw_hits or []) if h.get("bucket") in ["strong", "product", "future"]]
        min_core_hits = int(rule.get("min_core_hits", 1) or 0)
        if len(core_kw_hits) < min_core_hits:
            continue
        fin_hits = _nick_fin_feature_hits_for_rule(rule, fin or {}, fj)
        min_fin_hits = int(rule.get("min_fin_hits", 0) or 0)
        if len(fin_hits) < min_fin_hits:
            continue
        accepted = _nick_lower_set(rule.get("accepted_models"))
        suggested_key = str(rule.get("suggested_model_key") or "")
        # 已經在正確或可接受模型，不必吵；除非未來要做適配成功提示，目前先不顯示。
        if current_model_key.lower() in accepted or (suggested_key and current_model_key.lower() == suggested_key.lower()):
            continue
        coarse = _nick_lower_set(rule.get("coarse_models"))
        model_mismatch_bonus = 8 if (current_model_key.lower() in coarse or current_model_key.lower() in ["default", "default_pe_check", "growth_premium"]) else 2
        score = int(max(0, min(95, round(kw_score * 5 + min(len(fin_hits), 4) * 8 + model_mismatch_bonus))))
        if score < 60:
            continue
        if score >= 85:
            level = "可建議切換子模組"
        elif score >= 75:
            level = "高度建議覆核"
        else:
            level = "輕度提醒"
        item = {
            "show": True,
            "score": score,
            "level": level,
            "family": rule.get("family", ""),
            "suggested_label": rule.get("suggested_label", ""),
            "suggested_model_key": suggested_key,
            "current_model_key": current_model_key,
            "current_model_name": current_model_name,
            "keyword_hits": [h.get("keyword") for h in kw_hits[:12]],
            "keyword_score": round(kw_score, 1),
            "financial_hits": fin_hits[:8],
            "verdict": "僅提示覆核，不自動改 Core / Attack / Focus；若要切換，需由對應子族群規則卡確認。",
        }
        if best is None or item["score"] > best["score"]:
            best = item
    return best or {"show": False, "reason": "未達模組適配提醒門檻"}

def nick_module_adaptation_quick_text(box: dict):
    if not box or not box.get("show"):
        return ""
    hits = "、".join((box.get("keyword_hits") or [])[:8]) or "未列出"
    fins = "、".join((box.get("financial_hits") or [])[:5]) or "仍需財報確認"
    return (
        "【新聞關鍵字模組適配｜後台覆核】\n"
        f"模組適配信心：{box.get('score')}分｜{box.get('level')}\n"
        f"目前模型：{box.get('current_model_name')}\n"
        f"覆核方向：{box.get('family')}｜{box.get('suggested_label')}\n"
        f"新聞命中：{hits}\n"
        f"財報特徵：{fins}\n"
        "裁決：僅作後台覆核提醒，不進入 30 秒判讀主文；若與主模型產業不一致，不得直接改產業方向。"
    )

def nick_module_adaptation_detail_text(box: dict):
    if not box or not box.get("show"):
        return "【新聞關鍵字模組適配】\n未觸發模組適配提醒。"
    return nick_module_adaptation_quick_text(box)



