def nick_generic_news_catalyst_classify(text: str, structured: dict = None, model_key: str = ""):
    """把新聞 / 法說 / 公告先做通用催化分類，再交給族群母模型與財報驗證。

    回傳不直接決定 Core / Attack / Focus；它只回答：新聞在暗示哪一種估值重評路徑。
    """
    s = str(text or "")
    if not s.strip():
        return {
            "level": "資料不足",
            "score": 0,
            "types": [],
            "labels": [],
            "summary": "尚未取得可判讀的新聞 / 法說 / 公告內容。",
            "valuation_bridge": "無新聞催化橋接；估值仍以財報硬資料為主。",
        }
    items = []
    score = 0
    for key, rule in NICK_GENERIC_CATALYST_RULES.items():
        hits = nick_keyword_hits(s, rule.get("keywords", []))
        if not hits:
            continue
        snippets = nick_keyword_snippets(s, hits, limit=3)
        strong_hits = nick_keyword_hits("\n".join(snippets) or s, rule.get("strong_words", []))
        values = nick_extract_percent_values("\n".join(snippets) or s)
        item_score = 1 + (1 if strong_hits else 0) + (1 if values else 0)
        score += item_score
        items.append({
            "type": key,
            "label": rule.get("label", key),
            "hits": hits[:8],
            "strong_hits": strong_hits[:6],
            "values": values[:6],
            "snippets": snippets[:3],
            "score": item_score,
            "valuation_role": rule.get("valuation_role", "仍需財報驗證。"),
        })

    # 結構化證據可補強通用分類，即使產業字典沒完全命中，也能知道新聞屬於出貨、產品、毛利、認證等重評線索。
    structured = structured or {}
    try:
        focus_strong = int(structured.get("focus_strong") or 0)
        focus_hit = int(structured.get("focus_hit") or 0)
    except Exception:
        focus_strong, focus_hit = 0, 0
    if focus_strong >= 2:
        score += 2
    elif focus_hit >= 1:
        score += 1

    labels = []
    seen = set()
    for item in sorted(items, key=lambda x: x.get("score", 0), reverse=True):
        lab = item.get("label")
        if lab and lab not in seen:
            labels.append(lab)
            seen.add(lab)

    if score >= 8 and len(labels) >= 3:
        level = "高｜重評線索完整"
        bridge = "新聞已出現多重重評線索，但仍需月營收、毛利率、EPS 與現金流交叉驗證後，才可提高估值倍數。"
    elif score >= 5 and len(labels) >= 2:
        level = "中高｜重評線索明確"
        bridge = "新聞有明確催化方向，可作估值重評佐證；若財報同步通過，估值區間可考慮上修。"
    elif score >= 2:
        level = "中｜初步催化"
        bridge = "新聞有題材或需求線索，但尚不足以單獨提高估值，需看財報是否接上。"
    else:
        level = "低｜題材不足"
        bridge = "目前新聞催化不足，估值以既有財報與族群模型為主。"

    summary = "、".join(labels[:4]) if labels else "尚未萃取到明確催化類型"
    return {
        "level": level,
        "score": int(score),
        "types": [x.get("type") for x in items],
        "labels": labels,
        "items": items[:8],
        "summary": summary,
        "valuation_bridge": bridge,
        "model_key": model_key or "",
    }



