def _nick_structured_keys_with_signal(structured: dict):
    out = []
    for it in (structured or {}).get("items", []) or []:
        if it.get("status") and it.get("status") != "資料不足":
            out.append(str(it.get("key") or ""))
    return [x for x in out if x]


def nick_sector_catalyst_playbook(a: dict, catalyst: dict, structured: dict, model_key: str = "", industry_category: str = ""):
    """把通用新聞催化放回族群母模型，輸出『這則新聞對本族群估值重評代表什麼』。
    此函式不做個股特例，也不直接改 Core / Attack / Focus。
    """
    a = a or {}
    catalyst = catalyst or {}
    structured = structured or {}
    model_key = str(model_key or (a.get("val") or {}).get("model_key") or "")
    try:
        family_key = get_model_family_key(model_key, industry_category)
    except Exception:
        family_key = "quality_growth_pe"
    playbook = NICK_SECTOR_CATALYST_PLAYBOOKS.get(family_key)

    if playbook is None and family_key == "quality_growth_pe" and any(t in (catalyst.get("types") or []) for t in ["product_upgrade", "customer_validation", "margin_eps_upgrade"]):
        playbook = {
            "name": "高品質成長｜新聞催化待歸類",
            "applies_to": "尚未建立專用族群模型的高品質成長股",
            "generic_types": ["product_upgrade", "demand_expansion", "customer_validation", "margin_eps_upgrade"],
            "structured_keys": ["product_mix", "orders_shipments", "customer_certification", "margin_eps_outlook"],
            "valuation_meaning": "新聞顯示可能有產品升級或需求放大，但族群專用模型不足，估值仍需保守。",
            "must_validate": ["營收是否延續", "毛利率是否改善", "EPS 是否上修", "現金流是否配合"],
            "risk_note": "模型尚未完整，不能因新聞直接提高估值或 Focus。",
        }

    if playbook is None:
        return {
            "family_key": family_key,
            "path_name": "新題材 / 族群模型不足",
            "score": int(catalyst.get("score") or 0),
            "level": "保守｜需建立族群模型",
            "matched_generic": catalyst.get("labels", [])[:4],
            "matched_structured": [],
            "valuation_meaning": "目前只能判斷新聞有無催化，尚無足夠族群路徑可推估估值重評。",
            "must_validate": ["月營收", "毛利率", "EPS", "現金流", "法人籌碼"],
            "risk_note": "遇到新產業或新名詞時，需回灌法醫報告建立族群規則。",
            "is_model_gap": True,
        }

    c_types = set(catalyst.get("types") or [])
    s_keys = set(_nick_structured_keys_with_signal(structured))
    matched_generic = [t for t in playbook.get("generic_types", []) if t in c_types]
    matched_structured = [k for k in playbook.get("structured_keys", []) if k in s_keys]

    fj = a.get("fin_j") or {}
    rr = a.get("rerating") or {}
    fin_hard_ok = bool(
        fj.get("report") == "通過"
        and fj.get("eps") in ["有", "部分有"]
        and fj.get("margin") in ["有", "普通"]
        and fj.get("cashflow") in ["有", "普通"]
    )
    rerating_ok = str(rr.get("verdict") or "") in ["成立", "部分成立"]

    score = int(catalyst.get("score") or 0)
    score += len(matched_generic)
    score += len(matched_structured) * 2
    if fin_hard_ok:
        score += 3
    if rerating_ok:
        score += 2

    if score >= 14 and fin_hard_ok and rerating_ok:
        level = "高｜族群重評路徑成立"
    elif score >= 10 and fin_hard_ok:
        level = "中高｜族群重評路徑明確"
    elif score >= 6:
        level = "中｜有族群催化路徑"
    else:
        level = "低～中｜催化仍需驗證"

    return {
        "family_key": family_key,
        "path_name": playbook.get("name", family_key),
        "applies_to": playbook.get("applies_to", ""),
        "score": int(score),
        "level": level,
        "matched_generic": [NICK_GENERIC_CATALYST_RULES.get(t, {}).get("label", t) for t in matched_generic],
        "matched_structured": [NICK_STRUCTURED_EVIDENCE_CATEGORIES.get(k, {}).get("label", k) for k in matched_structured],
        "valuation_meaning": playbook.get("valuation_meaning", ""),
        "must_validate": playbook.get("must_validate", []),
        "risk_note": playbook.get("risk_note", ""),
        "is_model_gap": False,
        "fin_hard_ok": fin_hard_ok,
        "rerating_ok": rerating_ok,
    }


def nick_sector_catalyst_detail_lines(path: dict, max_items: int = 5):
    if not path:
        return ["- 族群催化路徑：資料不足"]
    lines = [f"- 族群催化路徑：{path.get('level', '')}｜{path.get('path_name', '')}"]
    if path.get("matched_generic"):
        lines.append("  • 通用催化：" + "、".join(path.get("matched_generic", [])[:max_items]))
    if path.get("matched_structured"):
        lines.append("  • 族群證據：" + "、".join(path.get("matched_structured", [])[:max_items]))
    if path.get("valuation_meaning"):
        lines.append("  • 對估值的意思：" + str(path.get("valuation_meaning")))
    if path.get("must_validate"):
        lines.append("  • 仍要驗證：" + "、".join(path.get("must_validate", [])[:max_items]))
    if path.get("risk_note"):
        lines.append("  • 風險提醒：" + str(path.get("risk_note")))
    return lines

def nick_generic_catalyst_detail_lines(catalyst: dict, max_items: int = 5):
    if not catalyst:
        return ["- 新聞催化分類：資料不足"]
    lines = [f"- 新聞催化分類：{catalyst.get('level', '資料不足')}｜{catalyst.get('summary', '')}"]
    for item in (catalyst.get("items") or [])[:max_items]:
        extra = ""
        if item.get("values"):
            extra = "｜數字：" + "、".join(item.get("values")[:3])
        elif item.get("hits"):
            extra = "｜命中：" + "、".join(item.get("hits")[:5])
        lines.append(f"  • {item.get('label')}：{item.get('valuation_role')}{extra}")
    lines.append(f"- 估值橋接：{catalyst.get('valuation_bridge', '')}")
    return lines


def nick_apply_news_catalyst_overlay(a: dict, evidence_box: dict):
    """把新聞催化分類回寫到 a / val，讓估值頁與自檢頁看得到新聞如何橋接估值。

    注意：此函式採保守設計。它不單靠新聞改 Core / Focus，也不直接無腦上修所有族群 PE。
    只有在已通過財報與估值重評的情況下，才把新聞催化標示為可支撐重評。
    """
    a = a or {}
    evidence_box = evidence_box or {}
    catalyst = evidence_box.get("generic_news_catalyst") or {}
    sector_path = evidence_box.get("sector_catalyst_path") or {}
    rerating_score_box = evidence_box.get("rerating_score") or {}
    val = a.get("val") or {}
    fj = a.get("fin_j") or {}
    rr = a.get("rerating") or {}

    a["news_catalyst"] = catalyst
    a["sector_catalyst_path"] = sector_path
    try:
        if isinstance(a.get("_diag"), dict):
            a["_diag"]["news_catalyst_level"] = catalyst.get("level", "")
            a["_diag"]["news_catalyst_types"] = catalyst.get("labels", [])
            a["_diag"]["news_to_valuation_bridge"] = catalyst.get("valuation_bridge", "")
            a["_diag"]["sector_catalyst_path"] = sector_path.get("path_name", "")
            a["_diag"]["sector_catalyst_level"] = sector_path.get("level", "")
            a["_diag"]["sector_catalyst_score"] = sector_path.get("score", 0)
            a["_diag"]["rerating_score"] = rerating_score_box.get("score", 0)
            a["_diag"]["rerating_score_label"] = rerating_score_box.get("label", "")
            a["_diag"]["rerating_pe_uplift_allowed"] = rerating_score_box.get("allow_pe_uplift", False)
    except Exception:
        pass

    if isinstance(val, dict):
        val["news_catalyst_level"] = catalyst.get("level", "")
        val["news_catalyst_summary"] = catalyst.get("summary", "")
        val["news_to_valuation_bridge"] = catalyst.get("valuation_bridge", "")
        val["news_catalyst_score"] = catalyst.get("score", 0)
        val["sector_catalyst_path"] = sector_path.get("path_name", "")
        val["sector_catalyst_level"] = sector_path.get("level", "")
        val["sector_catalyst_score"] = sector_path.get("score", 0)
        val["sector_catalyst_valuation_meaning"] = sector_path.get("valuation_meaning", "")
        val["rerating_score"] = rerating_score_box.get("score", 0)
        val["rerating_score_label"] = rerating_score_box.get("label", "")
        val["rerating_score_verdict"] = rerating_score_box.get("verdict", "")
        val["rerating_score_conclusion"] = rerating_score_box.get("conclusion", "")
        val["rerating_score_components"] = rerating_score_box.get("components", [])
        val["rerating_pe_uplift_allowed"] = rerating_score_box.get("allow_pe_uplift", False)
        # 財報硬資料 + 重評成立 + 新聞催化明確，才標示為「新聞支撐重評」。
        news_supports_rerating = bool(
            ((catalyst.get("score") or 0) >= 5 or (rerating_score_box.get("score") or 0) >= 55)
            and fj.get("report") == "通過"
            and fj.get("margin") in ["有", "普通"]
            and fj.get("eps") in ["有", "部分有"]
            and rr.get("verdict") in ["成立", "部分成立"]
        )
        val["news_supports_rerating"] = news_supports_rerating
        if news_supports_rerating:
            _sector_msg = ""
            if sector_path.get("path_name"):
                _sector_msg = "；族群催化路徑：" + str(sector_path.get("path_name") or "")
            val["reason"] = str(val.get("reason") or "") + "；新聞 / 法說催化已橋接估值重評：" + str(catalyst.get("summary") or "") + _sector_msg
        a["val"] = val
    return a



# ============================================================
# v40｜估值重評分數引擎
# ------------------------------------------------------------
# 目的：把「新聞催化 → 族群路徑 → 財報驗證 → 籌碼確認」轉成可檢查的分數。
# 注意：此分數不直接決定 Core / Attack / Focus，也不單靠新聞上修估值；
#      它只回答「這個利多有多像真正估值重評，而不是普通題材」。
# ============================================================
def nick_rerating_score_engine(a: dict, catalyst: dict, sector_path: dict, structured: dict, revenue_signal: dict = None, inst: dict = None, fin: dict = None, risk_hits=None):
    a = a or {}
    catalyst = catalyst or {}
    sector_path = sector_path or {}
    structured = structured or {}
    revenue_signal = revenue_signal or {}
    inst = inst or {}
    fin = fin or {}
    risk_hits = risk_hits or []
    fj = a.get('fin_j') or {}
    rr = a.get('rerating') or {}
    val = a.get('val') or {}

    components = []
    reasons = []
    blockers = []

    # 1) 新聞 / 法說催化：最高 18 分
    try:
        catalyst_raw = int(catalyst.get('score') or 0)
    except Exception:
        catalyst_raw = 0
    news_score = min(18, round(catalyst_raw * 2.2))
    if catalyst_raw >= 8:
        reasons.append('新聞 / 法說出現多重重評線索')
    elif catalyst_raw >= 5:
        reasons.append('新聞 / 法說有明確催化方向')
    elif catalyst_raw >= 2:
        reasons.append('新聞 / 法說只有初步題材線索')
    else:
        blockers.append('新聞 / 法說催化不足')
    components.append({'key':'news_catalyst','label':'新聞催化','score':int(news_score),'max':18})

    # 2) 族群催化路徑：最高 15 分
    try:
        sector_raw = int(sector_path.get('score') or 0)
    except Exception:
        sector_raw = 0
    sector_score = min(15, round(sector_raw * 1.05))
    if sector_path.get('is_model_gap'):
        sector_score = min(sector_score, 6)
        blockers.append('族群模型不足，重評需保守')
    elif sector_raw >= 14:
        reasons.append('族群催化路徑成立')
    elif sector_raw >= 10:
        reasons.append('族群催化路徑明確')
    elif sector_raw >= 6:
        reasons.append('有族群催化路徑，但仍需驗證')
    components.append({'key':'sector_path','label':'族群催化路徑','score':int(sector_score),'max':15})

    # 3) 財報驗證：最高 22 分
    fin_score = 0
    if fj.get('report') == '通過':
        fin_score += 6; reasons.append('財報通過')
    elif fj.get('report') in ['部分通過','部分通過偏強']:
        fin_score += 3; blockers.append('財報僅部分通過')
    else:
        blockers.append('財報尚未通過')
    if fj.get('revenue_to_eps') in ['有','部分有']:
        fin_score += 4; reasons.append('營收有轉 EPS')
    if fj.get('margin') == '有':
        fin_score += 5; reasons.append('毛利率 / 營益率支撐')
    elif fj.get('margin') == '普通':
        fin_score += 2
    if fj.get('eps') in ['有','部分有']:
        fin_score += 4; reasons.append('EPS 有支撐')
    if fj.get('cashflow') in ['有','普通']:
        fin_score += 3; reasons.append('現金流可用')
    components.append({'key':'financial_validation','label':'財報驗證','score':int(min(fin_score,22)),'max':22})

    # 4) 毛利率 / EPS / 營收數字驗證：最高 15 分
    hard_score = 0
    rev_yoy = to_float((fin or {}).get('revenue_yoy'))
    rev_mom = to_float((fin or {}).get('revenue_mom'))
    gm = to_float((fin or {}).get('gross_margin'))
    opm = to_float((fin or {}).get('operating_margin'))
    eps_yoy = to_float((fin or {}).get('eps_yoy'))
    if rev_yoy is not None:
        if rev_yoy >= 50:
            hard_score += 4; reasons.append(f'月營收年增 {rev_yoy:.1f}%')
        elif rev_yoy >= 20:
            hard_score += 3
        elif rev_yoy > 0:
            hard_score += 1
    if rev_mom is not None:
        if rev_mom >= 10:
            hard_score += 2; reasons.append(f'月營收月增 {rev_mom:.1f}%')
        elif rev_mom > 0:
            hard_score += 1
    if gm is not None:
        if gm >= 40:
            hard_score += 4; reasons.append(f'毛利率 {gm:.1f}% 高檔')
        elif gm >= 25:
            hard_score += 3
        elif gm >= 15:
            hard_score += 1
    if opm is not None:
        if opm >= 20:
            hard_score += 3; reasons.append(f'營益率 {opm:.1f}% 支撐')
        elif opm >= 10:
            hard_score += 2
        elif opm > 0:
            hard_score += 1
    if eps_yoy is not None:
        if eps_yoy >= 50:
            hard_score += 3; reasons.append(f'EPS 年增 {eps_yoy:.1f}%')
        elif eps_yoy >= 20:
            hard_score += 2
        elif eps_yoy > 0:
            hard_score += 1
    # 下月營收可信度是補強，不取代財報
    try:
        rev_sig_score = int(revenue_signal.get('score') or 0)
        if rev_sig_score >= 80:
            hard_score += 2; reasons.append('下月營收可信度高')
        elif rev_sig_score >= 70:
            hard_score += 1
    except Exception:
        pass
    components.append({'key':'margin_eps_numbers','label':'毛利率 / EPS 數字','score':int(min(hard_score,15)),'max':15})

    # 5) 籌碼確認：最高 15 分
    chip_score = 0
    try:
        cj = a.get('chip_j') or {}
        cj_score = float(cj.get('score') or 0)
    except Exception:
        cj_score = 0
    if cj_score >= 3:
        chip_score += 5; reasons.append('籌碼偏多')
    elif cj_score >= 1:
        chip_score += 3
    elif cj_score < 0:
        blockers.append('籌碼偏弱')
    f20 = to_float(inst.get('foreign_net20_lot'))
    t20 = to_float(inst.get('trust_net20_lot') or inst.get('investment_trust_net20_lot'))
    n20 = to_float(inst.get('net20_lot'))
    pos20 = to_float(inst.get('positive_days_20'))
    if f20 is not None and f20 >= 50000:
        chip_score += 4; reasons.append('外資 20 日明顯買超')
    elif f20 is not None and f20 > 0:
        chip_score += 2
    if t20 is not None and t20 >= 10000:
        chip_score += 3; reasons.append('投信 20 日明顯買超')
    elif t20 is not None and t20 > 0:
        chip_score += 1
    if n20 is not None and n20 >= 100000:
        chip_score += 3; reasons.append('法人合計 20 日大買')
    elif n20 is not None and n20 > 0:
        chip_score += 1
    if pos20 is not None and pos20 >= 12:
        chip_score += 2; reasons.append('近 20 日買進天數偏多')
    components.append({'key':'institutional_confirmation','label':'法人籌碼確認','score':int(min(chip_score,15)),'max':15})

    # 6) 族群 / 技術主流補強：最高 15 分
    trend_score = 0
    try:
        price_status = str(a.get('price_status') or '')
        trend = a.get('trend') or {}
        action = str(a.get('action') or '')
        if '主升' in action or '主升' in price_status:
            trend_score += 3
        if str(a.get('attack') or '') == 'Yes':
            trend_score += 3
        elif str(a.get('attack') or '') in ['候選','回檔候選']:
            trend_score += 1
        if str(a.get('core') or '') == 'Yes':
            trend_score += 3
        if str(rr.get('verdict') or '') == '成立':
            trend_score += 4; reasons.append('估值重評原裁決成立')
        elif str(rr.get('verdict') or '') == '部分成立':
            trend_score += 2
        # 結構化證據若有多項命中，也視為族群主流 / 產品路徑補強
        try:
            focus_strong = int((structured or {}).get('focus_strong') or 0)
            if focus_strong >= 2:
                trend_score += 2; reasons.append('結構化證據明確')
            elif focus_strong >= 1:
                trend_score += 1
        except Exception:
            pass
    except Exception:
        pass
    components.append({'key':'mainstream_confirmation','label':'族群 / 主升確認','score':int(min(trend_score,15)),'max':15})

    # 風險扣分：最高 12 分
    penalty = 0
    risk_text = []
    if risk_hits:
        penalty += min(6, len(risk_hits)*2)
        risk_text.append('新聞 / 法說出現風險詞')
    # 財報硬傷不直接歸零，但限制等級
    if fj.get('cashflow') == '沒有':
        penalty += 4; risk_text.append('現金流不配合')
    if fj.get('working_capital_verdict') in ['警訊','硬傷'] or fj.get('inv_ar') in ['異常','警訊','硬傷']:
        penalty += 4; risk_text.append('營運資金需警戒')
    if fj.get('liability') in ['明顯惡化','高']:
        penalty += 3; risk_text.append('負債壓力需追蹤')

    raw = sum(c['score'] for c in components)
    score = int(max(0, min(100, raw - min(penalty, 12))))

    if score >= 82:
        label = '強成立'
        verdict = '估值重評強成立'
        allow_pe_uplift = True
        conclusion = '新聞催化、財報驗證、毛利率 / EPS 與籌碼多數接上，可進入重評 PE / 估值區間，但仍要看買點。'
    elif score >= 70:
        label = '成立'
        verdict = '估值重評成立'
        allow_pe_uplift = True
        conclusion = '重評條件多數成立，可支撐估值上修；若現價已高，仍以回檔或回測為主。'
    elif score >= 55:
        label = '部分成立'
        verdict = '估值重評部分成立'
        allow_pe_uplift = False
        conclusion = '已有重評線索，但仍缺財報、籌碼或族群證據完整驗證，估值上修需保守。'
    elif score >= 40:
        label = '初步線索'
        verdict = '估值重評初步線索'
        allow_pe_uplift = False
        conclusion = '目前偏題材或單一證據，尚不足以提高估值倍數。'
    else:
        label = '不成立'
        verdict = '估值重評不成立'
        allow_pe_uplift = False
        conclusion = '重評證據不足，估值仍以原本族群模型保守看。'

    # 若財報未通過，最高只能部分成立
    if fj.get('report') not in ['通過','部分通過','部分通過偏強'] and score > 54:
        score = 54; label = '初步線索'; verdict = '估值重評初步線索'; allow_pe_uplift = False
        conclusion = '財報尚未通過，新聞催化不可直接轉成估值重評。'
    elif fj.get('report') != '通過' and score >= 70:
        score = min(score, 69); label = '部分成立'; verdict = '估值重評部分成立'; allow_pe_uplift = False
        conclusion = '財報僅部分通過，重評需保守，不直接上修到高倍數區間。'

    # 去重理由
    clean_reasons = []
    for r in reasons:
        if r and r not in clean_reasons:
            clean_reasons.append(r)
    clean_blockers = []
    for b in blockers + risk_text:
        if b and b not in clean_blockers:
            clean_blockers.append(b)

    return {
        'score': score,
        'label': label,
        'verdict': verdict,
        'allow_pe_uplift': allow_pe_uplift,
        'components': components,
        'reasons': clean_reasons[:10],
        'blockers': clean_blockers[:8],
        'risk_penalty': int(min(penalty,12)),
        'conclusion': conclusion,
        'pe_policy': '可評估重評 PE / 上修估值區間' if allow_pe_uplift else '不得只因新聞上修 PE；估值維持保守或部分重評',
    }


def nick_rerating_score_detail_lines(score_box: dict, max_items: int = 6):
    if not score_box:
        return ['- 估值重評分數：資料不足']
    lines = [f"- 估值重評分數：{score_box.get('score', 0)}分｜{score_box.get('label', '')}｜{score_box.get('verdict', '')}"]
    comps = score_box.get('components') or []
    if comps:
        parts = [f"{c.get('label')} {c.get('score')}/{c.get('max')}" for c in comps[:max_items]]
        lines.append('  • 分數拆解：' + '、'.join(parts))
    if score_box.get('reasons'):
        lines.append('  • 加分依據：' + '、'.join(score_box.get('reasons', [])[:max_items]))
    if score_box.get('blockers'):
        lines.append('  • 保守原因：' + '、'.join(score_box.get('blockers', [])[:max_items]))
    if score_box.get('pe_policy'):
        lines.append('  • PE / 估值政策：' + str(score_box.get('pe_policy')))
    if score_box.get('conclusion'):
        lines.append('  • 裁決：' + str(score_box.get('conclusion')))
    return lines

def nick_trading_certainty_score(a: dict, evidence_status: str, revenue_signal: dict, structured: dict, risk_hits=None):
    risk_hits = risk_hits or []
    a = a or {}
    fj = a.get("fin_j") or {}
    cj = a.get("chip_j") or {}
    plan = a.get("plan") or {}
    action = str(a.get("action") or "")
    ps = str(a.get("price_status") or "")
    s = 45
    reasons = []
    if fj.get("report") == "通過":
        s += 12; reasons.append("財報通過")
    elif fj.get("report") in ["部分通過", "部分通過偏強"]:
        s += 6; reasons.append("財報部分通過")
    else:
        s -= 8; reasons.append("財報未通過")
    if fj.get("margin") == "有":
        s += 5; reasons.append("毛利率 / 營益率支撐")
    if fj.get("eps") in ["有", "部分有"]:
        s += 5; reasons.append("EPS 支撐")
    if fj.get("cashflow") in ["有", "普通"]:
        s += 3; reasons.append("現金流可用")

    # v19｜營運資金提示不能硬套所有商業模式。
    # 航運 / 金融 / 營建 / 生技不因一般製造業存貨/應收欄位自動扣分；
    # 只有警訊/硬傷才影響交易點確定性。
    _mk_for_certainty = ((a.get("val") or {}).get("model_key") or "")
    try:
        _fam_for_certainty = get_model_family_key(_mk_for_certainty)
    except Exception:
        _fam_for_certainty = ""
    _wc_verdict_for_certainty = str(fj.get("working_capital_verdict") or fj.get("inv_ar") or "")
    _wc_general_exempt = (
        _fam_for_certainty in ["freight_cycle", "financial_pb_roe", "asset_nav_real_estate", "biotech_event_milestone"]
        or _mk_for_certainty in [
            "shipping_freight_rebound", "financial_bank_core", "financial_holding_life_revaluation",
            "financial_general_core", "financial_brokerage_cycle", "real_estate_delivery_recognition",
            "biotech_commercial_drug_growth", "biotech_healthcare"
        ]
    )
    if _wc_verdict_for_certainty in ["警訊", "硬傷"]:
        if _wc_general_exempt:
            # 航運 / 金融 / 營建 / 生技不硬套製造業存貨應收；改回各自母模型風險。
            s -= 3; reasons.append("依產業風險保守追蹤")
        else:
            s -= 6; reasons.append("營運資金出現警訊")
    elif (not _wc_general_exempt) and fj.get("inv_ar") != "正常":
        s -= 4; reasons.append("存貨 / 應收需追蹤")
    elif _wc_general_exempt and _wc_verdict_for_certainty in ["需追蹤"]:
        reasons.append("依產業風險保守追蹤")

    if a.get("core") == "Yes":
        s += 6; reasons.append("Core 通過")
    if a.get("attack") == "Yes":
        s += 6; reasons.append("Attack 成立")
    elif a.get("attack") == "候選":
        reasons.append("Attack 候選，等回檔觸發")
        # 候選不等於正式進場點；交易點分數不得因基本面好而衝太高。
        s = min(s, 76)
    if a.get("focus") == "Yes":
        s += 8; reasons.append("主攻成立")
    if evidence_status == "已驗證":
        s += 8; reasons.append("外部證據已驗證")
    elif evidence_status == "部分驗證":
        s += 5; reasons.append("外部證據部分驗證")
    elif evidence_status == "初步線索":
        s += 2; reasons.append("外部證據初步線索")
    else:
        s -= 4; reasons.append("外部證據不足")
    if structured and structured.get("overall") == "部分驗證":
        s += 5; reasons.append("產品 / 稼動 / 出貨證據部分驗證")
    elif structured and structured.get("overall") == "初步線索":
        s += 2; reasons.append("產品 / 稼動 / 出貨有初步線索")
    rev_score = int((revenue_signal or {}).get("score") or 0)
    if rev_score >= 80:
        s += 8; reasons.append("下月營收可信度高")
    elif rev_score >= 70:
        s += 6; reasons.append("下月營收可信度中高")
    elif rev_score >= 60:
        s += 3; reasons.append("下月營收可信度中")
    elif rev_score < 50:
        s -= 5; reasons.append("下月營收可信度偏低")
    try:
        chip_score = float(cj.get("score") or 0)
    except Exception:
        chip_score = 0
    if chip_score >= 2:
        s += 5; reasons.append("籌碼推進力偏多")
    elif chip_score < 0:
        s -= 4; reasons.append("籌碼偏弱")
    if ps in ["低估", "偏低估", "合理"]:
        s += 6; reasons.append("價格位置尚可")
    elif ps in ["偏貴 / 已提前反映未來", "高溢價區", "明顯跑太前面"]:
        s -= 8; reasons.append("股價已先買未來")
    elif ps in ["區間夾層", "區間重疊"]:
        s -= 3; reasons.append("估值區間需人工複核")
    if any(x in action for x in ["不追", "等回檔", "空手等回檔"]):
        s -= 4; reasons.append("買點甜度不足，偏等回檔")
    if any(x in action for x in ["右側", "突破"]):
        reasons.append("若已突破，等回測確認")
    if risk_hits:
        s -= min(10, len(risk_hits) * 3)
        reasons.append("風險詞扣分：" + "、".join(risk_hits[:4]))
    try:
        if isinstance(plan.get("num"), dict):
            nums = plan.get("num")
            cur = nums.get("current")
            new_hi = nums.get("new_high")
            shallow_hi = nums.get("shallow_high")
            right_px = nums.get("right") or nums.get("key_pressure")
            entry = nums.get("shallow_high") or nums.get("new_high")
            stop = nums.get("wrong") or nums.get("stop")
            target = nums.get("wave") or nums.get("short")

            # v19｜交易點確定性要看「現在是否在買點」，不是只看 Core/Attack。
            # 高於小倉區但尚未突破右側，不能給太高確定性。
            if cur is not None and shallow_hi is not None and cur > shallow_hi * 1.005:
                s -= 8; reasons.append("現價高於小倉舒適區")
                if right_px is None or cur < right_px:
                    s = min(s, 76)
            elif cur is not None and new_hi is not None and cur > new_hi * 1.005:
                s -= 3; reasons.append("現價高於主買區，需小倉或突破後回測確認")

            rr = calc_rr(entry, stop, target) if entry and stop and target else None
            if rr is not None:
                if rr >= 2.5:
                    s += 5; reasons.append(f"風報比約 {rr:.1f}")
                elif rr < 1.5:
                    s -= 4; reasons.append(f"風報比偏低約 {rr:.1f}")
    except Exception:
        pass
    if evidence_status in ["資料不足", "不適用"] and s > 72:
        s = 72
    if ps in ["高溢價區", "明顯跑太前面"] and s > 78:
        s = 78
    if a.get("attack") == "候選" and s > 76:
        s = 76
    if any(x in action for x in ["等回檔", "不追", "突破後回測"]) and a.get("attack") != "Yes" and s > 76:
        s = 76

    # v199｜法醫對齊：基本面強但籌碼偏賣 / Focus No / 觀察型小倉，不得給 80+ 高確定性。
    try:
        _chip_text_limit = str(cj.get("text") or "")
        _chip_score_limit = float(cj.get("score") or 0)
    except Exception:
        _chip_text_limit, _chip_score_limit = "", 0
    _observe_small_lot_limit = (
        (a.get("focus") != "Yes")
        and (
            any(k in action for k in ["小倉", "觀察", "不追"])
            or any(k in _chip_text_limit for k in ["賣超", "偏賣", "賣壓", "轉弱"])
            or _chip_score_limit < 0
        )
    )
    if _observe_small_lot_limit and s > 72:
        s = 72
        reasons.append("法醫限制：籌碼 / 位置未轉強，只能觀察型小倉")
    if a.get("attack") == "Yes" and a.get("focus") != "Yes" and any(k in action for k in ["小倉", "觀察", "不追"]) and s > 72:
        s = 72
        reasons.append("Attack Yes＝1–2週找買點；尚非主倉攻擊點，交易點確定性降為中高")

    # fix77｜交易點確定性分流：
    # 記憶體製造景氣反轉可有很高「基本面確定性」，但若 Attack / Focus 未成立，
    # 交易點確定性不得因 Core Yes 直接衝到 90+。
    _memory_trade_point_limited = False
    try:
        _mk_for_certainty = ((a.get("val") or {}).get("model_key") or "")
        if _mk_for_certainty == "memory_manufacturing_cycle_rerating" and a.get("focus") != "Yes":
            _memory_trade_point_limited = True
            # 記憶體製造可有高基本面確定性，但只要不是 Focus / 主倉點，交易點分數要降噪。
            # 即使回檔型 Attack 成立，也只能代表小倉觀察，不等於重押確定性。
            if str(a.get("action") or "").find("小倉") >= 0 or str(a.get("action") or "").find("不追") >= 0:
                if s > 78:
                    s = 78
                reasons.append("週期型 Core 只適合小倉觀察，非重押交易點")
            elif a.get("attack") != "Yes":
                if s > 78:
                    s = 78
                reasons.append("基本面確定性高，但 Attack 未成立，交易點需確認")
    except Exception:
        pass
    s = int(max(20, min(92, round(s))))
    if s >= 82:
        label, conclusion = "高", "確定性高，但仍要看買點；若已高於舒適區，不代表可追重倉。"
    elif s >= 72:
        label, conclusion = "中高", "具交易把握度，適合等回檔小倉 / 不追高，不宜無腦追。"
    elif s >= 60:
        label, conclusion = "中", "有條件，但仍需關鍵證據或買點確認。"
    elif s >= 50:
        label, conclusion = "普通", "只適合觀察型小倉，等待更多驗證。"
    else:
        label, conclusion = "低", "確定性不足，本金先保守。"
    try:
        if _memory_trade_point_limited:
            conclusion = "公司可收編，但交易點仍需等回檔小倉 / 不追高。"
    except Exception:
        pass
    dedup = []
    for r in reasons:
        if r not in dedup:
            dedup.append(r)
    return {"score": s, "label": label, "reasons": dedup[:9], "conclusion": conclusion}

def build_nick_evidence_box(stock, name, a, rev, fin, inst, news_rows=None, manual_text="", uploaded_text="", uploaded_notes=None):
    """建立子模組證據強度。只評估證據，不直接改 Core / Attack / Focus。"""
    val = (a or {}).get("val") or {}
    model_key = val.get("model_key") or val.get("model") or "default_pe_check"
    rule = nick_get_evidence_rule_for_model(model_key)

    # v47-7：模組適配只採用與股票名稱 / 代號強綁定的新聞，避免抓到頁面雜訊或不相關新聞。
    news_text = _nick_news_rows_to_text_bound(news_rows, stock=stock, name=name)
    combined = "\n".join([str(news_text or ""), str(manual_text or ""), str(uploaded_text or "")]).strip()

    fj = (a or {}).get("fin_j") or {}
    rr = (a or {}).get("rerating") or {}
    keyword_hits = nick_keyword_hits(combined, rule.get("keywords", []))
    risk_hits = nick_keyword_hits(combined, NICK_EVIDENCE_RISK_KEYWORDS)
    sources = nick_detect_evidence_sources(combined, uploaded_notes)
    module_adaptation = nick_module_adaptation_check(
        stock,
        name,
        a,
        rev=rev,
        fin=fin,
        news_rows=news_rows,
        manual_text=manual_text,
        uploaded_text=uploaded_text,
    )

    # 財報硬資料分數
    financial_checks = []
    if fj.get("report") == "通過":
        financial_checks.append("財報通過")
    elif fj.get("report") in ["部分通過", "部分通過偏強"]:
        financial_checks.append("財報部分通過")
    if fj.get("revenue_to_eps") in ["有", "部分有"]:
        financial_checks.append("營收有轉 EPS")
    if fj.get("margin") == "有":
        financial_checks.append("毛利率 / 營益率支撐")
    elif fj.get("margin") == "普通":
        financial_checks.append("三率普通")
    if fj.get("eps") in ["有", "部分有"]:
        financial_checks.append("EPS 有支撐")
    if fj.get("cashflow") in ["有", "普通"]:
        financial_checks.append("現金流可用")
    if rr.get("verdict") in ["成立", "部分成立"]:
        financial_checks.append(f"估值重評{rr.get('verdict')}")

    fin_score = min(len(financial_checks), 6)
    kw_score = min(len(keyword_hits), 4)
    risk_penalty = min(len(risk_hits), 2)
    total = fin_score + kw_score - risk_penalty

    if fin_score >= 5 and kw_score >= 2 and risk_penalty == 0:
        status = "已驗證"
    elif fin_score >= 4 and kw_score >= 1:
        status = "部分驗證"
    elif fin_score >= 3 or kw_score >= 1:
        status = "初步線索"
    else:
        status = "資料不足"

    evidence_bits = []
    if financial_checks:
        evidence_bits.append("財報：" + "、".join(financial_checks[:4]))
    if keyword_hits:
        evidence_bits.append("關鍵字：" + "、".join(keyword_hits[:8]))
    if not evidence_bits:
        evidence_bits.append("尚未看到足夠的新聞 / 公告 / 法說證據")

    gap = rule.get("gap", "仍需後續資料驗證。")
    if risk_hits:
        gap += "；風險詞：" + "、".join(risk_hits[:6])

    decision = "可作為子模組與估值重評佐證，但不直接決定 Core Yes。"
    if status in ["資料不足", "初步線索"]:
        decision = "只能當觀察線索，不能因題材直接升 Core / Focus。"
    elif status == "已驗證":
        decision = "證據較完整，可支撐估值重評；但是否 Core 仍交給法醫硬門檻。"

    structured = nick_structured_evidence_extract(combined, model_key)
    structured_summary = nick_structured_evidence_summary(structured)
    generic_news_catalyst = nick_generic_news_catalyst_classify(combined, structured=structured, model_key=model_key)
    try:
        _industry_for_path = (a.get("meta") or {}).get("industry_category", "") if isinstance(a.get("meta"), dict) else ""
    except Exception:
        _industry_for_path = ""
    sector_catalyst_path = nick_sector_catalyst_playbook(a, generic_news_catalyst, structured, model_key=model_key, industry_category=_industry_for_path)

    revenue_signal = nick_next_month_revenue_signal_score(
        rev,
        fin,
        inst,
        model_key,
        status,
        keyword_hits=keyword_hits,
        risk_hits=risk_hits,
        combined_text=combined,
    )
    rerating_score_box = nick_rerating_score_engine(
        a,
        generic_news_catalyst,
        sector_catalyst_path,
        structured,
        revenue_signal=revenue_signal,
        inst=inst,
        fin=fin,
        risk_hits=risk_hits,
    )
    _rr_components = []
    try:
        for _c in (rerating_score_box.get('components') or [])[:5]:
            if isinstance(_c, dict):
                _rr_components.append(f"{_c.get('label', '')}{_c.get('score', 0)}")
    except Exception:
        _rr_components = []
    _rr_component_text = "、".join([x for x in _rr_components if x.strip()]) or "資料不足"
    rerating_score_line = (
        f"【估值重評分數】{rerating_score_box['score']}分｜{rerating_score_box['label']}\n"
        f"拆解：{_rr_component_text}\n"
        f"依據：{'、'.join(rerating_score_box.get('reasons', [])[:5]) if rerating_score_box.get('reasons') else '資料不足'}\n"
        f"裁決：{rerating_score_box['conclusion']}"
    )
    revenue_line = (
        f"【下月營收成長可信度】{revenue_signal['score']}分｜{revenue_signal['label']}\n"
        f"依據：{'、'.join(revenue_signal.get('reasons', [])[:5]) if revenue_signal.get('reasons') else '資料不足'}\n"
        f"裁決：{revenue_signal['conclusion']}"
    )

    trade_certainty = nick_trading_certainty_score(a, status, revenue_signal, structured, risk_hits=risk_hits)
    trade_line = (
        f"【交易點確定性】{trade_certainty['score']}分｜{trade_certainty['label']}\n"
        f"依據：{'、'.join(trade_certainty.get('reasons', [])[:5]) if trade_certainty.get('reasons') else '資料不足'}\n"
        f"裁決：{trade_certainty['conclusion']}"
    )

    # fix68｜子模組驗證區塊減脂：
    # 手機畫面只顯示「下月營收成長可信度」與「交易點確定性」。
    # 詳細證據改放證據整理表與完整報告，不再塞一大段文字。
    module_adaptation_line = nick_module_adaptation_quick_text(module_adaptation)
    quick_text = (
        "【內部子模組參考】\n"
        f"{rerating_score_line}\n\n"
        f"{revenue_line}\n\n"
        f"{trade_line}"
        + ("\n\n" + module_adaptation_line if module_adaptation_line else "")
    )

    _structured_detail_lines = []
    for _item in (structured.get('items') or []):
        if _item.get('status') != '資料不足':
            _structured_detail_lines.append(
                f"- {_item.get('label')}：{_item.get('status')}｜命中：{'、'.join(_item.get('hits', [])[:5]) or '無'}｜數字：{'、'.join(_item.get('values', [])[:4]) or '未揭露'}"
            )
    if not _structured_detail_lines:
        _structured_detail_lines.append("- 尚未萃取到明確產品 / 稼動 / 出貨 / 認證證據。")

    detail_text = (
        f"子模組：{rule['display']}\n"
        f"證據模式：{rule.get('rule_type', '專用規則')}\n"
        f"證據強度：{status}（分數 {total}；財報 {fin_score} / 關鍵字 {kw_score} / 風險扣分 {risk_penalty}）\n"
        f"資料來源：{'、'.join(sources)}\n"
        f"證據：{'；'.join(evidence_bits)}\n"
        f"缺口：{gap}\n"
        f"裁決影響：{decision}\n\n"
        f"【通用新聞催化分類】\n" + "\n".join(nick_generic_catalyst_detail_lines(generic_news_catalyst)) + "\n\n"
        f"【族群催化路徑】\n" + "\n".join(nick_sector_catalyst_detail_lines(sector_catalyst_path)) + "\n\n"
        f"【估值重評分數】\n" + "\n".join(nick_rerating_score_detail_lines(rerating_score_box)) + "\n\n"
        f"【結構化證據萃取】\n" + "\n".join(_structured_detail_lines) + "\n\n"

        f"估值重評分數：{rerating_score_box['score']}分｜{rerating_score_box['label']}｜{rerating_score_box['conclusion']}\n"
        f"估值重評依據：{'、'.join(rerating_score_box.get('reasons', []))}\n\n"
        f"下月營收成長可信度：{revenue_signal['score']}分｜{revenue_signal['label']}｜{revenue_signal['conclusion']}\n"
        f"營收可信度依據：{'、'.join(revenue_signal.get('reasons', []))}\n\n"
        f"交易點確定性：{trade_certainty['score']}分｜{trade_certainty['label']}｜{trade_certainty['conclusion']}\n"
        f"交易點確定性依據：{'、'.join(trade_certainty.get('reasons', []))}\n\n"
        f"{nick_module_adaptation_detail_text(module_adaptation)}\n\n"
        f"注意：子模組只決定分析框架；Core Yes / No 仍由財報、EPS、三率、現金流、估值與籌碼法醫判斷。"
    )

    return {
        "model_key": model_key,
        "display": rule["display"],
        "status": status,
        "score": total,
        "quick_text": quick_text,
        "detail_text": detail_text,
        "sources": sources,
        "hits": keyword_hits,
        "risk_hits": risk_hits,
        "financial_checks": financial_checks,
        "structured_evidence": structured,
        "generic_news_catalyst": generic_news_catalyst,
        "sector_catalyst_path": sector_catalyst_path,
        "rerating_score": rerating_score_box,
        "revenue_signal": revenue_signal,
        "trade_certainty": trade_certainty,
        "module_adaptation": module_adaptation,
        "uploaded_notes": uploaded_notes or [],
    }


def nick_insert_evidence_into_quick_read(quick_read: str, evidence_box: dict) -> str:
    if not evidence_box or not evidence_box.get("quick_text"):
        return quick_read
    ev = evidence_box.get("quick_text", "").strip()
    if not ev:
        return quick_read
    marker = "\n\n【新聞】"
    if marker in quick_read:
        return quick_read.replace(marker, "\n\n" + ev + marker, 1)
    return quick_read.rstrip() + "\n\n" + ev + "\n"


def nick_append_evidence_to_report(report: str, evidence_box: dict) -> str:
    if not evidence_box or not evidence_box.get("detail_text"):
        return report
    return report.rstrip() + "\n\n━━━━━━━━━━\n【子模組證據強度｜新聞 / 法說 / 公告】\n" + evidence_box.get("detail_text", "") + "\n"



