def _nick_auto_evidence_today() -> str:
    return datetime.now().strftime("%Y%m%d")


def _nick_auto_evidence_now_iso() -> str:
    return datetime.now().isoformat(timespec="seconds")


def _nick_auto_evidence_safe_key(stock: str, name: str, model_key: str) -> str:
    raw = f"{stock}_{name}_{model_key}".strip("_") or "unknown"
    raw = re.sub(r"[^0-9A-Za-z_\-\u4e00-\u9fff]+", "_", raw)
    raw = re.sub(r"_+", "_", raw).strip("_")
    return raw[:96] or "unknown"


def _nick_auto_evidence_cache_path(stock: str, name: str, model_key: str) -> str:
    today = _nick_auto_evidence_today()
    key = _nick_auto_evidence_safe_key(stock, name, model_key)
    return os.path.join(NICK_AUTO_EVIDENCE_CACHE_DIR, f"{today}_{key}.json")


def nick_cleanup_old_auto_evidence_cache(keep_today: str = None) -> None:
    """只保留今天的外部證據快取，避免 Replit 檔案越堆越多。"""
    try:
        today = keep_today or _nick_auto_evidence_today()
        os.makedirs(NICK_AUTO_EVIDENCE_CACHE_DIR, exist_ok=True)
        for fn in os.listdir(NICK_AUTO_EVIDENCE_CACHE_DIR):
            if not fn.endswith(".json"):
                continue
            if not fn.startswith(today + "_"):
                try:
                    os.remove(os.path.join(NICK_AUTO_EVIDENCE_CACHE_DIR, fn))
                except Exception:
                    pass
    except Exception:
        pass


def nick_read_auto_evidence_cache(stock: str, name: str, model_key: str, ttl_seconds: int = None, allow_stale: bool = False):
    """讀今日外部證據快取。過期時預設不回傳；allow_stale=True 可當搜尋失敗備援。"""
    try:
        ttl = int(ttl_seconds or NICK_AUTO_EVIDENCE_CACHE_TTL_SECONDS)
        path = _nick_auto_evidence_cache_path(stock, name, model_key)
        if not os.path.exists(path):
            return None
        with open(path, "r", encoding="utf-8") as f:
            data = _json.load(f)
        updated_at = str(data.get("updated_at") or "")
        updated_dt = datetime.fromisoformat(updated_at) if updated_at else None
        age = (datetime.now() - updated_dt).total_seconds() if updated_dt else 10**9
        if age > ttl and not allow_stale:
            return None
        data["cache_age_seconds"] = age
        data["cache_path"] = path
        return data
    except Exception:
        return None


def nick_write_auto_evidence_cache(stock: str, name: str, model_key: str, evidence_text: str, notes, results) -> None:
    """寫入今日外部證據快取。只存搜尋證據，不存即時行情 / 財報硬資料。"""
    try:
        today = _nick_auto_evidence_today()
        nick_cleanup_old_auto_evidence_cache(today)
        os.makedirs(NICK_AUTO_EVIDENCE_CACHE_DIR, exist_ok=True)
        path = _nick_auto_evidence_cache_path(stock, name, model_key)
        payload = {
            "cache_version": "v63_auto_evidence_cache",
            "date": today,
            "updated_at": _nick_auto_evidence_now_iso(),
            "stock": str(stock or ""),
            "name": str(name or ""),
            "model_key": str(model_key or ""),
            "evidence_text": evidence_text or "",
            "notes": list(notes or []),
            "results": list(results or []),
            "scan_modules": NICK_AUTO_SCAN_MODULES,
        }
        with open(path, "w", encoding="utf-8") as f:
            _json.dump(payload, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def nick_auto_evidence_cache_note(cached: dict) -> str:
    try:
        updated_at = str(cached.get("updated_at") or "")
        t = updated_at[11:16] if len(updated_at) >= 16 else updated_at
        age_min = int((cached.get("cache_age_seconds") or 0) // 60)
        return f"今日證據快取：使用 {t} 快取（約 {age_min} 分鐘前），未重複搜尋外部證據。"
    except Exception:
        return "今日證據快取：已使用快取，未重複搜尋外部證據。"

