def nick_auto_search_queries(stock: str, name: str, model_key: str):
    code = str(stock or "").strip()
    nm = str(name or "").strip()
    label = " ".join([x for x in [code, nm] if x]).strip() or code or nm
    kws = nick_model_auto_search_keywords(model_key)
    kw_short = " ".join(kws[:4])
    return [
        f"{label} {kw_short} 法說 PDF",
        f"{label} {kw_short} 月營收 財報 毛利率 EPS",
        f"{label} {kw_short} 公告 重大訊息",
        f"site:mops.twse.com.tw {label} 法說會 PDF",
        f"site:mops.twse.com.tw {label} 月營收 財務報告",
        f"{label} 投資人關係 法說會 簡報 PDF",
    ]


def nick_clean_search_url(u: str):
    """清理搜尋結果網址，處理 DuckDuckGo uddg 轉址。"""
    if not u:
        return ""
    try:
        from urllib.parse import urlparse, parse_qs, unquote
        parsed = urlparse(u)
        qs = parse_qs(parsed.query)
        if "uddg" in qs and qs["uddg"]:
            return unquote(qs["uddg"][0])
    except Exception:
        pass
    return str(u).strip()


@st.cache_data(ttl=1800, show_spinner=False)
def nick_google_news_rss_search(query: str, limit: int = 4):
    """Google News RSS：比較穩，用於新聞線索。"""
    try:
        from urllib.parse import quote_plus
        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=zh-TW&gl=TW&ceid=TW:zh-Hant"
        r = requests.get(url, timeout=12, headers={"User-Agent": "Mozilla/5.0"})
        r.raise_for_status()
        root = ET.fromstring(r.content)
        out = []
        for item in root.findall(".//item")[:limit]:
            title = item.findtext("title") or ""
            link = item.findtext("link") or ""
            pub = item.findtext("pubDate") or ""
            if link:
                out.append({"title": title, "url": link, "source": "GoogleNewsRSS", "date": pub})
        return out
    except Exception:
        return []


@st.cache_data(ttl=1800, show_spinner=False)
def nick_duckduckgo_html_search(query: str, limit: int = 5):
    """DuckDuckGo HTML 搜尋：用於 PDF / 公司 IR / MOPS 搜尋線索。"""
    try:
        from urllib.parse import quote_plus
        url = "https://duckduckgo.com/html/?q=" + quote_plus(query)
        r = requests.get(url, timeout=12, headers={"User-Agent": "Mozilla/5.0"})
        r.raise_for_status()
        html = r.text
        urls = []
        for m in re.finditer(r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', html, flags=re.I | re.S):
            href = _html.unescape(m.group(1))
            title = re.sub(r"<.*?>", "", m.group(2))
            href = nick_clean_search_url(href)
            if href and href.startswith("http") and href not in [x["url"] for x in urls]:
                urls.append({"title": _html.unescape(title).strip(), "url": href, "source": "DuckDuckGo", "date": ""})
            if len(urls) >= limit:
                break
        if not urls:
            for m in re.finditer(r'https?://[^"\']+', html):
                href = nick_clean_search_url(_html.unescape(m.group(0)))
                if href.startswith("http") and "duckduckgo" not in href and href not in [x["url"] for x in urls]:
                    urls.append({"title": href[:80], "url": href, "source": "DuckDuckGo", "date": ""})
                if len(urls) >= limit:
                    break
        return urls
    except Exception:
        return []


def nick_auto_search_result_candidates(stock: str, name: str, model_key: str, max_results: int = 8):
    queries = nick_auto_search_queries(stock, name, model_key)
    found = []
    seen = set()
    for q in queries[:6]:
        # 新聞
        for item in nick_google_news_rss_search(q, limit=3):
            u = item.get("url", "")
            if u and u not in seen:
                item["query"] = q
                found.append(item)
                seen.add(u)
        # PDF / 官方 / IR
        for item in nick_duckduckgo_html_search(q, limit=3):
            u = item.get("url", "")
            if u and u not in seen:
                item["query"] = q
                found.append(item)
                seen.add(u)
        if len(found) >= max_results:
            break
    return found[:max_results]


def nick_one_click_auto_search_evidence(stock: str, name: str, model_key: str, max_results: int = 6):
    """全自動外部證據搜尋。

    v63：加入今日證據快取。
    - 同一天同一檔 + 同一估值模型，2 小時內直接讀快取。
    - 只快取新聞 / 法說 / PDF / 公告 / 財報線索等外部證據。
    - 不快取即時價、K線、法人、月營收、財報硬資料。
    """
    cached = nick_read_auto_evidence_cache(
        stock,
        name,
        model_key,
        ttl_seconds=NICK_AUTO_EVIDENCE_CACHE_TTL_SECONDS,
        allow_stale=False,
    )
    if cached:
        notes = [nick_auto_evidence_cache_note(cached)] + list(cached.get("notes") or [])
        return cached.get("evidence_text", "") or "", notes, list(cached.get("results") or [])

    candidates = nick_auto_search_result_candidates(stock, name, model_key, max_results=max_results)
    texts = []
    notes = []
    fetched_results = []
    for idx, item in enumerate(candidates, start=1):
        url = item.get("url", "")
        title = item.get("title", "") or url
        body, note = nick_fetch_single_url_evidence(url, max_chars=8000)
        short_title = title if len(title) <= 42 else title[:39] + "..."
        notes.append(f"自動{idx}：{note}｜{short_title}")
        fetched_results.append({
            "title": title,
            "url": url,
            "source": item.get("source", ""),
            "query": item.get("query", ""),
            "note": note,
            "chars": len(body or ""),
        })
        if body:
            texts.append(f"\n--- 自動搜尋{idx}｜{title}｜{url} ---\n{body}")

    evidence_text = "\n".join(texts).strip()

    # 若本次搜尋完全失敗，但今天有舊快取，回退使用舊快取，避免主分析卡死或空白。
    if not evidence_text and not fetched_results:
        stale = nick_read_auto_evidence_cache(stock, name, model_key, allow_stale=True)
        if stale:
            stale_notes = ["外部證據搜尋失敗，改用今日舊快取。", nick_auto_evidence_cache_note(stale)] + list(stale.get("notes") or [])
            return stale.get("evidence_text", "") or "", stale_notes, list(stale.get("results") or [])

    nick_write_auto_evidence_cache(stock, name, model_key, evidence_text, notes, fetched_results)
    if notes:
        notes = ["今日證據快取：本次已重新搜尋並寫入快取。"] + notes
    else:
        notes = ["今日證據快取：本次已重新搜尋，但未抓到有效外部證據。"]
    return evidence_text, notes, fetched_results


def nick_revenue_signal_label(score: int):
    if score >= 80:
        return "高"
    if score >= 70:
        return "中高"
    if score >= 60:
        return "中"
    if score >= 50:
        return "普通"
    return "低"


def nick_next_month_revenue_signal_score(rev, fin, inst, model_key: str, evidence_status: str, keyword_hits=None, risk_hits=None, combined_text: str = ""):
    """用財報硬資料 + 搜尋證據，評估下個月營收成長可信度。不是營收預測保證。"""
    keyword_hits = keyword_hits or []
    risk_hits = risk_hits or []
    s = 50
    reasons = []

    yoy = rev.get("yoy") if isinstance(rev, dict) else None
    mom = rev.get("mom") if isinstance(rev, dict) else None
    ytd_yoy = rev.get("ytd_yoy") if isinstance(rev, dict) else None
    yoy_list = rev.get("yoy_list") if isinstance(rev, dict) else []

    if yoy is not None:
        if yoy >= 50:
            s += 14; reasons.append("月營收年增 >50%")
        elif yoy >= 30:
            s += 11; reasons.append("月營收年增 >30%")
        elif yoy >= 10:
            s += 7; reasons.append("月營收雙位數年增")
        elif yoy < 0:
            s -= 8; reasons.append("月營收年減")
    if mom is not None:
        if mom >= 10:
            s += 6; reasons.append("月營收月增明顯")
        elif mom >= 0:
            s += 2; reasons.append("月營收月增")
        elif mom <= -15:
            s -= 6; reasons.append("月營收月減偏大")
    if ytd_yoy is not None:
        if ytd_yoy >= 30:
            s += 8; reasons.append("累計營收年增強")
        elif ytd_yoy >= 10:
            s += 4; reasons.append("累計營收年增")
        elif ytd_yoy < 0:
            s -= 5; reasons.append("累計營收年減")

    try:
        clean_yoys = [float(x) for x in (yoy_list or []) if x is not None]
        if len(clean_yoys) >= 3:
            if clean_yoys[-1] > clean_yoys[-2] > clean_yoys[-3]:
                s += 5; reasons.append("近三月年增率連續升溫")
            elif clean_yoys[-1] < clean_yoys[-2] < clean_yoys[-3]:
                s -= 5; reasons.append("近三月年增率連續降溫")
    except Exception:
        pass

    gm = fin.get("gross_margin") if isinstance(fin, dict) else None
    opm = fin.get("operating_margin") if isinstance(fin, dict) else None
    eps = fin.get("eps") if isinstance(fin, dict) else None
    if gm is not None and gm >= 25:
        s += 4; reasons.append("毛利率具支撐")
    if opm is not None and opm >= 10:
        s += 4; reasons.append("營益率具支撐")
    if eps is not None and eps > 0:
        s += 4; reasons.append("EPS 為正")

    if evidence_status == "已驗證":
        s += 8; reasons.append("子模組證據已驗證")
    elif evidence_status == "部分驗證":
        s += 5; reasons.append("子模組證據部分驗證")
    elif evidence_status == "初步線索":
        s += 2; reasons.append("子模組有初步線索")
    elif evidence_status in ["資料不足", "不適用"]:
        s -= 3; reasons.append("外部證據不足")

    # 產品 / 稼動 / 訂單 / 放量相關關鍵字加分
    positive_hits = nick_keyword_hits(combined_text, NICK_EVIDENCE_SIGNAL_KEYWORDS)
    if positive_hits:
        add = min(len(positive_hits), 8)
        s += add
        reasons.append("外部證據命中：" + "、".join(positive_hits[:5]))
    if risk_hits:
        s -= min(len(risk_hits) * 4, 12)
        reasons.append("風險詞：" + "、".join(risk_hits[:5]))

    if isinstance(inst, dict):
        net20 = inst.get("net20_lot")
        pos_days = inst.get("positive_days_20")
        if net20 is not None and net20 > 0:
            s += 3; reasons.append("法人近20日偏買")
        if pos_days is not None and pos_days >= 12:
            s += 2; reasons.append("法人買進天數偏多")

    # 若證據不足，分數上限不能太高
    if evidence_status in ["資料不足", "不適用"] and s > 68:
        s = 68
    if risk_hits and s > 72:
        s = 72
    s = int(max(25, min(90, round(s))))

    label = nick_revenue_signal_label(s)
    if s >= 75:
        conclusion = "下月營收續強可信度偏高，但仍需等公告驗證。"
    elif s >= 60:
        conclusion = "有續強條件，但還不能當成確定成長。"
    elif s >= 50:
        conclusion = "只能觀察，缺少足夠把握。"
    else:
        conclusion = "目前證據不足或有降溫風險。"

    return {
        "score": s,
        "label": label,
        "reasons": reasons[:8],
        "conclusion": conclusion,
    }


