def _render_change_reminder_section():
    # ── 變化提醒 ──────────────────────────────
    _prev_snap = load_analysis_history().get(stock)
    _curr_snap = save_analysis_snapshot(stock, name, a, current_zone)
    with st.expander("📋 變化提醒｜和上次比", expanded=False):
        if _prev_snap is None:
            st.info("第一次分析，尚無前次紀錄可比較。")
        else:
            _prev_time = _prev_snap.get("analysis_time", "")
            st.caption(f"上次分析時間：{_prev_time}")
            _changes = compare_snapshots(_prev_snap, _curr_snap)
            if not _changes:
                st.success("本次與前次分析相比，核心狀態沒有明顯改變。")
            else:
                _risk_worse = {
                    "fin_report": ["通過 → 不通過", "部分通過 → 不通過", "通過 → 部分通過"],
                    "trend_status": ["趨勢轉弱", "趨勢反轉", "趨勢鈍化"],
                    "fin_quality": ["高 → 中", "高 → 低", "中 → 低"],
                }

                def _is_worse(field, p, c):
                    if field == "trend_status" and c in ["趨勢轉弱", "趨勢反轉"]:
                        return True
                    if (
                        field == "fin_report"
                        and p in ["通過"]
                        and c in ["不通過", "部分通過"]
                    ):
                        return True
                    if field == "fin_quality" and p == "高" and c in ["中", "低"]:
                        return True
                    return False

                rows = []
                for label, p, c in _changes:
                    field = next(
                        (
                            f
                            for f, l in [
                                ("fin_report", "財報裁決"),
                                ("trend_status", "趨勢變化"),
                                ("fin_quality", "財務品質"),
                            ]
                            if l == label
                        ),
                        "",
                    )
                    worse = _is_worse(field, p, c)
                    tag = (
                        " ⚠️"
                        if worse
                        else " ✅"
                        if label
                        in ["最終動作", "Core 狀態", "金庫等級", "估值重評", "趨勢變化"]
                        else ""
                    )
                    rows.append({"項目": label + tag, "前次": p, "本次": c})
                st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)


def _render_internal_evidence_section():
    with st.expander("🔒 進階證據檢查", expanded=False):
        if nick_private_gate("進階證據檢查", "internal_evidence_breakdown"):
            _ev = a.get("evidence_box", {}) or {}
            if _ev.get("quick_text"):
                # fix68｜只顯示圈起來的兩個分數，不再顯示冗長來源文字。
                st.markdown(_ev.get("quick_text", "").replace("\n", "\n\n"))

                _structured = (_ev.get("structured_evidence") or {}).get("items", [])
                _structured_rows = []
                for x in (_structured or []):
                    if x.get("status") == "資料不足":
                        continue
                    _evidence_text = "、".join((x.get("values") or [])[:3])
                    if not _evidence_text:
                        _evidence_text = "、".join((x.get("hits") or [])[:5])
                    if not _evidence_text:
                        _evidence_text = "初步線索"
                    _structured_rows.append({
                        "項目": x.get("label"),
                        "狀態": x.get("status"),
                        "證據": _evidence_text,
                    })

                if _structured_rows:
                    st.markdown("#### 證據整理表")
                    st.dataframe(pd.DataFrame(_structured_rows), use_container_width=True, hide_index=True)
                else:
                    st.caption("證據整理表：目前尚未萃取到明確產品 / 稼動率 / 出貨 / 認證線索。")
            else:
                st.caption("本次尚未產生外部證據分數，請確認是否有完成自動搜尋或手動補充證據。")



