def _render_quick_share_section():
    # ── 快速判讀分享文：放在變化提醒下方，方便一分析完先複製分享 ─────────
    with st.expander("⚡ 快速判讀｜可分享", expanded=False):
        st.caption("可直接複製傳 LINE / 發文。一般使用者最容易看懂，放在結論後面。")

        # V8.5.12：手機版一鍵複製。若瀏覽器限制 Clipboard API，會自動改用選取複製備援。
        _copy_payload = _json.dumps(quick_read, ensure_ascii=False).replace("</", "<\\/")
        components.html(
            f"""
            <div style="display:flex;align-items:center;gap:10px;width:100%;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;">
              <button id="copyQuickReadBtn"
                style="
                  width:100%;
                  padding:13px 16px;
                  border-radius:12px;
                  border:1px solid #3b82f6;
                  background:#17324d;
                  color:#e5f1ff;
                  font-size:17px;
                  font-weight:700;
                  cursor:pointer;
                ">
                📋 複製快速判讀內文
              </button>
              <span id="copyQuickReadStatus"
                style="min-width:72px;color:#9ca3af;font-size:14px;"></span>
            </div>
            <textarea id="copyQuickReadHidden"
              style="position:fixed;left:-9999px;top:-9999px;width:1px;height:1px;"></textarea>
            <script>
            const quickReadText = {_copy_payload};
            const btn = document.getElementById("copyQuickReadBtn");
            const status = document.getElementById("copyQuickReadStatus");
            const hidden = document.getElementById("copyQuickReadHidden");

            async function copyQuickRead() {{
              try {{
                if (navigator.clipboard && window.isSecureContext) {{
                  await navigator.clipboard.writeText(quickReadText);
                }} else {{
                  hidden.value = quickReadText;
                  hidden.focus();
                  hidden.select();
                  document.execCommand("copy");
                }}
                status.textContent = "已複製";
                btn.textContent = "✅ 已複製，可貼到 LINE";
                setTimeout(() => {{
                  status.textContent = "";
                  btn.textContent = "📋 複製快速判讀內文";
                }}, 1800);
              }} catch (err) {{
                hidden.value = quickReadText;
                hidden.focus();
                hidden.select();
                try {{
                  document.execCommand("copy");
                  status.textContent = "已複製";
                  btn.textContent = "✅ 已複製，可貼到 LINE";
                }} catch (e) {{
                  status.textContent = "複製失敗";
                  btn.textContent = "請長按下方文字框複製";
                }}
              }}
            }}

            btn.addEventListener("click", copyQuickRead);
            </script>
            """,
            height=62,
        )

        st.text_area(
            "可複製快速判讀",
            value=quick_read,
            height=430,
        )
        st.download_button(
            "下載快速判讀 TXT",
            data=quick_read,
            file_name=f"{stock}_{name}_快速判讀.txt",
            mime="text/plain",
            use_container_width=True,
        )




