def _nick_simple_insufficient_reason_for_card(_a, _zone_text=""):
    """總覽卡用：若最終動作是「不買 / 條件不足」，把原因壓成小白看得懂的一句。"""
    try:
        _reasons = []
        _fj = (_a.get("fin_j", {}) or {}) if isinstance(_a, dict) else {}
        _rr = (_a.get("rerating", {}) or {}) if isinstance(_a, dict) else {}
        _diag = (_a.get("_diag", {}) or {}) if isinstance(_a, dict) else {}
        _core = str(_a.get("_forensic_core_effective") or _a.get("core", "") or "")
        _attack = str(_a.get("attack", "") or "")
        _focus = str(_a.get("focus", "") or "")
        _core_status = str(_a.get("core_status", "") or "")
        _action = str(_a.get("action", "") or "")
        _why = str(_a.get("why", "") or "")
        _zone_s = str(_zone_text or "")

        _report = str(_fj.get("report", "") or "")
        if _report and _report not in ["通過", "已通過"]:
            _reasons.append("財報未完全通過")
        _cash = str(_fj.get("cashflow", "") or "")
        if _cash in ["不配合", "偏弱"]:
            _reasons.append("現金流偏弱")
        _inv_ar = str(_fj.get("inv_ar", "") or "")
        if _inv_ar and _inv_ar not in ["正常", "資料不足"]:
            _reasons.append("存貨/應收需追蹤")

        _candidate = bool(_diag.get("core_candidate")) or ("候選" in _core_status) or (_core == "候選")
        if _core != "Yes" and not _candidate:
            _reasons.append("Core 未過")
        if _attack != "Yes":
            _reasons.append("Attack 未成立")
        if _focus != "Yes":
            _reasons.append("Focus 未成立")

        _rer = str(_rr.get("verdict", "") or _rr.get("rerating_verdict", "") or "")
        if _rer and "不成立" in _rer:
            _reasons.append("估值重評不成立")
        elif _rer and "部分" in _rer:
            _reasons.append("重評仍需驗證")

        if any(x in _zone_s for x in ["偏貴", "高溢價", "壓力", "跑太前", "過熱"]):
            _reasons.append("位置不舒服")

        # 去重並限制長度
        _uniq = []
        for _r in _reasons:
            if _r and _r not in _uniq:
                _uniq.append(_r)
        if not _uniq:
            if "條件不足" in _why:
                return "條件不足：財報、買點或籌碼尚未同時到位，先觀察。"
            return _why
        return "條件不足：" + "、".join(_uniq[:3]) + "，先觀察/等確認。"
    except Exception:
        return str((_a or {}).get("why", "條件不足，先觀察。"))

