def _v2732_rr_label_kind(_rr):
    """v273.2｜把風報比數字翻成人話，避免只顯示 0.42 這種使用者看不懂的模型數字。"""
    try:
        _v = float(_rr)
    except Exception:
        return "風報比資料不足", "neutral"
    if _v < 1.5:
        return f"風報比偏低 {_v:.2f}", "danger"
    if _v < 3.0:
        return f"風報比可觀察 {_v:.2f}", "warn"
    return f"風報比有利 {_v:.2f}", "good"


def _v2732_clean_badge(_label, _kind="neutral"):
    """v273.2｜清掉「通過｜不適用」等半成品語意，並補上更清楚的顏色。"""
    _s = str(_label or "").strip()
    if not _s:
        return "", _kind
    _s = _s.replace("通過｜不適用", "財報通過").replace("通過 | 不適用", "財報通過")
    _s = _s.replace("財報通過｜不適用", "財報通過").replace("財報通過 | 不適用", "財報通過")
    if _s in ["通過", "財報通過"]:
        return "財報通過", "good"
    if _s in ["不適用", "None", "none", "-", "—"]:
        return "", _kind
    if _s.startswith("風報比"):
        _m = re.search(r"([0-9]+(?:\.[0-9]+)?)", _s)
        if _m:
            return _v2732_rr_label_kind(float(_m.group(1)))
    return _s, _kind


def _vm_tag_html(_label, _kind="neutral"):
    _label, _kind = _v2732_clean_badge(_label, _kind)
    _label = str(_label or "").strip()
    if not _label:
        return ""
    _cls = "vm-tag"
    if _kind in ["good", "warn", "danger", "info", "neutral"]:
        _cls += f" vm-tag-{_kind}"
    return f'<span class="{_cls}">{_html.escape(_label)}</span>'

def _vm_tags_html(_items):
    _html_items = []
    for _item in (_items or []):
        if isinstance(_item, (list, tuple)):
            _html_items.append(_vm_tag_html(_item[0], _item[1] if len(_item) > 1 else "neutral"))
        else:
            _html_items.append(_vm_tag_html(_item))
    _html_items = [x for x in _html_items if x]
    return '<div class="vm-tag-row">' + ''.join(_html_items) + '</div>' if _html_items else ""

def _vm_kv_lines_html(_raw):
    _rows = []
    for _line in str(_raw or "").splitlines():
        _line = _line.strip()
        if not _line:
            continue
        if "：" in _line:
            _k, _v = _line.split("：", 1)
        elif ":" in _line:
            _k, _v = _line.split(":", 1)
        else:
            _k, _v = "", _line
        _k = _k.strip()
        _v = _v.strip()
        if _k:
            _rows.append(f'<div class="vm-kv-k">{_html.escape(_k)}</div><div class="vm-kv-v">{_html.escape(_v)}</div>')
        else:
            _rows.append(f'<div class="vm-kv-v" style="grid-column:1/-1">{_html.escape(_v)}</div>')
    return '<div class="vm-kv">' + ''.join(_rows) + '</div>' if _rows else '<div class="vm-val">資料不足</div>'


