# =========================================================
# v251｜Nick 買後導航核心模組（可供 app.py 或後續 API 直接呼叫）
# =========================================================
from typing import Any, Dict, List, Optional

def nick_v251_price(v: Any) -> Optional[float]:
    try:
        if v is None:
            return None
        x = float(v)
        if pd.isna(x) or x <= 0:
            return None
        return x
    except Exception:
        return None


def nick_v251_cluster_price_lines(candidates: List[Dict[str, Any]], cluster_pct: float = 0.01) -> List[Dict[str, Any]]:
    """Nick撐壓聚類：相近 1% 內合併，避免多條相近支撐/壓力打架。"""
    clean = []
    for c in candidates or []:
        px = nick_v251_price(c.get("price"))
        if px is None:
            continue
        cc = dict(c)
        cc["price"] = px
        clean.append(cc)
    if not clean:
        return []
    clean = sorted(clean, key=lambda x: x["price"], reverse=True)
    clusters: List[Dict[str, Any]] = []
    for c in clean:
        if not clusters:
            clusters.append({
                "max_p": c["price"], "min_p": c["price"],
                "sources": [str(c.get("source") or c.get("label") or "Nick撐壓")],
                "dates": [str(c.get("date") or "")],
                "total_vol": float(c.get("vol") or 0), "count": 1,
            })
            continue
        last = clusters[-1]
        base = last.get("max_p") or c["price"]
        if base and abs(base - c["price"]) / base <= cluster_pct:
            last["max_p"] = max(last["max_p"], c["price"])
            last["min_p"] = min(last["min_p"], c["price"])
            src = str(c.get("source") or c.get("label") or "Nick撐壓")
            if src and src not in last["sources"]:
                last["sources"].append(src)
            d = str(c.get("date") or "")
            if d and d not in last["dates"]:
                last["dates"].append(d)
            last["total_vol"] += float(c.get("vol") or 0)
            last["count"] += 1
        else:
            clusters.append({
                "max_p": c["price"], "min_p": c["price"],
                "sources": [str(c.get("source") or c.get("label") or "Nick撐壓")],
                "dates": [str(c.get("date") or "")],
                "total_vol": float(c.get("vol") or 0), "count": 1,
            })
    return clusters


def nick_v251_build_raw_nick_lines(df_kline: pd.DataFrame) -> List[Dict[str, Any]]:
    """120 日 Nick 撐壓：量 > 5日均量 且 量 > 前日量；紅K低點、綠K高點、十字K收盤。"""
    raw: List[Dict[str, Any]] = []
    if df_kline is None or df_kline.empty:
        return raw
    df = df_kline.copy().tail(121)
    rename = {}
    for c in df.columns:
        lc = str(c).lower()
        if lc in ["open", "high", "low", "close", "volume", "date"]:
            rename[c] = lc
    df = df.rename(columns=rename)
    if len(df) > 1:
        df = df.iloc[:-1].copy()
    df = df.tail(120).copy()
    if not set(["open", "high", "low", "close", "volume"]).issubset(set(df.columns)):
        return raw
    df["vol5"] = pd.to_numeric(df["volume"], errors="coerce").rolling(5).mean()
    df["prev_vol"] = pd.to_numeric(df["volume"], errors="coerce").shift(1)
    for _, r in df.iterrows():
        vol = nick_v251_price(r.get("volume")) or 0
        vol5 = nick_v251_price(r.get("vol5")) or 0
        pv = nick_v251_price(r.get("prev_vol")) or 0
        if not (vol > vol5 > 0 and vol > pv > 0):
            continue
        o, h, l, c = [nick_v251_price(r.get(k)) for k in ["open", "high", "low", "close"]]
        if None in [o, h, l, c]:
            continue
        try:
            dstr = pd.to_datetime(r.get("date")).strftime("%m/%d") if "date" in df.columns else ""
        except Exception:
            dstr = ""
        body_pct = abs(o - c) / c if c else 0
        if body_pct < 0.003:
            raw.append({"price": c, "source": "Nick大量十字K", "date": dstr, "vol": vol})
        elif c > o:
            raw.append({"price": l, "source": "Nick大量紅K低點", "date": dstr, "vol": vol})
        else:
            raw.append({"price": h, "source": "Nick大量綠K高點", "date": dstr, "vol": vol})
    return raw


def nick_v251_profit_stage(current_price: Any, buy_price: Any, max_price_since_buy: Any, take_profit_30_done: Any = 0, take_profit_50_done: Any = 0) -> Dict[str, Any]:
    """獲利階段狀態機：未拉開、小獲利、30%、50%、高獲利回吐。"""
    cur = nick_v251_price(current_price)
    bp = nick_v251_price(buy_price)
    mp = nick_v251_price(max_price_since_buy) or bp or cur
    if cur is not None:
        mp = max(mp or cur, cur)
    if not bp or cur is None:
        return {"stage": "無持股", "current_return": None, "max_return": None, "new_max_price_since_buy": mp or 0, "new_tp30_done": 0, "new_tp50_done": 0, "action": ""}
    cr = (cur - bp) / bp * 100
    mr = ((mp or cur) - bp) / bp * 100
    tp30 = bool(float(take_profit_30_done or 0))
    tp50 = bool(float(take_profit_50_done or 0))
    action = ""
    if mr >= 30 and (mr - cr) >= 10:
        stage = "高獲利回吐"
        action = "曾經獲利超過 30%，目前從高點回吐超過 10%，先提高防守。"
    elif cr >= 50:
        stage = "狂暴奔跑"
        if not tp50:
            action = "獲利已達 +50%，建議再分批停利一部分。"
            tp50 = True
    elif cr >= 30:
        stage = "獲利達標"
        if not tp30:
            action = "獲利已達 +30%，建議先分批賣出 1/3。"
            tp30 = True
    elif cr >= 5:
        stage = "小獲利"
    elif cr >= -5:
        stage = "未拉開"
    else:
        stage = "虧損防守"
    return {"stage": stage, "current_return": cr, "max_return": mr, "new_max_price_since_buy": mp, "new_tp30_done": int(tp30), "new_tp50_done": int(tp50), "action": action}


# =========================================================
# v267｜法醫報告 v6.7 解析接口：估值結構參數＋交易快照
# =========================================================
def _nick_v267_label(txt, labels):
    """支援 v6.7 欄位：快照新倉主區（snapshot_main_buy_zone）：3600～3900。"""
    txt = str(txt or "")
    labels = labels if isinstance(labels, (list, tuple, set)) else [labels]
    lines = [str(x).strip() for x in txt.splitlines()]
    found = ""
    for i, line in enumerate(lines):
        if not line:
            continue
        for label in labels:
            label = str(label or "").strip()
            if not label:
                continue
            patterns = [
                rf"^\s*{re.escape(label)}\s*[：:]\s*(.*?)\s*$",
                rf"^\s*{re.escape(label)}\s*（[^）]*）\s*[：:]\s*(.*?)\s*$",
                rf"^\s*{re.escape(label)}\s*\([^)]*\)\s*[：:]\s*(.*?)\s*$",
            ]
            for pat in patterns:
                m = re.match(pat, line)
                if m:
                    found = (m.group(1) or "").strip()
            if re.match(rf"^\s*{re.escape(label)}\s*[：:]?\s*$", line) and i + 1 < len(lines):
                nxt = lines[i + 1].strip()
                if nxt:
                    found = nxt
    return found.strip()


def _nick_v267_clean_range(x):
    try:
        return _nick_clean_ai_core_range_text(x)
    except Exception:
        s = str(x or "").strip()
        s = s.replace("－", "～").replace("-", "～").replace("~", "～").replace("—", "～")
        return s.replace("元", "").replace("倍", "").strip(" ：:,，;；")


_nick_v267_base_trade_plan_parser = nick_v247_extract_trade_plan_from_text

def nick_v247_extract_trade_plan_from_text(raw_text):
    """v267｜支援 v6.7 APP 作戰參數複製框的交易快照欄位。"""
    raw_text = str(raw_text or "")
    tp = _nick_v267_base_trade_plan_parser(raw_text) or {}
    v67 = {
        "new": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照新倉主區", "snapshot_main_buy_zone"])),
        "shallow": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照小倉試單區", "snapshot_small_position_zone"])),
        "right_confirm": _nick_v267_label(raw_text, ["快照右側確認條件", "snapshot_right_confirm"]),
        "upper_pressure": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線 / 關鍵壓力", "快照短線/關鍵壓力", "snapshot_pressure"])),
        "wrong": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線追錯失效", "snapshot_short_invalid"])),
        "stop": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照波段防守參考", "snapshot_swing_defense", "快照洗盤忍受底線"])),
        "short": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線目標", "snapshot_short_target"])),
        "wave": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照波段目標", "snapshot_swing_target"])),
        "snapshot_date": _nick_v267_label(raw_text, ["報告日期", "forensic_snapshot_date"]),
        "snapshot_note": "法醫交易快照僅供報告當下參考，APP 每日須用 Nick 撐壓 / 均線 / 籌碼重新校正。" if "APP 作戰參數" in raw_text or "法醫交易快照" in raw_text else "",
    }
    for k, v in v67.items():
        if str(v or "").strip():
            tp[k] = v
    return {k: v for k, v in tp.items() if v not in [None, "", "資料不足"]}


_nick_v267_base_ai_core_text_parser = _nick_parse_ai_core_text_to_case_fields

def _nick_parse_ai_core_text_to_case_fields(raw_text, default_subfamily="", default_source="manual_text"):
    """v267｜在既有 AI Core parser 上，新增 v6.7 雙軌輸出解析。

    - 估值結構參數：EPS / PE / 支撐區 / 重評區 / 失敗區，給 App 長期引用。
    - 法醫交易快照：買點 / 壓力 / 失效 / 目標，只當報告當下參考。
    """
    raw_text = str(raw_text or "")
    parsed = _nick_v267_base_ai_core_text_parser(raw_text, default_subfamily=default_subfamily, default_source=default_source)
    if not raw_text.strip():
        return parsed

    is_v67 = ("APP 作戰參數" in raw_text) or ("估值結構參數" in raw_text) or ("法醫交易快照" in raw_text) or ("forensic_snapshot_date" in raw_text)

    core_v = _nick_v267_label(raw_text, ["AI Core", "Core"])
    core_plain = _nick_v267_label(raw_text, ["Core"])
    core_type = _nick_v267_label(raw_text, ["Core 類型", "forensic_core_type"])
    rer = _nick_v267_label(raw_text, ["估值重評狀態", "forensic_rerating_status", "估值重評"])

    eps = parsed.get("eps_assumption") or {}
    eps2 = {
        "bear": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["EPS 保守"])),
        "base": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["EPS 中性", "EPS 假設"])),
        "bull": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["EPS 樂觀"])),
        "failure": eps.get("failure") or "",
    }
    for k, v in eps2.items():
        if v:
            eps[k] = v

    pe = parsed.get("pe_assumption") or {}
    pe2 = {
        "bear": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["PE 保守"])),
        "base": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["PE 中性"])),
        "bull": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["PE 樂觀"])),
        "rerating": _nick_clean_ai_core_number_text(_nick_v267_label(raw_text, ["PE 重評上緣"])),
        "failure": pe.get("failure") or "",
    }
    for k, v in pe2.items():
        if v:
            pe[k] = v

    zones = parsed.get("valuation_zones") or {}
    support = _nick_v267_clean_range(_nick_v267_label(raw_text, ["基本面支撐區", "forensic_value_floor"]))
    rer_zone = _nick_v267_clean_range(_nick_v267_label(raw_text, ["重評合理區", "forensic_re_rating_zone"]))
    fail_zone = _nick_v267_clean_range(_nick_v267_label(raw_text, ["驗證失敗下修區", "forensic_fail_zone"]))
    if support:
        zones["fundamental_support"] = support
    if rer_zone:
        zones["rerating_fair_zone"] = rer_zone
    if fail_zone:
        zones["failure_downside_zone"] = fail_zone

    trade_plan = parsed.get("trade_plan") or {}
    trade_plan.update(nick_v247_extract_trade_plan_from_text(raw_text) or {})

    validation_text = _nick_v267_label(raw_text, ["驗證條件", "買後續抱條件", "重新法醫條件"])
    limit_text = _nick_v267_label(raw_text, ["限制條件", "最大反方證據", "買錯條件"])
    limitations = list(parsed.get("limitations") or [])
    limitations += _nick_split_condition_text(limit_text)
    limitations = list(dict.fromkeys([x for x in limitations if str(x or "").strip()]))

    structural = {
        "forensic_snapshot_date": _nick_v267_label(raw_text, ["報告日期", "forensic_snapshot_date"]),
        "data_basis_date": _nick_v267_label(raw_text, ["資料基準日"]),
        "ai_core": core_v,
        "core": core_plain,
        "core_type": core_type,
        "rerating_status": rer,
        "report_verdict": _nick_v267_label(raw_text, ["財報裁決"]),
        "report_verdict_type": _nick_v267_label(raw_text, ["財報部分通過類型"]),
        "treasury_level": _nick_v267_label(raw_text, ["財報金庫"]),
        "financial_quality": _nick_v267_label(raw_text, ["法醫財務品質"]),
        "attack": _nick_v267_label(raw_text, ["Attack"]),
        "attack_type": _nick_v267_label(raw_text, ["Attack 類型"]),
        "observe_small_lot": _nick_v267_label(raw_text, ["是否觀察型小倉"]),
        "focus": _nick_v267_label(raw_text, ["Focus"]),
        "final_action": _nick_v267_label(raw_text, ["最終動作"]),
    }
    snapshot = {
        "main_buy_zone": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照新倉主區", "snapshot_main_buy_zone"])),
        "small_position_zone": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照小倉試單區", "snapshot_small_position_zone"])),
        "right_confirm": _nick_v267_label(raw_text, ["快照右側確認條件", "snapshot_right_confirm"]),
        "pressure": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線 / 關鍵壓力", "快照短線/關鍵壓力", "snapshot_pressure"])),
        "short_invalid": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線追錯失效", "snapshot_short_invalid"])),
        "swing_defense": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照波段防守參考", "snapshot_swing_defense", "快照洗盤忍受底線"])),
        "short_target": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照短線目標", "snapshot_short_target"])),
        "swing_target": _nick_v267_clean_range(_nick_v267_label(raw_text, ["快照波段目標", "snapshot_swing_target"])),
    }

    parsed.update({
        "core_verdict": core_v or parsed.get("core_verdict") or "",
        "rerating_verdict": rer or parsed.get("rerating_verdict") or "",
        "core_type": core_type or parsed.get("core_type") or default_subfamily or "",
        "subfamily": core_type or parsed.get("subfamily") or default_subfamily or "",
        "eps_assumption": eps,
        "pe_assumption": pe,
        "valuation_zones": zones,
        "trade_plan": trade_plan,
        "validation_rules": {
            **(parsed.get("validation_rules") or {"valid_days": 90}),
            "conditions_text": validation_text or (parsed.get("validation_rules") or {}).get("conditions_text", ""),
            "conditions": _nick_split_condition_text(validation_text) or (parsed.get("validation_rules") or {}).get("conditions", []),
        },
        "limitations": limitations,
    })
    raw_imp = parsed.get("raw_import") or {}
    if isinstance(raw_imp, dict):
        raw_imp.update({
            "parsed_by": "nick_ai_core_text_parser_v267_forensic_interface",
            "forensic_v67_detected": bool(is_v67),
            "forensic_structural_params": {k: v for k, v in structural.items() if str(v or "").strip()},
            "forensic_trade_snapshot": {k: v for k, v in snapshot.items() if str(v or "").strip()},
            "snapshot_lifecycle_note": "EPS/PE/估值區是地形，可較長期引用；交易快照是天氣，APP 每日須重新校正。" if is_v67 else "",
        })
        parsed["raw_import"] = raw_imp
    return parsed


# =========================================================
# v274.2｜崩盤換股雷達啟動閘門（純邏輯版）
# 原則：只判斷是否啟動資金重分配雷達，不覆蓋 Core / Attack / Focus。
# =========================================================
def build_v274_2_crash_rotation_activation_gate(
    market_drawdown_30d=None,
    market_drawdown_60d=None,
    panic_volume=False,
    margin_call_wave=False,
    core_sector_breakdown_ratio=None,
    manual_force=False,
):
    """3+1 啟動閘門：觀察 / 雷達 / 戰鬥 / 日常。

    market_drawdown_* 可以輸入百分比數字（10 代表 -10%）或小數（0.10）。
    core_sector_breakdown_ratio 可以輸入百分比（70 代表 70%）或小數（0.70）。
    """
    def _pct(x):
        try:
            if x is None or x == "":
                return 0.0
            v = float(str(x).replace("%", "").replace("％", "").replace(",", "").strip())
            if abs(v) <= 1.5:
                v *= 100.0
            return abs(v)
        except Exception:
            return 0.0

    dd30 = _pct(market_drawdown_30d)
    dd60 = _pct(market_drawdown_60d)
    sector_ratio = _pct(core_sector_breakdown_ratio)
    signals = []

    if dd30 >= 10.0 or dd60 >= 15.0:
        signals.append("大盤/櫃買/成長股池已達系統性修正幅度")
    elif dd30 >= 8.0 or dd60 >= 12.0:
        signals.append("市場已進入資金重分配觀察區")

    if bool(panic_volume) or bool(margin_call_wave):
        signals.append("恐慌放量或融資斷頭訊號出現")

    if sector_ratio >= 60.0:
        signals.append("核心成長族群同步跌破中期均線比例偏高")
    elif sector_ratio >= 50.0:
        signals.append("核心成長族群轉弱比例升高，先建立候選清單")

    signal_count = len(signals)
    if bool(manual_force) or signal_count >= 3:
        mode = "戰鬥模式"
        enabled = True
        action = "崩盤換股戰鬥模式啟動：開始尋找產業沒壞、基本面沒壞、未來三年成長強、股價被系統性錯殺的高彈性標的。"
    elif signal_count >= 2:
        mode = "雷達模式"
        enabled = True
        action = "資金重分配雷達啟動：開始比較原持股與候選股的三年成長性與估值支撐。"
    elif signal_count >= 1:
        mode = "觀察模式"
        enabled = False
        action = "進入資金重分配觀察模式：先建立候選清單，暫不建議急著換股。"
    else:
        mode = "日常模式"
        enabled = False
        action = "市場尚未達系統性錯殺條件，維持原本 Core / Attack / Focus 與買後導航。"

    return {
        "swap_mode_enabled": enabled,
        "activation_mode": mode,
        "activation_signals": signals,
        "activation_signal_count": signal_count,
        "manual_force": bool(manual_force),
        "market_drawdown_30d_pct": dd30,
        "market_drawdown_60d_pct": dd60,
        "core_sector_breakdown_ratio_pct": sector_ratio,
        "panic_volume": bool(panic_volume),
        "margin_call_wave": bool(margin_call_wave),
        "action_text": action,
        "rule_note": "本模組為崩盤換股輔助雷達，不覆蓋 Core / Attack / Focus。",
    }
